-- Generated by pipeline/lore/compile_lua.py --lang svSE - do not edit by hand.
-- Sources: data/i18n/svSE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism visar samlare vägen till lärare som kan lära dem att tillverka Incense Candle för lägerplatser i vildmarken. Med skördade växtingredienser kan örteologer erbjuda väldoftande tröst som stärker magiker och helare under långa resor.",h="Camping 101: Herbalism visar samlare vägen till lärare som kan lära dem att tillverka Incense Candle för...",kw={"läger","camping","camping 101: herbalism","helare","herbalism","örter","incense candle","magiker"},ang={["class:Mage"]="Magiker som förlorar sin koncentration i strid uppskattar lägerrökelseljus som lugnar sinnet och stödjer återhämtningen av magisk kraft.",["class:Priest"]="Rökelseljus som tänds vid en lägerplats höjer modet och fyller på de mentala krafterna hos heliga helare mellan striderna.",["profession:Herbalism"]="När man samlar växter i vildmarken får man de råa, aromatiska örter som behövs för att tillverka rökelse till lägret. Därmed är örteologens växtinsamling praktisk för överlevnad såväl som för alkemi."},sec={{t="Vilda växter längs vägen",b="För resenärer som tillbringar dagarna med att vandra genom vildmarken är det mycket mer än tidsfördriv att samla rötter och kronblad. Camping 101: Herbalism introducerar skickliga samlare till praktiska färdigheter i fält och för dem samman med mentorer som vet hur vilda, aromatiska växter blir till Incense Candle för lägret. I stället för att bara sälja färska stjälkar eller brygga drycker kan en samlare använda skördade växter för att hjälpa en grupp längs vägen."},{t="Lugn för sinnet",b="Långa resor genom fientligt territorium tär på helare och magiker, vars mentala krafter och moral är avgörande i strid. Ett Incense Candle som brinner vid en aktiv lägerplats fyller luften med lugnande, uppfriskande dofter som håller modet uppe. Magianvändare och helare uppskattar särskilt den aromatiska förstärkningen, som hjälper följeslagarna att återfå klarhet och styrka innan de ger sig ut i faran igen."}},faq={{q="Vad är Camping 101: Herbalism?",a="Camping 101: Herbalism är ett uppdrag för äventyrare som har övat på att samla örter. Det introducerar örteologen till specialiserade hantverkare som kan lära ut hur man tillverkar rökelse för läger i vildmarken.",al={"vad är camping 101: herbalism","uppdraget camping 101: herbalism","uppdrag om herbalism och camping"}},{q="Vad används Incense Candle till?",a="Incense Candle är ett lägertillbehör som tillverkas av växtmaterial. När ett sådant brinner på en lägerplats stärker det vilande äventyrares moral och mod, särskilt genom att ge helare och magiker en välgörande förstärkning.",al={"vad gör incense candle","effekt av incense candle vid läger","varför tillverka incense candle"}},{q="Vem lär ut hur man tillverkar Incense Candle?",a="Tränaren beror på var du börjar: Reyna Stonebranch i Ironforge, Malorne Bladeleaf i Dolanaar, Herbalist Pomeroy i Elwynn Forest, Jandi i Orgrimmar, Faruza i Brill, Komin Winterhoof i Thunder Bluff eller Syriel Nightrain i Valanaar.",al={"vem lär ut incense candle","tränare för incense candle","var lär man sig incense candle"}},{q="Varför är Incense Candle särskilt användbart för magianvändare?",a="Att kanalisera magi och vårda sår i strid dränerar både fysisk energi och mental koncentration. Gott mod är viktigt för att hålla magiker redo för strid, och den lugnande röken från ett rökelseljus hjälper dem att återhämta sig.",al={"varför behöver magiker rökelse","incense candle för helare","incense candle för magianvändare"}},{q="Måste man vara örteolog för att ta det här uppdraget?",a="Den här instruktionen riktar sig direkt till dem som kan samla växter och örter, eftersom metoderna går ut på att identifiera och använda vilda, aromatiska växter.",al={"kan vem som helst lära sig incense candle","behöver jag herbalism för camping 101: herbalism","krav på herbalism för lägerljus"}},{q="Hur hänger Herbalism ihop med camping?",a="Skördade växter från vildmarken kan användas till mer än brygder och salvor. De har även praktiska och väldoftande användningsområden vid lägret, som att tillverka rökelse som piggar upp trötta följeslagare.",al={"är herbalism bara till för brygder","användning av örter vid läger","föremål för lägret från herbalism"}}},fp="22,218,23.229.0,17.318.0,31.132.0,35.196.0,42.247.0,58.186.0,50.121.0,36.139.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking vägleder blivande läderarbetare till fördjupad undervisning i att tillverka tåliga vildmarksskydd. Hos Indari Sunseam i Shen'dar Village får hantverkare lära sig sy skyddande tält som ger välbehövlig vila under långa expeditioner i vildmarken.",h="Camping 101: Leatherworking vägleder blivande läderarbetare till fördjupad undervisning i att tillverka...",kw={"campingtält","lägereld","camping","matlagning","indari sunseam","läderarbete","shen'dar village","tält","vildmark"},ang={["profession:Cooking"]="Ett tält räcker inte för att skapa ett fungerande läger. Resenärer måste också kunna grunderna i att göra upp lägereld, något de vanligtvis lär sig av matlagningsinstruktörer."},sec={{t="Skydd på vägen",b="För läderarbetare på resande fot är det viktigt att kunna förvandla hudar och pälsar till tålig utrustning för vildmarken. När hantverket är inlärt hänvisas hantverkare till Indari Sunseam i Shen'dar Village för att lära sig tillverka ett ordentligt campingtält. Sådana skydd håller äventyrare torra under ihållande skyfall och svala under stekande sol, så att de får ordentligt med vila under långa resor."},{t="Lägerplatser i vildmarken",b="Att slå upp ett tält kräver respekt för gränserna för offentliga platser, eftersom stadsbor ogillar primitiva lägerplatser som skräpar ner gatorna. Läger måste slås upp ute i vildmarken. Dessutom är ett stadigt skydd bara halva lösningen: inget läger är komplett utan en värmande lägereld. Därför bör äventyrare besöka en lokal kock och lära sig grunderna i att göra upp eld innan de ger sig ut i vildmarken."}},faq={{q="Vem lär läderarbetare att tillverka ett tält?",a="Indari Sunseam bor i Shen'dar Village och lär skickliga läderarbetare att tillverka egna campingtält.",al={"vem lär ut tält i läderarbete","instruktör för campingtält","var finns indari sunseam"}},{q="Vad är syftet med att tillverka ett tält?",a="Ett välgjort tält skyddar resenärer mot hårt väder, som regn och brännande hetta, så att äventyrare får den vila de behöver för att hålla sig alerta längs vägen.",al={"vad gör ett tält","tältets syfte","tältets fördelar"}},{q="Var kan ett campingtält slås upp?",a="Tält får inte slås upp i stadskärnor där lokalbefolkningen motsätter sig dem. Resenärer måste ta sig ut i den öppna vildmarken innan de slår läger.",al={"kan jag slå upp tält i en stad","var kan jag använda tält","lägerregler"}},{q="Vad mer behövs för att slå upp ett ordentligt läger?",a="Ett komplett läger behöver en sprakande lägereld utöver skyddet. Äventyrare uppmuntras att söka upp en matlagningsinstruktör för att lära sig göra upp en enkel eld.",al={"behöver jag en eld","krav för läger","vad mer behövs för läger"}},{q="När lär Indari Sunseam dig tältmönstret?",a="Du måste öva på läderarbete och visa tillräcklig skicklighet i yrket innan Indari Sunseam lär dig att tillverka ett campingföremål.",al={"när kan jag lära mig tält","tältkrav","krav på tält i läderarbete"}},{q="Vad är Shen'dar Village?",a="Shen'dar Village är bosättningen där Indari Sunseam bor och arbetar, och där resenärer kan få undervisning i att tillverka campingutrustning.",al={"var ligger shen'dar village","shen'dar village plats","indari sunseams ort"}}},fp="27,216,19.306.0,20.227.0,47.88.0,39.114.0,36.88.0,43.91.0,52.115.0,25.103.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning lär äventyrare att förvandla insamlade hudar till en praktisk Camp Chair för läger i vildmarken. Under ledning av Mendalass Tattermend i Shen'dar Village lär sig garvare att förena sitt hantverk med överlevnad i vildmarken och avkoppling vid lägerelden.",h="Camping 101: Skinning lär äventyrare att förvandla insamlade hudar till en praktisk Camp Chair för läger i...",kw={"camp chair","lägereld","camping 101","hudar","mendalass tattermend","shen'dar village","garvning","vildmark"},ang={["profession:Cooking"]="Matlagning och överlevnad i vildmarken går hand i hand. Som Mendalass påpekar kräver en ordentlig lägerplats en enkel lägereld, en färdighet som traditionellt lärs ut av matlagningsinstruktörer."},sec={{t="Bekvämlighet i vildmarken",b="Att ta hudar från fallna bestar är en viktig överlevnadsfärdighet i Azeroth, men nyttan sträcker sig långt bortom enkel rustningstillverkning. Genom Camping 101: Skinning lär sig samlare att använda sitt yrke för att överleva i vildmarken genom att tillverka en bärbar Camp Chair. En stunds vila på en bekväm stol ute i vildmarken hjälper utmattade äventyrare att återfå sina krafter och hålla sig i bästa stridsform inför nästa strid."},{t="Undervisningen i Shen'dar Village",b="För att bemästra mönstret skickas äventyrare till Shen'dar Village för att träffa Mendalass Tattermend när de visat att de behärskar en flåkniv. Mendalass lär resenärer att sätta ihop hållbara sittplatser av insamlade hudar. Men för att slå läger krävs mer än möbler: bosättningar tolererar inte tillfälliga läger innanför stadsgränsen, och en lägerplats är inte komplett utan en sprakande lägereld, en färdighet man traditionellt lär sig av lokala matlagningsinstruktörer."}},faq={{q="Vad handlar Camping 101: Skinning om?",a="Camping 101: Skinning leder skickliga garvare till Mendalass Tattermend i Shen'dar Village. Genom utbildningen lär sig äventyrare att göra om insamlade hudar till en praktisk Camp Chair för vila och återhämtning i fält.",al={"vad är det här för uppdrag","syftet med camping 101","varför göra uppdraget"}},{q="Vem är Mendalass Tattermend?",a="Mendalass Tattermend är en garvningsinstruktör i Shen'dar Village. Han lär skickliga garvare att sy ihop insamlade hudar till bekväma sittplatser för läger i vildmarken.",al={"vem är mendalass","vem lär ut camp chair","mendalass tattermend"}},{q="Var finns Mendalass Tattermend?",a="Mendalass Tattermend finns i Shen'dar Village, dit äventyrare måste resa för att visa sin skicklighet och lära sig konsten att tillverka lägerutrustning.",al={"var finns mendalass","var ligger shendar village","var lämnar jag in det här"}},{q="Vilket föremål lär det här uppdraget dig att tillverka?",a="Garvare lär sig mönstret för att tillverka en Camp Chair av hudar från fallna bestar, så att de får en bekväm plats att vila på ute i vildmarken.",al={"vad tillverkar garvare","recept på camp chair","vilket föremål får jag"}},{q="Kan man slå läger inne i en stad?",a="Stadsbor ser ogärna att man slår läger mitt i en bosättning. Läger och Camp Chairs är till för vildmarken, långt från stadskärnorna.",al={"kan jag slå läger i staden","var kan jag slå läger","var använder jag camp chair"}},{q="Vad mer behövs för ett ordentligt läger?",a="Varje ordentlig lägerplats behöver en sprakande lägereld för att vara komplett. Äventyrare som ännu inte kan göra upp eld rekommenderas att fråga en matlagningsinstruktör om grunderna.",al={"vad mer behöver jag till lägret","lägereld behövs","krav för läger"}}},fp="21,162,20.195.0,33.244.0,36.158.0,28.147.0,40.109.0,44.118.0,34.89.0,44.101.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="Camping 101: Tailoring lär skräddare konsten att skapa specialutrustning för vildmarksläger. Genom att visa sin skicklighet för Taleen Shimmerthread i Shen'dar Village lär sig skräddare att sy en inspirerande Faction Banner som höjer modet och håller lägrets moral uppe.",h="Camping 101: Tailoring lär skräddare konsten att skapa specialutrustning för vildmarksläger.",kw={"lägerfana","lägerliv","camping 101: tailoring","faction banner","shen'dar village","skrädderi","taleen shimmerthread","yrkesfärdighet"},ang={["profession:Tailoring"]="Skräddare lär sig att tillverka inspirerande Faction Banners som stärker lägrets moral och ger allierade energi ute i fält."},sec={{t="Vävarens bidrag till lägret",b="Camping 101: Tailoring hjälper tygmakare att utveckla sitt hantverk bortom enkla kläder och väskor. I den otämjda vildmarken kräver överlevnad mer än varma kläder; en ordentlig lägerplats kan vara skillnaden mellan uthållighet och nederlag. Skräddare uppmuntras att söka avancerad undervisning för att förvandla tygbuntar till symboler för enighet och styrka."},{t="Undervisning i Shen'dar Village",b="Uppdraget leder blivande skräddare till Shen'dar Village, där Taleen Shimmerthread undervisar i lägerhantverk. De som har utvecklat tillräckliga färdigheter i skrädderi kan lära sig metoderna för att tillverka en Faction Banner. En sådan fana, omsorgsfullt sydd och stolt rest vid lägret, blir en inspirerande samlingspunkt som höjer moralen och håller allierade fulla av energi inför prövningarna som väntar."}},faq={{q="Vad är Camping 101: Tailoring?",a="Camping 101: Tailoring leder lovande skräddare till specialundervisning i fälthantverk. När du har visat tillräcklig skicklighet i skrädderi kan du lära dig att skapa en dekorativ och inspirerande Faction Banner för läger i vildmarken.",al={"vad är det här för uppdrag","uppdraget camping 101 tailoring","lägerfana i skrädderi"}},{q="Vem är Taleen Shimmerthread?",a="Taleen Shimmerthread är en skicklig skräddare i Shen'dar Village. Hon undervisar skickliga hantverkare i hur de väver lägerföremål med skrädderi, däribland fanor som höjer modet i lägret.",al={"taleen shimmerthread","vem lär ut att väva lägerfana","var finns taleen shimmerthread"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är bosättningen där Taleen Shimmerthread bor. Skräddare beger sig dit för att få särskild vägledning i hur de kan använda sitt tyghantverk till lägerutrustning.",al={"var ligger shen'dar village","shen'dar village plats"}},{q="Vilket lägerföremål kan skräddare lära sig att tillverka?",a="En Faction Banner är ett lägerföremål som skräddare tillverkar. På slagfält och under hårda expeditioner är inspiration och moral livsviktiga, och en rest fana skänker en energigivande närvaro åt dem som vilar i lägret.",al={"faction banner för läger","vad tillverkar skräddare till lägret","lägerföremål i skrädderi"}},{q="Vilka krav finns för att lära sig tillverka lägerfanan?",a="Du måste visa att du behärskar skrädderi som yrkesfärdighet innan Taleen Shimmerthread i Shen'dar Village lär dig mönstret för att väva en Faction Banner till ditt läger.",al={"hur lär man sig faction banner","krav för faction banner i skrädderi"}},{q="Varför är fraktionsfanor värdefulla i lägret?",a="Moral och inspiration är avgörande under varje fälttåg. Skräddare syr fraktionsfanor för att visa sin tillhörighet och skapa en energigivande samlingspunkt som hjälper äventyrare att hålla ut under strapatsrika resor.",al={"varför tillverka en faction banner","lägerfana och moral"}}},fp="22,136,33.268.0,31.258.0,31.176.0,28.160.0,26.138.0,45.114.0,54.133.0,41.149.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call är ett uppdrag i Shadowglen där dryaden Tarindrella vill ta reda på varför de lokala Gnarlpine-furbolgerna plötsligt vänt sig mot sina långvariga Night Elf-allierade. Genom att samla in ristade totem från deras övergivna läger hjälper äventyrare till att avslöja den oroande andliga fördärv som sprider sig genom Teldrassil.",h="Nature's Call är ett uppdrag i Shadowglen där dryaden Tarindrella vill ta reda på varför de lokala...",kw={"furbolg","gnarlpine","grell","grellkin","nature's call","mardrömmar","shadowglen","tarindrella","teldrassil","totem"},ang={["class:Druid"]="Druider är lyhörda för naturens balans och den andliga fördärv som påverkar Kalimdors varelser. Därför är den mardrömsdrivna fördärven av furbolgernas totem ett alarmerande tecken.",["faction:Alliance"]="Att skydda Teldrassils grenar är avgörande för att värna det unga Night Elf-riket och se till att deras nya Alliance-allierade förblir förankrade på Kalimdor.",["race:NightElf"]="Gnarlpine hade länge varit Night Elf-folkets följeslagare. Därför är deras fall i fientlighet och vansinne en djupt personlig tragedi för Teldrassils försvarare."},sec={{t="Undersöker gläntan",b="Nature's Call är ett undersökningsuppdrag i Shadowglen som ges av dryaden Tarindrella. Hon vägrar tro att Gnarlpine-furbolgerna skulle överge århundraden av vänskap med Night Elf utan anledning. Därför ber hon resenärer att leta igenom furbolgernas hastigt övergivna läger längs gläntans västra gräns och hämta hela, graverade totem."},{t="Skuggan och mardrömmen",b="När de återfunna totemen dechiffreras blottas en tragisk färd in i vansinnet. Gnarlpine plågades av återkommande mardrömmar om en annalkande skugga som var ämnad att utplåna dem. Med tiden förvandlades ren skräck till blint raseri och förvrängde deras sinnen, tills de såg sina långvariga alviska grannar som själva skuggan de fruktade. Tarindrella hoppas att fynden ska kasta ljus över den djupare sjukdom som sprider sig genom Teldrassil."}},faq={{q="Vem ger uppdraget Nature's Call?",a="Tarindrella är en dryad som vakar över Shadowglen i Teldrassil. Hon oroar sig över de lokala Gnarlpine-furbolgernas plötsliga fientlighet och skickar äventyrare att hämta reliker från deras övergivna läger för att undersöka orsaken till deras vansinne.",al={"vem ger nature's call","vem är tarindrella","tarindrella plats"}},{q="Varför blev Gnarlpine-furbolgerna fientliga?",a="Gravyrer på totem som hämtats från Gnarlpine visar att furbolgerna började lida av hemska mardrömmar om en hotande skugga som skulle förgöra dem. Den krypande skräcken förvandlades till okontrollerbar paranoia och vrede, och fick dem att se sina forna Night Elf-allierade som fiender.",al={"varför attackerade gnarlpine","varför är gnarlpine vansinniga","vad hände med gnarlpine-furbolgerna"}},{q="Var finns Gnarlpine-totemen?",a="De mindre totemen finns i Gnarlpine-furbolgernas övergivna läger längs gläntans västra kant, men grell och grellkin som letar efter mat bland ruinerna har spritt ut några i området runt omkring.",al={"var finns gnarlpine-totemen","hitta gnarlpine-totem","gnarlpine-lägrets plats"}},{q="Varför kan spelare inte samla in de större totemen i lägren?",a="Tarindrella avråder uttryckligen från att försöka hämta de större totemen i lägren. Som dryad har hon ingen aning om vad hon skulle göra med sådana otympliga sniderier och föredrar i stället mindre, bärbara totem med gravyrer.",al={"varför ignoreras stora totem","kan jag plundra stora totem","stort gnarlpine-totem"}},{q="Vilka är Gnarlpine-furbolgerna?",a="Gnarlpine är en furbolgklan från Teldrassil som levde sida vid sida med Night Elf som fredliga allierade. Att de nyligen blivit aggressiva fiender är en onaturlig förändring som orsakats av krypande mardrömmar, inte av urgammalt hat.",al={"vilka är gnarlpine","gnarlpine-lore","är gnarlpine onda"}},{q="Vad är den stora skuggan som nämns på totemen?",a="Gravyrerna berättar om en osedd Great Shadow som hemsöker furbolgernas drömmar. Även om ursprunget till detta mörka inflytande är okänt hoppas Tarindrella att deras öde ska hjälpa till att nysta upp den större fördärv som plågar Teldrassil.",al={"vilken skugga gnarlpine","vad är skuggan i teldrassil","mardrömmar i teldrassil"}}},fp="13,165,22.302.0,28.327.1,34.198.0,44.192.0,39.181.0,57.209.0,30.176.0,49.198.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="The Goddess Provides är ett introduktionsuppdrag för kaldorei som handlar om att uppmärksamma Elunes gudomliga gåvor. Bland Teldrassils grenar, efter den långa vaksamhetens slut, lär det unga Night Elf att ta till sig månens vägledning och de skuggor som döljer dem, gåvor från Moder Måne.",h="The Goddess Provides är ett introduktionsuppdrag för kaldorei som handlar om att uppmärksamma Elunes...",kw={"elune","goddess provides","hyjal","kaldorei","lång vaksamhet","moder måne","skuggmantel","teldrassil"},ang={["class:Priest"]="Kaldoreis prästerskap är hängivet Moder Måne och kanaliserar Elunes nåd direkt som vägledande strålglans och gudomligt beskydd.",["faction:Alliance"]="Efter slaget vid Mount Hyjal gjorde Night Elf slut på sin långa isolering och anslöt sig till Alliansen. De ställer sina heliga månkrafter till förfogande för ett gemensamt försvar.",["race:NightElf"]="Som stjärnornas barn ärver kaldorei Elunes direkta välsignelser. De använder månljuset för att visa dolda vägar och förmågan att gömma sig för att smälta in i skuggorna."},sec={{t="Vaksamheten är över",b="I årtusenden efter Sundringen höll kaldorei sin ensamma långa vaksamhet. De vakade över Kalimdor och skyddade Mount Hyjals heliga toppar. Den tredje krigets förödelse och det avgörande försvaret av världsträdet gjorde slut på denna urgamla isolering. Nu har Night Elf flyttat till Teldrassils skyddande grenar och möter en främmande värld. De tar plats på Azeroths större scen genom att knyta band till avlägsna allierade på andra sidan havet."},{t="Moder Månens välsignelser",b="Trots förändrade allianser och nya hem vilar grunden för kaldoreis identitet fortfarande på dyrkan av Elune, Moder Måne. Night Elf får från tidig ålder lära sig att åkalla hennes två aspekter: strålglans som vägleder stridsslag och klargör syftet, och skugga som döljer ens närvaro för fiendens blick. Dessa nedärvda gåvor är både en andlig gemenskap och en praktisk förberedelse inför farorna bortom det stora trädet."}},faq={{q="Vad är The Goddess Provides?",a="The Goddess Provides är en introduktionsrit för unga Night Elf bland Teldrassils grenar. Den lär kaldorei att känna igen och visa de medfödda välsignelser som mångudinnan Elune skänkt dem.",al={"vad är the goddess provides","uppdraget the goddess provides"}},{q="Vem är gudinnan som nämns i uppdraget?",a="Gudinnan är Elune, som kaldorei också vördar som Moder Måne. Hon är den centrala gudomen i Night Elfs kultur och andliga liv. Man tror att hon skänker sina barn månens välsignelser i form av beskydd, klarhet och förmågan att smälta in i skuggorna.",al={"vem är gudinnan","vem är moder måne","night elf-gudinna"}},{q="Vilka gåvor ger Elune kaldorei?",a="Elune skänker en nåd som kan lysa upp en krigares slag och hjälpa dem att träffa rätt, liksom förmågan att smälta in i omgivande skuggor, precis som månen döljer solen under en förmörkelse.",al={"vilka gåvor ger elune","elunes rasegenskaper","elunes krafter"}},{q="Vad var den långa vaksamheten?",a="Den långa vaksamheten var den tusentals år långa isolering som Night Elf upprätthöll för att vaka över Kalimdor. Den tog slut efter det avgörande försvaret av Mount Hyjal mot den brinnande legionen, vilket fick kaldorei att till sist öppna sina gränser.",al={"vad var den långa vaksamheten","varför tog den långa vaksamheten slut"}},{q="Varför har Night Elf anslutit sig till Alliansen?",a="Efter att försvaret av Mount Hyjal gjort slut på deras ensamma isolering valde kaldorei att knyta band till dödliga folkslag på andra sidan havet och ansluta sig till den stora alliansen för ömsesidig överlevnad och gemenskap.",al={"varför gick night elf med i alliansen","kaldorei och alliansen"}},{q="Var äger den här undervisningen rum?",a="Teldrassil är det väldiga stora trädet utanför Kalimdors norra kust. Dess höga, skyddade grenar är Night Elfs nya hem och fristad efter den tredje kriget.",al={"var ligger teldrassil","vad är teldrassil"}}},fp="20,177,17.451.0,24.405.0,29.113.0,44.188.0,46.104.0,24.206.0,45.197.0,39.151.0"}
P.entries["quest:97985"] = {n="Thundering Hearts",s="I Thousand Needles söker forskaren Stormhearts väldiga hjärta för arbetet med en styggelse.",h="I Thousand Needles söker forskaren Stormhearts väldiga hjärta för arbetet med en styggelse.",kw={"styggelse","skapande","hjärta","stormheart","thousand needles","åsködla","thundering hearts"},sec={{t="Ett stort hjärta",b="En forskare som studerar hur styggelser skapas tror att arbetet kräver ett väldigt hjärta. Stormheart, en åsködla som sägs patrullera längs kanjonens kant i Thousand Needles, verkar stor nog. Men Stormheart är inte foglig."},{t="Hjärtat",b="Stormhearts hjärta avger fortfarande elektriska pulser. Forskaren säger att det verkar ha den storlek som anges i anteckningarna och ska fogas till styggelsen."}},faq={{q="Vem vill ha Stormhearts hjärta?",a="En forskare som studerar hur styggelser skapas vill ha Stormhearts hjärta till en styggelse.",al={"vem behöver hjärtat","styggelseforskare","vem skickade mig"}},{q="Var finns Stormheart?",a="Stormheart patrullerar längs kanjonens kant i Thousand Needles.",al={"stormhearts plats","var finns åsködlan","stormheart var"}},{q="Vad är Stormheart?",a="Stormheart är en åsködla av imponerande storlek.",al={"stormheart varelse","stor ödla","åsködla"}},{q="Varför behövs ett hjärta?",a="Enligt forskarens anteckningar krävs ett väldigt hjärta för att skapa en styggelse.",al={"varför hjärta","styggelsens hjärta","vad ska hjärtat användas till"}},{q="Vad vet forskaren om hjärtat?",a="Forskaren säger att hjärtat fortfarande avger elektriska pulser och verkar ha den storlek som anges i anteckningarna.",al={"detaljer om hjärtat","elektriskt hjärta","vad är speciellt med det"}}},fp="17,98,13.218.0,9.163.1,31.89.0,20.61.0,19.50.0,22.75.0,46.115.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces är ett uppdrag där Arbal ger äventyrare från Grove of the Ancients i uppgift att minska antalet Stormscale-naga som samlas i ruinerna i nordost.",h="Swelling Forces är ett uppdrag där Arbal ger äventyrare från Grove of the Ancients i uppgift att minska...",kw={"arbal","grove of the ancients","highborne","myrmidon","naga","trollkvinna","stormscale","swelling forces","twilight's hammer"},ang={["faction:Alliance"]="Alliansens styrkor som försvarar de heliga skogarna kring Darkshore och Grove of the Ancients måste möta en samordnad front mellan nagorna och Twilight's Hammer.",["race:NightElf"]="Nagorna som strövar omkring i ruinerna var en gång nattalvernas Highborne-fränder. Att se dem återvända för att vanhelga och plundra de forntida skogarna tillsammans med mörka kultister är ett bittert svek."},sec={{t="Ormar i den sjunkna staden",b="Från Grove of the Ancients ser Arbal med stor oro mot ruinerna i nordost. Förbannade Highborne, förvandlade till de ormlika nagorna i Stormscale-stammen, har tagit över resterna av sin en gång magnifika civilisation. De sjunkna stenarna vilar inte i minnet, utan ekar nu av en framryckande härs slingrande marsch. Arbal skickar försvarare till ruinerna för att hugga ned deras växande antal innan de sprider sig ut i den större skogen."},{t="En ohelig allians",b="Stormscale-nagornas närvaro handlar om mer än enkel territoriell aggression. Arbal avslöjar att dessa förvridna forna Highborne hjälper den nihilistiska kulten Twilight's Hammer. Att vanhelga och plundra skogarna som en gång gav dem skydd, särskilt i tjänst hos lömska skuggmästare, är ett oförlåtligt brott. Det är brådskande att minska deras antal för att hindra kulten och dess ormlika allierade från att stärka sitt grepp om landet."}},faq={{q="Vem ger uppdraget Swelling Forces?",a="Arbal ger uppdraget Swelling Forces och skickar äventyrare från Grove of the Ancients för att konfrontera de fientliga naga-styrkor som samlas i ruinerna i nordost.",al={"vem ger swelling forces","arbal uppdragsgivare","var finns arbal"}},{q="Varför är nagorna måltavlor i det här uppdraget?",a="Stormscale-nagorna har tagit över ruinerna i närheten och hotar skogsmarkerna runt omkring. Än mer oroande är att de verkar hjälpa kulten Twilight's Hammer och därmed våldföra sig på markerna de en gång kallade sitt hem.",al={"varför döda nagor","nagor i ruinerna","stormscale-hotet"}},{q="Vad har nagorna för koppling till ruinerna?",a="Som Arbal berättar var nagorna en gång Highborne-alver i det forntida Kalimdor, men drabbades av en fruktansvärd förbannelse. De bodde förr i dessa storslagna städer, men har återvänt som förvridna ormar som söker erövring och förödelse.",al={"vilka är stormscale-nagorna","nagornas ursprung","förbannade highborne"}},{q="Vad har nagorna för koppling till Twilight's Hammer?",a="Uppdraget avslöjar att nagorna hjälper den skuggfulla kulten Twilight's Hammer. Deras exakta överenskommelse är fortfarande höljd i dunkel, men Arbal varnar för att alliansen bara kan föra med sig mer förödelse och elände till de forntida skogarna.",al={"twilight's hammer och nagor","varför samarbetar nagorna med kulten"}},{q="Var samlas Stormscale-styrkorna?",a="Ruinerna ligger nordost om Grove of the Ancients. Äventyrare skickas dit för att hejda den växande Stormscale-hären genom att jaga deras myrmidoner, trollkvinnor och krigare.",al={"var finns ruinerna","var hittar man stormscale"}},{q="Varför anser Arbal att nagornas handlingar är oförlåtliga?",a="För Arbal är det fullständigt oförlåtligt att plundra sitt eget forntida hemland på uppdrag av en mörk härskare. All den ädelhet Highborne en gång ägde har suddats ut av deras förfall till grymhet och mörka allianser.",al={"varför hatar arbal nagorna","oförlåtligt enligt arbal"}}},fp="15,191,27.366.0,18.316.1,36.132.0,46.182.0,54.180.0,55.141.0,38.133.0,56.181.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="Journey to Sentinel Hill leder Alliansens äventyrare till Westfalls oroliga jordbruksmarker, där de ska rapportera till utposten Sentinel Hill. Efter månader av obesvarade vädjanden till Stormwind om kungliga förstärkningar är de frustrerade lokala befälhavarna redo att genast sätta alla villiga resenärer i arbete.",h="Journey to Sentinel Hill leder Alliansens äventyrare till Westfalls oroliga jordbruksmarker, där de ska...",kw={"journey to sentinel hill","folkets milisstyrka","sentinel hill","spinkig alv","stormwind","westfall"},ang={["faction:Alliance"]="Westfall är ett alliansområde i desperat behov av stöd, men Stormwind har lämnat de lokala befälhavarna att vädja om förstärkningar och förlita sig på de frivilliga som anländer.",["race:NightElf"]="Gränsbefälhavaren vid Sentinel Hill kanske muttrar över att ha fått en ”spinkig alv” i stället för vältränat infanteri från Stormwind, men Sentinel Hill behöver all hjälp det kan få."},sec={{t="Ankomst till gränslandet",b="Journey to Sentinel Hill markerar en äventyrares ankomst till den hårt prövade regionen Westfall. Utposten Sentinel Hill är den främsta försvarsbastionen för de omgivande jordbruksmarkerna, men dess garnison har ständigt för få soldater och förbigås av det kungliga hovet. När resenärer anländer för att erbjuda hjälp slösar den lokala befälhavaren ingen tid på att fråga om deras härkomst, utan vill genast sätta alla villiga händer i arbete."},{t="Vädjanden till Stormwind",b="I månader har ledningen vid Sentinel Hill vädjat till Stormwind om militära förstärkningar för att skydda regionen mot annalkande hot. Rikets försummelse har tvingat de lokala befälhavarna att ta emot all hjälp som dyker upp, även om det innebär att hälsa en nyanländ äventyrare med en torr kommentar om att de väntade sig en armé men fick en spinkig alv i stället. I Westfall har tiggare inte råd att vara kräsna."}},faq={{q="Vad är Journey to Sentinel Hill?",a="Journey to Sentinel Hill är ett uppdrag för Alliansen som leder äventyrare till gränsområdet Westfall. Det introducerar nykomlingar för de lokala försvararna vid Sentinel Hill, som har vädjat om hjälp från Stormwind utan att få tillräckliga officiella förstärkningar.",al={"vad är journey to sentinel hill","uppdraget journey to sentinel hill","uppdraget sentinel hill"}},{q="Varför ber Sentinel Hill om hjälp?",a="Den militära ledningen vid Sentinel Hill har i månader bett Stormwind om förstärkningar för att hantera problemen som plågar Westfall. I stället för reguljära trupper måste den lokala ledningen förlita sig på de äventyrare som råkar dyka upp.",al={"vem ber stormwind om hjälp","sentinel hills garnison","varför sentinel hill behöver hjälp"}},{q="Varför nämner uppdragstexten en spinkig alv?",a="När du har slutfört resan säger befälhavaren att de har bett Stormwind om hjälp i månader, bara för att få en spinkig alv skickad till sig. Befälhavaren muttrar att tiggare inte kan vara kräsna och bestämmer sig snabbt för att genast sätta den nyanlända äventyraren i arbete.",al={"citat om spinkig alv","varför spinkig alv","sentinel hills kommentar om alven"}},{q="Varför har Stormwind inte skickat ordentliga förstärkningar?",a="Stormwinds kungliga regering är för närvarande upptagen och pressad, vilket gör att avlägsna områden som Westfall till stor del försummas. Sentinel Hill har vädjat upprepade gånger om hjälp under flera månader, men något officiellt kungligt stöd har inte kommit. De lokala befälhavarna måste därför förlita sig på frivilliga.",al={"varför hjälper stormwind inte westfall","stormwind försummar westfall","stormwinds hjälp till westfall"}},{q="Vad är Sentinel Hill?",a="Sentinel Hill är Folkets milisstyrkas centrala militärutpost och bastion i Westfall. Den utgör den främsta försvarslinjen mot laglösheten, Defias-banditerna och gnollerna som härjar bland regionens jordbruksmarker.",al={"var ligger sentinel hill","vad är sentinel hill","sentinel hills läge"}},{q="Vad händer när man kommer till Sentinel Hill?",a="När du har rapporterat in vid Sentinel Hill sätter de lokala försvararna genast dig i arbete. Äventyrare får i uppgift att hjälpa till att hantera de många hoten över Westfalls slätter och jordbruksmarker.",al={"vad man gör i westfall","nästa uppdrag i westfall","vad händer efter ankomsten till westfall"}}},fp="24,224,23.270.0,18.284.0,33.163.0,37.169.0,45.167.0,48.129.0,22.155.0,42.151.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Journey to the Crossroads leder nyanlända resenärer från det elementära planet till The Barrens karga savann. Äventyrare får i uppdrag att rapportera till Thork vid The Crossroads och hjälpa Hordens styrkor att kämpa mot den hårda gränsmarken. Det ger en nödvändig introduktion till de dödliga faror som väntar Horden i Kalimdor.",h="Journey to the Crossroads leder nyanlända resenärer från det elementära planet till The Barrens karga savann.",kw={"barrens","crossroads","elementära planet","horden","journey to the crossroads","the barrens","thork"},ang={["faction:Horde"]="Den här resan leder nyanlända mästare till att ta till vapen för Horden och sättsätter dem på prov i Kalimdors karga gränsland.",["race:Skyborne"]="Efter ankomsten till Azeroth från det elementära planet uppmanas resenärerna att inte underskatta dödliga konflikter och att bevisa sitt värde i Hordens tjänst."},sec={{t="En kallelse till gränslandet",b="Resenärer som anländer till Azeroth efter en färd från det elementära planet möts av en bister verklighet: dödliga konflikter kan verka små i jämförelse, men farorna som hotar Horden är högst verkliga. Tjänstgöring vid fronten ger en viktig prövning för den som vill bli mäktig och samtidigt hjälpa riket."},{t="Kalimdors vägskäl",b="För att påbörja sin tjänstgöring skickas äventyrare sydväst, till The Barrens vidsträckta, solstekta slätter. Där ligger The Crossroads, en viktig knutpunkt och utpost för Horden, vars stolta försvarare ständigt pressas av farorna runtomkring. Genom att rapportera direkt till Thork blir nykomlingarna en del av bosättningens försvar."}},faq={{q="Vem är Thork?",a="Thork är en framstående företrädare för Horden, stationerad vid The Crossroads i The Barrens. Han leder det lokala försvaret och skickar äventyrare för att bistå mot de många hot som riktas mot bosättningen och de omgivande områdena.",al={"vem är thork","ledare vid crossroads","var är thork"}},{q="Vad är The Crossroads?",a="The Crossroads är en central utpost för Horden och ett handelscentrum där flera stora leder möts i The Barrens. Den omges av fientligt djurliv, centaurstammar och quilboar-rövare, så försvararna behöver ständigt hjälp med att hålla viktiga försörjningsleder säkra.",al={"vad är crossroads","crossroads i barrens","varför bege sig till crossroads"}},{q="Var ligger The Barrens?",a="The Barrens är en vidsträckt, torr savann i centrala Kalimdor, sydväst om Durotar. Området utgör en viktig länk mellan Hordens territorier på kontinenten.",al={"var ligger barrens","barrens läge"}},{q="Varför nämner uppdraget det elementära planet?",a="Uppdraget nämner att resenären nyligen har anlänt från det elementära planet. Även om konflikter i andra världar kan verka storslagna är farorna som hotar de dödligas rike och Horden omedelbara och allvarliga.",al={"ankomst från det elementära planet","varför det elementära planet","resa från det elementära planet"}},{q="Vad är syftet med Journey to the Crossroads?",a="Uppdraget leder nykomlingar till att rapportera direkt till Thork vid The Crossroads. Där blir de en del av Hordens insatser vid fronten och får möjlighet att växa sig mäktiga genom hedervärd tjänstgöring.",al={"syftet med crossroads-uppdraget","varför skickas man till crossroads"}},{q="Vilka faror möter invånarna vid The Crossroads?",a="The Barrens utsätts ständigt för angrepp från inhemska rovdjur, kringströvande centaurer, quilboar-krigshorder och intrång från Alliansen. Varje utpost blir därför en omstridd bastion som behöver dugliga försvarare.",al={"vilka faror finns i barrens","hot i barrens"}}},fp="25,173,22.236.0,26.230.0,13.182.0,23.225.0,30.131.0,47.173.0,49.147.0,52.182.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel är en alliansisk efterlysning som utfärdats av Auberdines byråd i Darkshore. Efterlysningen kräver att Jai'vhanel, en vansinnig svart uggla känd som ”Swordfeather”, dödas. Hon har börjat överfalla resenärer på vägen nära Auberdine. Äventyrare måste jaga varelsen nära ruinerna av Ameth'Aran och ta med bevis på hennes död till Sentinel Glynda Nal'Shea.",h="WANTED: Jai'vhanel är en alliansisk efterlysning som utfärdats av Auberdines byråd i Darkshore.",kw={"ameth'aran","auberdine","svart uggla","darkshore","glynda nal'shea","jai'vhanel","swordfeather","wanted: jai'vhanel"},ang={["class:Druid"]="Nattalvernas druider håller noga uppsikt över Darkshores djurliv. Därför är den plötsliga vansinnigheten och aggressiviteten hos en ädel fågel som Jai'vhanel en oroande ekologisk störning.",["class:Hunter"]="Denna våldsamma, kolsvarta rovfågel kallas Swordfeather. Hon stryker omkring aggressivt nära bergen i Darkshore, där hennes jaktvanor har blivit oförutsägbart dödliga.",["faction:Alliance"]="Auberdines byråd förlitar sig på äventyrare från Alliansen och nattalvernas väktare för att hålla Darkshores viktiga kustvägar säkra från vansinniga rovdjur."},sec={{t="Ett hot på vägen",b="En anslagen efterlysning från Auberdines byråd varnar resenärer längs Darkshores kustvägar för ett farligt hot. En välkänd uggla i trakten vid namn Jai'vhanel, med smeknamnet ”Swordfeather”, har plötsligt blivit vansinnig. I stället för att hålla sig till den täta vildmarken har hon börjat överfalla resenärer och kurirer nära Auberdine. En vanlig skogspredator har därmed blivit en allvarlig fara för bosättningen."},{t="Rådets belöning",b="För att göra vägarna säkra har rådet utlyst en belöning för Jai'vhanels huvud. Jägare ska spåra den svartfjädrade rovfågeln till hennes jaktmarker norr om ruinerna av Ameth'Aran, vid bergsfoten. För att bekräfta dödsfallet och få sin belöning måste jägarna ta med en av hennes karaktäristiska kolsvarta fjädrar till Sentinel Glynda Nal'Shea i Auberdine."}},faq={{q="Vem är Jai'vhanel?",a="Jai'vhanel, även känd under namnet ”Swordfeather”, är en stor uggla med kolsvarta fjädrar. Hon är vanligtvis ett vilt djur från Darkshores skogar, men har blivit vansinnig och nu är hon aggressivt fientlig mot resenärer.",al={"vem är jai'vhanel","vad är jai'vhanel","vem är swordfeather"}},{q="Varför har Jai'vhanel en belöning utfäst på sig?",a="Auberdines byråd utfäste en formell belöning för Jai'vhanel eftersom hon har blivit vansinnig och börjat angripa resenärer på huvudvägen nära Auberdine. Hon utgör en allvarlig fara för den lokala trafiken.",al={"varför döda jai'vhanel","varför har jai'vhanel en belöning utfäst på sig","varför angrips ugglan"}},{q="Var finns Jai'vhanel?",a="Jai'vhanel sågs senast norr om de forntida ruinerna av Ameth'Aran i Darkshore, där hon strök omkring vid foten av de östra bergen.",al={"var finns jai'vhanel","jai'vhanels plats","var hittar man swordfeather"}},{q="Vem utfäste belöningen för Jai'vhanel?",a="Belöningen utfästes av Auberdines byråd, som ansvarar för den civila säkerheten och invånarnas välfärd i kustbosättningen och längs de omgivande vägarna.",al={"vem utfäste belöningen","vem vill se jai'vhanel död"}},{q="Vem hämtar ut belöningen för Jai'vhanel?",a="Prisjägare måste visa upp en av Jai'vhanels kolsvarta fjädrar som bevis på hennes död för Sentinel Glynda Nal'Shea, som finns i staden Auberdine.",al={"vem tar emot dödsbeviset","var lämnar man in jai'vhanels fjäder","glynda nal'sheas belöning"}},{q="Vilket bevis krävs för att få belöningen?",a="Den som vill få rådets belöning måste hämta och visa upp en av Jai'vhanels karaktäristiska kolsvarta fjädrar som bevis på att den vansinniga fågeln har dödats.",al={"vad är dödsbeviset för jai'vhanel","vilket föremål bevisar att jai'vhanel är död"}}},fp="18,212,20.238.0,20.265.0,18.151.0,36.156.0,30.104.0,36.134.0,39.103.0,41.61.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... är ett uppdrag om en djupt oroande upptäckt som förs till Thundris. När Thundris känner igen det omisskännliga tecknet på en uråldrig ondska ser han till att reliken genast skickas till Darnassus för vidare undersökning.",h="It's All Fun and Games Until...",kw={"uråldrig ondska","ande'thoras-ethil","darnassus","tecknet på en uråldrig ondska","night elf","thundris"},ang={["faction:Alliance"]="Alliansens äventyrare som för oroande fynd till nattalvernas myndigheter hjälper till att se till att farliga reliker undersöks och tas om hand av lärda från Darnassus.",["race:NightElf"]="Undersökningen berör nattalvernas vaksamhet mot uråldrig korruption och leder till att Darnassus genast ingriper."},sec={{t="En oroande rapport",b="En oroande upptäckt får en äventyrare att söka upp Thundris för råd i en olustig fråga. När Thundris hör äventyrarens rapport och undersöker det som lagts fram sjunker han in i tyst begrundan och känner igen mörka tecken som inte kan avfärdas lättvindigt."},{t="Den uråldriga ondskans tecken",b="När Thundris undersöker saken närmare urskiljer han det omisskännliga tecknet på en uråldrig ondska som klamrar sig fast vid upptäckten. Han inser att faran sträcker sig långt bortom en lokal incident och beslutar att genast skicka reliken till Darnassus, där huvudstadens lärda och präster får ta hand om den för grundlig undersökning och inneslutning."}},faq={{q="Vilka är inblandade i att slutföra uppdraget?",a="Uppdraget lämnas in till och avslutas hos Thundris. Han lyssnar på den bekymrade äventyraren och undersöker föremålet eller bevismaterialet som visas upp innan han förbereder det för transport.",al={"vem lämnar in it's all fun and games until","thundris uppdrag","vem lämnar in its all fun and games until"}},{q="Varför skickas föremålet till Darnassus?",a="Thundris upptäcker att artefakten eller fyndet bär tecknet på en uråldrig ondska. Han säger att han genast ska se till att det förs till Darnassus för vidare undersökning, och säger inget mer än så.",al={"varför skicka till darnassus","undersökning i darnassus","uråldrig ondska darnassus"}},{q="Vad är den uråldriga ondska som Thundris nämner?",a="Thundris upptäcker att fyndet bär tecknet på en uråldrig ondska, men detaljer om dess exakta ursprung hålls hemliga i väntan på närmare undersökning i nattalvernas huvudstad.",al={"vad är den uråldriga ondskan","betydelsen av tecknet på uråldrig ondska"}},{q="Vad betyder ”Ande'thoras-ethil”?",a="”Ande'thoras-ethil” är en darnassisk fras som Thundris säger när han avslutar samtalet med dig, efter att ha sagt att fyndet ska föras till Darnassus.",al={"betydelsen av ande'thoras-ethil","ande'thoras-ethil nattalvsfras","darnassisk avskedsfras thundris"}},{q="Vad händer efter att uppdraget har slutförts?",a="Efter avslöjandet om den uråldriga korruptionen förbereder Thundris den oroande reliken för omedelbar transport till Darnassus, så att lärda i huvudstaden kan undersöka den.",al={"vad händer efter it's all fun and games until","nästa uppdrag efter it's all fun and games until","uppföljning till darnassus"}},{q="Vilken fraktion hanterar den här undersökningen?",a="Ärendet hanteras av Darnassus ledare och nattalver som Thundris, och kretsar kring hot som förs inför nattalvernas myndigheter.",al={"är it's all fun and games until endast för alliansen","vem kan göra it's all fun and games until"}}},fp="31,128,18.198.0,24.226.1,41.123.0,42.108.0,48.130.0,35.145.0,40.146.0,41.129.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="Crown of the Earth är ett uppdrag i Darnassus som börjar när Arch Druid Fandral Staghelm avbryter en misslyckad besvärjelse med en vattenflaska. Den frustrerade Arch Druid avfärdar dig och ger dig i uppgift att lämna den tömda behållaren till Priestess Lariia vid Temple of the Moon för att kastas bort. Men när prästinnan undersöker flaskan märker hon att det finns lite vatten kvar, vilket väcker tvivel om varför ritualen egentligen misslyckades.",h="Crown of the Earth är ett uppdrag i Darnassus som börjar när Arch Druid Fandral Staghelm avbryter en...",kw={"cenarion circle","crown of the earth","darnassus","drained vessel","elune","fandral staghelm","lariia","malfurion","temple of the moon"},ang={["class:Druid"]="Fandral tilltalar dig uttryckligen som en meddruid och bemöter ritualens misslyckande med kort tålamod innan han avfärdar dig.",["faction:Alliance"]="Uppdraget visar de lågmälda ledningsspänningarna i Darnassus, Alliansens främsta huvudstad på Kalimdor, medan Malfurion Stormrage är borta.",["race:NightElf"]="Ärendet visar den vardagliga pressen i Darnassus och ställer Fandral Staghelms lättretliga auktoritet mot The Sisterhood of Elunes tålmodiga hängivenhet i Temple of the Moon."},sec={{t="Fandrals frustration",b="I Darnassus bär Arch Druid Fandral Staghelm ansvaret för att vägleda nattalverna medan Malfurion Stormrage är borta. I sin jakt på svar försöker Fandral utföra en besvärjelse med heligt vatten i en flaska. När ritualen till synes inte ger något resultat tappar Arch Druid humöret. Övertygad om att vattnet är värdelöst avfärdar han dig med hårda ord och säger åt dig att ta den tömda behållaren söderut till Temple of the Moon, så att prästinnorna kan göra sig av med den."},{t="De sista dropparna",b="När du kommer fram till Temple of the Moon erbjuder Priestess Lariia ett mildare perspektiv och ber dig att ha överseende med Fandrals hårda sätt med tanke på den tunga börda han bär. När hon undersöker flaskan upptäcker hon dock något som Arch Druid missade i sin brådska: flera vattendroppar finns fortfarande kvar därinne. Resterna gör det mycket möjligt att Fandrals ritual inte misslyckades på grund av bristfällig magi, utan för att behållaren inte hade tömts ordentligt."}},faq={{q="Vem ger uppdraget Crown of the Earth?",a="Uppdraget ges av Arch Druid Fandral Staghelm i Darnassus. Fandral har för tillfället hand om Cenarion Circle medan Malfurion Stormrage är borta. Han ger dig uppgiften i ett plötsligt vredesutbrott efter att en besvärjelse med heligt vatten inte ger de svar han sökte.",al={"vem startar crown of the earth","crown of the earth uppdragsgivare","fandral uppdrag"}},{q="Var ska du lämna Drained Vessel?",a="Du lämnar Drained Vessel till Priestess Lariia vid Temple of the Moon i södra Darnassus. Fandral säger åt dig att överlämna den så att Elunes prästinnor kan göra sig av med den, eftersom han antar att den förbrukade behållaren inte längre är till någon nytta.",al={"var ska drained vessel lämnas","lämna in drained vessel","var finns lariia"}},{q="Varför är Fandral Staghelm så frustrerad?",a="Arch Druid Fandral Staghelm är hårt pressad av ansvaret att leda nattalverna och Cenarion Circle medan Malfurion Stormrage är borta. När hans magiska besvärjelse inte ger något resultat får hans irritation och stolthet honom att snäsa åt dig och snabbt avfärda dig i stället för att undersöka misslyckandet närmare.",al={"varför är fandral arg","fandrals attityd","varför är fandral otålig"}},{q="Varför misslyckades Fandrals besvärjelse?",a="Fandral Staghelm antar att vattnet saknade all användbar kraft, men Priestess Lariia upptäcker en viktig detalj när hon tar emot behållaren. Flera vattendroppar sitter fortfarande kvar på insidan, vilket tyder på att besvärjelsen kan ha misslyckats helt enkelt för att behållaren inte tömdes helt under ritualen.",al={"varför misslyckades besvärjelsen","fungerade fandrals ritual","misslyckad besvärjelse"}},{q="Var är Malfurion under det här uppdraget?",a="Malfurion Stormrage är för tillfället borta från Darnassus, så Arch Druid Fandral Staghelm får leda Cenarion Circle och vägleda nattalverna. Frånvaron lägger en tung börda på Fandral och bidrar till hans häftiga humör och otålighet när motgångar uppstår.",al={"var är malfurion","varför är malfurion borta","malfurions status"}},{q="Vem är Priestess Lariia?",a="Priestess Lariia är en nattalv som tjänar Elune och håller till i Temple of the Moon i Darnassus. Hon tar emot behållaren från dig, visar förståelse för Fandrals stora ansvar och upptäcker klokt nog att det fortfarande finns vatten kvar i den.",al={"vem är lariia","priestess lariias bakgrund","lariia temple of the moon"}}},fp="18,166,21.381.0,19.245.1,39.223.0,37.198.0,38.263.0,35.189.0,37.215.0,24.170.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="Crown of the Earth är ett uppdrag i Darnassus där äventyrare överlämnar renade Moonwell Remnants till översteprästinnan Tyrande Whisperwind. Mötet äger rum i Temple of the Moon och visar hur heliga Elunes vatten är och hur de politiska spänningarna mellan Tyrande och Arch Druid Fandral Staghelm växer.",h="Crown of the Earth är ett uppdrag i Darnassus där äventyrare överlämnar renade Moonwell Remnants till...",kw={"crown of the earth","darnassus","elune","fandral staghelm","malfurion","moonwell remnants","temple of the moon","tyrande whisperwind"},ang={["class:Druid"]="Tyrandes skarpa ord om Arch Druid Fandral Staghelm understryker den växande friktionen inom Cenarion Circle när Malfurion är borta.",["class:Priest"]="Att tjäna översteprästinnan Tyrande Whisperwind stärker förståelsen för den viktiga roll Elunes prästerskap spelar i att vägleda och styra nattalvernas samhälle.",["faction:Alliance"]="Ett möte med Darnassus ledare ger en inblick i de interna politiska spänningar som präglar en av Alliansens viktigaste huvudstäder.",["race:NightElf"]="Att överlämna heligt månbrunnsvatten visar tydligt kaldoreiernas delade ledarskap, klämt mellan Tyrandes prästerskap och Fandrals druider."},sec={{t="Möte med översteprästinnan",b="När de har samlat in de heliga Moonwell Remnants får äventyrarna i uppdrag att hälla det välsignade vattnet i ett ceremoniellt kärl och överlämna det direkt till Tyrande Whisperwind. Elunes översteprästinna håller hov högt uppe i Temple of the Moon i Darnassus, vakar över staden och skänker sin gudinnas ljus åt alla som kommer dit. Att anförtro henne sådant heligt vatten ses som en ära och en handling av hängivenhet till Elune."},{t="Spänningar i ledarskapet",b="När Tyrande tar emot resterna uttrycker hon djup tacksamhet för att det välsignade vattnet har räddats, men tankarna vänder sig snart till de politiska spänningar som håller Darnassus i sitt grepp. I Malfurion Stormrages frånvaro har Arch Druid Fandral Staghelm tagit kommandot över druidernas angelägenheter, men Tyrande gör det fullständigt klart att ansvaret för att styra kaldorei-folket enbart vilar på henne. Hon uppmanar till respekt för Staghelms ämbete, men samtalet blottlägger den skarpa friktionen mellan The Sisterhood of Elune och Cenarion Circle."}},faq={{q="Vad är Crown of the Earth?",a="Crown of the Earth är ett uppdrag i Darnassus där en äventyrare bär ett ceremoniellt kärl med Moonwell Remnants till översteprästinnan Tyrande Whisperwind i Temple of the Moon. Det markerar ett ögonblick av direkt kontakt med nattalvernas högsta ledare.",al={"vad är crown of the earth","crown of the earth-uppdraget","uppdraget crown of the earth"}},{q="Vem är Tyrande Whisperwind?",a="Tyrande Whisperwind är Elunes översteprästinna och nattalvernas politiska ledare. Hon styr Darnassus från den övre nivån i Temple of the Moon och bär ansvaret för att vägleda sitt folk i oroliga tider.",al={"vem är tyrande whisperwind","var är tyrande","översteprästinnan tyrande"}},{q="Varför förs Moonwell Remnants till Tyrande?",a="Moonwell Remnants består av heligt vatten som välsignats av Elune. Eftersom vattnet är heligt hälls det i ett ceremoniellt kärl och förs till Tyrande, så att hon kan ta emot och skydda det å gudinnans vägnar.",al={"varför föra moonwell remnants till tyrande","vad är moonwell remnants","heligt vatten darnassus"}},{q="Vad är tvisten mellan Tyrande och Fandral Staghelm?",a="Medan Malfurion Stormrage är borta leder Arch Druid Fandral Staghelm druiderna, men Tyrande håller bestämt fast vid att ansvaret för att styra Darnassus och leda kaldorei-folket fortfarande enbart är hennes. Hon vägrar låta druidernas makt överskugga Elunes prästerskap.",al={"spänningar mellan tyrande och fandral","varför ogillar tyrande staghelm","fandral mot tyrande"}},{q="Var är Malfurion under det här uppdraget?",a="Malfurion Stormrage är för tillfället borta från Darnassus. Det lämnar ett tomrum i druidernas ledarskap som Arch Druid Fandral Staghelm har klivit in för att fylla, vilket ökar de politiska spänningarna med Tyrande.",al={"var är malfurion","vad hände med malfurion","malfurions frånvaro"}},{q="Var ligger Temple of the Moon?",a="Temple of the Moon ligger i hjärtat av Darnassus. Det är The Sisterhood of Elunes främsta helgedom, och Tyrande håller hov på den övre nivån, direkt ovanför helgedomens stora sal.",al={"temple of the moon plats","var ligger temple of the moon","var hittar man tyrande"}}},fp="18,247,32.385.0,22.423.1,27.198.0,27.228.0,49.181.0,57.244.0,37.193.0,32.185.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="Eyes of the Sentinels är ett uppdrag i Darnassus där spelare hjälper Sentinel Dalia Sunblade att placera ut magiska spaningsugglor vid viktiga poster i nattalvernas huvudstad. När oron växer i Teldrassil stärker övervakningen från luften stadens försvar och ger Sentinels tid att be till Elune.",h="Eyes of the Sentinels är ett uppdrag i Darnassus där spelare hjälper Sentinel Dalia Sunblade att placera ut...",kw={"cenarion hold","craftsman's terrace","dalia sunblade","darnassus","elune","eyes of the sentinels","feathermoon","sentinelugglor","teldrassil","temple of the moon"},ang={["class:Hunter"]="Spaningsugglorna speglar nattalvernas klassiska spaning, där tränade djur och himmelska fågelväktare blir en naturlig förlängning av en jägarinnas sinnen.",["class:Priest"]="Sentinels betonar att vapen inte ensamma kan skydda kaldorei. Regelbunden bön och Elunes andliga gåvor är avgörande för deras väktarskap.",["faction:Alliance"]="När Darnassus hålls säkert skyddas nattalvernas huvudstad och Alliansens främsta fäste i norra Kalimdor stärks.",["race:NightElf"]="Sentinels är nattalvernas traditionella stående armé och folkets väktare. De förenar stridskonst med Elunes gudomliga välsignelser och vaksamma blick."},sec={{t="Hängivenhet och försvar",b="I Temple of the Moons heliga fristad vakar Sentinel Dalia Sunblade över Darnassus. General Shandris Feathermoon har befallt att varje krigare ska förena stridskonst med andlig hängivenhet, och därför ordnar Dalia så att vaksamma sentinelugglor placeras ut på viktiga platser i staden. När Sentinel tar över hennes dagliga plikter får hon värdefulla stunder till bön och eftertanke inför mångudinnan, samtidigt som kaldorei-huvudstaden förblir väl bevakad."},{t="Vaka över Darnassus",b="Oro ligger i luften över Teldrassil, och Sentinels skärper därför sin vaksamhet. För att skydda sig mot infiltration och oroligheter placeras sentinelugglor vid viktiga knutpunkter: i djupen under Cenarion Hold i norr, vid den livliga banken på torget, på värdshuset i Craftsman's Terrace och vid stadens huvudportar. Med hjälp av stadsvakterna blir dessa bevingade väktare tysta beskyddare som vakar över alla som går på det stora trädets gator."}},faq={{q="Vad är Eyes of the Sentinels?",a="Eyes of the Sentinels är ett uppdrag i Darnassus där en äventyrare hjälper Sentinel Dalia Sunblade att placera ut sentinelugglor på viktiga platser i staden och hålla vakt mot hot som närmar sig.",al={"uppdraget eyes of the sentinels","vad är eyes of the sentinels","översikt över eyes of the sentinels"}},{q="Vem är Sentinel Dalia Sunblade?",a="Sentinel Dalia Sunblade är en kaldorei-väktare stationerad i Temple of the Moon i Darnassus. Hon övervakar stadens försvarsrutiner och ser till att vaksamma ugglor bevakar stadens viktigaste stråk.",al={"vem är dalia sunblade","dalia sunblades bakgrund","sentinel dalia sunblade"}},{q="Varför placeras sentinelugglor ut runt Darnassus?",a="Sentinelugglorna fungerar som vaksamma spanare från luften och gudomliga spejare som Elune har skänkt. De låter Sentinels övervaka viktiga samlingsplatser och trånga passager i Darnassus.",al={"varför placera ut sentinelugglor","vad gör sentinelugglor","sentinelugglornas syfte"}},{q="Var placeras sentinelugglorna?",a="Sentinelugglorna placeras vid ingången till djupen under Cenarion Hold i norr, vid Darnassus Bank mitt i staden, på värdshuset i Craftsman's Terrace och vid stadsportarna.",al={"platser för ugglorna","var placeras ugglorna","eyes of the sentinels platser"}},{q="Varför är Sentinels på högsta beredskap i Teldrassil?",a="Sentinel Dalia Sunblade säger att något känns fel i världsträdet Teldrassil. Därför ökar Sentinels övervakningen och håller ständig beredskap mot osedda faror.",al={"varför är sentinels oroliga","vad är fel med teldrassil","något känns fel i teldrassil"}},{q="Vilken roll har General Feathermoon i Sentinels dagliga plikter?",a="General Shandris Feathermoon leder Sentinels och ser till att hennes jägarinnor förenar sina militära plikter med daglig hängivenhet och bön till gudinnan Elune.",al={"general feathermoons roll","shandris feathermoon och sentinels","feathermoons böneregel"}}},fp="21,165,20.384.0,20.363.0,30.164.0,31.167.0,52.151.0,35.181.0,50.158.0,71.144.0"}
P.entries["quest:98069"] = {n="Stolen Freewind Supplies",s="I Freewind Post behöver Jandia få tillbaka förnödenheterna som harpyorna har stulit. Utposten har tillräckligt för tillfället, men utan en ny leverans tar förråden snart slut.",h="I Freewind Post behöver Jandia få tillbaka förnödenheterna som harpyorna har stulit.",kw={"karavan","grotta","klippa","freewind post","harpyor","jandia","stulna förnödenheter till freewind","förnödenheter"},sec={{t="Den försvunna leveransen",b="Harpyorna anföll den senaste karavanen på väg till Freewind Post. Jandia säger att utposten klarar sig för tillfället, men förråden räcker inte utan fler förnödenheter. Harpyornas tillhåll ligger väster om utposten, längs klippans fot och i en grotta högre upp."}},faq={{q="Vem behöver förnödenheterna?",a="Jandia i Freewind Post behöver få tillbaka de stulna förnödenheterna.",al={"vem bad om förnödenheter","jandia förnödenheter","freewind förnödenheter"}},{q="Vem tog karavanens förnödenheter?",a="Harpyor anföll den senaste karavanen som fraktade förnödenheter till Freewind Post.",al={"vem stal dem","harpyornas förnödenheter","vad stal harpyorna"}},{q="Var ligger harpyornas tillhåll?",a="Harpyornas tillhåll ligger väster om Freewind Post, längs klippans fot och i en grotta högre upp.",al={"var finns harpyorna","harpyornas grotta","harpyor västerut"}},{q="Varför behöver Jandia få tillbaka dem?",a="Freewind Post har tillräckligt med förnödenheter för tillfället, men utan en ny leverans tar förråden snart slut.",al={"varför hämta tillbaka förnödenheter","freewinds förråd tar slut","varför är förnödenheterna viktiga"}},{q="Vad ber Jandia dig att hämta tillbaka?",a="Jandia ber dig att hämta tillbaka åtta stulna förnödenheter till Freewind Post.",al={"hur många förnödenheter","stöldgods","vad ska tas med"}}},fp="24,147,20.239.0,23.60.0,32.69.0,24.87.0,31.95.0,36.67.0"}
P.entries["quest:98070"] = {n="Stop the Screeching",s="I Screeching Canyon överfaller harpyor karavaner med förnödenheter på väg till Freewind Post. Deras anfall kan hindra karavanerna från att färdas dit.",h="I Screeching Canyon överfaller harpyor karavaner med förnödenheter på väg till Freewind Post.",kw={"karavan","freewind post","harpya","roguefeather","screeching canyon","screeching harpy","stop the screeching","förnödenheter","windcaller"},sec={{t="Karavaner i fara",b="En leverantör fruktar att harpyornas anfall ska hindra karavaner från att färdas till Freewind Post. Du ombeds dräpa Screeching Harpies, Screeching Roguefeather Harpies och Screeching Windcallers. Tills dess är karavanerna som vågar färdas genom kanjonen fortfarande i fara."},{t="Besked till leverantörerna",b="När harpyorna har besegrats kommer leverantören att underrätta dem som förser Freewind Post med varor. Då kommer karavanerna att möta ett hot mindre på sina färder."}},faq={{q="Varför blir karavanerna anfallna?",a="Harpyor i Screeching Canyon överföll de senaste karavanerna med förnödenheter som färdades därigenom.",al={"harpyor anfaller karavaner","varför harpyor anfaller","karavanproblem"}},{q="Vad står på spel om anfallen fortsätter?",a="Leverantören fruktar att inga karavaner kommer att våga färdas till Freewind Post om anfallen fortsätter.",al={"varför skydda karavaner","freewind post förnödenheter","karavaner slutar färdas"}},{q="Vilka harpyor är inblandade?",a="Harpyorna är Screeching Harpies, Screeching Roguefeather Harpies och Screeching Windcallers.",al={"typer av harpyor","screeching harpies","roguefeather windcaller"}},{q="Var finns harpyorna?",a="Harpyorna lever i Screeching Canyon.",al={"harpyornas plats","screeching canyon harpyor","var ligger screeching canyon"}}},fp="19,137,16.250.0,17.163.1,36.89.0,40.89.0,27.96.0,22.38.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="En byteshandel har ordnats med bryggsläkten i Dun Garok, som saknar familjen Fallrooks vingårdar lika mycket som någon annan. En låda Fallrook Varietal färdas till deras fäste i sydöstra Hillsbrad Foothills, och en säck av deras Homebrew Hops kommer tillbaka.",h="En byteshandel har ordnats med bryggsläkten i Dun Garok, som saknar familjen Fallrooks vingårdar lika mycket...",kw={"bryggsläkt","dun garok","fallrook","fallrook varietal","hillsbrad","homebrew hops","humle","vin"},sec={{t="Smaken av det förflutna",b="De flesta av de bästa årgångarna av Fallrook-vin på flaska dracks upp för länge sedan, men lådor med Fallrook Varietal står fortfarande i källarna. Bryggsläkten i Dun Garok saknar också familjen Fallrooks vingårdar, och en byteshandel har ordnats med dem."},{t="Bytet vid Dun Garok",b="Lådan färdas sydost till Dun Garok, där den lämnas till bryggsläkten vid eldstaden där de samlas, nere vid foten av deras fäste. I utbyte tar du med dig en säck av deras Homebrew Hops tillbaka."}},faq={{q="Vad byts i den här byteshandeln?",a="En låda Fallrook Varietal från källarna går till bryggsläkten i Dun Garok i utbyte mot en säck av deras Homebrew Hops.",al={"vad ska jag leverera","föremål i bryggarens byte","fallrook-vin"}},{q="Var i Dun Garok ska vinet lämnas?",a="Du lämnar det till bryggsläkten vid eldstaden där de samlas, nere vid foten av deras fäste.",al={"var är eldstaden","leveransplats i dun garok","var ska vinet lämnas"}},{q="Var ligger Dun Garok?",a="Dun Garok ligger i sydöstra Hillsbrad Foothills.",al={"dun garoks läge","var ligger dun garok"}},{q="Vilka var familjen Fallrook?",a="Familjen Fallrook hade vingårdar som man saknar. De flesta av deras bästa årgångar på flaska dracks upp för länge sedan, men lådor med vinet finns kvar i källarna.",al={"familjen fallrook","fallrooks vingårdar"}}},fp="14,183,19.181.0,25.165.0,38.126.0,44.103.0,27.55.0,23.166.0"}
P.entries["quest:98072"] = {n="Crocs of the Sky",s="James frågar om du har fjällen och berömmer sedan din skicklighet. Han erbjuder dig arbete om du lämnar äventyrslivet bakom dig.",h="James frågar om du har fjällen och berömmer sedan din skicklighet.",kw={"äventyrande","crocs of the sky","james","fjäll","arbete"},sec={{t="James erbjudande",b="James kallar dig en naturbegåvning och välkomnar dig tillbaka om du tar en paus från äventyrandet. Han skämtar om att du kanske är äldre då."}},faq={{q="Vem frågar efter fjällen?",a="James frågar om du har fjällen.",al={"vem vill ha fjällen","fjäll till james"}},{q="Vad tycker James om mig?",a="James tycker att du är en naturbegåvning.",al={"gillar james mig","james åsikt"}},{q="Vad erbjuder James?",a="James erbjuder dig arbete om du tar en paus från äventyrandet.",al={"jobb hos james","erbjudande om arbete"}}},fp="16,111,13.131.0,31.39.0,28.38.0,22.59.0"}
P.entries["quest:98094"] = {n="Scout Support",s="Söder om Tarren Mill bär du nya order från High Executor Darthalia till Deathstalker Masoj. Forsaken går vidare med sin plan att ta kontroll över dessa marker.",h="Söder om Tarren Mill bär du nya order från High Executor Darthalia till Deathstalker Masoj.",kw={"deathstalker masoj","dun garok","forsaken","spioner vid fronten","high executor darthalia","nethander stead","stöd till spejare","tarren mill","uppdaterade order"},sec={{t="Order till Masoj",b="High Executor Darthalia anförtror dig ett meddelande till spionerna vid fronten. Hon ger dig uppdaterade order till Deathstalker Masoj, som väntar på en höjd norr om Nethander Stead och utanför Dun Garok. Forsakens plan att ta kontroll över dessa marker fortskrider, och Masoj väntar på din leverans."}},faq={{q="Vem gav mig orderna?",a="High Executor Darthalia gav dig uppdaterade order till Deathstalker Masoj.",al={"vem skickade mig","darthalias order","uppdragsgivare"}},{q="Vem är Deathstalker Masoj?",a="Deathstalker Masoj är en spion vid fronten som är stationerad utanför Dun Garok, norr om Nethander Stead.",al={"masoj vem","vem är masoj","masoj"}},{q="Var hittar jag Masoj?",a="Masoj väntar söder om Tarren Mill, på en höjd norr om Nethander Stead och utanför Dun Garok.",al={"masojs plats","var är masoj","söder om tarren mill"}},{q="Vad har jag med mig till Masoj?",a="Du har med dig uppdaterade order till Deathstalker Masoj.",al={"vad ska levereras","order till masoj","paketet"}},{q="Varför levererar jag order?",a="Din leverans stöder Forsakens plan att ta kontroll över dessa marker.",al={"varför masoj","vad är planen","forsakens plan"}}},fp="13,164,16.293.0,23.71.0,26.87.0,22.96.0,28.48.0,27.72.0"}
P.entries["quest:98095"] = {n="Valuable Vantages",s="Runt Hillsbrad Foothills behöver Deathstalker Masoj din hjälp för att återställa tre signalmarkeringar. Fladdermusryttare använder punkterna för att leda strategiska trupper till deras avlämningsplatser.",h="Runt Hillsbrad Foothills behöver Deathstalker Masoj din hjälp för att återställa tre signalmarkeringar.",kw={"apothecary vials","fladdermusryttare","deathstalker masoj","dun garok","dunholde keep","headland","hillsbrad foothills","signalfyrar","valuable vantages"},sec={{t="Tre höjder",b="Du bär Apothecary Vials till tre höga platser: kullarna intill Dun Garok, platån ovanför Dunholde Keep och Headland-åsen ovanför Hillsbrad. Ångorna från flaskorna lockar tillbaka fladdermöss till markeringarna. Då kan Masojs överkommando leda sina trupper genom de låga kullarna."},{t="Masojs order",b="Masoj ber dig att leta efter krossade, tomma flaskor och förnya markeringarna på alla tre platserna. Han säger att arbetet tjänar planer som drivs framåt under Deathstalkers baner."}},faq={{q="Vem ber mig att placera ut flaskorna?",a="Deathstalker Masoj ber dig att återställa signalmarkeringarna runt Hillsbrad Foothills.",al={"vem gav valuable vantages","masoj flaskor","vem är masoj"}},{q="Varför behövs signalmarkeringarna?",a="Fladdermusryttare använder signalpunkterna för att leda strategiska trupper till avlämningsplatser.",al={"varför fladdermöss behöver markeringar","fladdermussignaler","vad är signalfyrarna till för"}},{q="Var placerar jag flaskorna?",a="Placera flaskorna på kullarna intill Dun Garok, platån ovanför Dunholde Keep och Headland-åsen ovanför Hillsbrad.",al={"flaskornas platser","var finns höjderna","tre flaskplatser"}},{q="Vad gör ångorna från flaskorna?",a="Ångorna lockar tillbaka fladdermöss till de önskade avlämningsplatserna.",al={"vad gör flaskorna","fladdermusdoft","flaskornas syfte"}}},fp="17,169,11.261.0,14.164.0,36.86.0,35.80.0,27.119.0,27.57.0"}
P.entries["quest:981"] = {n="The Tower of Althalaxx",s="Det här uppdraget avslutar triumferande fälttåget mot Cult of the Dark Strand vid Tower of Althalaxx. Efter att ha utplånat kultens ledarskap i Darkshores olycksbådande ruiner för en äventyrare budskap söderut till Delgren the Purifier i Ashenvale. Det är en avgörande seger för Alliansen i kampen mot demonisk korruption vid de forntida nattalvergränserna.",h="Det här uppdraget avslutar triumferande fälttåget mot Cult of the Dark Strand vid Tower of Althalaxx.",kw={"althalaxx","ashenvale","balthule","kult","dark strand","darkshore","delgren","maestra's post"},ang={["class:Paladin"]="Att rapportera till Delgren the Purifier har särskild betydelse för paladiner, som delar hans heliga uppdrag att rena världen från demonisk korruption och onda kulter.",["faction:Alliance"]="När kulten utplånas skyddas landsvägen mellan Darkshore och Ashenvale, så att Alliansens spejare och resenärer kan färdas säkert från demoniska bakhåll.",["race:NightElf"]="För nattalverna innebär reningen av Tower of Althalaxx att en vidrig plåga försvinner från de forntida Highborne-ruinerna som ligger utspridda i deras heliga kustskogar."},sec={{t="Ett avvärjt hot",b="Tower of Althalaxx stod i veckor som ett varigt sår i norra Darkshore, ockuperat av den fanatiska Cult of the Dark Strand och dess skuggmästare. Genom ihärdig spårning, underrättelsearbete och våldsamma skärmytslingar monterades kultens verksamhet systematiskt ned. När dess trollkarlar dödats och de mörka ritualerna brutits har det omedelbara hotet från demonisk infiltration i Darkshore äntligen avvärjts."},{t="Rapportera till Maestra's Post",b="Efter kultledarens död skickar Balthule Shadowstrike segraren söderut till Maestra's Post bland Ashenvales trädkronor. Där väntar Delgren the Purifier, en hängiven krigare i det Heliga ljusets tjänst som ledde korståget mot Althalaxxs onda invånare. Nyheten om kultens fall ger områdets försvarare sinnesro och ger hjälten Delgrens bestående välsignelse och välförtjänta tacksamhet."}},faq={{q="Vad är målet med uppdraget?",a="Det här uppdraget är den sista inlämningen i den långa berättelsen om Tower of Althalaxx. Du behöver bara ta dig från tornets närhet till Maestra's Post i Ashenvale och rapportera din avgörande seger till Delgren the Purifier.",al={"målet med tower of althalaxx","lämna in tower of althalaxx","var lämnar man in uppdrag 981"}},{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en Alliansens förkämpe stationerad vid Maestra's Post i norra Ashenvale. Han brukar det Heliga ljuset och är hängiven åt att rena världen från korruption och bekämpa demoniska hot som Cult of the Dark Strand i norra Kalimdor.",al={"vem är delgren","delgrens bakgrund","delgren the purifier"}},{q="Vem är Balthule Shadowstrike?",a="Balthule Shadowstrike är en agent för Alliansen som håller till nära Tower of Althalaxx i Darkshore. Han samarbetar nära med Delgren, håller uppsikt över kultens rörelser och vägleder äventyrare när de monterar ned den mörka sammansvärjningen inifrån.",al={"balthule","balthules bakgrund","vem är balthule shadowstrike"}},{q="Vad gjorde Cult of the Dark Strand i tornet?",a="Cult of the Dark Strand ockuperade de forntida ruinerna av Tower of Althalaxx för att utföra mörka ritualer, åkalla demoniska väsen och utöka sitt olycksbådande inflytande över Darkshores kustland.",al={"cult of the dark strand","vad hände vid althalaxx","tower of althalaxx bakgrund"}},{q="Var ligger Maestra's Post?",a="Maestra's Post är en utpost för Alliansen i nordvästra Ashenvale, strax söder om gränsövergången från Darkshore längs huvudvägen.",al={"maestra's post plats","var ligger maestra's post","var finns delgren"}},{q="Är Cult of the Dark Strand helt utplånad?",a="Ledarskapet vid Tower of Althalaxx har avrättats och den främsta ritualen brutits, men kringströvande kultister och rester finns fortfarande kvar i avlägsna delar av Kalimdor. Deras organiserade hot i Darkshore har dock krossats.",al={"är kulten borta","är dark strand utplånad","dödade vi kulten"}}},fx={b456cfd7={q="Varför vill Balthule Shadowstrike att detta görs?",a="Nu när Cult of the Dark Strand har slagits sönder och dess ledarskap krossats vill Balthule att du förmedlar segerbudskapet till Delgren the Purifier. Delgren inledde kampanjen mot kultisterna som höll till i tornet. Balthule anser att dina insatser förtjänar erkännande och den belöning paladinen lovade.",al={"varför skicka mig tillbaka till delgren","balthules motiv","varför rapportera till delgren"}}},fp="22,192,16.329.0,24.372.0,31.186.0,28.248.0,29.205.0,56.189.0,32.129.0,52.239.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="Pristine Pesterhide Pelts är ett uppdrag på uppdrag av Kristy Grant, en resenär som söker efter Pesterhide-hyenornas lysande pälsar i Thousand Needles. Eftersom Kristy själv saknar stridsvana förlitar hon sig på skickliga äventyrare som jagar odjuren och tar till vara på deras skinn. Hon vill skicka de unika skinnen över havet till sina systrar i Stormwind, där de kan förvandlas till fina kläder och föremål.",h="Pristine Pesterhide Pelts är ett uppdrag på uppdrag av Kristy Grant, en resenär som söker efter...",kw={"päls","jakt","hyena","kristy grant","skinn","pesterhide","stormwind","thousand needles"},ang={["faction:Alliance"]="Uppdraget handlar om en resenär från Stormwind som vill förse sin hantverkskunniga familj i huvudstaden. Det visar hur invånare i Alliansen färdas djupt in i Kalimdors gränsland för att hitta exotiska material.",["profession:Tailoring"]="Hantverkare som arbetar med tyg och dekorativa pälsar kan uppskatta Kristys systrars ambition att förvandla vilda skinn från Kalimdor till förfinade kläder.",["race:Human"]="Kristy Grant förkroppsligar Stormwind-människornas företagsamma anda när de färdas långt över havet och håller nära kontakt med släktingar i kungariket."},sec={{t="En systers ambition",b="Långt från Stormwinds livliga kullerstensgator färdas Kristy Grant genom den torra, solstekta ravinen i Thousand Needles. När hon betraktar det lokala djurlivet slås hon av Pesterhide-hyenornas pälsars intensiva färg och fina kvalitet. Hon inser att sådana särpräglade skinn är så gott som okända i Eastern Kingdoms och föreställer sig hur hon skickar en last hem till sina systrar. För henne är skinnen inte bara en bit av Kalimdors gränsland, utan också råmaterial som familjens skickliga händer i kungariket kan förvandla till något alldeles enastående."},{t="Jägare på saltslätterna och i ravinerna",b="Kristy Grant har sinne för hantverk och handel, men är ingen krigare och saknar stridsvana för att själv möta ravinens vildsinta rovdjur. Pesterhide-hyenorna är våldsamma asätare som jagar i flock och strövar över de dammiga vidderna nedanför de höga platåbergen. Att samla in felfria skinn är därför farligt för en ensam resenär. För att få tag på fem oskadade skinn utan att riskera livet tar Kristy hjälp av erfarna äventyrare som färdas genom Needle. Uppdraget kräver att de ger sig ut i vildmarken, besegrar de revirhävdande odjuren och varsamt samlar in skinnen som hennes familj behöver för sitt hantverk där hemma."}},faq={{q="Vem är Kristy Grant?",a="Kristy Grant är en resenär från kungariket Stormwind som just nu färdas genom Kalimdor. Till skillnad från de härdade soldater och legosoldater som tar sig genom Thousand Needles medger hon att hon själv saknar stridsvana. I stället förlitar hon sig på skarp iakttagelseförmåga och sinne för värdefulla hantverksmaterial. Hon anlitar skickliga äventyrare för att samla in varor som hyenaskinn åt henne.",al={"kristy grant bakgrund","vem ger pristine pesterhide pelts","vem är kristy grant"}},{q="Vad är Pesterhide-hyenor?",a="Pesterhide-hyenor är vilda rovdjur av hundsläktet som hör hemma på de torra ravinbottnarna och vidderna i Thousand Needles. De strövar genom den ogästvänliga terrängen och jagar och letar efter as i flock. Förutom sin vildsinta natur är de kända för sin lysande, vackert färgade päls, som sticker ut mot öknens klippor och fångar resande skräddares och pälsarbetares blickar.",al={"pesterhide-hyena","hyenor i thousand needles","vad är pesterhides"}},{q="Varför vill Kristy Grant ha skinnen?",a="Kristy Grant vill samla in felfria hyenaskinn och skicka dem över havet till sina systrar i kungariket Stormwind. Hon är mycket imponerad av pälsarnas lysande färg och tror att hennes systrar har hantverksskickligheten som krävs för att väva eller sy fantastiska färdiga produkter av de exotiska skinnen.",al={"varför samla pesterhide-skinn","vad används pesterhide-skinn till","vad gör kristy med skinnen"}},{q="Vart tar skinnen vägen?",a="Skinnen som samlas in i Thousand Needles ska till Eastern Kingdoms, närmare bestämt stadsriket Stormwind. Kristy tänker frakta skinnen hem över Great Sea, så att hennes systrar kan arbeta med exotiska material som är nästan omöjliga att få tag på i de välbekanta skogarna i Elwynn eller Redridge.",al={"vart skickas skinnen","skinn till stormwind","vem får hyenaskinnen"}},{q="Varför kan inte Kristy jaga hyenorna själv?",a="Kristy Grant medger öppet att hon helt saknar stridsvana. De vilda djuren i Thousand Needles är aggressiva och farliga att möta, särskilt för en obeväpnad hantverkare eller resenär. I stället för att riskera skada eller död bland hyenornas kringströvande flockar anlitar hon skickliga vandrare för att jaga djuren säkert.",al={"varför kan kristy inte slåss","kristy grant stridsvana","varför behöver kristy hjälp"}},{q="Vad gör skinnen felfria?",a="Eftersom skinnen är avsedda för fint hantverk och modekreationer av Kristys systrar i Stormwind duger inte vanliga eller sönderrivna pälsar. Endast oskadade, felfria skinn bevarar den livfulla färgen och strukturen som krävs för att tillverka kläder av hög kvalitet. Därför måste jägarna vara försiktiga och bara ta till vara på de bästa skinnen från odjuren.",al={"vad betyder felfria skinn","varför felfria skinn","kvaliteten på pristine pesterhide-pälsar"}}},fp="25,191,19.290.0,37.280.0,20.213.0,27.221.0,37.183.0,26.185.0,41.198.0,32.139.0"}
P.entries["quest:98189"] = {n="Return the Statuette",s="Leveransen av en statyett till Menethil Harbor avbröts av en tragedi. Du ombeds föra den till Captain Stoutfist i Menethil Keep.",h="Leveransen av en statyett till Menethil Harbor avbröts av en tragedi.",kw={"blind princess","captain stoutfist","menethil harbor","menethil keep","menethil statuette","statyett"},sec={{t="En oavslutad leverans",b="Statyetten var avsedd för Menethil Harbor, där Captain Stoutfist i Menethil Keep förväntades kvittera den. Nu ombeds du slutföra leveransen."}},faq={{q="Vem ska ta emot statyetten?",a="Captain Stoutfist i Menethil Keep förväntas kvittera Menethil Statuette.",al={"vem får statyetten","statyettens mottagare","captain stoutfist leverans"}},{q="Vart skulle statyetten skickas?",a="Statyetten skulle levereras till Menethil Harbor.",al={"vart ska den","statyettens destination","menethil statuette"}},{q="Vem hade den tidigare?",a="The Blind Princess skulle leverera statyetten innan tragedin slog till.",al={"vem hade statyetten","blind princess statyett","statyettleverans"}},{q="Vad ombeds jag göra?",a="Du ombeds föra Menethil Statuette till Captain Stoutfist i Menethil Keep.",al={"vad ska göras","lämna tillbaka statyetten","statyettuppdrag"}}},fp="20,134,22.156.0,38.82.0,39.59.0,27.79.0,26.84.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="A Friend of the Family är ett brådskande kuriruppdrag från Menethil Harbor i Wetlands. Av rädsla för lokala hot som Dragonmaw-orcherna anförtror hamnens myndigheter en äventyrare att leverera den ovärderliga Menethil Statuette direkt till Highlord Bolvar Fordragon i Stormwind Keep.",h="A Friend of the Family är ett brådskande kuriruppdrag från Menethil Harbor i Wetlands.",kw={"bolvar","dragonmaw","fordragon","hamn","menethil","statyett","stormwind","terenas","wetlands"},ang={["class:Paladin"]="Namnet Menethil för tankarna till den välgörare som grundade Silver Hand-riddarna. Därför är det en högtidlig plikt för varje helig krigare att bevara reliken.",["faction:Alliance"]="Att leverera reliken hedrar den historiska nordliga alliansen och håller en ovärderlig symbol borta från klanen Dragonmaws klor.",["race:Human"]="För människor bevarar skyddet av ett föremål från Menethil-dynastin det stolta och tragiska minnet av det fallna Lordaeron och stärker Stormwinds plikt som det sista stora mänskliga kungariket."},sec={{t="En utsatt hamn",b="Menethil Harbor är en viktig flottport som förbinder de norra delarna av Eastern Kingdoms med södern. Hamnen är uppkallad efter den avlidne kung Terenas Menethil II av Lordaeron och ligger isolerad bland förrädiska träsk och fientliga fiender. När hoten i området ökar inser hamnens ledning att ovärderliga reliker med anknytning till det fallna nordliga kungariket inte kan förvaras säkert i en så utsatt utpost."},{t="Hotet från Dragonmaw",b="Wetlands är fortfarande hemsökt av resterna av klanen Dragonmaw, vildsinta orcher kända för sitt mörka förflutna och sin hänsynslösa opportunism. Med tanke på hur nära de finns och hur hungriga de är på erövringar fruktar hamnens försvarare att Dragonmaw inte skulle dra sig för att plundra historiska skatter som Menethil Statuette, kanske vanhelga den eller använda den som vapen för egna syften."},{t="Rakt till Highlord",b="I stället för att riskera förseningar via vanliga byråkratiska eller militära kanaler får kuriren order att helt kringgå befälskedjan. Reliken skickas direkt till Stormwind Keep, till Highlord Bolvar Fordragons händer. Han är regent åt den unge kungen Anduin Wrynn, och man litar på att ledningen i huvudstaden bäst kan skydda en del av Lordaerons arv."}},faq={{q="Vad är Menethil Statuette?",a="Menethil Statuette är ett värdefullt arvegods med band till Lordaerons kungliga ätt och kung Terenas Menethil II. Den representerar de historiska banden mellan det nordliga kungariket och Alliansen, vilket gör den till ett mål för asätare och fiender.",al={"menethil-relik","vad är statyetten","statyettens historia"}},{q="Varför kan statyetten inte stanna i Menethil Harbor?",a="Menethil Harbor ligger isolerad och omges av fientliga träsk, mörka järndvärgar, murlocer och fientliga orcher. Garnisonen anser att bosättningen är alldeles för utsatt för att kunna skydda en så betydelsefull relik.",al={"varför flytta statyetten","är menethil harbor osäkert"}},{q="Vilka är Dragonmaw och varför vill de ha den?",a="Klanen Dragonmaw är en orchfraktion som har slagit sig ned i Wetlands. Hamnens tjänstemän oroar sig för att de gärna skulle offra krigare för att plundra ansedda alliansreliker och kanske vanhelga eller använda dem i onda syften.",al={"hotet från dragonmaw","varför vill orcher ha statyetten"}},{q="Varför leverera reliken direkt till Bolvar Fordragon?",a="Som regent över Stormwind och beskyddare av den unge kungen Anduin har Highlord Bolvar Fordragon den högsta verkställande makten i huvudstaden. Om reliken överlämnas direkt till honom slipper den administrativa låsningar och får högsta möjliga säkerhet.",al={"varför bolvar","varför kringgå befälskedjan"}},{q="Var befinner sig Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon står i tronsalen i Stormwind Keep, bredvid pojkkungen Anduin Wrynn.",al={"var bolvar finns","var är bolvar"}},{q="Hur hänger Menethil Harbor ihop med kung Terenas?",a="Menethil Harbor fick sitt namn som en hyllning till kung Terenas Menethil II, som ledde Lordaeron och stödde Alliansen av Lordaeron under det andra kriget, innan han tragiskt dog under det tredje kriget.",al={"varför heter hamnen menethil harbor","terenas menethils koppling"}}},fx={ece51c60={q="Varför väljs du att föra Menethil Statuette till Stormwind?",a="Menethil Harbor är isolerat och ständigt hotat av fientliga styrkor på andra sidan Wetlands, vilket gör att garnisonen har fullt upp med att försvara hamnen. Du har redan visat dig kapabel och pålitlig genom att återfinna arvegodset. Genom att anförtro det åt en självständig resenär som du slipper staden försvaga sitt lokala försvar, och uppdraget kan genomföras diskret genom farligt område.",al={"varför skicka mig","varför inte skicka vakter","varför leverera statuetten"}}},fp="22,170,19.295.0,20.229.0,24.269.0,31.211.0,48.159.0,46.187.0,51.190.0,43.100.0,49.159.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="I Stormwind för A Friend of the Family en sällsynt avbild av kung Terenas till Cathedral of Light. Highlord Bolvar Fordragon anförtror Menethil Statuette åt en äventyrare för Lord Grayson Shadowbreaker, som ska hålla den i säkerhet.",h="I Stormwind för A Friend of the Family en sällsynt avbild av kung Terenas till Cathedral of Light.",kw={"bolvar","katedral","lordaeron","menethil","shadowbreaker","statuett","stormwind","terenas"},ang={["class:Paladin"]="Som paladin skyddar du en relik från kung Terenas som berörts av ljuset. Den hedrar härskaren som först gav sitt godkännande till grundandet av Knights of the Silver Hand.",["class:Priest"]="Som präst kan du se hur helig kraft samlats i en enkel, utskuren avbild. Den vittnar om Lordaerons trogna arv, trots att kungarikets landområden förstörts.",["faction:Alliance"]="Som medlem av Alliansen minns du kung Terenas Menethil II som en grundpelare i Alliance of Lordaeron. Varje föremål med anknytning till honom är ett kärt tecken på enighet och hågkomst."},sec={{t="Ett sällsynt minne",b="Kung Terenas Menethil II hjälpte till att forma Grand Alliance under andra kriget och levde med stor personlig hängivenhet. Trots sin höga ställning bland människornas kungariken var han ödmjuk och ogillade monument som restes till hans ära. Få avbildningar beställdes, och ännu färre överlevde Lordaerons fall och Scourges förödelse."},{t="Berörd av nåden",b="Highlord Bolvar Fordragon ser mer än ett fint hantverk i den bevarade Menethil Statuette. The Holy Light har börjat samlas i den och ger figuren en stilla andlig närvaro. Bolvar beslutar att Stormwind Keep inte är rätt plats för ett sådant heligt föremål. Han skickar den genom staden till Cathedral of Light, i Lord Grayson Shadowbreakers vård. Där tränar han paladiner."}},faq={{q="Vem var kung Terenas Menethil II?",a="Kung Terenas Menethil II styrde Kingdom of Lordaeron och var älskad av sitt folk. Under andra kriget förenade han människorikena med dvärgarna, gnomerna och högalverna för att bilda Grand Alliance, som besegrade Orcish Horde. Han dödades när hans rike föll.",al={"terenas menethil","vem är terenas","lordaerons kung"}},{q="Varför är statyer av kung Terenas så sällsynta?",a="Kung Terenas var ödmjuk och ogillade storslagna monument till sin ära. Få avbildningar höggs ut, och nästan inga överlevde Scourges förstörelse av Lordaeron.",al={"varför finns det få statyer","terenas statuett sällsynthet","varför så få minnesmärken"}},{q="Varför lyser Menethil Statuette av ljuset?",a="Bolvar märker att ljuset har samlats i statuetten. Han kallar Terenas en god och from man, men förklarar inte varför denna avbild bär på helig kraft.",al={"varför har statuetten ljus","helig statuett","ljus som samlas"}},{q="Vem är Lord Grayson Shadowbreaker?",a="Lord Grayson Shadowbreaker är en erfaren mänsklig paladin i Knights of the Silver Hand och en mästare vid Cathedral of Light. Han är stationerad i Cathedral Square, där han tränar blivande paladiner och vakar över heliga angelägenheter för Stormwinds troende.",al={"vem är shadowbreaker","lord graysons roll"}},{q="Varför skickar Highlord Bolvar statuetten till katedralen?",a="Bolvar hedrar Terenas som Alliansens fader och anser att statuetten hör hemma i Cathedral of Light. Helig kraft har samlats i den, och han anförtror den åt de heliga ordnarna i stället för att låta den stanna bland hovets tjänstemän i Stormwind Keep.",al={"varför skicka till katedralen","varför inte behålla i stormwind keep"}},{q="Var ligger Cathedral of Light?",a="Cathedral of Light dominerar Cathedral Square i hjärtat av Stormwind City, mellan Dwarven District, Trade District och Mage Quarter. Den är den främsta helgedomen och gudstjänstplatsen för Church of the Holy Light i de södra kungarikena.",al={"var ligger cathedral of light","cathedral squares läge"}}},fp="22,156,18.328.0,16.369.0,33.285.0,40.164.0,53.156.0,34.250.0,61.248.0,40.251.0"}
P.entries["quest:98197"] = {n="Spoils of War",s="När Dragonmaw förflyttar sig söker Valstag Ironjaw timmer och järn från Menethil Harbor. Han behöver materialet för att stärka stadens försvar.",h="När Dragonmaw förflyttar sig söker Valstag Ironjaw timmer och järn från Menethil Harbor.",kw={"dragonmaw","järn från khaz modan","timmer från khaz modan","menethil harbor","old horde","spoils of war","stadens försvar","valstag ironjaw"},ang={["faction:Alliance"]="Som resenär från Alliance hjälper du till att stärka stadens försvar mot Dragonmaw.",["race:Dwarf"]="Som dvärg vet du kanske att Old Horde byggde sin flotta här med resurser stulna från Khaz Modan."},sec={{t="Ham­nens förråd",b="Menethil Harbor var en gång Old Hordes uppmarschområde inför en invasion av Hillsbrad. Flottan som byggdes där använde resurser stulna från Khaz Modan. En del förnödenheter finns kvar i hamnen, och Valstag ber dig hämta virket och järnet åt honom till stadens försvar."},{t="Nya förnödenheter",b="Valstag tackar dig för att du hämtade materialet. Med det behöver staden inte enbart förlita sig på leveranser från Theramore eller Auberdine."}},faq={{q="Vad behöver Valstag från Menethil Harbor?",a="Valstag ber dig hämta timmer och järn från Khaz Modan i Menethil Harbor.",al={"vad behöver han","timmer och järn","hamnens förnödenheter"}},{q="Varför finns förnödenheter från Khaz Modan i hamnen?",a="Old Horde byggde en flotta i Menethil Harbor med resurser stulna från Khaz Modan.",al={"varför finns timmer där","järn från khaz modan","old hordes förnödenheter"}},{q="Vad ska materialet användas till?",a="Valstag säger att materialet ska hjälpa till att stärka stadens försvar när Dragonmaw förflyttar sig.",al={"varför samla förnödenheter","försvar","vad är de till för"}},{q="Vem är Valstag Ironjaw?",a="Valstag Ironjaw ber dig hämta timmer och järn från Menethil Harbor.",al={"vem är valstag","valstag","ironjaw"}},{q="Var använde Old Horde Menethil Harbor?",a="Old Horde använde Menethil Harbor som uppmarschområde för sin sjöburna invasion av Hillsbrad.",al={"old hordes hamn","menethils historia","invasionen av hillsbrad"}},{q="Varför välkomnar Valstag dessa förnödenheter?",a="Materialet innebär att staden inte enbart behöver förlita sig på leveranser från Theramore eller Auberdine.",al={"varför tackar han","leveranser från theramore","förnödenheter från auberdine"}}},fp="13,133,13.272.0,12.129.1,44.76.0,42.86.0,36.92.0,23.73.0,44.91.0,40.90.0"}
P.entries["quest:982"] = {n="Deep Ocean, Vast Sea",s="Deep Ocean, Vast Sea är ett Alliance-uppdrag som Gorbold Steelhand ger i Auberdine. Du ska dyka i vattnet norr om byn och hämta personliga kassaskrin från två sjunkna Night Elf-fartyg, Silver Dawning och Mist Veil. Båda fartygen överfölls av murlocs från kusten, och de överlevande i besättningarna söker nu ett avslut.",h="Deep Ocean, Vast Sea är ett Alliance-uppdrag som Gorbold Steelhand ger i Auberdine.",kw={"auberdine","darkshore","deep ocean vast sea","gorbold steelhand","kassaskrin","mist veil","murloc","skeppsvrak","silver dawning"},ang={["faction:Alliance"]="Besättningarnas gemensamma sorg i Auberdine visar på det nära maritima samarbetet mellan dvärgar och Night Elves längs Kalimdors kust.",["race:Dwarf"]="Gorbold Steelhand visar den typiska dvärgiska instinkten att hedra fallna kamrater och stötta sina sjömän i främmande hamnar.",["race:NightElf"]="De stupade kaptenerna var Night Elf-sjöfarare i Auberdines sjöfartshandel, så att återfinna deras tillhörigheter är en fråga om heder gentemot förfäderna."},sec={{t="Tragedi vid kusten",b="Vattnen utanför Darkshore har blivit allt farligare, inte bara på grund av förrädiska strömmar och naturliga rev, utan också på grund av aggressiva kuststammar. Fartygen Silver Dawning och Mist Veil var på väg in till hamnen i Auberdine när de övermannades av svärmande murlocs. Inget av fartygen överlevde anfallet, och båda sjönk på grunt vatten norr om bosättningen. De överlevande i besättningarna lyckades ta sig i land, men förlusten av fartygen och kaptenerna lade en tung skugga över hamnen."},{t="Återfinna förlorade minnen",b="Gorbold Steelhand, en dvärg stationerad i Auberdine, tar sig an uppgiften att hedra de stupade Night Elf-kaptenerna. Fartygen är nu ruiner under vattnet, som traktens murlocs tagit över som troféer och bon, men kaptenernas kassaskrin ligger fortfarande låsta i de vattenfyllda lastrummen. När loggböckerna och de personliga tillhörigheterna därinne återbördas kan de överlevande sjömännen i Auberdine sörja sina befälhavare ordentligt och låta deras andar få ro."}},faq={{q="Var ligger de sjunkna fartygen?",a="Vrak efter både Silver Dawning och Mist Veil ligger under vatten utanför Darkshores kust, alldeles norr om bryggorna i Auberdine.",al={"var ligger skeppsvraken","vrakens plats","var hittar man silver dawning"}},{q="Vad hände med Silver Dawning och Mist Veil?",a="Båda fartygen överfölls av murlocs när de seglade över havet mot Auberdine. Besättningarna övermannades, båda kaptenerna dog och fartygen gick under och lade sig på havsbotten.",al={"hur sjönk fartygen","varför förliste fartygen","vad sänkte mist veil"}},{q="Vem är Gorbold Steelhand?",a="Gorbold Steelhand är en dvärg som bor i Night Elf-hamnen Auberdine. Han håller uppsikt över de överlevande sjömännen i staden och ger äventyrare i uppdrag att återfinna de förlorade kaptenernas tillhörigheter.",al={"vem ger deep ocean vast sea","gorbold steelhands historia"}},{q="Vad finns i kassaskrinen?",a="Kassaskrinen innehåller personliga tillhörigheter och loggböcker som tillhör de stupade Night Elf-kaptenerna. Föremålen är kära minnen för besättningsmedlemmarna som överlevde förlisningen.",al={"vad finns i kassaskrinen","kaptenernas kassaskrin innehåll"}},{q="Varför bryr sig de överlevande så mycket om de här tillhörigheterna?",a="Kaptenerna var respekterade Night Elf-sjöfarare. Att återfinna deras loggböcker och ägodelar ger deras överlevande besättningar ett avslut och tros hjälpa deras andar att få ro.",al={"varför återfinna kassaskrinen","varför hjälpa kaptenerna"}},{q="Vilka varelser bor nu i skeppsvraken?",a="Ruinerna har tagits över av murlocs, som behandlar de vrakslagna skroven som troféer och stryker omkring i vattnen intill.",al={"vad vaktar fartygen","fiender vid skeppsvraken"}}},fp="20,205,21.245.0,24.307.0,35.71.0,54.167.0,25.141.0,29.126.0,54.150.0,42.102.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="Bloom of the Heavens handlar om att återfinna Nord'el, en helig Night Elf-blomma som plockas under fullmåne på Mount Hyjal. Blomman gick förlorad när Night Elf-fartyget Flying Osprey förliste söder om Menethil Harbor tillsammans med skepp från Kul Tiran Third Fleet. Nu måste äventyrare våga möta murlocer som håller till bland vrakdelarna för att hämta den.",h="Bloom of the Heavens handlar om att återfinna Nord'el, en helig Night Elf-blomma som plockas under fullmåne...",kw={"auberdine","bloom of the heavens","flying osprey","menethil harbor","mount hyjal","murlocer","nord'el","sylessa duskwhisper","teldrassil","wetlands"},ang={["faction:Alliance"]="Det förlorade fartyget Flying Osprey seglade tillsammans med Kul Tiran Third Fleet innan båda drabbades av katastrofen utanför Menethil Harbors kust.",["profession:Herbalism"]="Nord'el är en ytterst sällsynt Night Elf-blomma som odlas under fullmåne på toppen av Mount Hyjal. Den är ett botaniskt underverk utan motstycke.",["race:NightElf"]="Nord'el är en dyrbar botanisk relik från Mount Hyjal, plockad innan Night Elf flyttade sitt hem till Teldrassils grenar."},sec={{t="En relik från Mount Hyjal",b="Sylessa Duskwhisper gjorde den långa resan från Auberdine vid Kalimdors kust till Menethil Harbor för att rädda en skatt med djup kulturell betydelse. Lasten hon söker är Nord'el, som på det gemensamma språket kallas Bloom of the Heavens, en helig blomma plockad på Mount Hyjals topp under en strålande fullmåne. För de fördrivna Night Elf som nu bor i Teldrassil är sådana reliker från deras förfäders berg ovärderliga påminnelser om deras arv."},{t="Flying Ospreys öde",b="Blomman gick förlorad för många månvarv sedan när Night Elf-fartyget Flying Osprey förliste längs den klippiga kusten strax söder om Menethil Harbor, efter att ha seglat tillsammans med Kul Tiran Third Fleet. I dag ligger det förstörda skrovet på grunt vatten, som ett dystert minnesmärke över katastrofen. Som om det inte vore nog har våldsamma murlocrövare tagit över vraket. De försvarar det förstörda fartyget med våld och hotar alla som försöker återta Kaldorei-lasten."}},faq={{q="Vad är Nord'el?",a="Nord'el betyder Bloom of the Heavens på darnassiska. Det är en helig blomma av stor betydelse för Night Elf, plockad efter att ha blommat under fullmåne på toppen av Mount Hyjal, Night Elfs förfäders bergshem.",al={"vad är nord'el","nord'el-blomma","vad är bloom of the heavens"}},{q="Vad var Flying Osprey?",a="Flying Osprey var ett Night Elf-fartyg som seglade tillsammans med Kul Tiran Third Fleet. För många månvarv sedan förliste fartyget strax söder om Menethil Harbor, längs Wetlands kust, och dess värdefulla last spreds ut.",al={"fartyget flying osprey","vilket fartyg förliste","kul tiran third fleet wetlands"}},{q="Vem är Sylessa Duskwhisper?",a="Sylessa Duskwhisper är en Night Elf-sändebud som reste över havet från Auberdine och Teldrassils grenar till Menethil Harbor, särskilt för att återfinna den förlorade blomman åt sitt folk.",al={"vem är sylessa duskwhisper","uppdragsgivare menethil","night elf i menethil"}},{q="Varför är skeppsvraket farligt?",a="Våldsamma murlocrövare har tagit över kustvraket söder om Menethil Harbor och lagt beslag på resterna av Flying Osprey. Därför är bärgningen farlig för Sylessa.",al={"varför finns murlocer vid vraket","vem vaktar vraket","vrak söder om menethil"}},{q="Varför är Nord'el så viktig för Night Elf?",a="Blomman plockades på toppen av Mount Hyjal, Kaldoreis forna hem, innan Teldrassil grundades. Dess ursprung och heliga skörd under fullmånen ger den ett enormt kulturellt och känslomässigt värde för Night Elf.",al={"varför är blomman viktig","varför vill sylessa ha nord'el"}},{q="Var finns vraket?",a="Vraket efter Flying Osprey ligger vid kusten strax söder om Menethil Harbor i Wetlands, bland klippor som nu svärmar av fientliga murlocer.",al={"var finns vraket","var finns blomman","skeppsvrakets plats wetlands"}}},fp="20,285,22.299.0,29.295.0,16.175.0,27.182.0,27.145.0,31.155.0,47.190.0,32.122.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="Bloom of the Heavens är en resa över havet för att föra en mirakulös botanisk relik från Night Elf, kallad Nord'el, vidare. Den bevarade blomman troddes ha gått förlorad i generationer och är en stark symbol för Elunes nåd och kaldoreiernas motståndskraft efter förlusten av sin odödlighet.",h="Bloom of the Heavens är en resa över havet för att föra en mirakulös botanisk relik från Night Elf, kallad...",kw={"auberdine","bloom of the heavens","darkshore","darnassus","elune","menethil harbor","nord'el","sylessa","thundris windweaver","wetlands"},ang={["faction:Alliance"]="Uppdraget förbinder den livliga allianshamnen Menethil Harbor i Eastern Kingdoms med Auberdine och Darnassus i norra Kalimdor, tvärs över Great Sea.",["profession:Herbalism"]="Örtkännare och botaniker kommer att uppskatta att Nord'el återfunnits. Denna heliga växt troddes ha varit förlorad i evigheter och behöver odlas i Darnassus.",["race:NightElf"]="Nord'el är en dyrbar kvarleva av Kalimdors heliga arv och ett upplyftande tecken på att Elune vakar över kaldoreierna medan de anpassar sig till förlusten av sin odödlighet."},sec={{t="En farlig återhämtning",b="I våtmarkerna i Wetlands lyckas Sylessa återfinna en legendarisk blomma som kallas Nord'el, trots att hon utsätts för ett angrepp från våldsamma lokala murlocer. Utmattad efter sin farliga flykt anförtror hon växten åt en äventyrare, som ska föra den över Great Sea till Auberdine. Båten från Menethil Harbor går direkt till Darkshore och förbinder Eastern Kingdoms med norra Kalimdor."},{t="Ett tecken på Elunes nåd",b="När Elder Thundris Windweaver får Nord'el i Auberdine blir han häpen. Han hade trott att den heliga blomman försvunnit för alltid. Night Elf kämpar fortfarande med uppoffringen av sin odödlighet efter slaget vid Mount Hyjal, och Nord'els mirakulösa överlevnad lyser som en välsignelse från Elune. Thundris förbereder sig på att skicka den ömtåliga växten vidare till Darnassus, där den ska odlas och bevaras åt kommande generationer."}},faq={{q="Vad är Nord'el?",a="Nord'el är en helig växt som Night Elf länge trodde hade gått förlorad. Att den återfunnits och överlevt efter många år gör den till en dyrbar symbol för Elunes gudomliga ynnest och ett vittnesbörd om naturens motståndskraft.",al={"vad är nord'el","nord'el blomma","helig blomma"}},{q="Vem ger uppdraget Bloom of the Heavens?",a="Sylessa i Wetlands ger uppdraget. Hon lyckades återfinna den heliga blomman trots att hon överfölls och förföljdes av fientliga murlocer, men prövningen gjorde henne alltför utmattad för att själv slutföra resan.",al={"vem ger bloom of the heavens","uppdragsgivare i wetlands nord'el","sylessa wetlands"}},{q="Vart ska Nord'el levereras?",a="Nord'el ska föras över havet till Elder Thundris Windweaver i Auberdine, vid kusten i Darkshore. Resenärer tar båten direkt från Menethil Harbor till Auberdine.",al={"vart ska jag föra nord'el","thundris windweaver plats","leverans till auberdine"}},{q="Varför är Nord'el så betydelsefull för Night Elf?",a="Elder Thundris Windweaver ser blommans överlevnad som ett sällsynt hoppets ljus i mörka tider. Den är en helig påminnelse om Elunes nåd och kaldoreiernas uthålliga anda efter att de offrat sin odödlighet under det tredje kriget.",al={"varför är nord'el viktig för night elf","nord'el bakgrund","night elf odödlighet nord'el"}},{q="Vad händer med blomman när den når Auberdine?",a="När Thundris Windweaver tar emot blomman i Auberdine ordnar han så att den förs säkert inåt landet till Darnassus, där Night Elf-botaniker och präster kan vårda och odla den ordentligt.",al={"vad händer med nord'el sedan","nord'el darnassus","vart skickar thundris nord'el"}},{q="Hur tar man sig från Menethil Harbor till Auberdine?",a="Resenärer kan ta passagerarbåten som lägger till i Menethil Harbor i Wetlands. Den seglar direkt över Great Sea till hamnen i Auberdine i Darkshore.",al={"hur tar man sig till auberdine från wetlands","båt från menethil till auberdine","båt till darkshore"}}},fp="20,189,20.315.0,23.403.0,16.153.0,41.199.0,40.155.0,49.201.0,56.170.0,52.98.0"}
P.entries["quest:98219"] = {n="The Shamed Lieutenant",s="En vakt från Stormwind ber dig se till Lieutenant Farren Orinelle i Southshore. Hans omplacering ska lära honom en läxa, men vakten hoppas att han ändå kan lyckas.",h="En vakt från Stormwind ber dig se till Lieutenant Farren Orinelle i Southshore.",kw={"farren orinelle","hillsbrad foothills","lieutenant farren","menethil harbor","southshore","vakt från stormwind","den vanärade löjtnanten"},ang={["faction:Alliance"]="Som resenär från Alliance blir du ombedd att se till en stadsvakt från Stormwind som tjänstgör i Southshore."},sec={{t="En tillsyn",b="Du har levererat statyetten i tryggt förvar. Nu ber din kontakt dig att tala med Lieutenant Farren Orinelle, en stadsvakt som skickats till Southshore i Hillsbrad Foothills. Farrens far var vän med vakten, som tror att Farren skulle kunna behöva hjälp. Om du har vägarna förbi går en båt till Southshore från Menethil Harbor."}},faq={{q="Vem blir jag ombedd att tala med?",a="Du blir ombedd att tala med Lieutenant Farren Orinelle, en stadsvakt som skickats till Southshore.",al={"vem är farren","lieutenant farren","farren orinelle"}},{q="Var är Lieutenant Farren?",a="Lieutenant Farren Orinelle är i Southshore, i Hillsbrad Foothills.",al={"var är farren","farrens plats","löjtnanten i southshore"}},{q="Varför blev Farren omplacerad?",a="Vakten säger att Farren skulle behöva lära sig en läxa, men ger ingen ytterligare anledning till hans omplacering.",al={"varför omplacerad","farrens straff","varför är han i southshore"}},{q="Hur känner vakten Farren?",a="Farrens far var vän med vakten som ber dig se hur han har det.",al={"farrens far","vem var hans pappa","koppling till vakten"}},{q="Hur tar jag mig till Southshore?",a="En båt från Menethil Harbor kan ta dig till Southshore.",al={"båt till southshore","rutten från menethil","hur tar man sig dit"}},{q="Har någon sett till Farren tidigare?",a="Farren säger att en annan vakt från Stormwind kom för att se till honom förra månaden.",al={"förra månaden","andra besökare","vem ser till farren"}}},fp="21,171,10.331.0,35.94.0,27.68.0,26.93.0,31.71.0,28.55.0,36.76.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="Razormaw Needling är ett uppdrag i Wetlands där Howin Kindfeather ber resenärer samla in framtänder från traktens Razormaw-raptorer. Howin vill tillverka hållbara sylverktyg av deras vassa tänder för att kunna genomborra och sy ihop drakungars fjäll till eldtålig rustning.",h="Razormaw Needling är ett uppdrag i Wetlands där Howin Kindfeather ber resenärer samla in framtänder från...",kw={"dark iron","dragonmaw","howin kindfeather","raptor ridge","raptorer","razormaw-framtänder","razormaw needling","saltspray glen","wetlands","drakungafjäll"},ang={["faction:Alliance"]="Skyddsutrustning mot drakeld hjälper Alliansen i den pågående kampen mot drakkin och Dragonmaw-styrkorna som håller de östra träskmarkerna.",["race:Dwarf"]="Howin Kindfeather delar Wildhammer- och Ironforge-dvärgarnas bittra hat mot både Dark Iron-klanen och Dragonmaw-orcherna, som härjade i Wetlands och Grim Batol."},sec={{t="Hämndens verktyg",b="I Wetlands blöta marker hyser Howin Kindfeather ett djupt raseri mot fienderna som har plågat trakten: de förrädiska Dark Iron-dvärgarna, de brutala Dragonmaw-orcherna och de eldsprutande drakar de förde med sig i strid. För att slå tillbaka och skydda sig mot drakeld arbetar Howin med att sätta ihop skyddande rustning av drakungars fjäll. Men de tåliga skinnen är ökända för att vara svåra att sy ihop utan särskilda hantverksverktyg."},{t="Tänder som nålar",b="För att sticka igenom det tåliga drakungeskinnet behöver Howin verktyg som är mycket vassare och starkare än vanliga metallnålar, som lätt böjs eller blir slöa mot drakfjäll. Han vänder sig till de lokala Razormaw-raptorerna som stryker omkring på Raptor Ridge i nordost och Saltspray Glen i nordväst. De har fått sitt namn efter sina dödliga, nålvassa tänder. Hela Razormaw-framtänder fungerar utmärkt som sylverktyg och genomborrar hårda fjäll utan att splittras under tryck."}},faq={{q="Vem ger uppdraget Razormaw Needling?",a="Howin Kindfeather ger uppdraget i Wetlands. Han hyser ett djupt agg mot Dark Iron-dvärgarna, Dragonmaw-klanen och drakarna de red på, och vill tillverka drakeldstålig rustning av drakungars fjäll.",al={"vem ger razormaw needling","vem är howin kindfeather","uppdragsgivare för razormaw needling"}},{q="Varför behöver Howin Kindfeather Razormaw-framtänder?",a="Howin arbetar med tåliga drakungafjäll för att tillverka skyddande rustning, men skinnet är för tätt för att enkelt kunna sys ihop. Han behöver Razormaw-raptorernas vassa, starka framtänder för att tillverka sylverktyg som kan genomborra fjällen utan att gå sönder.",al={"varför vill howin ha raptortänder","vad används razormaw-framtänder till","vad ska tänderna användas till"}},{q="Var finns Razormaw-raptorerna?",a="Razormaw-raptorer stryker omkring på två huvudsakliga jaktmarker i Wetlands: Raptor Ridge i högländerna i nordost och Saltspray Glen i nordväst, mot kusten.",al={"var hittar man razormaw-raptorer","razormaw-raptorernas plats i wetlands","var finns raptorerna"}},{q="Vad tillverkar Howin Kindfeather av drakungafjällen?",a="Howin syr ihop drakungars fjäll till skyddande utrustning. Fjällen ger ett gott skydd mot eldiga andedräkter och skyddar mot drakar och Dragonmaw-klanens drakar.",al={"vilken rustning tillverkar howin","rustning av drakungafjäll i wetlands","varför drakungafjäll"}},{q="Varför hatar Howin Dark Iron och Dragonmaw?",a="Wetlands och de omgivande bergen bär djupa ärr efter både Dark Iron-klanen och Dragonmaw-orcherna, som förslavade röda drakar under det andra kriget. Howin avskyr båda fraktionerna och deras flygande riddjur och är fast besluten att återställa balansen.",al={"varför hata dark iron och dragonmaw","howins fiender","varför hatar howin dragonmaw"}},{q="Vad gör Howin av raptorernas framtänder?",a="En syl är ett smalt, spetsigt handverktyg som används för att göra hål i tjocka hudar och läder före sömnad. Genom att fästa hela raptorframtänder på skaft eller använda deras naturliga avsmalning tillverkar Howin hållbara sylverktyg som kan genomborra drakfjäll utan att knäckas.",al={"vad är en syl","razormaw-sylverktyg","hur används raptortänder som verktyg"}}},fp="17,157,20.291.0,16.280.0,38.212.0,50.198.0,39.116.0,55.165.0,49.209.0,46.173.0"}
P.entries["quest:98246"] = {n="Trying Times",s="Trying Times är ett Alliance-uppdrag i Wetlands där äventyrare hjälper dvärgen Howin Kindfeather. För att förbereda sin griniga gryf Bassbeak för ett kommande uppdrag behöver Howin ett dussin hela ägg från de vilda Razormaw-raptorerna.",h="Trying Times är ett Alliance-uppdrag i Wetlands där äventyrare hjälper dvärgen Howin Kindfeather.",kw={"bassbeak","gryf","howin kindfeather","raptor ridge","razormaw-ägg","saltspray glen","trying times","wetlands"},ang={["faction:Alliance"]="Att hålla gryfer friska är avgörande för Alliansens resor och kommunikation genom Khaz Modan, särskilt när lokala faror hotar säkerheten i regionen.",["race:Dwarf"]="Dvärgarnas gryfryttare vet att en argsint gryf är lika farlig som vilken fiende som helst. Därför måste den få ordentlig mat och omvårdnad innan den lyfter mot skyn.",["race:Gnome"]="Howin påpekar skämtsamt att Razormaw-raptorernas ägg har gulor stora som en gnoms knopp. Det är ett talande, om än lite respektlöst, dvärgmått."},sec={{t="Att blidka en hungrig gryf",b="I Wetlands dunkla vidder krävs ständig vaksamhet för att hålla ett riddjur i skick. Howin Kindfeather, en dvärg som arbetar tillsammans med sin gryf Bassbeak, vägrar lyfta utan att först stilla sin följeslagare nyckfulla aptit. En hungrig gryf är envis och oförutsägbar, och den kan lätt gå till angrepp. Därför måste den få en ordentlig måltid innan någon flygtur över träskmarkerna."},{t="Razormaw-raptorernas fångst",b="Det har blivit allt svårare att hitta pålitlig, ofördärvad föda i Wetlands. För att mätta Bassbeak siktar Howin in sig på de inhemska Razormaw-raptorernas bon vid Raptor Ridge i nordost och Saltspray Glen i nordväst. Raptorernas ägg sägs ha gulor stora som en gnoms huvud. De ger Bassbeak den rejäla, rena måltid hon behöver innan hon möter regionens faror."}},faq={{q="Vem är Howin Kindfeather?",a="Howin Kindfeather är en dvärgskötare som tar hand om en gryf vid namn Bassbeak i Wetlands. Han ber äventyrare samla färska raptorägg och mata sin följeslagare innan han sätter sina planer i verket.",al={"vem är howin kindfeather","howin kindfeather wetlands","uppdragsgivare trying times"}},{q="Vem är Bassbeak?",a="Bassbeak är Howin Kindfeathers gryf. Enligt Howin blir hon lättretlig och direkt farlig när hon är hungrig. Det är därför osäkert att rida på eller använda henne innan hon är mätt.",al={"vem är bassbeak","bassbeak gryfen","howins gryf"}},{q="Varför behöver Howin raptorägg?",a="Howin är särskilt ute efter Razormaw-raptorägg eftersom ofördärvad föda är sällsynt i Wetlands. Äggen har stora, näringsrika gulor som kan mätta Bassbeaks väldiga aptit.",al={"varför raptorägg","varför mata gryfen med ägg","vad ska äggen användas till"}},{q="Var finns Razormaw-raptorerna?",a="Razormaw-raptorer håller till vid Raptor Ridge i nordost och Saltspray Glen i nordväst i Wetlands. Äventyrarna måste själva våga sig in i bona för att få tag på felfria ägg.",al={"var finns razormaw-raptorer","var hittar man razormaw-ägg","raptorernas platser i wetlands"}},{q="Varför måste äggen vara perfekta?",a="Howin kräver ägg utan sprickor eller skavanker för att maten ska vara helt färsk och ofördärvad. Då håller sig Bassbeak frisk och nöjd, i stället för att få dåliga rester.",al={"varför måste äggen vara perfekta","spruckna ägg trying times"}},{q="Vad planerar Howin att göra med Bassbeak?",a="Howin nämner att han har större planer för Bassbeak, men håller detaljerna i bakgrunden tills gryfen har fått mat och lugnat sig så pass att hon säkert kan lyfta trots hoten i regionen.",al={"vad är howins plan","vad planerar howin och bassbeak"}}},fp="12,140,26.252.0,19.298.0,25.150.0,16.139.0,32.153.0,36.146.0,35.109.0,43.133.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Shipping Label är en återfunnen fraktmarkering på en Supply Crate som tillhör Azeroth Commerce Authority. Den hänvisar kurirer till organisationens handelsnav vid Three Corners-korsningen i Redridge Mountains och introducerar resenärer till dess nätverk av självständiga transportörer.",h="Shipping Label är en återfunnen fraktmarkering på en Supply Crate som tillhör Azeroth Commerce Authority.",kw={"azeroth commerce authority","låda","leverans","merchant's favor","redridge mountains","shipping label","three corners"},ang={["faction:Alliance"]="Azeroth Commerce Authority verkar vid Three Corners-korsningen och förlitar sig på kringresande äventyrare i Alliansens södra områden för att återfinna gods på villovägar och säkra landvägarna för transport."},sec={{t="En leverans på villovägar",b="Den här skadade fraktsedeln sitter på en välfylld Supply Crate och markerar gods som tillhör Azeroth Commerce Authority. Den avsedda destinationen och mottagaren har rivits bort, men tydliga instruktioner säger att den som hittar godset ska återlämna det eller rapportera till myndighetens handelsutpost i Redridge Mountains. Bredvid den formella texten visar en enkel karta vägarna mot Three Corners-korsningen."},{t="Commerce Authoritys nav",b="Vid Three Corners-korsningen värvar representanter för Azeroth Commerce Authority aktivt resenärer som självständiga kurirer. I stället för att binda transportörer till strikta handelsavtal driver myndigheten ett informellt nätverk där äventyrare får Merchant's Favor i ersättning för att återfinna försvunnet gods och slutföra övergivna leveranser längs landsvägen."}},faq={{q="Vad är Shipping Label?",a="Shipping Label är ett sönderrivet dokument som hittas på sidan av en återfunnen Supply Crate. Mottagarens namn saknas, men etiketten visar att varorna tillhör Azeroth Commerce Authority och hänvisar upphittaren till deras nav vid Three Corners.",al={"vad är shipping label","uppdraget shipping label","trasig shipping label"}},{q="Vad är Azeroth Commerce Authority?",a="Azeroth Commerce Authority är ett företag som organiserar logistik, handel och frakt i regionen. De håller lokala handelsnav för att återfinna förlorade försändelser och anlitar kringresande kurirer utan långsiktiga avtal.",al={"vem är aca","azeroth commerce authority","vad är azeroth commerce authority"}},{q="Var ligger Azeroth Commerce Authoritys handelsnav?",a="Azeroth Commerce Authoritys handelsnav ligger vid Three Corners-korsningen i Redridge Mountains, strategiskt placerat längs vägarna som förbinder Elwynn Forest, Duskwood och Lakeshire.",al={"var ligger aca:s handelsnav","navet vid three corners","var lämnar jag in shipping label"}},{q="Vad är Merchant's Favor?",a="Merchant's Favor är en särskild sorts värdebevis eller kredit som Azeroth Commerce Authority ger till självständiga kurirer. Anslutna kurirer använder den för att köpa olika handelsvaror och logistiktjänster vid myndighetens stationer.",al={"vad är merchant's favor","merchant's favor","aca:s ersättning"}},{q="Hur blir du ansluten till Azeroth Commerce Authority?",a="För att bli ansluten krävs inga formella avtal, papper eller långsiktiga åtaganden. Azeroth Commerce Authority kräver bara att kurirer hjälper till att återlämna eller slutföra felriktade leveranser som de stöter på ute i världen.",al={"hur blir man ansluten till aca","gå med i aca","behöver jag ett avtal"}},{q="Vad händer med lådan efter att du lämnat in fraktsedeln?",a="Fraktsedeln får handelsnavets representanter att fråga om den fysiska låda som den satt på, eftersom det är viktigt för deras handelsverksamhet att få tillbaka tomma eller levererade fraktbehållare.",al={"vad händer med lådan","försvunnen låda","vill de ha lådan"}}},fp="14,206,16.350.0,28.327.0,27.216.0,39.192.0,58.165.0,25.189.0,65.208.0,53.185.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="En sönderriven fraktsedel på en nyligen påfylld fraktcontainer visar vägen till ett regionalt handelscentrum i The Barrens. Durotar Supply and Logistics förlitar sig på kringresande vandrare som kan återfinna försvunna lådor och lämna tillbaka papperen till deras postering väster om The Crossroads. När du lämnar tillbaka dem hålls viktiga leveranskedjor och handeln i centrala Kalimdor igång.",h="En sönderriven fraktsedel på en nyligen påfylld fraktcontainer visar vägen till ett regionalt handelscentrum...",kw={"låda","crossroads","durotar supply and logistics","shipping label","the barrens","handelsplats"},ang={["faction:Horde"]="Horde-äventyrare som färdas genom The Barrens stöter ofta på Durotar Supply and Logistics verksamhet och hjälper till att upprätthålla viktig handel och leveranser mellan Durotar och centrala Kalimdor."},sec={{t="En vilsegången fraktsedel",b="Det här sönderrivna dokumentet sitter på en nyligen påfylld lastlåda och innehåller logistikuppgifter från Durotar Supply and Logistics. Mottagarens namn har slitits bort under resans gång, men ursprungsrubriken visar tydligt vilket fraktbolag som verkar från Horde-territorier. En grovt skissad färdväg bredvid texten visar kurirer raka vägen till företagets uppställningsplats på de centrala slätterna."},{t="Handel vid gränsen",b="Meddelandet uppmanar resenärer att frakta vilsegångna containrar, skadade varor eller bevis på bärgning till handelsplatsen, som ligger rakt väster om The Crossroads. Durotar Supply and Logistics verkar i The Barrens karga vidder och är starkt beroende av självständiga fraktare och resenärer för att återfinna utspridd last. De lovar ersättning till alla som hjälper till att hålla regionens leveranser igång."}},faq={{q="Vad är Shipping Label?",a="Det är ett dokument som sitter på en fullastad låda och innehåller returinstruktioner för Durotar Supply and Logistics. Det visar vägen tillbaka till deras postering nära The Crossroads för försvunna eller tomma containrar.",al={"vad är shipping label","shipping label uppdrag","sönderriven fraktsedel"}},{q="Vart ska fraktsedeln lämnas?",a="Fraktsedeln visar kurirer till personalen på Durotar Supply and Logistics handelscentrum, som ligger rakt väster om The Crossroads i The Barrens.",al={"vart lämnar jag shipping label","vem vill ha shipping label","lämna in shipping label"}},{q="Vad är Durotar Supply and Logistics?",a="Durotar Supply and Logistics är ett kommersiellt fraktbolag som verkar i Durotar och The Barrens. De sköter godstransporter, insamling av lådor och logistiskt stöd i Horde-territorier.",al={"vad är durotar supply and logistics","durotar supply handelsplats"}},{q="Vem var försändelsen ursprungligen avsedd för?",a="Den avsedda mottagarens namn har slitits bort helt från fraktsedeln. Bara returinstruktionerna och företagets ursprungsuppgifter finns kvar på lådan.",al={"vem var lådan avsedd för","lådans mottagare"}},{q="Var ligger Durotar Supply and Logistics handelsplats?",a="Enligt anvisningarna och den grova kartan på fraktsedeln ligger handelsplatsen bekvämt nog rakt väster om bosättningen The Crossroads i The Barrens.",al={"var ligger handelsplatsen","durotar supply plats crossroads"}},{q="Ersätter Durotar Supply and Logistics resenärer för återlämnade lådor?",a="Ja, det tryckta meddelandet lovar uttryckligen att kurirer får ersättning för tid och arbete när de lämnar skadade försändelser, fraktsedlar eller tomma lådor vid handelsplatsen.",al={"betalar de för återlämnade lådor","durotar supply ersättning"}}},fp="14,255,18.294.0,17.312.0,27.184.0,36.111.0,37.170.0,45.123.0,64.93.0,76.116.0"}
P.entries["quest:98283"] = {n="Carnage",s="Carnage är ett uppdrag i Wetlands som Rethiel the Greenwarden ger i The Green Belt. Rethiel ber resenärer locka fram och döda Carnage, en vansinnig Razormaw-raptorhane vars pestframkallade raseri har rubbat regionens naturliga ordning.",h="Carnage är ett uppdrag i Wetlands som Rethiel the Greenwarden ger i The Green Belt.",kw={"carnage","loch modan","raptor ridge","razormaw","rethiel the greenwarden","rotclaw","the green belt","wetlands"},ang={["class:Druid"]="Druider delar Rethiels sorg över den rubbade naturliga balansen i Wetlands, där sjukdom har förvandlat rovdjur som Carnage till vettlösa skräckväsen.",["class:Hunter"]="Jägare förstår faran när en alfahanes naturliga instinkter går förlorade i pestframkallat raseri och den börjar jaga sina egna."},sec={{t="En rubbad balans",b="I Wetlands träskmarker har den naturliga ordningen börjat krackelera. Razormaw-raptorerna fyllde en gång en viktig ekologisk funktion och höll vildmarken fri från okontrollerad växtlighet. Nu har deras flockhierarki slagits sönder av den skräckinjagande alfahanen, ett blodtörstigt best känt enbart som Carnage. I stället för att leda flocken har Carnage spridit skräck bland de sina, slaktat urskillningslöst och kastat det lokala ekosystemet i kaos."},{t="Locka fram alfahanen",b="Rethiel the Greenwarden, som vakar över The Green Belt, tror att Carnage har fallit offer för den vidriga korruption som fortfarande plågar regionen. För att locka fram det rasande odjuret ur sitt gömställe måste resenärer samla in de sjuka Rotclaw-björnarnas illasinnade inälvor. Björnarna har vandrat ner från Loch Modan. Om man placerar det vidriga köttet i Carnages grotta under Raptor Ridge retas monstret till anfall, så att resenärerna kan göra slut på dess lidande."}},faq={{q="Vem är Carnage?",a="Carnage är den monstruösa alfahanen bland Wetlands Razormaw-raptorer. I stället för att leda flocken som vanligt har sjukdomen drivit odjuret till vansinne. Det lämnar bara slakt efter sig och skrämmer till och med sina egna raptorfränder.",al={"vem är carnage","carnage raptor","vad är carnage"}},{q="Vem ger uppdraget Carnage?",a="Uppdraget ges av Rethiel the Greenwarden, en väktare stationerad i Wetlands, i The Green Belt. Hen arbetar för att återställa regionens fördärvade naturliga balans.",al={"vem ger uppdraget carnage","var lämnar man in carnage","rethiel wetlands"}},{q="Varför måste Carnage dödas?",a="Rethiel vill att Carnage ska dö eftersom en onaturlig sjukdom har drivit odjuret till vansinne. Det har krossat Razormaw-raptorernas naturliga hierarki och ödelagt den lokala ekologin.",al={"varför döda carnage","varför vill rethiel att carnage ska dö"}},{q="Hur lockas Carnage fram?",a="Carnage lockas fram genom att man agnar grottan med sjuka björnars illasinnade kött och inälvor. Björnarna finns nedanför Raptor Ridge, åt nordost.",al={"hur kallar man fram carnage","hur lockar man fram carnage","var finns carnages grotta"}},{q="Vilka är de sjuka björnarna som Rethiel nämner?",a="De sjuka björnarna är Rotclaws som har vandrat ner från Loch Modan. Den kvardröjande korruptionen har drivit dem till vansinne. Deras fördärvade kött fungerar som effektivt bete för att locka fram den galna raptoralfan.",al={"vad är rotclaw-björnar","varifrån kommer de sjuka björnarna"}},{q="Vilken roll hade Razormaw-raptorerna ursprungligen i Wetlands?",a="Under normala omständigheter upprätthåller Razormaw-raptorerna den ekologiska balansen i Wetlands genom att hindra växt- och djurlivet från att breda ut sig okontrollerat. Carnages vansinne har rubbat denna viktiga funktion.",al={"vilken roll har razormaw","varför är raptorer viktiga i wetlands"}}},fp="7,161,16.216.0,16.305.0,15.159.0,28.147.0,30.161.0,25.128.0,49.162.0,68.187.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting skickar utövare av den magiska konsten till Shen'dar Village för att lära sig skapa specialutrustning för vildmarken. Genom att tala med Nasalanna Windsinger kan erfarna förtrollare lära sig att tillverka en Enchanted Lute som underhåller och stärker deras följeslagare vid lägerelden.",h="Camping 101: Enchanting skickar utövare av den magiska konsten till Shen'dar Village för att lära sig skapa...",kw={"lägereld","camping","camping 101","enchanted lute","förtrollning","luta","nasalanna windsinger","shen'dar village"},sec={{t="Hemmets bekvämligheter",b="Livet på vägarna kräver mer än vässade klingor och ransoner; vila och gott mod är avgörande för att klara långa expeditioner. Förtrollare bidrar med unika magiska bekvämligheter i lägerlivet och använder sin kunskap om omgivande magi för att muntra upp resenärer under vilan. I vildmarksläger över hela Azeroth ser en förtrollare till att utmattade äventyrare kan återfå sin styrka och sitt mod innan de återvänder till farliga stigar."},{t="Sången från Shen'dar",b="För att lära sig lägrets subtila skapandemagi hänvisas blivande förtrollare till Shen'dar Village. Där instruerar Nasalanna Windsinger skickliga besvärjare i att konstruera en Enchanted Lute. Hantverkare måste först visa sin hängivenhet och skicklighet i förtrollning innan Nasalanna delar med sig av hemligheterna bakom ett instrument som kan väva läkande melodier under stjärnorna."}},faq={{q="Vem är Nasalanna Windsinger?",a="Nasalanna Windsinger är en instruktör som bor i Shen'dar Village. Hon lär skickliga utövare att tillverka särskilda yrkesföremål för vildmarksläger, närmare bestämt Enchanted Lute för förtrollare som visar sin skicklighet.",al={"vem lär ut enchanted lute","vem är nasalanna windsinger","var finns nasalanna windsinger"}},{q="Var ligger Shen'dar Village?",a="Shen'dar Village är bosättningen där Nasalanna Windsinger bor. Äventyrare som vill lära sig att tillverka campingutrustning som Enchanted Lute reser dit när de har utvecklat sina grundläggande färdigheter.",al={"var ligger shendar village","hur hittar man shendar village"}},{q="Vad är Enchanted Lute?",a="Enchanted Lute är ett magiskt campinginstrument som tillverkas av förtrollare. Det underhåller och stärker moralen under vilan vid lägerelden, så att resenärer kan samla mod och förbereda sig på vildmarkens utmaningar.",al={"vad gör enchanted lute","varför tillverka enchanted lute","campingluta"}},{q="Vilka krav gäller för att lära sig receptet?",a="Innan Nasalanna Windsinger lär dig att tillverka en Enchanted Lute måste du först bevisa din skicklighet i förtrollningens magiska konst. Bara erfarna utövare får förtroendet att skapa dessa praktiska lägerförtrollningar.",al={"krav för camping 101 enchanting","när kan jag lära mig enchanted lute"}},{q="Varför är förtrollare värdefulla vid lägerplatser i vildmarken?",a="Förtrollare bidrar med subtil nytta och magiska bekvämligheter i avlägsna läger där vanliga förnödenheter ofta inte räcker till. Genom att förse vanliga campingredskap med magiska egenskaper hjälper de äventyrare att återhämta sig, få underhållning och förbereda sig på oväntade faror längs vägen.",al={"varför vill campare ha förtrollare","fördelar med förtrollare vid camping"}},{q="Kan andra yrken tillverka campingföremål?",a="Ja, hantverkare och samlare inom olika yrken lär sig att skapa särskilda redskap för lägerplatser. För förtrollare består detta specialhantverk av Enchanted Lute, som Nasalanna Windsinger lär ut i Shen'dar Village.",al={"finns det andra campingföremål","andra yrkens campinghantverk"}}},fp="23,170,22.284.0,20.330.0,28.190.0,26.185.0,26.202.0,46.172.0,52.188.0,42.179.0"}
P.entries["quest:98291"] = {n="Death to the Dragonmaw",s="Vid Dragonmaw Retreat ber Howin Kindfeather dig att glesa ut leden i Dragonmaw. Han hoppas kunna nå Grim Batol och återta det åt Wildhammers, eller lära sig mer om det.",h="Vid Dragonmaw Retreat ber Howin Kindfeather dig att glesa ut leden i Dragonmaw.",kw={"dragonmaw infiltrators","orcher från dragonmaw","dragonmaw reclaimers","dragonmaw retreat","dragonmaw soulbinders","grim batol","howin kindfeather","wildhammers"},sec={{t="Dragonmaws reträtt",b="Orcher från Dragonmaw har samlats längs reträttvägen, där röda drakar tidigare drev dem på flykten. Howin behöver få deras antal minskat innan han kan närma sig Grim Batol. Han visar dig österut längs vägen för att hitta dem."}},faq={{q="Vem är Howin Kindfeather?",a="Howin Kindfeather hoppas kunna ta sig in i Grim Batol igen och återta det åt Wildhammers, eller åtminstone lära sig mer om det.",al={"vem är howin","personen howin"}},{q="Varför vill Howin ha hjälp?",a="Howin säger att orcher från Dragonmaw marscherar genom Dragonmaw Retreat. Han behöver få deras antal minskat innan han kan närma sig Grim Batol.",al={"varför hjälpa howin","vad behöver howin"}},{q="Var finns orcherna från Dragonmaw?",a="Orcherna från Dragonmaw finns längs Dragonmaw Retreat. Howin visar dig österut längs vägen för att hitta dem.",al={"var finns dragonmaw","dragonmaws plats"}},{q="Vilka ska jag leta efter?",a="Howin nämner Dragonmaw Reclaimers, Dragonmaw Soulbinders och Dragonmaw Infiltrators.",al={"vilka orcher","typer av dragonmaw"}},{q="Vad hände vid Dragonmaw Retreat?",a="Röda drakar drev tidigare orcherna från Dragonmaw på flykten vid Dragonmaw Retreat.",al={"dragonmaws historia","varför reträtt"}}},fp="22,166,17.202.0,25.120.0,25.131.0,29.98.0,22.84.0,35.66.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament är ett uppdrag för Alliansen i Wetlands där äventyrare ska lägga beslag på vapengömmor från Dragonmaw-klanen vid Dragonmaw Retreat. Genom att samla in trettio buntar med vapen hindrar spelarna de fientliga orcherna från att utrusta fler soldater inför framtida räder. Den beslagtagna utrustningen lämnas till Captain Stoutfist i Menethil Keep för att skydda regionens viktiga hamn.",h="Forced Disarmament är ett uppdrag för Alliansen i Wetlands där äventyrare ska lägga beslag på vapengömmor...",kw={"captain stoutfist","dragonmaw armaments","dragonmaw-klanen","dragonmaw retreat","forced disarmament","menethil harbor","menethil keep","wetlands"},ang={["faction:Alliance"]="Alliansens styrkor är beroende av Menethil Harbor som en viktig livlina över Great Sea, vilket gör det till ett akut strategiskt behov att avväpna fientliga klaner i närheten.",["race:Dwarf"]="Dvärgiska försvarare från Ironforge bemannar garnisonen i Menethil Keep och strävar efter att säkra Khaz Modans gränser mot gamla fiender som slagit rot i träskmarkerna.",["race:Orc"]="Dragonmaw är en splittrad och obotfärdig kvarleva från Old Horde, vars våldsamma krigshets isolerar dem från den nya Horde-ledningen i Kalimdor."},sec={{t="Ett vapenförråd i träskmarkerna",b="I Wetlands träskmarker har den fientliga Dragonmaw-klanen börjat samla på sig ett oroväckande stort vapenförråd i Dragonmaw Retreat. Om förrådet lämnas orört kan de fredlösa orcherna utrusta nya skaror krigare och inleda förödande räder mot närliggande bosättningar. Genom att avväpna deras läger slår man direkt mot deras försörjningsförmåga och hejdar varje planerad offensiv innan deras krigshärar hinner mobiliseras och gå ut i strid."},{t="Att säkra kusthamnen",b="Menethil Harbor är den främsta porten som förbinder Khaz Modan och Stormwind med havet, vilket gör all militär upprustning i närheten till ett allvarligt hot. Captain Stoutfist samordnar försvaret från Menethil Keep och håller noggrann uppsikt över de fientliga klanerna och bestarna som närmar sig staden. Genom att återta trettio uppsättningar Dragonmaw-vapen berövar man orcherna nödvändig ammunition och ger samtidigt dvärgarnas garnison viktig information om fiendens beredskap."}},faq={{q="Vem är Captain Stoutfist?",a="Captain Stoutfist är en dvärgisk officer som är stationerad i Menethil Keep och ansvarar för försvaret av Menethil Harbor och de omgivande Wetlands. Stoutfist står under ständig press från fientliga bestar, Dark Iron-sabotörer och Dragonmaw-klanen och leder aktivt soldater och äventyrare i arbetet med att slå ner närliggande hot innan hamnens viktiga försörjningslinjer och anläggningar blir översvämmade av fiender.",al={"stoutfist","vem är stoutfist","kaptenen i menethil keep"}},{q="Varför måste Dragonmaw avväpnas?",a="Dragonmaw-klanen samlar aktivt vapen i sitt tillhåll för att utrusta nya kämpar inför strid. Om de tillåts samla på sig ammunition utan motstånd kan deras krigshärar övermanna Alliansens lokala försvar och hota Menethil Harbor. Genom att beslagta trettio buntar med vapen hindrar man direkt deras logistiska förberedelser och hindrar fler orksoldater från att gå ut i strid.",al={"varför ta dragonmaws vapen","syftet med dragonmaw armaments","avväpna dragonmaw"}},{q="Var ligger Dragonmaw Retreat?",a="Dragonmaw Retreat är ett läger som Dragonmaw-orcherna har upprättat i Wetlands, österut mot bergen bortom Menethil Harbor. Klanen använder denna avskilda utpost för att samla styrkor, lagra vapen och förbereda attacker mot resande i träskmarkerna. Äventyrare måste ta sig in i lägrets hjärta för att återta vapnen de samlat på sig.",al={"dragonmaw retreats läge","var ligger dragonmaw retreat","dragonmaw retreat i wetlands"}},{q="Vad är Dragonmaw Armaments?",a="Dragonmaw Armaments är förråd med stridsutrustning, klingor och utrustning som Dragonmaw-klanen har smitt eller stulit för att förse sina krigare. Dessa vapen utgör klanens omedelbara militära kapacitet i regionen. Captain Stoutfist begär att trettio buntar av denna ammunition beslagtas och förs tillbaka till Menethil Keep för undersökning och bortskaffning.",al={"dragonmaw-vapen","vad är vapenutrustning","dragonmaw-utrustning"}},{q="Är Dragonmaw-klanen en del av Horde år tjugofem efter den mörka porten?",a="Nej, Dragonmaw-klanen i Wetlands verkar som en självständig, fientlig fraktion som inte lyder under Warchief Thrall. Orcherna är fortfarande trogna sina gamla seder efter det andra kriget, hyser ett djupt hat mot Alliansen och avvisar alla fredliga inviter. Därför betraktar både Alliansens försvarare och självständiga resande dem som dödliga fiender.",al={"tillhör dragonmaw horde","dragonmaw-klanens fraktion","dragonmaw och thrall"}},{q="Varför oroar sig Menethil Keep för Dragonmaw?",a="Menethil Keep är den administrativa och militära fästning som skyddar Menethil Harbor, Alliansens främsta sjöfartsknutpunkt i Khaz Modan. Eftersom träskmarkerna runt hamnen plågas av träskbestar och aggressiva orcher kan Captain Stoutfist inte låta ett tungt beväpnat läger som Dragonmaw Retreat växa fram så nära rikets kajer och handelsvägar.",al={"dragonmaw-hotet mot menethil keep","varför stoutfist bryr sig","försvaret av menethil harbor"}}},fp="18,271,24.276.0,25.378.0,25.349.0,41.274.0,35.290.0,29.311.0,50.325.0,50.342.0"}
P.entries["quest:98297"] = {n="Stopping the Cycle",s="Vid Dragonmaw Gates försöker häxmästare förslava en röd drakvarelse. Howin Kindfeather återvänder från en provflygning med oroande nyheter, och Wildhammer tänker inte låta det hända igen.",h="Vid Dragonmaw Gates försöker häxmästare förslava en röd drakvarelse.",kw={"dragonmaw","dragonmaw gates","howin kindfeather","röd drakvarelse","bryta kretsloppet","kuvad drakvarelse","häxmästare","wildhammer"},sec={{t="Vid portarna",b="Howin Kindfeather ber dig att möta den kuvade drakvarelsen vid Dragonmaw Gates. Döda först häxmästarna som håller den nere. Det borde befria den. Gör sedan slut på drakvarelsens lidande. Howin räknar med att du tar med dig vänner, för Wildhammer tänker inte låta Dragonmaw stå i vägen för dem."}},faq={{q="Vem ber om hjälp?",a="Howin Kindfeather ber dig att hindra Dragonmaw från att förslava en röd drakvarelse.",al={"vem vill detta","howins uppgift"}},{q="Vad gör Dragonmaw?",a="En grupp häxmästare från Dragonmaw håller en röd drakvarelse nere och försöker förslava den.",al={"vad gör dragonmaw","varför är drakvarelsen kuvad"}},{q="Var finns drakvarelsen?",a="Den kuvade drakvarelsen finns vid Dragonmaw Gates.",al={"drakvarelsens plats","var finns den kuvade drakvarelsen"}},{q="Vad ber Howin mig att göra?",a="Howin ber dig att döda häxmästarna som håller drakvarelsen nere och sedan göra slut på dess lidande.",al={"vad ska jag göra","stoppa kretsloppet"}},{q="Varför säger Howin att Wildhammer inte kan tillåta detta?",a="Howin säger att Dragonmaw håller på att förslava en röd drakvarelse och insisterar på att Wildhammer inte tänker låta dem stå i vägen.",al={"varför inte igen","wildhammers skäl"}}},fp="18,188,12.291.0,23.82.0,29.89.0,25.50.0,29.96.0,52.122.0"}
P.entries["quest:98298"] = {n="Arugal's Folly",s="Arugal's Folly är ett uppdrag från Forsaken i Silverpine Forest där Dalar Dawnweaver undersöker worgenflockarnas verkliga ursprung nära The Greymane Wall. Genom att analysera insamlade worgenlämningar vill Dalar bevisa att Archmage Arugal var en bedragare som bara band varelserna, snarare än att framkalla deras förbannelse.",h="Arugal's Folly är ett uppdrag från Forsaken i Silverpine Forest där Dalar Dawnweaver undersöker...",kw={"arugal","arugal's folly","dalar dawnweaver","the greymane wall","silverpine forest","the sepulcher","worgenbitar","worgenförbannelse"},ang={["class:Mage"]="De som utövar arcane-magi kan uppskatta Dalars analytiska nedmontering av Arugals så kallade magiska förbannelse och se skillnaden mellan bindande förtrollningar och smittsamma sjukdomar.",["faction:Horde"]="Hordens äventyrare som hjälper Dalar Dawnweaver bidrar till att skydda Silverpine Forest från både vilda rovdjur på härjningståg och de närliggande mänskliga bosättningar som dukar under för sjukdomen.",["race:Undead"]="För Forsaken vid The Sepulcher är det avgörande att förstå worgenutbrottets verkliga natur i Silverpine för att skydda Lordaeron från okontrollerbara vilda hot."},sec={{t="Avslöja ärkemagikern",b="Forsaken-magikern Dalar Dawnweaver är stationerad vid The Sepulcher i Silverpine Forest och vill rasera rivalen Archmage Arugals mystik. Efter att ha undersökt förtrollade bojor drar Dalar slutsatsen att Arugal saknade den råa kraft som krävdes för att frambringa eller skapa worgenflockarna som terroriserar trakten. Arugal kunde bara använda enklare förtrollningar för att binda bestarna en kort stund, så förbannelsens verkliga mekanik och ursprung förblir ett mysterium."},{t="Bestarnas intrång",b="För att hitta konkreta bevis skickar Dalar äventyrare söderut till The Greymane Walls imponerande befästningar. I vildmarken runt muren har vilda worgen börjat angripa och smitta människor i närheten. Genom att fälla de glupska varelserna och hämta vävnadsprover ger utredarna Dalar fysiska prover som han kan analysera för att förstå sjukdomens biologiska och magiska natur."},{t="En bitter upprättelse",b="När Dalar undersöker de insamlade worgenlämningarna utropar han skadeglatt sin seger över Arugals akademiska rykte och bekräftar att ärkemagikern inte hade något med sjukdomens ursprung att göra. Men avslöjandet får en dyster följd för Forsaken: om Arugal aldrig skapade förbannelsen är de påstådda botemedel och motåtgärder han tog fram helt värdelösa, och worgenutbrottets verkliga gåta förblir olöst."}},faq={{q="Vem ger uppdraget Arugal's Folly?",a="Uppdraget ges och avslutas hos Dalar Dawnweaver, en arcane-forskare och Forsaken-magiker stationerad vid The Sepulcher i Silverpine Forest.",al={"vem ger arugal's folly","var lämnar jag in arugal's folly","uppdragsgivare arugal's folly"}},{q="Varför anser Dalar Dawnweaver att Arugal är en bedragare?",a="Dalar Dawnweaver drar slutsatsen att Archmage Arugal är en arrogant bedragare. Dalar hävdar att Arugal knappt hade tillräcklig magisk skicklighet för att tillfälligt binda worgen, snarare än att skapa dem eller ge dem deras ursprung. Därmed avslöjar han den så kallade ”Curse of Arugal” som en bluff.",al={"vad tycker dalar om arugal","skapade arugal worgen","arugal bedragare"}},{q="Var hittar du worgenbitar åt Dalar?",a="För att slutföra uppdraget reser äventyrarna söderut genom Silverpine Forest mot The Greymane Wall, där vilda worgen stryker omkring nära traktens mänskliga bosättningar. När bestarna dödas får man worgenbitarna som Dalar behöver för sin undersökning.",al={"var finns worgenbitarna","worgen vid greymane wall","vart ska jag gå i arugal's folly"}},{q="Hittar Dalar ett botemedel mot worgenförbannelsen?",a="Inget botemedel upptäcks här. Eftersom Dalar kommer fram till att Arugal inte skapade worgensjukdomen är alla botemedel eller motbesvärjelser som Arugal kokade ihop helt värdelösa. Forsaken måste söka någon annanstans efter en verklig lösning.",al={"kan worgenförbannelsen botas","fungerar arugals botemedel","finns det ett botemedel mot worgen"}},{q="Hur sprids worgensjukdomen nära The Greymane Wall?",a="Dalar noterar att worgensjukdomen verkar spridas direkt till människor i närheten av The Greymane Wall genom fysisk kontakt och bett, snarare än genom någon övergripande magisk ritual eller besvärjelse från Arugal.",al={"hur sprids förbannelsen","worgen smittar människor","vem blir smittad"}},{q="Vad drar Dalar för slutsats efter att ha undersökt worgenbitarna?",a="Undersökningen av de anatomiska delarna från dödade worgen bevisar för Dalar att deras förbannelse inte har något med Arugals trolldom att göra. Den bekräftar hans rivals magiska inkompetens, men också att worgenförbannelsen fortfarande är ett aktivt, oförklarat hot utan fungerande motgift.",al={"vad lär sig dalar av bitarna","slutsats arugal's folly","avslöjandet i arugal's folly"}}},fp="14,206,21.341.0,21.318.0,20.332.1,35.129.0,50.172.0,44.159.0,44.181.0,62.182.0,58.209.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="Stop the Spread är ett uppdrag i Silverpine Forest som handlar om att begränsa worgenförbannelsen med koppling till ärkemagikern Arugal. Medan forskare söker ett sätt att hejda smittan beordras förebyggande åtgärder mot levande mänskliga flyktingar vid The Greymane Wall, så att de inte förvandlas till Arugals tjänare.",h="Stop the Spread är ett uppdrag i Silverpine Forest som handlar om att begränsa worgenförbannelsen med...",kw={"arugal","förbannelse","forsaken","the greymane wall","flyktingar","silverpine","himmelsburna","stop the spread","worgen"},ang={["race:Human"]="Forsaken-forskare ser de oinfekterade mänskliga flyktingarna som kurar ihop sig vid The Greymane Walls förseglade portar som perfekta smittspridare för Arugals förbannelse.",["race:Skyborne"]="Äventyrare från himlen varnas uttryckligen för att bli bitna när de utför de dystra begränsningsorderna nära The Greymane Wall.",["race:Undead"]="Forsaken verkar vara unikt immuna mot worgensmittan, vilket gör begränsningsinsatser möjliga utan infektionsrisk för de odöda styrkorna."},sec={{t="Smittan i Silverpine",b="I Silverpine Forest sprids worgenplågan av den avfällige ärkemagikern Arugal. De exakta metoderna och mekanismerna bakom detta vilda tillstånd är fortfarande till stor del okända, men faran för området är obestridlig. Forskare arbetar aktivt med att förstå magins natur, men deras omedelbara fokus är att hindra Arugal från att samla en ostoppbar här av vilda anhängare."},{t="Begränsning vid muren",b="Forsaken-utredare har sett att deras odöda fysiologi gör dem immuna mot worgeninfektionen. Levande människor har däremot inget sådant naturligt försvar. Vid den södra gränsen har ett desperat läger med mänskliga flyktingar samlats kring The Greymane Walls låsta portar. Av rädsla för att dessa försvarslösa överlevande ska bli bitna och förvandlas till Arugals lojala trälar har förebyggande och skoningslösa begränsningsorder utfärdats, för att rensa bort folksamlingen innan smittan får tag i dem."}},faq={{q="Vad handlar uppdraget Stop the Spread om?",a="Stop the Spread är ett uppdrag som går ut på att begränsa worgenförbannelsen som härjar i Silverpine Forest. För att hindra ärkemagikern Arugal från att få fler tjänare skickas styrkor ut för att undanröja mänskliga flyktingar nära The Greymane Wall innan de dukar under för smittan.",al={"vad är stop the spread","stop the spread uppdragslore"}},{q="Vem bär ansvaret för worgen i Silverpine?",a="Ärkemagikern Arugal hålls ansvarig för worgen i Silverpine Forest, vare sig de är resultatet av hans avsiktliga planer eller oförutsedda följder av hans magi. Hans växande flock hotar hela regionen.",al={"vem sprider worgenförbannelsen","arugals koppling till worgen"}},{q="Kan Forsaken smittas av worgenförbannelsen?",a="Enligt lokala Forsaken-forskares rön kan worgenförbannelsen inte smitta de odöda. Denna immunitet gör att Forsaken-agenter kan bekämpa hotet utan risk att förvandlas till bestialiska tjänare åt Arugal.",al={"kan forsaken bli worgen","är odöda immuna mot worgen"}},{q="Varför är mänskliga flyktingar vid The Greymane Wall måltavlor?",a="En stor grupp mänskliga flyktingar har samlats utanför The Greymane Walls förseglade portar. Eftersom levande människor är mottagliga för Arugals förbannelse anses de utgöra ett överhängande hot, då de kan öka worgenhordens antal.",al={"varför döda flyktingar","flyktingar vid greymane wall"}},{q="Hur sprids worgensmittan?",a="Det är känt att worgenförbannelsen kan överföras genom bett, men de exakta magiska och biologiska mekanismerna bakom smittspridningen undersöks fortfarande av forskare i Silverpine Forest.",al={"hur sprids worgen","worgenförbannelsens smittspridning"}},{q="Finns det något sätt att hejda eller bota worgenförbannelsen?",a="För närvarande finns det inget känt botemedel mot worgensmittan. Forskare försöker hitta ett sätt att hejda förbannelsen, men deras omedelbara prioritet är fortfarande kraftfulla begränsningsåtgärder.",al={"kan worgenförbannelsen botas","botemedel mot worgen"}}},fp="15,223,25.314.0,23.402.1,40.178.0,48.169.0,40.155.0,59.166.0,38.144.0,48.129.0"}
P.entries["quest:983"] = {n="Buzzbox 827",s="Buzzbox 827 är den första i en experimentell kommunikationskedja som gnomen Wizbang Cranktoggle byggt längs Darkshores kust. De märkliga mekaniska apparaterna drabbas ofta av haverier och bygger på en excentrisk konstruktion som använder delar från det lokala djurlivet vid fältreparationer. När den tysta maskinen återställs kan Wizbang testa sitt långdistansnät för röstsändningar direkt från Auberdine.",h="Buzzbox 827 är den första i en experimentell kommunikationskedja som gnomen Wizbang Cranktoggle byggt längs...",kw={"auberdine","buzzbox 827","crawler legs","darkshore","gnomisk ingenjörskonst","reef crawler","tide crawler","wizbang cranktoggle"},ang={["profession:Engineering"]="Att använda organiskt kitin och leddjurslemmar i stället för smidda kugghjul av mässing är typiskt för gnomisk improvisationsförmåga: hållbarhet byts mot lättillgängliga material från närområdet.",["race:Gnome"]="Wizbangs apparat står för klassisk gnomisk ambition och försöker föra teknisk uppkoppling till ett forntida, otämjt land som aldrig har sett en telefon eller radio.",["race:NightElf"]="De skramlande, rykande Buzzboxarna är en bisarr skamfläck vid Kalimdors heliga, dystra stränder, men nattalverna i Auberdine tolererar uppfinnarens experiment."},sec={{t="Gnomisk uppfinningsrikedom vid forntida stränder",b="Under ett besök i Auberdine ville den excentriske gnomiske ingenjören Wizbang Cranktoggle överbrygga de långa avstånden längs den vilda kusten med en serie långdistansreläer för ljudöverföring, kallade Buzzboxes. De här spakförsedda apparaterna är utformade för att överföra röster över långa avstånd och står i skarp kontrast till Darkshores forntida ruiner och dystra skogar. Men likt många ambitiösa gnomiska uppfinningar lider de av kronisk instabilitet och kräver nästan ständig skötsel för att hålla kugghjulen i gång."},{t="Ekologiskt underhåll",b="I stället för att släpa förädlade järnkugghjul och kopparstift genom vildmarken valde Wizbang en okonventionell lösning: han byggde varje Buzzbox så att den kunde servas med delar från närliggande inhemska djur. Buzzbox 827, placerad strax söder om Auberdine längs den dimmiga strandlinjen, konstruerades för att fungera med de kraftiga, ledade benen från lokala tidvatten- och revkrypare. När benen läggs i mottagarfacket sätter maskinen ihop sig själv och vaknar till liv igen, så att Wizbangs avlägsna röst hörs ur högtalarna."}},faq={{q="Vad är en Buzzbox?",a="En Buzzbox är en långdistansmaskin för röstkommunikation som uppfunnits av gnomen Wizbang Cranktoggle. Den är utrustad med spakar och ett inre maskineri och utformad för att överföra röster över Darkshores otämjda vidder, så att folk kan tala med varandra över flera mil.",al={"vad gör en buzzbox","buzzboxens syfte","gnomisk låda darkshore"}},{q="Varför behöver en metallmaskin krabbben för att fungera?",a="Wizbang konstruerade med flit varje Buzzbox för att använda organiska delar från det omgivande djurlivet som provisoriska reservdelar. Genom att placera Buzzbox 827 nära stranden där krypare lever såg han till att resande kunde utföra akuta mekaniska reparationer med kitinösa lemmar i stället för sällsynt bearbetad metall.",al={"varför crawler legs","reparation med crawler leg","varför mata in ben"}},{q="Var finns Buzzbox 827?",a="Buzzbox 827 står längs Darkshores strandlinje, bara en kort vandring söder om kustbosättningen Auberdine.",al={"buzzbox 827 plats","var finns buzzbox 827","hitta buzzbox 827"}},{q="Vem är Wizbang Cranktoggle?",a="Wizbang Cranktoggle är en gnomisk uppfinnare som bor på övervåningen i värdshuset i Auberdine. Ambitiös och företagsam försöker han bygga ett sammankopplat kommunikationsnät över Darkshore, trots att hans prototyper ständigt krånglar.",al={"wizbang cranktoggle","vem byggde buzzbox","gnom i auberdine"}},{q="Var hittar jag Crawler Legs till reparationen?",a="Crawler Legs kan samlas in från Pygmy Tide Crawlers och Young Reef Crawlers som kilar omkring i sanden och det grunda vattnet längs Darkshores strand, strax söder om Auberdine.",al={"crawler leg plats","hur får man crawler legs","pygmy tide crawler"}},{q="Vad händer när Buzzbox 827 har reparerats?",a="När Crawler Legs matats in i facket bearbetar maskinen dem på plats, börjar surra igen och förmedlar Wizbangs röst från Auberdine. Han är nöjd med resultatet och ber dig genast resa längre längs kusten för att reparera nästa enhet i kedjan, Buzzbox 411.",al={"efter buzzbox 827","nästa del av buzzbox-uppdraget","buzzbox 827 klar"}}},fx={aa80bf26={q="Varför vill Wizbang Cranktoggle att Buzzbox 827 repareras?",a="Wizbang Cranktoggle testar sin senaste uppfinning: ett experimentellt kommunikationsnät över Darkshore som låter folk tala med varandra på långt håll. Tyvärr kräver hans buzzboxar ständigt underhåll och går ofta sönder. Att få Buzzbox 827 att fungera är första steget mot att bevisa att nätverket faktiskt fungerar.",al={"wizbang cranktoggles motiv","varför laga buzzbox 827","varför vill wizbang att detta görs"}},["2c1df07a"]={q="Vad används Crawler Legs till?",a="Wizbang konstruerade varje buzzbox så att den använder delar från det inhemska djurlivet i närheten. Buzzbox 827 behöver särskilt sex Crawler Legs för att ersätta slitna eller trasiga mekaniska delar i hållaren. När de satts in mal och passar enhetens inre kugghjul in benen på plats, så att ström och överföring återställs.",al={"vad används crawler legs till","crawler leg till buzzbox","varför crawler legs"}}},fp="11,237,36.339.0,22.404.0,18.189.0,47.198.0,29.67.0,27.169.0,45.165.0,42.226.1"}
P.entries["quest:98310"] = {n="Gleaning Our Future",s="Prospector Whelgar ser ett sätt att lära sig mer av Goaz Stone. Fyra större golemer bär namn som motsvarar dess saknade delar.",h="Prospector Whelgar ser ett sätt att lära sig mer av Goaz Stone.",kw={"ados","gleaning our future","goaz stone","golemhjärtan","golm","inskrifter","modr","neru","prospector whelgar","wetlands"},sec={{t="Fyra inskrifter",b="Du har hittat saknade delar av Goaz Stone. Prospector Whelgar pekar ut fyra större golemer vid namn Ados, Modr, Golm och Neru. Han ber dig att använda stenen nära var och en och sedan ta med deras hjärtan tillbaka. Han hoppas att de ska avslöja fler av dess tecken."},{t="Svaga ord",b="När Prospector Whelgar för hjärtana nära Goaz Stone skimrar ny skrift fram: ”Curse of Flesh... de kommer att misslyckas.” Han kan inte tyda vad orden betyder. Han vill ta stenen till en säker plats för vidare studier."}},faq={{q="Vad vill Whelgar att jag ska ta med tillbaka?",a="Prospector Whelgar ber dig att använda Goaz Stone nära Ados, Modr, Golm och Neru och sedan ta med deras hjärtan tillbaka.",al={"vad vill whelgar ha","golemhjärtan","ta med hjärtan tillbaka"}},{q="Var finns de fyra golemerna?",a="Ados finns vid Dragonmaw Gates nära Grim Batol. Modr finns strax utanför Dun Modr i norr. Golm finns under Grim Batol, öster om Dun Algaz. Neru finns bakom Direforge Hill i nordost.",al={"var finns ados modr golm neru","golemernas platser","var finns golemerna"}},{q="Varför vill Whelgar ha golemhjärtana?",a="Golemerna bär inskrifter som motsvarar saknade delar av Goaz Stone. Whelgar hoppas att deras hjärtan ska avslöja fler av dess tecken.",al={"varför hjärtan","vad är hjärtana till för","delar av goaz stone"}},{q="Vad tror Whelgar om golemerna?",a="Whelgar misstänker att konstruktionerna kommer att vara svårare att besegra än väktaren.",al={"är golemer svåra","whelgars varning","golemernas styrka"}}},fp="19,125,17.250.0,11.239.1,40.112.0,26.188.0,39.134.0,38.64.0"}
P.entries["quest:98313"] = {n="For Further Study",s="Historian Karnik väntar på ett paket i Ironforge, kopplat till något episkt. Det som hittills har setts gör vidare studier värda mödan.",h="Historian Karnik väntar på ett paket i Ironforge, kopplat till något episkt.",kw={"för vidare studier","hall of explorers","historian karnik","ironforge","bibliotek","whelgar relic package"},sec={{t="Karniks bibliotek",b="Du bär med dig Whelgar Relic Package till Historian Karnik i Hall of Explorers. Han brukar sitta längst in i biblioteket och läsa."}},faq={{q="Vem väntar på paketet?",a="Historian Karnik väntar på Whelgar Relic Package i Hall of Explorers i Ironforge.",al={"vem får det","paket till vem"}},{q="Var hittar jag Karnik?",a="Historian Karnik brukar sitta och läsa längst in i biblioteket i Hall of Explorers i Ironforge.",al={"var är karnik","karniks plats"}},{q="Vilket paket bär jag på?",a="Du bär med dig Whelgar Relic Package till Historian Karnik.",al={"vilket paket","relikpaket"}},{q="Varför behöver detta studeras vidare?",a="Saken beskrivs som episk, och det som hittills har setts får vidare studier att verka värda mödan. Inga fler detaljer ges.",al={"varför studera det","vad är så märkvärdigt"}}},fp="17,129,16.139.0,31.83.0,24.96.0,27.64.0,33.123.0"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="Secure the Mountain är ett uppdrag för Alliansen om hur ett plötsligt stort antal wendigos har tagit över The Grizzled Den i Dun Morogh. Äventyrare skickas in i den angripna grottan för att hitta en överentusiastisk dvärgspanare vid namn Cornelius och hämta en viktig rapport åt Whitebeard.",h="Secure the Mountain är ett uppdrag för Alliansen om hur ett plötsligt stort antal wendigos har tagit över The...",kw={"cornelius","dun morogh","the grizzled den","bergsbestigare","secure the mountain","troll","wendigo","whitebeard"},ang={["faction:Alliance"]="Det är viktigt att se till att Whitebeard får underrättelserapporterna, så att Alliansens styrkor kan upprätthålla gränssäkerheten mot de inhemska hoten i bergen.",["race:Dwarf"]="När grottor som The Grizzled Den återtas skyddas dvärgarnas bergsbestigare och resenärer från aggressiva wendigos som tränger in på Dun Moroghs vägar."},sec={{t="En grotta översvämmad av wendigos",b="Dvärgspanare som bevakar de iskalla bergssluttningarna har problem från två håll. Utöver det ständiga hotet från Frostmane-troll har de lokala wendigosarna börjat föröka sig snabbt. De lämnar sina vanliga, ensliga hålor och trängs i The Grizzled Den norrut. De här vildsinta bestarna gör färder genom bergsklipporna farliga för både patruller och kurirer."},{t="Dumdristigt mod",b="En spanare vid namn Cornelius rusade rakt in i The Grizzled Den för att hämta en viktig rapport som skulle till Whitebeard. Hans impulsiva mod lämnade hans partner strandsatt utanför, på jakt efter dugliga äventyrare som vågar ta sig in i den besttäta grottan, leta reda på den dumdristiga dvärgen och minska antalet våldsamma wendigos."}},faq={{q="Vem är Cornelius?",a="Cornelius är en spanare eller bergsbestigare som arbetar med uppdragsgivaren. Drivna av dumdristigt mod rusade han rakt in i The Grizzled Den, som kryllar av wendigos, och lämnade sin partner utanför i väntan på hjälp med att hitta honom och hämta Whitebeards rapport.",al={"vem är cornelius","dvärgen cornelius","var är cornelius"}},{q="Vad är The Grizzled Den?",a="The Grizzled Den är en grotta norr om bergsbestigarnas utpost. Wendigos brukar hålla sig i avlägsna berghålor, men på senare tid har de tagit över grottan i ovanligt stort antal.",al={"vad är grizzled den","var finns wendigos","wendigogrotta dun morogh"}},{q="Varför sprider sig wendigos?",a="Wendigos brukar hålla till i avlägsna grottor, men lokala spanare har lagt märke till att de förökar sig och sprider sig snabbt över de snöiga bergsklipporna. Tillsammans med det lokala trollhotet utgör de en allvarlig fara.",al={"varför sprider sig wendigos","wendigoproblem dun morogh","wendigos förökar sig snabbt"}},{q="Vem är Whitebeard och vad gäller rapporten?",a="Whitebeard är en befälhavare eller annan auktoritet som väntar på en viktig spaningsrapport om förhållandena i bergen. Cornelius bar med sig rapporten när han dumdristigt rusade in i grottan.",al={"vem är whitebeard","whitebeards rapport","senir whitebeard"}},{q="Vad är målet med Secure the Mountain?",a="Det är ett räddnings- och utrensningsuppdrag där äventyrare ska gå in i The Grizzled Den, hitta den försvunne spanaren Cornelius och minska antalet fientliga wendigos som angripit grottan.",al={"vad är secure the mountain","målet med secure the mountain"}},{q="Hur bidrar trollen till problemen i bergen?",a="Lokala spanare utsätts redan för ett ihållande tryck från Frostmane-troll som hör hemma bland bergstopparna. Den plötsliga ökningen av aggressiva wendigos skapar ett farligt hot från två håll för patruller som försöker säkra bergspassen.",al={"troll dun morogh","trollhot"}}},fp="19,179,13.227.0,14.179.0,17.179.0,25.147.0,31.167.0,41.112.0,40.92.0,54.139.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="Tognus Flintfire i Kharanos har akut brist på förnödenheter sedan vilda wendigos tagit över hans främsta malmkälla vid Grizzled Den. Gruvarbetarna tvingades lämna sina lådor under evakueringen, och nu får äventyrare i uppdrag att hämta de förlorade lasterna så att de lokala smedjorna kan hållas igång.",h="Tognus Flintfire i Kharanos har akut brist på förnödenheter sedan vilda wendigos tagit över hans främsta...",kw={"dun morogh","flintfire","smedja","the grizzled den","kharanos","gruvarbetare","malm","leveranser","tognus flintfire","wendigo"},ang={["profession:Blacksmithing"]="Att återfinna Flintfires leveranser är avgörande för att förse smedjorna i Kharanos med bearbetbar metall.",["profession:Mining"]="De förlorade leveranserna består av viktig malm som gruvarbetarna lämnade kvar när de evakuerade sin främsta gruva under wendigornas attack.",["race:Gnome"]="Tognus Flintfire välkomnar särskilt gnomäventyrare som är villiga att utföra tungt kroppsarbete i Dun Morogh, och visar uppriktig uppskattning för deras uthållighet."},sec={{t="En försörjningskris i Kharanos",b="I den snöiga bosättningen Kharanos står Tognus Flintfire inför en allvarlig försörjningskris vid sin smedja. Områdets mest produktiva och pålitliga malmkälla har plötsligt tystnat efter att vilda wendigos invaderat gruvan. Gruvarbetarna överrumplades av de våldsamma rovdjuren och tvingades lämna sina poster utan förvarning, fly för sina liv och lämna nyfyllda lådor med värdefull malm utspridda över grottans golv."},{t="In i Grizzled Den",b="Den övertagna gruvan Grizzled Den ligger väster om Kharanos. Tognus är tacksam över att alla gruvarbetare lyckades undkomma de våldsamma bestarna oskadda, men arbetsstoppet hotar att helt lamslå den lokala smidesverksamheten. I stället för att vänta på en beväpnad expedition som röjer grottan söker Tognus modiga äventyrare som kan smyga in i wendigornas håla, samla ihop lådorna som lämnats kvar och föra den viktiga malmen tillbaka till smedjan."}},faq={{q="Vem är Tognus Flintfire?",a="Tognus Flintfire är en dvärg i Kharanos som behöver regelbundna leveranser av bruten malm för att hålla sin smedja igång. Efter att wendigos tagit över hans främsta gruva råder det akut brist på förnödenheter, så han ber resande att trotsa faran och hämta de övergivna lådorna.",al={"vem är tognus flintfire","tognus flintfire","uppdragsgivare"}},{q="Var ligger Grizzled Den?",a="Grizzled Den är ett grottsystem väster om Kharanos i Dun Morogh. Den var tidigare en pålitlig gruva, men är nu en håla för vilda wendigos. Den som söker den förlorade malmen måste därför ge sig in på fientligt territorium.",al={"var ligger grizzled den","grizzled den plats","var hittar man leveranserna"}},{q="Varför övergavs gruvan?",a="Grottan var de lokala gruvarbetarnas pålitligaste malmkälla tills fientliga wendigos invaderade och tog över platsen. Arbetarna tvingades släppa sin utrustning och de lagrade leveranserna i en desperat flykt, men lyckades mirakulöst nog ta sig ut levande.",al={"varför flydde gruvarbetarna","vad hände med gruvan","wendigoattack"}},{q="Vad finns i de saknade leveranserna?",a="Leveranserna består av bruten malm som gruvarbetarna packade i lådor innan de drevs ut. Utan materialet stannar den lokala metallbearbetningen och smidesverksamheten i Kharanos helt.",al={"vad är flintfires leveranser","vad finns i lådorna","leveransernas innehåll"}},{q="Skadades några gruvarbetare i attacken?",a="Wendigorna var skrämmande våldsamma, men Tognus konstaterar lättat att alla gruvarbetare lyckades ta sig oskadda ut ur Grizzled Den och bara lämnade sina förnödenheter och sin malm bakom sig.",al={"överlevde gruvarbetarna","dödsoffer bland gruvarbetarna","wendigooffer"}},{q="Vad händer när leveranserna har återfunnits?",a="När leveranserna har säkrats får Tognus Flintfire den råmetall som behövs för att få fyr i den lokala smedjan och åter sätta den i drift, utan att först behöva röja hela den angripna grottan.",al={"varför behövs malm","vad händer efter återfyndet","smedjan i drift"}}},fp="20,190,27.261.0,31.353.0,24.208.0,34.160.0,34.193.0,37.174.0,42.137.0,46.170.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="Secure the Mountain är ett uppdrag för Alliansen som börjar i Kharanos i Dun Morogh. En lokal tjänsteman som sammanställer underrättelser åt Ironforge skickar äventyrare väster om staden för att undersöka hur det går för Mountaineer Gretchen, efter att spanare som undersökte aggressiva wendigoer inte återvänt.",h="Secure the Mountain är ett uppdrag för Alliansen som börjar i Kharanos i Dun Morogh.",kw={"dun morogh","dvärg","ironforge","kharanos","mountaineer gretchen","secure the mountain","wendigo","whitebeard"},ang={["faction:Alliance"]="När du hjälper de lokala dvärgpatrullerna runt Kharanos stärks samordningen av försvaret i det snötäckta hjärtat av Khaz Modan.",["race:Dwarf"]="Bergsspanarna i Dun Morogh patrullerar vaksamt snöiga åsar och förrädiska grottor. Tillförlitlig spaning är avgörande för att hålla dvärgarnas bosättningar säkra."},sec={{t="En försenad rapport",b="En tjänsteman i Kharanos har i uppdrag att sammanställa lokal militär underrättelse åt Ironforges högsäte, men hans rutinmässiga korrespondens avbryts. Ett bergsspanarteam som skickats för att bedöma aktiviteten bland närliggande wendigoer har inte återvänt med uppdateringar. I stället för att själv utforska iskalla grottor ber byråkraten dugliga resenärer att bege sig strax väster om staden och ta reda på hur det står till med spanarna."},{t="Oro på den västra åsen",b="När Mountaineer Gretchen spåras upp väster om Kharanos byts den lugna rutinen med regional bevakning mot oro. Gretchen bekräftar att Whitebeards förfrågningar nått henne, men avslöjar att oron bland wendigoerna i de omgivande bergsklipporna är långt mer våldsam än de första rapporterna antydde. Det bäddar för vidare spaning i den närliggande vildmarken."}},faq={{q="Vem ger uppdraget Secure the Mountain?",a="Uppdraget ges av Senir Whitebeard i Kharanos, som Mountaineer Gretchen kallar ”Ol' Whitebeard”. Hans uppgift är att sammanställa officiella rapporter om hoten i den lokala vildmarken och skicka dem till dvärgarnas ledning i Ironforge.",al={"vem ger secure the mountain","uppdragsgivare för secure the mountain","vem startar secure the mountain"}},{q="Var hittar man Mountaineer Gretchen?",a="Mountaineer Gretchen är stationerad strax väster om staden Kharanos i Dun Morogh. Hon håller uppsikt över hotet från wendigoer vid bergssidorna och grottorna i närheten.",al={"var är gretchen","mountaineer gretchens plats","hitta mountaineer gretchen"}},{q="Varför letar uppdragsgivaren efter Mountaineer Gretchen?",a="Uppdragsgivaren ansvarar för att skicka underrättelser till Ironforge, men spanaren som skickats för att undersöka wendigoaktiviteten i området har inte rapporterat tillbaka i tid. Han ligger efter i arbetet och vill undvika att utforska farliga grottor, så han ber en äventyrare på genomresa att se till Mountaineer Gretchen.",al={"varför skicka en äventyrare","varför behöver whitebeard hjälp","varför kontrollera hur det går för gretchen"}},{q="Vilket problem med wendigoer hotar området?",a="Wendigoer håller till i de klippiga bergssluttningarna och mörka grottorna runt Kharanos. Deras aggressiva närvaro utgör ett direkt hot mot resenärer och lokala utposter, så spanare från Ironforge håller noga koll på deras rörelser.",al={"wendigohotet mot kharanos","vad gör wendigoerna","varför är wendigoerna ett problem"}},{q="Vad rapporterar Mountaineer Gretchen när man kommer fram?",a="När du når Mountaineer Gretchen väster om staden bekräftar hon att hon fått Whitebeards förfrågningar och konstaterar bistert att hela situationen med de närliggande wendigoerna har blivit ett rejält elände.",al={"vad säger gretchen","lämna in secure the mountain","gretchens lägesrapport"}},{q="Vilken roll har bergsspanare runt Kharanos?",a="Bergsspanare är Ironforgedvärgarnas främsta gränsvakter, spårare och spaningsstyrkor. De bevakar avlägsna pass, mörka grottor och snöiga leder i Dun Morogh för att skydda städer som Kharanos.",al={"vilka är bergsspanarna","ironforges bergsspanarpatrull","vad gör bergsspanare"}}},fp="19,150,17.281.0,28.237.1,40.184.0,40.134.0,55.226.0,45.176.0,51.145.0,47.185.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="Secure the Mountain är en spaningsrapport som Mountaineer Gretchen skickar till Senir Whitebeard i Kharanos. Efter en katastrofal expedition till en närliggande grotta bedömer Gretchen att grottan är förlorad och vägrar skicka fler spejare in i den övertagna dödsfällan. Uppdraget visar hur Ironforges bergsvakter fortsätter kämpa för att hålla Dun Morogh tryggt när hoten växer.",h="Secure the Mountain är en spaningsrapport som Mountaineer Gretchen skickar till Senir Whitebeard i Kharanos.",kw={"grotta","cornelius","dun morogh","kharanos","mountaineer gretchen","mountaineers rapport","secure the mountain","senir whitebeard"},ang={["faction:Alliance"]="Att säkra de höga passen runt Ironforge är avgörande för trygga resor och försvar i Alliansens snöiga fäste i Khaz Modan.",["race:Dwarf"]="Dun Morogh är Bronzebeard-dvärgarnas uråldriga bergshem, så Mountaineer Gretchens envisa vakthållning är avgörande för att skydda hennes folk mot farorna omkring dem."},sec={{t="En dyster rapport",b="Mountaineer Gretchen är utposterad bland de iskalla topparna i Dun Morogh och håller vakt med order om att säkra de höga passen. Men en färsk utflykt till en närliggande grotta visar att vildmarken långt ifrån är pacificerad. Efter att ha bedömt läget drar Gretchen slutsatsen att grottan har blivit en dödsfälla, översvämmad av fientliga byrackor. I stället för att riskera fler liv stannar hon på sin post i sluttningarna, fast besluten att hålla stånd medan hon skickar ett sändebud med sin skriftliga bedömning."},{t="Förluster i djupet",b="Beslutet att avbryta fler intrång i grottan följer på ett kostsamt offer. Bland offren för den misslyckade spaningen fanns Cornelius, vars död tynger Mountaineer Gretchen. Hon medger att grottan inte kan återtas under rådande förhållanden och beordrar att alla ytterligare utforskningsuppdrag i de underjordiska gångarna ska upphöra. Hennes prioritet skiftar från offensiv rensning till defensiv inneslutning, och hon vägrar offra fler spejare i onödan åt de skoningslösa varelserna som lurar under de snötäckta branterna."},{t="Senir Whitebeards akt",b="I den livliga bosättningen Kharanos håller Senir Whitebeard reda på de många faror som hotar dvärgarnas hjärtland. När han får Gretchen dystra bedömning blir Whitebeard föga förvånad över beskedet att grottan är helt övertagen. Han har accepterat den bistra verklighet som Dun Morogh står inför och viker tyst ihop Gretchens brev och lägger det i sin växande hög med fältrapporter. Uppgifterna blir ännu ett nedslående dokument i Ironforges större arbete med att kartlägga och hantera den oroliga gränsmarken."}},faq={{q="Vem är Mountaineer Gretchen?",a="Mountaineer Gretchen är en vaktpost från Ironforge, utstationerad i Dun Moroghs snöiga vildmark. Hon är hängiven sin plikt och vägrar lämna sin post på berget förrän det omgivande området bedöms vara säkert. Efter ett dödligt spaningsuppdrag i en närliggande grotta skriver hon en officiell fältrapport om den stora fiendenärvaron och skickar den till Kharanos.",al={"gretchen","bergsvakten gretchen i berättelsen","vem är gretchen"}},{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är en dvärgisk myndighetsperson stationerad i staden Kharanos. Han samlar in underrättelser och samordnar lokala säkerhetsinsatser i Dun Morogh, och tar emot rapporter och spaningsbedömningar från bergsvakter i fält. När han får veta om farliga fiendeintrång eller grottor som gått förlorade arkiverar han rapporterna i sina officiella handlingar för att bedöma hotnivån i regionen.",al={"senir whitebeard","whitebeard kharanos","vem är senir"}},{q="Vem var Cornelius?",a="Cornelius var en medarbetare eller medspejare som deltog i utforskningen av den angripna grottan på berget. Mountaineer Gretchen nämner hans tragiska öde med sorg, vilket tyder på att han omkom under det olycksaliga spaningsuppdraget. Hans död påverkade direkt Gretchens beslut att kalla grottan en dödlig dödsfälla och förbjuda att fler liv slösades där inne.",al={"cornelius","vem är cornelius","vad hände med cornelius","cornelius secure the mountain"}},{q="Vad hände i bergsgrottan?",a="Utforskningen av grottan slutade i katastrof när spejarna upptäckte att gångarna var helt övertagna av fientliga byrackor. Uppdraget ledde till att Cornelius tragiskt gick förlorad. Efter denna dystra upptäckt förklarade Mountaineer Gretchen den underjordiska passagen för förlorad och slog fast att det vore självmord att skicka in mer personal. I stället valde hon att spärra av eller undvika området.",al={"vad finns i grottan","varför är grottan en dödsfälla","grottan är förlorad"}},{q="Varför vägrar Gretchen lämna sin post?",a="Mountaineer Gretchen tar sin ed att skydda Dun Morogh på allvar och säger bestämt att hon inte tänker lämna sin position förrän själva berget är säkert. Hon inser att den närliggande grottan är för farlig att återta, men stannar ändå på de snöiga höjderna för att vakta tillfartsvägen och hålla utkik medan hon skickar besked om hotet till Kharanos.",al={"varför stannar gretchen","gretchens post","varför stanna på berget"}},{q="Hur reagerar Senir Whitebeard på Gretchens rapport?",a="Senir Whitebeard blir knappast förvånad över att höra att grottan är helt övertagen, vilket antyder att sådana fientliga angrepp blivit alltför vanliga i Dun Morogh. Han reagerar inte med bestörtning, utan tar stoisk emot de dåliga nyheterna och lägger Gretchens skriftliga rapport i sin växande hög med anteckningar. Han för noggranna register över farorna som hotar riket.",al={"senirs reaktion","whitebeards reaktion på rapporten","vad gör senir"}},{q="Vilken roll har bergsvakterna i Dun Morogh?",a="Bergsvakterna fungerar som Ironforges vaksamma gränsspejare och gränsvakter. De patrullerar Dun Moroghs förrädiska snötäckta toppar, höga leder och bergspass. Dessa härdade dvärgar är stationerade långt från huvudstadens värme och håller uppsikt över fientliga bestars rörelser, spanar i grottor och rapporterar viktig information till lokala knutpunkter som Kharanos för att skydda resande och bosättningar.",al={"ironforges bergsvakter","vad är bergsvakter","dvärgarnas bergsvakter i berättelsen"}}},fp="19,248,13.377.0,20.352.1,26.274.0,28.270.0,24.242.0,18.248.0,35.216.0,43.233.0,53.205.0,49.275.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl är ett uppdrag i Dun Morogh där äventyrare ska återta en stulen säck fisk från en tjuvaktig wendigo. Odjuret överföll en lokal dvärgisk fiskare och flydde in i djupet av The Grizzled Den.",h="Frosthowl är ett uppdrag i Dun Morogh där äventyrare ska återta en stulen säck fisk från en tjuvaktig wendigo.",kw={"dun morogh","frosthowl","frusen sjö","the grizzled den","isfiske","paxton","stulen fisk","wendigo"},ang={["faction:Alliance"]="Det är upp till lokala äventyrare i Alliansen att hålla de isiga stigarna och fiskeplatserna nära Brewnall och Kharanos trygga från aggressiva rovdjur.",["race:Dwarf"]="Härdade dvärgiska fiskare uthärdar den bitande kylan vid Dun Moroghs frusna sjöar. Wendigoattacker är ett ständigt hot mot ortsborna och deras försörjning."},sec={{t="En stulen fångst",b="Isfiske i Dun Moroghs iskalla vatten är ett slitsamt och bistert arbete. En dvärgisk fiskare och hennes make Paxton tillbringade dagar ute på den frusna sjön och trotsade bitande vindar för att få ihop en enda säck fisk. Deras hårda arbete blev plötsligt ogjort när Frosthowl, en hotfull och dånande wendigo, överföll lägret och försvann med hela fångsten ut i den snötäckta vildmarken."},{t="The Grizzled Dens skränfock",b="Frosthowl är ingen vanlig asätare. Odjuret är ökänt för sina dånande vrål som får isen att skaka och skrämmer bort sjöns fåtaliga fiskar. Efter att ha stulit fiskarens säck drog sig den dreglande varelsen djupt in i de mörka tunnlarna i The Grizzled Den åt sydost. De strandsatta fiskarna är nu desperata efter någon som vågar möta monstret och återta deras stulna egendom."}},faq={{q="Vem är Frosthowl?",a="Frosthowl är en högljudd och aggressiv wendigo som håller till i Dun Morogh. Odjuret är känt för att ryta och terrorisera de frusna vattendragen och anföll nyligen en lokal dvärgisk fiskare för att stjäla den fångst som hennes make slitit hårt för att få ihop.",al={"vem är frosthowl","vad är frosthowl","frosthowl wendigo"}},{q="Var finns Frosthowl?",a="Frosthowl har tagit sin tillflykt djupt inne i The Grizzled Den, ett grottsystem sydost om den frusna sjön där Paxton fiskar.",al={"var finns frosthowl","frosthowls plats","var gömmer sig wendigon"}},{q="Vad stal Frosthowl?",a="Frosthowl överföll en dvärgisk fiskare och stal en hel säck fisk som hennes make Paxton hade tillbringat dagar med att fånga i den frusna sjön. Äventyrare ombeds att spåra upp odjuret och återta den stulna fångsten.",al={"vad stal frosthowl","varför döda frosthowl","vad tog wendigon"}},{q="Vem är Paxton?",a="Paxton är en dvärgisk fiskare som tillbringade dagar ute på den frusna sjön i hopp om en blygsam fångst. Hans fru ber förbipasserande resenärer att spåra upp Frosthowl efter att odjuret stulit deras enda säck fisk.",al={"vem är paxton","paxton dun morogh","paxton fiskare"}},{q="Vad är The Grizzled Den?",a="The Grizzled Den är ett känt tillhåll för wendigor sydost om den frusna sjön i Dun Morogh. Det är en mörk tillflykt där odjur som Frosthowl kan samla kött från asätande och stulna förnödenheter.",al={"vad är the grizzled den","wendigogrotta the grizzled den","var bor wendigor i dun morogh"}},{q="Varför heter odjuret Frosthowl?",a="Wendigon kallas en skränfock vars dånande vrål och tjut ekar över de snötäckta slätterna. Ljuden hotar att skrämma bort fiskarna och terroriserar alla som arbetar vid de frusna sjöarna.",al={"hur fick frosthowl sitt namn","varför kallas den frosthowl","högljudd wendigo"}}},fp="9,138,13.252.0,33.302.0,17.204.0,29.95.0,25.168.0,14.158.0,25.147.0,33.181.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit är en helig mentor från riket Zephras, som visar sig som Saeyleenans avatar i Moonglade. Den vägleder unga shen'dorei-druider genom deras andliga prövning, så att de kan anta sitt avlägsna hemlands vindburna kattgestalt.",h="The Great Windborne Cat Spirit är en helig mentor från riket Zephras, som visar sig som Saeyleenans avatar i...",kw={"kattgestalt","kattande","druidprövning","moonglade","saeyleenan","shen'dorei","vindburen katt","zephras"},ang={["class:Druid"]="Druider från Zephras umgås med den vindburna kattanden för att bemästra sin kattgestalt och fullgöra en rit som är anpassad till deras unika arv, snarare än följa Azeroths traditionella väg.",["race:Skyborne"]="Druiderna kallas shen'dorei och vägleds av andarna från sitt hemland Zephras i stället för att anta Azeroths inhemska former."},sec={{t="En besökare från Zephras",b="I Moonglades heliga helgedom har en ande från det avlägsna riket Zephras visat sig söder om tvillingbroarna. Den kallar sig Saeyleenans avatar och har korsat över till Azeroth för att vägleda och undervisa unga shen'dorei-druider som är redo att låsa upp sin kattgestalt."},{t="Den vindburna gestaltens natur",b="Alla druider söker så småningom kattgestaltens visdom, men de från Zephras följer en tradition som skiljer sig från Azeroths ursprungsbefolkningars. I stället för att anta en vildkatts gestalt från Azeroth antar shen'dorei sitt hemlands vindburna rovdjursform. För att se till att de förstår dess andliga natur övervakar Saeyleenan själv deras prövning i Moonglade."}},faq={{q="Vem är The Great Windborne Cat Spirit?",a="Den vindburna kattanden visar sig som Saeyleenans avatar, en ande från shen'doreis avlägsna hemland Zephras. Den har rest till Moonglade för att vägleda och pröva unga shen'dorei-druider som vill anta dess kattgestalt.",al={"vem är den vindburna kattanden","vad är saeyleenans avatar","saeyleenans bakgrund"}},{q="Var finns Saeyleenans avatar?",a="Andens avatar visar sig i Moonglades södra delar, strax söder om tvillingbroarna.",al={"var hittar man kattanden i moonglade","saeyleenans avatars plats","den vindburna kattens plats"}},{q="Varför umgås druider från Zephras med en annan kattande?",a="Eftersom shen'dorei-druider kommer från Zephras återspeglar deras kattgestalt hemlandets vindburna andar snarare än Azeroths inhemska stora kattdjur. Anden övervakar personligen deras prövning för att se till att de verkligen antar dess väsen.",al={"varför ser kattgestalten annorlunda ut","skillnaden mellan kattgestalter från zephras","varför inte azeroths kattande"}},{q="Vad går den vindburna kattens prövning ut på?",a="Saeyleenans avatar låter den blivande druiden genomgå Azeroths Great Cat Spirits prövning, samtidigt som den själv övervakar och bekräftar att druiden förstår den vindburna andens unika natur.",al={"vilken prövning ger kattanden","zephras kattandes prövning","hur får man den vindburna kattgestalten"}},{q="Vad syftar shen'dorei på?",a="Saeyleenans avatar tilltalar den blivande druiden som shen'dorei, vilket anger att hen kommer från Zephras och skiljer hens arv och andliga sedvänjor från Azeroths ursprungsbefolkningars.",al={"vilka är shen'dorei","shen'dorei-druider","vad betyder shen'dorei"}},{q="Vad är Zephras?",a="Zephras är shen'doreis avlägsna hemland. Dess inhemska växter, djur och andar skiljer sig tydligt från Azeroths, vilket har gett upphov till unika skepnadsskiftande former bland dess druider.",al={"vad är zephras","var ligger zephras","zephras hemland"}}},fp="30,193,22.262.0,32.302.0,38.177.0,44.87.0,58.213.0,48.192.0,30.176.0,16.170.0"}
P.entries["quest:98362"] = {n="To Thunder Bluff",s="Uppdraget To Thunder Bluff markerar en ung tauren-druids triumferande återkomst från mötet med Cenarion Circle i Moonglade. Efter att ha vunnit The Great Cat Spirits gunst återvänder novisen till Turak Runetotem på Elder Rise för att bemästra kattens skepnad.",h="Uppdraget To Thunder Bluff markerar en ung tauren-druids triumferande återkomst från mötet med Cenarion...",kw={"kattform","dendrite starblaze","druid","elder rise","the great cat spirit","moonglade","thunder bluff","turak runetotem"},ang={["class:Druid"]="Den här riten låser upp dina rovdjursinstinkter och ger dig, enligt Turak Runetotems läror, mästerskap över smygande och klor.",["faction:Horde"]="Även om Cenarion Circle förblir neutralt måste Horde-druider återvända till sin huvudstad för att säkerställa att deras växande kraft tjänar försvaret av deras folk.",["race:Tauren"]="Resan visar hur tauren återknyter till Cenarion-traditionerna och för lärdomarna från det heliga Moonglade tillbaka till Elder Rise i Thunder Bluff."},sec={{t="Åter från Moonglade",b="Efter att ha visat sin insikt och sitt värde inför Dendrite Starblaze och The Great Cat Spirit i Moonglades heliga lundar måste en ung druid föra andens välsignelse tillbaka till Mulgore. Mötet med sådana urkrafter är en avgörande milstolpe i en druids träning och förenar urgamla nattalviska läror med taurenfolkets jordnära arv."},{t="Bemästra kattformen",b="Turak Runetotem väntar på dig högt uppe på Elder Rise i Thunder Bluff. Dendrite förmedlade mötet med själva anden, men Turak ska vägleda den fysiska förvandlingen. När The Great Cat Spirits välsignelse har bekräftats förmedlar den äldre tränaren den heliga kunskap som krävs för att anta kattens snabba, rovdjurslika skepnad."}},faq={{q="Var börjar och slutar uppdraget?",a="Dendrite Starblaze ger uppdraget i Moonglades heliga tillflyktsort. Det leder resenären tillbaka till Elder Rise i Thunder Bluff för att tala med Turak Runetotem.",al={"var lämnar jag in uppdraget","vem startar to thunder bluff","lämna in uppdraget to thunder bluff"}},{q="Vad är syftet med uppdraget?",a="Det är den avslutande övergången i druids prövning av katten. Efter att ha fått The Great Cat Spirits välsignelse i Moonglade måste novisen återvända till sin mentor i Thunder Bluff för att till slut lära sig anta kattform.",al={"varför göra to thunder bluff","vad får jag från to thunder bluff","uppdraget om kattform"}},{q="Vem är Turak Runetotem?",a="Turak Runetotem är en respekterad äldre tauren-druid på Elder Rise i Thunder Bluff. Han ansvarar för träningen och invigningen av unga Horde-druider som vill leva i harmoni med naturen och bemästra sina skepnadsförvandlingar.",al={"turak runetotem i berättelsen","vem är turak"}},{q="Vem är Dendrite Starblaze?",a="Dendrite Starblaze är en nattalvisk väktare inom Cenarion Circle som vägleder besökande druider i Nighthaven i Moonglade. Han förmedlar lärdomar mellan urgamla kaldoreiska traditioner och tauren-utövare, trots spänningar mellan fraktionerna.",al={"dendrite starblazes roll","nattalv i moonglade"}},{q="Vad är The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig urkraft som druider vördar och som förkroppsligar rovdjursinstinkt, smygande och smidighet. Varje druid som vill anta kattens skepnad måste klara en prövning för att förtjäna dess välsignelse och förstå dess dubbla natur, både lekfull och dödlig.",al={"om kattandens historia","kattens ande"}},{q="Har Alliance-druider en motsvarande uppgift?",a="Ja. Nattalviska druider genomgår en liknande rit i Moonglade och återvänder till Darnassus för att rapportera till sin egen mentor, i stället för att bege sig till Mulgore och dess vindpinade platåer.",al={"alliance-versionen av to thunder bluff","nattalv återvänder för kattform"}}},fx={cdfa9758={q="Varför skickar Dendrite Starblaze dig tillbaka till Thunder Bluff?",a="Dendrite Starblaze är mentor och prövare i Moonglade, där han vägleder dig när du kommunicerar med The Great Cat Spirit. När du har klarat prövningen och vunnit andens gunst är hans roll i det här skedet av din träning över. Han skickar dig tillbaka till Turak Runetotem, så att din huvudlärare kan ge dig de sista lärdomarna och vägleda dig när du antar kattformen.",al={"varför skicka till thunder bluff","dendrite starblazes motiv","varför återvända till turak runetotem"}}},fp="16,219,21.247.0,22.290.0,36.146.0,34.121.0,23.221.0,26.228.0,29.225.0,43.171.0"}
P.entries["quest:98372"] = {n="An Unfortunate End",s="En fallen Night Watchman ligger i Duskwoods mörker, svårt söndersliten av ett okänt rovdjur. Att ta den släckta facklan ur hans kalla fingrar ger en möjlighet att tränga igenom mörkret omkring dig och avslöja det som döljer sig i skuggorna.",h="En fallen Night Watchman ligger i Duskwoods mörker, svårt söndersliten av ett okänt rovdjur.",kw={"an unfortunate end","odjur","duskwood","söndersliten","nattvakt","fackla"},sec={{t="En dyster upptäckt",b="En fallen medlem av Night Watch ligger stilla på Duskwoods mörka mark, med djupa hugg och skärsår efter ett vilt möte. De fruktansvärda såren tyder på att ett enormt odjur överföll patrullvakten innan han hann fly."},{t="Ljus i mörkret",b="I den fallna vaktens stela fingrar ligger en släckt fackla. Tar du den ur hans grepp får du ett värdefullt redskap mot skuggorna som tränger sig på. Den kan avslöja sådant som döljer sig i Duskwoods djupa mörker och längs andra mörka vägar."}},faq={{q="Vem tillhör kroppen?",a="Den fallna kroppen tillhör en medlem av Night Watch, stadsvakten som patrullerar Duskwoods mörka vägar och gränser. Han mötte en våldsam död ensam i skuggorna.",al={"vem är den döda kroppen","vem dog här","vem är den döda nattvakten"}},{q="Vad dödade vakten?",a="Han slets sönder av ett stort odjur, och kroppen bär djupa hugg och vilda skärsår. Odjuret hann övermanna honom innan han kunde försvara sig eller tända sin fackla.",al={"vad dödade nattvakten","hur dog vakten","vad anföll honom"}},{q="Varför är facklan viktig?",a="Den släckta facklan som vakten höll i kan lysa upp mörkret omkring dig och hjälpa vandrare att avslöja sådant som döljs i Duskwoods täta mörker och länderna bortom.",al={"vad används facklan till","vad gör jag med facklan","facklans användning i duskwood"}}},fp="18,147,16.143.0,21.149.0,19.124.0,25.134.0,27.126.0"}
P.entries["quest:98386"] = {n="Alther's Mill",s="Alther's Mill är ett uppdrag i Redridge Mountains som Foreman Oslow ger i Lakeshire. Han behöver äventyrare som röjer bort en farlig invasion av tarantlar vid det närbelägna sågverket, så att arbetarna tryggt kan hämta virket som behövs för att färdigställa bron i Lakeshire.",h="Alther's Mill är ett uppdrag i Redridge Mountains som Foreman Oslow ger i Lakeshire.",kw={"alther's mill","bro","foreman oslow","lakeshire","sågverk","redridge mountains","tarantel"},ang={["faction:Alliance"]="Att återuppbygga Lakeshires infrastruktur är viktigt för kungariket Stormwind, men ständiga hot drar resurser från bron."},sec={{t="En flaskhals i virkesflödet",b="Foreman Oslow har fullt upp med att hålla broreparationerna i Lakeshire enligt tidsplanen. Fientliga Blackrock-orcher, framryckande gnollflockar och aggressiva murlocer längs Lake Everstill pressar hans arbetsstyrka till bristningsgränsen. Det senaste avbrottet slår direkt mot försörjningskedjan: Alther's Mill, sågverket österut, har tagits över av jättelika tarantlar, vilket stoppar virkesleveranserna som behövs till stadens bro."},{t="Röj bort invasionen",b="Sågverket är så gott som obrukbart medan spindlar lurar bland timmerstaplarna. Foreman Oslow vågar inte skicka in sina arbetare i ett bo av större tarantlar, så han anlitar dugliga äventyrare för att röja bort spindlarna och förstöra deras äggsamlingar. Oslow är irriterad över att Alther låtit sågverket förfalla så, men att få igång virkesflödet igen går före alla klagomål."}},faq={{q="Vem är Foreman Oslow?",a="Foreman Oslow är stenhuggaren och arbetsledaren med ansvar för att reparera och återuppbygga bron i Lakeshire. Lokala hot försenar ständigt hans byggarbete.",al={"vem är foreman oslow","foreman oslow i redridge"}},{q="Vad är Alther's Mill?",a="Alther's Mill är ett sågverk öster om Lakeshire i Redridge Mountains. Det levererar viktigt virke till byggprojekt runt Lakeshire, däribland bron.",al={"vad är alther's mill","var ligger alther's mill"}},{q="Vem är Alther?",a="Alther äger eller driver sågverket öster om Lakeshire. Enligt Foreman Oslow ansvarar Alther för att sköta platsen, men just nu har spindlar tagit över hans sågverk.",al={"vem är alther","var är gamle alther"}},{q="Varför behöver Foreman Oslow få Alther's Mill röjt?",a="Foreman Oslow kan inte tryggt skicka arbetare för att hämta nödvändiga virkesleveranser medan sågverket är fullt av tarantlar. När spindlarna röjs bort och deras ägg förstörs kan sågverket tryggt återuppta leveranserna till brobygget.",al={"varför röja alther's mill","varför döda spindlar i redridge"}},{q="Vad har invaderat Alther's Mill?",a="Större tarantlar har invaderat sågverksområdet, tillsammans med samlingar av spindelägg. De utgör ett allvarligt hot mot alla arbetare som skickas dit för att hämta virke.",al={"vilka spindlar finns vid alther's mill","spindlar i redridge"}},{q="Vilken bro försöker Foreman Oslow bygga?",a="Foreman Oslow arbetar med att återuppbygga bron i Lakeshire, men arbetet försenas gång på gång av fientliga orcher, gnoller och murlocer samt brist på resurser till följd av lokala skadedjur.",al={"vilken bro i redridge","bron i lakeshire"}}},fp="13,163,22.272.0,24.353.0,21.131.0,22.156.0,14.133.0,50.191.0,32.111.0,45.153.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="Blackrock Blockade är ett militärt uppdrag från Alliansen som Marshal Marris utfärdar i Lakeshire. Stadsvakten vill svälta ut inkräktarna och ta deras vapen när den möter Blackrock-orcherna som rycker fram öster om Lake Everstill.",h="Blackrock Blockade är ett militärt uppdrag från Alliansen som Marshal Marris utfärdar i Lakeshire.",kw={"battleworn axe","blackrock blockade","blackrock-klanen","lakeshire","marshal marris","redridge mountains","stonewatch keep"},ang={["class:Warrior"]="I närstrider mot de härdade Blackrock-orcherna är det grundläggande gränskrigföring att beröva fienden tunga huggare och förnödenheter.",["faction:Alliance"]="Varje vapen som tas från Blackrocks förtrupp köper dyrbar tid åt Lakeshire, som måste stå emot fientliga arméer utan nämnvärd hjälp från Stormwind."},sec={{t="Ett utnötningskrig",b="Blackrock-klanen har gjort djärva räder in i Redridge Mountains, men deras fräcka framryckning in på Alliansens territorium har pressat deras försörjning till bristningsgränsen. Utan regelbundna försörjningstransporter måste deras främsta krigstrupper leva av de karga kullarna i Redridge. Marshal Marris vet att inte ens våldsamma orcher kan föra ett fälttåg utan stadig tillgång till förnödenheter och stål."},{t="Skär av de främsta lägren",b="Orchernas läger söder om Stonewatch Keep utgör spetsen i Blackrocks offensiv. Genom att plundra lägren, tömma deras förråd och ta tillbaka deras stulna vapen hoppas Alliansens försvarare slå ut förtruppens stridsstyrka och knäcka dess moral."}},faq={{q="Vad är målet med Blackrock Blockade?",a="Uppdraget ska försvaga Blackrock-klanens främsta läger söder om Stonewatch Keep. Genom att slå till mot deras försörjningslinjer, ta deras mat och återta deras vapen hoppas vakten i Lakeshire svälta ut orcherna och hejda deras framryckning in i Redridge.",al={"vad är blackrock blockade","målet med blackrock blockade","syftet med blockaden"}},{q="Vem utfärdar uppdraget?",a="Marshal Marris, befälhavare för stadsvakten i Lakeshire, leder försvaret av Redridge och styr arbetet med att störa Blackrocks försörjning.",al={"vem ger blackrock blockade","uppdragsgivare","marshal marris uppdrag"}},{q="Var ligger Blackrock-lägren?",a="De utpekade krigslägren ligger i de östra kullarna i Redridge Mountains, strax söder om Stonewatch Keep, på andra sidan floden från Lakeshire.",al={"var finns orcherna","blackrock-lägrets plats","var ligger stonewatch-lägret"}},{q="Varför förlitar sig Lakeshire på utnötning i stället för ett direkt anfall?",a="Vakten i Lakeshire har för få soldater och får knappt några förstärkningar från Stormwind. Det här är ett utnötningskrig: Blackrock-orchernas fräcka framryckning in på Alliansens territorium har gjort dem sårbara och lämnat dem utan förnödenheter. De är beroende av bergen omkring sig för att få resurser, och en armé kan inte kämpa på tom mage.",al={"varför svälta ut orcherna","varför inte anfalla stonewatch direkt","lakeshires strategi"}},{q="Vilka vapen beslagtar man från orcherna?",a="Marshal Marris vill att vapnen och förnödenheterna som lagras i Blackrock-lägren ska beslagtas, så att orcherna blir utan sina krigsredskap.",al={"vilka föremål behövs","vilka yxor","berättelser om stridsnötta yxor"}},{q="Tillhör de här orcherna Thralls Horde?",a="Nej. Blackrock-orcherna i Redridge tillhör den förrymda Dark Horde, som har sin bas i Blackrock Mountain. De förkastar Thralls ledarskap och är fortsatt fientliga mot både Alliansen och den nya Horden.",al={"är de här orcherna från horden","tillhör blackrock horden","thrall och blackrock-klanen"}}},fp="18,151,18.247.0,26.192.0,43.183.0,27.120.0,46.123.0,67.211.0,49.137.0,46.188.0"}
P.entries["quest:98389"] = {n="A Light in the Darkness",s="I Deathknell ber Aramis Hammerhand dig att rädda nyväckta Forsaken från Night Web's Hollow. Din hjälp kan visa att de som brukar Holy Light förblir lojala mot Sylvanas och sitt folk.",h="I Deathknell ber Aramis Hammerhand dig att rädda nyväckta Forsaken från Night Web's Hollow.",kw={"aramis hammerhand","deathknell","executor arren","forsaken","holy light","night's web hollow","tirisfal glades","offer i näten"},ang={["class:Priest"]="Som präst bland Forsaken vandrar du en svår väg mellan den tro du hade i livet och den hårda sanningen om din odöda tillvaro.",["race:Undead"]="Som en av Forsaken ser du slitningarna inom ditt folk. De nyväckta kan möta fördomar från sina egna fränder."},sec={{t="En utsatt tro",b="Vissa Forsaken brukar fortfarande Holy Light, som de kände i livet, trots att det plågar deras odöda kött. I Deathknell hoppas Aramis Hammerhand och andra kunna visa att deras tro inte har vänt dem mot deras eget folk. De använder sina gåvor för att skydda Forsaken och stilla oron för att de ser sina fränder som monster."},{t="Night Web's Hollow",b="Nordväst om Deathknell vandrar nyväckta Forsaken in i Night Web's Hollow, en fuktig grotta som kryllar av argsinta spindlar. Förvirrade och oförmögna att försvara sig fastnar de i klibbiga nät. Att rädda dem ger Dark Lady nya rekryter och kan övertyga Executor Arren om att de som brukar Light tjänar Forsaken troget."}},faq={{q="Vem ger uppdraget A Light in the Darkness?",a="Aramis Hammerhand, som brukar helig kraft i Deathknell i Tirisfal Glades, ber dig om hjälp.",al={"uppdragsgivare","vem startar a light in the darkness","aramis hammerhands uppdrag"}},{q="Var ligger Night Web's Hollow?",a="Night Web's Hollow ligger nordväst om Deathknell bland kullarna i Tirisfal Glades.",al={"nights web hollow plats","var finns offren i näten","var ligger grottan"}},{q="Varför misstror Forsaken dem som brukar Light?",a="Holy Light bränner odött kött. Många Forsaken fruktar att de som brukar det ser dem som styggelser att förgöra snarare än som fränder.",al={"varför frukta light","varför hatar forsaken paladiner","forsakens rädsla för helig kraft"}},{q="Vilka är offren som sitter fast i näten?",a="De är nyvaknade äventyrare bland Forsaken som vandrade in i spindelgrottorna innan de hunnit orientera sig.",al={"vem sitter fast i näten","vad finns i näten","fångade offer"}},{q="Vem är Executor Arren, och varför vill Aramis imponera på honom?",a="Executor Arren ansvarar för den militära och civila ordningen i Deathknell. Aramis söker hans förtroende så att de som brukar helig kraft utan svårigheter kan ansluta sig till Forsakens styrkor.",al={"vem är executor arren","varför arren är viktig"}},{q="Kan odöda verkligen bruka Holy Light?",a="Ja. Vissa odöda behåller sitt band till Light genom stark vilja och hängivenhet. Att bruka det medför oerhört obehag och väcker misstänksamhet hos deras eget folk.",al={"kan forsaken använda light","berättelser om odöda och light"}}},fx={f946e0be={q="Varför vill Aramis Hammerhand att de spindelinsnärjda offren befrias?",a="Aramis vill bevisa för sina andra Forsaken att odöda som brukar det heliga ljuset inte är ett hot mot sina egna. Många i Deathknell, däribland Executor Arren, fruktar eller misstänker att ljusbärare ska vända sina krafter mot andra odöda som om de vore monster. Genom att rädda nyväckta Forsaken från spindlarna i Night Web's Hollow hoppas Aramis visa att deras kraft finns till för att skydda Forsaken och tjäna Dark Ladys vision.",al={"aramis hammerhands motiv","varför befria de spindelinsnärjda offren","varför vill aramis att detta görs"}}},fp="23,192,18.305.0,18.343.0,44.90.0,36.80.0,51.119.0,40.110.0,63.142.0,43.155.0"}
P.entries["quest:98391"] = {n="The Sisterhood of Elune",s="The Sisterhood of Elune är ett introduktionsuppdrag som leder äventyrare till Darnassus för att träffa Sister Aquinne. Som den främsta andliga auktoriteten bland Night Elf behöver orden snabbt hjälp utifrån för att möta de växande utmaningarna i sina länder.",h="The Sisterhood of Elune är ett introduktionsuppdrag som leder äventyrare till Darnassus för att träffa Sister...",kw={"aquinne","darnassus","elune","prästinna","sister aquinne","the sisterhood of elune","teldrassil"},ang={["class:Priest"]="Prästerskapet i kaldoreisk kultur är synonymt med hängivenhet till Elune, och genom att svara Sister Aquinne knyter du an direkt till templets höga traditioner.",["faction:Alliance"]="Eftersom Darnassus är en viktig huvudstad för Alliance i Kalimdor bidrar din hjälp till The Sisterhood till stabiliteten i Night Elfs andliga och civila styre.",["race:NightElf"]="The Sisterhood of Elune är hjärtat i Night Elfs andliga liv och ledarskap. Därför är det en helig plikt för varje stjärnornas barn att svara på deras kallelse."},sec={{t="En kallelse till huvudstaden",b="”The Sisterhood of Elune” är en kallelse som uppmanar äventyrare att söka upp Sister Aquinne i Night Elf-huvudstaden Darnassus. Som företrädare för Elunes trogna skickar prästinnorna ofta ut kallelser efter pålitliga hjältar som kan hjälpa till med brådskande angelägenheter som berör deras folk och heliga länder."},{t="Rapportera till Sister Aquinne",b="När du anländer till Darnassus och hittar Sister Aquinne uttrycker hon stor lättnad över att du kom så snabbt. Hennes välkomnande markerar början på ditt direkta arbete för The Sisterhood of Elune och visar att prästinnorna ställs inför allt fler krav som behöver pålitliga händer utanför deras slutna krets."}},faq={{q="Vem är Sister Aquinne?",a="Sister Aquinne är ett sändebud och en prästinna som tjänar The Sisterhood of Elune i huvudstaden Darnassus. Hon tar emot resenärer som skickats för att hjälpa prästerskapet med brådskande angelägenheter som möter Night Elf.",al={"vem är sister aquinne","aquinne darnassus","var finns aquinne"}},{q="Vad är The Sisterhood of Elune?",a="The Sisterhood of Elune är en uråldrig orden av Night Elf-prästinnor som ägnar sig åt mångudinnan Elune. De vördas som andliga vägledare, helare och ledare för kaldoreisk kultur och ansvarar för sitt folks andliga välfärd och försvar.",al={"vad är the sisterhood of elune","vilka är elunes systrar","night elf-prästinnor"}},{q="Vart ska jag bege mig för att slutföra uppdraget?",a="Du måste resa till Darnassus, Night Elfs mäktiga huvudstad högt uppe på Teldrassil. Sister Aquinne väntar på dig i staden för att ge dig en genomgång på The Sisterhood of Elunes vägnar.",al={"var lämnar jag in the sisterhood of elune","plats för the sisterhood-uppdraget","vart går jag för the sisterhood of elune"}},{q="Varför behöver The Sisterhood hjälp?",a="Sister Aquinne antyder att The Sisterhood snabbt behöver hjälp utifrån för att hantera de akuta problem som drabbar Darnassus och de omkringliggande Night Elf-länderna. När du talar med henne får du fler uppdrag från dem.",al={"varför behöver the sisterhood hjälp","problem för the sisterhood","vilken hjälp behöver the sisterhood"}},{q="Kan Horde-karaktärer ta sig an det här uppdraget?",a="Nej. The Sisterhood of Elune står i centrum för Night Elfs ledarskap och är helt knuten till Alliance. Darnassus är en huvudstad för Alliance, så uppdraget är exklusivt för äventyrare i Alliance.",al={"får horde det här uppdraget","kan horde göra the sisterhood of elune"}},{q="Vem leder The Sisterhood of Elune?",a="Översteprästinnan Tyrande Whisperwind är The Sisterhood of Elunes andliga ledare och den högsta ledaren för kaldoreifolket. Hon vägleder sina systrar från Temple of the Moon i Darnassus.",al={"vem leder the sisterhood of elune","the sisterhoods ledare","tyrande och the sisterhood"}}},fp="23,152,21.169.0,27.161.0,22.167.0,32.217.0,45.122.0,36.168.0,42.175.0,34.154.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade är en utredning ledd av Sentinel Arynia Cloudsbreak om förgiftade läderbälten från harpyor i The Oracle Glade. Amuletter från harpyornas matriarker bekräftar att demonisk felmossa har slagit rot i Teldrassils grenar.",h="Darkness in the Glade är en utredning ledd av Sentinel Arynia Cloudsbreak om förgiftade läderbälten från...",kw={"arynia cloudsbreak","arysa","darkness in the glade","fel moss","gaedress","harpyor","hatescreech","the oracle glade","teldrassil"},ang={["class:Druid"]="Felmossa som förorenar djurliv och läderfibrer är ett tecken på en onaturlig farsot som rubbar världsträdets naturliga balans.",["faction:Alliance"]="Sentinel Cloudsbreak företräder Darnassus militära vaksamhet och arbetar för att hitta demonisk förorening som hotar Alliansens länder.",["race:NightElf"]="När felkorruption sprider sig genom heliga grenar som The Oracle Glade slår den direkt mot kaldoreiernas strävan att vårda och skydda Teldrassil."},sec={{t="Förgiftade fibrer",b="I The Oracle Glades rofyllda trädkronor lade Sentinel Arynia Cloudsbreak märke till något märkligt bland de lokala harpyflockarna. Läderbälten från varelserna bar på en onaturlig förorening, invävd direkt i materialet. Cloudsbreak misstänkte ett demoniskt intrång snarare än vanligt aggressivt beteende hos bestar och behövde säkra bevis innan hon slog larm till Darnassus."},{t="En bekräftad farsot",b="Cloudsbreak skickade hjältar till de västra bona för att fälla flyktens matriarker: Hatescreech, Windmistress Gaedress och Witchmother Arysa. Var och en bar en amulett med synliga spår av sin kraft. När Sentinel undersökte stenarna upptäckte hon vidriga gröna virvlar inneslutna i ädelstenarna, vilket bekräftade att felmossa aktivt förvred harpyorna och trängde in i de heliga grenarna."}},faq={{q="Vad är Darkness in the Glade?",a="Darkness in the Glade är ett uppdrag från Sentinel Arynia Cloudsbreak i The Oracle Glade. Efter att ha upptäckt en onaturlig förorening i harpyornas läderbälten skickar hon äventyrare för att hämta amuletter från harpyledarna och fastställa föroreningens källa.",al={"vad är darkness in the glade","uppdraget darkness in the glade"}},{q="Vem ger uppdraget?",a="Sentinel Arynia Cloudsbreak ger uppdraget. Hon är stationerad i The Oracle Glade, där hon vakar över Teldrassils grenar och undersöker märkliga störningar bland de harpyor som bor där.",al={"vem ger darkness in the glade","uppdragsgivare the oracle glade"}},{q="Varför vill Arynia ha amuletter från harpyledarna?",a="Sentinel Cloudsbreak upptäckte förorenade fibrer i läderbälten från vanliga harpyor och behövde fler bevis. Hon misstänkte att harpyornas ledare bar smycken som visade farsotens verkliga natur och ursprung.",al={"varför döda harpyledare","varför hämta amuletter","varför harpyamuletter"}},{q="Vilka harpyledare har amuletterna?",a="Amuletterna tillhör tre framstående ledare med bon i väster: Hatescreech, Windmistress Gaedress och Witchmother Arysa.",al={"vilka harpyor har amuletter","harpyledare the oracle glade"}},{q="Vad orsakar föroreningen i gläntan?",a="Föroreningen kommer från felmossa. När Arynia undersöker de återfunna amuletterna upptäcker hon vidriga gröna virvlar i ädelstenarna, vilket bekräftar att felmossa förorenar området.",al={"vad förorenar harpyorna","vad är den gröna virveln","ursprunget till gläntans mörker"}},{q="Har föroreningen dykt upp någon annanstans?",a="Ja, Sentinel Cloudsbreak nämner att rapporter om felmossa som vänder miljön mot nattalverna också har kommit från Shadowglen och andra grenar runt om på världsträdet.",al={"felmossa på andra platser","är shadowglen förorenat"}}},fp="21,142,14.262.0,18.295.1,30.187.0,21.158.0,52.161.0,37.112.0,44.147.0,43.136.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="The Great Cat Spirit är ett heligt druidiskt uppdrag som kallar utövare till Nighthaven i Moonglade för att möta Dendrite Starblaze. Efter att ha bemästrat björnens aspekt kallas druider att påbörja sin resa in i vildmarkens kattperspektiv, med Father Cenarius välsignelse.",h="The Great Cat Spirit är ett heligt druidiskt uppdrag som kallar utövare till Nighthaven i Moonglade för att...",kw={"kattaspekten","cenarius","dendrite starblaze","druidutbildning","moonglade","nighthaven","the great cat spirit"},ang={["class:Druid"]="Denna kallelse är en viktig övergångsrit för druider som vill bemästra vildmarkens aspekter bortom björnen.",["race:NightElf"]="Moonglade är förfädernas mark för kaldorei-druider som följer Cenarius uråldriga läror.",["race:Tauren"]="Taurendruider reser fritt till Nighthaven tillsammans med sina nattalvssystrar och -bröder under Cenarion Circles gemensamma ledning."},sec={{t="Kallelsen till Moonglade",b="Efter att redan ha visat att de behärskar björnens uthålliga aspekt blir blivande druider åter kallade till Moonglades heliga skog. Äldsten Dendrite Starblaze sträcker sig över landet och kallar lärjungar till den fridfulla tillflyktsorten Nighthaven för att inleda nästa steg i sin förening med naturen. Druider använder sin unika andemagi för att färdas långa sträckor och samlas i Cenarion-visdomens stilla hjärta."},{t="Kattens perspektiv",b="När du anländer till Nighthaven åkallar Dendrite Starblaze Father Cenarius och en svag kraftens aura sänker sig medan han välkomnar den växande lärjungen. Han berättar att tiden är inne att ta till sig kattens perspektiv, en vild aspekt som är rovdjurslik och smidig. Liksom vid tidigare övergångsriter öppnar Dendrite vägen till förståelse, men resan att förkroppsliga och sprida denna kattande vilar helt på utövaren."}},faq={{q="Vem kallar på dig i The Great Cat Spirit?",a="Dina druidtränare kallar på dig på uppdrag av Dendrite Starblaze, en äldste och mentor i Nighthaven, i Moonglades avskilda tillflyktsort.",al={"vem ger uppdraget the great cat spirit","dendrite starblaze kallelse"}},{q="Var hittar man Dendrite Starblaze?",a="Dendrite Starblaze bor i byn Nighthaven, Moonglades centrala bosättning, som nås med druidisk teleportationsmagi.",al={"var finns dendrite starblaze","dendrite starblazes plats"}},{q="Vad är syftet med att träffa Dendrite Starblaze?",a="Dendrite förbereder dig på att kommunicera med och förstå naturens kattaspekt, så att du kan fortsätta din andliga utveckling efter att ha lärt dig björnens vägar.",al={"vad lär dendrite ut","uppdrag för kattformsutbildning"}},{q="Varför åkallar Dendrite Father Cenarius?",a="Dendrite åkallar Father Cenarius när han hälsar dig välkommen för att hedra halvguden och druidismens beskyddare, som först lärde de dödliga naturens och skepnadsskiftandets hemligheter.",al={"varför father cenarius","cenarius nämns av dendrite"}},{q="Hur reser druider till Moonglade när de blir kallade?",a="Druider använder sin medfödda andliga förmåga att kommunicera med naturen och teleportera direkt till Moonglade när deras mentorer kallar på dem.",al={"hur tar man sig till moonglade","druidteleportering till moonglade"}},{q="Hur hänger denna aspekt ihop med björnaspekten?",a="Druidisk lära närmar sig naturen ur olika perspektiv. Nybörjare börjar med att bemästra björnens uthålliga styrka innan de går vidare till kattens snabba rovdjursinstinkt.",al={"lore om kattform jämfört med björnform","björnform först"}}},fp="20,187,24.264.0,26.323.0,42.120.0,38.109.0,50.116.0,41.137.0,51.93.0,47.162.0"}
P.entries["quest:98397"] = {n="To Darnassus",s="To Darnassus är slutpunkten på en nattalvdruids resa för att samråda med The Great Cat Spirit. När du har visat dig värdig inför Dendrite Starblaze i Moonglade skickas du tillbaka till Cenarion Enclave för att bemästra konsten att anta kattform.",h="To Darnassus är slutpunkten på en nattalvdruids resa för att samråda med The Great Cat Spirit.",kw={"kattform","cenarion enclave","dendrite starblaze","the great cat spirit","mathrengyl bearwalker","moonglade","teldrassil","to darnassus"},ang={["class:Druid"]="Det här uppdraget markerar din övergång till att jaga från skuggorna och ger dig förmågan att kanalisera The Great Cat Spirit direkt genom kattform.",["faction:Alliance"]="Alliansens druider återvänder från Moonglades neutrala mark till Darnassus och stärker sitt hemlands magiska försvar.",["race:NightElf"]="När du återvänder till Darnassus hedrar du nattalvernas traditioner, som Cenarion Circle har bevarat under världsträdet Teldrassil."},sec={{t="Återvänd till Cenarion Enclave",b="Efter att ha samrått med The Great Cat Spirit under Dendrite Starblazes vägledning i Moonglade måste en nattalvdruid under utbildning återvända till Teldrassil. Starblaze anser att du har visat dig vara en värdig elev och skickar dig tillbaka till din huvudlärare, Mathrengyl Bearwalker, som väntar under trädkronorna i Cenarion Enclave i Darnassus."},{t="Kattens natur",b="När du anländer till Darnassus konstaterar Mathrengyl Bearwalker att du har tagit till dig The Great Cat Spirits visdom. Enligt honom ställs varje druidsläkte inför ett prov som formas av denna uråldriga varelse, som är lika lekfull som dödlig. När din förbindelse har knutits och din ande förberetts ger Mathrengyl dig de sista riterna som krävs för att anta kattens smidiga form."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här uppdraget avslutar ditt prov med The Great Cat Spirit. När du har utfört dina uppgifter åt Dendrite Starblaze i Moonglade skickas du tillbaka till Mathrengyl Bearwalker i Darnassus, så att han kan lära dig att anta kattform.",al={"varför göra uppdraget","syftet med to darnassus","uppdrag för kattform"}},{q="Vem skickar dig tillbaka till Darnassus?",a="Dendrite Starblaze, en högt uppsatt druid som bor i Nighthaven i den heliga fristaden Moonglade, ger dig uppdraget efter att du har fått The Great Cat Spirits välsignelse.",al={"vem startar uppdraget","uppdragsgivare"}},{q="Var hittar jag Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker finns i Cenarion Enclave, druidernas helgedom i Darnassus nordvästra kvarter på Teldrassil.",al={"mathrengyls plats","var finns bearwalker"}},{q="Vad betyder The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig, vild naturande som förkroppsligar smidiga, dödliga rovdjur. Druider måste vinna dess gunst och förstå dess dubbla natur, både lekfull och livsfarlig, innan de får kanalisera dess gestalt.",al={"kattandens bakgrund","vad är the great cat spirit"}},{q="Går alla druider igenom exakt samma prov?",a="Enligt Mathrengyl Bearwalker måste alla druider klara ett prov som The Great Cat Spirit ger dem för att bemästra dess form, men provens exakta utformning varierar mellan generationerna.",al={"är druidernas prov likadana","prov mellan generationer"}},{q="Kan andra än nattalver ta uppdraget?",a="Det här särskilda uppdraget är till för alliansens nattalvdruider som återvänder till Darnassus. Taurendruider följer sin egen väg och rapporterar tillbaka till sina egna lärare i Thunder Bluff efter besöket i Moonglade.",al={"är uppdraget bara för alliansen","kan taurener göra detta"}}},fx={["5fd4c60a"]={q="Varför skickar Dendrite Starblaze dig tillbaka till Darnassus?",a="Du har visat ditt värde inför The Great Cat Spirit i Moonglade, och dina prövningar under Dendrite Starblaze är över. Dendrites uppgift var att vaka över din gemenskap med den uråldriga anden. Nu väntar din första tränare, Mathrengyl Bearwalker, på dig i Darnassus för att hjälpa dig omsätta lärdomarna och slutligen bemästra kattens skepnadskonst.",al={"varför skicka till darnassus","dendrite starblazes motiv","varför återvända till mathrengyl"}}},fp="12,204,21.301.0,21.285.0,34.200.0,32.138.0,39.103.0,49.202.0,44.144.0,36.174.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="The Oracle Tree är ett uppdrag där en lovande äventyrare får i uppgift att söka kontakt med ett medvetet, uråldrigt träd. Genom att leta efter en barkbit som trädet med avsikt har fällt får resenärer ta emot dess rogivande telepatiska budskap och förbereda sig för större uppgifter.",h="The Oracle Tree är ett uppdrag där en lovande äventyrare får i uppgift att söka kontakt med ett medvetet...",kw={"oracle tree","oracle tree-bark","medvetet träd","fälld bark","telepati","the oracle tree"},ang={["class:Druid"]="Druider är naturligt mottagliga för medvetet växtliv och uråldriga träds röster. Därför blir kontakten med The Oracle Tree en förlängning av deras vördnad för naturen."},sec={{t="Ett kall till större uppgifter",b="The Oracle Tree är ett vist, medvetet träd som vakar över sin omgivning och vägleder resenärer som visar sitt värde. När det behöver en agent ute i världen fäller det med avsikt en bit bark i närheten. De som lägger märke till den kallas att träda fram, ett tecken på att deras inledande uppgifter är avslutade och att större ansvar väntar dem."},{t="Kontakt genom barken",b="The Oracle Tree talar inte med en vanlig, fysisk röst. I stället kan trädet nå direkt in i sökarens sinne när denne undersöker den fallna barkbiten. Dess närvaro är lugn och rogivande och sveper över lyssnaren som en mild bris genom ett lövverk. Trädet förmedlar tankar och önskningar utan att yttra ett enda ord."}},faq={{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett uråldrigt, medvetet träd som kan kommunicera telepatiskt med dem som befinner sig i närheten. När det vill förmedla ett budskap eller ge någon en uppgift fäller det en bit bark för att få värdiga äventyrares uppmärksamhet.",al={"vad är oracle tree","oracle trees bakgrund"}},{q="Hur kommunicerar The Oracle Tree?",a="I stället för att tala med hörbar röst förmedlar The Oracle Tree sina tankar telepatiskt. Den som undersöker den fallna barken hör en lugn, rogivande röst träda in i sitt sinne, som en mild bris som susar genom lövverket.",al={"hur talar oracle tree","oracle trees kommunikation"}},{q="Varför behöver du hitta barken från The Oracle Tree?",a="Trädet fäller en bit bark särskilt när det har ett syfte eller en uppgift som måste tas om hand. När du undersöker barken får trädet en fokalpunkt för att förmedla sin telepatiska vägledning.",al={"varför hitta barken","syftet med den fallna barken"}},{q="Vem leder dig till The Oracle Tree?",a="En lokal uppsyningsman eller vårdare som har följt dina framgångar inser att större uppgifter väntar dig. När personen får syn på den nyfallna barken leder hen dig till trädet för att ta emot dess vägledning.",al={"vem skickar dig till oracle tree","uppdragsgivare för oracle tree"}},{q="Vad är syftet med uppdraget The Oracle Tree?",a="Uppdraget inleder kontakten mellan en erfaren resenär och själva trädet. Genom att söka upp barken öppnar du ditt sinne för trädets budskap och får veta vilken större uppgift det vill att du utför.",al={"målet med oracle tree-uppdraget","vad vill oracle tree"}},{q="Var hittar du barken från The Oracle Tree?",a="Den fällda barken ligger på marken alldeles intill The Oracle Tree, i väntan på att undersökas av någon som är tillräckligt mottaglig för att höra dess budskap.",al={"var hittar man oracle tree-bark","barkens plats"}}},fp="15,181,24.291.0,26.219.0,24.202.0,37.174.0,47.141.0,35.166.0,49.157.0,36.112.0"}
P.entries["quest:984"] = {n="How Big a Threat?",s="How Big a Threat? är ett alliansuppdrag som Terenthis ger i Auberdine. Efter att ha sett furbolgarnas vansinne få fäste över Teldrassil skickar nattalvdruiden ut spejare för att undersöka lokala furbolgbosättningar i Darkshore och ta reda på om samma mörka besmittelse har korsat havet.",h="How Big a Threat?",kw={"ameth'aran","auberdine","fördärv","darkshore","furbolg","teldrassil","terenthis","hot"},ang={["class:Druid"]="Furbolgarna har starka band till naturen och vildmarkens uråldriga andar, så deras plötsliga fall i fördärv är ett allvarligt bekymmer för druiderna som har till uppgift att läka Kalimdors balans.",["faction:Alliance"]="Auberdine är alliansens främsta port till norra Kalimdors fastland. Att skydda staden från hot i vildmarken är avgörande för regionens säkerhet och försörjning.",["race:NightElf"]="För kaldorei är det både en bitter tragedi och en omedelbar fara för heliga marker att se uråldriga allierade som furbolgarna falla i irrationellt mörker så kort efter det tredje kriget."},sec={{t="Skuggor över havet",b="Nattalverna i norra Kalimdor har länge haft vänskapliga eller fredliga relationer med ursprungsbefolkningens furbolgstammar. Men efter det tredje kriget började märkliga förvridningar rubba furbolgarnas sinnen i Teldrassil, vilket ledde till våldsamma kidnappningar och vilda attacker mot deras forna allierade. Druiden Terenthis, som är stationerad i Auberdine, fruktar att denna olycksbådande plåga inte är begränsad till Världsträdet, utan sprider sig bland fastlandets stammar längs Darkshores dimhöljda kuster."},{t="En storm samlas",b="Spaning vid ett furbolgläger nära ruinerna av Ameth'Aran bekräftar Terenthis värsta farhågor. Furbolgarna där uppvisar oberäknelig, fientlig aggressivitet och bär tydliga tecken på samma fördärv som plågar norr. Deras närhet till Auberdine gör dem till ett akut försvarshot mot alliansens bosättning i stället för fredliga grannar i vildmarken."}},faq={{q="Vem är Terenthis?",a="Terenthis är en nattalvdruid stationerad i kuststaden Auberdine. Han hemsöks av berättelser om nattalver som angripits och tillfångatagits av vansinniga furbolgar runt Teldrassil, och arbetar för att bevaka och hejda nya hot i Darkshore.",al={"terenthis uppdragsgivare","vem ger uppdraget how big a threat","terenthis auberdine"}},{q="Varför blir furbolgarna i Darkshore fientliga?",a="Terenthis har sett tecken på fördärv i Darkshore och misstänker att furbolgarna kan vara drabbade, liksom vissa på Teldrassil. Han ber dig undersöka deras läger eftersom han ännu inte har fastställt om tecknen är utbredda.",al={"varför är furbolgarna galna","fördärvade furbolgar i darkshore","furbolgarnas fördärv"}},{q="Var ligger det fördärvade furbolglägret?",a="Lägret ligger en bit inåt landet i centrala Darkshore, strax norr om de uråldriga högalveruinerna i Ameth'Aran och sydöst om Auberdine.",al={"lägrets plats","var ligger furbolglägret","platsen för how big a threat"}},{q="Hur hänger detta samman med händelserna på Teldrassil?",a="På Teldrassil kidnappade och skadade flera fördärvade furbolgar nattalvsnärvakter och civila. Terenthis hänvisar till de nyligen genomförda räddningarna när han vill ta reda på om fastlandet i Darkshore står inför exakt samma kris.",al={"samband med teldrassil","furbolgar på teldrassil","varför nämner terenthis teldrassil"}},{q="Vad händer efter att du rapporterat tillbaka till Terenthis?",a="Rapportera alla tecken på fördärv till Terenthis i Auberdine. Hans reaktion på fynden får du se när du återvänder.",al={"nästa uppdrag","vad följer efter how big a threat","fortsättning på uppdraget"}},{q="Varför oroar sig nattalverna så mycket för furbolgläger nära Auberdine?",a="Auberdine är alliansens främsta hamn och försörjningsled på fastlandet. Djupt fördärvade, fientliga stammar inom anfallsavstånd gör handelsvägarna, spejargrupperna och själva staden sårbara för plötsliga angrepp.",al={"hot mot auberdine","varför bry sig om furbolgarna"}}},fx={["0269df0a"]={q="Varför vill Terenthis att detta görs?",a="Terenthis svor personligen att hindra mer blodspillan efter att hans nattalvskamrater behövt räddas från fördärvade furbolger på Teldrassil. Han har redan märkt svaga tecken på att korruptionen nått Darkshore, och fruktar att smittan kan spridas obemärkt genom de lokala furbolgstammarna. Genom att skicka dig för att spana på deras läger hoppas han avgöra om faran redan står vid Auberdines tröskel innan fler liv går förlorade.",al={"terenthis motiv","varför undersöka furbolger i darkshore","varför bryr sig terenthis"}},["1e1a0eb0"]={q="Vem skickas du för att undersöka?",a="Du skickas för att spana på de lokala furbolgstammarna i Darkshore. Många furbolgklaner levde en gång fredligt eller tillbakadraget sida vid sida med nattalverna, men mörka krafter har börjat förvrida deras sinnen och driva dem till vansinne. Terenthis skickar dig för att inspektera deras bosättningar och ta reda på om denna plåga fått fäste bland stammarna som lever farligt nära Auberdine.",al={"vem undersöker jag","vilket furbolgläger","vem är målet"}}},fp="17,234,22.337.0,17.259.1,17.193.0,50.221.0,42.132.0,45.202.0,47.90.0,68.180.0"}
P.entries["quest:98403"] = {n="Twisted Hatred",s="Twisted Hatred är ett uppdrag i Teldrassil som avslöjar vem som styr Lord Melenas. Äventyrare tar sig in i The Cleft, nordväst om Dolanaar, för att möta Xethorr the Wicked och utrota hans förvridna spindlar innan hans onda planer sprider sig bland trädets grenar.",h="Twisted Hatred är ett uppdrag i Teldrassil som avslöjar vem som styr Lord Melenas.",kw={"befouled webwood","the cleft","dolanaar","lord melenas","mature fel moss","satyr","tallonkai swiftroot","teldrassil","twisted hatred","xethorr the wicked"},ang={["class:Druid"]="När Teldrassils naturliga spindlar förvandlas till ett fördärvat yngel rubbas naturens balans, och Cenarionförsvararna måste rena platsen.",["faction:Alliance"]="Genom att hjälpa Tallonkai Swiftroot skyddar du bosättningen Dolanaar mot satyrernas växande intriger i Alliansens främsta fristad på Kalimdor.",["race:NightElf"]="Teldrassil är hjärtat i kaldoreiernas återkomst. Därför är det en direkt förolämpning och ett hot mot ditt folk när demoniskt fördärv frodas bland de inhemska djuren i The Cleft."},sec={{t="En skuggornas mästare",b="Upptäckten att Lord Melenas inte agerade på egen hand avslöjar en mörkare strömning i Teldrassils vildmark. Bakom Melenas stod Xethorr the Wicked, en förhärdad satyr som drog i trådarna från skogens skuggor för att undergräva världsträdets fridfulla grenar."},{t="The Clefts fördärvade yngel",b="Xethorr tog sin tillflykt nordväst om Dolanaar, i den avskilda enklaven som kallas The Cleft, och riktade sedan blicken mot Teldrassils inhemska spindlar. Genom att förvrida lokala Webwood-spindlar till fördärvade bestar försökte satyren använda deras gift i lömska demoniska planer. Tallonkai Swiftroot skickade äventyrare för att decimera ynglet och ta Xethorrs Mature Fel Moss innan fördärvet kunde sprida sig ytterligare."}},faq={{q="Vem är Xethorr the Wicked?",a="Xethorr the Wicked är en illvillig satyr som ligger bakom fördärv i Teldrassil. Han styrde Lord Melenas och slog sig ner i The Cleft, där han förvrider inhemska spindlar och använder Mature Fel Moss för sina ondskefulla planer.",al={"vem är xethorr","xethorr the wicked","vem är satyren"}},{q="Var ligger The Cleft?",a="The Cleft är ett avskilt område djupt inne i skogen nordväst om Dolanaar i Teldrassil. Där har Xethorr the Wicked och hans fördärvade yngel slagit sig ner.",al={"var ligger the cleft","the clefts läge","var hittar jag xethorr"}},{q="Varför är Teldrassils spindlar fördärvade?",a="Befouled Webwoods är inhemska spindlar från Teldrassil som Xethorr the Wicked har fördärvat. Satyren förvrängde deras sinnen och kroppar för att skörda deras gift till en avskyvärd demonisk plan.",al={"varför förändrades spindlarna","vad är befouled webwoods","befouled webwoods bakgrund"}},{q="Vem är Tallonkai Swiftroot?",a="Tallonkai Swiftroot är en nattalvsväktare stationerad i byn Dolanaar i Teldrassil. Han ger äventyrare i uppdrag att röja undan demoniskt inflytande i skogarna omkring byn.",al={"vem gav uppdraget","var finns tallonkai","tallonkai swiftroots roll"}},{q="Vad är Mature Fel Moss?",a="Mature Fel Moss är ett fördärvande växtprov som Xethorr the Wicked bär på. Tallonkai Swiftroot vill få tag på det för att ta reda på mer om satyrens verkliga motiv och pågående verksamhet i Teldrassil.",al={"mature fel moss","varför samla fel moss","vad är fel moss"}},{q="Hur var Lord Melenas inblandad?",a="Lord Melenas handlade inte av egen illvilja, utan på direkt uppmaning av Xethorr the Wicked. Det avslöjar en samordnad satyrkonspiration i Teldrassil.",al={"melenas koppling","vem är lord melenas","melenas och xethorr"}}},fp="14,191,18.200.0,31.300.1,26.206.0,27.138.0,43.158.0,27.158.0,28.180.0,30.147.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit är en helig prövning i list och smygande för blivande druider. De invigda måste bege sig till den närbelägna Stormrage Barrow Den för att hämta tre uråldriga reliker och samtidigt smita förbi fientliga, rasande andar. Den som klarar denna andliga rit bevisar sitt mästerskap i kattens dygder: smygande, ursinne och list. Då får de välsignelsen att anta kattgestalt.",h="The Great Windborne Cat Spirit är en helig prövning i list och smygande för blivande druider.",kw={"avatar of saeyleenan","kattgestalt","druidprövning","rasande andar","relic of the claw","relic of the fang","relic of the silent shadow","saeyleenan","stormrage barrow den","the great windborne cat spirit"},ang={["class:Druid"]="Denna rit är en viktig milstolpe för druider som lär sig att kanalisera vildkattens smidighet, smygförmåga och rovdjursinstinkt. De måste bevisa att de besitter list och ursinne innan anden skänker sin välsignelse till formskiftet.",["race:NightElf"]="Stormrage Barrow Den bär namnet från en av de mest framstående nattalviska druidiska släktlinjerna. Att utforska dess djup knyter Kaldorei-utövare direkt till folkets uråldriga gravkammartradition och förfädersandar."},sec={{t="Prövningen i list och smygande",b="För att dra kraft ur den stora kattandens makt måste aspiranter bevisa att de har rovdjurets temperament. Sann harmoni med katten kräver förståelse för list och tålamod, tillsammans med explosivt ursinne när den trängs in i ett hörn. Anden skänker inte sin gåva lättvindigt till dem som bara kräver makt. I stället prövar den om en sökare kan tänka, röra sig och slå till som vildmarkens kattjägare. Först när en invigd visar dessa inre egenskaper kan den hoppas förtjäna rätten att anta kattens fysiska gestalt."},{t="Stormrage Barrow Den",b="Provet skickar sökare in i dunklet i den närbelägna Stormrage Barrow Den, strax öster om andens avatar. Djupt inne i de underjordiska salarna finns tre heliga föremål: Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow. Men det är långt ifrån enkelt att hämta dem. Gravkammaren har blivit full av rasande andar som våldsamt angriper alla inkräktare de får syn på. För att överleva grottan och nå relikerna kan en sökare inte förlita sig enbart på råstyrka, utan måste röra sig varsamt genom mörkret."},{t="Saeyleenans avatar",b="I centrum för denna prövning står Avatar of Saeyleenan, den fysiska gestalt genom vilken The Great Windborne Cat Spirit talar till unga invigda. Eftersom otränade sökare saknar en erfaren jägares naturliga smygförmåga erbjuder en staty vid gravkammarens ingång en tillfällig välsignelse som döljer dem. De som lyckas smita förbi de ursinniga andarna och återvända med alla tre reliker bevisar att de har tagit till sig rovdjurets lärdomar. Som svar erkänner avataren deras värdighet och skänker välsignelsen som krävs för att anta kattgestalt."}},faq={{q="Vad är The Great Windborne Cat Spirit?",a="The Great Windborne Cat Spirit är en vild beskyddare som vägleder unga druider i att bemästra kattens skepnadsskifte. Anden visar sig genom Avatar of Saeyleenan och förkroppsligar rovdjurets främsta dygder: list, smygande och ursinne. I stället för att fritt skänka sin gestalt prövar den aspiranter genom en helig rit för att försäkra sig om att de respekterar kattens rovdjursinstinkter och natur.",al={"vindburen kattande","vem är saeyleenan","kattandens historia"}},{q="Vad är Avatar of Saeyleenan?",a="Avatar of Saeyleenan är The Great Windborne Cat Spirits fysiska gestalt och språkrör. Avataren står väster om Stormrage Barrow Den och vakar över områdets druidiska prövning. Den ger sökare i uppgift att hämta gravkammarens stulna eller gömda reliker och bedömer om en invigd har visat tillräckligt med smygförmåga och list för att förtjäna kattens välsignelse.",al={"avatar of saeyleenan","vem är avatar saeyleenan","saeyleenan npc"}},{q="Vilka reliker krävs för prövningen?",a="Prövningen kräver att tre särskilda reliker hämtas från Stormrage Barrow Den: Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow. Tillsammans symboliserar dessa föremål de fysiska vapen och den svårfångade smygförmåga som utmärker kattandens gestalt. De visar att den invigde vördar rovdjurets alla sidor.",al={"tre reliker","relic of the claw","stormrage barrow den reliker"}},{q="Var ligger Stormrage Barrow Den?",a="Stormrage Barrow Den ligger strax öster om Avatar of Saeyleenan. De underjordiska kamrarna är druidprövningens testområde och rymmer de tre heliga relikerna. Invigda måste bege sig ner i de mörka salarna och undvika de farliga, rasande andar som strövar i tunnlarna.",al={"stormrage barrow den plats","var ligger gravkammaren","var hittar man relikerna"}},{q="Varför vaktar rasande andar gravkammaren?",a="Stormrage Barrow Den har blivit övertagen av mäktiga, rasande andar som angriper alla levande inkräktare de får syn på. Dessa fientliga varelser är ingen villig vaktstyrka, utan utgör en aktiv fara i gravkammaren. Därför måste blivande druider använda list och smygförmåga för att hämta relikerna i stället för att ta strid direkt.",al={"varför är andarna rasande","rasande andar i gravkammaren","gravkammarens väktare"}},{q="Hur smiter sökare förbi de rasande andarna?",a="En stenstaty vid ingången till Stormrage Barrow Den skänker sökare en tillfällig välsignelse i smygande. Unga invigda har ännu inte förtjänat sin egen medfödda kattgestalt eller förmåga att smyga fram. Därför gör denna skyddande förtrollning att de kan smita förbi de vaksamma, fientliga andarna utan att upptäckas och hämta relikerna.",al={"hur smyger man i gravkammaren","smygandevälsignelse från statyn","hur undviker man rasande andar"}},{q="Vilken belöning eller välsignelse får man när prövningen är avklarad?",a="När sökaren återlämnar Relic of the Fang, Relic of the Claw och Relic of the Silent Shadow anser Avatar of Saeyleenan att sökaren förtjänar The Great Windborne Cat Spirits välsignelse. Riten visar att den invigde förstår kattens sanna natur och ger den andliga bekräftelse som krävs för att anta rovdjurets gestalt.",al={"prövningens belöning","vad får man från kattanden","kattandens välsignelse"}}},fp="30,237,32.343.0,24.379.0,24.452.0,38.263.0,33.273.0,39.281.0,42.213.0,48.273.0,46.264.0,61.320.0"}
P.entries["quest:98407"] = {n="Show of Force",s="Show of Force är ett defensivt uppdrag för Alliansen i Redridge Mountains, som Deputy Feldon har gett. För att hejda gnollflockar som tränger fram mot Lakeshire skickas äventyrare ut för att jaga gnoll thrashers och samla in deras taggiga halsband, så att vidare intrång i mänskliga bosättningar avskräcks.",h="Show of Force är ett defensivt uppdrag för Alliansen i Redridge Mountains, som Deputy Feldon har gett.",kw={"deputy feldon","gnoll thrasher","gnoller","lakeshire","redridge mountains","show of force","taggigt halsband"},ang={["class:Warrior"]="Gnoller ger bara vika för uppvisningar av direkt, förkrossande våld. Därför är en rak militär disciplin vid frontlinjen det bästa sättet att bryta deras led.",["faction:Alliance"]="Lakeshire är en av Alliansens östligaste utposter i södra Eastern Kingdoms. Att säkra dess gränser mot vilddjursangrepp är avgörande för stabiliteten i området.",["race:Human"]="Redridges nybyggare och stadsbor är undersåtar av Stormwind, lämnade farligt oskyddade och beroende av sina fränder för att slå tillbaka vilda plundrare."},sec={{t="Ett djärvt intrång",b="Redridge Mountains har länge gett skydd åt vilda gnollstammar, men de har blivit allt djärvare. I stället för att hålla sig isolerade högt uppe bland de klippiga kullarna har gnollernas plundrarflockar slagit läger oroväckande nära Lakeshire och de avlägsna mänskliga gårdarna. Stormwinds militär är hårt ansträngd och kan inte avvara förstärkningar till landsbygdens gränstrakter, så de lokala myndigheterna måste förlita sig på förbipasserande äventyrare för att säkra området innan de framryckande banden vågar anfalla själva staden."},{t="Tala deras språk",b="Deputy Feldon vet att gnoller är brutala och oorganiserade varelser som knappt respekterar något utöver ren militär överlägsenhet. Diplomatiska vädjanden och halvhjärtade åtgärder hjälper inte om de ska drivas tillbaka ut i vildmarken. Feldon vill slå mot deras våldsammaste förtrupper, gnoll thrashers, och ta deras taggiga halsband som ett bistert bevis på överlägsenhet. Genom att slå ut deras främsta krigare och visa upp troféerna från deras nederlag hoppas Lakeshires försvarare skrämma de överlevande flockarna till reträtt upp i högländerna."}},faq={{q="Vem erbjuder uppdraget och var finns de?",a="Uppdraget erbjuds av Deputy Feldon, en stadsvakt som är stationerad vid områdets gräns nära Lakeshire i Redridge Mountains.",al={"uppdragsgivare","deputy feldons plats","vem ger show of force"}},{q="Varför tränger gnollerna så nära Lakeshire?",a="Gnoller är aggressiva opportunister som prövar sina gränser. Eftersom Lakeshire kämpar med försvaret och får lite militär hjälp från Stormwind har gnollerna blivit så djärva att de slagit upp jaktläger alldeles utanför de mänskliga bosättningarna.",al={"varför anfaller gnollerna","gnollhot i redridge","varför är gnollerna nära"}},{q="Vilka fiender måste besegras i det här uppdraget?",a="Uppdraget riktar in sig på gnoll thrashers, de farligare och mer aggressiva anfallsgrälarna i de lokala flockarna, som bär tunga taggiga halsband.",al={"vilka gnoller","vilka fiender ska dödas","gnoll thrashers"}},{q="Varför vill Deputy Feldon särskilt ha taggiga halsband?",a="Gnoller styrs av en brutal hierarki och råstyrka. Att ta halsbanden från deras thrashers visar upp direkt våldsam styrka och ska skrämma de överlevande gnollerna till att retirera upp i bergen.",al={"varför taggiga halsband","halsbandets syfte","varför ta halsband"}},{q="Kan Stormwind skicka soldater för att ta hand om gnollerna?",a="Stormwind har i stort sett lämnat Redridge att försvara sig självt. Huvudstaden står inför inre instabilitet och brist på trupper i hela riket och har skickat nästan inga förstärkningar, så de lokala deputerade tvingas förlita sig på självständiga hjältar.",al={"stormwinds hjälp till redridge","varför ingen stormwind-armé","var finns vakterna"}},{q="Var brukar gnollerna slå läger i Redridge?",a="Gnollernas läger ligger utspridda bland kullarna och de låga höjdryggarna intill Lake Everstill och längs vägarna österut mot Stonewatch-området.",al={"gnolläger","var hittar man gnoller","gnollplatser i redridge"}}},fp="13,131,19.326.0,23.332.0,49.102.0,49.164.0,50.109.0,56.119.0,55.129.0,52.109.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="The Treaty of Understanding är en forntida dvärgtavla som beskriver det historiska fredsavtalet mellan Bronzebeard- och Wildhammer-klanerna efter War of the Three Hammers. Den återfanns i underjordiska djup och fördes inför King Magni Bronzebeard. Artefakten bevarar ett avgörande ögonblick i dvärgarnas historia och visar samtidigt den bittra spricka som höll Dark Iron-klanen utanför freden.",h="The Treaty of Understanding är en forntida dvärgtavla som beskriver det historiska fredsavtalet mellan...",kw={"dark iron","ironforge","madoran bronzebeard","magni bronzebeard","fredsavtal","treaty of understanding","war of the three hammers","wildhammer"},ang={["faction:Alliance"]="Den historiska freden mellan Bronzebeard- och Wildhammer-dvärgarna lade grunden för deras moderna samarbete inom Grand Alliance.",["race:Dwarf"]="Den här stentavlan är ett påtagligt vittnesmål om dvärgarnas försoning och visar hur dina förfäder lade fejden åt sidan efter kampen om berget."},sec={{t="En relik som försonade dvärgar",b="The Treaty of Understanding återfanns djupt inne i ett forntida valv. Den är en historisk stentavla som dokumenterar det formella slutet på fientligheterna mellan dvärgklaner. Den härrör från den oroliga tiden efter War of the Three Hammers och markerar ögonblicket då fred slöts mellan Bronzebeard- och Wildhammer-klanerna, efter att Bronzebeard-klanen säkrat kontrollen över Ironforge-berget."},{t="Den osignerade freden",b="När den återfunna tavlan visas upp känner King Magni Bronzebeard igen den som ett verk av sin förfader Madoran Bronzebeard, den förste Bronzebeard-kungen av Ironforge. Dokumentet bär underskrifterna från både Bronzebeard- och Wildhammer-ledarna, men saknar tydligt Dark Iron-klanens märke. Det vittnar än i dag om den bestående sprickan mellan Dark Irons och deras släktingar från berget."}},faq={{q="Vad är The Treaty of Understanding?",a="The Treaty of Understanding är en forntida dvärgisk stentavla som återfanns i djupa valv. Den beskriver det formella fredsavtalet mellan Bronzebeard- och Wildhammer-klanerna, som slöts direkt efter War of the Three Hammers.",al={"vad är treaty of understanding","avtalstavla","vad är det här för avtal"}},{q="Vem skapade avtalet?",a="Avtalet skrevs i tiden efter War of the Three Hammers, under Madoran Bronzebeards regeringstid. Han var den förste Bronzebeard-kungen av Ironforge, efter att de tre klanerna kämpat om berget.",al={"vem skrev treaty of understanding","vem skapade treaty of understanding","vem utformade avtalet"}},{q="Varför skrev Dark Iron-klanen inte under avtalet?",a="Dark Iron-klanen vägrade acceptera fred efter att Bronzebeard-klanen tagit kontroll över Ironforge. Därför skrev bara Bronzebeard- och Wildhammer-klanerna under avtalet, vilket lämnade Dark Irons isolerade och fientligt inställda.",al={"varför skrev dark iron inte under","skrev dark iron under avtalet","dark irons saknas på avtalet"}},{q="Vem är intresserad av The Treaty of Understanding?",a="Tavlan överlämnas till King Magni Bronzebeard i High Seat i Ironforge. Han värdesätter den som en ovärderlig relik efter sin förfader Madoran och som ett stycke dvärghistoria.",al={"vem vill ha avtalet","vem ska jag lämna treaty of understanding till","var lämnar jag in avtalet"}},{q="Vad var War of the Three Hammers?",a="War of the Three Hammers var ett bittert inbördeskrig mellan dvärgklanerna Bronzebeard, Wildhammer och Dark Iron om kontrollen över Ironforge-berget. Bronzebeard-klanen segrade och tog berget, medan de andra klanerna drevs bort.",al={"vad var war of the three hammers","dvärgarnas inbördeskrig","three hammers-kriget"}},{q="Vem var Madoran Bronzebeard?",a="Madoran Bronzebeard var förfader till King Magni Bronzebeard och den förste Bronzebeard-kungen som styrde Ironforge efter inbördeskriget mellan de tre dvärgklanerna.",al={"vem är madoran bronzebeard","madoran bronzebeard","magni förfader madoran"}}},fp="27,209,33.315.0,18.304.0,36.207.0,23.189.0,47.191.0,49.145.0,38.214.0,28.159.0"}
P.entries["quest:98424"] = {n="Fizsprockets Notizen",s="I Venture Co. Mine söker Morin Cloudstalker efter de sidor ur anteckningsboken som fortfarande saknas. De innehåller viktig information om företagets planer i området.",h="I Venture Co.",kw={"bloodhoof village","fizsprocket","gruva","morin cloudstalker","anteckningsbok","sidor","venture co."},sec={{t="De saknade sidorna",b="Morin Cloudstalker väntar i Bloodhoof Village på de sidor som fortfarande saknas ur Fizsprockets anteckningsbok. Du har hittat hopvikta sidor i Fizsprockets ficka, och de återstående anteckningarna finns i Venture Co. Mine. Informationen i dem kan vägleda nästa steg."}},faq={{q="Vilka sidor letar jag efter?",a="Du letar efter de återstående sidorna ur Overseer Fizsprockets anteckningsbok.",al={"fizsprockets anteckningar","anteckningsbokens sidor","saknade anteckningar"}},{q="Var finns resten av anteckningarna?",a="De återstående sidorna finns i Venture Co. Mine.",al={"var finns sidorna","venture co. mine","anteckningsbokens plats"}},{q="Vem vill ha sidorna?",a="Morin Cloudstalker väntar på sidorna i Bloodhoof Village.",al={"vem behöver anteckningarna","morins begäran","vem ska få sidorna"}},{q="Vad står det i Fizsprockets anteckningsbok?",a="Anteckningsboken innehåller viktig information om Venture Co. och dess planer i området.",al={"vad säger anteckningarna","fizsprockets anteckningsbok","information om venture co."}}},fp="20,158,17.257.0,28.77.0,32.48.0,20.65.0,36.96.0"}
P.entries["quest:98427"] = {n="Ceasing Operations",s="Morin Cloudstalker uppmanar dig att stoppa avverkningsmaskinen innan den fäller ännu ett träd. Han ber dig att samla allierade, återvända till gruvan i nordost och hindra den från att fälla fler träd.",h="Morin Cloudstalker uppmanar dig att stoppa avverkningsmaskinen innan den fäller ännu ett träd.",kw={"bloodhoof village","earth mothers barn","mechanoroderschlüssel","gruva","morin cloudstalker","nordost","avverkningsmaskin","träd"},ang={["race:Tauren"]="Som tauren delar du Morins oro för lundarna som skyddat Earth Mothers barn och för de ungas säkerhet nära hemmet."},sec={{t="Ett hot mot hemmet",b="Morin har hört talas om avverkningsmaskinen som beskrivs på en sida. Sådana maskiner kan fälla en skog långt snabbare än yxor och muskelkraft. Lundar som skyddat Earth Mothers barn i evigheter kan försvinna på några dagar. Han ber dig att samla allierade, återvända till gruvan i nordost och se till att maskinen inte fäller fler träd. Ta med Mechanoroderschlüssel till Morin i Bloodhoof Village."}},faq={{q="Vad ber Morin mig att göra?",a="Morin ber dig att samla allierade, återvända till gruvan i nordost och hindra avverkningsmaskinen från att fälla fler träd.",al={"vad vill morin","morins begäran","uppgift med avverkningsmaskinen"}},{q="Varför är avverkningsmaskinen ett hot?",a="Morin säger att avverkningsmaskiner kan fälla en skog långt snabbare än yxor och muskelkraft. De kan förstöra lundar som skyddat Earth Mothers barn.",al={"varför stoppa avverkningsmaskinen","avverkningsmaskinens fara","vad kan den göra"}},{q="Vart vill Morin att jag ska gå?",a="Morin ber dig att återvända till gruvan i nordost.",al={"var ligger gruvan","gruvan i nordost","vart återvända"}},{q="Vad ska jag ta med tillbaka till Morin?",a="Ta med Mechanoroderschlüssel till Morin Cloudstalker i Bloodhoof Village.",al={"vilket föremål till morin","mechanoroderschlüssel","nyckel till morin"}},{q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker ber dig att hindra avverkningsmaskinen från att fälla träd nära taurenfolkets hem.",al={"vem är morin","morin cloudstalker","personen morin"}}},fp="18,186,16.385.0,30.116.0,29.148.0,31.54.0,30.76.0,26.89.0"}
P.entries["quest:98430"] = {n="Die Langläufer",s="Vid Bleachmane Rock är Perith Stormhoof fångad sedan ett fredsförsök med gnollerna slutade i våld. Cairne Bloodhoof skickade spejaren, och hans trygga återkomst är viktig för taurenfolket.",h="Vid Bleachmane Rock är Perith Stormhoof fångad sedan ett fredsförsök med gnollerna slutade i våld.",kw={"bleachmane rock","cairne bloodhoof","gnoller","long runners","fredsförsök","perith stormhoof","thunder bluff"},ang={["race:Tauren"]="Som tauren hjälper du Cairne Bloodhoofs betrodda spejare. Hans uppdrag är viktigt för taurenfolket."},sec={{t="En spejare i fara",b="Cairne Bloodhoof skickade Perith Stormhoof för att träffa gnollerna som slagit sig ner här. Perith är en av Cairnes Long Runners, så han kan inte berätta om hela uppdraget. Fredsförsöket slutade i våld, och han fruktar att gnollerna kommer att äta upp honom om han stannar över natten. Du ombeds hjälpa honom att fly från Bleachmane Rock och meddela Cairne i Thunder Bluff att han är i säkerhet."},{t="Cairnes tack",b="Cairne är lättad över att Perith är i säkerhet. Han kallar spejaren sin mest betrodda och säger att uppdraget är mycket viktigt. Cairne tackar dig för att du riskerade livet för att rädda Perith. Du har gjort taurenfolket en större tjänst än du anar."}},faq={{q="Vem är Perith Stormhoof?",a="Perith Stormhoof är en av Cairne Bloodhoofs Long Runners, hövdingens spejare.",al={"vem är perith","stormhoof spejare","mannen i long runners"}},{q="Varför är Perith vid Bleachmane Rock?",a="Cairne skickade Perith för att träffa gnollerna som slagit sig ner där, men Perith kan inte berätta om hela uppdraget.",al={"varför är perith där","bleachmane rock","periths uppdrag"}},{q="Vad hände med fredsförsöket?",a="Gnollerna besvarade Long Runners fredsförsök med våld, vilket försatte Perith i fara.",al={"gnoller fred","varför är perith fångad","fred med gnoller"}},{q="Vad ber Cairne mig att göra?",a="Du ombeds hjälpa Perith att fly från Bleachmane Rock och berätta för Cairne i Thunder Bluff att han är i säkerhet.",al={"hjälpa perith","stormhoofs uppgift","få ut honom"}}},fp="15,196,17.410.0,12.263.1,25.79.0,39.122.0,31.89.0,29.120.0"}
P.entries["quest:98435"] = {n="Thunderhorns Bericht",s="Mull skickar dig för att överlämna Thunderhorns rapport till ärkedruiden Hamuul Runetotem i Thunder Bluff. De äldste behöver få höra vad din hjälp har åstadkommit.",h="Mull skickar dig för att överlämna Thunderhorns rapport till ärkedruiden Hamuul Runetotem i Thunder Bluff.",kw={"elder rise","hamuul runetotem","mulgore","rapport","källor","tauren","thunder bluff","thunderhorn"},sec={{t="Rapporten",b="Du överlämnar Thunderhorns rapport till Hamuul på Elder Rise i östra Thunder Bluff. Rapporten gäller Mulg ores källor, som håller taurenfolket och djuren de är beroende av för mat, kläder och sällskap vid liv."}},faq={{q="Vem behöver Thunderhorns rapport?",a="Ärkedruiden Hamuul Runetotem i Thunder Bluff behöver Thunderhorns rapport.",al={"vem får rapporten","rapport till hamuul","thunderhorns rapport"}},{q="Var finns Hamuul Runetotem?",a="Hamuul finns på Elder Rise i östra Thunder Bluff.",al={"var finns hamuul","hamuuls plats","hitta hamuul"}},{q="Varför är rapporten viktig?",a="Mulg ores källor håller taurenfolket och djuren de är beroende av för mat, kläder och sällskap vid liv.",al={"varför rapporten är viktig","vad är källorna till för","mulg ores källor"}},{q="Vad säger Hamuul om källorna?",a="Hamuul säger att källorna håller både taurenfolket och djuren de är beroende av vid liv.",al={"vad säger hamuul","källor och djur","vad sa hamuul"}}},fp="20,151,10.220.0,33.73.0,26.53.0,27.106.0,39.79.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="A Lack of Virtue är ett leveransuppdrag om ett långlivat småaktigt agg mellan två sjömän som spelar kort, Tom Half-fish och Bart Tidewater. Resande fraktar en inslagen gåva över havet till Menethil Harbor och hamnar mitt i en ömsesidig anklagelse om fusk kring hur Maiden's Virtue vanns.",h="A Lack of Virtue är ett leveransuppdrag om ett långlivat småaktigt agg mellan två sjömän som spelar kort, Tom...",kw={"a lack of virtue","bart tidewater","maidens virtue","menethil harbor","poker","tanaris","tom half-fish","tom's gift","wetlands"},ang={["faction:Alliance"]="Alliansresande som passerar Menethil Harbor stöter ofta på Bart Tidewater när han skäller order till sin besättning. Leveransen blir ett snabbt avbrott medan du väntar på transport över Great Sea."},sec={{t="Ett bittert agg",b="A Lack of Virtue kretsar kring en bitter rivalitet mellan två saltstänkta sjöfarare och spelare: Tom Half-fish och Bart Tidewater. Tom värvar förbipasserande resande för att frakta ett inslaget paket över vattnet till Bart i Menethil Harbor, som en småaktig, illvillig pik mot sin tidigare följeslagare. På vägen varnar Tom för att Bart inte alls är någon riktig sjöbuse, utan en före detta skådespelare som fuskade i kortspel för att köpa sitt befäl."},{t="Korten på bordet",b="När Bart Tidewater får Tom's Gift på kajen i Menethil Harbor blir han rasande bara den gamle bekantens namn nämns. Bart vänder genast anklagelsen mot Tom och svär på att det var Tom som fuskade i kortspel och att Bart bara vann tillräckligt med mynt för att köpa Maiden's Virtue efter att deras pokerkrets uteslutit Half-fish. Trots sitt häftiga vredesutbrott hejdar sig Bart snart, ber kuriren om ursäkt för sitt rytande och hälsar resanden välkommen till hamnen."}},faq={{q="Vem är Bart Tidewater?",a="Bart Tidewater är den självutnämnde kaptenen på Maiden's Virtue, som ligger förtöjd i Menethil Harbor. Enligt hans gamle bekant Tom Half-fish var Bart ursprungligen skådespelare och köpte sitt skepp för vinster från pokerspel, fast båda männen anklagar varandra för att fuska i kortspel.",al={"vem är bart tidewater","bart tidewaters bakgrund","vem är kapten på maidens virtue"}},{q="Vem är Tom Half-fish?",a="Tom Half-fish är en gammal bekant till Bart Tidewater som ger resande en gåva att frakta över havet till Bart. Han hyser ett glödande agg mot kaptenen och hävdar att Bart är en bedragare, en snåljåp och en fuskare i kortspel.",al={"vem är half-fish","vem är tom half-fish","vem ger uppdraget a lack of virtue"}},{q="Vad är Maiden's Virtue?",a="Maiden's Virtue är ett fartyg som ligger förtöjt i Menethil Harbor i Wetlands. Bart Tidewater hävdar att det är det finaste skeppet på Great Sea, fast Tom Half-fish hånfullt påstår att fartyget har seglat lika långt som en klippa i Tanaris.",al={"vad är maidens virtue","maidens virtue skepp","var finns maidens virtue"}},{q="Vad är Tom's Gift?",a="Tom's Gift är ett paket som Tom Half-fish skickar till Bart Tidewater i Menethil Harbor. Kuriren får aldrig veta vad det innehåller, men mottagandet får genast Bart att brista ut i rasande förolämpningar om Toms eget pokerspel och fusk.",al={"vad är tom's gift","vad finns i tom's gift","varför blir bart arg på tom's gift"}},{q="Vem fuskade egentligen i poker?",a="Båda sjömännen anklagar varandra häftigt för fusk. Tom Half-fish insisterar på att Bart är en skådespelare som bara vann tillräckligt många pokerhänder för att köpa sitt skepp genom att fuska, medan Bart hävdar att han vann sitt fartyg på hederligt vis först efter att ha kastat ut Tom ur deras pokerkrets för fusk.",al={"vem fuskade i poker","fuskade bart i poker","fuskade tom i poker"}},{q="Hur lämnar du gåvan i Menethil Harbor?",a="Resande kan ta sig till Menethil Harbor i Wetlands med båt över Great Sea. Uppdragsgivaren nämner att en direkt båttur stannar vid hamnen på sitt andra stopp.",al={"hur tar jag mig till menethil harbor","båt till menethil harbor"}}},fp="16,170,15.236.0,18.339.1,22.212.0,21.214.0,28.187.0,19.195.0,30.215.0,47.146.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love är ett leveransuppdrag för Alliansen som börjar i Auberdine vid Darkshores kust. Hollee ber resenärer på väg med båten till Menethil Harbor att överlämna en personlig hälsning till Tarrel Rockweaver, en studiekamrat från utgrävningsutbildningen som hon fortfarande hyser varma känslor för.",h="Unrequited Love är ett leveransuppdrag för Alliansen som börjar i Auberdine vid Darkshores kust.",kw={"auberdine","darkshore","utgrävning","hollee","hollee's note","menethil harbor","merrin","tarrel rockweaver","unrequited love","wetlands"},ang={["faction:Alliance"]="Den här leveransen förbinder Alliansens hamn Auberdine i Darkshore direkt med Menethil Harbor i Wetlands och knyter samman Kalimdor och Eastern Kingdoms.",["race:Dwarf"]="Tarrel Rockweaver och Hollee har båda erfarenhet av utgrävning, ett yrke som har en central plats i dvärgarnas traditioner och studier på Azeroth."},sec={{t="Ett meddelande över havet",b="I hamnstaden Auberdine längs Darkshores dimmiga kust ser Hollee resenärer gå ombord på fartyg till Eastern Kingdoms. Hon söker hjälp av förbipasserande att nå en gammal studiekamrat, Tarrel Rockweaver. De tillbringade flera år med att studera utgrävningskonsten innan examen skilde dem åt över kontinenterna."},{t="Outtalade känslor",b="Hollee minns Tarrels skarpa intellekt och skicklighet inom utgrävning med värme, men tappar fattningen när hans fru Merrin kommer på tal. Trots avståndet och hans äktenskap anförtro hon en äventyrare ett personligt brev och ber dem söka upp Tarrel nära Menethil Harbor för att försäkra sig om att han är trygg."}},faq={{q="Vem erbjuder uppdraget Unrequited Love?",a="Hollee ger uppdraget i kustbosättningen Auberdine i Darkshore. Hon ber resenärer som går ombord på båten till Menethil Harbor att lämna en personlig hälsning till en gammal skolkamrat.",al={"vem ger uppdraget unrequited love","uppdragsgivare auberdine"}},{q="Vem är Tarrel Rockweaver?",a="Tarrel Rockweaver är utgrävare och Hollees före detta skolkamrat. Efter deras studier skickades han till Wetlands, där han nu arbetar nära Menethil Harbor tillsammans med sin fru Merrin.",al={"vem är tarrel rockweaver","tarrels bakgrund"}},{q="Vem är Merrin?",a="Merrin är Tarrel Rockweavers fru. Hollee nämner henne med tydlig tvekan och rynkad panna, vilket avslöjar hennes kvarvarande, obesvarade känslor för Tarrel trots hans äktenskap.",al={"vem är merrin","tarrels fru"}},{q="Varför heter uppdraget Unrequited Love?",a="Titeln syftar på Hollees stillsamma känslor för Tarrel Rockweaver. De studerade utgrävning tillsammans som nära skolkamrater, men Tarrel gifte sig med Merrin och lämnade Hollee att längta efter honom på andra sidan havet i Auberdine.",al={"vad handlar uppdraget unrequited love om","varför heter det unrequited love"}},{q="Var finns Tarrel Rockweaver?",a="Tarrel Rockweaver finns nära Menethil Harbor i Wetlands, på andra sidan Stora havet från Darkshore. En passagerarbåt från Auberdine tar resenärer direkt till hamnens bryggor.",al={"var hittar man tarrel rockweaver","tarrels plats wetlands"}},{q="Vilket föremål ska lämnas i uppdraget?",a="Du ska ta med Hollee's Note till Tarrel Rockweaver för att se hur han mår i Wetlands och lämna hennes personliga meddelande.",al={"vad ska lämnas","hollees brev"}}},fp="15,110,24.272.0,17.267.0,37.173.0,25.176.0,14.132.0,40.167.0,35.160.0,37.124.0"}
P.entries["quest:98463"] = {n="Talk of the Town",s="En vänlig värdshusvärd visar resenärer som söker ett livligare sällskap till hamnen Booty Bay i Stranglethorn Vale. Den som vill ha vildare sällskap får rådet att leta upp Nixxrax Fillamug på Salty Sailor Tavern.",h="En vänlig värdshusvärd visar resenärer som söker ett livligare sällskap till hamnen Booty Bay i Stranglethorn...",kw={"booty bay","goblinvärdshus","nixxrax fillamug","salty sailor tavern","stranglethorn vale","talk of the town"},sec={{t="Ett ord över disken",b="Ord sprids snabbt mellan serveringspersonal och gäster, och nyheter färdas långt bortom den lokala disken. En vänlig bartender tipsar om var det verkligen är livat och hänvisar den som söker vildare nöjen till hamnen Booty Bay."},{t="Salty Sailor",b="Målet är Salty Sailor Tavern, ett livligt etablissemang som drivs av gobliner mitt i Stranglethorn Vales myller. Där håller Nixxrax Fillamug muggarna fyllda åt alla som kommer in."}},faq={{q="Vart leder det här?",a="Det leder till Stranglethorn Vale, rakt till hamnstaden Booty Bay som drivs av gobliner.",al={"vart ska jag gå","resmål","vägbeskrivning till booty bay"}},{q="Vem ska du leta upp i Booty Bay?",a="Du får rådet att leta upp Nixxrax Fillamug inne på Salty Sailor Tavern, där han ser till att allas drycker är påfyllda.",al={"vem ska besökas","vem är nixxrax","nixxrax fillamug"}},{q="Varför skicka någon ända till Stranglethorn Vale?",a="Bartendrar hör allt skvaller från sina gäster, och ryktet säger att Salty Sailor Tavern bjuder på traktens vildaste festligheter, trots att gobliner sköter stället.",al={"varför salty sailor","varför åka till booty bay","varför rekommendationen"}}},fp="16,172,25.184.0,16.164.0,21.70.0,42.100.0,51.140.0"}
P.entries["quest:985"] = {n="How Big a Threat?",s="How Big a Threat? är ett alliansuppdrag som ges av nattalven Terenthis i Auberdine. Äventyrarna har redan spanat på det fientliga Blackwood-furbolglägret söder om staden och skickas nu för att decimera de korrumperade stigfinnarna och vindviskarna innan deras raseri hotar bosättningen.",h="How Big a Threat?",kw={"auberdine","blackwood","darkshore","fel moss","furbolg","grimclaw","stigfinnare","terenthis","vindviskare"},ang={["class:Druid"]="Druider känner tragedin djupt, eftersom furbolgernas öde speglar skogens fortsatta lidande under felmossans besudling.",["faction:Alliance"]="Auberdine är en livsviktig hamn för Alliansen i Darkshore, vilket gör det avgörande för regionens säkerhet att slå ut fientliga läger i närheten.",["race:NightElf"]="För nattalverna är decimeringen av Blackwood en bitter sorg. Århundraden av släktskap med furbolgerna har krossats av den demoniska farsot som dröjer kvar efter det tredje kriget."},sec={{t="En nödvändig decimering",b="Efter den första spaningen söder om Auberdine har Sentinels fastställt att Blackwood-furbolgerna utgör en omedelbar fara för Darkshores flyktingar och försvarare. Terenthis ger stridsdugliga resenärer i uppdrag att slå direkt mot lägret och eliminera Blackwood Pathfinders och Windtalkers för att bryta deras offensiva framfart."},{t="De korrumperades tragedi",b="Nattalver ser traditionellt furbolgerna som andliga fränder och vildmarkens gamla allierade. Men den onda spridningen av felmossa och demonisk besudling över norra Kalimdor har drivit Blackwood-stammen till vansinne. Eftersom det inte finns något känt botemedel som kan återställa furbolgernas sinnen ser Auberdines försvarare våld som en dyster nödvändighet för att förhindra oskyldigas död."},{t="Grimclaw anländer",b="När du rapporterar decimeringen till Terenthis rusar en vit björn vid namn Grimclaw in i Auberdine, mot nattalven. Ankomsten förebådar nya brådskande händelser kring djurlivet och korruptionen som härjar längs kusten och inleder nästa steg i Auberdines försvar."}},faq={{q="Varför vill Terenthis döda Blackwood-furbolgerna?",a="Blackwood-stammen söder om Auberdine har fallit offer för korruption och blivit våldsam och irrationell. Eftersom deras läger utgör ett överhängande hot mot bosättningen och inget botemedel mot korruptionen har upptäckts, beordrar Terenthis en förebyggande attack för att skydda Auberdine.",al={"varför döda blackwood-furbolger","orsak till att decimera furbolger","terenthis furbolguppdrag"}},{q="Var ligger Blackwood-furbolglägret?",a="Lägret ligger strax söder om Auberdine, i Darkshores kustskog, bland de korrumperade träden där Blackwood-stammen har samlats.",al={"blackwood-furbolgernas plats","var finns stigfinnare och vindviskare","furbolgläger i darkshore"}},{q="Vem är Grimclaw?",a="Grimclaw är en vit björn som är knuten till vildmarksundersökningarna i Darkshore.",al={"vit björn i auberdine","grimclaw björnen"}},{q="Vad får furbolgerna att bli vansinniga?",a="Furbolgerna har förgiftats av felmossa och kvarvarande demonisk korruption från tiden efter det tredje kriget. De mörka energierna som härjar i Darkshore förvrider både kropp och sinne och driver fredliga stammar till okontrollerad aggression.",al={"varför är furbolgerna galna","furbolgernas korruption i darkshore","vad korrumperade blackwood"}},{q="Varför tvekar nattalver att döda furbolger?",a="Furbolgerna och nattalverna har haft ett vänskapsband och vördat naturen tillsammans i tusentals år. För nattalverna känns det som att slakta sina egna vilda bröder att avliva dem, men korruptionen lämnar inget annat val.",al={"nattalver och furbolger","varför sörja furbolgerna"}},{q="Vad är skillnaden mellan det första och det andra uppdraget ”How Big a Threat?”?",a="Det första uppdraget prövar din förmåga att spana genom att kräva att du hittar och observerar Blackwood-lägret. Det andra uppdraget är ett direkt stridsuppdrag där du ska decimera lägrets stigfinnare och vindviskare när hotet väl har bekräftats.",al={"delar av how big a threat","skillnad mellan how big a threat-uppdragen"}}},fx={a17cffed={q="Varför skickar Terenthis en äventyrare i stället för Auberdines väktare?",a="Terenthis vänder sig till en resenär som redan har visat sig skicklig på att spana på Blackwood-lägret. Han frågar om samma resenär är beredd att möta stammen i strid och minska hotet mot Auberdine.",al={"varför skicka mig","varför inte använda vakter","varför behöver terenthis mig"}},["0dbe6a0f"]={q="Vilka är Blackwood-spejarna och vindpratarna?",a="De är medlemmar av furbolgstammen Blackwood, som har slagit läger söder om Auberdine. Skogskorruptionen sprider sig, gör dem vansinniga och aggressiva, och deras spejare och schamaner utgör ett omedelbart och växande hot mot nattalvbebyggelsen. Tills ett botemedel mot deras plåga upptäcks anser Terenthis att det enda sättet att skydda sitt folk är att decimera deras led.",al={"blackwood-spejare","blackwood-vindpratare","vem dödar vi"}}},fp="17,195,16.282.0,24.317.0,18.281.1,54.201.0,44.138.0,16.81.1,39.186.0,47.189.0,79.168.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins är ett uppdrag där en farlig grupp dödliga mördare ska elimineras. Äventyrare hjälper en spejare att undanröja hotet och får ett formellt erkännande som ska tas med i en rapport till Valanaar.",h="Al'Aketh Assassins är ett uppdrag där en farlig grupp dödliga mördare ska elimineras.",kw={"al'aketh","mördare","uppdrag","rapport","valanaar"},ang={["class:Rogue"]="Att möta dödliga mördare som Al'Aketh kräver samma dödliga fokus och skoningslösa precision."},sec={{t="Ett dödligt hot",b="Al'Aketh-mördarna utgör ett dödligt hot i fältet och beskrivs av spejare på plats som iskalla mördare. Deras skoningslösa effektivitet och samordnade närvaro gör varje konfrontation med dem ytterst farlig för både lokala spejare och resenärer. De måste hanteras snabbt och beslutsamt innan de hinner slå till mot sina mål."},{t="Rapport till Valanaar",b="När den fientliga Al'Aketh-styrkan har oskadliggjorts uttrycker en allierad fältagent stor lättnad över att du överlevde mötet med så farliga motståndare. Spejaren är tacksam för ditt snabba ingripande och lovar att dokumentera din heroiska hjälp i en officiell rapport till Valanaar."}},faq={{q="Vad är Al'Aketh Assassins?",a="Al'Aketh Assassins är ett uppdrag där äventyrare ska eliminera en dödlig grupp Al'Aketh-agenter. Hotet de utgör är så allvarligt att omedelbara åtgärder och en officiell rapport krävs.",al={"vad är alaketh assassins","vad är det här för uppdrag","alaketh assassins uppdrag"}},{q="Vilka är Al'Aketh-mördarna?",a="Al'Aketh-mördarna beskrivs som iskalla mördare som verkar som en samordnad och farlig anfallsstyrka. Deras dödliga framtoning gör dem till ett allvarligt hot i fältet.",al={"vilka är alaketh","vilka är alaketh-mördarna","alaketh-mördare"}},{q="Vad är Valanaar?",a="Valanaar är bosättningen vid öns sydöstra kant och en bas för dess fredsvakter. Spejaren planerar att ta med din hjälp i en rapport när hen återvänder till Valanaar.",al={"vad är valanaar","rapport till valanaar","rapportera till valanaar"}},{q="Varför måste Al'Aketh-mördarna hanteras?",a="Al'Aketh-mördarna utgör ett omedelbart dödligt hot mot agenter och resenärer i området. De måste oskadliggöras för att skydda de allierade styrkorna och säkra deras överlevnad.",al={"varför slåss mot alaketh","varför döda alaketh-mördarna","alaketh-hot"}},{q="Vad händer efter att mördarna har hanterats?",a="Efter konfrontationen med mördarna förbereder sig spejaren på att rapportera tillbaka till Valanaar och erkänner din avgörande hjälp under uppdraget.",al={"vad händer efter alaketh assassins","nästa uppdrag alaketh","rapportera till valanaar uppdrag"}},{q="Vem erkänner din hjälp med att besegra mördarna?",a="Uppdraget involverar en allierad fältagent som övervakar fientliga rörelser. Spejaren är tacksam för ditt ingripande mot de dödliga mördarna och noterar ditt bidrag för befälet.",al={"vem ger alaketh assassins","vem är spejaren","spejarens rapport valanaar"}}},fp="18,115,15.226.0,21.140.0,27.120.0,31.102.0,16.133.0,46.130.0,46.78.0,53.115.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter är ett leveransuppdrag som leder resenärer ner i Undercitys djup. Leonid är försiktig med att själv gå in i De bortglömdas huvudstad, eftersom han har en ansträngd relation till Lady Sylvanas Windrunner. Därför anlitar han en opartisk kurir som ska överlämna ett meddelande till Glix Xizzix, en gammal goblinkontakt i Trade Quarter.",h="Leonid's Letter är ett leveransuppdrag som leder resenärer ner i Undercitys djup.",kw={"dark lady","glix xizzix","leonid","hittegods","naxxramas","förseglat brev","sylvanas","trade quarter","undercity"},ang={["faction:Horde"]="När du tar dig in i De bortglömdas huvudstad på uppdrag av en utomstående får Horde-äventyrare enkel tillgång till bekvämligheterna i Undercitys Trade Quarter.",["race:Undead"]="Leonids bakgrund med Dark Lady hindrar honom från att själv kliva in i Undercity och visar på de politiska spänningarna mellan oberoende odöda och Sylvanas lojala anhängare."},sec={{t="Ett ärende åt en utomstående",b="Leonid behöver en kurir som kan lämna ett förseglat brev till en bekant i Undercity. På grund av tidigare motsättningar och en ansträngd relation till Lady Sylvanas Windrunner väljer Leonid att inte själv gå genom De bortglömdas huvudstad. I stället litar han på en kringresande neutral part som kan passera stadens vakter utan att väcka misstankar."},{t="Gamla kamrater i Trade Quarter",b="Mottagaren är Glix Xizzix, en opportunistisk goblin som gör affärer i Undercitys Trade Quarter. När Glix får meddelandet minns han hur han och Leonid överlevde sida vid sida i skuggan av Scourge-citadellet Naxxramas. Han blir både förvånad och irriterad över Leonids löfte om ersättning, men betalar motvilligt ur sortimentet av kvarglömda saker som vårdslösa odöda kunder lämnat efter sig."}},faq={{q="Vem är Leonid och varför går han inte in i Undercity?",a="Leonid är en erfaren soldat som upprätthåller känsliga relationer med flera fraktioner. På grund av en komplicerad bakgrund med Lady Sylvanas Windrunner undviker han att gå in i Undercity själv och förlitar sig på kringvandrande äventyrare som kan lämna meddelanden till hans bekanta.",al={"vem ger leonid brevet","leonid barthalomew","leonid uppdragsgivare"}},{q="Vem är Glix Xizzix?",a="Glix Xizzix är en goblin som håller till i Undercitys livliga Trade Quarter. Han verkar arbeta i närheten av frisörtjänster och har en samling kvarglömda saker som tankspridda odöda kunder lämnat efter sig.",al={"var finns glix xizzix","vem är glix xizzix","goblinfrisör i undercity"}},{q="Vad har Leonid för bakgrund med Dark Lady?",a="Leonid medger att han har en ”något färgstark bakgrund” med Sylvanas Windrunner, De bortglömdas bansheedrottning. För att inte riskera att reta upp henne eller hennes vakter anlitar han neutrala mellanhänder för sina ärenden inne i staden.",al={"leonids bakgrund med dark lady","leonid och sylvanas"}},{q="Hur känner Leonid och Glix varandra?",a="Glix minns Leonid som en erfaren veteran från hårda militära strider mot Scourge. Han minns hur den fruktade citadellet Naxxramas regnade förödelse över dem.",al={"glix xizzix leonid naxxramas","hur känner glix och leonid varandra"}},{q="Varför belönar Glix dig med kvarglömda saker?",a="Leonid sa till kuriren att Glix gärna skulle betala dricks, men Glix hade inte lovat något sådant. Goblinen går motvilligt med på det och erbjuder märkliga prydnadssaker från salongens hittegods, sådant som tankspridda kunder ur De bortglömda lämnat efter sig.",al={"uppdragsbelöning från glix","varför hittegods"}},{q="Vart levereras brevet?",a="Brevet förs ner till De bortglömdas huvudstad Undercity, rakt in i Trade Quarter där köpmän, hantverkare och gobliner gör affärer under Royal Apothecary Societys och stadsvakternas vaksamma blickar.",al={"vart ska leonids brev levereras","leverans till trade quarter"}}},fp="15,268,20.252.0,33.318.0,47.236.0,19.171.0,44.206.0,39.142.0,51.208.0,30.207.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="Hallowed Memorandum är en skriftlig kallelse som ber blivande gnompräster i Coldridge Valley att möta Branstock Khalder i Anvilmar. Den inleder deras andliga träning och beskriver Holy Light som en filosofisk gåta, väl lämpad för gnomers intellekt och nyfikenhet.",h="Hallowed Memorandum är en skriftlig kallelse som ber blivande gnompräster i Coldridge Valley att möta...",kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","gnompräst","hallowed memorandum","holy light"},ang={["class:Priest"]="Det här memorandumet markerar början på den formella prästutbildningen i Coldridge Valley och introducerar blivande helare till Holy Lights filosofi.",["race:Gnome"]="Gnomer som närmar sig Light tar med sig skarpt intellekt och nyfikenhet till sina andliga studier och begrundar de heliga mysterierna som gåtor vid sidan av tron."},sec={{t="En kallelse till Anvilmar",b="När de hjälper sina allierade i Coldridge Valley får lovande gnomnoviser Hallowed Memorandum, ett inledande meddelande som ber dem söka upp Branstock Khalder i Anvilmar. Anteckningen är en uppmaning till andliga studier och bjuder in blivande präster att påbörja sin formella utbildning i Dun Morogh."},{t="Trons gåtor",b="När novisen visar upp memorandumet välkomnar Branstock Khalder hen. Han förklarar att fördjupning i Holy Light inte är ett strikt tekniskt hantverk, utan en djupgående gåta som kräver nyfikenhet, skarpt intellekt och harmoni mellan tanke och känsla. Genom begrundan och övning lär sig eleverna att kanalisera dessa heliga mysterier till läkande krafter och gudomlig vedergällning."}},faq={{q="Vem skickade Hallowed Memorandum?",a="Memorandumet förmedlades av en lokal allierad medan du hjälpte till i Coldridge Valley. Det kom ursprungligen från Branstock Khalder, prästtränaren som bor i Anvilmar.",al={"vem gav mig memorandumet","vem skickade hallowed memorandum","varifrån kom anteckningen"}},{q="Vem är Branstock Khalder?",a="Branstock Khalder är en dvärgisk prästtränare i Anvilmar i Coldridge Valley. Han vägleder blivande präster i att förstå Light och använda heliga krafter för att läka sår eller slå ner ondska.",al={"vem är branstock","branstock khalder i anvilmar"}},{q="Hur närmar sig gnomer Holy Light?",a="Branstock förklarar att gnomers nyfikenhet och intellekt är naturliga vägar till förståelse av Light. I stället för att se det som ett strikt tekniskt hantverk uppmuntrar han dem att betrakta det som en filosofisk gåta som förenar tanke och känsla.",al={"kan gnomer bli präster","gnomers koppling till light","hur ser gnomer på light"}},{q="Vad lär Branstock ut om Light?",a="Branstock beskriver Light som en gåta som ger praktiska välsignelser och lärdomar om livet, inte som en krävande teknisk disciplin. Gåtan kan lösas genom att förena sina tankar med sina innersta känslor.",al={"vad är light enligt branstock","branstocks gåta om light"}},{q="Vilka förmågor kan Branstock lära ut?",a="När en präst börjar förstå Light erbjuder Branstock vägledning i att kanalisera dess kraft till skyddande helande böner och heliga slag mot de onda, i utbyte mot en blygsam donation.",al={"vad lär branstock ut","vad kan prästtränare lära ut"}},{q="Var finns Branstock Khalder?",a="Anvilmar är en central fästning och välkomsthall i hjärtat av Coldridge Valley i Dun Morogh. Där finns tränare och en fristad för dvärgar och besökande gnomer.",al={"var ligger anvilmar","var finns branstock"}}},fp="19,212,21.209.0,20.325.0,33.150.0,25.180.0,38.177.0,42.154.0,45.169.0,37.202.0"}
P.entries["quest:98575"] = {n="Tainted Tablet",s="Tainted Tablet är ett nybörjaruppdrag i Valley of Trials som leder blivande magiker till Nartok i The Den. Det introducerar Durotars demonbesvärjares pragmatiska men försiktiga synsätt. De söker kraft från Nether för att forma sitt eget öde, trots att det förflutna fortfarande kastar en skugga över dem.",h="Tainted Tablet är ett nybörjaruppdrag i Valley of Trials som leder blivande magiker till Nartok i The Den.",kw={"durotar","nartok","nether","tainted tablet","the den","valley of trials","demonbesvärjare"},ang={["class:Warlock"]="Tainted Tablet markerar den formella introduktionen av Durotars blivande demonbesvärjare till deras tränare, Nartok. Den uppmanar dem att bemästra Nether i stället för att frukta dess kraft.",["faction:Horde"]="Thralls nya Horde är på sin vakt mot demonisk fördärvning, men utövare som håller till på platser som The Den hävdar att de tryggt kan härska över Nether-krafter och säkra en framtid för sitt folk.",["race:Orc"]="Med tanke på demonpaktens katastrofala arv på Draenor är felmagi fortfarande kontroversiell bland orker. Därför råder Durotars demonbesvärjare dem att hålla sig dolda och visa mod."},sec={{t="En mörk kallelse",b="Tainted Tablet är ett inskrivet meddelande till nyanlända utövare som inleder sin färd i Valley of Trials. Stenen har passerat genom oroliga lägerförvaltares händer och bär en kallelse från Nartok, en tränare i demonbesvärjelse som har sitt hem i The Dens skuggiga djup. Meddelandet bjuder in läsaren att lämna vanliga stamplikter bakom sig och utforska magins djupare, förbjudna strömningar."},{t="Att härska över Nether",b="När Nartok får svar på sin kallelse talar han öppet om orkernas stormiga historia med Nether. Han menar att de starka måste gripa makten över sitt eget öde, i stället för att avsvära sig dessa oberäkneliga krafter av skam eller rädsla. I hans ögon kommer utövare som med list bemästrar varelser från Nether att nå framgång där vanliga hövdingar misslyckas. Men eftersom rädda sinnen gärna angriper det de inte förstår varnar han för att alltid hålla sådana krafter väl dolda."}},faq={{q="Vad är Tainted Tablet?",a="Tainted Tablet är en skriftlig kallelse som lämnas till en blivande utövare i Valley of Trials. Den uppmanar dem att söka upp Nartok, deras klasstränare, som väntar i The Den.",al={"vad är tainted tablet","uppdraget tainted tablet","tavlans syfte"}},{q="Vem skickade Tainted Tablet?",a="Tavlan skickades av Nartok, en orsk demonbesvärjare och tränare som håller till i The Den i Valley of Trials. Han använder den för att presentera sig för nyanlända utövare och bjuda in dem till undervisning.",al={"vem skrev tavlan","vem är nartok","vem skickade tavlan"}},{q="Var finns Nartok?",a="Nartok bor i The Den, en grotta undangömd i Valley of Trials där mörkare konster och specialiserad träning utövas i det fördolda.",al={"var finns nartok","var finns the den","hur hittar man nartok"}},{q="Varför varnar Nartok för att hålla sina krafter väl dolda?",a="Nartok varnar för att vanligt folk fruktar krafter de inte förstår och ofta slår tillbaka i panik. Eftersom orkerna har lidit svårt av demonisk fördärvning förr i tiden håller demonbesvärjare sina konster dolda och går försiktigt fram.",al={"varför dölja demonbesvärjare","varför hålla krafter dolda","varför demonbesvärjare håller sig dolda"}},{q="Vad tycker Nartok om att utöva felmagi?",a="Nartok tror att de som bemästrar varelserna från Nether kan skapa sin egen väg och gripa makten att forma sitt folks öde, där vanliga ledare misslyckas, i stället för att låta ödet förslava dem.",al={"vad är nartoks mål","nartoks filosofi","varför använda krafter från nether"}},{q="Vem ger dig Tainted Tablet?",a="En lokal uppdragsgivare i Valley of Trials lämnar över tavlan. Hen erkänner öppet sitt obehag inför felmagiker, men inser att Nartoks kallelse ändå måste levereras.",al={"vem levererade tavlan","vem gav mig tavlan"}}},fp="14,197,14.271.0,21.390.0,27.144.0,28.150.0,26.129.0,50.243.0,46.197.0,33.140.0"}
P.entries["quest:98576"] = {n="Glyphic Parchment",s="I Valley of Trials visar Glyphic Parchment unga magiker vägen till sina första lektioner. Gornek lämnar över det runmärkta meddelandet, som skickar dem till Mai'ah nära The Den för att börja lära sig magi.",h="I Valley of Trials visar Glyphic Parchment unga magiker vägen till sina första lektioner.",kw={"arkana","durotar","glyphic parchment","gornek","magiker","mai'ah","the den","valley of trials"},ang={["class:Mage"]="Som magiker skickas du med detta meddelande till Mai'ah för att börja dina studier och utöka din besvärjelsebok.",["faction:Horde"]="Som medlem av Horden lär du dig att Valley of Trials fostrar även oberäkneliga konster som magi med disciplin, för att stärka Hordens framtid.",["race:Troll"]="Som troll kan du se till Mai'ah och Darkspears växande magitraditioner. Hon delar sin förståelse för kosmiska krafter med andra troll och allierade rekryter."},sec={{t="En kallelse till studier",b="Nya rekryter prövar sin styrka mot Durotars lokala skadedjur, men de som dras till magi behöver mer än råstyrka. Gornek lämnar över ett runmärkt meddelande. Det visar nybörjare i magi till Mai'ah, som vägleder Hordens nyaste rekryter genom deras första lektioner i magi."},{t="Det arkanas väg",b="Mai'ah väntar strax utanför The Den, där hon lär unga magivävare att tygla sina ambitioner med tålamod och eftertanke. Hon uppmanar dem att välja rätt ögonblick i stället för att kasta ut rå magi utan omsorg. Under hennes lektioner lär sig nybörjare att väva kosmos sköra trådar i stället för att släppa lös en vild storm."}},faq={{q="Vem skickar Glyphic Parchment?",a="Mai'ah skickar pergamentet, och Gornek räcker det till dig. Magitränaren väntar nära The Den i Valley of Trials.",al={"vem skrev glyphic parchment","vem skickade det här","pergamentets författare"}},{q="Var finns Mai'ah?",a="Mai'ah väntar strax utanför The Den i Valley of Trials i Durotar, tillsammans med de andra klassmentorerna.",al={"var finns mai'ah","mai'ahs plats","hitta mai'ah"}},{q="Vad är syftet med det här uppdraget?",a="Pergamentet visar nybörjare i magi till deras tränare. När du talar med Mai'ah börjar din formella undervisning i magi och vägen öppnas till nya besvärjelser och grundläggande träning.",al={"vad gör glyphic parchment","varför göra uppdraget","uppdragets mål"}},{q="Vad är Mai'ahs filosofi om magi?",a="Mai'ah lär ut att magi kräver intellekt, återhållsamhet och tålamod. En magiker iakttar noga och agerar sedan i rätt ögonblick.",al={"vad lär mai'ah ut","mai'ahs bakgrund"}},{q="Varför tränar en troll magiker i Valley of Trials?",a="Valley of Trials välkomnar unga orcher och Darkspear Trolls till Horden. Darkspear-magiker som Mai'ah lär blivande magiker om kosmiska krafter.",al={"varför trollmagiker","troll och det arkana","trolltränare i orchområde"}},{q="Vem lämnar pergamentet till spelaren?",a="Gornek, prövningarnas övervakare vid Valley of Trials centrala läger, ger dig pergamentet när du återvänder till honom under dina första uppgifter.",al={"vem ger glyphic parchment","gorneks uppdrag"}}},fp="17,177,18.255.0,21.281.0,32.116.0,26.102.0,34.173.0,37.139.0,54.173.0,41.138.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Archaic Rune är ett introduktionsuppdrag för unga dvärgschamaner i Dun Morogh. Den heliga tavlan är genomsyrad av elementarkraft från uråldriga Wildhammer-inskrifter och introducerar unga lärlingar till deras elementära arv. När stenen överlämnas till Teo Hammerstorm i Anvilmar inleds formellt deras träning i jordens, luftens, eldens och vattnets vägar.",h="Archaic Rune är ett introduktionsuppdrag för unga dvärgschamaner i Dun Morogh.",kw={"anvilmar","archaic rune","bronzebeard","coldridge valley","element","schaman","teo hammerstorm","wildhammer-klanen"},ang={["class:Shaman"]="Archaic Rune är det allra första steget på en dvärgschamans andliga resa. Den bekräftar deras elementära samhörighet och för dem till deras första mentor.",["faction:Alliance"]="När Wildhammer-mentorer för schamankonsterna till Dun Morogh breddas Alliansens andliga utövning, och elementära traditioner får en plats vid sidan av det heliga ljuset.",["race:Dwarf"]="Den här runan markerar ett viktigt kulturutbyte mellan dvärgklaner, när Wildhammer delar sina uråldriga andliga traditioner med sina Bronzebeard-fränder i Coldridge Valley."},sec={{t="En uråldrig inskrift",b="Unga äventyrare i Coldridge Valley upptäcker Archaic Rune efter att ha hjälpt lokala allierade nära Anvilmar. Stenen bär en tydlig skrift, huggen i Wildhammer-klanens stil, och är synbart och påtagligt laddad med uråldrig elementarkraft. Runan är inte bara en relik av stenhantverk, utan också ett elementärt prov: endast de med en gryende förmåga att stämma in på urtidens andar kan förstå tecknen som ristats på dess väderbitna yta. För dem som kan läsa skriften ger den tydliga instruktioner om att söka rätt undervisning i den närbelägna dvärgposteringen."},{t="Wildhammers visdom i Dun Morogh",b="I Anvilmars stora sal tar Wildhammer-schamanen Teo Hammerstorm emot den inskrivna stenen. I generationer bevarades elementens andliga konster till största delen av Wildhammer-klanen bland deras vindpinade bergstoppar. Nu har dessa traditioner börjat slå rot bland Bronzebeard-dvärgarna i Ironforge och Dun Morogh. Hammerstorm fungerar som en viktig bro mellan de två dvärgkulturerna. Han välkomnar unga lärlingar som visar en kallelse att tala med elementen och erbjuder formell undervisning i jordens, luftens, eldens och vattnets discipliner."}},faq={{q="Vad är Archaic Rune?",a="Archaic Rune är en uråldrig stentavla med gammal Wildhammer-skrift, genomsyrad av elementarkraft. Den ges till lovande nya äventyrare i Coldridge Valley som ett första prov på deras andliga förmåga. Om en lärling har den inre känslighet som krävs för att läsa runan, bekräftar det deras kallelse till schamanens väg och visar dem att tala med tränaren i Anvilmar.",al={"uppdraget archaic rune","vad är den här runan","föremålet archaic rune"}},{q="Vem ristade Archaic Rune?",a="Inskrifterna på runan är utförda i Wildhammer-klanens traditionella stil. Den skickades av Teo Hammerstorm, en Wildhammer-schaman som bor i Anvilmar. Han använder den inskrivna stenen för att hitta och ta kontakt med nya lärlingar som har en medfödd koppling till elementandar.",al={"vem gjorde archaic rune","runans ursprung","wildhammer-runans skapare"}},{q="Vem är Teo Hammerstorm?",a="Teo Hammerstorm är en Wildhammer-dvärg och schamantränare stationerad i Anvilmar i Coldridge Valley. Han har rest till Dun Morogh för att hjälpa till att dela sin klans förfäders schamanlära med Bronzebeard-dvärgarna och vägleda nya utövare i jordens, eldens, vattnets och luftens vägar.",al={"vem är teo hammerstorm","teo hammerstorm i anvilmar","schamantränare i anvilmar"}},{q="Varför delas Wildhammer-läran med Bronzebeard-dvärgar?",a="Schamankonsterna bevarades och vaktades traditionellt av Wildhammer-klanen under många år, men nyligen har även Bronzebeard-dvärgarna tagit sig an dessa elementära seder. Mentorer som Teo Hammerstorm har tagit på sig att lära Ironforge-dvärgar hur de kan tala med och hedra elementandar.",al={"varför är dvärgar schamaner","bronzebeard och wildhammer-schamaner","dvärgschamanernas historia"}},{q="Vart ska jag ta Archaic Rune?",a="Runan måste föras till Teo Hammerstorm, som finns i Anvilmars huvudbyggnad i Coldridge Valley. När du visar honom runan demonstrerar du din förmåga att kanalisera elementen och får tillgång till vidare träning i dina grundläggande schamantrollformler.",al={"var lämnar jag in archaic rune","lämna in archaic rune","hitta teo hammerstorm"}},{q="Vad innebär det att läsa runan?",a="Archaic Rune är genomsyrad av elementarkrafter från en uråldrig dvärgskrift. Endast en lärling med en medfödd förmåga att stämma in på elementarkrafterna kan tyda skriften. Att lyckas läsa den bevisar att en äventyrare har de naturliga förutsättningarna och den andliga beredskapen för att bli en sann schaman.",al={"varför kan jag läsa runan","runans betydelse","läsa archaic rune"}}},fp="12,186,22.331.0,31.441.0,25.302.0,28.216.0,23.259.0,67.243.0,33.193.0,35.233.0"}
P.entries["quest:986"] = {n="A Lost Master",s="A Lost Master ger en alliansäventyrare i uppdrag att samla material som ska hjälpa till att hitta Volcor, en nattalv som försvunnit i Darkshores vildmark. Terenthis i Auberdine erbjuder sig att väva en förtrollad kamouflagekappa som skyddar den som ger sig ut för att leta, men behöver då skinn från kustens vildaste moonstalkers.",h="A Lost Master ger en alliansäventyrare i uppdrag att samla material som ska hjälpa till att hitta Volcor, en...",kw={"a lost master","auberdine","darkshore","fine moonstalker pelt","grimclaw","moonstalker","terenthis","volcor","wildbend river"},ang={["class:Druid"]="Druider kan uppskatta Terenthis respekt för moonstalkers naturliga förmåga att smyga, när han omvandlar deras vilda essens till skyddande kamouflage.",["class:Hunter"]="Jägare känner igen bandet mellan Volcor och Grimclaw, liksom skickligheten som krävs för att spåra och jaga Darkshores matriarker och hanar.",["race:NightElf"]="Att hitta Volcor speglar nattalvernas plikt att skydda sitt folk och sina vilda följeslagare i Darkshores otämjda vidder."},sec={{t="En sökning i vildmarken",b="Medan Terenthis i Auberdine spårar hot längs Darkshores kust börjar han oroa sig för hur det har gått för Volcor och hans följeslagare Grimclaw. Det är ökänt farligt att ge sig djupt in i regionens södra delar, där aggressiva rovdjur och förvridet djurliv håller till. I stället för att skicka ut en oskyddad spejare lägger Terenthis upp en plan på att skapa en skyddande mantel genomsyrad av vilda illusioner."},{t="Päls från de stoltaste",b="Vanliga skinn räcker inte för att väva en mantel som kan förvilla Darkshores odjur. Terenthis behöver fina moonstalker-skinn från fullvuxna moonstalker-hanar eller matriarker. Dessa väldiga kattdjur strövar i skogarna söder om Auberdine, nära Wildbend River och vidare mot Ashenvales skogsklädda gräns."},{t="Skör magi",b="Det färdiga plagget använder moonstalker-päls och naturens förtrollningar så att bäraren kan ta sig obemärkt genom fientliga områden medan hen söker efter Volcor. Men Terenthis varnar för att illusionen är skör: ansträngande aktivitet eller strid bryter förtrollningen och lämnar den som letar oskyddad."}},faq={{q="Vem är Volcor?",a="Volcor är en nattalv, spejare eller spårare, som försvann i södra Darkshores vildmark. Hans följeslagare Grimclaw och Terenthis i Auberdine försöker hitta honom, vilket sätter sökandet i gång.",al={"vem är volcor","volcors bakgrund","den försvunne mästaren volcor"}},{q="Vem ger uppdraget?",a="Terenthis, en nattalv som är stationerad i bosättningen Auberdine i Darkshore, ger uppdraget efter att äventyrare hjälpt honom med tidigare problem i området.",al={"uppdragsgivare","var får man uppdraget a lost master","terenthis plats"}},{q="Var hittar man moonstalker-hanar och matriarker?",a="Dessa fullvuxna moonstalkers strövar omkring i södra Darkshore, särskilt nära Wildbend Rivers stränder och längre söderut mot gränsen till Ashenvale.",al={"platser med fine moonstalker pelt","var hittar man moonstalkers","kattdjur vid wildbend river"}},{q="Vad ska manteln göra?",a="Terenthis tänker skapa en förtrollad mantel som döljer bäraren för Darkshores fientliga odjur, så att hen kan leta efter Volcor utan att ständigt dra till sig angrepp.",al={"vad gör manteln","terenthis mantel","mantelns förtrollning"}},{q="Varför behöver Terenthis särskilda skinn?",a="Terenthis säger att han behöver fem fina skinn från moonstalker-hanar eller matriarker för att få tillräckligt med material till manteln.",al={"varför hanar och matriarker","varför fina skinn"}},{q="Har kamouflagemanteln några begränsningar?",a="Ja. Terenthis varnar för att förtrollningen är skör. Det går bra att prata med andra, men ansträngande aktiviteter eller strid skingrar snabbt illusionen.",al={"bryts illusionen","mantelns begränsningar"}}},fx={bc18541c={q="Varför vill Terenthis att detta ska göras?",a="Terenthis är djupt bekymrad för sin nattalvskamrat Volcor, som försvann i de farliga vildmarkerna i södra Darkshore, och för den lojala björnen Grimclaw, som kom till Auberdine för att söka hjälp åt sin herre. Terenthis vägrar skicka dig in i så farligt område utan skydd, så han insisterar på att först förbereda en magisk kamouflagekappa. Den ska se till att du tryggt kan hitta Volcor utan att kustens rovdjur sliter dig i stycken.",al={"varför hjälpa volcor","terenthis motiv","varför vill terenthis ha pälsar"}}},fp="13,180,23.289.0,18.236.0,14.245.0,14.150.0,21.113.0,49.135.0,30.157.0,39.87.0,43.148.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="A Difficult Path markerar den formella början på en Forsaken-paladins träning i Deathknell. Efter att ha tagit hand om de tanklösa odöda som reser sig ur kryptorna får nyvaknade Ljusets förkämpar instruktioner om att söka upp Aramis Hammerhand i bykyrkan och möta den plågsamma verkligheten i att utöva helig kraft som odöd.",h="A Difficult Path markerar den formella början på en Forsaken-paladins träning i Deathknell.",kw={"a difficult path","aramis hammerhand","consecrated scroll","deathknell","forsaken-paladin","holy light","shadow priest sarvis","tirisfal glades"},ang={["class:Paladin"]="Uppdraget utgör den grundläggande prövningen för en Forsaken-paladin och framställer helig kraft inte som en lätt välsignelse, utan som en plågsam smältdegel av disciplin och uthållighet.",["race:Undead"]="För Forsaken visar åkallan av Ljuset att hängivenhet och disciplin kan överleva den fysiska döden, även om magin aktivt bränner det kärl som kanaliserar den."},sec={{t="En stinkande skriftrulle",b="När en nyväckt Forsaken-paladin har rensat bort de vilda odöda utanför kryptan överlämnar Shadow Priest Sarvis en oväntad försändelse. Consecrated Scroll utstrålar så intensiv helig kraft att skuggprästen synbart ryggar tillbaka och bryskt ber bäraren att flytta sig. För den som utövar skuggmagi och förfall känns själva auran från Holy Light som en öppen låga."},{t="Den heliga eldens smältdegel",b="I Deathknells vanhelgade kyrka väntar Aramis Hammerhand, paladintränaren bland Forsaken. Medan andra raser utövar Ljuset naturligt och med glädje får odöda som åkallar det utstå en brännande, påtaglig smärta. Aramis försöker inte mildra sanningen: att kanalisera helig kraft genom ett ruttnande kärl är ren plåga, men han kräver att lärjungarna omfamnar smärtan i stället för att rygga undan och använder den som en smältdegel för att härda sin nyfunna beslutsamhet."}},faq={{q="Varför tycker Shadow Priest Sarvis illa om skriftrullen?",a="Shadow Priest Sarvis är hängiven skuggmagi och att bevara sina odöda fränder. Consecrated Scroll utstrålar ren helig kraft, som är i grunden fientlig mot odött kött och djupt oroande för dem som utövar skuggan.",al={"sarvis heliga skriftrulle","varför är sarvis orolig","skuggpräst reagerar på skriftrulle"}},{q="Kan Forsaken verkligen utöva Holy Light utan att dö?",a="Forsaken kan utöva Ljuset genom ren viljestyrka och tro, men det orsakar dem intensiv smärta, särskilt när de kanaliserar det för att hela sig själva eller andra. Det kräver enorm mental uthållighet att kanalisera kraften.",al={"forsaken-paladiners historia","odöda som använder ljuset","gör ljuset ont på forsaken"}},{q="Vem är Aramis Hammerhand?",a="Aramis Hammerhand är paladintränaren som finns i Deathknells kapell. Han vägleder nyuppståndna Forsaken-paladiner och lär dem att uthärda plågan i att utöva Ljuset som odöd och smida det till ett effektivt vapen.",al={"vem är aramis hammerhand","paladintränare i deathknell","aramis roll"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar hos Shadow Priest Sarvis på den centrala gläntan i Deathknell och avslutas bara några steg bort, inne i byns förfallna kapell där Aramis Hammerhand håller till.",al={"var finns a difficult path","uppdragets plats","var finns deathknells kyrka"}},{q="Måste jag läsa Consecrated Scroll för att slutföra uppdraget?",a="Nej, det är inte strikt nödvändigt att läsa skriftrullen för att slutföra målet. Om du talar direkt med Aramis Hammerhand inne i kyrkan går din träning vidare.",al={"läsa consecrated scroll","måste man läsa skriftrullen","hoppa över läsning av skriftrullen"}},{q="Varför kallas vägen ”svår”?",a="Namnet speglar Forsaken-paladinens brutala väg. Medan andra av Ljusets krigare finner tröst och ro i sin tro måste en odöd paladin uthärda brännande helig eld som flödar genom dött kött varje gång de kastar en välsignelse eller slår till.",al={"varför svår väg","uppdragsnamnets betydelse"}}},fx={["6833d98f"]={q="Varför vill Shadow Priest Sarvis att detta ska göras?",a="Sarvis vill bara slippa se det Heliga ljuset. Den konsekrerade skriftrullen kom till dig medan du gallrade bland de tanklösa Scourge, och dess strålande magi kränker naturligt hans skuggberörda sinnen. I stället för att stanna i dess närhet eller ta hand om en blivande paladin skickar han dig till din egen tränare, Aramis Hammerhand, så att du kan börja lära dig att finslipa din smärtsamma disciplin.",al={"varför skickar sarvis mig till aramis","sarvis motiv svår väg","varför ger sarvis mig skriftrullen"}}},fp="16,234,16.283.0,25.384.0,49.168.0,54.180.0,25.165.0,33.159.0,63.124.0,35.216.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis återvänder efter att ha kommunicerat med The Great Cat Spirit i Zephras. Novisen har tagit till sig vildkattens smygförmåga, snabbhet och ursinne och visar upp sin nyväckta aura för Dendrite för fortsatt andlig vägledning.",h="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis återvänder efter att ha...",kw={"blessings of the great windborne cat spirit","kattform","dendrite","druid","the great cat spirit","shen'dorei","smygförmåga","zephras"},ang={["class:Druid"]="Uppdraget markerar en viktig milstolpe i bemästrandet av kattdjurets rovdjursinstinkter och ger druider den smygförmåga, snabbhet och det ursinne som krävs för att kommunicera med och anta kattens aspekt.",["race:Skyborne"]="Anden erkänner särskilt novisen som unga shen'dorei och erbjuder vägledning genom vind och skugga från Zephras, medan novisen lär sig att tygla sin vilda kraft."},sec={{t="Gemenskap med vindanden",b="Blessings of the Great Windborne Cat Spirit markerar höjdpunkten i en helig gemenskap med The Great Cat Spirit i Zephras. Efter att ha sökt upp denna vindburna beskyddare och vunnit dess gunst återvänder en novis till Dendrite för att visa att hen har tagit till sig vildkattens list, rovdjurens smygförmåga och ursinne."},{t="Dendrites vägledning",b="När novisen återvänder efter att ha fått välsignelsen gör Dendrite subtila kroppsrörelser för att läsa av novisens nyväckta aura. Dendrite känner hur kattdjurets instinkter vävts in i novisens själ och bekräftar att kandidaten äntligen är redo att fokusera sitt sinne och åkalla kattens sanna aspekt."}},faq={{q="Vad är Blessings of the Great Windborne Cat Spirit?",a="Blessings of the Great Windborne Cat Spirit är en övergångsrits där en novis som sökt upp och fått The Great Cat Spirits välsignelse återvänder till Dendrite för att fullborda sin andliga gemenskap.",al={"vad är det här för uppdrag","kattens välsignelseuppdrag","kattandens uppdrag"}},{q="Vem är Dendrite?",a="Dendrite är en mentor som skickar noviser för att kommunicera med The Great Cat Spirit. När de återvänder utför han rituella gester för att känna av förvandlingen och bekräfta om novisen har tagit till sig den smygförmåga, snabbhet och list som krävs för att kanalisera kattdjurets natur.",al={"vem är dendrite","dendrites historia"}},{q="Vem är The Great Cat Spirit?",a="The Great Cat Spirit är en uråldrig beskyddarande ande i Zephras. Den skänker värdiga noviser andlig gunst, vindarnas snabbhet och rovdjurens smygförmåga innan den skickar tillbaka dem för att fortsätta sin utbildning.",al={"vad är kattanden","den stora vindburna kattanden"}},{q="Var ligger Zephras?",a="Zephras är The Great Cat Spirits hem. Dit reser lovande noviser för att söka dess råd, få dess välsignelser av vind och skugga och lära sig grunderna i kattdjursformen.",al={"var ligger zephras","kattandens plats"}},{q="Varför tilltalar anden novisen som shen'dorei?",a="The Great Cat Spirit tilltalar novisen direkt som unga shen'dorei och syftar på utövarens förfäders arv. Utövaren söker gemenskap med naturandar och vill bemästra vild förvandlingsmagi.",al={"vilka är shendorei","unga shendorei"}},{q="Vad ger kattandens välsignelse?",a="Välsignelsen skänker kattdjursformens list, snabbhet och smygförmåga. Med välsignelsen i hand blir novisen erkänd av Dendrite och kan fokusera sitt inre ursinne och åkalla kattens sanna natur.",al={"vad ger välsignelsen","kattandens välsignelseeffekt"}}},fp="43,231,35.196.0,22.218.0,52.119.0,16.223.0,28.184.0,25.181.0,55.193.0,47.203.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides är ett expeditionskontrakt beställt av James Halloran, en garvare i Menethil Harbor. Halloran söker förstklassiga material från Highlands dimhöljda bergsträsk och byter tillverkade lädervaror mot de tåliga skinnen från rovdjuren Thicket Raptors.",h="Highland Hides är ett expeditionskontrakt beställt av James Halloran, en garvare i Menethil Harbor.",kw={"highland hides","highlands","james halloran","menethil harbor","raptorhudar","garvare","thicket raptor","wetlands"},ang={["class:Hunter"]="Jägare som ger sig ut i Highlands bergsträsk möter mäktiga bestar som Thicket Raptors, vars tåliga hudar kräver noggrann spårning och en ren jakt.",["faction:Alliance"]="Menethil Harbor är en viktig allianshamn i Wetlands, där handelsmän som James Halloran utrustar resenärer på väg ut i de farliga träskmarkerna runt omkring."},sec={{t="En garvares möjlighet",b="James Halloran, en skicklig garvare verksam i hamnstaden Menethil Harbor, håller ständigt utkik efter exotiska hantverksmaterial. När han får höra om en expedition som utforskar bortglömda ruiner i Highlands bryr han sig mindre om forntida historia och mer om de mäktiga bestar som strövar omkring i bergsträsken. Han inser djurlivets kommersiella värde och värde för hantverkare och anlitar djärva äventyrare för att ge sig in bland de dimhöljda topparna och hämta tillbaka utvalda skinn."},{t="Highlands bestar",b="Bland djuren som lurar i Highlands är Thicket Raptors ökända rovdjur, väl anpassade till den oländiga träskterrängen. Hantverkare värdesätter deras tåliga, strukturerade skinn för särskilt läderarbete. Halloran ber resenärer spåra upp varelserna och återvända med fyra hela hudar, som han använder till fina detaljer och dekorativa kanter på verkstadens alster."}},faq={{q="Vem är James Halloran?",a="James Halloran är en lokal garvare och hantverkare med bas i Menethil Harbor. Han arbetar med läder och oljor och söker skinn av hög kvalitet från exotiska bestar i Wetlands och de omgivande högländerna för att tillverka fina kanter och rustningar.",al={"vem ger highland hides","vem är james halloran","garvare i menethil"}},{q="Varför behöver James Halloran de här hudarna?",a="Halloran vill ha hudar från Thicket Raptors för deras exceptionella tålighet och struktur. Han anser att de hör till de finaste hudar han har hanterat och använder dem till spektakulära detaljer på läderkanter.",al={"vad används highland hides till","varför vill james ha raptorhudar","syftet med raptorhudar"}},{q="Var hittar man Thicket Raptors?",a="Thicket Raptors håller till i Highlands bergsträsk och lurar i den oländiga vildmarken nära forntida ruiner som en expedition utforskar just nu.",al={"var finns thicket raptors","thicket raptors plats","var finns raptrarna"}},{q="Vilka ruiner syftar Halloran på?",a="I Highlands finns bortglömda ruiner som ett expeditionsteam undersöker just nu. Medan hantverkare som Halloran fokuserar på djurlivet utforskar lärda och upptäcktsresande områdets forntida hemligheter på djupet.",al={"vilka ruiner finns i highlands","highlands expeditionsruiner","vem utforskar highlands"}},{q="Är jakten tänkt för en grupp?",a="Halloran råder dig att ta med välutrustade följeslagare. I Highlands bergsträsk finns farliga vilda djur, så utflykter mot rovdjur som Thicket Raptors är riskfyllda för den som reser ensam.",al={"är highland hides farligt","behövs en grupp för highland hides","behöver jag vänner för highland hides"}},{q="Vad erbjuder James Halloran i byte?",a="I utbyte mot fyra felfria hudar från Thicket Raptors erbjuder Halloran läderarbeten av hög kvalitet, tillverkade i hans verkstad. Äventyrare får välja en del som passar deras resor.",al={"vad byter halloran bort","belöningslore för highland hides"}}},fp="14,155,22.329.0,23.280.0,22.196.0,41.123.0,35.117.0,36.173.0,34.144.0,40.143.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism är ett upptäcktsuppdrag där äventyrare ska föra en mångfacetterad titanrelik från Wetlands till Ironforge. Prospector Whelgar ger dig reliken, som skänks till High Explorer Magellas i Hall of Explorers för att främja League:s studier av de forntida väktarna.",h="Prehistoric Prism är ett upptäcktsuppdrag där äventyrare ska föra en mångfacetterad titanrelik från Wetlands...",kw={"hall of explorers","high explorer magellas","ironforge","prehistoric prism","prospector whelgar","titan relic","uldaman","wetlands"},ang={["faction:Alliance"]="När du skänker forntida skatter du hittat berikar du direkt de lärda samlingarna i Ironforge prestigefyllda Hall of Explorers.",["race:Dwarf"]="Att återfinna äkta titanreliker går till kärnan av dvärgarnas identitet och Explorers' Leagues uppdrag att avslöja deras skapares ursprung."},sec={{t="En forntida upptäckt",b="När Prospector Whelgar undersöker Wetlands hittar han en anmärkningsvärd artefakt med intrikata väktarinskrifter på sina många fasetter. Han inser att ett fynd med så stor historisk betydelse hör hemma hos lärda och uppmanar dig att genast föra det till dvärgarnas huvudstad Ironforge. Whelgar hoppas att upptäckten ska föras in i den officiella katalogen, så att äventyraren får erkännande tillsammans med hans äkthetsintyg."},{t="En gåva till museet",b="I Hall of Explorers anrika salar tar High Explorer Magellas emot reliken på Explorers' League vägnar. Den ledande arkeologen förundras över dess äkta tillverkarstämplar och säger att ljuset som strömmar genom de polerade fasetterna påminner om underverken han såg vid sin första utgrävning i Uldaman. Genom att skänka artefakten bevaras den för studier och League:s växande dokumentation av titanernas arv utökas."}},faq={{q="Vem ger uppdraget Prehistoric Prism?",a="Prospector Whelgar ber dig föra reliken till Ironforge efter att ha bekräftat att inskrifterna på fasetterna i Wetlands liknar titanernas.",al={"vem ger prehistoric prism","var börjar prehistoric prism","uppdragsgivare prehistoric prism"}},{q="Var lämnar du in Prehistoric Prism?",a="Du lämnar reliken till High Explorer Magellas i Hall of Explorers i Ironforge. Han tar gärna emot den till museets samling.",al={"vem lämnar man in prehistoric prism till","var lämnar man in prehistoric prism","slutföra prehistoric prism"}},{q="Vad är det för slags artefakt, Prehistoric Prism?",a="Det är en forntida artefakt med många fasetter och tydliga kännetecken från väktarna. När ljuset träffar den dansar det genom kristallformen på ett sätt som påminner om relikerna som grävts fram i Uldaman.",al={"vad är prehistoric prism","är prehistoric prism en titanrelik","vad är reliken"}},{q="Varför är Hall of Explorers intresserad av prismat?",a="Explorers' League samlar aktivt in och katalogiserar äkta reliker med titanursprung. High Explorer Magellas anser att artefakter av den här kalibern är nödvändiga för att vidga världens kunskap och förstå forntida historia.",al={"varför vill magellas ha den","varför skänka prismat","hall of explorers prismat"}},{q="Hur hör prismat ihop med Uldaman?",a="När High Explorer Magellas undersöker artefaktens ljusbrytning och väktarmärkningar jämför han det dansande ljuset med reliker han undersökte under sin allra första arkeologiska utgrävning i Uldaman.",al={"har uldaman något med prismat att göra","kopplingen till uldaman","prismat uldaman"}},{q="Blir ditt namn infört i museets katalog?",a="Prospector Whelgar och High Explorer Magellas ser till att du formellt får erkännande för att ha återfunnit reliken och att det förs in i Explorers' Leagues historiska arkiv.",al={"prehistoric prism katalog","får man erkännande","historiskt erkännande prismat"}}},fp="17,157,20.368.0,20.348.0,38.139.0,43.124.0,47.148.0,53.167.0,37.168.0,54.133.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash är en militär uppmaning från Alliansen att försvara viktig mark mot de våldsamma Darkspear Raiders. Utan omedelbart stöd vid frontlinjen riskerar Alliansen att helt förlora den omstridda ögruppen.",h="Darkspear Islands Clash är en militär uppmaning från Alliansen att försvara viktig mark mot de våldsamma...",kw={"alliansen","slagfält","brigadgeneral","darkspear islands","darkspear islands clash","darkspear raiders","marks of honor"},ang={["class:Paladin"]="Alliansens heliga krigare möter de våldsamma striderna med orubblig beslutsamhet och svarar på uppmaningen att skydda alliansmedlemmars liv och slå tillbaka fiendestyrkorna.",["class:Warrior"]="Stridskämparna vid frontlinjen får ta emot den hårdaste stöten från de våldsamma trollräderna. Militär disciplin och tapperhet på slagfältet kan vända stridens gång.",["faction:Alliance"]="Alliansens högsta befäl förlitar sig på frivilliga mästare för att förstärka fronten mot Darkspear Raiders och skydda strategiska positioner på öarna."},sec={{t="En omstridd front",b="Kampen om kontrollen över Darkspear Islands har brutit ut i öppet krig mellan Alliansen och aggressiva krigsband av Darkspear Raiders. Alliansens befälhavare varnar för att deras fäste i ögruppen kommer att övermannas utan brådskande förstärkningar. Därför har de kallat dugliga mästare till vapen för att hejda fiendens framryckning."},{t="Ett bevis på tapperhet",b="Alliansens ledning förlitar sig på beprövade stridskämpar som är villiga att ge sig direkt ut på frontlinjen. För att upprätthålla disciplin och uppmärksamma verkligt hjältemod kräver befälhavarna att krigare återvänder med Darkspear Islands Marks of Honor som ett konkret bevis på sina stridsinsatser. De hedrar dem som vänder stridens gång."}},faq={{q="Vad är Darkspear Islands Clash?",a="Darkspear Islands Clash är en militär uppmaning till vapen från Alliansens officerare som leder krigsinsatsen vid frontlinjen. Alliansens mästare ska strida mot Darkspear Raiders och bevisa sina insatser genom att hämta hedersmärken från striderna.",al={"vad är darkspear islands clash","uppdraget clash","striden på darkspear islands"}},{q="Vilka är Darkspear Raiders?",a="Darkspear Raiders är trollkrigsband som kämpar om kontrollen över Darkspear Islands. Deras aggressiva framryckningar hotar Alliansens fästen i området och får högsta befälet att kalla på förstärkningar utan dröjsmål.",al={"vilka är darkspear raiders","fienden darkspear raiders","vilka strider vi mot på darkspear islands"}},{q="Varför strider Alliansen på Darkspear Islands?",a="Alliansen försöker hålla strategiskt viktig mark på Darkspear Islands och hindra att regionen helt hamnar under trollens kontroll. Om Alliansen förlorar mark hotas dess inflytande och säkerhet i de omstridda kustvattnen.",al={"varför strider alliansen på darkspear islands","varför strida här","alliansens krig mot darkspear"}},{q="Vem utfärdar och tar emot uppdraget?",a="En brigadgeneral från Alliansen, stationerad utanför slagfälten, leder truppmobiliseringen och tar emot bevis på återvändande mästares insatser i strid.",al={"vem utfärdar darkspear islands clash","vem tar emot darkspear marks of honor","var finns alliansens brigadgeneral"}},{q="Vad är Darkspear Islands Marks of Honor?",a="Marks of Honor är militära märken som tilldelas stridskämpar för tapperhet och aktivt deltagande vid frontlinjen. Om du överlämnar tre sådana märken till en brigadgeneral från Alliansen får du ett slutgiltigt bevis på dina insatser på slagfältet.",al={"vad är marks of honor","darkspear islands mark of honor","hur bevisar man insatser vid frontlinjen"}},{q="Vad står på spel om Alliansen misslyckas?",a="Utan snabba förstärkningar riskerar Alliansens positioner på Darkspear Islands att helt kollapsa under Darkspear Raiders obevekliga tryck. Genom att säkra öarna hindrar Alliansen fiendestyrkorna från att befästa sin obestridda dominans över ögruppen.",al={"vad händer om alliansen förlorar darkspear islands","varför behövs brådskande hjälp","förlusten av darkspear islands"}}},fp="23,162,17.280.0,14.233.0,32.162.0,30.180.0,54.219.0,38.157.0,42.199.0,39.243.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash kallar krigare att samla sina följeslagare och besegra de fientliga Darkspear Raiders som strider om ögruppen. Den pågående striden kräver samordnade insatser för att hejda fiendens intrång på öarna.",h="Darkspear Islands Clash kallar krigare att samla sina följeslagare och besegra de fientliga Darkspear Raiders...",kw={"strid","darkspear islands","darkspear raiders","ökonflikt","samla","skärmytsling","trollplundrare"},ang={["faction:Horde"]="Det här är Alliansens sida av kampen om Darkspear Islands, de heliga trollöarna utanför Kalimdors kust som Horden försvarar mot alla främlingar.",["race:Troll"]="För trolläventyrare är Darkspear Raiders, som den här alliansordern riktar sig mot, Vol'jins eget folk, som försvarar stammens heliga öar."},sec={{t="Ögruppen i krig",b="Darkspear Islands Clash är en pågående militär offensiv på de omstridda Darkspear Islands. Styrkor som skickats till stridsområdet uppmanas att hålla stånd mot vågor av Darkspear Raiders, som fortsätter att utkämpa skärmytslingar längs stränderna och i inlandet. Striden är ingen isolerad händelse, utan en del av ett långvarigt fälttåg för att säkra ett brohuvud i ögruppen."},{t="Samla frontlinjen",b="Befälhavarna vid fronten betonar att organisation och numerärt övertag krävs för att besegra de motståndskraftiga plundrarna. Överlevnad och seger beror på att samla närliggande allierade till en samlad styrka som kan stå emot motattacker, driva bort befästa plundringsförband och bryta deras grepp om de omstridda öarnas fästen."}},faq={{q="Vad är Darkspear Islands Clash?",a="Darkspear Islands Clash är ett uppdrag som kallar äventyrare att samla sina allierade och gå till angrepp mot de fientliga Darkspear Raiders i den pågående konflikten på Darkspear Islands.",al={"vad är det här för uppdrag","sammanfattning av darkspear islands clash","information om stridsuppdraget"}},{q="Var utkämpas striden?",a="Skärmytslingen utkämpas på Darkspear Islands, en ögrupp präglad av hårda territoriella strider och pågående sjödrabbningar.",al={"var utspelar det sig","var ligger darkspear islands","stridens plats"}},{q="Vilka är Darkspear Raiders?",a="Darkspear Raiders är hordenstroll som försvarar Darkspear Islands, de heliga öarna där Vol'jins stam bor. Ordern kräver att soldaterna besegrar dem medan de kämpar om territorium på öarna.",al={"vilka är fienderna","vilka slåss vi mot","mål för darkspear raiders"}},{q="Varför måste styrkor samlas inför striden?",a="Konflikten kräver att allierade styrkor samlas och mobiliseras för att stå emot långvariga motattacker och bryta igenom de fientliga plundrarnas linjer.",al={"varför samla styrkor","vad är målet","hur slutför man striden"}},{q="Varför fortsätter striderna på Darkspear Islands?",a="Horden och Alliansen utkämpar en olöst kamp om öarnas fästen: Horden försvarar dem som helig trollmark, medan Alliansen söker ett brohuvud utanför Kalimdors kust.",al={"varför pågår striderna","varför konflikt på öarna","orsaken till östriden"}},{q="Vem leder styrkorna i den här striden?",a="Ordern kommer från Alliansens brigadgeneral i Alterac Mountains, som uppmanar soldaterna på marken att rycka fram utan att tveka.",al={"vem ger uppdraget","uppdragsgivare för striden","stridens befälhavare"}}},fp="23,187,22.190.0,23.294.0,36.126.0,33.121.0,30.200.0,42.93.0,53.178.0,42.141.0"}
P.entries["quest:99"] = {n="Arugal's Folly",s="Arugal's Folly kulminerar i en farlig undersökning av förbannelsen som håller Pyrewood Village i sitt grepp. Dalar Dawnweaver ger Hordens agenter i uppdrag att hämta förtrollade bojor från byborna för att tyda ärkemagikern Arugals förvridna verk. När bojorna undersöks blottas den tragiska magi som håller bosättningen i worgenens skugga.",h="Arugal's Folly kulminerar i en farlig undersökning av förbannelsen som håller Pyrewood Village i sitt grepp.",kw={"arugal","arugal's folly","dalar dawnweaver","moonrage-worgen","pyrewood shackles","pyrewood village","silverpine forest","the sepulcher"},ang={["class:Mage"]="För magiutövare är Arugals bojor en dyster påminnelse om hur Kirin Tors trolldom kan spåra ur i vansinne när den blandas med utomvärldsliga frammanade bestar.",["faction:Horde"]="När bojorna säkras bryts Arugals mystiska grepp om vägen söderut mot The Greymane Wall.",["race:Undead"]="De Fördärvade ser på Pyrewood Village med kall fascination och skoningslös pragmatism. De vill gärna montera ned Arugals förtrollningar för att säkra södra Silverpine."},sec={{t="Pyrewoods dubbla liv",b="Söder om The Sepulcher ligger Pyrewood Village, en bosättning fångad i ett kusligt tillstånd. I dagsljus lever invånarna som vanliga mänskliga bönder, rädda och tillbakadragna. Men när skymningen faller över skogen slits deras mänskliga gestalter sönder och blir till vilda Moonrage-worgen som stryker omkring på gatorna under Arugals kontroll. Dalar Dawnweaver försöker reda ut exakt vilka magiska bindningar som orsakar denna fasansfulla förvandling om natten."},{t="Bojorna krossas",b="För att analysera förtrollningen som håller Pyrewood i sitt våld behöver Dawnweaver förtrollade Pyrewood Shackles som tagits direkt från de förvandlade byborna. De här bojorna är mer än enkelt järn; de pulserar av kvarvarande magi från Arugals misslyckade skyddsförtrollningar. Genom att studera deras magiska sammansättning hoppas den Fördärvades magikern förstå hur förvandlingen till odjur går till och hitta ett sätt att till slut störta den avfällige ärkemagikern i Shadowfang Keep."}},faq={{q="Varför förvandlas invånarna i Pyrewood Village till worgen om natten?",a="Ärkemagikern Arugal lade förvridna förtrollningar över Pyrewood Village. Dagtid upprätthåller hans besvärjelser en illusion av mänsklighet eller ett vilande mänskligt tillstånd, men vid mörkrets inbrott förvandlas byborna till Moonrage-worgen under hans kontroll.",al={"pyrewood dag och natt","pyrewoods förbannelse","varför människa först och varg sedan"}},{q="Vad är Pyrewood Shackles?",a="De är förtrollade bojor som de förbannade invånarna i Pyrewood Village bär. Arugal använde dem som en del av sin magi över byn, och Dalar Dawnweaver studerar förbannelsen med hjälp av deras kvarvarande energi.",al={"pyrewood shackle","arugals bojor"}},{q="Vem är Dalar Dawnweaver?",a="Dalar Dawnweaver är en Fördärvad magiker som är stationerad vid The Sepulcher i Silverpine Forest. Han leder de Fördärvades magiska undersökning av ärkemagikern Arugals frammanade worgen.",al={"dalar dawnweavers bakgrund","vem ger uppdrag vid sepulcher"}},{q="Botar det Pyrewood Village om uppdraget slutförs?",a="Nej. De återfunna bojorna ger Dalar Dawnweaver de magiska insikter han behöver för att förstå Arugals magi, men förbannelsen fortsätter att hålla Pyrewood i ständig plåga.",al={"går pyrewood att bota","blir pyrewoods invånare botade"}},{q="Hur kontrollerar Arugal byborna?",a="Med vårdslösa förtrollningar och förtrollade bojor band Arugal byborna till sin vilja och tvingade dem att anta odjursgestalter som vaktar vägen till hans domän i Shadowfang Keep.",al={"arugal och pyrewood","hur kontrollerar arugal dem"}},{q="Vad händer när uppdragskedjan Arugal's Folly är slutförd?",a="Det här uppdraget utgör det sista kapitlet i kedjan Arugal's Folly. Kunskapen som samlats in låter de Fördärvade bedöma hotet från Shadowfang Keep fullt ut och planera Arugals fall.",al={"efter arugals folly","arugals folly avslutning"}}},fx={["0ad90a3b"]={q="Varför vill Dalar Dawnweaver ha Pyrewood Shackles?",a="Dalar Dawnweaver studerar de besynnerliga förtrollningar som Archmage Arugal har kastat över Silverpine Forest. Genom att analysera magin som är bunden i bybornas bojor hoppas Dalar kunna avslöja Arugals så kallade botemedel, bemästra hemligheterna bakom hans vilda besvärjelser och samla den viktiga kunskap som krävs för att till sist fälla den galne magikern och upphäva hans vårdslösa trolldom.",al={"varför vill dalar ha detta","dalar dawnweavers motiv","varför samla pyrewood shackles"}}},fp="14,199,26.323.0,23.328.1,64.161.0,31.203.0,24.160.0,48.134.1,38.161.0,61.157.1"}
P.entries["quest:990"] = {n="Trek to Ashenvale",s="Trek to Ashenvale är ett reseuppdrag för Alliansen som leder erfarna äventyrare söderut från Darkshore till Ashenvales urskogar. Sentinel Selarin, som kom till Auberdine för att söka hjälp, skickar resenärer till Raene Wolfrunner i Astranaar, där Sentinels kämpar mot en spridande förvridning.",h="Trek to Ashenvale är ett reseuppdrag för Alliansen som leder erfarna äventyrare söderut från Darkshore till...",kw={"ashenvale","astranaar","darkshore","night elf","raene wolfrunner","sentinel selarin","färd till ashenvale"},ang={["faction:Alliance"]="Som mästare för Alliansen stärker du banden till nattalverna när du hörsammar Astranaars vädjan och hjälper till att säkra fraktionens främsta fäste i norra Kalimdor.",["race:NightElf"]="För nattalver innebär den här färden en återkomst till Kalimdors heliga hjärtland, där du hörsammar dina systrars vädjan att skydda de uråldriga heliga markerna från onaturlig röta."},sec={{t="Från kusten",b="Efter att ha hörsammat Sentinel Selarins nödrop i Auberdine lämnar resenärerna kustens dystra, grå stränder och skuggade ruiner bakom sig. Sentinel ser att de är stridsvana kämpar och spejare som klarar sig själva och visar dem vägen rakt in i nattalvernas skogsrike. När de lokala hoten i Darkshore är hanterade riktas uppmärksamheten mot de långt större faror som tränger in från söder."},{t="Vägen till Astranaar",b="Vägen söderut följer en uråldrig nattalvsväg som slingrar sig genom Ashenvales täta, gamla trädkronor. Raene Wolfrunner, ledare för Sentinels i Astranaar, har vädjat om förstärkning med brådskande besked. Demonkontaminering, vilddjur på härjningståg och intrång i förfädernas marker har pressat Sentinels i Astranaar hårt. De behöver hjälp utifrån för att hålla stånd i den heliga skogen."}},faq={{q="Vem skickar dig på färden?",a="Sentinel Selarin, en nattalvsvakt som Raene Wolfrunner skickat till Auberdine för att söka hjälp, visar dig söderut mot Astranaar.",al={"uppdragsgivare","vem startar trek to ashenvale","selarin"}},{q="Vem är Raene Wolfrunner?",a="Raene Wolfrunner är den högsta Sentinel-befälhavaren i Astranaar. Hon ansvarar för att organisera försvaret av Ashenvale och samordna insatserna mot den förvridning som drabbar skogen.",al={"raene","wolfrunner","ledare i astranaar"}},{q="Varför skickas äventyrare till Ashenvale?",a="Ashenvales uråldriga skogar dukar under för en spridande förvridning och växande yttre hot. De lokala nattalvsvakterna är överväldigade och behöver brådskande dugliga allierade som kan hjälpa Astranaars invånare och försvarare.",al={"varför ashenvale","vad händer i ashenvale","förvridning i ashenvale"}},{q="Är vägen mellan Darkshore och Ashenvale säker?",a="Sentinel Selarin råder dig särskilt att hålla dig nära vägen. Om du lämnar stigen och går in i den djupa skogen utsätter du dig för aggressiva rovdjur, satyrer och fientliga styrkor som strövar omkring i de vilda gränstrakterna.",al={"säkerhet på vägen","är vägen i ashenvale säker"}},{q="Vad ska jag göra när jag kommer fram till Astranaar?",a="När du har rapporterat direkt till Raene Wolfrunner råder hon dig att tala med de andra invånarna och försvararna runt om i Astranaar. Många av dem behöver omedelbar hjälp med lokala kriser.",al={"vad göra i astranaar","ankomst till astranaar"}},{q="Vilken nivå är uppdraget avsett för?",a="Den här färden brukar markera slutet på äventyrares tid i Darkshore kring nivå nitton och övergången till Ashenvales vidsträcktare och mer omstridda gränsland.",al={"vilken nivå","nivåkrav"}}},fx={b4a50545={q="Varför vill Sentinel Selarin att du ska bege dig till Ashenvale?",a="Sentinel Selarin lyder under Raene Wolfrunner, som leder försvaret och återställningsarbetet i Astranaar. Den utbredda korruptionen plågar de uråldriga skogarna i Ashenvale, och de lokala Sentinels är hårt ansträngda och under stor press. Selarin skickar beprövade kämpar från Darkshore direkt till sin härskarinna, så att dugliga händer genast kan börja lindra skogens nöd.",al={"varför skicka till ashenvale","selarins motiv","varför färdas till ashenvale"}}},fp="17,158,17.265.0,21.326.0,27.126.0,24.154.0,44.191.0,49.151.0,44.178.0,46.166.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner är ett uppdrag där du ska hitta Sentinel Eralya Leafshadow, en budbäraraspirant som är försenad från The Oracle Tree. Det är viktigt eftersom kommunikationen mellan det heliga trädet och de äldste i Darnassus är avgörande för Night Elf-ledarskapet.",h="The Lost Runner är ett uppdrag där du ska hitta Sentinel Eralya Leafshadow, en budbäraraspirant som är...",kw={"council of the forest","darnassus","eralya leafshadow","the oracle glade","oracle tree","sentinels","the lost runner"},ang={["faction:Alliance"]="Säkra vägar och kommunikationslinjer genom Teldrassil bidrar till stabiliteten i Darnassus och alliansens territorium.",["race:NightElf"]="Att säkra kommunikationen mellan det uråldriga The Oracle Tree och ledarskapet i Darnassus är avgörande för kaldoreis säkerhet och andliga vägledning."},sec={{t="Budbärare från The Oracle",b="Council of the Forest har en grupp Sentinels stationerad vid det vördnadsvärda The Oracle Tree i Teldrassil. Trädet förmedlar heliga meddelanden till Night Elf-äldste, och förlitar sig på hängivna löpare som bär dessa försändelser tillbaka till Darnassus längs de slingrande skogsvägarna. Att se till att dessa meddelanden kommer fram säkert är avgörande för kaldoreis vägledning och styre."},{t="En försenad budbärare",b="Tiden mellan meddelandena från The Oracle Tree varierar, men en ovanligt lång tystnad väcker oro när en budbärare inte dyker upp. Det senaste uppdraget gick till Sentinel Eralya Leafshadow, en aspirant som fortfarande genomgår sin utbildning. Hennes överordnade fruktar att hon råkat ut för en olycka längs vägen och ber resande söka längs den västra vägen mot The Oracle Glade för att ta reda på vad som hänt henne."}},faq={{q="Vem är den försvunna löparen?",a="Den försvunna löparen är Sentinel Eralya Leafshadow, en Night Elf-sentinel under utbildning som fick i uppdrag att leverera ett meddelande från The Oracle Tree till Darnassus.",al={"vem är den försvunna löparen","försvunnen sentinel","vem är eralya"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett uråldrigt träd i The Oracle Glade som med jämna mellanrum förmedlar meddelanden till Night Elf-äldste i Darnassus. Stationerade Sentinels måste leverera dem säkert.",al={"vad är the oracle tree","the oracle glades syfte","varför meddelanden från the oracle tree"}},{q="Vart var Eralya på väg?",a="Eralya väntades längs den västra vägen mellan Darnassus och The Oracle Glade, där löpare regelbundet färdas för att förmedla budskap från trädet.",al={"vart var eralya på väg","eralya rutt","den försvunna löparens plats"}},{q="Vem stationerade Sentinels vid The Oracle Tree?",a="Council of the Forest skickade en avdelning Sentinels till The Oracle Tree för att se till att meddelanden snabbt och säkert förs vidare till de äldste i Darnassus.",al={"vem skickade sentinels till the oracle tree","vad är council of the forest"}},{q="Varför är hennes frånvaro oroande?",a="Även om det varierar hur ofta meddelanden kommer från The Oracle Tree, har hennes frånvaro varat ovanligt länge. Hennes överordnade är oroliga med tanke på att hon fortfarande är under utbildning.",al={"varför är hennes försening ovanlig","hur ofta skickar the oracle meddelanden"}},{q="Vad är målet med sökandet?",a="Du ombeds följa stigen västerut mot The Oracle Glade och leta efter Sentinel Eralya Leafshadow för att ta reda på vad som har försenat henne.",al={"vad gör man i the lost runner","målet med uppdraget the lost runner"}}},fp="15,128,24.261.0,18.306.0,23.156.0,24.180.0,36.135.0,47.152.0,29.168.0,37.126.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="'Not Dead Yet' är en brådskande vädjan från Eralya, en dödligt sårad Night Elf som hittas efter ett katastrofalt uppdrag mot The Oracle Tree. Övermannad av grymma harpies ber hon resande att underrätta Byancie i Dolanaar om patrullens öde. Berättelsen visar de dödliga hot som tränger in på Teldrassils skogsstigar.",h="'Not Dead Yet' är en brådskande vädjan från Eralya, en dödligt sårad Night Elf som hittas efter ett...",kw={"byancie","dolanaar","eralya","harpies","not dead yet","oracle tree","teldrassil"},ang={["faction:Alliance"]="Alliansens äventyrare som utforskar Teldrassil får i uppdrag att föra brådskande bud tillbaka till utposter som Dolanaar när fältspanare blir avskurna och övermannade.",["race:NightElf"]="Den fallna budbäraren Eralya och hennes systrar är väktare som tjänstgör på Teldrassil. Att se Night Elf-försvarare överfallas av harpies nära det heliga The Oracle Tree visar tydligt hur farorna på grenarna tilltar."},sec={{t="En överfallen patrull",b="I Teldrassils vildmark kretsar 'Not Dead Yet' kring Eralya, en sårad Night Elf-budbärare som hittas blödande och klamrande sig fast vid livet. Hon skickades på ett viktigt uppdrag mot det heliga The Oracle Tree tillsammans med sina systrar, men patrullen överfölls brutalt och mejades ner av harpies som trängde sig fram. Ingen hjälp är på väg och hennes krafter sinar snabbt. Eralya anförtror förbipasserande resande att föra brådskande nyheter tillbaka till tryggheten."},{t="Ett rop till Dolanaar",b="Med rossliga andetag och blodhosta ber Eralya spelaren att föra hennes rapport till Byancie i den närbelägna byn Dolanaar. Harpies som hemsöker Teldrassils mäktiga grenar har blivit allt djärvare och aggressivare. De utgör ett dödligt hot mot ensamma budbärare och väktare som försöker ta sig fram längs skogsstigarna. Om du för Eralyas vädjan vidare får Dolanaars invånare veta om överfallet vid The Oracle Tree innan fler liv går förlorade."}},faq={{q="Vem är Eralya?",a="Eralya är en Night Elf-väktare eller budbärare som överfölls på ett uppdrag till The Oracle Tree. Hon klamrar sig fast vid livet och hostar blod medan hon ber förbipasserande äventyrare att berätta om hennes enhets öde innan tiden rinner ut.",al={"vem är eralya","eralya uppdrag","döende night elf"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är ett gammalt landmärke i Teldrassils Oracle Glade. Eralya och hennes systrar skickades dit med ett brådskande meddelande men övermannades på vägen.",al={"vad är oracle tree","oracle glade träd","vart var eralya på väg"}},{q="Vad hände med Eralya och hennes patrull?",a="Eralya och hennes systrar överfölls och övermannades av harpies som hemsöker Teldrassils grenar. Varelserna svärmade fram i stora mängder, mejade ner patrullen och lämnade Eralya dödligt sårad.",al={"vem attackerade eralya","vem överföll henne","varför blöder eralya"}},{q="Vem är Byancie?",a="Byancie är en kontaktperson stationerad i Night Elf-byn Dolanaar. Eralya ber enträget att någon för bud om harpies överfall och patrullens svåra läge direkt till Byancie.",al={"vem är byancie","var finns byancie","byancie dolanaar"}},{q="Vart ska Eralyas meddelande föras?",a="Dolanaar är den främsta Night Elf-byn längs vägen söder om Shadowglen på Teldrassil. Byancie finns där för att ta emot rapporter och samordna det lokala försvaret.",al={"vart ska meddelandet föras","eralya överlämning","var finns dolanaar"}},{q="Vad hände med de andra systrarna på uppdraget?",a="Eralyas Night Elf-kamrater bland väktarna skildes åt eller dödades under harpies brutala angrepp. Utan förstärkningar i sikte fruktade Eralya att ingen av hennes systrar hade undkommit anfallet.",al={"vad hände med eralyas systrar","väktarpatrullens systrar"}}},fp="12,199,18.288.0,18.293.0,14.183.0,24.175.0,39.130.0,15.137.0,41.225.0,50.162.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand är ett uppdrag i Durotar som handlar om Heglan Shadeeyes plötsliga försvinnande. Hon är en spanare i Shattered Hand med uppdrag att hålla uppsikt över Tiragarde Keep. När hennes regelbundna underrättelserapporter plötsligt upphör skickas en utredare för att hitta hennes postering och ta reda på vad som tystade henne.",h="A Missing Hand är ett uppdrag i Durotar som handlar om Heglan Shadeeyes plötsliga försvinnande.",kw={"a missing hand","durotar","heglan shadeeye","skurk","spanare","shattered hand","tiragarde keep"},ang={["class:Rogue"]="Shattered Hand fungerar som hordens hemliga ryggrad och underrättelsegille. Utredningen av en försvunnen agent visar hur farliga deras spaningsuppdrag i fält kan vara.",["faction:Horde"]="Det är avgörande för Durotars säkerhet att hålla uppsikt över resterna av Kul Tiras vid Tiragarde Keep, och en oförklarligt försvunnen spanare tyder på ett möjligt osynligt hot alldeles intill Orgrimmars tröskel.",["race:Orc"]="Durotar är ett nyligen säkrat orkområde, och när en agent tystnar inom synhåll från de närliggande mänskliga inkräktarna väcks omedelbart oro för rikets säkerhet."},sec={{t="Tystnade rapporter",b="A Missing Hand börjar med växande oro för Heglan Shadeeye, en spanare i Shattered Hand. Hon är stationerad i Durotar för att på avstånd bevaka den fientliga mänskliga garnisonen i Tiragarde Keep, men hennes stadiga ström av underrättelserapporter upphör plötsligt utan förklaring. Hennes överordnade tvivlar på att människosoldaterna lyckades upptäcka och tillfångata henne, vilket väcker farhågor om att en oväntad och farligare fara ingrep. Äventyrare skickas norr om fästningen för att hitta hennes postering och avgöra om avbrottet bara beror på en försening i kommunikationen eller på något mycket mörkare."},{t="Den kalla kojan",b="När du kommer fram till den angivna observationsposten norr om Tiragarde Keep slutar sökandet i tragedi. Heglan ligger död bland de splittrade resterna av en raserad koja. De fysiska spåren tyder på att angriparen inte var människa, vilket väcker den obehagliga frågan om vilken varelse eller entitet som fällde en tränad agent så nära hordens områden. Ledtrådar kring spillrorna antyder ett okänt hot som nu måste avslöjas."}},faq={{q="Vad är uppdraget A Missing Hand?",a="A Missing Hand är ett uppdrag i Durotar där en äventyrare får i uppdrag att hitta Heglan Shadeeye, en spanare i Shattered Hand. Hon var stationerad norr om Tiragarde Keep, men hennes regelbundna underrättelserapporter upphörde plötsligt.",al={"vad är a missing hand","översikt över uppdraget a missing hand"}},{q="Vem är Heglan Shadeeye?",a="Heglan Shadeeye är en agent i Shattered Hand med uppdrag att i hemlighet bevaka Tiragarde Keep från en närliggande utsiktspunkt. Hennes spaningsrapporter upphörde plötsligt, vilket ledde till en utredning om var hon befann sig.",al={"vem är heglan","var är heglan shadeeye","försvunnen spanare"}},{q="Vad hände med Heglan Shadeeye?",a="Det är vad uppdraget ska ta reda på. Hennes rapporter från posteringen norr om Tiragarde Keep upphörde utan förvarning, och den som skickar dig tvivlar på att människorna tog henne till fånga och befarar att något farligare ligger bakom.",al={"vad hände med heglan shadeeye","är heglan död","heglans öde"}},{q="Vad är Shattered Hand?",a="I den moderna Horden är Shattered Hand en organisation av diskreta agenter, lönnmördare och spioner. De utför hemlig övervakning och underrättelsearbete för att skydda hordens områden.",al={"vad är shattered hand","vilka är shattered hand"}},{q="Dödade människorna i Tiragarde Keep Heglan?",a="Hennes överordnade tvivlar på det. Heglan bevakade de fientliga människorna från Kul Tiras som höll Tiragarde Keep, men den som skickar dig tror inte att de kunde ha tagit henne till fånga och befarar att något farligare ligger bakom.",al={"dödade människor heglan","dödade soldater från tiragarde henne"}},{q="Varför bevakades Tiragarde Keep?",a="Tiragarde Keep är en utpost som hålls av fientliga sjömän och soldater från Kul Tiras, vilka hotar Durotars kust. Heglan var stationerad i närheten för att hålla uppsikt över deras förehavanden och rapportera underrättelser till Horden.",al={"varför bevakade heglan tiragarde keep","övervakning av tiragarde keep"}}},fp="14,194,14.354.0,12.234.1,33.185.0,23.176.0,33.184.0,27.184.0,45.185.0,37.173.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below är ett uppdrag för Horde där du undersöker ett våldsamt bakhåll längs östra Durotars kust. Efter att spanaren Heglan Shadeeye överfallits vid sin post i en hård strid måste du leta efter ledtrådar i det skövlade området. Fysiska bevis avslöjar ett hot som direkt hotar Razor Hills försvarslinjer.",h="Threat from Below är ett uppdrag för Horde där du undersöker ett våldsamt bakhåll längs östra Durotars kust.",kw={"durotar","heglan shadeeye","horde","naga","orgnil soulscar","razor hill","spanare","threat from below"},ang={["faction:Horde"]="Att undersöka kusten är avgörande för Durotars säkerhet och skyddar den unga Horde-nationen från att bli kringränd längs sina kustgränser.",["race:Orc"]="Orciska försvarare ser bakhållet mot spanaren Heglan Shadeeye som ett outhärdligt intrång i deras etablerade hemland och kräver en omedelbar undersökning och hämnd.",["race:Troll"]="Darkspear Trolls känner naga-farornas lömska natur alltför väl efter att tidigare ha mött sjöhäxor och fasor från havet i Great Sea."},sec={{t="Bakhåll vid Durotars kust",b="En våldsam strid längs Durotars kust lämnar marken sönderslagen och väcker omedelbar oro bland Hordes försvarare. Heglan Shadeeye, en spanare från Shattered Hand som höll vakt från sin post, överfölls av en osedd fiende. Stridsplatsen visar tydligt att Heglan kämpade hårt och skadade sina angripare. Fientliga styrkor rör sig obehindrat längs den östra kusten. Därför får äventyrare från Horde i uppdrag att undersöka det skövlade lägret, söka igenom marken efter ledtrådar och ta reda på vilken sorts fiende som anföll spanaren."},{t="Ormhota",b="I spillrorna hittar du en sönderriven fana och en flisa från ett exotiskt klingvapen. Båda tillhör de ormlika naga. De lömska vattenvarelserna tycks ha krupit söderut längs Durotars kust från Azshara för att skapa ett fäste där de kan jaga. För garnisonen i Razor Hill signalerar fyndet en annalkande kris. Bosättningen är redan ansatt av människor från Kul Tiras vid Tiragarde Keep i söder och quilboar längs de västra ravinerna. Den kan inte stå emot ett nytt anfall från havet i norr utan att riskera att falla helt."}},faq={{q="Vad är Threat from Below?",a="Threat from Below är ett uppdrag i Durotar där äventyrare från Horde undersöker bakhållet mot spanaren Heglan Shadeeye. Efter tecken på en våldsam strid längs kusten söker du igenom den uppbökade marken efter ledtrådar som angriparna lämnat. Sedan lämnar du fynden direkt till Orgnil Soulscar i Razor Hill, så att han kan bedöma det militära hotet mot området.",al={"uppdraget threat from below","vad är threat from below","översikt över threat from below"}},{q="Vem är Heglan Shadeeye?",a="Heglan Shadeeye är en spanare från Shattered Hand som höll uppsikt över Tiragarde Keep från en hydda norr om fästet och vaktade Hordes kärnland. Under ett uppdrag överfölls hon vid sin utsiktspost vid kusten. De omfattande skadorna på lägerplatsen tyder på att hon kämpade hårt mot angriparna. Därför kräver ledarna i Razor Hill omedelbara svar.",al={"heglan shadeeye","vem är heglan","heglan shadeeyes bakgrund"}},{q="Vem anföll Heglan Shadeeye?",a="Heglan Shadeeye överfölls av naga som rörde sig söderut längs Durotars kust. Fysiska bevis från striden, närmare bestämt en särskild fana och en bit av ett sönderslaget klingvapen, bekräftar att ormvarelserna utförde räden. Striden var så våldsam att även angriparna skadades.",al={"vem överföll heglan","heglans angripare","vad anföll heglan shadeeye"}},{q="Vem är Orgnil Soulscar?",a="Orgnil Soulscar är en framstående orcisk befälhavare stationerad i Razor Hill i centrala Durotar. Han ansvarar för att organisera områdets försvar och samordna Hordes spanare, och håller uppsikt över underrättelser om fientliga intrång. När Heglan Shadeeye inte återvänder förlitar sig Orgnil på spanare och äventyrare som kommer tillbaka för att identifiera angriparna och skydda bosättningen.",al={"vem är orgnil","orgnil soulscar","orgnil i razor hill"}},{q="Varför är naga ett hot mot Razor Hill?",a="Razor Hill är redan hårt pressat av människor från Kul Tiras som befäst sig i söder och fientliga quilboar i väster. Om naga etablerar ett permanent brohuvud längs den östra kusten i norr riskerar Hordes utpost att fångas i en omöjlig kniptång. Det skulle tänja garnisonens begränsade styrkor till bristningsgränsen och skära av förstärkningsvägarna genom Durotar.",al={"varför är naga farliga här","naga hotar razor hill","naga-faran vid razor hill"}},{q="Varifrån kom naga som anföll?",a="De militära lämningarna tyder på att naga färdades söderut längs kusten från nordliga vatten, troligen från Azshara eller kontinentalsockeln i Great Sea. Genom att färdas på vattenvägarna och undvika patruller i inlandet kunde vattenvarelserna snabbt slå till mot isolerade kustposter innan Durotars försvarare hann ordna ett sammanhängande försvar.",al={"varifrån kom naga","nagas ursprung i durotar","hur kom naga till durotar"}}},fp="17,217,27.374.0,18.374.1,26.247.0,23.254.0,29.191.0,23.281.0,40.284.0,39.272.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="The Great Tree Provides är ett uppdrag i Dolanaar där Byancie ber om hjälp att hejda en farlig åkomma som hotar Eralya. Genom att samla daggiga lasherskott från Teldrassils sjöar och hämta grundläggande förnödenheter hjälper spelarna till att förbereda en brådskande läkande salva.",h="The Great Tree Provides är ett uppdrag i Dolanaar där Byancie ber om hjälp att hejda en farlig åkomma som...",kw={"åkomma","byancie","daggiga lasherskott","dolanaar","eralya","läkande salva","lake al'ameth","teldrassil","the great tree provides","wellspring lake"},ang={["class:Druid"]="Druider uppskattar de naturligt läkande egenskaperna hos Teldrassils växter och förlitar sig på inhemska växter som lasherskott i stället för konstgjorda blandningar.",["profession:Herbalism"]="För erfarna örtmästare är det naturligt att samla inhemskt växtmaterial som daggiga lasherskott för att brygga kraftfulla läkande salvor.",["race:NightElf"]="Teldrassils örtmediciner speglar kaldoreis tro på att deras världsträd uppehåller och skyddar dem genom att erbjuda levande läkemedel mot plötsliga åkommor."},sec={{t="En kamp mot tiden",b="I den skogsklädda byn Dolanaar vårdar Byancie de lokala nattalverna. När beskedet kommer att Eralya har drabbats av en farlig åkomma ute i Teldrassils vildmark börjar Byancie genast förbereda en akut behandling. Utan en snabbverkande salva som hejdar sjukdomens förlopp överlever Eralya inte färden tillbaka till byn för att få ordentlig vård."},{t="Det väldiga världsträdet",b="Även i krisens stund litar kaldorei på Teldrassils överflöd. Byancie vänder sig till det levande världsträdet för att finna botemedlet och söker daggiga lasherskott som växer nära Lake Al'Ameth i söder och Wellspring Lake i nordväst. Blandade med rent källvatten i en enkel glasflaska ger dessa kraftfulla blad den viktiga medicin som behövs för att hålla åkomman stången."}},faq={{q="Vad är The Great Tree Provides?",a="The Great Tree Provides är ett brådskande uppdrag i Dolanaar från Byancie, som vill blanda till en läkande salva för att hejda en åkomma som hotar Eralya tills vidare behandling blir möjlig.",al={"vad är the great tree provides","uppdraget the great tree provides","byancies uppdrag"}},{q="Vem är Byancie?",a="Byancie är en nattalv och helare eller apotekare som bor i byn Dolanaar på Teldrassil. Hon ägnar sig åt att vårda sjuka och tillreda naturläkemedel av den lokala floran.",al={"vem är byancie","byancie i dolanaar","uppdragsgivaren byancie"}},{q="Vem är Eralya och vad hände henne?",a="Eralya är en drabbad person som befinner sig utanför Dolanaar och vars tillstånd snabbt försämras. Byancie behöver en akut salva för att stabilisera henne länge nog för att hon ska kunna föras tryggt in till byn för fullständig behandling.",al={"vem är eralya","vad hände eralya","eralya åkomma"}},{q="Var hittar man daggiga lasherskott?",a="Daggiga lasherskott växer på växtlashers runt Lake Al'Ameth, rakt söder om Dolanaar, samt längs Wellspring Lake och dess flod i nordväst.",al={"var hittar man daggiga lasherskott","plats för daggiga lasherskott","lasherskott på teldrassil"}},{q="Vilka ingredienser behövs för att tillreda salvan?",a="Byancie behöver sex daggiga lasherskott som plockats från inhemska lashers, en tom flaska och Refreshing Spring Water för att blanda den akuta läkande salvan.",al={"vilka ingredienser behöver byancie","salvans ingredienser i dolanaar","föremål till the great tree provides"}},{q="Var kan man få tag på en tom flaska och Refreshing Spring Water?",a="Både tomma flaskor och Refreshing Spring Water kan köpas direkt av handlare med allmänna varor eller handelsvaror i Dolanaar.",al={"var får man tag på flaska och källvatten","tom flaska i dolanaar","refreshing spring water i dolanaar"}}},fp="23,183,19.267.0,24.258.0,32.152.0,15.138.0,39.157.0,35.139.0,51.102.0,63.91.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below är ett försvarsuppdrag där aggressiva naga-spejare som slagit läger i närheten ska rensas bort. Genom att slå till mot spejarstyrkorna och ta deras ryggfenor försöker äventyrarna driva de ormlika inkräktarna norrut och skydda området.",h="Threat from Below är ett försvarsuppdrag där aggressiva naga-spejare som slagit läger i närheten ska rensas...",kw={"fotsoldater","naga","naga-ryggfenor","spejare","ormavskum","ryggfenor","threat from below"},ang={["faction:Horde"]="Uppdragsgivaren mobiliserar Horde-fotsoldater för att hålla utkik efter eftersläntrare, vilket gör detta till ett förebyggande försvar av Horde-kontrollerat territorium mot naga-spejare som tränger in."},sec={{t="Ormlikt intrång",b="Threat from Below handlar om en växande gränsstörning som orsakas av naga-spejare som tränger in i området. De ormlika plundrarna har börjat anlägga förläger i närheten, så de lokala försvararna slår till innan inkräktarna hinner säkra ett permanent fotfäste. Äventyrarna skickas ut för att slå ut spejarstyrkorna och återvända med naga-ryggfenor som bevis på att lägret har krossats."},{t="Säkra gränsen",b="Det är inte första gången ormfolket stör området, och det lokala befälet gör klart att deras närvaro inte kommer att tolereras. Efter anfallet mot deras spejarläger är målet att driva alla överlevande naga norrut och låta vaksamma Horde-fotsoldater hålla vakt mot eftersläntrare eller plötsliga bakhåll."}},faq={{q="Vad är Threat from Below?",a="Threat from Below är ett Horde-uppdrag där äventyrarna ska eliminera naga-spejare som har börjat anlägga läger i närheten. För att stoppa intrången måste spelarna döda de framryckande ormfolken och samla naga-ryggfenor som bevis på bedriften.",al={"vad är threat from below","uppdraget threat from below"}},{q="Vilka är ormarna som nämns i ordern?",a="”Ormarna” eller ”ormavskummet” syftar på naga, amfibiska ormlika humanoider som har kommit från kusternas eller vattendjupens mörker för att spana på lokala positioner.",al={"vilka är ormarna","ormar i threat from below"}},{q="Varför måste naga-spejarna elimineras?",a="Lägren tyder på en organiserad spaningsinsats, inte kringströvande varelser. Den lokala befälhavaren kräver ett snabbt motangrepp för att driva bort inkräktarna innan de kan inleda ett större anfall eller befästa sina positioner ytterligare.",al={"varför döda naga-spejare","nagas motiv"}},{q="Varför samlas naga-ryggfenor in?",a="Avskurna ryggfenor är ett otvetydigt fysiskt bevis på att spejarlägren har upptäckts och slagits sönder, och bekräftar att det omedelbara trycket längs gränsen har brutits.",al={"varför ryggfenor","bevis från naga"}},{q="Vart förväntas naga dra sig tillbaka?",a="När fenorna lämnas in säger befälhavaren att förhoppningen är att anfallet ska driva naga norrut igen. Fotsoldater får i uppdrag att hålla utkik efter eftersläntrare eller misstänkta rörelser.",al={"vart tar naga vägen","naga norrut"}},{q="Vem håller vakt när spejarna har dödats?",a="Horde-fotsoldater får i uppdrag att hålla vakt i området och se till att inga eftersläntrare finns kvar och att naga inte försöker göra fler intrång.",al={"vem håller utkik efter naga","fotsoldater håller utkik efter naga"}}},fp="17,156,20.218.0,20.232.0,26.149.0,43.142.0,39.192.0,33.150.0,39.121.0,43.86.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="Threat from Below är en belöningsuppgift från Horde där äventyrare får i uppdrag att jaga en farlig havsjätte som stryker längs Durotars norra kust. Att besegra en så väldig kusttitan skyddar stränderna i närheten och vinner Durotars krigares respekt.",h="Threat from Below är en belöningsuppgift från Horde där äventyrare får i uppdrag att jaga en farlig havsjätte...",kw={"blod och åska","kustmonster","durotar","horde-uppdrag","the north coast","havsjätte","threat from below"},ang={["class:Warrior"]="Att möta en väldig havsjätte i direkt strid är ett hårt prov på kamputhållighet och ett sätt att bevisa sig mot en av kustens allra tyngsta bestar.",["faction:Horde"]="När en havsjätte fälls längs Durotars kust försvinner en farlig koloss som lurade alldeles intill Hordes kärnland.",["race:Orc"]="Orchisk heder värdesätter att möta titaniska motståndare och besvara stridsropet ”blod och åska” med överväldigande fysisk styrka."},sec={{t="Den norra kustlinjen",b="Längs Durotars norra kustlinje sköljer Stora havets vatten mot ojämna sandstränder och klippiga kuster. Där brukar enkla asätare och krabbor hålla till, men på den norra kusten lurar ett mycket dödligare hot: en väldig havsjätte som strövar på grunt vatten och hotar alla som försöker färdas längs eller säkra vattnen intill Hordes torra, nya hemland."},{t="Vågornas titan",b="Havsjättar är resliga bestar som kan slå sönder långbåtar och krossa krigare under sina väldiga nävar. Det är ingen vanlig bedrift för unga äventyrare att dräpa en sådan, och den som fäller denna vågarnas koloss vinner stor respekt bland orcherna. Då ekar det traditionella stridsropet ”blod och åska” över de torra, röda klipporna."}},faq={{q="Vad är uppdraget Threat from Below?",a="Threat from Below är ett uppdrag åt Hordes mästare att jaga och besegra en kolossal havsjätte som strövar längs Durotars norra kust och återvända med bevis på bedriften.",al={"vad är threat from below","uppdraget threat from below","havsjätteuppdrag durotar"}},{q="Var hittar man havsjätten?",a="Havsjätten strövar i vattnen och längs stränderna på Durotars norra kust.",al={"var finns havsjätten","havsjättens plats i durotar","platsen för threat from below"}},{q="Vad är en havsjätte för slags varelse?",a="Havsjättar är väldiga, uråldriga kustkolosser som skapades för att muddra haven och forma Azeroths kustlinjer. Få kringvandrande överlever en direkt konfrontation med en av dem.",al={"vad är en havsjätte","havsjättens historia","vilka är havsjättarna"}},{q="Varför måste havsjätten dödas?",a="En så enorm varelse som stryker så nära Durotar utgör en allvarlig fara för kustresenärer, fiskare och Hordes läger längs stranden.",al={"varför döda havsjätten","är havsjätten farlig","hot mot durotar"}},{q="Vad menar uppdragsgivaren med ”blod och åska”?",a="”Blod och åska” är ett traditionellt orcist stridsrop som hyllar kampstyrka, våldsamhet och äran i att segra över farliga motståndare.",al={"betydelsen av blod och åska","orchehälsning blod och åska"}},{q="Vilket bevis krävs för att slutföra uppdraget?",a="Uppdraget kräver att du tar med ett konkret, fysiskt bevis på havsjättens fall från den norra kusten, så att det kan bekräftas att den väldiga besten har dödats.",al={"bevis för threat from below","bevis på bedriften"}}},fp="17,185,22.278.0,20.257.0,36.120.0,29.70.0,37.153.0,45.123.0,54.140.0,44.118.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="Escaping Ban'ethil är ett räddningsuppdrag i den underjordiska gravkammaren på Teldrassil. Sentinel Lynessa Duskblossom, som tillfångatogs av aggressiva Gnarlpine furbolg när hon levererade ett meddelande till sovande druider, måste eskorteras säkert upp till ytan och rapporteras vara i trygghet i Dolanaar.",h="Escaping Ban'ethil är ett räddningsuppdrag i den underjordiska gravkammaren på Teldrassil.",kw={"ban'ethil barrow den","dolanaar","escaping ban'ethil","furbolg","gnarlpine","kaldorei","kyra starsong","lynessa duskblossom","oracle tree","teldrassil"},ang={["class:Druid"]="Ban'ethil Barrow Den är avsedd som en fristad för druider som slumrar medan de kommunicerar med The Emerald Dream. Att den fallit i händerna på vilda furbolg är därför en akut kris för Cenarion-försvararna.",["faction:Alliance"]="Att skydda Darnassus och Teldrassil kräver att man hjälper Sentinels att möta den växande fientligheten från fördärvat inhemskt djurliv och stammar.",["race:NightElf"]="Sentinel Lynessa Duskblossom är en vapensyster vars fångenskap under rötterna går stick i stäv med nattalvernas heliga band till Teldrassils öppna stjärnhimmel och trädkronor."},sec={{t="Bakhåll under rötterna",b="Oracle Tree skickade Sentinel Lynessa Duskblossom på ett brådskande ärende för att överlämna ett meddelande till druiderna som vilade i Ban'ethil Barrow Den. Det som skulle ha varit en vanlig budtjänst slutade i katastrof när hon upptäckte att de underjordiska kamrarna var helt översvämmade av aggressiva Gnarlpine furbolg. Hon blev avskuren och överfallen innan hon hann retirera, och togs till fånga i de mörka tunnlarna. Hon fruktade ett grymt slut i händerna på stammen tills en äventyrare ingrep och kämpade med henne upp till ytan."},{t="Trygg återkomst till Dolanaar",b="För kaldorei Sentinels är det underjordiska mörkret i en gravkammare en onaturlig och motbjudande plats att vara fången på, långt från Elunes rogivande stjärnljus och Teldrassils friska luft. Efter att ha räddats ur djupet flyr Lynessa tillbaka mot civilisationen, medan budet om att hon överlevt förs till Dolanaar. Där tar Sentinel Kyra Starsong emot nyheten om sin väns överlevnad med stor lättnad och belönar dem som hjälpte hennes kamrat att försvara kaldorei-folket."}},faq={{q="Vem är Sentinel Lynessa Duskblossom?",a="Sentinel Lynessa Duskblossom är en night elf-sentinel stationerad på Teldrassil. Oracle Tree skickade henne för att leverera ett viktigt meddelande till druiderna som vilade i Ban'ethil Barrow Den, men hon överfölls och tillfångatogs av Gnarlpine furbolg djupt under marken.",al={"vem är lynessa duskblossom","lynessa duskblossom","vem är fångad i gravkammaren"}},{q="Varför gick Sentinel Lynessa in i Ban'ethil Barrow Den?",a="Oracle Tree skickade henne på ett officiellt uppdrag för att bära ett meddelande till druiderna som slumrade i Ban'ethil Barrow Den. När hon nådde den underjordiska gravkammaren upptäckte hon att fientliga furbolg hade tagit över den innan hon hann överlämna sitt meddelande.",al={"varför gick lynessa till banethil","vad var lynessas uppdrag","meddelande från oracle tree"}},{q="Vem tillfångatog Sentinel Lynessa?",a="Hon tillfångatogs av Gnarlpine furbolg som bodde i gravkammaren. Stammen var fientlig och aggressiv och överföll henne innan hon hann fly och släpade ner henne i djupet, så att hon fruktade att bli deras nästa måltid.",al={"vem tillfångatog lynessa","vilka furbolg finns i banethil","gnarlpine furbolg"}},{q="Vad är Ban'ethil Barrow Den?",a="Ban'ethil Barrow Den är en underjordisk fristad på Teldrassil, väster om Dolanaar. Den höggs traditionellt ut under jorden som viloplats för night elf-druider som gick in i djup gemenskap, men har tagits över av fördärvade Gnarlpine furbolg.",al={"var ligger banethil barrow den","vad är banethil barrow den","gravkammare på teldrassil"}},{q="Vem är Sentinel Kyra Starsong?",a="Sentinel Kyra Starsong är en night elf-sentinel stationerad i byn Dolanaar. Hon är nära vän med Lynessa Duskblossom och väntar ivrigt på nyheter om att Lynessa har flytt och återvänt i trygghet.",al={"vem är kyra starsong","var lämnar jag in escaping banethil","dolanaars sentinel"}},{q="Varför avskyr Lynessa att vara under jord?",a="Druider använder gravkammare för helig sömn, men många night elf-sentinels och krigare ogillar starkt att vara instängda under jord. Kaldorei-kulturen värnar om den öppna natthimlen, Elunes stjärnljus och skogens skyddande grenverk ovanför de underjordiska tunnlarna.",al={"varför ogillar nattalver gravkammare","under jorden hör kaldorei inte hemma"}}},fp="18,232,26.363.0,23.395.0,36.196.0,52.178.0,30.183.0,29.178.0,30.166.0,42.238.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering är ett uppdrag i Teldrassil där du ska ge akut hjälp åt Sentinel Eralya Leafshadow, som ligger svårt sjuk av en häftig röta på vägen till The Oracle Tree. Du skyndar Lashwater Salve till henne för att lindra plågorna och ge ro åt hennes sviktande andning.",h="Easing Suffering är ett uppdrag i Teldrassil där du ska ge akut hjälp åt Sentinel Eralya Leafshadow, som...",kw={"easing suffering","eralya leafshadow","lashwater salve","oracle tree","röta","sentinel eralya","teldrassil"},ang={["faction:Alliance"]="När du hjälper fallna Night Elf-väktare längs vägarna i Darnassus hemland bidrar du till att bevara den sköra frontlinjen mot den växande korrumperingen i Teldrassils grenar.",["race:NightElf"]="Sentinel Eralya Leafshadow är en av dina egna, drabbad av en häftig korrumpering i Teldrassils vildmark nära The Oracle Tree. När du ger henne tröst hedrar du det ansvar som Sentinels har för sina fränder."},sec={{t="En kamp mot rötan",b="Sentinel Eralya Leafshadow ligger svårt sjuk av en snabbt spridande, varig röta på vägen till The Oracle Tree. För att hejda hennes plågsamma försämring måste en nyberedd Lashwater Salve föras till henne utan dröjsmål, innan åkomman får fullt grepp."},{t="Ro i skuggorna",b="De som vårdar henne tvivlar på att Lashwater Salve är stark nog att helt utrota farsoten, men när den ges lugnar den snabbt Eralyas ansträngda, rosslande andning. Det är osäkert om hon överlever, men behandlingen ger henne ro under hennes mörkaste stund."}},faq={{q="Vem är Sentinel Eralya Leafshadow?",a="Sentinel Eralya Leafshadow är en Night Elf-väktare som ligger sjuk längs vägen mot The Oracle Tree. När hon hittas är hon utslagen och nära döden, drabbad av en aggressiv, varig röta.",al={"vem är eralya","eralya leafshadow","vem är sentinel eralya"}},{q="Vad är Lashwater Salve?",a="Lashwater Salve är ett läkemedel som ska lindra den våldsamma smärta som den häftiga rötan orsakar Sentinel Eralya. Det är osäkert om det kan bota åkomman helt, men det lindrar hennes plågor.",al={"vad är lashwater salve","lashwater salve","botar salvan röta"}},{q="Överlever Sentinel Eralya åkomman?",a="Salvan lindrar Sentinel Eralyas andning och ger henne viss ro, men det är fortfarande osäkert om hon verkligen återhämtar sig eller dukar under för rötan som fått fäste.",al={"överlever eralya","är eralya botad","dog eralya"}},{q="Var hittar man Sentinel Eralya Leafshadow?",a="Sentinel Eralya Leafshadow ligger längs stigen mot The Oracle Tree, i Teldrassils uråldriga marker.",al={"var finns oracle tree","vägen till oracle tree","eralya plats"}},{q="Vilken åkomma drabbade Sentinel Eralya?",a="Eralya lider av en aggressiv, varig röta som snabbt sprider sig genom kroppen. Den exakta källan till smittan är okänd, men den angriper snabbt och blir allt häftigare med tiden.",al={"vad orsakade eralyas sjukdom","vad är rötan","eralya åkomma"}},{q="Varför måste salvan levereras skyndsamt?",a="Rötan sprider sig snabbt genom Eralyas kropp och blir värre. Det är nödvändigt att skynda, eftersom varje ögonblick för henne närmare att helt duka under för plågorna och förruttnelsen.",al={"varför skynda med salvan","varför skynda för eralya"}}},fp="16,154,22.200.0,20.222.1,34.154.0,24.157.0,44.135.0,46.89.0,39.144.0,43.165.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="Longwalker Malah är en försvunnen tauren-spejare som skickades för att undersöka Mulgore östra gränstrakter på uppdrag av Bloodhoof Village. Som en av de främsta Longwalker-spejarna, direkt underställd överhövdingen, väcker hennes plötsliga frånvaro efter tre dagar en brådskande efterlysning för att säkra både hennes överlevnad och dalens trygghet.",h="Longwalker Malah är en försvunnen tauren-spejare som skickades för att undersöka Mulgore östra gränstrakter...",kw={"baine bloodhoof","bloodhoof village","fjäderprydd stav","longwalker malah","longwalkers","malah longwind","mulgore","tauren-spejare"},ang={["class:Hunter"]="Jägare respekterar Longwalkers kunskaper i att spåra vildmarken och den uthållighet som krävs för att till fots patrullera Mulgore avlägsna utkanter.",["faction:Horde"]="När du hjälper ledarna i Bloodhoof Village att hitta försvunna gränsspejare bidrar du till att skydda Mulgore mot yttre hot som tränger in på Horde-land.",["race:Tauren"]="Longwalkers är vördnade spejare som rapporterar direkt till överhövdingen Cairne Bloodhoof. Därför är deras säkerhet en fråga av största kulturella och taktiska vikt för alla tauren."},sec={{t="Överhövdingens ögon",b="Longwalkers tjänar som shu'halos ögon och öron. De är kända över slätterna för sina outtröttliga steg och sin överlevnadsförmåga. Dessa elitspejare har svurit trohet direkt till överhövdingen Cairne Bloodhoof och får i uppdrag att färdas genom vidsträckta områden för att samla underrättelser och leverera viktiga budskap. Även om deras trohet ytterst endast tillhör överhövdingen, ber unge Baine Bloodhoof dem ibland om hjälp med att skydda bosättningen Bloodhoof Village och betesmarkerna runtomkring."},{t="Försvunnen vid gränsen",b="Longwalker Malah Longwind skickades för att bevaka Mulgore östra gräns och gav sig ut på ett vanligt spaningsuppdrag som skulle pågå i tre dagar. När hon inte återvände till Bloodhoof Village som väntat började byns ledare bli oroliga. Longwalkers bär på livsviktiga underrättelser, och faror lurar ständigt längs Mulgore gränsklippor. Därför ombeds spejare och villiga resenärer att följa hennes spår och ta reda på om hon är oskadd. Du känner igen Malah på ordens traditionella kännetecken: ett ceremoniellt pannband och en fjäderprydd stav."}},faq={{q="Vem är Longwalker Malah?",a="Longwalker Malah Longwind är en uppskattad tauren-spejare som tjänar överhövdingen. Hon skickades på ett spaningsuppdrag nära Mulgore östra gräns och bar det traditionella pannbandet och den fjäderprydda staven som kännetecknar hennes orden.",al={"vem är malah","malahs bakgrund","longwalker malah identitet"}},{q="Vilka är Longwalkers?",a="Longwalkers är taurenfolkets mest betrodda elitspejare och budbärare. De har svurit trohet direkt till överhövdingen, men andra stamledare, som unge Baine Bloodhoof, ber dem ibland om hjälp med viktig gränsbevakning.",al={"vad är longwalkers","vilka är longwalkers","tauren-spejare"}},{q="Varför letar man efter Longwalker Malah?",a="Malah skickades för att undersöka Mulgore östra utkanter och väntades tillbaka inom tre dagar. När hon inte återvände blev man orolig i Bloodhoof Village för att något kunde ha hänt henne under patrulleringen av den oländiga gränsen.",al={"varför är malah försvunnen","varför malah-uppdraget","vart tog malah vägen"}},{q="Var kan Malah finnas?",a="Longwalker Malah skickades mot Mulgore östra gräns, förbi Bloodhoof Village och mot bergsryggen vid gränsen. Resenärer som söker efter henne bör leta i gränstrakterna öster om byn.",al={"var är malah","malahs plats","hitta malah"}},{q="Hur känner du igen Longwalker Malah?",a="Du känner igen Malah på Longwalkers utmärkande dräkt: ett särskilt pannband och en hög fjäderprydd stav som spejare från den ansedda orden bär.",al={"malahs utseende","hur känner man igen malah","longwalkers utrustning"}},{q="Varför är Baine Bloodhoof inblandad med Longwalkers?",a="Longwalkers rapporterar endast till överhövdingen Cairne Bloodhoof, men hans son Baine sköter lokala angelägenheter i Bloodhoof Village. Ibland ber han dem använda sina spårningskunskaper för att bevaka gränsen och trygga dalen.",al={"baines roll","varför är baine inblandad","baine bloodhoof spejare"}}},fp="16,203,25.371.0,27.450.0,24.193.0,25.197.0,43.189.0,25.154.0,38.106.0,53.244.0"}
P.entries["quest:99080"] = {n="Vertreibt sie",s="Baine Bloodhoof ber dig att röja undan Galak-kentaurerna från byns väg. Deras nederlag kan ge barnen en viss trygghet.",h="Baine Bloodhoof ber dig att röja undan Galak-kentaurerna från byns väg.",kw={"baine bloodhoof","kentaurer","barn","galak","herak the plunderer","spejare","by"},ang={["race:Tauren"]="Som tauren kallar Baine blodspillan en unik heder bland ditt folk."},sec={{t="Galak",b="Baine ber dig att döda sex Galak-kentaurer och fyra Galak-spejare. Ge honom sedan Herak the Plunderers huvud. Byns säkerhet står på spel."},{t="En bys lättnad",b="Baine hör den sista kentauren falla och skenandet upphöra. Han kallar det en stor seger för byn. Barnen där behöver den känslan av trygghet mer än någonsin."}},faq={{q="Vem ber mig att driva bort Galak?",a="Baine Bloodhoof ber dig att ta dig an Galak-kentaurerna och spejarna. Han ber dig också att ge honom Herak the Plunderers huvud.",al={"vem gav detta","baines uppdrag"}},{q="Vad vill Baine att jag ska göra?",a="Döda sex Galak-kentaurer och fyra Galak-spejare åt Baine och ge honom sedan Herak the Plunderers huvud.",al={"vad ska göras","galak-uppdrag"}},{q="Vem är Herak the Plunderer?",a="Herak the Plunderer är en Galak vars huvud Baine ber dig att ge honom.",al={"vem är herak","plundrarens huvud"}},{q="Varför är detta viktigt för byn?",a="Baine säger att segern ger byns barn en känsla av trygghet som de behöver mer än någonsin.",al={"varför hjälpa byn","trygga barn"}}},fp="13,137,9.145.0,20.159.1,35.127.0,29.101.0,27.66.0,36.95.0"}
P.entries["quest:99081"] = {n="Schwieriges Unterfangen",s="Langläuferin Malahs rapport berättar om ett nytt kentaurläger i Mulgore. Kriegerheld Wildrunner behöver veta vad som hände henne, vem som dödade henne och varför lägret tyder på att en liten plundringsstyrka har tagit sig in i landet.",h="Langläuferin Malahs rapport berättar om ett nytt kentaurläger i Mulgore.",kw={"baine","bloodhoof village","kentaurläger","kriegerheld wildrunner","langläuferin malah","malah","mulgore","schwieriges unterfangen"},ang={["race:Tauren"]="Som tauren för du nyheter om en plundringsstyrka av kentaurer i Mulgore till Kriegerheld Wildrunner."},sec={{t="Malahs rapport",b="Du tar med dig Langläuferin Malahs rapport till Kriegerheld Wildrunner i Bloodhoof Village. Han behöver veta vad som hände Malah och vem som dödade henne. Hennes rapport kommer med oroande nyheter, och Baine måste få höra dem genast."}},faq={{q="Vem vill ha Malahs rapport?",a="Kriegerheld Wildrunner i Bloodhoof Village vill ha Langläuferin Malahs rapport.",al={"vem behöver rapporten","wildrunners rapport","vem ska rapporten lämnas till"}},{q="Vad handlar rapporten om?",a="Rapporten handlar om vad som hände Langläuferin Malah och vem som dödade henne.",al={"vad hände malah","malahs rapport","varför är malah död"}},{q="Vad finns i riktningen som pilarna kom från?",a="Ett nytt kentaurläger ligger i den riktning som pilarna som träffade Malah verkar ha kommit från.",al={"nytt kentaurläger","kentaurläger","varifrån kom plundrarna"}},{q="Vad tyder lägret på?",a="Aktiviteten i lägret tyder på att en liten plundringsstyrka har tagit sig in i Mulgore.",al={"kentaurernas plundringståg","plundrare i mulgore","vad betyder lägret"}},{q="Vem behöver få höra nyheterna?",a="Kriegerheld Wildrunner säger att Baine måste få höra nyheterna genast.",al={"underrätta baine","wildrunner underrättar baine","vem blir underrättad"}}},fp="23,220,14.214.0,25.81.0,29.76.0,35.99.0,27.72.0,27.61.0"}
P.entries["quest:99082"] = {n="The High Chieftain",s="Cairne Bloodhoofs son skickar dig till Thunder Bluff för att söka audiens hos sin far. Ditt försvar av ditt folk har vunnit erkännande.",h="Cairne Bloodhoofs son skickar dig till Thunder Bluff för att söka audiens hos sin far.",kw={"audiens","cairne bloodhoof","kentaurer","överhövding","tauren","thrall","thunder bluff"},ang={["race:Tauren"]="Som tauren skickas du till Cairne Bloodhoof efter att ha försvarat ditt folk. Han och Thrall ledde arbetet med att återta slätterna."},sec={{t="En hövdings gärning",b="Cairne Bloodhoof och den unge krigshövdingen Thrall ledde arbetet med att återta dessa slätter från kentaurerna. Som storhövding kan Cairne erkänna din insats för att försvara ditt folk."}},faq={{q="Vem skickas jag för att träffa?",a="Du skickas för att söka audiens hos Cairne Bloodhoof, överhövdingen i Thunder Bluff.",al={"vem är överhövdingen","audiens hos cairne","träffa cairne"}},{q="Varför ska jag till Thunder Bluff?",a="Ditt mod i försvaret av ditt folk har vunnit erkännande. Därför ombeds du att söka audiens hos Cairne Bloodhoof.",al={"varför thunder bluff","vad vill cairne","möte med cairne"}},{q="Vem hjälpte till att återta slätterna?",a="Cairne Bloodhoof och den unge krigshövdingen Thrall ledde arbetet med att återta slätterna från kentaurerna.",al={"vem stred mot kentaurerna","thrall och cairne","återta slätterna"}},{q="Var är Cairne?",a="Cairne Bloodhoof befinner sig på den centrala höjden i Thunder Bluff.",al={"var är överhövdingen","cairnes plats","hitta cairne"}}},fp="18,136,20.180.0,27.98.0,32.121.0,30.102.0,16.54.0"}
P.entries["quest:991"] = {n="Raene's Cleansing",s="Raene's Cleansing börjar när Raene Wolfrunner ber en äventyrare att leta reda på hennes försvunne vän Teronis. För att hitta ett sätt att hejda furbolgernas våldsamma angrepp i Ashenvale gav sig Teronis av mot Lake Falathim för att hämta en magisk ädelsten.",h="Raene's Cleansing börjar när Raene Wolfrunner ber en äventyrare att leta reda på hennes försvunne vän Teronis.",kw={"ashenvale","falathim","furbolg","ädelsten","murloc","raene","teronis","wolfrunner"},ang={["faction:Alliance"]="Alliansens rekryter som anländer till Astranaar får snart veta att Ashenvales heliga lundar belägras av fientliga vilddjur, furbolger och invaderande murlocs.",["race:NightElf"]="Teronis försvinnande är ännu ett hårt slag för nattalverna, som redan har fullt upp med att hela Ashenvale och skydda sina helgedomar från korruption."},sec={{t="En väns oro",b="Raene Wolfrunner tjänstgör tillsammans med Sentinels i Astranaar och försvarar Ashenvale mot växande hot. Teronis var en av hennes närmaste följeslagare och tog på sig att hitta ett kraftfullt försvar mot de allt våldsammare furbolgstammarna. När dagarna gick utan att han återvände blev Raene djupt orolig. Hon kunde inte lämna sin post, men fruktade det värsta."},{t="Jakten på staven",b="Teronis följde rykten om en mäktig stav som smitts av en avliden, ondskefull trollkarl. Han trodde att dess magi kunde stilla furbolgernas raseri. För att återställa artefakten behövde han en förtrollad ädelsten som gömts i en alvisk helgedom vid Lake Falathim, nära bergen i väster. Tyvärr hade aggressiva murlocstammar nyligen tagit över de fridfulla vattnen."},{t="Tragedin vid Lake Falathim",b="När du följer Teronis spår till ön i Lake Falathim möts du av en mörk syn. Teronis tog sig aldrig levande ur vattnet. Hans döda kropp ligger vid helgedomen, täckt av djupa hugg från murlocernas vapen och klor. Hans sökande fick ett alltför tidigt slut."}},faq={{q="Vem är Raene Wolfrunner?",a="Raene Wolfrunner är en nattalv som är allierad med Ashenvales Sentinels och stationerad i Astranaar. Hon leder olika försvarsinsatser för att skydda skogen mot fiender som tränger in.",al={"raene","vem är raene","uppdragsgivare"}},{q="Vem var Teronis?",a="Teronis var en nära vän till Raene Wolfrunner som sökte efter forntida magiska lösningar för att rädda skogen. Han trodde att en förtrollad stav kunde lugna de korrumperade furbolgerna och gav sig ensam av för att hämta dess delar.",al={"vem är teronis","teronis bakgrund","försvunnen vän"}},{q="Var försvann Teronis?",a="Teronis försvann vid Lake Falathim, en sjö vid foten av bergen i västra Ashenvale, som hade översvämmats av fientliga murlocs.",al={"var är teronis","teronis plats","lake falathim"}},{q="Varför letade Teronis efter en ädelsten?",a="Ädelstenen var en viktig del som behövdes för att ge kraft åt en magisk stav skapad av en avliden, ond trollkarl. Teronis hoppades kunna använda stavens kraft för att hejda de rasande furbolgernas angrepp.",al={"vilken ädelsten","varför ädelsten","teronis ädelsten"}},{q="Vad hände med Teronis?",a="Raene har inte hört från honom sedan han gav sig av till Lake Falathim. Om du följer hans spår får du veta vad som hände honom.",al={"hur dog teronis","teronis mördare","vem dödade teronis"}},{q="Varför angriper furbolgerna Ashenvale?",a="Efter det tredje kriget föll Ashenvales furbolger offer för demonisk korruption och vansinne. Det drev stammar som en gång levt i fred till skoningslös, våldsam fientlighet mot sina tidigare allierade.",al={"furbolgangrepp","varför är furbolgerna aggressiva","furbolgernas vansinne"}}},fx={["82e89856"]={q="Varför vill Raene Wolfrunner att Teronis ska hittas?",a="Teronis är en gammal och betrodd vän till Raene Wolfrunner som ställde upp för att hjälpa Sentinels mot de rasande furbolgs. Han gav sig av för att söka efter en magisk stav och ädelsten som kanske kunde stoppa angreppen på deras folk, men han kom aldrig tillbaka. Raene oroar sig djupt för hans säkerhet och är desperat efter att få veta vilken hjälp han kan ha funnit åt deras hårt ansatta länder.",al={"varför vill raene hitta teronis","raene wolfrunners motiv","varför leta efter teronis"}}},fp="17,245,18.364.0,22.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99101"] = {n="Our Ancient Enemy",s="Malahs rapport har nått Baine Bloodhoof, och hans svar är dystert. Saken kommer inte att förbli obesvarad.",h="Malahs rapport har nått Baine Bloodhoof, och hans svar är dystert.",kw={"urgammal fiende","baine bloodhoof","malah","vår urgamla fiende","rapport"},faq={{q="Vem tar emot Malahs rapport?",a="Baine Bloodhoof tar emot Malahs rapport.",al={"vem får rapporten","baines rapport","malahs rapport"}},{q="Vad säger Baine om rapporten?",a="Efter att ha läst Malahs rapport säger Baine att saken inte kommer att förbli obesvarad.",al={"baines reaktion","vad säger baine","svar på rapporten"}},{q="Vem kom med rapporten till Baine?",a="Du tar med dig Malahs rapport till Baine Bloodhoof.",al={"ta med malahs rapport","vem överlämnar den","rapport till baine"}}},fp="17,102,28.40.0,37.75.0,32.44.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match är ett introduktionsprov under kampinstruktören Tang Stonehoofs uppsikt. Provet prövar nykomlingar oavsett klass eller bakgrund. Äventyrarna ska besegra tre arenanybörjare eller andra duellanter för att visa sitt mod i direkt strid.",h="Sparring Match är ett introduktionsprov under kampinstruktören Tang Stonehoofs uppsikt.",kw={"arena","stridsträning","duell","novice warrior","sparring","sparring match","tang stonehoof"},ang={["class:Warrior"]="Tang Stonehoof kan inte träna icke-krigare i deras särskilda discipliner, men hans sparringring betonar krigarfilosofin: att stridsgrunder, mod och stärkt kampvilja är till nytta för alla äventyrare.",["race:Tauren"]="Tang Stonehoof använder traditionella taurenuttryck som ”vässa hornen” för att beskriva hur man prövar sitt mod. Han välkomnar alla villiga motståndare till sparringarenan, oavsett ursprung."},sec={{t="Sparring Grounds",b="Den erfarne instruktören Tang Stonehoof håller uppsikt över sparringmatchen, där äventyrare med alla slags bakgrunder bjuds in i ringen för att pröva sitt mod. Tang uppmärksammar särskilt dem som följer andra vägar än krigarens, men menar att kampdisciplin och direkt strid ger alla resenärer visdom i en farlig värld."},{t="Vässa hornen",b="I Tang Stonehoofs arena suddas skillnader i härkomst och vapenval ut. Oavsett om utmanarna använder svärd, båge eller magi ska de visa att de är redo för strid genom att besegra tre villiga motståndare, antingen träningskrigarna Novice Warriors eller andra äventyrare i dueller. När du klarar dessa kamper vinner du Tangs respekt och bandage att lägga om såren efter en ärlig strid."}},faq={{q="Vem är Tang Stonehoof?",a="Tang Stonehoof är en stridsinstruktör som håller uppsikt över den lokala sparringarenan. Även för dem som följer andra vägar än krigarens erbjuder Tang stridsundervisning och bjuder in lovande äventyrare att pröva sitt mod i direkt strid mot nybörjare eller villiga motståndare.",al={"vem är tang stonehoof","tang stonehoof bakgrund","uppdragsgivare"}},{q="Vad kräver Tang Stonehoof för sparringmatchen?",a="Provet kräver att du besegrar tre motståndare i arenan, antingen andra äventyrare som vill duellera eller Novice Warriors som tränar där under Tang Stonehoofs ledning. Syftet är att visa att du är redo och har förmåga att strida direkt.",al={"sparring match mål","vad göra i sparring match","vem ska man slåss mot"}},{q="Varför tränar en krigarinstruktör andra klasser?",a="Tang Stonehoof tror att alla äventyrare har nytta av att möta direkt strid, oavsett om de använder klinga, båge eller magi. I hans arena betyder härkomst och klassens särskilda disciplin mindre än viljan att pröva sig själv och stärka sin kampvilja.",al={"kan icke-krigare delta","varför sparring för andra klasser","inte en krigare"}},{q="Var äger sparringmatchen rum?",a="Tävlingen äger rum precis framför Tang Stonehoof i den öppna sparringarenan, där nybörjare tränar och villiga utmanare kan mötas på lika villkor.",al={"var slåss man mot nybörjare","arenans plats","var finns ringen"}},{q="Kan du duellera med andra spelare i stället för med nybörjarkrigarna?",a="Ja. Tang Stonehoof godtar segrar över både Novice Warriors som tränar i arenan och andra äventyrare som besegras i formella dueller. Det enda han bryr sig om är att du prövar din förmåga mot villiga motståndare.",al={"kan jag slåss mot spelare","duellera med spelare för uppdraget","novice warriors eller spelare"}},{q="Vad säger Tang Stonehoof när du har klarat matchen?",a="När du har bevisat dig mot tre motståndare erkänner Tang din skicklighet och uttrycker hopp för den nya generationen. Han erbjuder förbandsmaterial så att du kan ta hand om dina sår inför den hårda väg som väntar.",al={"belöning för sparring match","vad ger tang dig"}}},fp="14,178,20.258.0,20.304.0,22.197.0,56.215.0,50.222.0,41.167.0,58.196.0,57.195.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="'Lost in the Shadows' är ett uppdrag där Pal'juh, en impulsiv jägare som ensam gav sig in i faran, måste räddas. Räddningen visar hur vildmarkens spårare måste balansera rå aggressivitet med tålamod när de smyger på sitt byte.",h="'Lost in the Shadows' är ett uppdrag där Pal'juh, en impulsiv jägare som ensam gav sig in i faran, måste...",kw={"jägare","lost in the shadows","pal'juh","paljuh","rovfågel","tiger"},ang={["class:Hunter"]="Uppdraget lyfter fram en grundläggande jägarregel: ha tålamod och smyg som en tiger i stället för att rusa vårdslöst fram som en hungrig rovfågel.",["race:Troll"]="Pal'juhs namn och temperament speglar unga Darkspear-jägare som ivrigt vill bevisa sin skicklighet i vildmarken innan de har lärt sig behärskning."},sec={{t="En vårdslös spejare",b="'Lost in the Shadows' handlar om att hitta och rädda Pal'juh, en skicklig men hetlevrad jägare som ensam gav sig ut i fientligt territorium. Hon ville inte vänta på förstärkning och hamnade snart i en situation hon inte kunde hantera, så hon behövde hjälp utifrån för att komma hem oskadd."},{t="Jaktens tålamod",b="När Pal'juh har räddats påpekar hennes övervakare att hennes potential som spejare och spårare är obestridlig, men att hon rusar rakt in i faran som en rovfågel i stället för att smyga med en tigers tålamod. Att hon överlevde prövningen är en tydlig påminnelse om vildmarkens skoningslösa natur."}},faq={{q="Vem är Pal'juh?",a="Pal'juh är en lovande ung jägare som är känd för att ge sig ut på egen hand i farliga områden. Hon är skicklig, men har rykte om sig att handla förhastat och hamna i kläm eller bli övermannad av vilddjur och vildmarken.",al={"vem är paljuh","paljuhs bakgrund","pal'juh"}},{q="Vad händer under uppdraget 'Lost in the Shadows'?",a="I 'Lost in the Shadows' gav sig Pal'juh ut ensam och råkade illa ut igen. En äventyrare behövdes för att spåra upp henne och hjälpa henne innan hon skadades allvarligt.",al={"vad hände i lost in the shadows","bakgrund till uppdraget lost in the shadows","berättelsen om lost in the shadows"}},{q="Varför säger uppdragsgivaren att Pal'juh beter sig mer som en rovfågel än en tiger?",a="Jämförelsen handlar om jaktteknik och disciplin. En rovfågel kastar sig fram aggressivt utan försiktighet eller eftertanke, medan en tiger väntar, smyger tålmodigt och slår till med precision och beräknande list.",al={"varför rovfågel och tiger","betydelsen av mer som en rovfågel än en tiger","jägare rovfågel tiger"}},{q="Vem tar emot rapporten för Lost in the Shadows?",a="Uppdraget avslutas hos en mentor eller jämlike som känner Pal'juh väl nog för att förutse hennes vårdslöshet och uttrycker lättnad över att någon ingrep och räddade den egensinniga spåraren.",al={"vem lämnar in lost in the shadows","uppdragsgivaren för lost in the shadows"}},{q="Lär sig Pal'juh något av det här missödet?",a="Pal'juh klarade sig tack vare hjälp utifrån, men de som har uppsikt över henne håller fortfarande ögonen på om hon verkligen lär sig hur farligt det är att ge sig av ensam.",al={"lärde sig paljuh något","mår paljuh bra"}},{q="Anses Pal'juh vara en skicklig jägare?",a="Hon anses vara en lovande jägare med stor medfödd talang och mod, men hennes mentorer varnar för att instinkt inte kan ersätta taktiskt tålamod när man spårar farligt byte.",al={"är paljuh en bra jägare","paljuhs skicklighet"}}},fp="19,119,16.176.0,20.193.0,15.144.0,52.126.0,74.166.0,48.135.0,53.135.0,39.132.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="A Net Disaster är ett uppdrag i Elwynn Forest som kretsar kring en ovanlig störning vid Crystal Lake. Mete och lina ger ingen fångst, och till och med småfiskarna har försvunnit från det grunda vattnet. Därför skickas äventyrare ut för att undersöka nattens fällor. De förstörda fällorna visar att fientliga grannar aktivt saboterar den lokala fiskeutrustningen.",h="A Net Disaster är ett uppdrag i Elwynn Forest som kretsar kring en ovanlig störning vid Crystal Lake.",kw={"a net disaster","crystal lake","elwynn forest","fiskbestånd","fiskefällor","lee","murlocs","besvärliga grannar"},ang={["faction:Alliance"]="Crystal Lake ligger mitt i Elwynn Forest, så störningar här hotar direkt försörjningen och förråden som stöder hjärtat av Alliansens territorium."},sec={{t="Oroliga vatten vid Crystal Lake",b="Vid Crystal Lake i Elwynn Forest står de lokala fiskarna inför en oroväckande brist på fångst. Tomma krokar är inget ovanligt, men när inte ens småfisk syns i det grunda vattnet blir det vardagliga fisket ett allvarligt mysterium. För att rädda det som går sätter de ut fällor över natten i hopp om att få upp ett grundbestånd."},{t="Förstörda fällor och besvärliga grannar",b="När de nedsänkta fällorna dras upp visar det sig att problemet inte beror på otur, utan på rent sabotage och förstörelse. Fientliga grannar längs sjöns stränder har förstört fällorna och hotar att driva de lokala fiskarna ur branschen om ingen gör något."}},faq={{q="Vad är A Net Disaster?",a="A Net Disaster är ett uppdrag vid Crystal Lake i Elwynn Forest. De lokala fiskarna har märkt att fisken slutat nappa och att till och med småfiskarna har försvunnit. Därför undersöker de nattens fällor.",al={"vad är a net disaster","uppdraget a net disaster","a net disaster vid crystal lake"}},{q="Var ska du undersöka fiskefällorna?",a="Fiskefällorna ligger nedsänkta i Crystal Lake. Lee satte ut dem över natten för att säkra fiskbeståndet när vanligt mete med krok och lina inte gav någon fångst.",al={"var finns fällorna","a net disaster plats","fällor i crystal lake"}},{q="Vem är Lee?",a="Lee är en lokal fiskare vid Crystal Lake som satte ut fällor över natten för att säkra fångsten när fisken slutade nappa på krok och lina.",al={"vem är lee","lee fiskare"}},{q="Vad hände med fisken i Crystal Lake?",a="Fisken har helt försvunnit från ytvattnet, och inte ens en enda småfisk syns till. Undersökningen visar att nattens fällor har förstörts av nya besvärliga grannar.",al={"vad hände med fisken i crystal lake","varför finns det ingen fisk i crystal lake","tomma crystal lake"}},{q="Vilka är de besvärliga grannarna som nämns i slutet?",a="Uppdragsgivaren syftar på nya besvärliga grannar som tränger sig in vid Crystal Lake. Aggressiva murlocs har slagit läger i och längs vattnet och ställt till oreda bland det lokala djurlivet och fiskeutrustningen.",al={"vilka är de besvärliga grannarna","a net disaster besvärliga grannar","vem förstörde fällorna"}},{q="Varför är fiskbristen ett så stort problem för fiskarna?",a="Uppdragsgivaren är direkt beroende av fiskbeståndet i Crystal Lake för sin försörjning. Med skadade fällor och tomma fångster hotar ekonomisk ruin om störningen inte stoppas.",al={"varför bryr sig uppdragsgivaren","fisket vid crystal lake"}}},fp="14,165,31.208.0,39.181.1,23.152.0,39.145.0,11.133.0,42.126.0,55.161.0,61.141.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="Slimy Menace handlar om en växande murlocinvasion längs stränderna vid Crystal Lake i Elwynn Forest. Dessa aggressiva varelser hotar att tömma sjön på fisk och utsätta lokalbefolkningen i närheten för fara. Snabba åtgärder krävs för att hålla deras antal nere.",h="Slimy Menace handlar om en växande murlocinvasion längs stränderna vid Crystal Lake i Elwynn Forest.",kw={"crystal lake","elwynn forest","fisk","goldshire","murloc","murlocer","slimy menace"},ang={["faction:Alliance"]="Att säkra stränderna vid Crystal Lake skyddar lokala fiskare i Elwynn och resenärer nära Goldshire från aggressiva murlocräder.",["race:Human"]="För folket i Elwynn Forest hotar murlocernas framryckning direkt deras vattenleder, matförråd och tryggheten i närliggande bosättningar."},sec={{t="Problem vid Crystal Lake",b="Längs den östra stranden vid Crystal Lake har en aggressiv murlocgrupp fått fäste. Dessa vilda, halvvattenlevande varelser har vassa tänder och ett häftigt temperament, och har förvandlat en gång så fridfull sjö till en farlig födopplats. Lokalbefolkningen är starkt beroende av sjön för sin dagliga försörjning, men murlocernas närvaro hotar nu alla som vågar fiska eller närma sig vattenbrynet."},{t="En ändlös invasion",b="Utöver den fysiska fara de utgör för resenärer hotar murlocer att sluka varenda fisk i sjön om de tillåts föröka sig obehindrat. När deras antal minskar får vattnen i området ett välbehövligt andrum, men deras kusliga, ekande läten är fortfarande en dyster påminnelse om deras envishet. Även när de skingras fyller murlocer snabbt på sina led, så strandlinjen måste hållas under ständig uppsikt."}},faq={{q="Vad handlar uppdraget Slimy Menace om?",a="Slimy Menace är en lokal uppgift som gäller den aggressiva murlocpopulationen vid Crystal Lakes avlägsna stränder. Om de lämnas ifred slukar dessa groddjurslika varelser den lokala fisken och hotar alla som arbetar eller färdas i närheten.",al={"vad är slimy menace","information om uppdraget slimy menace","sammanfattning av slimy menace"}},{q="Var utspelar sig händelserna i uppdraget?",a="Oroligheterna utspelar sig runt Crystal Lake i Elwynn Forest, där en grupp murlocer har samlats på den motsatta stranden. Deras närvaro stör sjöns naturliga djurliv och utgör en fara för lokalbefolkningen.",al={"var finns murlocer vid crystal lake","var ligger crystal lake","var händer detta"}},{q="Varför måste murlocer vid Crystal Lake gallras ut?",a="Murlocer tömmer snabbt sjön på fisk och terroriserar samtidigt omgivningen med sitt vilda temperament och sina vassa tänder. Att decimera deras antal hjälper till att skydda fisket i sjön och hejdar tillfälligt deras aggressiva utbredning.",al={"varför döda murlocer vid crystal lake","murlocer äter fisk","vad är problemet med murlocer"}},{q="Löser det problemet permanent att röja undan murlocer?",a="Att gallra ut murlocer ger bara en tillfällig lättnad. Som det framgår när uppgiften är slutförd förökar sig murlocer och samlar sig igen i oroväckande takt, så deras antal återhämtar sig snabbt trots de första förlusterna.",al={"är murlocer borta för alltid","utrotade vi murlocer","kommer murlocer tillbaka till crystal lake"}},{q="Vem ber om hjälp med det slemmiga hotet?",a="Uppgiften ges av en invånare i Elwynn som oroar sig för Crystal Lakes tillstånd. Plågad av murlocernas obehagliga läten och glupska aptit ber personen äventyrare att minska deras antal för att skydda fisket.",al={"vem ger slimy menace","uppdragsgivare för slimy menace"}},{q="Vad gör murlocer så hotfulla?",a="Murlocer beskrivs som vilda, lättretliga groddjurslika varelser med vassa tänder och ett ökänt, gutturalt läte. De samlas längs stränderna, försvarar sitt revir aggressivt och anfaller allt som kommer för nära deras födoplatser.",al={"hur är murlocer","murlocers beteende vid crystal lake"}}},fp="12,155,23.269.0,22.271.0,37.152.0,45.170.0,47.207.0,58.143.0,40.184.0,37.228.0"}
P.entries["quest:99129"] = {n="A Man About a Murloc",s="A Man About a Murloc är ett ärende åt fiskaren Jason, som plågas av att murlocer i trakten rövar bort hans fisk. Jason skickar äventyrare till Remy \"Two Times\", en lokal särling med ett djupt agg och egna planer mot varelserna.",h="A Man About a Murloc är ett ärende åt fiskaren Jason, som plågas av att murlocer i trakten rövar bort hans...",kw={"a man about a murloc","elwynn","fisk","jason","murloc","remy two times"},ang={["faction:Alliance"]="Bosättningar vid sjöar och bryggor drabbas ofta av murloc-intrång. Det tär på invånare och vakter i Elwynn och närliggande alliansområden."},sec={{t="Problem på vattnet",b="Fiskaren Jason har tröttnat på att murlocer rövar bort hans fångst. Eftersom Remy \"Two Times\" delar hans hat mot groddjuren skickar Jason resenärer till Remy för att höra om han har kommit på några praktiska sätt att driva bort dem från vattnen."},{t="Remys vedergällning",b="När någon söker upp Remy ger han uttryck för sin frustration över att vakterna i trakten inte lyssnar på hans ständiga varningar om murloc-hotet. I stället för att vänta på officiell hjälp förbereder Remy egna motåtgärder mot varelserna och tar hjälp av dugliga resenärer för att genomföra sina planer."}},faq={{q="Vem ger uppdraget A Man About a Murloc?",a="Fiskaren Jason skickar äventyrare på det här ärendet för att få råd om hur han kan hindra murlocer från att röva bort hans fångst.",al={"vem ger a man about a murloc","vem startar a man about a murloc","jasons murloc-uppdrag"}},{q="Vem är Remy \"Two Times\"?",a="Remy \"Two Times\" är en invånare som är känd för sina ständiga klagomål och varningar om murlocer. Jason vänder sig till honom för att få praktiska råd om hur de kan hållas borta.",al={"vem är remy two times","remy two times i elwynn","var finns remy"}},{q="Varför vill Jason rådfråga Remy?",a="Murlocer har trängt in på Jasons fiskeplatser och stulit hans fisk, så han söker hjälp utifrån för att skydda sitt levebröd.",al={"varför behöver jason hjälp","jasons fisk och murlocer","jasons murloc-problem"}},{q="Vad planerar Remy att göra åt murlocer?",a="Remy säger att stadsvakterna ignorerar hans varningar, så han smider egna planer på vedergällning mot varelserna och behöver hjälp av en äventyrare med att samla material.",al={"remy two times idéer","vad är remys plan","remys plan mot murlocer"}},{q="Varför har inte vakterna tagit hand om murlocer?",a="Enligt Remy har han upprepade gånger försökt varna vakterna i trakten för det växande murloc-problemet, men de har vägrat att ta hans varningar på allvar.",al={"vakterna och murlocer i elwynn","varför hjälper vakterna inte remy","remys varning till vakterna"}},{q="Vad händer efter att man talat med Remy?",a="När du talar med Remy leder det direkt vidare till hans egna planer på att slå tillbaka mot murlocer i trakten, och fler uppgifter väntar på hans vägnar.",al={"vart leder a man about a murloc","efter a man about a murloc","nästa uppdrag efter remy"}}},fp="20,132,20.217.0,18.186.0,41.76.0,24.140.0,36.82.0,44.119.0,46.100.0,36.120.0"}
P.entries["quest:99130"] = {n="An Enticing Offer",s="'An Enticing Offer' är ett lokalt initiativ för att hålla murlocer på avstånd med bete gjort på giftigt duskweed. Genom att skörda det skadliga ogräset från närliggande åkrar hjälper planen lokala odlare och håller skadedjur borta från stranden.",h="'An Enticing Offer' är ett lokalt initiativ för att hålla murlocer på avstånd med bete gjort på giftigt...",kw={"an enticing offer","duskweed","jason","murlocbete","murlocer","giftigt bete"},ang={["class:Hunter"]="Spårare och bestmästare bör känna till duskweeds giftiga egenskaper, eftersom betet utgör en allvarlig fara för husdjur och jaktföljeslagare om de får i sig det.",["profession:Herbalism"]="Samlare som känner till traktens växter känner igen duskweeds dubbla natur: det är ett besvärligt ogräs vars giftiga kronblad måste hanteras varsamt när du tillreder kraftigt bete."},sec={{t="En lösning på två problem",b="Att hantera utbredda murlocangrepp kräver ofta uppfinningsrik skadedjursbekämpning i stället för ändlösa strider vid fronten. 'An Enticing Offer' föreslår en smart lösning på två lokala problem på en gång: att tillverka särskilt bete spetsat med duskweed som hindrar murlocer från att tränga in på bebodda marker, samtidigt som ogräset röjs bort från närliggande åkrar."},{t="Duskweeds egenskaper",b="Huvudingrediensen i blandningen är duskweed, ett seglivat vilt ogräs som plågar närliggande odlingsmark. I stora mängder innehåller duskweeds kronblad kraftiga gifter som är skadliga för de flesta djur. Genom att samla in ogräset direkt från drabbade bönder rensas fälten från en aggressiv ogräsväxt, och den giftiga skörden ger samtidigt grunden för att lära murlocflockar att hålla sig undan."},{t="Bete i vattnet",b="Blandningen är relativt enkel att tillreda, men eftersom duskweed är giftigt för alla slags varelser är det riskabelt att hantera. Husdjur måste hållas långt borta från den färdiga blandningen, och uppdragsgivaren varnar innan du ger dig av för att bekanta i trakten, särskilt någon vid namn Jason, inte ska missta det illaluktande betet för mat."}},faq={{q="Vad är uppdraget An Enticing Offer?",a="An Enticing Offer är ett uppdrag som går ut på att hantera murlocproblemen i trakten och samtidigt hjälpa närliggande bönder. Du samlar ingredienser för att tillreda ett särskilt giftigt bete som ska hålla varelserna borta.",al={"vad är an enticing offer","vad är det här för uppdrag"}},{q="Vad är duskweed?",a="Duskweed är ett vanligt ogräs som sprider sig på traktens åkrar. Det betraktas oftast som ett jordbruksskadedjur, men dess kronblad är giftiga för de flesta djur i stora mängder. Därför kan det användas som ett effektivt avskräckande bete när det koncentreras.",al={"vad är duskweed","duskweed-växt","duskweeds effekter"}},{q="Hur är det tänkt att murlocbetet ska fungera?",a="Planen är att tillreda bete med giftiga duskweed-kronblad. Målet är inte vanlig utrotning, utan att göra betet så obehagligt eller skadligt att traktens murlocer lär sig att undvika området.",al={"hur fungerar betet","giftbete för murlocer","varför göra bete"}},{q="Vem är Jason?",a="Jason är fiskaren som skickade dig till Remy på grund av sina murlocproblem. När det giftiga duskweed-betet är färdigt säger Remy att du ska be Jason att inte äta något av det.",al={"vem är jason","låt inte jason äta det","varning om jasons bete"}},{q="Är murlocbetet farligt för andra varelser?",a="Ja. Duskweed-kronblad är giftiga för de flesta djur i stora mängder, trots att betet är avsett för murlocer. Uppdragsgivaren varnar särskilt för att husdjur och följeslagare måste hållas långt borta från blandningen.",al={"är duskweed-bete farligt","giftbete för husdjur"}},{q="Varför är det en win-win att samla duskweed?",a="Duskweed sprider sig aggressivt på odlad mark och ställer till problem för traktens odlare. När du samlar ogräset för att blanda bete rensas åkrarna samtidigt som du får materialet du behöver för att hålla murlocer borta.",al={"varför hjälpa bönder","win-win-situation"}}},fp="17,106,18.229.0,22.296.0,18.227.0,36.144.0,17.165.0,40.130.0,13.123.0,48.127.0,47.160.0"}
P.entries["quest:99131"] = {n="Baited for Success",s="I Baited for Success hjälper du den lokala fiskaren Jason Mathers att hantera ett störande murlocangrepp. Genom att samarbeta med Remy och förbereda ett målinriktat, förgiftat bete hoppas Mathers kunna rensa vattnen och tryggt börja sälja sin fångst igen.",h="I Baited for Success hjälper du den lokala fiskaren Jason Mathers att hantera ett störande murlocangrepp.",kw={"baited for success","fiske","jason mathers","murloc","förgiftat bete","remy"},ang={["class:Rogue"]="Att använda ett specialanpassat gift för att bekämpa besvärliga murlocs visar på en praktisk och lågmäld problemlösning.",["faction:Alliance"]="Genom att säkra vattnen och återställa lokala näringar som fisket kan bosättningarna få förnödenheter samtidigt som antalet aggressiva murlocs minskar."},sec={{t="En fiskares dilemma",b="Jason Mathers är beroende av öppet vatten för sitt fiske, men ett angrepp av aggressiva murlocs har stört hans arbete. Eftersom han inte kan sälja sin fisk på ett säkert sätt söker han en lösning för att bli av med varelserna. Remy hjälper till genom att tillverka ett särskilt förgiftat bete som ska minska antalet murlocs i området så att vanligt fiske kan återupptas."},{t="En riktad lösning",b="Remy förbereder den giftiga blandningen och lovar att gå igenom hur den ska användas, så att giftet bara träffar murlocs utan att förorena fisken. När Mathers får besked planerar han att hämta blandningen senare samma dag och hoppas att den äntligen ska rensa vattnen och återställa hans försörjning."}},faq={{q="Vem förberedde betet åt Jason Mathers?",a="Remy förbereder det särskilda betet åt Jason Mathers och lovar att förklara hur det ska användas när Mathers kommer förbi senare under dagen.",al={"vem ger uppdraget baited for success","remys betesuppdrag","vem gjorde betet"}},{q="Varför behöver Jason Mathers det här betet?",a="Jason Mathers är en fiskare som har svårt att sälja sin fångst på grund av de lokala murlocs. Det förgiftade betet ska minska antalet murlocs utan att skada fisken som han vill fånga och sälja.",al={"varför behöver jason mathers bete","mathers fiskeverksamhet","varför förgiftat bete"}},{q="Kommer det förgiftade betet att skada fisken?",a="Mathers nämner särskilt sin oro för att fiskarna kan äta betet. Planen går ut på att giftet ska träffa murlocs men lämna fisken oskadd, så att Mathers kan återuppta sin försörjning.",al={"är betet säkert för fisk","dödar förgiftat bete fisk"}},{q="Var slutförs uppgiften?",a="Uppgiften slutförs genom att du lämnar beskedet direkt till Jason Mathers och berättar att Remy håller på att förbereda betet.",al={"var lämnar jag in baited for success","slutet på uppdraget baited for success"}},{q="Vilket hot utgör murlocs för Mathers?",a="Murlocs stör de lokala fiskevattnen, vilket gör det omöjligt eller farligt för fiskare som Mathers att försörja sig tills deras antal minskar.",al={"varför döda murlocs här","mathers murlocproblem"}},{q="Vad planerar Mathers att göra när han hört från Remy?",a="När beskedet har lämnats bestämmer sig Mathers för att gå till Remy senare under dagen för att hämta det förgiftade betet och få instruktioner om hur han använder det säkert.",al={"vad händer efter att meddelandet lämnats","får mathers betet"}}},fp="18,149,21.212.0,19.223.1,40.121.0,38.175.0,37.154.0,29.69.0,43.144.0,49.123.0"}
P.entries["quest:99134"] = {n="Discipline",s="Discipline är ett uppdrag från Executor Zygand i Tirisfal Glades. Han är inte imponerad av den lokala Deathguard-garnisonens duglighet och ger därför utomstående äventyrare i uppdrag att ge slappnande odöda vaktposter en fysisk tillrättavisning.",h="Discipline är ett uppdrag från Executor Zygand i Tirisfal Glades.",kw={"dark lady","deathguard","discipline","executor zygand","forsaken","motivator","tirisfal glades","odöda"},ang={["faction:Horde"]="Forsaken-befälhavarnas bistre metoder visar hur hårda och oförsonliga förhållandena är i Hordens nordliga utmarker.",["race:Undead"]="För Forsaken är militär disciplin en fråga om artens överlevnad. Vaktposter som ger efter för apati äventyrar hela Tirisfal Glades."},sec={{t="Ordning bland de odöda",b="Deathguard utgör ryggraden i Forsakens armé i Lordaeron, men friheten från Lich Kings järnvilja för med sig egna problem: apati, trötthet och försummelse. Hårda uppsyningsmän som Executor Zygand har föga tålamod med slapp disciplin, särskilt när hot från Scarlet Crusade och Scourge stryker omkring längs Tirisfals gränser. För att hålla trupperna skärpta förlitar sig befälen på brutala metoder och sträng tillsyn för att upprätthålla stridsberedskapen."},{t="Exekutorns räkenskapsbok",b="Executor Zygand anlitar medvetet fristående uppdragstagare i stället för soldater ur garnisonens egna led för att utdela sina straff. Med Executor's Motivator påminner utomstående försumliga Deathguards om att överlevnad i tjänst hos Dark Lady kräver ständig vaksamhet. De som brister i sina plikter lär sig snabbt att odöden inte skyddar mot konsekvenser."}},faq={{q="Vem ger uppdraget Discipline?",a="Executor Zygand ger uppdraget Discipline. Han är en krävande Forsaken-officer stationerad i Tirisfal Glades, där han övervakar försvaret av området och kräver strikt lydnad av sina trupper.",al={"vem ger uppdraget discipline","vem startar discipline","executor zygand uppdrag"}},{q="Varför vill Executor Zygand att Deathguard ska straffas?",a="Zygand anser att Deathguards under hans befäl är inkompetenta och saknar drivkraft. Eftersom självbelåtenhet hotar Forsakens överlevnad i Tirisfal upprätthåller han sträng disciplin för att få vaktposterna på alerten.",al={"varför slå deathguards","varför sporra deathguard","zygand deathguard anledning"}},{q="Varför använder Zygand en äventyrare i stället för en annan soldat?",a="Zygand påpekar att du som utomstående ännu inte tillhör Deathguard och därför inte har haft chansen att göra honom besviken.",al={"varför jag discipline","varför zygand anlitar utomstående"}},{q="Vad är Executor's Motivator?",a="Executor's Motivator är ett bestraffande disciplinverktyg som Executor Zygand tillhandahåller. Det används för att ge sysslolösa Deathguards en smärtsam tillrättavisning på olika platser i Tirisfal Glades.",al={"executors motivator","vad är zygands motivator"}},{q="Vad händer om du vägrar lyda Zygands order?",a="Zygand varnar för att tvekan eller vägran leder till att ditt eget namn skrivs in i hans räkenskapsbok. Då blir du nästa mål för någon annans disciplinering.",al={"zygands hot","zygands hot om räkenskapsboken"}},{q="Hur ser Forsaken på smärta?",a="Zygand räknar smärta bland de få njutningar han fortfarande har tillgång till i döden. Hans entusiasm för bestraffning speglar hans eget hårda temperament.",al={"känner odöda smärta","forsaken och smärta"}}},fx={ae86ed1b={q="Vilka är Deathguards som du straffar?",a="Deathguard är Forsakens stående militärstyrka och vaktstyrka. De har i uppgift att försvara Tirisfal Glades och upprätthålla Dark Ladys styre. Executor Zygand anser att de som är posterade runt Brill och vid utposterna är lata och inkompetenta. Han kräver att de genom fysisk bestraffning påminns om sin edsvurna plikt att skydda Forsakens länder.",al={"vilka är deathguards","deathguards mål disciplin","vem ska jag disciplinera"}}},fp="10,162,26.376.0,21.299.0,31.124.0,54.172.0,61.98.0,33.125.0,42.133.0,30.123.0"}
P.entries["quest:99141"] = {n="Patience",s="Tålamod är ett uppdrag som Executor Zygand delar ut i Tirisfal Glades och som kräver strikt militärt ansvar inför den Mörka Damen. När rutinmässiga fältrapporter dröjer skickar Zygand ut en äventyrare för att hämta uppdateringar från närliggande Deathguards och en ovanlig vaktpost. Uppdraget visar den stränga, kompromisslösa disciplin som upprätthålls i de Fördömdas områden.",h="Tålamod är ett uppdrag som Executor Zygand delar ut i Tirisfal Glades och som kräver strikt militärt ansvar...",kw={"brill","den mörka damen","deathguard","dillinger","gordo","kristof","tålamod","stillwater pond","tirisfal glades","zygand"},ang={["faction:Horde"]="Uppdraget ger besökande allierade från Horde en inblick i den dystra och strängt disciplinerade befälsstruktur som Sylvanas Windrunners officerare upprätthåller i hela Tirisfal.",["race:Undead"]="För nybefriade Fördömda förstärker utförandet av Zygands order Lordaerons hårda överlevnadsvillkor: fullständig hängivenhet åt den Mörka Damen och nolltolerans mot misslyckanden."},sec={{t="Den Mörka Damens vilja verkställs",b="Executor Zygand ansvarar för den lokala säkerheten i Tirisfal Glades och tolererar inga brister i vaksamheten. För Zygand kräver tjänsten åt Lady Sylvanas fullständig effektivitet. När regelbundna fältrapporter inte kommer fram till hans post i tid ser han det som ett oacceptabelt tjänstefel, inte som en mindre försening. I stället för att lämna sin post för att undersöka saken skickar han nyanlända Fördömda agenter för att få ordning på försumliga underställda och säkra att gränserna förblir trygga."},{t="Vakter i Glades",b="Rapporterna kommer från vakter vid viktiga utsiktspunkter runt Brill. Deathguard Dillinger håller vakt vid kyrkogården i väster, där kringströvande odöda och rester av Scourge ofta rör på sig. I öster övervakar Deathguard Kristof en vägstation som bevakar tillfartsvägarna till Capital City och de östra vägarna. Mest ovanlig av dem är Gordo, en väldig styggelse som strövar nära Stillwater Pond. Hans enkla sinne gör förväntningar på militär rapportering högst tveksamma."}},faq={{q="Vem är Executor Zygand?",a="Executor Zygand är en högt uppsatt Fördömd officer med uppgift att upprätthålla ordning och försvar runt Brill i Tirisfal Glades. Han rapporterar direkt till befälskedjan som tjänar Lady Sylvanas och kräver att alla trupper under hans tillsyn utför sina uppgifter felfritt.",al={"zygand","vem är zygand","executor zygands roll"}},{q="Varför skickar Zygand en äventyrare för att hämta rapporter?",a="Flera fältvakter har inte lämnat in sina rapporter enligt schemat. Zygand har inget tålamod med förseningar och vill inte lämna sin centrala post, så han skickar nyprövade Fördömda för att leta upp de försenade rapporterna ute på landsbygden.",al={"varför göra tålamod","varför hämta rapporter"}},{q="Vem är Gordo och varför har han en rapport?",a="Gordo är en styggelse som strövar omkring i väster, nära Stillwater Pond. Zygand förväntade sig en lägesrapport från honom, precis som från vilken annan fältvakt som helst. När Executor får rapporten inser han dock snabbt att det var ett pinsamt misstag att förvänta sig skriftlig information från en styggelse.",al={"gordo","varför har en styggelse en rapport","vem är gordo"}},{q="Var finns Deathguard Dillinger?",a="Deathguard Dillinger är stationerad strax väster om Brill, nära den lokala kyrkogården. Där håller han uppsikt över kvarvarande Scourge-aktivitet och nyuppståndna lik.",al={"dillingers plats","hitta dillinger","var är dillinger"}},{q="Var är Deathguard Kristof stationerad?",a="Deathguard Kristof är stationerad vid vägstationen längs vägen öster om Brill. Han bevakar tillfartsvägarna mot inkräktare och håller uppsikt över trafiken.",al={"kristofs plats","hitta kristof","var är kristof"}},{q="Vad händer när Gordos rapport lämnas in?",a="Executor Zygand medger att det var ett dåraktigt misstag att förvänta sig en sammanhängande skriftlig rapport från en styggelse. Han accepterar utfallet utan vidare och ber dig hålla det pinsamma förbiseendet mellan er.",al={"utfallet av gordos rapport","gordos skrivande"}}},fx={e0ff4089={q="Varför vill Executor Zygand att de här rapporterna samlas in?",a="Executor Zygand har i uppgift att upprätthålla Dark Ladys vilja och hålla noggrann uppsikt över Brills försvar. När väktare och spejare inte lämnar in sina lägesrapporter i tid försämras Forsakens beredskap, och Sylvanas riskerar att bli missnöjd. Zygand kräver snabb lydnad för att upprätthålla järnhård disciplin.",al={"zygands motiv","varför vill zygand ha rapporter","varför uppdraget patience"}},cb8b3e87={q="Vad är Deathguard Dillingers rapport till för?",a="Dillingers rapport beskriver säkerhetsläget kring Brills kyrkogård, strax väster om staden. Deathguard Dillinger är posterad nära gravplatsen för att hålla utkik efter hot och oroligheter. Hon förväntas hålla Executor Zygand underrättad om oron i trakten och hur stabilt området är bevakat.",al={"dillingers rapport","vad är dillingers rapport","syftet med dillingers rapport"}},["744f946d"]={q="Vad är Deathguard Kristofs rapport till för?",a="Kristofs rapport beskriver patrullverksamheten och väglaget kring den östra vägstationen. Deathguard Kristof bevakar passagen österut genom Tirisfal Glades, och hans rapport ger Executor Zygand viktig information om trafiken och annalkande faror.",al={"kristofs rapport","vad är kristofs rapport","syftet med kristofs rapport"}},["79b1ee7a"]={q="Vad är Gordos rapport till för?",a="Gordos rapport ska redogöra för området kring Stillwater Pond i väster, där styggelsen lunkar omkring på patrull. Executor Zygand väntar sig skriftliga spaningsrapporter, men det trögfattade odjuret har svårt att förstå vad militära rapporter är.",al={"gordos rapport","vad är gordos rapport","syftet med gordos rapport"}}},fp="8,159,30.345.0,23.418.0,23.183.0,54.181.0,43.199.1,38.122.0,38.107.0,46.185.1"}
P.entries["quest:99142"] = {n="Tomb Weed",s="Tomb Weed är ett alkemiskt uppdrag som Junior Apothecary Holland ger i Tirisfal Glades. Holland har modifierat vild doom weed och planterat den på nytt vid det hemsökta Balnir Farmstead, där han odlar fram ett kraftfullt nytt exemplar som oväntat lockar till sig den lokala Scourge.",h="Tomb Weed är ett alkemiskt uppdrag som Junior Apothecary Holland ger i Tirisfal Glades.",kw={"balnir farmstead","doom weed","gordo","junior apothecary holland","royal apothecary society","tirisfal glades","tomb weed"},ang={["profession:Herbalism"]="Tomb weed visar hur konstgjord alkemisk påverkan i grunden kan förändra egenskaperna och beteendet hos fördärvade örter som doom weed.",["race:Undead"]="Junior Apothecary Hollands forskning visar hur Forsakens apotekare envist försöker omforma Tirisfals fördärvade flora till särskilda alkemiingredienser."},sec={{t="Hollands odling",b="Junior Apothecary Holland nöjer sig inte med att bara skörda inhemska örter åt Royal Apothecary Society; han har egna storslagna ambitioner. Genom att samla in doom weed och utsätta den för mindre alkemiändringar planterade han om plantorna i jorden vid Balnir Farmstead för att odla fram ett utvecklat exemplar som han döpte till tomb weed. Holland ser denna hybridflora som höjdpunkten i sitt arbete och ett förebud om sitt personliga öde."},{t="Oväntad dragningskraft",b="Holland väntade sig alkemisk styrka, men att plantera tomb weed vid Balnir Farmstead fick en oförutsedd bieffekt. De kringströvande resterna av Scourge som hemsöker de fördärvade fälten har visat en märklig och utbredd dragning till den växande floran. Holland förlitar sig på förbipasserande resenärer som kan tränga igenom de framryckande odöda och skörda den mogna grödan, så att han kan fortsätta sina experiment."}},faq={{q="Vad är tomb weed?",a="Tomb weed är en alkemiskt modifierad variant av doom weed som Junior Apothecary Holland odlar. Han tar inhemsk doom weed, förändrar den med kemiska reagenser och planterar den i den fördärvade jorden vid Balnir Farmstead.",al={"vad är tomb weed","tomb weed i berättelsen","tomb weed växt"}},{q="Vem är Junior Apothecary Holland?",a="Holland tillhör Royal Apothecary Society och är verksam i Tirisfal Glades. Han är ambitiös och blir ofta frustrerad på assistenter som styggelsen Gordo. Holland utför privata trädgårdsodlings- och alkemiexperiment för att höja sin egen ställning.",al={"vem är holland","junior apothecary holland","apotekaren holland"}},{q="Var odlas tomb weed?",a="Holland planterar sina modifierade grödor vid Balnir Farmstead, en övergiven gård i östra Tirisfal Glades som har förfallit och drabbats av fördärv.",al={"var hittar man tomb weed","tomb weed plats","ogräs vid balnir farmstead"}},{q="Varför dras Scourge till tomb weed?",a="Holland har lagt märke till att de tanklösa Scourge som hemsöker Balnir Farmstead verkar dras instinktivt till den modifierade växten, men han vet inte varför; han tycker bara att det är märkligt.",al={"varför vill scourge ha tomb weed","scourge dras till tomb weed","scourges reaktion"}},{q="Hur skiljer sig tomb weed från vanlig doom weed?",a="Doom weed är en vild växt som växer nära massgraven norr om Brills gravgård. Tomb weed skapas när doom weed genomgår konstgjorda alkemiändringar och planteras om utvalda gånger i jorden vid gården under Hollands ledning.",al={"doom weed jämfört med tomb weed","skillnaden mellan doom weed och tomb weed"}},{q="Vem är Gordo som Holland nämner?",a="Gordo är en kringströvande styggelse skapad av Forsaken. Han vandrar längs vägarna i Tirisfal Glades och får ofta enkla uppgifter av Holland, men hans tröga sinne gör dem svåra.",al={"vem är gordo","möte med gordo","gordo i tirisfal"}}},fp="9,152,21.321.0,21.259.0,18.143.0,33.248.0,25.136.0,43.140.0,48.175.0,34.182.0"}
P.entries["quest:99143"] = {n="Bottles and Baubles",s="Bottles and Baubles är ett uppdrag byggt på den märkliga logiken att eftersom murlocer ser ut som fiskar måste de tänka som fiskar. Äventyrare skickas till ett närliggande murlocläger för att rota bland glittrande skrot och bortkastade prydnadssaker som en ivrig fiskare kan göra fiskebete av.",h="Bottles and Baubles är ett uppdrag byggt på den märkliga logiken att eftersom murlocer ser ut som fiskar...",kw={"bete","bottles and baubles","fiske","drag","murloc","murlocläger","glänsande skrot"},sec={{t="Fisklogik och strandfynd",b="Bottles and Baubles börjar med en ganska ovanlig teori om vattenlevande biologi: eftersom murlocer är fiskliknande varelser måste deras sinnen fungera precis som hos fiskarna som simmar i djupet. Med den logiken som grund hävdar en excentrisk fiskare att allt märkligt som fångar en murlocs vandrande blick säkert också lockar en hungrig fisk på kroken. Asätare får i uppgift att bege sig till ett närliggande murlocläger, rota igenom deras högar och samla glänsande bortkastat skrot för att pröva teorin."},{t="Glittrande prydnader som bete",b="Murlocer längs kustvatten och flodstränder är ökända asätare som samlar på ljusa stenar, snäckor, bitar av polerat glas och metallskrot i röriga högar kring sina hyddor. När man letar igenom dessa leriga samlingar hittar man alla möjliga glittrande rester som en påpasslig fiskare kan göra enkla drag och blänken av. När de väl har hämtats och lämnats över visar sig den udda blandningen vara tillräcklig för att äventyraren ska få ett grundläggande fiskeset."}},faq={{q="Varför behöver du samla skrot från murlocer?",a="Uppdragsgivaren tror att eftersom murlocer liknar fiskar måste deras sinnen också fungera som fiskars. Enligt teorin att allt som lockar en murloc även lockar fiskar under vattenytan skickas äventyrare för att leta efter prydnadssaker och glänsande rester i deras läger och göra fiskebete av dem.",al={"varför samla skrot","vad används bottles and baubles till","glänsande murlocskrot"}},{q="Var finns det glänsande skrotet?",a="Det glänsande skrotet finns utspritt kring det närliggande murloclägret. Murlocer är ökända asätare som samlar glittrande skräp, bortkastade prydnadssaker och glas längs stränder och vattendrag. Föremålen kan hämtas direkt från deras område.",al={"var finns skrot","murloclägrets plats","hur får man tag på glänsande skrot"}},{q="Vem ger uppgiften och vad vill personen ha?",a="Uppgiften kommer från en lokal fiskare som vill fylla på sitt förråd av drag och bete. Teorierna om murlocers psykologi är ganska excentriska, men fiskaren belönar hjälpsamma asätare med extra fiskeutrustning för att uppmuntra nybörjare.",al={"vem ger bottles and baubles","vem är uppdragsgivaren","lämna in uppdraget"}},{q="Tänker murlocer verkligen som fiskar?",a="Trots uppdragsgivarens resonemang är murlocer amfibiska, stamlevande humanoider, inte enkla och tanklösa fiskar. Men liksom många andra varelser och rovdjur dras de naturligt till glänsande föremål, polerade snäckor och färgglada prydnadssaker. Därför bildar de högar av saker som råkar innehålla glittrande material.",al={"tänker murlocer som fiskar","murlocers intelligens","är murlocer verkligen fiskar"}},{q="Hur ska murlocernas skrot användas som bete?",a="Det insamlade skrotet består av reflekterande glas, metallbitar och polerade småsaker. Fiskaren tänker göra drag och provisoriskt bete av de reflekterande bitarna i hopp om att glansen ska efterlikna småfiskar eller väcka nyfikna fiskars intresse när de äter.",al={"vad används glänsande skrot till","är glänsande skrot bete","fungerar murlocskrot som bete"}},{q="Vad erbjuder uppdragsgivaren som belöning?",a="När tillräckligt många användbara, glänsande skrotbitar har lämnats tillbaka överlämnar uppdragsgivaren äldre fiskeutrustning från sitt eget förråd. De här enkla redskapen och förnödenheterna ska hjälpa blivande fiskare att komma igång och pröva fiskelyckan.",al={"vilken belöning ger bottles and baubles","vad får man","belöning i fiskeutrustning"}}},fp="19,100,35.301.0,24.322.0,45.223.0,30.139.0,42.147.0,36.222.0,41.192.0,43.189.0"}
P.entries["quest:99144"] = {n="Seeking Refuge",s="Seeking Refuge är ett uppdrag i Tirisfal Glades där Bareth Dawnstone, ett sändebud från Bandarion Keep som hålls fången vid Crusader's Outpost, ska räddas. Hans kamp visar hur en ovanlig orden växer fram, hängiven det Heliga ljuset trots lokala fanatikers starka fördomar. När nyheten om hans flykt når Brill tryggas viktiga band för denna nya fristad.",h="Seeking Refuge är ett uppdrag i Tirisfal Glades där Bareth Dawnstone, ett sändebud från Bandarion Keep som...",kw={"bandarion keep","bareth dawnstone","brill","crusader's outpost","korsfarare","heliga ljuset","seeking refuge","shari stilwell","solliden farmstead","tirisfal glades"},ang={["class:Paladin"]="Paladiner kan lägga märke till skillnaden mellan fanatikerna vid Crusader's Outpost, som använder Ljuset drivna av hat, och Bareth Dawnstones strävan efter välvilja och skydd.",["class:Priest"]="Präster kan finna Bandarion Keeps filosofi fascinerande. Medlemmarna ägnar sig åt ren meditation och vägledning i det Heliga ljuset trots fördomarna mot odöda som utövar det.",["faction:Horde"]="Genom att trygga kurirtrafiken mellan Bandarion Keep och Brill får nya neutrala eller allierade ordnar fäste i Tirisfal Glades trots de fientliga korsfararna.",["race:Undead"]="De Fördömda som fortfarande vördar det Heliga ljuset möter fientlighet från både levande fanatiker och misstänksamma fränder. Det växande brödraskapet i Bandarion Keep är därför en sällsynt fristad."},sec={{t="En farofylld färd",b="Seeking Refuge skildrar Bareth Dawnstones farofyllda färd. Han skickades från det avlägsna klostret Bandarion Keep. På väg till Brill för att träffa Shari Stilwell blev Bareth överfallen och tillfångatagen av fanatiska krigare vid Crusader's Outpost. Trots hatet mot att han är odöd förblir Bareth ståndaktig i sin tro på Ljuset. Han längtar bara efter att fly sina plågoandar och se till att hans budskap når fram."},{t="Hämnd eller hängivenhet",b="B areths fångenskap belyser den bittra ideologiska klyfta som präglar Tirisfal Glades. Fanatikerna vid Crusader's Outpost kanaliserar det Heliga ljuset genom hämndlystnad och dogmatisk rättfärdighet, och ser Bareths existens som en skymf. Dawnstone ser däremot Ljuset som en källa till skydd och inre renhet. Han beklagar hur fångvaktarnas grymhet förvränger de heliga läror han håller kära."},{t="En fristad på höjderna",b="Efter flykten bekräftas Bareths säkerhet hos Shari Stilwell i Brill. Stilwell berättar att deras klosterorden fortfarande håller på att slå rot på höjderna nordväst om Solliden Farmstead. Att förlora en så lovande utövare som Dawnstone hade varit ett hårt slag för deras unga gemenskap, som välkomnar alla resande som söker uppriktig andlig vägledning."}},faq={{q="Vem är Bareth Dawnstone?",a="Bareth Dawnstone är hängiven det Heliga ljuset och har sin bas i Bandarion Keep. På väg till Brill för att överlämna ett budskap överfölls han och fängslades av fanatiska korsfarare som avskyr hans folk. Trots att han är odöd mediterar han över Ljuset och strävar efter att använda det till skydd.",al={"vem är bareth dawnstone","bareth dawnstones historia","dawnstone"}},{q="Vem tillfångatog Bareth Dawnstone och varför?",a="Fanatiker vid Crusader's Outpost överföll Bareth Dawnstone på vägen från Bandarion Keep. Han beklagar att hans fångvaktare använder det Heliga ljuset med glödande hat i sina hjärtan. De förvränger den välvilja han mediterar över och förföljer dem de anser vara vidunder.",al={"vem tillfångatog bareth dawnstone","fångvaktarna vid crusader's outpost","varför tillfångatogs han"}},{q="Vem är Shari Stilwell?",a="Shari Stilwell representerar klosterorden och är stationerad i de Fördömdas stad Brill. Hon tar emot resande och samordnar arbetet med sändebud från Bandarion Keep. Hon välkomnar alla som söker vägledning i Ljuset.",al={"vem är shari stilwell","stilwell brill","shari brill"}},{q="Vad är Bandarion Keep?",a="Bandarion Keep är ett avlägset kloster på höjderna nordväst om Solliden Farmstead i Tirisfal Glades. Det är en fristad och en träningsplats för en växande religiös orden som ägnar sig åt ren meditation och studier av det Heliga ljuset.",al={"vad är bandarion keep","var ligger bandarion keep","klostret nordväst om solliden"}},{q="Varför har Bareths fångvaktare något emot hans folk?",a="Bareth Dawnstone talar om ”det som återstår av mitt blod” och erkänner att hans folk möter fördomar. Det visar att han är en odöd utövare av det Heliga ljuset. Tirisfals fanatiska korsfarare avskyr alla odöda och vägrar tro att deras avsikter eller tro någonsin kan vara rena.",al={"varför hatar de hans folk","odöda som använder ljuset","bareth det som återstår av mitt blod"}},{q="Vad är det för orden som har sin bas i Bandarion Keep?",a="Orden i Bandarion Keep är ett ungt klosterbrödraskap som håller på att slå rot på Tisifals höjder. Till skillnad från de hatiska korsfararna i närheten predikar de fridfull meditation och skydd. De öppnar sina dörrar för alla som söker sann vägledning i Ljuset.",al={"vad är orden i bandarion keep","munkarna i bandarion keep","bandarion keep och tron"}}},fp="14,228,18.299.0,25.284.0,23.310.0,24.233.0,39.241.0,22.205.0,23.223.0,49.259.0,46.202.0"}
P.entries["quest:99152"] = {n="As Above, So Below",s="As Above, So Below är ett uppdrag från Hilda the Breaker vid Bandarion Keep, där du ska möta en dold Scourge-infiltration under närliggande Shadowvale. Genom att samla ben som fortfarande sjuder av färsk återupplivningsmagi hoppas försvararna förstå hur de odöda samlades obemärkt mitt under staden.",h="As Above, So Below är ett uppdrag från Hilda the Breaker vid Bandarion Keep, där du ska möta en dold...",kw={"as above so below","bandarion keep","lysande ben","hilda the breaker","återupplivningsmagi","scourge","shadowvale","tarnished"},ang={["class:Mage"]="Magiker lägger märke till den kvarvarande återupplivningsmagin som klänger vid de lysande benen. Den antyder att särskilda nekromantiska tekniker döljer sig under staden.",["class:Paladin"]="Paladiner ser varje oupptäckt Scourge-närvaro som en omedelbar fara. Därför är undersökningen av återupplivningsmagin under Shadowvale en angelägen plikt.",["class:Priest"]="Präster som tränats i att bekämpa det onda oroar sig förstås över mörka återupplivningskonster som frodas direkt under en bebodd stad."},sec={{t="Det dolda hotet",b="Vid Bandarion Keep leder Hilda the Breaker försvararnas hårda förberedelser inför farorna runt omkring. Blickarna på ytan är riktade mot det oroliga Shadowvale i sydväst, där en fientlig fraktion vid namn Tarnished regelbundet ställer till oreda. Men en långt mörkare fara har fått fäste utom synhåll. I de mörka källarvalven under staden samlar en oupptäckt Scourge-styrka kraft och hotar att plötsligt anfalla fästet om den tillåts växa sig starkare."},{t="Magi i källarvalven",b="Hilda vill inte låta gröna rekryter marschera blint in i underjordiska gravkamrar, så hon skickar erfarna äventyrare på en direktkurs ner i källarvalven under Shadowvale. Huvudmålet är inte bara att utrota fienden, utan att samla information: återvinna skelettdelar som fortfarande sprakar av kvarvarande återupplivningsmagi. Genom att undersöka dessa svagt lysande ben får försvararna en viktig chans att förstå hur den mörka nekromantin kunde verka obemärkt precis under deras fötter."}},faq={{q="Vad är As Above, So Below?",a="As Above, So Below är ett uppdrag från Hilda the Breaker att undersöka en dold Scourge-närvaro som frodas under Shadowvale. Medan rekryter övas vid Bandarion Keep skickas en äventyrare ner under staden för att samla in återupplivade benprover.",al={"vad är as above so below","uppdraget as above so below"}},{q="Vem ger uppdraget As Above, So Below?",a="Hilda the Breaker är en sträng instruktör som tränar rekryter vid Bandarion Keep. Hon är hård och kompromisslös och kräver resultat av alla under sitt befäl. Hon föredrar att en rekryt återvänder på en bår framför att komma tillbaka tomhänt.",al={"vem ger as above so below","vem är hilda the breaker","uppdragsgivaren hilda"}},{q="Var ligger Shadowvale?",a="Shadowvale är en stad sydväst om Bandarion Keep. Problemen på ytan orsakas av en grupp som kallas Tarnished, men stadens källarvalv döljer en långt mer lömsk odödlig pest.",al={"var ligger shadowvale","shadowvales läge"}},{q="Vilket hot lurar under Shadowvale?",a="Källarvalven under Shadowvale har hemsökts av återupplivade odöda. Om den dolda Scourge-närvaron lämnas ifred hotar den att utlösa ett fullskaligt uppror mot närliggande Bandarion Keep.",al={"vad finns i källarvalven under shadowvale","scourge i shadowvales källarvalv","hotet under shadowvale"}},{q="Varför behöver Hilda svagt lysande ben?",a="Hilda behöver ben som fortfarande bär spår av den magiska aura som återupplivade dem. Genom att studera dessa svagt lysande kvarlevor hoppas försvararna förstå hur nekromantikerna organiserade upproret utan att upptäckas.",al={"varför samla lysande ben","syftet med svagt lysande ben","återupplivningsmagi i ben"}},{q="Vilka är Tarnished i Shadowvale?",a="Tarnished är en fientlig fraktion som är aktiv på ytan i Shadowvale. De utgör ett konkret hot mot området, men Hilda anser att det dolda Scourge-nästet under staden är ännu farligare.",al={"vilka är tarnished","tarnished i shadowvale"}}},fp="18,203,17.307.0,20.376.1,27.213.0,39.229.0,28.136.0,37.139.0,42.155.0,36.137.0"}
P.entries["quest:99153"] = {n="The One That Got Away",s="The One That Got Away är ett uppdrag som Ephram Barbaro ger dig. Du ska spåra upp en avhoppad kultist som flydde efter en skärmytsling nära resterna av Naxxramas. Flyktingen tog med sig en aktiv bit av en fokuseringskristall och flydde under Shadowvale. Den hotar att stärka eller återuppliva de döda.",h="The One That Got Away är ett uppdrag som Ephram Barbaro ger dig.",kw={"kristallfragment","kultist","ephram barbaro","fokuseringskristall","naxxramas","shadowvale","the one that got away"},ang={["class:Paladin"]="Paladiner som svurit att utplåna nekromantiska hot känner igen faran med en aktiv Scourge-fokuseringskristall, särskilt en som kan väcka odöda till liv eller stärka dem under jord.",["class:Priest"]="Präster som är vana vid att bekämpa mörk magi vet hur oheliga reliker kan korrumpera omgivningen om de inte återtas och renas snabbt."},sec={{t="En flykting i skuggorna",b="Efter en strid mot kultister vid resterna av slaget mot Naxxramas sprids nyheten snabbt bland leden. Ephram Barbaro söker upp dugliga äventyrare när han får veta att en ensam kultist tog sig igenom avspärrningen och stal en aktiv bit av en Scourge-fokuseringskristall."},{t="Hotet under Shadowvale",b="Underrättelser pekar ut gångarna under jord i Shadowvale, dit den flyende kultisten tog sig. Fragmentet bär fortfarande på mörk nekromantisk energi. Det misstänks kunna återuppliva de döda eller stärka fientliga styrkor som lurar under jord. Barbaro ger äventyrarna i uppdrag att spåra upp och säkra den gömda kristallen innan dess kraft orsakar en större katastrof."}},faq={{q="Vem ger uppdraget The One That Got Away?",a="Uppdraget ges av Ephram Barbaro, som söker upp dig efter att ha hört om dina tidigare insatser mot kultister nära resterna av slaget mot Naxxramas.",al={"vem ger the one that got away","vem startar det här uppdraget","uppdragsgivare för the one that got away"}},{q="Vad är fokuseringskristallens fragment?",a="Det är en kvarvarande skärva från en Scourge-fokuseringskristall som en flyende kultist tog med sig. Ephram Barbaro säger att den fortfarande bär på kraft och antingen väcker odöda till liv eller gör de odöda under Shadowvale starkare.",al={"vad är kristallfragmentet","vad gör kristallen","varför är kristallen farlig"}},{q="Var finns kristallfragmentet?",a="Enligt Ephram Barbaros underrättelser flydde kultisten under Shadowvale med reliken och gömde den någonstans under jord, där dess kraft fortfarande sipprar ut.",al={"var är kristallen gömd","kristallens plats i shadowvale","var hittar man kristallfragmentet"}},{q="Vem är ”den som kom undan”?",a="Titeln syftar på en kultist som lyckades smita undan efter konfrontationen vid resterna av slaget mot Naxxramas och tog med sig en aktiv skärva av en fokuseringskristall.",al={"vem flydde med kristallen","kultist med kristall","betydelsen av the one that got away"}},{q="Vad händer när du återlämnar kristallen till Ephram Barbaro?",a="När du återlämnar det återfunna kristallfragmentet berömmer Ephram Barbaro din snabbhet och säger att det är dags att gå vidare till hans favoritdel av hanteringen av situationen.",al={"vad händer när man återlämnar kristallen","lämna in the one that got away","ephram barbaros favoritdel"}},{q="Hur känner Ephram Barbaro till dig?",a="Ephram säger att ryktet sprids snabbt bland leden. Han nämner särskilt ditt tidigare arbete mot kultister som höll till vid resterna av slaget mot Naxxramas.",al={"kultister vid resterna av slaget mot naxxramas","hur känner ephram till dig","förutsättningar för the one that got away"}}},fp="21,192,25.263.0,29.262.0,42.123.0,38.192.0,38.108.0,31.132.0,59.133.0,39.144.0"}
P.entries["quest:99156"] = {n="Rear Guard Patrol",s="Rear Guard Patrol är ett avgörande försvarsuppdrag som Deathguard Linnea ger i Tirisfal Glades. I stället för att jaga enstaka kringströvande gastar ska patrullerna spåra upp Riptear, en styggelse som stryker omkring nära Venomweb Vale och aldrig borde ha tagit sig förbi The Bulwark.",h="Rear Guard Patrol är ett avgörande försvarsuppdrag som Deathguard Linnea ger i Tirisfal Glades.",kw={"styggelse","the bulwark","deathguard linnea","rear guard patrol","riptear","tirisfal glades","venomweb vale"},ang={["faction:Horde"]="När den östra gränsen i Tirisfal säkras förblir försörjningslederna till The Bulwark och Undercity fria från kringströvande fasor.",["race:Undead"]="De Fördömda har inte råd att föra krig på två fronter. Varje Scourge-konstruktion som stryker omkring bakom deras försvarsbarrikader utgör ett existentiellt hot mot deras rike."},sec={{t="Genombrott vid gränsen",b="The Bulwark är den enda befästa barriären mellan Tirisfal Glades och fasorna i Western Plaguelands. De Fördömdas militära strategi bygger på ett krig vid en enda front. Om tanklösa odöda tar sig bakom linjerna kan försörjningslederna till fronten strypas på ett ögonblick. Enstaka andar eller gastar tar sig ibland förbi barrikaderna, men rapporter om en styggelse som stryker omkring i gläntorna tyder på ett allvarligt misslyckande med att hålla fienden instängd."},{t="Hotet från Riptear",b="Den förrymda monstrositeten Riptear sågs hasa fram nära Venomweb Vale, bakom The Bulwarks främre skansar. Styggelser är enorma slaktmaskiner, hopsydda av lik och mörk nekromanti. De tar sig inte obemärkta genom befästa pass, så Deathguard Linnea är djupt oroad över hur varelsen korsade försvarslinjen. Linnea kräver Riptear's Heart som ett obestridligt bevis på att den har förstörts."}},faq={{q="Vem erbjuder uppdraget Rear Guard Patrol?",a="Patrullordern utfärdas av Deathguard Linnea, en dödsvakt bland de Fördömda i Tirisfal Glades som rapporterar till Executor Zygand.",al={"vem ger rear guard patrol","uppdragsgivare för rear guard patrol","vem ger det här uppdraget"}},{q="Vad är Riptear?",a="Riptear är en förrymd styggelse som upptäckts stryka omkring i östra Tirisfal Glades nära Venomweb Vale, bakom de främre försvarslinjerna.",al={"vem är riptear","vad är riptear","riptears bakgrund"}},{q="Varför är en styggelse nära Venomweb Vale så alarmerande?",a="Styggelser är enorma konstruktioner som kräver mörk nekromanti och tungt arbete att tillverka. Det borde vara omöjligt att obemärkt ta sig genom det kraftigt befästa The Bulwark, vilket tyder på ett alarmerande genombrott eller en oupptäckt väg bakom de Fördömdas linjer.",al={"varför är riptear så viktig","varför är en styggelse farlig här","genombrott vid the bulwark"}},{q="Var brukar besten finnas?",a="Enligt vittnesmål stryker Riptear omkring i skogarna och gläntorna i östra Tirisfal Glades, i närheten av Venomweb Vale.",al={"var finns riptear","riptears plats","var hittar jag styggelsen"}},{q="Vilket bevis krävs för att slutföra patrullen?",a="Deathguard Linnea kräver Riptear's Heart för att bekräfta att den enorma monstrositeten har oskadliggjorts för gott.",al={"vad ska jag ta med till linnea","föremål att lämna in för uppdraget","bevis på riptears död"}},{q="Vem ansvarar för försvaret av The Bulwark?",a="Uppdraget nämner inte vem som leder The Bulwark. Deathguard Linnea lyder under sin överordnade, Executor Zygand i Brill, som tar emot hennes rapporter om patruller som håller Scourge stången.",al={"vem ansvarar för the bulwark","linneas överordnade","executor zygand"}}},fp="17,195,24.374.0,21.336.1,39.116.0,16.113.0,53.190.0,33.98.0,44.109.0,40.165.0"}
P.entries["quest:99158"] = {n="Dawn in the Mountains",s="Dawn in the Mountains är ett uppdrag där du ska leverera en sändning heliga ljus till Father Gavin vid Misty Pine Refuge. Den milde prästen från Argent Dawn håller bergsfristaden öppen för att läka och trösta trötta resenärer, inte för att strida med vapen.",h="Dawn in the Mountains är ett uppdrag där du ska leverera en sändning heliga ljus till Father Gavin vid Misty...",kw={"argent dawn","dawn in the mountains","father gavin","heliga ljus","misty pine refuge","präst","fristad"},ang={["class:Priest"]="Father Gavin förkroppsligar prästämbetets mildare, läkande väg. Han väljer att hjälpa resenärer och vårda sår i stället för att svinga vapen vid Argent Dawns frontlinjer.",["faction:Alliance"]="Genom att förse en tillflyktsort för Argent Dawn, som Misty Pine Refuge, med förnödenheter stöder du neutralt humanitärt arbete i omstridd och farlig bergsterräng.",["faction:Horde"]="Argent Dawn tar emot hjälp och erbjuder fristad oavsett lojalitet, vilket gör utposter som Father Gavins till sällsynta trygga tillflykter i vildmarken."},sec={{t="En fristad bland topparna",b="Medan många inom Argent Dawn griper till vapen för att rensa Azeroth från oheliga fasor väljer andra Ljusets mildare kallelse. Father Gavin, en präst som bor i den karga bergsvildmarken, har lagt svärdet åt sidan för att helt ägna sig åt att läka sjuka och ta hand om trötta resenärer. Han tog över en övergiven byggnad och rustade upp den till Misty Pine Refuge, ett tryggt stopp för resenärer som möter farorna i de höga bergspassen."},{t="Ljus åt Ljusets tjänare",b="En avlägsen bergsfristad kräver ständig omsorg och hängivet praktiskt arbete. För att kunna fortsätta sitt andliga uppdrag och hålla lampor och altaren tända är Father Gavin beroende av hjälp från avlägsna allierade. En leverans invigda ljus ser till att fristaden förblir en fyr av ljus, värme och hopp i den obarmhärtiga vildmarken."}},faq={{q="Vem är Father Gavin?",a="Father Gavin är en präst knuten till Argent Dawn som håller till uppe i bergen. Till skillnad från många i sin heliga orden, som griper till vapen mot det oheliga, ägnar sig Gavin främst åt att läka, trösta resenärer och ge dem tak över huvudet vid Misty Pine Refuge.",al={"vem är father gavin","father gavins bakgrund","vem är prästen vid misty pine"}},{q="Vad är Misty Pine Refuge?",a="Misty Pine Refuge är ett rastställe för bergsresenärer som grundades av Father Gavin. Han rustade upp en gammal byggnad i vildmarken till en fridfull fristad där vandrare kan återhämta sig, vila och få vård.",al={"vad är misty pine refuge","var ligger misty pine refuge","misty pine refuge bakgrund"}},{q="Vad är Argent Dawn?",a="Argent Dawn är en hängiven helig orden som söker upp och förgör oheliga och onaturliga hot i hela Azeroth, samtidigt som den erbjuder hjälp och tröst åt dem som kämpar för att överleva i oroliga länder.",al={"vad är argent dawn","argent dawns syfte","vilka är argent dawn"}},{q="Varför behöver Father Gavin en sändning heliga ljus?",a="Lådan med heliga ljus ska fylla på Father Gavins förråd vid Misty Pine Refuge. I heliga tjänster och avlägsna fristäder behövs invigda ljus för religiösa riter och böner, och för att lysa upp fristaden åt trötta resenärer.",al={"varför ljus","syftet med heliga ljus","leverans av crate of candles"}},{q="Griper Father Gavin till vapen som andra medlemmar av Argent Dawn?",a="Father Gavin föredrar att läka och ge resenärer skydd framför att gripa till vapen. Argent Dawn är känt för sina väpnade korståg mot mörkret, men Gavin tjänar orden genom medkänsla, gästfrihet och andlig omsorg.",al={"strider father gavin","är father gavin en kämpe"}},{q="Vad går uppdraget Dawn in the Mountains ut på?",a="Uppdraget ber en resenär på väg in i bergen att ta med en låda heliga ljus direkt till Father Gavin vid Misty Pine Refuge för att stödja hans enkla bergsfristad.",al={"vem gav uppdraget","vart leder dawn in the mountains"}}},fp="21,151,24.340.0,21.297.0,20.196.0,26.174.0,24.164.0,54.149.0,62.183.0,55.133.0"}
P.entries["quest:99159"] = {n="Finding Warmth",s="Finding Warmth är ett enkelt ärende som går ut på att hålla en välkomnande härd brinnande med ved. Värden är upptagen med annat och ber resenärer samla vedträn, så att alla som söker värme kan finna ro. När uppgiften är slutförd fortsätter elden att brinna och fler sysslor väntar.",h="Finding Warmth är ett enkelt ärende som går ut på att hålla en välkomnande härd brinnande med ved.",kw={"finding warmth","ved","härd","ljus","värme","trä"},sec={{t="En välkomnande härd",b="Finding Warmth är en enkel syssla som håller en välkomnande eld vid liv. Uppdragsgivaren håller härden öppen för att värma vilsna själar, men har fått så mycket annat att göra att hen inte kan hämta ved själv. Genom att samla ved ser resenärer till att härden förblir tänd för alla som söker skydd och ro."},{t="Hålla elden vid liv",b="All ved som hämtas i trakten är inte redo att brinna genast. När veden lämnas över läggs alltför fuktiga eller blöta vedträn åt sidan för att torka ordentligt, medan torr ved genast läggs på elden. Värden är glad över hjälpen i rättan tid och tar sig snabbt an andra angelägna ärenden."}},faq={{q="Vad handlar uppdraget Finding Warmth om?",a="Finding Warmth är ett lokalt uppdrag där en äventyrare ombeds samla ved för att hålla en välkomnande härd brinnande. Uppdragsgivaren brukar själv sköta elden, men har fått fullt upp med andra angelägna sysslor och ber om hjälp.",al={"uppdraget finding warmth","vad är finding warmth","ved till finding warmth"}},{q="Varför behövs veden?",a="Veden behövs för att hålla en härd brinnande, så att förbipasserande resenärer och ortsbor kan få värme och ro. Vedhuggning är en vanlig syssla som blivit eftersatt eftersom värden fått annat att göra.",al={"varför behövs ved","ved i finding warmth","ved till härden"}},{q="Vad händer med blöt ved som lämnas in?",a="En del av veden kan vara för fuktig eller blöt för att brinna direkt när den lämnas in. Uppdragsgivaren lägger de blöta vedträna åt sidan så att de får torka, och använder genast den torra veden för att mata elden.",al={"blöt ved i finding warmth","fuktig ved"}},{q="Vad är det för person som erbjuder uppgiften?",a="Även om värdens identitet inte beskrivs närmare, tyder välsignelsen ”Må Ljuset vägleda dig i dina sysslor” på att personen har en stark tro på eller vördnad för det Heliga Ljuset och håller härden öppen för alla som behöver värme.",al={"vem ger finding warmth","finding warmth ljuset vägleda dig"}},{q="Finns det fler uppgifter efter Finding Warmth?",a="Ja. När veden har lämnats över nämner värden att det finns fler sysslor som kräver ett par flinka händer, om resenären vill hjälpa till mer.",al={"fler uppdrag efter finding warmth","fortsättning på finding warmth"}},{q="Vem är välkommen vid härden?",a="Värden håller härden brinnande för att erbjuda skydd, ro och värme åt alla som passerar och behöver en paus från kylan eller en tröttsam resa.",al={"öppen härd för alla","öppen härd finding warmth"}}},fp="14,136,18.178.0,16.192.0,39.118.0,27.127.0,40.73.0,37.172.0,53.90.0,30.86.0"}
P.entries["quest:99160"] = {n="Rime's Wrath",s="Rime's Wrath är ett uppdrag där du ska hejda ett farligt utbrott av mindre iselementaler. Eftersom ingen kände till något fredligt sätt att lugna de aggressiva frostandarna blev det nödvändigt att förgöra dem för att hålla området säkert.",h="Rime's Wrath är ett uppdrag där du ska hejda ett farligt utbrott av mindre iselementaler.",kw={"elementaler","frost","iselementaler","mindre iselementaler","blidka","rime's wrath","rimes vrede"},ang={["class:Mage"]="Frostmagiker studerar hur ismagins råa kraft frammanas och formas. Vilda mindre iselementaler är därför ett fascinerande men svårstyrt uttryck för elementarkrafter.",["class:Shaman"]="Schamaner försöker förstå och kommunicera med elementandar. Dessa fientliga isväsen gick dock inte att blidka fredligt och måste hejdas med våld."},sec={{t="En bitter manifestation",b="I Rime's Wrath ska du hantera en lokal ökning av mindre iselementaler. Dessa andar av bitande frost och kyla utgör en aktiv fara i området. Därför krävs ett snabbt ingripande innan kylan sprider sig eller skadar förbipasserande. Svaret är inte en samordnad attack, utan en inneslutningsåtgärd mot vilda, fientliga elementmanifestationer."},{t="Utan möjlighet att blidka",b="Det bästa hade varit att lugna de upprörda frostandarna, men kunskapen som krävdes för att blidka dem fanns inte tillgänglig. Eftersom det saknades ett praktiskt sätt att lugna dem och andarna blev allt farligare återstod bara att förgöra dem för att skydda omgivningen."}},faq={{q="Vad är Rime's Wrath?",a="Rime's Wrath är ett uppdrag där du ska förgöra mindre iselementaler som utgör ett omedelbart hot. Eftersom fredliga sätt att lugna de upprörda andarna var okända eller otillgängliga blev våld det enda alternativet för att hålla området säkert.",al={"vad är rime's wrath","uppdraget rime's wrath","översikt över rime's wrath"}},{q="Varför måste de mindre iselementalerna förgöras?",a="De mindre iselementalerna blev för oberäkneliga och farliga för att lämnas åt sitt öde. Det hade varit bättre att lugna dem fredligt, men kunskapen som krävdes saknades. Därför återstod bara att förgöra dem.",al={"varför döda ise elemental","varför strida mot dem","kan vi inte lugna elementalerna"}},{q="Vem begär att elementalerna ska förgöras?",a="Uppdraget kommer från någon som vill hålla situationen under kontroll och helst hade blidkat andarna fredligt. Eftersom personen saknar den magiska eller andliga kunskap som krävs för att lugna dem vänder hen sig i stället till äventyrare för att undanröja hotet.",al={"vem ger rime's wrath","vem vill att elementalerna ska dö","vem är uppdragsgivaren"}},{q="Kunde man ha hanterat elementalerna fredligt?",a="Uppdragsgivaren säger att det översteg hens kunskap att blidka dem. Elementandar kan ibland balanseras eller blidkas, men utan rätt sakkunskap fanns inget annat val än att strida mot dem.",al={"kan iselementaler lugnas","blidka iselementaler","varför inte lugna elementalerna"}},{q="Vad är mindre iselementaler för slags varelser?",a="Mindre iselementaler är oberäkneliga manifestationer av elementär frost. Trots att de räknas som mindre andar gör deras kyla och aggressiva natur dem farliga för resenärer och lokalbefolkningen om de får ströva fritt.",al={"vad är mindre iselementaler","faran med iselementaler","hur starka är mindre iselementaler"}},{q="Vad blir resultatet av att hantera elementalerna?",a="När tio mindre iselementaler har besegrats är den omedelbara faran över. Uppdragsgivaren beklagar att våld var nödvändigt och medger att det helt enkelt var för riskabelt att låta dem härja fritt.",al={"vad händer efter rime's wrath","slutet på rime's wrath"}}},fp="12,137,22.160.0,16.166.0,21.148.0,53.152.0,47.156.0,53.131.0,48.157.0,51.176.0"}
P.entries["quest:99161"] = {n="Rime's Wrath",s="Efter ett stenras dök en ovanligt stor elementarvarelse vid namn Avala upp och började orsaka oberäkneliga väderomslag och nya jordskred. En observatör ger äventyrare i uppdrag att spåra upp elementarvarelsen och ta dess kärna för att säkra området. När varelsen besegras blir bergssluttningarna stabila igen och resenärer skyddas från vinterns dödliga faror.",h="Efter ett stenras dök en ovanligt stor elementarvarelse vid namn Avala upp och började orsaka oberäkneliga...",kw={"avala","avala kärna","elementarvarelse","elementarkärna","rime's wrath","stenras","väder","vinter"},ang={["class:Paladin"]="Paladiner värnar om plikten att skydda resenärer och utsatta allmoge från plötsliga katastrofer. När uppdraget slutförs åkallar uppdragsgivaren Ljusets välsignelse som tack för att onödiga dödsfall har förhindrats.",["class:Shaman"]="Schamaner känner igen faran med tygellösa elementarvarelser som Avala, vars turbulenta närvaro förvrider det lokala vädret och skakar stenen. Det är viktigt att hejda sådana upprörda varelser för att återställa harmonin mellan elementen."},sec={{t="Stenrasets följder",b="Störningarna började när ett plötsligt stenras destabiliserade bergspasset och banade väg för elementarvarelser. Bland varelserna som dök upp utmärkte sig en särskilt, med sin enorma storlek och råa kraft. Den uppmärksamma uppdragsgivaren gav den det informella namnet \"Avala\". Denna mäktiga varelse är inte bara imponerande att se på, utan orsakar också direkt väderkaos i trakten och gör de omgivande klipporna instabila. Den utgör en omedelbar fara för alla som försöker ta sig genom området, eftersom instabil mark och plötslig vinterkyla gör vanliga resor livsfarliga."},{t="Avala hejdas",b="När faran från Avalas inflytande över terrängen blev allt större gick en uppmaning ut om att döda besten innan fler ras krävde liv. För att dräpa varelsen måste du möta både dess elementarkrafter och de hårda förhållanden den skapar. Till sist måste du hämta dess kärna som ett definitivt bevis på att den är död. När Avala har besegrats och dess livgivande hjärta säkrats avtar de våldsamma väderomslagen. Bergspassen i trakten blir tryggare och framtida resenärer skyddas från onödiga katastrofer."}},faq={{q="Vad är Rime's Wrath?",a="Rime's Wrath är ett uppdrag där äventyrare ska döda Avala, en stor och farlig elementarvarelse som visade sig efter ett plötsligt stenras. Genom att spåra upp elementarvarelsen och hämta dess kärna sätter äventyrarna stopp för de oberäkneliga väderstörningarna och återkommande rasen som hotar resenärer i bergspasset.",al={"rime's wrath","vad är rime's wrath","uppdraget rime's wrath"}},{q="Vem eller vad är Avala?",a="Avala är en ovanligt stor elementarvarelse som dök upp efter ett stort stenras. Avala är större än andra elementarvarelser och orsakar plötsliga väderomslag, bitande kyla och farliga jordskalv i området. Namnet \"Avala\" gavs av observatören som håller uppsikt över passet.",al={"vad är avala","vem är avala","avala elementarvarelse"}},{q="Varför måste Avala dödas?",a="Avalas ständiga närvaro orsakar oförutsägbara väderstörningar och mindre stenras som destabiliserar de omgivande sluttningarna. Om ingen hejdar den hotar elementarvarelsens övernaturliga inflytande över vintervädret och terrängen att utlösa fler ras och orsaka dödsfall bland resenärer i bergspasset.",al={"varför döda avala","skäl att döda avala","varför förgöra avala"}},{q="Vilket bevis krävs för att slutföra Rime's Wrath?",a="Äventyrarna måste hämta Avalas kärna efter att ha besegrat varelsen i strid. När kärnan lämnas till uppdragsgivaren bekräftar det att hotet är undanröjt och att klimatet i trakten kan återgå till det normala.",al={"bevis på avala","vilket föremål släpps","avala kärna bevis"}},{q="Hur visade sig Avala först?",a="Avala dök upp efter ett första stenras som störde området. Den visade sig tillsammans med andra elementarvarelser efter raset och blev snabbt den mest framträdande och farligaste av dem tack vare sin storlek och elementarkraft.",al={"var kom avala ifrån","avalas ursprung","hur uppstod avala"}},{q="Vem ger uppdraget Rime's Wrath?",a="Uppdraget ges av en lokal observatör som är stationerad nära det farliga bergspasset och noga höll uppsikt över stenraset och elementarvarelsernas uppdykande. När uppdraget är slutfört åkallar denna väktare den Heliga Ljusets välsignelse. Hen vill förhindra onödiga dödsfall genom att anlita dugliga förkämpar för att döda Avala.",al={"vem ger rime's wrath","uppdragsgivare för rime's wrath","rime's wrath uppdragsgivare"}},{q="Vad händer när Avala besegras?",a="När Avala har dödats och dess kärna återlämnats avtar de kraftiga väderomslagen och de lokala skalv som varelsens närvaro orsakat. Uppdragsgivaren ger en välsignelse från Ljuset och en belöning, och konstaterar att området har blivit betydligt säkrare för framtida resenärer.",al={"vad händer när avala dör","slutföra rime's wrath","efter rime's wrath"}}},fp="12,177,25.310.0,14.327.0,21.178.0,21.216.0,36.201.0,46.132.0,27.151.0,34.265.0,37.187.0"}
P.entries["quest:99162"] = {n="Treacherous Cold",s="Treacherous Cold är en räddningsinsats i Dun Moroghs förrädiska höjder efter förödande snö- och isras. Äventyrare får i uppdrag att hämta de ingraverade gevären från fallna bergsvakter i Ironforge, så att de kan identifieras och deras familjer få visshet.",h="Treacherous Cold är en räddningsinsats i Dun Moroghs förrädiska höjder efter förödande snö- och isras.",kw={"lavin","dun morogh","ironforge","bergvakter","gevär","snöras","treacherous cold"},ang={["class:Hunter"]="Bergsvakterna litar på sina gevär i den frusna vildmarken och ristar in sina namn i träkolvarna, så att deras identiteter och bedrifter aldrig glöms.",["faction:Alliance"]="När fallna bergvakters utrustning hämtas kan Ironforge ge visshet åt familjerna som offrat sina närstående för att skydda de höga vägarna.",["race:Dwarf"]="Dun Moroghs toppar är dvärgarnas hemland, men även erfarna bergsvakter kan ryckas bort av plötsliga laviner och fientliga element i bergspassen."},sec={{t="Faror på höjderna",b="Dun Moroghs karga, snötäckta klippor utgör en ständig fara för både resande och soldater. Även Ironforges härdade bergsvakter kan överrumplas av plötsliga laviner och fallande ismassor, och oerfarna rekryter får sätta livet till när vintern slår till utan förvarning."},{t="Dyster räddningsinsats",b="När ras begraver patruller blir sökandet i den farliga terrängen en dyster kapplöpning mot tiden. Ökad elementaraktivitet i området gör omfattande räddningsexpeditioner riskfyllda, så spejare måste be modiga vandrare att söka igenom snödrivorna efter fallna bergsvakter och hämta deras ingraverade gevär innan snön döljer dem för alltid."},{t="Ingraverade gevärskolvar",b="Varje bergsvakt i Ironforge graverar in sitt namn i gevärskolven. Det blir ett bestående kännetecken under de hårdaste förhållandena. När sökarna säkrar vapnen ur snödrivorna kan de fallna identifieras och deras familjer i Ironforge få veta om deras hedrade tjänst."}},faq={{q="Vad är Treacherous Cold?",a="Treacherous Cold går ut på att söka igenom Dun Moroghs snöfyllda bergspass efter bergsvakter som drabbats av plötsliga ras och hämta deras tjänstegevär.",al={"vad är treacherous cold","uppdraget treacherous cold"}},{q="Varför samlas bergvakternas gevär in?",a="Bergsvakterna graverar in sina namn direkt på gevärskolvarna. I de iskalla snödrivorna kan kroppar ligga begravda eller vara omöjliga att återfinna. Om deras vapen hämtas kan Ironforge säkert identifiera de fallna och underrätta deras familjer.",al={"varför samla in gevär","bergvakternas gevär","varför behöver vi deras vapen"}},{q="Vilka försvinner i snön?",a="Oerfarna bergsvakter som patrullerar Dun Morogh är särskilt utsatta för plötsliga laviner, fallande is och extremt väder i de höga bergen.",al={"vilka är offren","vem försvinner i dun morogh"}},{q="Varför har sökandet inte redan genomförts?",a="Uppdragsgivaren brukar genomföra räddnings- och bärgningssök efter ett ras, men de senaste elementarstörningarna i Dun Morogh har gjort det alldeles för farligt att ensam ta sig djupt in i bergspassen.",al={"varför kan inte uppdragsgivaren söka","varför behövs en äventyrare"}},{q="Vad händer med gevären när de har hämtats?",a="De gevär som hämtas samlas ihop och skickas tillbaka till staden Ironforge, där myndigheterna ser till att de fallna bergvakternas personliga vapen återlämnas till deras familjer.",al={"vart skickas gevären","vad händer med hämtade gevär"}},{q="Vad gör Dun Moroghs höga bergspass så farliga?",a="Dun Moroghs höjder präglas av sträng kyla, bländande snöras och instabila klippor. Tillsammans med den oroliga elementaraktiviteten kan miljön snabbt övermanna även tränade dvärgpatruller.",al={"hur farligt är dun morogh","faror i dun morogh"}}},fp="16,158,19.219.0,13.331.0,16.192.0,25.117.0,43.192.0,30.140.0,45.197.0,42.136.0,54.179.0"}
P.entries["quest:99191"] = {n="A Donation of Wool",s="High Order tar emot ylletyg från dem som söker dess fulla erkännande. Sextio stycken täcker dess nuvarande behov.",h="High Order tar emot ylletyg från dem som söker dess fulla erkännande.",kw={"donation","high order","erkännande","sextio stycken","ull","ylletyg"},sec={{t="En värdig gåva",b="High Order tar emot ylletyg, och sextio stycken täcker dess nuvarande behov. Givaren kan ta emot din donation nu. I gengäld ger orden dig sitt fulla erkännande."}},faq={{q="Vad behöver High Order?",a="High Order behöver ylletyg, och sextio stycken täcker dess nuvarande behov.",al={"high order ull","vad ska doneras","ulldonation"}},{q="Hur mycket ylletyg ska jag ge?",a="Ge sextio stycken ylletyg för att få fullt erkännande från High Order.",al={"hur mycket ull","sextio ull","ullmängd"}},{q="Vem kan ta emot donationen?",a="Givaren kan ta emot dina sextio stycken ylletyg.",al={"vem tar emot ull","donation givare","ge ull"}},{q="Vad får jag genom att donera?",a="Att ge sextio stycken ylletyg ger dig fullt erkännande från High Order.",al={"ull erkännande","anseende hos high order","donationens fördel"}}},fp="18,113,13.168.0,30.72.0,34.77.0,26.53.0,27.81.0"}
P.entries["quest:99196"] = {n="A Donation of Wool",s="Windshapers tar emot donationer av ylletyg, och sextio stycken ger dig deras fulla erkännande.",h="Windshapers tar emot donationer av ylletyg, och sextio stycken ger dig deras fulla erkännande.",kw={"donation","erkännande","sextio stycken","windshapers","ull","ylletyg"},sec={{t="En gåva av ull",b="Windshapers tar emot ylletyg från dig. När du är redo att donera kan deras representant ta emot sextio stycken."}},faq={{q="Vad vill Windshapers ha?",a="Windshapers tar emot donationer av ylletyg.",al={"windshapers donation","vilken ull tar de emot"}},{q="Hur mycket ylletyg ska jag ge?",a="Ge Windshapers sextio stycken ylletyg för att få deras fulla erkännande.",al={"hur mycket ull","sextio ull"}},{q="Vad får jag för att donera ullen?",a="Sextio stycken ylletyg ger dig Windshapers fulla erkännande för din generositet.",al={"resultat av ulldonation","windshapers erkännande"}},{q="Kan deras representant ta emot ullen nu?",a="Deras representant kan ta emot de sextio tygstyckena när du har dem med dig och är redo att donera.",al={"ge ull nu","donera tyg"}}},fp="18,99,14.115.0,29.51.0,34.69.0,36.88.0,43.99.0"}
P.entries["quest:992"] = {n="Gadgetzan Water Survey",s="Senior Surveyor Fizzledowser i Gadgetzan söker en tillfällig juniorbesiktningsman åt Gadgetzan Water Company. Nomaderna har tagit företagets brunnar, så du får en slagrutepryl för att ta ett vattenprov ur dammen nära Sandsorrow Watch.",h="Senior Surveyor Fizzledowser i Gadgetzan söker en tillfällig juniorbesiktningsman åt Gadgetzan Water Company.",kw={"slagrutepryl","fizzledowser","gadgetzan","gadgetzan water company","sandsorrow watch","tanaris"},sec={{t="Ett företag i vattennöd",b="Nomaderna har tagit alla brunnar som tillhör Gadgetzan Water Company, så företaget måste hitta fler fria vattenkällor. Senior Surveyor Fizzledowser tror att det finns några i öknen, men bara för den som är smart nog att undersöka området först. Han söker en tillfällig juniorbesiktningsman som kan hjälpa till."},{t="Provtagning vid Sandsorrow Watch",b="Du får en oanvänd slagrutepryl och skickas till dammen nära Sandsorrow Watch. Dammen ligger rakt väster om Gadgetzan och söder om Zul'Farrak, inom synhåll för trollen i närheten. Du ska ta ett vattenprov med prylen och lämna tillbaka den använda prylen till Fizzledowser."},{t="Tillbaka hos Fizzledowser",b="När du kommer tillbaka får Fizzledowser höra att du överfölls av något otäckt kryp med dålig mojo. Han medger att det har kommit rapporter om galna insektsvarelser som suger upp öknens vatten. Först trodde han att det var struntprat, troligen ännu ett problem orsakat av nomaderna, men nu är sanningen känd."}},faq={{q="Vem erbjuder undersökningsarbetet i Gadgetzan?",a="Senior Surveyor Fizzledowser, som söker en tillfällig juniorbesiktningsman åt Gadgetzan Water Company.",al={"vem ger vattenundersökningen i gadgetzan","uppdragsgivare för vattenundersökningen i gadgetzan","vem är fizzledowser"}},{q="Varför letar Gadgetzan Water Company efter nya vattenpölar?",a="Nomaderna har tagit företagets alla brunnar, så det behöver hitta andra fria vattenkällor.",al={"varför undersöka vatten","varför behöver gadgetzan vatten"}},{q="Var ligger dammen som ska undersökas?",a="Vid dammen nära Sandsorrow Watch, som ligger rakt väster om Gadgetzan och söder om Zul'Farrak, inom synhåll för trollen i närheten.",al={"var ligger dammen","var ligger dammen vid sandsorrow watch","var använder man slagruteprylen"}},{q="Vilket verktyg får du för att samla in provet?",a="En slagrutepryl som du använder vid dammen för att ta ett vattenprov.",al={"slagrutepryl","vilket föremål används"}},{q="Vad följer efter det här steget?",a="Det här inleder kedjan som fortsätter med Noxious Lair Investigation.",al={"vilket uppdrag kommer härnäst","uppdragskedjan för vattenundersökningen i gadgetzan"}}},fp="22,226,26.239.0,28.253.0,22.279.1,40.105.0,59.100.0,40.112.0,47.59.0,23.71.0"}
P.entries["quest:99260"] = {n="Fillion's Mission",s="Fillion's Mission skildrar följderna av en spaning för att kartlägga elementarströmmar vid Overlook Standing Stones. Uppgifterna skulle visa säkra flygleder för skycutterfartyg mellan Skywall och Azeroth, men när spanaren sätts ur spel hotas hela företaget.",h="Fillion's Mission skildrar följderna av en spaning för att kartlägga elementarströmmar vid Overlook Standing...",kw={"elaadrin evengale","elementarplanet","fillion","overlook standing stones","skycutter","skywall","valanaar","windshapers"},ang={["class:Mage"]="Arkanister som följer Supreme Magisters planer kommer att uppskatta de invecklade magiska beräkningar som krävs för att styra skycutterfartyg genom turbulensen mellan planen.",["race:Skyborne"]="Uppdraget berör direkt ditt folks kamp för att upprätta säkra flygleder mellan Skywall och Azeroth trots motsättningar mellan fraktionerna."},sec={{t="Ett farligt uppdrag",b="Fillion skickades till Overlook Standing Stones för att samla in viktiga mätvärden om elementarenergins strömmar. Dessa mätvärden ligger till grund för beräkningarna som krävs för att styra skycutterfartyg mellan Skywall och Azeroth. Efter en prövning som krävde att han räddades kan Fillion inte slutföra sitt uppdrag, och de viktiga uppgifterna antas vara förlorade. Eftersom hans skador hindrar honom från att fortsätta ber han sin räddare rapportera till Supreme Magister."},{t="Planar strid i Valanaar",b="I bosättningen Valanaar tar Supreme Magister Elaadrin Evengale med lättnad emot beskedet att Fillion överlevt, men sörjer den förlorade forskningen. Utan tillförlitliga navigationsuppgifter blir det mycket svårt att öppna säkra färdvägar genom Elemental Plane. Läget förvärras ytterligare av rapporter om att rivaliserande Windshapers har skaffat ett eget sätt att färdas mellan plan, men vägrar dela med sig och sätter fraktionens hemlighetsmakeri framför allas bästa."}},faq={{q="Vem är Fillion?",a="Fillion är ett sändebud eller en spejare som Supreme Magister skickat för att samla in viktiga mätvärden om elementarenergins flöden från Overlook Standing Stones. Efter att ha räddats av en äventyrare är han fortfarande för svag för att slutföra sitt ursprungliga uppdrag.",al={"vem är fillion","fillions bakgrund","fillion wow"}},{q="Vem är Supreme Magister Elaadrin Evengale?",a="Elaadrin Evengale är Supreme Magister och bor i Valanaar. Han leder arbetet med att färdas säkert genom Elemental Plane och samordnar insamlingen av uppgifter om planen för att säkra resor mellan Skywall och Azeroth.",al={"vem är supreme magister","elaadrin evengale","vem är elaadrin"}},{q="Varför var Fillions uppgifter så viktiga?",a="Uppgifterna visar elementarenergins strömmar, som mättes upp vid Overlook Standing Stones. De är avgörande för beräkningarna som krävs för att säkert navigera skycutterfartyg genom Elemental Plane till Azeroth utan att de förstörs.",al={"varför är uppgifterna viktiga","vilka uppgifter förlorade fillion","elementaruppgifter skywall"}},{q="Vilka är Windshapers?",a="Windshapers är en fraktion som enligt uppgift har säkrat ett eget sätt att färdas mellan plan. Enligt Supreme Magister Evengale vaktar de svartsjukt denna hemlighet på grund av dogmatisk högmod, i stället för att dela den till gagn för sitt folk.",al={"vilka är windshapers","windshapers historia","windshapers rivaler"}},{q="Vad är skycutters?",a="Skycutters är specialbyggda fartyg som kan flyga genom Elemental Plane. För att styra dem krävs exakta mätvärden för elementarenergins flöden. Annars slutar försöken att styra dem mellan Skywall och Azeroth i katastrof.",al={"vad är skycutters","skycutterfartyg","skycutter"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en fientlig eller föraktad fraktion som Supreme Magister Evengale nämner. Han jämför Windshapers själviska och dogmatiska beteende direkt med deras.",al={"vilka är alaketh","al'aketh","alaketh historia"}}},fp="17,156,21.350.0,25.364.1,15.191.0,42.176.0,36.167.0,24.212.0,20.159.0,21.140.0"}
P.entries["quest:993"] = {n="A Lost Master",s="Efter att ha samlat fina moonstalkerpälsar tar du den färdiga Enchanted Moonstalker Cloak med dig ut i Darkshores vildmark för att hitta den försvunna Night Elf Volcor. Med hjälp av hans trogna vita björn Grimclaw måste du spåra upp den sårade spejaren innan fientliga furbolger gör slut på honom.",h="Efter att ha samlat fina moonstalkerpälsar tar du den färdiga Enchanted Moonstalker Cloak med dig ut i...",kw={"auberdine","darkshore","furbolg","grimclaw","moonstalker cloak","nightsaber","terenthis","volcor"},ang={["class:Hunter"]="Att se Grimclaw hitta hjälp åt Volcor visar hur anmärkningsvärt intelligenta och lojala Kalimdors vältränade djur kan vara.",["faction:Alliance"]="Auberdine är beroende av spejare som Volcor för att hålla uppsikt över den växande korruptionen bland Darkshores furbolgstammar, så att rädda honom är livsviktigt för utposten.",["race:NightElf"]="Bandet mellan Night Elf-spejare och deras djurkamrater märks här i Grimclaws orubbliga lojalitet när han söker hjälp åt sin herre Volcor."},sec={{t="En fyr i skogen",b="När Terenthis i Auberdine har vävt Enchanted Moonstalker Cloak börjar sökandet efter den försvunna spejaren Volcor på allvar. Hans björnkamrat Grimclaw har återvänt till vägen söder om bosättningen och håller utkik efter en allierad som Terenthis skickat. Om du hälsar på det trogna odjuret på ett välbekant sätt leder det resenärer bort från den upptrampade stigen, mot grottan där Volcor gömmer sig."},{t="Gömd i mörkret",b="Volcor sökte skydd i en grotta efter att ha skadats svårt av de korrumperade furbolgerna i trakten. Instängd och blödande har han helt fått förlita sig på smygande och Grimclaws list för att undvika att bli övermannad. Den förtrollade manteln ger honom det skydd och hopp han behöver för att planera sin flykt, men hans sår gör återfärden till Auberdine farlig."}},faq={{q="Vem är Volcor?",a="Volcor är en Night Elf-spejare från Darkshore som försvann under en färd nära fientliga furbolgläger. Han sårades svårt i en sammandrabbning och lyckades krypa in i en närliggande grotta, medan hans björnkamrat Grimclaw sökte hjälp.",al={"volcors bakgrund","vem är den försvunne mästaren"}},{q="Hur hittar du Volcors gömställe?",a="Grimclaw väntar vid vägen söder om Auberdine. Om du vinkar till björnen förstår han att du är hjälpen som Terenthis skickat, och springer då direkt mot den avskilda grottan där Volcor vårdar sina sår.",al={"var finns volcor","hitta volcorgrottan","hur följer man grimclaw"}},{q="Vad är Enchanted Moonstalker Cloak till för?",a="Terenthis förtrollade manteln, som tillverkats av fina moonstalkerpälsar, så att den ger kortvarig och kraftfull magisk smygförmåga. Magin låter dig röra dig obehindrat bland Darkshores varelser medan du letar efter Volcor. Sedan får han manteln.",al={"moonstalker cloak","mantelns magi"}},{q="Vem angrep Volcor?",a="Volcor överfölls och sårades av de korrumperade furbolgstammar som strövar omkring i Darkshore. Han lyckades undkomma att bli dödad direkt, men skadorna hindrade honom från att på egen hand ta sig tillbaka till Auberdine.",al={"vem skadade volcor","varför blöder volcor"}},{q="Vad händer när du har hittat Volcor?",a="När Volcor får den förtrollade manteln hämtar han andan och ber dig hjälpa honom ut ur vildmarken. Du får välja mellan att leda honom ut försiktigt och obemärkt eller att röja väg genom furbolgerna med råstyrka.",al={"volcors nästa uppdrag","efter a lost master"}}},fx={["49342a22"]={q="Varför vill Terenthis hitta Volcor så brådskande?",a="Terenthis fruktar att tiden håller på att rinna ut för hans nattalvskamrat. Volcor överfölls av korrumperade furbolgs, och eftersom bara den lojala björnen Grimclaw har återvänt för att be om hjälp vet Terenthis att Volcor inte kan hålla sig gömd och överleva särskilt länge. Den förtrollade kappan är färdig och döljer hans lukt och närvaro. Nu måste du nå Volcor innan furbolgs jagar fatt honom eller hans skador tar hans liv.",al={"terenthis motiv","varför rädda volcor","varför bryr sig terenthis om volcor"}}},fp="13,171,21.327.0,18.281.1,14.220.0,37.165.0,55.205.0,20.164.0,34.198.1"}
P.entries["quest:994"] = {n="Escape Through Force",s="Escape Through Force är ett Alliance-uppdrag i Darkshore där du hjälper Volcor att kämpa sig igenom hoten omkring honom. När du har tagit dig förbi vildmarkens faror och nått vägen återförenas Volcor med sin trogna följeslagare Grimclaw. Sedan rapporterar du till Terenthis i Auberdine att Volcor kommit undan oskadd.",h="Escape Through Force är ett Alliance-uppdrag i Darkshore där du hjälper Volcor att kämpa sig igenom hoten...",kw={"auberdine","darkshore","eskort","grimclaw","selarin","terenthis","volcor"},ang={["faction:Alliance"]="När du hjälper lokala spejare stärks banden mellan unga Alliance och Night Elves. Det visar fraktionens värde när Kalimdors norra gräns ska säkras.",["race:NightElf"]="Att rädda spejare som Volcor är avgörande för kaldoreiernas osäkra grepp om Darkshore, där vilddjur, fördärv och inkräktare utifrån hotar deras förfäders skogsland."},sec={{t="En rak väg ut",b="När du är strandsatt i Darkshores farliga vildmark är det inte alltid bäst att röra sig försiktigt. Ställd inför faran väljer nattalven Volcor en rättfram strategi: han tar sig rakt igenom de fientliga varelserna omkring sig för att nå säkerhet. I stället för att försöka smyga sig undan förlitar han sig på sin stridskonst och röjer en väg rakt ner till huvudvägen."},{t="Återförening vid vägen",b="När Volcor tryggt når vägen återförenas han med Grimclaw, hans trogna björnkamrat som väntat vid stigen. Nu när flykten är säkrad förbereder sig Volcor för nästa resa och ber dig rapportera direkt till Terenthis i Auberdine. Beskedet om att Volcor är oskadd lugnar nattalvernas ledning och väcker genast Sentinel Selarins uppmärksamhet. Det pekar mot större problem som håller på att uppstå söderut i Ashenvale."}},faq={{q="Vem är Volcor?",a="Volcor är en nattalvsspejare eller skogsvaktare i Darkshore som försvann tillsammans med sin följeslagare Grimclaw. Äventyrare som letar efter honom på Terenthis uppdrag hittar honom. Han behöver hjälp att ta sig undan fientliga djur och farlig terräng.",al={"volcors identitet","vem är volcor","volcor i darkshore"}},{q="Vem är Grimclaw?",a="Grimclaw är Volcors trogna björnkamrat. Medan Volcor var fångad höll sig Grimclaw vid vägen, där björnen blev den bestämda mötesplatsen för Volcors flykt.",al={"grimclaw","volcors björn","volcors husdjur"}},{q="Varför bryr sig Terenthis om att Volcor återvänder?",a="Terenthis samordnar spejarnas rörelser och det lokala försvaret från Auberdine. Det är viktigt att hitta försvunna allierade och bedöma hoten längs kusten för att bevara nattalvernas kontroll över ett Darkshore som snabbt blir allt oroligare.",al={"terenthis och volcor","varför hjälpa volcor","terenthis uppdrag"}},{q="Vad händer när uppdraget är klart?",a="Rapportera till Terenthis i Auberdine att Volcor kommit fram oskadd. Uppdragskedjan fortsätter sedan med Trek to Ashenvale.",al={"efter escape through force","what comes next","nästa uppdrag efter volcor"}},{q="Finns det ett annat sätt att slutföra eskortuppdraget för Volcor?",a="Ja. När du räddar Volcor får du välja hur ni ska ta er ut: kämpa er fram via Escape Through Force eller smyga förbi farorna tillsammans.",al={"alternativ till escape through force","smyga ut med volcor","volcors val"}},{q="Vart leder uppdraget i den större berättelsen?",a="När Volcor räddas knyts de lokala konflikterna i Darkshore samman med nattalvernas större regionala försvar. Det öppnar direkt för uppdrag i Ashenvale.",al={"volcors berättelse","uppdragskedja från darkshore till ashenvale"}}},fx={["8bb9ddbb"]={q="Varför vill Volcor kämpa sig ut?",a="Volcor har varit fångad och hotad alltför länge i Darkshores vildmarker, långt från sin följeslagare Grimclaw. Han har bestämt sig för att bryta sig ut direkt i stället för att smyga iväg och tänker bana väg genom alla fiender som spärrar vägen ner till landsvägen. Hans enda mål är att nå säkerheten och återförenas med sin lojala björn innan han rapporterar tillbaka till Auberdine.",al={"volcors motiv","varför fly genom strid","varför vill volcor detta"}},["365007a7"]={q="Varför behöver Volcor din hjälp för att fly?",a="Volcor är skild från Grimclaw och omringad av fientliga hot i vildmarken. Ensam och oskyddad löper han stor risk om han försöker slå sig igenom med råstyrka. Med ditt stöd i striden har han mycket större chans att överleva den långa vägen ner till landsvägens trygghet än om han försöker kämpa sig ut på egen hand.",al={"varför behöver volcor mig","varför kan inte volcor fly ensam","varför hjälpa volcor"}}},fp="20,152,16.216.0,19.308.1,14.211.0,16.145.0,46.166.0,41.104.1,52.91.0,52.128.1"}
P.entries["quest:99411"] = {n="Kyle's Gone Missing!",s="Kyle's Gone Missing! är ett lokalt uppdrag i Bloodhoof Village där Ahab Wheathoof ber förbipasserande äventyrare hitta hans egensinniga hund, Kyle the Frenzied. En bit mört striderkött stillar den hungriga valpens humör och hjälper honom att tryggt återvända hem.",h="Kyle's Gone Missing!",kw={"ahab wheathoof","bloodhoof village","kyle","kyle the frenzied","kyle's gone missing!","mulgore","plainstrider","mört striderkött"},ang={["faction:Horde"]="När du hjälper de lokala invånarna i Bloodhoof med vardagliga bestyr stärks banden till Shu'halo medan de bosätter sig i och försvarar sitt hemland.",["race:Tauren"]="Ahab Wheathoof bor i Bloodhoof Village, så det här personliga ärendet är ett välbekant sätt att stötta gemenskapen ute på Mulgore's betesmarker."},sec={{t="En försvunnen hund",b="I Bloodhoof Village oroar sig äldste Ahab Wheathoof för sitt egensinniga husdjur, Kyle the Frenzied. Titeln kan låta alarmerande för utomstående, men Kyle är Ahabs älskade valp som har smitit ut på Mulgore's grässlätter. Ahab ber resenärer som passerar genom bosättningen att spåra upp sin ostyriga följeslagare och bjuda honom på en rejäl måltid för att lugna hans vilda lynne."},{t="En enkel lösning",b="För att lugna Kyle behövs en bit mört striderkött från de snabba plainstriders som strövar omkring i Mulgore. När han får godbiten blir den hungriga valpen mätt, hans ursinniga humör stillas och han lockas tryggt tillbaka till Bloodhoof Village och sin tacksamma ägare."}},faq={{q="Vem är Ahab Wheathoof?",a="Ahab Wheathoof är en äldste tauren som bor i Bloodhoof Village i Mulgore. Han bryr sig djupt om sin älskade hund Kyle och ber resande äventyrare hjälpa honom att hitta och mata hunden när den har vandrat för långt hemifrån.",al={"vem är ahab wheathoof","ahab mulgore","uppdragsgivare kyle"}},{q="Vem är Kyle the Frenzied?",a="Kyle är Ahab Wheathoofs älskade hund, känd som Kyle the Frenzied. Trots sin vildsinta titel är han Ahabs älskade följeslagare. Det räcker att mata honom med mört striderkött för att lugna honom och locka honom tillbaka.",al={"vem är kyle","kyles hund","kyle the frenzied"}},{q="Var utspelar sig uppdraget?",a="Bloodhoof Village är en central taurenbosättning mitt i Mulgore, söder om Thunder Bluff. Den är en viktig samlingsplats för lokala stammar, handelsmän och herdar.",al={"var ligger bloodhoof village","bloodhoofs plats"}},{q="Varför behöver Kyle mört striderkött?",a="Kyle tycker särskilt mycket om färskt kött från plainstriders som strövar omkring i Mulgore. Mört striderkött lugnar den hungriga hunden och får honom att återvända tryggt till Ahab.",al={"varför mört striderkött","striderkött kyle","hur lugnar man kyle"}},{q="Varför anses Kyle vara ursinnig?",a="I trakten kallas Kyle 'the Frenzied'. Han strövar omkring på slätterna när han har gått vilse eller är hungrig. Hans ursinne lägger sig när en tålmodig resenär ger honom ordentligt med mat.",al={"varför är kyle ursinnig","kyle arg"}},{q="Var kan Kyle hittas?",a="Kyle strövar omkring på de öppna slätterna runt Bloodhoof Village i Mulgore. Resenärer brukar leta efter honom på prärien i närheten tills de kan bjuda honom på en måltid.",al={"kyles plats","var är kyle"}}},fp="20,167,15.363.0,15.224.0,22.205.0,25.123.0,32.115.0,39.179.0,32.147.0,24.148.0"}
P.entries["quest:995"] = {n="Escape Through Stealth",s="Escape Through Stealth är ett eskortuppdrag för Alliansen i Darkshore. Efter att ha hittat nattalvsspejaren Volcor, fångad djupt inne i ett furbolghåla, hjälper du honom förbi fientliga bestar till friheten innan du rapporterar till Terenthis i Auberdine.",h="Escape Through Stealth är ett eskortuppdrag för Alliansen i Darkshore.",kw={"ashenvale","auberdine","darkshore","eskort","furbolg","smyga","terenthis","volcor"},ang={["class:Rogue"]="Rogues uppskattar Volcors taktiska instinkt att kringgå en väl förskansad fiende i stället för att slösa tid och blod på en vårdslös frontalkamp.",["faction:Alliance"]="När du lyckas säkra Volcors flykt visar det nattalvledarna i Auberdine att Alliansens allierade som inte är kaldorei går att lita på i känsliga uppdrag i vildmarken.",["race:NightElf"]="För nattalver stärker hjälpen till Volcor det viktiga nätverket av spejare som vakar över Kalimdors utsatta skogar medan fördärvet sprider sig från fördärvade gravhögar och hålor."},sec={{t="Den fångade spejaren",b="Volcor, en agent som skickats till Darkshores djup för att undersöka de växande hoten i regionen, blev instängd i en furbolggrotta. I underläge och avskuren från huvudvägarna förlitar han sig på en förbipasserande allierad för att samordna en flykt innan de fientliga furbolgerna märker att han smiter iväg."},{t="En försiktig flykt",b="I stället för att försöka sig på en självmordsartad frontalanstormning väljer Volcor försiktighet. Med hjälp av skuggorna och noggranna rörelser smyger han förbi grottans fördärvade invånare. Eftersom snabbhet och tystnad är avgörande skiljs Volcor från sin räddare när de kommit ut ur grottan. Han springer före till fots och ber sin räddare möta honom i bosättningen Auberdine."},{t="Rapport till Auberdine",b="När du återvänder till Auberdine berättar du för Terenthis om räddningen. Han är en nattalvledare som samordnar arbetet med att skydda den utsatta kusten. Terenthis ser Volcors trygga återkomst som ett bevis på att disciplin och samarbete kan stå emot mörkret som breder ut sig i Darkshore och vildmarken bortom."}},faq={{q="Vem är Volcor?",a="Volcor är en nattalvsspejare som gav sig djupt in i Darkshores vildmark på uppdrag av sina överordnade. Han blev fångad i en fientlig furbolggrotta tills en äventyrare från Alliansen räddade honom.",al={"volcors bakgrund","vem är volcor","volcor i darkshore"}},{q="Varför springer Volcor iväg ensam när han kommit ut ur grottan?",a="Volcor säger att han kan färdas snabbare på egen hand när han väl har kommit ut ur grottans trånga gångar. Han ber äventyraren att möta honom i Auberdine i stället för att hålla ihop längs de öppna vägarna.",al={"varför lämnar volcor","volcor skiljs från gruppen"}},{q="Vem är Terenthis?",a="Terenthis är en framstående nattalvsamordnare som är stationerad i Auberdine. Han ansvarar för lokala spejaruppdrag och organiserar insatser mot fördärvet och de fientliga invånare som hotar Darkshore.",al={"terenthis auberdine","vem är terenthis"}},{q="Var äger räddningen rum?",a="Räddningen börjar djupt inne i en furbolggrotta i Darkshores vildare, omstridda skogar, långt från tryggheten i Auberdine.",al={"volcors grotta plats","var ligger volcors grotta"}},{q="Vad händer när uppdraget är slutfört?",a="När Volcor är i säkerhet och Terenthis har fått sin rapport skickas du vidare till nästa del av färden söderut mot Ashenvale i uppdraget Trek to Ashenvale.",al={"vad kommer efter escape through stealth","nästa uppdrag efter volcor"}},{q="Vad finns det för alternativ till smygande under räddningen?",a="Volcor erbjuder ett alternativ: i stället för att smyga ut kan äventyrare välja att kämpa sig ut med ren styrka i ett separat eskortuppdrag med fokus på strid.",al={"flykt med våld","volcors andra uppdrag","smyga eller slåss"}}},fx={b4a3f8fd={q="Varför vill Volcor fly i smyg?",a="Volcor är fångad djupt inne i ett fientligt furbolgshåla, och hans främsta bekymmer är att överleva tillräckligt länge för att återvända till Auberdine och rapportera till Terenthis. Om han smiter förbi de korrumperade furbolgs utan att slå larm får han den säkraste vägen ut ur hålan och slipper riskera en övermäktig strid i trånga utrymmen.",al={"varför fly i smyg","volcors motiv för att smyga","varför smyga ut med volcor"}}},fp="22,154,17.228.0,16.197.0,22.261.0,14.166.0,52.169.0,17.161.0,34.99.0,41.143.0,50.133.0"}
P.entries["quest:997"] = {n="Denalan's Earth",s="Denalan's Earth är ett ärende söderut från Dolanaar till Lake Al'Ameths lugna vatten. Syral Bladeleaf ber resande att personligen lämna en försenad leverans av sällsynt, näringsrik jord till sin botanistkollega Denalan, som studerar den nya världsträdets grenar och växtlighet.",h="Denalan's Earth är ett ärende söderut från Dolanaar till Lake Al'Ameths lugna vatten.",kw={"darnassus","denalan","dolanaar","lake al'ameth","rare earth","syral bladeleaf","teldrassil","timberling"},ang={["class:Druid"]="Druider känner en naturlig samhörighet med Denalans arbete, eftersom det är viktigt att följa Teldrassils växtlighet och dess balans för att värna naturen på den nya grenen.",["profession:Herbalism"]="Örtkännare kommer att uppskatta Denalans tillflyktsort vid sjön, eftersom hans experiment handlar om att förstå det sköra, spirande växtliv som är unikt för det nyvuxna världsträdet.",["race:NightElf"]="För nattalver som lämnar Shadowglen blir hjälpen till Syral och Denalan en tidig introduktion till det större ansvar som krävs för att värna Teldrassil."},sec={{t="Bud åt Dolanaar",b="När resande färdas genom Dolanaar på väg söderut mot Lake Al'Ameth vinkar Syral Bladeleaf till sig dem med ett försenat ärende. Hennes forskarkollega Denalan beställde ett särskilt paket sällsynt jord hela vägen från Darnassus för att stödja sina pågående botaniska studier. Försändelsen blev försenad under transporten och anlände till Dolanaar först nyligen. I stället för att låta den näringsrika jorden förfaras eller bli liggande söker Syral en hjälpsam budbärare som kan bära den längs skogsstigen till Denalans läger vid sjön."},{t="Att odla Teldrassil",b="Denalan har en avskild arbetsplats längs Lake Al'Ameths östra strand, där han iakttar hur Teldrassils spirande ekosystem slår rot. Teldrassil är ungt och växte snabbt efter slaget vid Mount Hyjal, och dess växtlighet beter sig oväntat. Denalan använder unika jordblandningar och exemplar för att pröva livskraften och beteendet hos öns timberlings och inhemska växter, så den färska leveransen av sällsynt jord är avgörande för hans experiment."}},faq={{q="Vem är Denalan?",a="Denalan är en nattalvsforskare och örtkännare som har slagit läger på Lake Al'Ameths östra strand. Han ägnar sin tid åt att studera, odla och experimentera med Teldrassils unika växtliv.",al={"denalans berättelse","vem är denalan","denalan npc"}},{q="Var finns Syral Bladeleaf?",a="Syral Bladeleaf håller till i Dolanaar, den främsta nattalvsutposten i centrala Teldrassil, där hon samordnar forskningsleveranser och hjälper resande som färdas över grenarna.",al={"syral bladeleafs plats","var finns syral"}},{q="Vad används den sällsynta jorden till?",a="Leveransen innehåller särskilt näringsrik jord från Darnassus, huvudstaden. Den behövs för att Denalan ska kunna vårda experimentella planteringar och pröva hur Teldrassils inhemska plantor, som timberlings, reagerar på olika odlingsförhållanden.",al={"vad behöver denalan jorden till","sällsynt jords användning"}},{q="Var ligger Lake Al'Ameth?",a="Lake Al'Ameth ligger söder om Dolanaar och är en fridfull vattenyta bland Teldrassils södra rötter.",al={"lake al'ameths läge","hur tar man sig till lake al'ameth"}},{q="Varför blev leveransen försenad?",a="Paketet skulle fraktas från Darnassus och drabbades av ospecificerade förseningar längs Teldrassils slingrande vägar innan det till slut nådde distributionsplatsen i Dolanaar.",al={"varför blev jorden försenad","försenat paket"}},{q="Vad leder leveransen av jorden till?",a="När Denalan har tagit emot den sällsynta jorden ber han budbäraren att hjälpa till att samla timberlinggroddar och frön längs sjöns stränder, vilket inleder en mer omfattande serie botaniska fältstudier.",al={"uppföljning på denalans jord","what comes next"}}},fx={["77a156f9"]={q="Varför vill Syral Bladeleaf att den sällsynta jordarten levereras?",a="Denalan har ivrigt väntat på den här leveransen från Darnassus för att kunna fortsätta sina experiment med Teldrassils lokala växtlighet. Eftersom den sällsynta jordarten blev försenad under transporten och nyligen kom fram till Dolanaar vill Syral att den förs till hans läger vid sjön utan ytterligare dröjsmål, innan materialet förlorar sin kraft.",al={"varför leverera rare earth","syral bladeleafs motiv","varför skicka jordarten till denalan"}},["2b5476f7"]={q="Varför ber Syral dig att leverera den?",a="Syral Bladeleaf stannar i Dolanaar för att sköta sina plikter, och hon ser helt enkelt att du är en kapabel resenär på väg söderut mot Lake Al'Ameth. Eftersom leveransen redan har blivit kraftigt försenad är det snabbaste sättet att få den till Denalan att anförtro den åt någon som ändå är på väg mot hans tillflyktsort.",al={"varför behöver syral mig","varför inte skicka en kurir","varför jag med denalan's earth"}}},fp="15,160,22.261.0,22.386.0,15.171.0,33.156.0,32.199.0,23.71.0,26.116.0,40.159.1"}
P.entries["quest:cutting-teeth"] = {n="Cutting Teeth",s="I Valley of Trials möter nya rekryter sitt första prov mot fläckiga vildsvin. Uppsyningsmannen Gornek skickar blivande krigare och magiker för att minska antalet vildsvin runt de kaktusbevuxna odlingarna, där de kan bevisa sin stridsförmåga och beredskap att tjäna Horden.",h="I Valley of Trials möter nya rekryter sitt första prov mot fläckiga vildsvin.",kw={"the barrens","vildsvin","cutting teeth","durotar","gornek","horden","fläckigt vildsvin","rekryter","valley of trials"},ang={["faction:Horde"]="Varje ung mästare som kommer till Durotar börjar i jorden och bevisar att Hordens framtid vilar på deras blod och svett, inte på oförtjänt anseende.",["race:Orc"]="Orchkulturen sätter praktisk överlevnad och krigarära högt. Även att gallra ut vildsvin är ett heligt första steg in i vuxenlivet och tjänsten för Thralls nya nation.",["race:Troll"]="Medan Darkspear-stammen återuppbygger sitt samhälle tillsammans med sina orchallierade bevisar unga trollspanare och mystiker sin självständighet bland Durotars skoningslösa rovdjur."},sec={{t="Ett prov på ryggrad",b="Valley of Trials lämnar föga utrymme för storslagna drömmar. Unga rekryter kanske föreställer sig att jaga stora bestar i The Barrens eller vinna ära på slagfältet, men uppsyningsmannen Gornek börjar med odlingarna. Att minska antalet fläckiga vildsvin är ett jordnära prov på en rekryts första färdigheter med vapen eller magi. Det visar om de kan möta en vild angripare och har vett nog att överleva sin första skärmytsling."},{t="Att tämja det röda stoftet",b="Vilda svin strövar omkring på jordbrukslotterna i den röda ökenbosättningen, norr och nordost om lägret. De bökar bland kaktusarna och hotar de få grödor som odlas i Durotars karga jord. Att skicka aspiranter för att röja undan dem håller lokala skadedjur i schack och formar samtidigt unga orcher och troll till försvarare av den nya nationen."}},faq={{q="Varför skickar Gornek rekryterna efter vildsvin i stället för större bestar?",a="Gornek skickar rekryter efter vildsvin eftersom Horden behöver dem vid liv. I The Barrens finns mäktiga kodoer och rovdjur, men en oprövad rekryt som skickas mot dem riskerar att dö i onödan. Vildsvinen ger ett sunt prov på grundläggande stridsförmåga utan att liv kastas bort.",al={"varför vildsvin","varför döda vildsvin","gorneks vildsvinsjakt"}},{q="Var finns de fläckiga vildsvinen?",a="Fläckiga vildsvin bökar bland snår och jordbrukslotter norr och nordost om den centrala gläntan i Valley of Trials.",al={"vildsvinens plats","var finns vildsvin","hitta fläckiga vildsvin"}},{q="Vad betyder uttrycket ”att få sina första tänder”?",a="”Att få in sina första stötar” betyder att skaffa sig sin första praktiska erfarenhet inom ett hantverk eller kall. För en blivande försvarare av Horden betyder det att lämna träningsdockor och tomt prat bakom sig och utgjuta blod i en kamp för överlevnad.",al={"vad betyder att få sina första tänder","betydelsen av att få sina första tänder"}},{q="Vem ger det här provet?",a="Gornek delar ut provet. Han är uppsyningsman i hjärtat av Valley of Trials, där han bedömer och leder nya rekryter som kommer till Durotars träningsmarker.",al={"vem ger cutting teeth","uppdragsgivare för cutting teeth","gorneks prövning"}},{q="Avslutar detta träningen i Valley of Trials?",a="Nej. Gornek varnar för att striden mot vildsvinen bara är en uppvärmning. Farligare utmaningar väntar, däribland att möta humanoida inkräktare och samla viktiga resurser i dalen.",al={"är detta det sista uppdraget","vad händer efter cutting teeth"}},{q="Varför är vildsvinen ett problem i dalen?",a="Vilda vildsvin strövar omkring på de lokala jordbrukslotterna och i snåren, där de hotar arbetarna och äter de få tåliga grödorna, som kaktusfrukt, som håller lägret vid liv.",al={"problemet med vildsvinen","vildsvin i valley of trials"}}},fx={["852f533a"]={q="Varför skickar Gornek mig i stället för de erfarna krigarna?",a="Valley of Trials finns till för att sålla bort de svaga och göra gröna rekryter till dugliga försvarare av Horde. Erfarna veteraner har viktigare uppgifter med att skydda Durotar och befästa Orgrimmar. För en oprövad nybörjare visar strider mot det lokala djurlivet att du har den styrka och ryggrad som krävs innan någon anförtror dig verkligt militärt ansvar.",al={"varför skicka mig på cutting teeth","varför behöver gornek rekryter","varför inte erfarna vakter"}}},fp="13,219,21.304.0,19.271.0,67.237.0,36.116.0,55.215.0,23.164.0,56.163.0,46.158.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="Galgar's Cactus Apple Surprise",s="I Valley of Trials skickar Galgar ut nya rekryter för att samla kaktusäpplen till sin svalkande godsak. Arbetet lär dem att samla föda och överleva i Durotars torra landskap.",h="I Valley of Trials skickar Galgar ut nya rekryter för att samla kaktusäpplen till sin svalkande godsak.",kw={"kaktus","cactus apple","durotar","mat","samla föda","galgar","horden","valley of trials"},ang={["faction:Horde"]="Varje ny rekryt som kommer till Valley of Trials lär sig snabbt att uthärda Durotars obarmhärtiga sol är en del av träningen, vid sidan av strid.",["profession:Cooking"]="Galgar visar med sin rätt hur man kan laga närande mat och uppfriskande godsaker av tåliga, taggiga ökenväxter.",["race:Orc"]="När orcherna slog sig ner i Durotar fick de anpassa sig till ett torrt landskap. Rätter av inhemska kaktusar visar orkernas praktiska förmåga att trivas i sitt nya hem."},sec={{t="Överleva i det röda ödemarkslandet",b="Unga orcher och Darkspear Trolls tar sina första steg som Horde-försvarare i Valley of Trials. Stridsövningar och hårda prövningar mot traktens vilda djur leder snabbt till utmattning och törst. Att lära sig leva av det landet ger är lika viktigt som att lära sig svinga en yxa. Kaktusar i dalen bär mogna, vattenrika äpplen som lindrar ökensolens hetta."},{t="En delikatess från dalen",b="Galgar sköter matlagningen på träningsplatsen, där han har gjort en konst av att samla föda. Hans Cactus Apple Surprise är känd bland dalens invånare för att svalka en snabbare än ett dopp i flodvatten. Han skickar ivriga rekryter att plocka taggig frukt från närliggande kaktusar, så att hans kök hålls välförsett och nya vandrare inte ger sig ut i Durotar hungriga."}},faq={{q="Vem är Galgar?",a="Galgar är en orch som är stationerad i Valley of Trials i Durotar. Han lagar svalkande förtäring och godsaker som Cactus Apple Surprise åt rekryter i ökenhettan, snarare än att leda formella stridsövningar.",al={"vem är galgar","galgars bakgrund","vem ger uppdraget med cactus apple"}},{q="Vad är Cactus Apple Surprise?",a="Cactus Apple Surprise är en populär lokal sötsak som Galgar gör av färska äpplen från vilda ökenkaktusar. Eleverna uppskattar det uppfriskande tilltugget för snabb lindring och vätska under Durotars skoningslösa sol.",al={"maten cactus apple surprise","vad är överraskningen","galgars recept"}},{q="Var hittar man Cactus Apple?",a="Kaktusäpplen växer i små klasar på marken vid foten av blommande kaktusar, utspridda bland Valley of Trials röda klippor och raviner.",al={"var finns cactus apple","hitta cactus apple","hur får man tag på cactus apple"}},{q="Varför ber Galgar rekryterna samla dem?",a="Det är mycket hett i Valley of Trials, och Galgar kan inte lämna sin post för att själv leta i öknen. Han erbjuder portioner av sin berömda godsak till alla förbipasserande nybörjare som är villiga att samla råvarorna från snåren.",al={"varför samla cactus apple","varför behöver galgar frukterna"}},{q="Har uppdraget koppling till en större berättelse?",a="Nej. Insamlingen låter nya rekryter bekanta sig med att samla lokala resurser medan de genomgår sina första prövningar för Horde.",al={"finns det en uppdragskedja","fortsättning på cactus apple","vad händer efter cactus apple surprise"}},{q="Varför är det viktigt att samla föda i Valley of Trials?",a="Durotar är ett ogästvänligt land av torr klippmark och snår. Hordens ledare anser att kunskaper om att överleva på dess knappa naturresurser förbereder rekryterna på att uthärda den större världens prövningar.",al={"varför samla föda","överlevnad i durotar"}}},fx={e97f8b04={q="Varför vill Galgar att kaktusäpplen samlas in?",a="Den tryckande hettan i Valley of Trials ger ingen ro, och Galgar söker svalka. Han längtar efter sitt signaturrecept, Cactus Apple Surprise, som enligt honom är den bästa godsaken för att svalka sig under Durotars brännande sol. När du samlar in frukten kan han laga en sats som hjälper er att stå ut med hettan och bjuda dig på den svalkande maten.",al={"varför vill galgar ha äpplen","galgar motiv","varför samla kaktusäpplen"}}},fp="30,152,24.355.0,17.311.0,14.212.0,30.211.0,30.145.0,44.206.0,46.121.0,50.185.0"}
P.entries["quest:lazy-peons"] = {n="Lazy Peons",s="Foreman Thazz'ril skickar nya rekryter till Horde genom Valley of Trials för att väcka sovande peons. Deras arbete håller timmerleveranserna till Durotars bosättningar igång.",h="Foreman Thazz'ril skickar nya rekryter till Horde genom Valley of Trials för att väcka sovande peons.",kw={"blackjack","durotar","foreman thazz'ril","lata peons","timmer","peon","valley of trials"},ang={["faction:Horde"]="Som medlem av Horde vet du att varje utpost i Durotar är beroende av timmer som peons har huggit, så det är viktigt för alla att hålla arbetarna sysselsatta.",["race:Orc"]="Som en ung orch på väg in i vuxenlivet lär du dig de hårda realiteterna och den praktiska disciplinen i att bygga en nation ur vildmarken genom att tukta dina fränders arbetare.",["race:Troll"]="Som en Darkspear-troll som tränar tillsammans med dina allierade ser du den råa styrkan och den organisatoriska frustrationen bakom orcisk byggverksamhet."},sec={{t="Slöa i solen",b="Durotars nya hem behöver timmer, sten och hårt arbete. Peons, orcher med liten stridsförmåga, utför en stor del av arbetet och ser till att Horde har arbetskraft. I Valley of Trials får hettan och det slitsamma arbetet Foreman Thazz'rils arbetslag att söka skugga under träden för otillåtna tupplurar."},{t="En snabb väckning",b="Foreman Thazz'ril ger nya rekryter till Horde sin Foreman's Blackjack och skickar dem över dalen för att väcka de sovande arbetarna. De uppskrämda peonsen återgår till att hugga ved och håller timmerflödet igång för Durotars överlevnad."}},faq={{q="Varför somnar peons?",a="Att samla tungt timmer under Durotars stekande sol är utmattande arbete. Peons smiter in under stora träd för att vila när ingen arbetsledare är i närheten.",al={"varför är peons lata","sovande peons","peons som sover på jobbet"}},{q="Vem är Foreman Thazz'ril?",a="Foreman Thazz'ril övervakar arbetslagen i Valley of Trials. De samlar timmer och förnödenheter till Hordes nya byggprojekt.",al={"thazzril","vem ger uppdraget lata peons","thazz'ril"}},{q="Vad är Foreman's Blackjack?",a="Foreman's Blackjack är en tung piska av läder som Thazz'ril använder för att disciplinera arbetare som maskar sig. Ett slag mot huvudet väcker en sovande peon utan att orsaka bestående skador.",al={"blackjack","peonklubba","blackjack-verktyg"}},{q="Vilken roll har peons i Horden?",a="Peons utgör arbetarklassen i det orciska samhället. Trots att de är kraftigt byggda anses de olämpliga för krig och arbetar i stället som byggare, gruvarbetare och skogshuggare åt Hordes bosättningar och krigsmaskin.",al={"peons roll hos orcherna","vad är peons","peonkast"}},{q="Var hittar jag de sovande peons?",a="Du hittar sovande peons överallt i Valley of Trials, norr och söder om The Den. Titta under de vidsträckta trädkronorna där arbetarna söker skugga.",al={"platser med lata peons","var finns lata peons","hitta sovande peons"}},{q="Vad händer när peons har väckts?",a="När du har lämnat tillbaka blackjacken till Foreman Thazz'ril skickar han dig för att hämta hans borttappade gruvhacka i en närliggande grotta.",al={"efter lata peons","vad följer efter lata peons","nästa uppdrag efter peons"}}},fx={a41786ab={q="Varför vill Foreman Thazz'ril att peonerna väcks?",a="Foreman Thazz'ril ansvarar för att hålla Valley of Trials försörjt med timmer, och bygget kräver ständigt arbete. När peonerna slappar och tar sig en tupplur under träden stannar timmerinsamlingen av. Thazz'ril måste få dem att skärpa sig och hugga ved, så att Hordes läger kan hålla sina förråd och befästningar i gott skick.",al={"thazz'rils motiv","varför väcka peonerna","varför slå på peonerna"}},["088600b8"]={q="Vem skickas du efter?",a="Du skickas efter Valley of Trials peoner, de lägst rankade arbetarna i Horde som fått i uppgift att hugga timmer från dalens träd. I stället för att arbeta har många övergett sina yxor för att ta en tupplur i skuggan. De är viktiga för dalens försörjningslinjer, men deras ökända brist på arbetsvilja kräver en sträng påminnelse om att hålla sig på sina poster.",al={"vem ska jag slå","vilka är de lata peonerna","mål för lata peoner"}},["94fa6eb4"]={q="Varför behöver Foreman Thazz'ril att du tillrättavisar peonerna?",a="Foreman Thazz'ril övervakar flera verksamheter i Valley of Trials och kan inte lämna sin post för att leta igenom varje träddunge efter arbetsvägrare. Dalens krigartränare och vakter är upptagna med att träna rekryter eller skydda området mot lokala hot, så det snabbaste sättet att upprätthålla ordningen bland arbetarna är att ge en duglig ung rekryt som du en blackjack.",al={"varför jag och lata peoner","varför slår inte thazz'ril dem","varför inte vakterna"}}},fp="10,153,19.287.0,20.221.0,33.140.0,25.134.0,32.182.0,37.191.0,35.151.0,42.117.1"}
P.entries["quest:sarkoth"] = {n="Sarkoth",s="På en sydlig platå i Valley of Trials har Sarkoth lämnat en ung Darkspear-jägare nära döden. Sårad under ett träd ber Hana'zua en förbipasserande krigare att döda skorpionen och hämta tillbaka dess sönderslagna klo, så att hans sista slag ska betyda något.",h="På en sydlig platå i Valley of Trials har Sarkoth lämnat en ung Darkspear-jägare nära döden.",kw={"darkspear","durotar","hana'zua","sönderslagen klo","sarkoth","skorpion","valley of trials"},ang={["faction:Horde"]="Som medlem av Horde kommer du en fallen kamrat till undsättning i Valley of Trials, där den gemenskapen ger Thralls folk styrka.",["race:Orc"]="Som orc känner du smärtan i att dö utan seger. När du hämnas Hana'zua får du en oprövad spanare att se sin fiende besegrad.",["race:Troll"]="Som Darkspear svarar du på Hana'zuas vädjan som en av hans egna och ser till att en stammedlems hedervärda kamp blir erkänd över Durotars sanddyner."},sec={{t="En fråga om heder",b="I Valley of Trials prövar Horde blivande krigare mot Durotars hårda öken. Under jakten på dalens giftiga varelser mötte den unge trollspanaren Hana'zua en skorpion som var mycket större och dödligare än de andra. Han slog så hårt att han krossade den ena klon, men Sarkoth drev in sin svans i hans bröst. Nu blöder Hana'zua i den röda jorden och fruktar att hans liv snart är slut. Han vill att besten ska dö innan den överlever honom."},{t="Platåns fasa",b="Sarkoth strövar omkring på en hög platå ovanför den södra delen av Valley of Trials. Hana'zuas slag krossade den ena klon, men skorpionen härskar fortfarande över bergsryggen och anfaller alla som klättrar uppför den steniga stigen. Ta tillbaka den ärrade klon till den sårade spanaren, så får han bevis på att hans sista slag försvagade monstret tillräckligt för att någon skulle kunna fälla det."}},faq={{q="Var hittar jag Sarkoth?",a="Sarkoth strövar omkring på den höga platån söder om Hana'zuas gömställe. Följ jordrampen som slingrar sig uppför ravinväggen till bergsryggen.",al={"sarkoths plats","var finns sarkoth","hur tar man sig till sarkoth"}},{q="Vem är Hana'zua?",a="Hana'zua är en ung Darkspear-troll på jaktprov i Valley of Trials. Sarkoth har lemlästat och förgiftat honom, och han ligger under ett träd och ber en förbipasserande äventyrare att hämnas honom innan såren tar hans liv.",al={"hana'zua","döende troll i valley of trials","uppdragsgivare sarkoth"}},{q="Varför vill Hana'zua ha Sarkoths klo?",a="Hana'zua krossade Sarkoths klo med ett kraftfullt slag innan skorpionen stack honom. Om du hämtar tillbaka den sönderslagna klon bevisar det att besten är död och ger Hana'zua stolthet över sin sista strid.",al={"varför sarkoths klo","sönderslagen klo som bevis","hana'zuas heder"}},{q="Dör Hana'zua av giftet?",a="Trots sina svåra sår och bitterheten över det han ser som ett misslyckande finner Hana'zua tillräckligt med hopp när Sarkoth faller för att skicka dig till The Den efter läkarhjälp.",al={"överlever hana'zua","hana'zuas öde","är hana'zua död"}},{q="Vad skiljer Sarkoth från andra skorpioner?",a="Sarkoth är större och mer aggressiv än skorpionarbetarna på den nedre dalbottnen. Den ena klon bär spåren efter Hana'zuas slag.",al={"sarkoths skillnader","varför är sarkoth speciell","skorpionboss i durotar"}},{q="Vad ska jag göra efter att ha dödat Sarkoth?",a="När du har tagit Sarkoths klo till Hana'zua uppmanar han dig att skynda till The Den, berätta för lägrets ledare om hans situation och hämta hjälp innan giftet blir dödligt.",al={"uppdrag efter sarkoth","nästa steg hana'zua","uppdrag tillbaka till the den"}}},fx={["2909716d"]={q="Varför vill Hana'zua se Sarkoth död?",a="Hana'zua tror att livet håller på att rinna ur honom under skorpionens gift, och han vägrar att dö i vanära. Hans far brukade säga att det aldrig skulle bli något av honom, och att dö ensam i smutsen utan att ha besegrat sin motståndare skulle bevisa att de bittra orden var sanna. Att hämnas sitt nederlag är hans sista chans att försvara sin krigarheder och se till att hans sista fiende inte överlever honom.",al={"varför döda sarkoth","hana'zuas motiv","varför vill hana'zua se sarkoth död"}},["3ecf0257"]={q="Varför kan inte Hana'zua döda Sarkoth själv?",a="Hana'zua är svårt skadad och förblöder under ett träd. I deras strid på den södra platån lyckades han träffa Sarkoths klo, men besten stötte sin gadd djupt in i hans bröst. Förgiftad och alltför svag för att stå eller ta sig tillbaka till The Den efter hjälp är han helt beroende av att du avslutar jakten innan livet rinner ur honom.",al={"varför behöver hana'zua mig","varför kan hana'zua inte strida","varför jag och sarkoth"}}},fp="7,246,17.407.0,18.315.0,25.126.0,16.214.0,38.169.0,33.144.1,49.133.0,49.159.1"}
P.entries["quest:your-place-in-the-world"] = {n="Your Place In The World",s="I Valley of Trials tar oprövade rekryter sina första steg mot heder och överlevnad i Durotar. Kaltunk skickar dem direkt till Gornek för grundläggande stridsträning, där deras tjänst för Horde börjar.",h="I Valley of Trials tar oprövade rekryter sina första steg mot heder och överlevnad i Durotar.",kw={"cutting teeth","durotar","gornek","horde","kaltunk","rekryter","valley of trials","warchief"},ang={["faction:Horde"]="Varje ung rekryt i Horde i Durotar måste bevisa att hen har modet att försvara sin unga nation innan hen griper till vapen i Warchiefs namn.",["race:Orc"]="För orcher är det en kulturell milstolpe att bli vuxen och inställa sig till tjänst i Valley of Trials, med fokus på personlig heder och stridsberedskap.",["race:Troll"]="Darkspear Trolls slog sig ned i Durotar tillsammans med sina orciska allierade. Här tränar de med sina fränder för att skapa enighet och trygga varandras överlevnad."},sec={{t="Coming of Age i Durotar",b="I Durotars torra Valley of Trials bevisar unga orcher och Darkspear Trolls sitt värde innan de ger sig ut i den större världen. Under Warchief Thrall kräver livet styrka, vaksamhet och disciplin. Kaltunk bedömer varje ivrig rekryt och dämpar drömmar om att brottas med demoner och drakar med de praktiska uppgifter som väntar. Träningen börjar i ravinen, där rekryterna lär sig ödmjukhet innan de kan vinna ära."},{t="Rapportera till Gornek",b="Gornek väntar vid lägerelden, bara några steg från Kaltunk. Den barske veteranen betraktar nyanlända med skeptisk blick och muttrar ofta över de klena rekryter som kommer till lägret. Hans uppgift är att härda de unga kämparna genom prövningar, med skadedjuren som hotar lägrets förråd som första utmaning."}},faq={{q="Vad är syftet med uppdraget?",a="Den här riten markerar en ung rekryts inträde i Hordes tjänst i Valley of Trials. Du går direkt till Gornek, som inleder din grundläggande stridsträning och ger dig dina första uppgifter.",al={"varför göra uppdraget","första horde-uppdraget","vad är din plats i världen"}},{q="Vem är Kaltunk?",a="Kaltunk är en orcisk uppsyningsman vid ingången till Valley of Trials. Han bedömer rekryter som nått vuxen ålder och hänvisar dem till rätt tränare och ledare i lägret.",al={"kaltunks roll","vem ger uppdraget"}},{q="Vem är Gornek?",a="Gornek är en erfaren tränare för Horde, som sitter nära lägerelden i Valley of Trials. Han prövar nyanlända rekryter och härdar dem till dugliga soldater innan de lämnar ravinen.",al={"gorneks roll","var finns gornek"}},{q="Vart leder uppdraget härnäst?",a="När du rapporterar till Gornek får du genast uppdraget \"Cutting Teeth\". Rekryterna ger sig ut i terrängen för att gallra bland fläckiga vildsvin och bevisa sin grundläggande stridsförmåga.",al={"vilket uppdrag kommer härnäst","nästa efter your place in the world"}},{q="Varför hålls rekryterna i Valley of Trials?",a="Valley of Trials är en avskild, skyddad ravin i Durotar där rekryter tränas, bedöms och sållas bort innan de möter områdets farligare bestar, quilboar och fiendens spejare.",al={"varför valley of trials","varför börja här"}},{q="Skiljer sig uppdraget mellan orcher och troll?",a="Unga orcher och Darkspear Trolls börjar träna tillsammans i Valley of Trials och får samma uppmaning till strid av Kaltunk.",al={"introduktionsuppdrag för troll","introduktionsuppdrag för orcher"}}},fx={["4ca14302"]={q="Varför skickar Kaltunk dig till Gornek?",a="Du har äntligen blivit gammal nog att strida för Horde och vinna ära åt Warchief Thrall. Kaltunk ser potential i dig, men vet att ivriga rekryter ofta drömmer om att dräpa drakar innan de lärt sig grunderna. Han skickar dig till Gornek så att du kan prövas med uppgifter som passar en nybörjare och överleva länge nog för att bli en verklig tillgång för Valley.",al={"varför vill kaltunk att detta görs","kaltunks motiv","varför skickar kaltunk dig"}}},fp="23,199,24.374.0,19.281.0,34.179.0,15.157.0,14.184.0,32.158.0,46.198.0,47.122.0"}
P.entries["subzone:addle-s-stead"] = {n="Addle's Stead",s="Addle's Stead är en övergiven gård i sydvästra Duskwood, tyst under skogens dunkel söder om Raven Hill. De första nybyggarna flydde för länge sedan, och gården har blivit en dold samlingsplats för Defias Brotherhood.",h="Addle's Stead är en övergiven gård i sydvästra Duskwood, tyst under skogens dunkel söder om Raven Hill.",kw={"addle's stead","defias","defias brotherhood","duskwood","raven hill"},ang={["class:Rogue"]="Den hemliga utposten visar hur djupt Defias syndikat obemärkt tar sig över territoriella gränser och placerar sina agenter bakom Duskwoods dunkla slöja.",["faction:Alliance"]="För utredare från Alliansen som letar efter den försvunne kung Varian Wrynn rymmer det förfallna boningshuset viktiga konspirationsakter som Defias Brotherhood lämnat efter sig."},sec={{t="En utpost i mörkret",b="Liksom många bortglömda gårdar runt om i Duskwood förföll Addle's Stead när mörker och förfall slukade trakten. Gården lämnades inte tom, utan togs i bruk av Defias Brotherhood. Agenter patrullerar utkanterna, smyger omkring i det förfallna boningshuset och gömmer förnödenheter i ladan. De använder det skuggiga sydvästra Duskwood för att undgå både Night Watch och myndigheterna i Stormwind."},{t="Inblandad i kungens försvinnande",b="Defias närvaro här handlar om mer än vanligt banditliv. Addle's Stead fungerar som ett operativt gömställe med känsliga handlingar åt brödraskapet. Viktiga dokument och akter som knyter regionala konspiratörer till kung Varian Wrynns försvinnande kan spåras till just den här markbiten. Den oansenliga, förfallna gården blir därmed en viktig ledtråd när förräderiet inom Alliansen nystas upp."}},faq={{q="Var ligger Addle's Stead?",a="Addle's Stead ligger i sydvästra Duskwood, strax söder om byn Raven Hill och rakt väster om Vul'Gol Ogre Mound.",al={"addle's steads läge","var ligger addle's stead","hitta addle's stead"}},{q="Vem kontrollerar Addle's Stead just nu?",a="Gården är full av Defias Brotherhood, däribland nattspringare, nattklingor och besvärjare som använder det gamla huset och ladan som ett avlägset gömställe.",al={"vem finns vid addle's stead","fiender vid addle's stead","addle's steads fiender"}},{q="Varför är gården övergiven?",a="Liksom mycket annat i Duskwood övergav de ursprungliga invånarna gården när skogen föll under en genomgripande förbannelse av mörker, bestar och odöda som drev bort vanligt folk.",al={"vad hände med gården","vem var addle","varför är addle's stead förstört"}},{q="Varför kommer äventyrare från Alliansen till Addle's Stead?",a="Äventyrare från Alliansen som följer ett spår av ledtrådar genom Duskwood skickas ibland till Addle's Stead för att leta efter en viktig akt i Defias gömställe.",al={"varför ta sig till addle's stead","uppdrag vid addle's stead","försvunne kungen i duskwood"}}},fx={["84087cc5"]={q="Vad är Addle's Stead?",a="Addle's Stead är en övergiven gård i sydvästra Duskwood, söder om Raven Hill och strax väster om Vul'Gol Ogre Mound. Liksom många gårdar i trakten slukades den av det växande mörkret och övergavs av sina ursprungliga ägare. Kvar finns dess igenvuxna åkrar och förfallna bondgård.",al={"vad är addle's stead","addle's stead","om addle's stead"}},c80be076={q="Vad hände vid Addle's Stead?",a="Gården var en gång ett fridfullt hem, men förföll när mörka förbannelser drabbade Duskwood och drev bort invånarna. Så småningom flyttade agenter från Defias Brotherhood in och tog ladan och bondgården i anspråk som utpost.",al={"addle's steads historia","vad hände här"}},["67874313"]={q="Är Addle's Stead farligt?",a="Mycket. Den övergivna gården patrulleras av fientliga agenter från Defias, däribland smygande Night Runners, dödliga Night Blades och besvärjare som lurar nära bondgården.",al={"hur farligt är addle's stead","är addle's stead tryggt","hot vid addle's stead"}}},fp="13,182,21.277.0,35.297.1,31.122.0,37.138.0,26.124.0,50.136.1"}
P.entries["subzone:agama-gor"] = {n="Agama'gor",s="Agama'gor ligger norr om vägen från Camp Taurajo mot Mulgore. Bristleback-kilborrar håller till i lägret i södra Barrens och pressar den närliggande utposten för Horden.",h="Agama'gor ligger norr om vägen från Camp Taurajo mot Mulgore.",kw={"agama'gor","the barrens","blood shards","bristleback","camp taurajo","mangletooth","quilboar","kilborrar"},ang={["faction:Horde"]="När Hordens försvarare passerar genom Camp Taurajo hjälper det till att skydda utposten att hålla Bristleback-folket i Agama'gor i schack. Deras krigare är fortfarande en prioritet.",["race:Tauren"]="Som tauren möter du fara från Agama'gors rövare längs stigen till Great Gate och Mulgore. De hotar försörjningslinjerna och pilgrimerna."},sec={{t="Ett Bristleback-fäste",b="Agama'gor är ett fäste för Bristleback-kilborrar i södra Barrens. Deras hyddor, snår och grovhuggna totempålar ligger nära Camp Taurajo. Kilborrarna hotar resande mellan Barrens och Mulgore kullar med gräs, och spejare och jägare från Horden kämpar för att hålla dem i schack."},{t="Blood Shards och exil",b="Bristleback-kilborrar i Agama'gor bär på röda kristaller som kallas Blood Shards. Mangletooth, en landsförvisad kilborre som hålls fången i Camp Taurajo, söker efter kristallerna på grund av uråldriga föreställningar om Agamaggan heliga väsen. Hordens äventyrare plundrar lägret på kristaller och byter dem med Mangletooth mot stamamuletter."}},faq={{q="Vad är Agama'gor?",a="Agama'gor är en stor bosättning för Bristleback-kilborrar i södra Barrens, precis norr om vägen västerut från Camp Taurajo mot Mulgore.",al={"översikt över agama'gor","vad är det här för quilboarplats","quilboarläger nära taurajo"}},{q="Varför är quilboarerna från Bristleback så fientliga här?",a="Kilborrar tror att all mark som berörts av den fallne urguden Agamaggan tillhör dem. Bristleback-folket ser de närliggande taurerna och orcherna från Camp Taurajo som inkräktare på sina förfäders mark.",al={"varför anfaller quilboar","quilboarernas fientlighet","varför är bristleback arga"}},{q="Vad kan du hitta i Agama'gor?",a="Bristleback-kilborrar i Agama'gor bär på Blood Shards, kristalliserade avlagringar av urkraft. Du kan byta dem med Mangletooth, en landsförvisad kilborre i Camp Taurajo.",al={"vad kan man hitta här","föremål från agama'gor","varför döda bristleback här"}},{q="Vem är Mangletooth, och hur hör han ihop med platsen?",a="Mangletooth är en landsförvisad kilborre som hålls i en bur i Camp Taurajo. Han hyser agg mot sitt folk och erbjuder Hordens äventyrare skyddsamuletter i utbyte mot Blood Shards från Bristleback-folket i Agama'gor.",al={"mangletooths koppling","vem är mangletooth","grisfånge i taurajo"}}},fx={["62d1d1e5"]={q="Vilka bor i Agama'gor?",a="Agama'gor bebos av quilboar från Bristleback. De har gjort området norr om Camp Taurajo till en befäst boplats och försvarar ursinnigt sin mark mot alla främlingar som närmar sig deras taggar och boningar.",al={"vilka bor i agama'gor","invånare i agama'gor","vilka finns i agama'gor"}},def0ef2e={q="Är Agama'gor farligt?",a="Ja. Agama'gor kryllar av fientliga quilboar från Bristleback som anfaller resenärer så fort de får syn på dem. Eftersom området ligger nära vägen västerut från Camp Taurajo kan det vara livsfarligt att lämna den upptrampade stigen om man inte är beredd på svärmar av quilboarförsvarare.",al={"hur farligt är agama'gor","är agama'gor tryggt","faran i agama'gor"}}},fp="9,162,24.235.0,22.313.0,18.138.0,49.192.0,31.163.0,56.190.0"}
P.entries["subzone:agamand-family-crypt"] = {n="Agamand Family Crypt",s="Inbäddad bland kullarna strax norr om Agamand Mills ligger Agamand Family Crypt, den uråldriga gravplatsen för en av Tirisfals rikaste jordbrukarsläkter. Nu har Scourge under Captain Dargol tagit över den, gravarna har slitits upp och de slumrande förfäderna har väckts till liv som viljelösa fasor.",h="Inbäddad bland kullarna strax norr om Agamand Mills ligger Agamand Family Crypt, den uråldriga gravplatsen...",kw={"agamand family crypt","agamand mills","captain dargol","krypta","mausoleum","scourge","skelett","tirisfal glades"},ang={["race:Undead"]="För Forsaken är Captain Dargols ockupation av kryptan en outhärdlig närvaro från Scourge i Tirisfal. Den hånar de döda och hotar Undercitys norra gräns."},sec={{t="Rastlösa förfäder",b="Före tredje kriget ägde familjen Agamand vidsträckta marker över norra Tirisfal Glades och begravde sina förfäder i detta mausoleum på sluttningen. När pesten ödelade kungariket hamnade kryptan i händerna på Captain Dargol, en agent för Scourge. I stället för att låta den förmögna släkten vila i frid använde Dargol mörk nekromanti för att väcka de begravda skeletten och hämndlystna vålnaderna. Därmed förvandlade han en helig begravningsplats till ett aggressivt fäste för Scourge, precis vid gränsen till Forsaken-territorium."}},faq={{q="Var ligger Agamand Family Crypt?",a="Kryptan är uthuggen i sluttningen strax norr om Agamand Mills, i de norra delarna av Tirisfal Glades.",al={"agamand crypts läge","var ligger kryptan","hur hittar man agamand crypt"}},{q="Vem kontrollerar kryptan just nu?",a="Graven hålls av Captain Dargol, en tjänare till Scourge som styr den mörka magin där inne och befaller de uppväckta döda.",al={"vem finns i agamand crypt","kryptans boss","captain dargol"}},{q="Vad möter jag inne i kryptan?",a="Kryptan är full av väckta skelett och rastlösa andar från familjen Agamands förfäder. Drivna av mörk magi går dessa hämndlystna odöda till angrepp mot alla som kliver in i gravarna.",al={"kryptans fiender","vad finns i agamand crypt","varelser i agamand crypt"}},{q="Är de odöda inne i kryptan allierade med Forsaken?",a="Nej. Varelserna där inne är trälar under Scourge och lyder Captain Dargol. Därför är de fientliga mot både Forsaken och levande resenärer.",al={"är de forsaken","är agamand crypt vänlig","varför anfaller odöda"}}},fx={["1e347eab"]={q="Vad är Agamand Family Crypt?",a="Agamand Family Crypt är Agamandsläktens förfäders gravvalv, strax norr om deras vidsträckta kvarnar i Tirisfal Glades. Det var en gång en stillsam viloplats för den adliga familjen, men har fallit i mörker sedan Scourge erövrade Lordaeron.",al={"vad är agamand family crypt","information om agamand family crypt","vad är det här för krypta"}},["2b90d8b5"]={q="Vad hände vid Agamand Family Crypt?",a="När Scourge svepte genom norra Lordaeron krossades Agamandgodset och dess gravplatser skändades. En tjänare till Lich King vid namn Captain Dargol tog över kryptan och använde nekromanti för att väcka Agamandsläktens lik och förfädersandar till tanklös, hämndlysten tjänst.",al={"agamand family crypts historia","vad hände med agamand family crypt"}},["1ce0db9b"]={q="Är Agamand Family Crypt farlig?",a="Ja, den är ytterst farlig. De dammiga salarna kryllar av uppväckta odöda och hämndlystna vålnader som förvridits av nekromantisk magi. Dessa andar och vandrande lik styrs av Captain Dargol och går våldsamt till angrepp mot alla som oförsiktigt tränger in i graven utan tillstånd.",al={"är agamand family crypt farlig","faran i agamand family crypt","hur farlig är agamand family crypt"}},["02ac6c6f"]={q="Varför kallas den Agamand Family Crypt?",a="Den har fått sitt namn efter Agamands, en framstående människosläkt i Lordaeron som ägde och drev närbelägna Agamand Mills. Valvet byggdes för att rymma kvarlevorna efter flera generationer av deras förfäder innan kungariket föll.",al={"varför kallas den agamand family crypt","ursprunget till namnet agamand family crypt","vilka är agamands"}}},fp="20,213,18.401.0,42.93.0,33.79.0,39.142.0,57.107.0"}
P.entries["subzone:agamand-mills"] = {n="Agamand Mills",s="Agamand Mills är ett vidsträckt gårds- och väderkvarnskomplex bland de norra höjderna i Tirisfal Glades. Det var en gång den välbärgade Agamand-dynastins stolta gods, men har förfallit och är nu regionens största fäste för Scourge.",h="Agamand Mills är ett vidsträckt gårds- och väderkvarnskomplex bland de norra höjderna i Tirisfal Glades.",kw={"agamand","agamand family crypt","agamand mills","captain dargol","devlin agamand","gregor agamand","scourge","tirisfal glades"},ang={["race:Undead"]="För Forsaken handlar återerövringen av Agamand Mills inte bara om taktik, utan också om personlig hämnd mot Scourge och om att göra upp med det förflutna, som den före detta godstjänaren Coleman Farthing."},sec={{t="En splittrad familj",b="Den välbärgade familjen Agamand byggde sitt gods kring ett omfattande nätverk av kvarnar i norra Tirisfal. När det tredje kriget bröt ut och Scourge svepte över Lordaeron vägrade patriarken Gregor Agamand att fly. Han befäste gården och övertalade sina tjänare och arbetare att stanna och kämpa. Deras förråd och stenmurar kunde kanske ha stått emot, men den yngste sonen, Devlin Agamand, förrådde sin släkt. Devlin massakrerade godsets vakter och släppte in de vandrande döda i sovsalarna. Försvagade inifrån blev de återstående försvararna utplånade, och familjen anslöt sig till de odödas själlösa skaror."},{t="En härd av förruttnelse",b="I dag är Agamand Mills Scourges mest befästa bastion i Tirisfal Glades och utgör ett omedelbart hot mot Forsaken-riket. De ruttnande väderkvarnarna mal nu ovanför angripna fält med vålnader, zombier och skelettbestar. Under godset leder Captain Dargol garnisonen från den djupa Agamand Family Crypt och utövar nekromanti för att återuppliva generationer av Agamand-anfäder. Från Brill bedriver Magistrate Sevren och Deathguards en aktiv kampanj för att rensa kvarnarna och driva bort Scourge innan styrkorna kan marschera mot Undercity."}},faq={{q="Varför är Agamand Mills översvämmat av Scourge?",a="När Scourge härjade i Lordaeron befäste familjen Agamand sitt gods och försökte hålla stånd mot den odöda horden. Men den yngste sonen, Devlin Agamand, förrådde sin familj och öppnade portarna för Scourge, vilket ledde till att alla där inne massakrerades och återupplivades.",al={"vad hände med agamand mills","varför finns det odöda vid kvarnarna","agamand mills historia"}},{q="Vem kontrollerar kvarnarna just nu?",a="Godset fungerar som en regional utpost för Scourge, under ledning av Captain Dargol. Dargol håller till djupt inne i den befästa Agamand Family Crypt, där han använder svart magi för att resa förfädernas lik som nya soldater.",al={"vem leder agamand mills","scourge-ledare i tirisfal","vem styr kvarnarna"}},{q="Varför bryr sig Forsaken om den här platsen?",a="Kvarnarna hyser den största koncentrationen av själlösa Scourge-styrkor som finns kvar i Tirisfal Glades. Om de lämnas ostörda hotar Captain Dargols styrka Brill och kan skära av vägarna söderut mot Undercity.",al={"varför angriper brill agamand","forsakens intresse för agamand mills"}},{q="Vilka var familjen Agamand?",a="De var en välbärgad människofamilj från Lordaeron som ägde kvarnarna och den omgivande jordbruksmarken i norra Tirisfal. I dag vandrar deras återupplivade ättlingar, däribland Gregor, Nissa, Thurman och Devlin, omkring på ägorna som själlösa slavar.",al={"vilka är familjen agamand","agamand-släkten","gregor agamand"}}},fx={["9a335608"]={q="Vad är Agamand Mills?",a="Agamand Mills är ett vidsträckt nätverk av väderkvarnar och jordbruksmarker i höglandet i norra Tirisfal Glades. Innan pesten svepte genom Lordaeron var det ett välmående jordbruksgods som ägdes av den rika adelsfamiljen Agamand. I dag ligger godset i förfall och fungerar som den största kvarvarande befästningen för Scourge i regionen.",al={"agamand mills berättelse","vad var agamand mills","vad är det här för plats"}},ef38e774={q="Vad hände vid Agamand Mills?",a="När Scourge svepte in i Tirisfal valde Gregor Agamand att befästa kvarnarna och övertala sin familj och sina arbetare att göra motstånd. Försvaret var starkt och välförsett tills deras yngste son, Devlin, förrådde dem och gick över till fienden. Devlin dödade vaktposterna och släppte in en odöd anfallsstyrka i lägret, där den slaktade en tredjedel av försvararna medan de sov. De överlevande övermannades av följande angrepp, dukade under för pesten och återuppstod som Lich Kings tanklösa hantlangare.",al={"agamand mills fall","agamand mills historia","hur föll agamand mills"}},["513094d3"]={q="Är Agamand Mills farligt?",a="Det är ytterst farligt. Godset kryllar av återupplivade lantarbetare, skelettvakter och de uppståndna medlemmarna av själva Agamandfamiljen. Djupt inne i familjekryptan använder Scourge-befälhavaren Captain Dargol mörk nekromanti för att väcka sedan länge döda förfäder. På så sätt blir kvarnarna en beväpnad utpost riktad rakt mot Forsaken i Tirisfal.",al={"är agamand mills tryggt","hur farligt är agamand mills","hot vid agamand mills"}},["4d06011e"]={q="Varför heter det Agamand Mills?",a="Godset har fått sitt namn efter Agamands, en rik människosläkt i Lordaeron som ägde kvarnarna och den omgivande jordbruksmarken. Godset bar deras namn fram till deras tragiska undergång.",al={"varför heter det agamand","ursprunget till namnet agamand mills","vem gav agamand mills dess namn"}}},fp="13,166,15.570.0,16.500.0,42.291.0,33.157.0,42.197.0,27.235.0"}
P.entries["subzone:agmond-s-end"] = {n="Agmond's End",s="Agmond's End är en övergiven dvärgisk utgrävningsplats bland de södra kullarna i Badlands. Den var en gång en hoppfull undersökning ledd av prospektören Agmond, men lägret förvandlades till ett slakthus när grävande troggar översvämmade platsen och dödade dess ledare.",h="Agmond's End är en övergiven dvärgisk utgrävningsplats bland de södra kullarna i Badlands.",kw={"agmond","agmond's end","badlands","utgrävningsplats","prospektör","theldurin the lost","trogg"},ang={["race:Dwarf"]="Lägret är en allvarlig påminnelse om farorna med att gräva upp forntida jord utan tillräckligt militärt stöd."},sec={{t="En fasansfull utgrävning",b="Liksom många platser i det torra Badlands började Agmond's End som ett dvärgprojekt för att finna forntida reliker och utforska jordens begravda historia. Drömmen fick ett abrupt slut när vilda troggar vällde fram ur de omgivande sprickorna och övermannade gruvarbetarna. Agmond själv fälldes under anfallet, vilket gav platsen dess dystra namn. I dag är den förstörda utgrävningen fortfarande helt översvämmad av Stonevault-troggar, och krossade lådor och övergivna verktyg ligger kvar precis där de föll."},{t="En ensam granne",b="Nära den förstörda utgrävningen ligger ett ensligt läger där Theldurin the Lost bor, en dvärg vars förstånd sedan länge har börjat svikta. Han är fortfarande en av få själar som vågar sig ut i den södra öknen nära den dödsdömda platsen."}},faq={{q="Vem var Agmond?",a="Agmond var en dvärgisk prospektör som ledde en utgrävning i södra Badlands. Hans undersökning slutade i katastrof när underjordiska troggar dök upp och slaktade honom och hans expedition.",al={"vem är agmond","agmonds historia"}},{q="Vilka varelser bor i Agmond's End?",a="Den förstörda utgrävningsplatsen är helt övertagen av fientliga troggar som slaktade dvärggruvarbetarna och lade beslag på det förstörda lägret och de omgivande klipporna.",al={"fiender vid agmond's end","vem bor här"}},{q="Vem bor nära Agmond's End?",a="En eremit till dvärg, känd som Theldurin the Lost, håller till i ett läger i närheten bland de södra kullarna och vakar försiktigt över det karga landskapet.",al={"npc i närheten","theldurins plats"}},{q="Varför grävde dvärgarna här från början?",a="Dvärgiska prospektörer undersöker ofta Badlands på jakt efter titanartefakter, forntida ruiner och rika mineralådror, men många sådana expeditioner underskattar de vilda varelser som lurar under jord.",al={"varför dvärgisk utgrävning","utgrävningens syfte"}}},fp="12,168,21.312.0,17.209.0,15.146.0,36.124.0,28.127.0,49.163.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Aku'mai's Lair",s="Aku'mai's Lair är den djupaste och mörkaste grottan i Blackfathom Deeps. Bortom Moonshrine Sanctum ligger denna översvämmade håla, där Aku'mai, en monstruös hydra vördad som tjänare åt Old Gods, har sitt bo.",h="Aku'mai's Lair är den djupaste och mörkaste grottan i Blackfathom Deeps.",kw={"aku'mai's lair","aku'mai","blackfathom deeps","hydra","moonshrine sanctum","naga","old gods","twilight's hammer"},ang={["class:Druid"]="Den vidriga förvandlingen och onaturliga korruptionen som strålar ut från Aku'mais vattniga tillhåll är en svår plåga för Kalimdors naturliga vattendrag och bestar.",["race:NightElf"]="För nattalverna är det en outhärdlig skändning av Ashenvales heliga jord att se ett vanhelgat Elune-tempel förvandlas till ett smutsigt bo åt en avkomma från en vidrig Old God."},sec={{t="Djupens hjärta",b="Aku'mai's Lair är förseglad bakom Moonshrine Sanctum och utgör slutpunkten för den korruption som sveper genom Blackfathom Deeps. För att komma in i grottan måste mörka ritualer utföras genom att tända de fyra fyrfaten intill en naga-staty. Då väcks väktare som svurit att försvara tröskeln. Bortom de tunga dubbeldörrarna ligger en sollös, översvämmad grotta. Här samlas både Twilight's Hammer-kultister och invaderande naga för att vörda Aku'mai, en uråldrig hydra med tre huvuden som anses vara en levande tjänare åt Old Gods."},{t="Undergångens förebud",b="Aku'mais närvaro i hålan gör den till en brännpunkt för Twilight's Hammers apokalyptiska planer. Kultisterna vördar det stora odjuret som ett förebud om en utlovad mörkrets tidsålder. De tror att dess framträdande och fortsatta näring ska varsla om att de underjordiska fängelserna där deras uråldriga gudar hålls fångna bryts upp. Den underjordiska dammen, som får näring av offergåvor och vaktas nitiskt med mörk magi, är en kuslig symbol för den uråldriga ondska som klöser sig tillbaka in i Kalimdor."}},faq={{q="Var ligger Aku'mai's Lair?",a="Aku'mai's Lair ligger längst in i grottkomplexet Blackfathom Deeps i Ashenvale, strax bortom de förseglade dörrarna till Moonshrine Sanctum.",al={"var ligger aku'mais lya","hur tar man sig till aku'mais rum","aku'mais lya plats"}},{q="Hur öppnar man dörrarna till Aku'mai's Lair?",a="Dubbeldörrarna in till hålan öppnas genom att tända de fyra rituella fyrfaten runt naga-statyn i Moonshrine Sanctum och besegra vågorna av varelser som tillkallas för att skydda dem.",al={"öppna aku'mais dörr","hur låser man upp aku'mais lya","tända eldar för aku'mai"}},{q="Vad finns i grottan?",a="I grottan bor Aku'mai, en väldig hydra med tre huvuden, besmittad av uråldriga mörka krafter och tjänare åt Old Gods.",al={"vem finns i aku'mais lya","vad lever i aku'mais lya","boss i aku'mais lya"}},{q="Varför tillber Twilight's Hammer här?",a="Twilight's Hammer vördar Aku'mai som en tjänare åt Old Gods, och kultisterna tror att om de stärker odjuret kan de återställa den tid då Old Gods härskade över världen.",al={"varför tillber kultister aku'mai","twilight's hammer aku'mais lya","varför är twilight's hammer här"}}},fx={d1c19121={q="Vad är Aku'mai's Lair?",a="Aku'mai's Lair är den djupaste och mörkaste grottan i de översvämmade ruinerna av Blackfathom Deeps. Den var en gång en del av ett forntida nattalvstempel helgat åt Elune, men denna vattenfyllda håla är nu ett heligt rum för en monstruös trehövdad hydra, en varelse genomsyrad av de gamla gudarnas illvilliga inflytande.",al={"vad är aku'mai's lair","information om aku'mai's lair","om aku'mai's lair"}},b75b148a={q="Vad förvandlade den här platsen till Aku'mai's Lair?",a="Efter den forntida Sundringen sjönk Blackfathomtemplet under vattenytan och föll i glömska. Under århundradena sipprade fördärv in i dess översvämmade inre. Det gjorde att den fruktansvärda hydran Aku'mai kunde ta de dränkta kamrarna i besittning som sitt bo, medan mörka kultister och naga samlades för att dyrka den.",al={"aku'mai's lairs historia","vad hände vid aku'mai's lair","hur bildades aku'mai's lair"}},["7d86eb37"]={q="Är Aku'mai's Lair farligt?",a="Det är oerhört farligt. Bortom raden av fanatiker och naga som vaktar Moonshrine Sanctum finns en kolossal tjänare åt de gamla gudarna i själva hålan. Aku'mai angriper med frätande andedräkt, krossande vrede och uråldrig ondska som kan slita sönder oförberedda äventyrare.",al={"är aku'mai's lair farligt","hur farligt är aku'mai's lair","faran i aku'mai's lair"}},["39ca825a"]={q="Varför kallas den här grottan Aku'mai's Lair?",a="Grottan har fått sitt namn efter sin monstruösa invånare, Aku'mai. Den väldiga, korrumperade hydran har bott här så länge att den gjort hålan till sin egen häckningsplats, vördad av Twilight's Hammer och de naga som väntar på dess mörka uppvaknande.",al={"varför heter det aku'mai's lair","betydelsen av namnet aku'mai's lair","vem namngav aku'mai's lair"}}},fp="14,187,19.366.0,17.399.0,32.135.0,44.178.0,31.128.0,50.166.0"}
P.entries["subzone:aldrassil"] = {n="Aldrassil",s="Aldrassil är det väldiga gren-trädet och samhället mitt i Shadowglen i nordöstra Teldrassil. Dess uthuggna håligheter är en tillflykt och träningsplats för unga kaldorei, och rymmer tränare, handelsmän och lokala ledare.",h="Aldrassil är det väldiga gren-trädet och samhället mitt i Shadowglen i nordöstra Teldrassil.",kw={"aldrassil","stort träd","kaldorei","night elf-start","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="Aldrassil visar kaldoreis fallenhet för levande arkitektur, formad av levande trä utan att skogens balans rubbas.",["race:NightElf"]="För många unga kaldorei är Aldrassils uthuggna håligheter och ramper deras första minne av samhällsliv och grunden för deras tidiga träning."},sec={{t="Shadowglens hjärta",b="Högt över den avskilda dalen Shadowglen fungerar Aldrassil som både skydd och samlingsplats för unga Night Elf som tar sina första steg ut i världen. Bebyggelsen är uppförd i och kring den väldiga stammen från detta uråldriga träd. Slingrande ramper passerar klassinstruktörer och hantverkare på vägen upp till det höga nästet, där Tenaron Stormgrip vakar över gläntans skydd. Medan världsträdet Teldrassil sträcker sig över horisonten erbjuder Aldrassil ett tryggt och stadigt krontak där noviser lär sig sina färdigheter innan de ger sig ner i Kalimdors oroliga vildmark."}},faq={{q="Vad är Aldrassil?",a="Aldrassil är det väldiga, urholkade trädet och samhället mitt i Shadowglen i nordöstra Teldrassil. Det är en första trygg plats där unga Night Elf samlas för att få träning, utrustning och vägledning.",al={"aldrassils träd","vad är aldrassil","shadowglens stora träd"}},{q="Vem leder samhället i Aldrassil?",a="Tenaron Stormgrip vakar över Shadowglen från sitt näste högst upp i Aldrassil, samordnar dalens försvar och vägleder nyvaknade kaldorei.",al={"vem leder aldrassil","aldrassils ledare","tenaron stormgrips plats"}},{q="Vilka tjänster finns här?",a="I trädet finns klassinstruktörer för unga Night Elf-krigare, lönnmördare, druider, jägare och präster, liksom lokala handelsmän med förnödenheter, rustningsmakare och uppdragsgivare som tar hand om gläntans omedelbara behov.",al={"tränare i aldrassil","handelsmän i aldrassil","vad finns i aldrassil"}}},fx={f93f81e4={q="Vilka bor i Aldrassil?",a="Aldrassil är hem för nattalvernas väktare, tränare och vårdare som vakar över Shadowglen. Präster åt Elune, druider, skurkar och krigare har sina kvarter i den uthuggna stammen och på plattformarna runtomkring, medan Tenaron Stormgrip, ledaren för gläntan, bor högt uppe bland grenarna.",al={"vilka bor här","invånare i aldrassil","befolkning i aldrassil"}},["1582ff91"]={q="Är Aldrassil farligt?",a="Själva trädet är en trygg fristad och Shadowglens livliga hjärta, skyddat av vaksamma nattalvssentineler. Men grenarna runtomkring och skogen hotas allt mer av närgångna grell, sjuka nattsablar och korrumperade skogsdjur som lurar strax utanför dess skugga.",al={"är aldrassil tryggt","faran i aldrassil","faror vid aldrassil"}}},fp="9,138,19.378.0,18.177.0,38.140.0,32.158.0"}
P.entries["subzone:alexston-farmstead"] = {n="Alexston Farmstead",s="På Alexston Farmstead stryker vilda Harvest Watchers omkring på de ödelagda fälten. Baros Alexston växte upp här innan han blev stadsarkitekt i Stormwind.",h="På Alexston Farmstead stryker vilda Harvest Watchers omkring på de ödelagda fälten.",kw={"alexston","arkitekt","baros","kompass","gård","harvest watcher","westfall"},ang={["faction:Alliance"]="För Alliansen påminner gården om Stormwinds främsta tänkare och deras enkla, arbetsamma början, samt om kampen för att skydda dess gränser."},sec={{t="Ett övergivet hem",b="Alexston Farmstead ligger på Westfalls torra slätter, övergivet liksom de närliggande gårdarna. Gårdsfolket flydde när banditväsendet spred sig över landsbygden. Nu har fälten vuxit igen, och Harvest Watchers som lämnades att sköta grödorna anfaller alla som närmar sig det karga boningshuset."},{t="Enkla rötter",b="Baros Alexston arbetade på fälten här i sin ungdom innan han gav sig av för att ägna sig åt murning och byggnadsarbete. Han blev en av Stormwinds mest framstående medborgare och hjälpte till att utforma delar av den återuppbyggda huvudstaden. Något från hans tidiga liv finns kvar bland ruinerna."}},faq={{q="Vem äger Alexston Farmstead?",a="Familjen Alexston har gett gården dess namn. Baros Alexston, Stormwinds stadsarkitekt, arbetade på marken som pojke innan han flyttade till huvudstaden för att ägna sig åt arkitektur.",al={"vem äger gården","alexstons ägare","vems gård är det här"}},{q="Varför är gården övergiven?",a="Liksom stora delar av Westfall övergavs gården efter omfattande oroligheter och banditverksamhet från Defias Brotherhood. Eftersom kungariket inte kunde skydda dem flydde bönderna och lämnade gården att förfalla.",al={"varför övergiven","vad hände med alexston farm","vem förstörde gården"}},{q="Varför anfaller mekaniska fågelskrämmor folk här?",a="Harvest Watchers byggdes för att bruka jorden och skydda grödorna från asätare. När bönderna flydde blev maskinerna utan underhåll, och deras urverk gick sönder. Nu anfaller de levande varelser.",al={"varför anfaller harvest watchers","fientliga fågelskrämmor","fientliga harvest golems"}},{q="Finns det något gömt i boningshuset?",a="Baros Alexston lämnade sin personliga kompass i boningshuset när han var ung. Resenärer som arbetar i Stormwind City får ibland i uppdrag att hämta den från det övergivna hemmet.",al={"uppdrag här","byte på gården","baros föremål"}}},fx={["3df1ed7f"]={q="Vad är Alexston Farmstead?",a="Alexston Farmstead är en övergiven lantgård i norra Westfall. Liksom många gårdar i trakten bidrog den en gång till att föda kungariket Stormwind, innan laglösheten svepte genom området. Gården är också känd som Baros Alexstons barndomshem. Som ung arbetade han på just de här fälten innan han blev stadsarkitekt i Stormwind.",al={"vad är det här för plats","alexston farm","om alexston farmstead"}},["10e8b118"]={q="Vad hände vid Alexston Farmstead?",a="Marken var en gång en fredlig och produktiv familjegård, men drabbades av oroligheterna som plågade Westfall. När Defias Brotherhood tog kontroll över landsbygden beslagtogs gården och invånarna drevs bort. Med tiden ersattes de levande arbetarna av förrymda Harvest Watchers, och gården blev öde och igenvuxen medan fälten förblev under fientlig kontroll.",al={"alexston farmsteads historia","historia om alexston farmstead","vad hände här"}},["6ef1debd"]={q="Är Alexston Farmstead farligt?",a="Ja, du bör gå försiktigt fram kring gården. Fälten patrulleras av dödliga mekaniska Harvest Watchers, förrymda automater som anfaller alla som närmar sig. Dessutom har Defias Brotherhood en aktiv och fientlig närvaro i hela området, vilket gör den förfallna gården osäker för oförsiktiga vandrare.",al={"är det farligt här","hot vid alexston farmstead","monster vid alexston farm"}}},fp="18,140,18.275.0,12.250.0,32.141.0,26.192.0,52.204.0,46.176.0"}
P.entries["subzone:algaz-station"] = {n="Algaz Station",s="Algaz Station är en militär utpost för dvärgar i nordvästra Loch Modan, strax söder om det befästa passet Dun Algaz. Dess bergsvaktgarnison bevakar infarten till de norra tunnlarna och skyddar resenärer samt håller uppsikt över gränslandet mot The Marshlands.",h="Algaz Station är en militär utpost för dvärgar i nordvästra Loch Modan, strax söder om det befästa passet Dun...",kw={"algaz station","dun algaz","gothor brumn","ironforge","loch modan","mountaineer stormpike","bergsvakter","north gate pass"},ang={["faction:Alliance"]="Utposten erbjuder ett säkert uppmarschområde och ett reparationsstopp för alliansens äventyrare som färdas mellan Loch Modan och de norra träskmarkerna.",["race:Dwarf"]="För dvärgiska resenärer är Algaz Station en välbekant symbol för Ironforges räckvidd och ser till att kungens huvudvägar hålls skyddade mot hot som väller fram ur bergen."},sec={{t="Vakt vid norra passet",b="Algaz Station ligger strax öster om North Gate Pass och söder om Dun Algaz och fungerar som en viktig strategisk utkikspost för kungariket Ironforge. En grupp dvärgiska bergsvakter håller ständig uppsikt här och ser till att den viktiga vägen mellan Loch Modan och de norra låglanden hålls öppen för handel och truppförflyttningar. Eftersom hoten i de omgivande kullarna är många, från kringströvande bestar till framryckande troggs, erbjuder utposten vila, reparationer och militärt stöd åt trötta resenärer innan de ger sig genom bergstunnlarna."}},faq={{q="Vad är Algaz Station?",a="Det är en militär utpost tillhörande Ironforge i nordvästra Loch Modan. Den fungerar som vaktpost och rastplats för bergsvakter som patrullerar bergspassen norrut mot Dun Algaz.",al={"vad är det här för plats","algaz stations syfte","vem sköter algaz station"}},{q="Varifrån kommer stationens namn?",a="Den har fått sitt namn från Dun Algaz, det väldiga dvärgiska passet och tunnelsystemet strax norr om stationen som förbinder Loch Modan med The Marshlands.",al={"varför heter den algaz station","kopplingen till dun algaz","namnets betydelse"}},{q="Vilka finns vid Algaz Station?",a="Utposten bemannas av dvärgiska bergsvakter, däribland Mountaineer Stormpike, samt stödpersonal som rustningsmästaren Gothor Brumn, som utför reparationer åt resenärer.",al={"vilka finns här","npc:er vid algaz station","mountaineer stormpikes plats"}}},fx={c8a5caec={q="Är Algaz Station farligt?",a="Utposten är en trygg fristad bemannad av vaksamma dvärgbergsmän, men vägarna runtomkring är fulla av faror. Den ligger strax söder om Dun Algaz och öster om North Gate Pass. Resande som vilar här måste hålla utkik efter fientliga troggar, bestar och grönhudar som strövar omkring i norra Loch Modan.",al={"faran vid algaz station","är algaz station tryggt","hot vid algaz station"}}},fp="13,155,26.435.0,22.165.0,36.149.0,34.116.0"}
P.entries["subzone:altar-of-storms-burning-steppes"] = {n="Altar of Storms (Burning Steppes)",s="Högt uppe bland Burning Steppes taggiga klippor står Altar of Storms, ett mörkt monument tillägnat felritualer och demonisk makt. Svartrockklanens häxmästare håller till på den olycksbådande platsen och utför avskyvärd magi i skuggan av Blackrock Spire. Dess mörka aura lockar skuggnens ambitiösa utövare från hela Azeroth.",h="Högt uppe bland Burning Steppes taggiga klippor står Altar of Storms, ett mörkt monument tillägnat...",kw={"altar of storms","blackrock","burning steppes","fel","gorzeeki wildeyes","mor'zul bloodbringer","häxmästare"},ang={["class:Warlock"]="Altar of Storms och eremiterna i närheten, Mor'zul Bloodbringer och Gorzeeki Wildeyes, är viktiga kraftkällor för häxmästare som söker material och ritualer för att frammana en fruktad dreadsteed.",["race:Orc"]="Altaret är en obehaglig påminnelse om Old Hordes mörka historia, då Gul'dans Shadow Council använde liknande avskyvärda helgedomar för att fylla ogres och soldater med mörk trolldom."},sec={{t="Ett arv av skugga och lågor",b="Altar of Storms byggdes under de tidigare krigen för att kanalisera korrumperande felmagi och står som ett dystert monument över mörka pakter. I Burning Steppes kontrollerar fientliga häxmästare från Svartrockklanen området, där de utför ockulta ritualer och åkallar demoniska krafter. I närheten blickar eremiten Gorzeeki Wildeyes och hans mästare Mor'zul Bloodbringer ut över platsen från sitt läger. Där studerar avfälliga utövare dess våldsamma energier och hittar på krävande ritualer för ambitiösa magiker som söker större mörk makt."}},faq={{q="Vad är Altar of Storms?",a="Det är ett korrumperat stenmonument som används för mörka felritualer och för att kanalisera demonisk energi. Det byggdes under Old Hordes krig och är fortfarande en aktiv källa till mörk makt som Blackrock-häxmästare utnyttjar.",al={"altar of storms historia","vad är detta altare","burning steppes altare"}},{q="Vem kontrollerar altaret just nu?",a="Fientliga häxmästare och akolyter från Svartrockklanens orcher håller till på marken närmast altaret. De utför mörka ceremonier och skyddar sin plats från inkräktare.",al={"vem finns vid altar of storms","fiender vid altar of storms","vem bor här"}},{q="Vem är Gorzeeki Wildeyes?",a="Gorzeeki Wildeyes är en excentrisk goblinlärd inom mörka konster som bor på kullen med utsikt över altaret tillsammans med sin mästare, Mor'zul Bloodbringer. Han hjälper mäktiga häxmästare som vill bemästra starkare demoniska bindningar.",al={"gorzeeki wildeyes","ork på kullen","vem är gorzeeki"}}},fp="33,136,28.399.0,28.192.0,33.144.0,25.228.0"}
P.entries["subzone:alterac-mountains"] = {n="Alterac Mountains",s="Alterac Mountains är en karg, snötäckt bergskedja som reser sig direkt ovanför Hillsbrads böljande betesmarker. En gång var sluttningarna hjärtat i ett stolt människorike. Nu hyser de ruinerade bosättningar, banditfraktioner och farlig vildmark där resenärer sällan färdas utan skydd.",h="Alterac Mountains är en karg, snötäckt bergskedja som reser sig direkt ovanför Hillsbrads böljande...",kw={"alterac","crushridge","hillsbrad","berg","perenolde","strahnbrad","syndicate"},ang={["class:Rogue"]="Bergspassen vimlar av agenter från Syndicate och lejda mördare, vilket gör kullarna till en utmärkt prövning i överlevnad och kontraspionage.",["faction:Alliance"]="För alliansen står Alterac som ett bittert minnesmärke över förräderi, där Perenoldes svek nästan ledde till mänsklighetens undergång under det andra kriget."},sec={{t="Ett fallit rike",b="Långt innan kullarna föll i kaos utgjorde dessa högländer den självständiga nationen Alterac, ett av de sju rikena som föddes ur det forntida Arathor. Arvet krossades under det andra kriget, när kung Aiden Perenolde slöt en hemlig pakt med den gamla horden och lät orcherna passera genom bergstopparna i utbyte mot att hans rike skonades. Alliansen i Lordaeron avslöjade förräderiet och avsatte Perenolde, vilket lämnade regionen splittrad av militärstyre och territoriella konflikter."},{t="Vildmark och banditer",b="Efter det tredje krigets förödelse föll bergen i fullständig laglöshet. Rikets arvlösa adelsmän slöt sig samman och bildade Syndicate. De höll till i ruinerna av Strahnbrad och smidde planer på att återta sitt förlorade välde genom sabotage och mord. Mellan de hänsynslösa Crushridge-ogrerna som ockuperar den sönderslagna huvudstaden, härjande gnoller och de splittrade magiska ruinerna kring Dalaran är passen i Alterac fortfarande några av de farligaste färdvägarna i Lordaeron."}},faq={{q="Vilket rike styrde över bergen förr?",a="Människornas rike Alterac behärskade bergen i generationer efter att Arathors imperium splittrades. Huvudstaden låg bland de högsta bergstopparna och kontrollerade vägarna mellan Lordaeron, Dalaran och Arathi Highlands fram till rikets fall under det andra kriget.",al={"vem ägde alterac","vad var alterac","alteracs rikets historia"}},{q="Varför ligger Alterac i ruiner?",a="Under det andra kriget förrådde kung Aiden Perenolde Alliansen i Lordaeron genom att hjälpa horden. När förräderiet avslöjades krossade alliansens arméer Alteracs styrkor och avsatte kungen. Utan någon legitim härskare och efter den senare förödelsen under det tredje kriget föll nationen i ruiner.",al={"vad hände med alterac","vem förstörde alterac","bakgrund till ruinerna i alterac"}},{q="Vilka är Syndicate, som lurar i kullarna?",a="Syndicate är ett laglöst förbund bestående av tidigare alteracisk adel och deras följeslagare. Under Aliden Perenoldes ledning anlitar de rövare, lönnmördare och skurkaktiga legosoldater för att destabilisera regionen i hopp om att med våld återupprätta sitt rike.",al={"vilka är syndicate","vad är syndicate","varför finns det banditer i alterac"}},{q="Vilka faror strövar omkring på de snöiga topparna?",a="Resenärer som vågar sig uppför sluttningarna måste stå emot de brutala Crushridge-ogrerna, flockar av Highland-gnoller, födosökande kobolder och opportunistiska rövare från Syndicate som patrullerar passen.",al={"vad lever i alterac","monster i alterac","faror i alterac"}}},fx={e4635e9a={q="Vad är Alterac Mountains?",a="Alterac Mountains är en karg, snötäckt bergskedja i centrala Lordaeron, strax norr om Hillsbrad Foothills. Höjderna var en gång kungariket Alteracs självständiga territorium, med befästa städer, bergsfästen och avlägsna dalar. I dag är nationen krossad och dess städer ligger i ruiner under snön. De iskalla topparna har blivit ett slagfält för kvarvarande utstötta, stridande klaner och rovgiriga monster.",al={"vad är alterac mountains","alterac mountains i historien","översikt över alterac"}},["858b3945"]={q="Vem styr över Alterac Mountains i dag?",a="Ingen legitim regering styr över Alterac Mountains. Kungariket föll efter sitt förräderi under det andra kriget, och den ordning som återstod försvann under Scourges anfall. I dag gör Syndicate, fördrivna adelsmän och laglösa människor ledda av ätten Perenolde, anspråk på sina förfäders rätt till ruinerna. Men de strider våldsamt mot brutala Crushridge-ogrer, kringströvande odöda och befästa Frostwolf-orcher som gömmer sig i de höga dalarna.",al={"vem kontrollerar alterac","vilka bor i alterac mountains","ledarskapet i alterac"}}},fp="17,193,14.394.0,22.400.0,42.256.0,24.301.0,43.248.0,36.145.0"}
P.entries["subzone:alterac-mountains-classic"] = {n="Alterac Mountains (Classic)",s="Alterac Mountains är ett kargt, molnigt högland som reser sig brant norr om Hillsbrad Foothills, med ständig snö och taggiga bergstoppar. Regionen var en gång hem åt människoriket Alterac och Dalarans lärda tillflyktsorter, men ligger nu till stor del i ruiner och strids om av brutala ogres, adelsfödda banditer och de stridande arméerna i Alterac Valley.",h="Alterac Mountains är ett kargt, molnigt högland som reser sig brant norr om Hillsbrad Foothills, med ständig...",kw={"alterac mountains","alterac valley","crushridge ogres","dalaran","lordamere","ruins of alterac","strahnbrad","syndicate","uplands"},ang={["class:Rogue"]="Undangömt i en avskild bergsdal vid Alteracs gräns ligger Ravenholdt Manor, det historiska högkvarteret för tjuvarnas och lönnmördarnas gille, som leds av Lord Jorach Ravenholdt.",["faction:Alliance"]="Alliansen håller en framskjuten utpost i dessa frusna kullar under ledning av Lieutenant Haggerdin. Där rekryterar de ståndaktiga kämpar för att förstärka dvärgarnas Stormpike Guard i Alterac Valley."},sec={{t="Ett härjat högland",b="Högt ovanför låglandet i Hillsbrad reser sig Alterac Mountains, ett hårt land av regn, tallskog och höghöjdssnö. Regionen hade en gång tre stora mänskliga makter: bergariket Alterac, magokratin Dalaran och den befästa staden Strahnbrad. Men svek och krig ledde till dess fall. I dag har Crushridge ogres slagit sig ned i Alteracs förstörda huvudstad, Strahnbrad hålls av laglösa och bland Dalarans krossade ruiner arbetar de överlevande magikerna outtröttligt för att återställa sin förstörda fristad."},{t="Banditer, bestar och krig",b="Förutom de inhemska bergslejonen och yetierna som stryker omkring på de frostbitna bergsryggarna strider desperata dödliga fraktioner om höglandet. Syndicate, som består av egendomslösa adelsmän från Alterac som blivit stråtrövare, använder svärd och bakhåll från gamla gods och läger vid bergens fot. De drabbar ständigt samman med ogres som tränger in. Samtidigt används de djupa passen in bland de höga klipporna som uppmarschläger för det blodiga kriget mellan Stormpike Expedition och Frostwolf Clan om Alterac Valleys dolda trakter."}},faq={{q="Vad hände med kungariket Alterac?",a="Alterac föll i vanära under det andra kriget, när dess härskare, King Aiden Perenolde, förrådde Grand Alliance för att hjälpa Horde. Efter kriget upplöstes kungariket. Utan ledarskap förföll dess städer, Strahnbrad lades i ruiner och huvudstaden översvämmades av de brutala Crushridge ogres.",al={"varför ligger alterac i ruiner","vem styrde alterac","alteracs fall"}},{q="Vilka är banditerna i Syndicate i bergen?",a="Syndicate är en laglös organisation som främst består av tidigare adelsmän från Alterac och deras följeslagare. Efter att ha förlorat sina marker, sin ställning och sin rikedom när Alterac förrådde sina allierade började de ägna sig åt spionage, lönnmord och vägrån i ett försök att återta markerna som de anser vara deras rättmätiga egendom.",al={"vilka är syndicate","varför finns det skurkar i alterac","banditer i alterac"}},{q="Vad är den väldiga lila kupolen vid sjön?",a="I dag står ingen kupol över Dalaran. Efter att demonfursten Archimonde jämnade staden med marken under det tredje kriget reste de överlevande magikerna i Kirin Tor en violett sköld över ruinerna. Men de tog bort den tidigt under återuppbyggnaden och bygger nu upp sina ödelagda torn under bar himmel.",al={"lila bubbla i alterac","vad är dalarans bubbla","magisk sköld över dalaran"}},{q="Hur tar du dig till Alterac Mountains?",a="Resande kommer vanligtvis till fots från Hillsbrad Foothills och följer de nordliga vägarna från Tarren Mill eller norr om Southshore. Våghalsiga simmare kan också korsa Lordamere Lake åt sydost från Silverpine Forests stränder eller från Undercitys utkanter.",al={"hur tar man sig till alterac","ingång till alterac","vägen till alterac"}}},fp="27,229,20.448.0,24.468.0,40.275.0,47.289.0,50.265.0,35.277.0"}
P.entries["subzone:alther-s-mill"] = {n="Alther's Mill",s="Alther's Mill är ett förfallet sågverk i de karga kullarna nordost om Lakeshire i Redridge Mountains. Det var en gång en viktig källa till bearbetat virke för traktens byggare, men de övergivna markerna har förfallit till ett tillhåll för vilda asätare och strövande rovdjur. För äventyrare som färdas österut mot Stonewatch är de förfallna byggnaderna ett dystert landmärke som markerar gränsen för tryggt gränsland.",h="Alther's Mill är ett förfallet sågverk i de karga kullarna nordost om Lakeshire i Redridge Mountains.",kw={"alther's mill","althers mill","lakeshire","låsdyrkning","sågverk","redridge","spindlar","stonewatch"},ang={["class:Rogue"]="Alliansens skurkar känner Alther's Mill väl. Tjuvgillen använder sågverkets utspridda, bortglömda lådor med lås och avskilda marker som en lugn träningsplats för att öva på fin låsdyrkning.",["faction:Alliance"]="Det förfallna sågverket står som ännu en skarp påminnelse om Stormwinds hårt ansatta gränsgarnisoner, där värdefull industri ligger sönderslagen och övergiven inom synhåll från Lakeshire."},sec={{t="Ett övergivet gränslandssågverk",b="Innan området hemsöktes av invaderande rovdjur och orchanfall sjöd handeln med timmer vid Alther's Mill, och virket användes till byggen i Lakeshire och kringliggande bosättningar. Den stillsamma gläntan nordost om Lake Everstill gav enkel tillgång till bergens timmerbestånd. När oron spred sig genom Stormwinds kungarike och Blackrock-klanen trängde ned från Stonewatchs höjder övergav traktens mjölnare anläggningen och lämnade timmerbyggnaderna och hjulet att ruttna."},{t="Skuggor och skrot",b="Utan mänskliga arbetare blev sågverket angripet av monstruösa tarantellor, asgamar och plundrare som slog till när tillfälle gavs. Resenärer som tar vägen mot de östra passen måste varsamt hålla sig längs dess skuggiga ytterkant. På senare år har även skumma agenter och tjuvar utnyttjat den övergivna anläggningen och använt dess bortglömda förvaringslådor och dolda hörn för att finslipa olovlig låsdyrkning och bedriva hemlig handel långt från Lakeshire Town Watchs blickar."}},faq={{q="Vad är Alther's Mill?",a="Alther's Mill är ett förfallet sågverk nordost om Lakeshire i Redridge Mountains. Där höggs och bearbetades tidigare timmer åt de kringliggande bosättningarna, tills farorna i vildmarken tvingade fram en nedläggning.",al={"alther's mill","althers mill","vad är det här för plats","vad var alther's mill"}},{q="Varför är sågverket övergivet?",a="När det regionala försvaret försvagades efter det första och andra kriget blev gränsområdets verksamhet alltför farlig för vanliga arbetare att upprätthålla utan kungligt militärt skydd. Det berodde på aggressiva vilda djur som jättespindlar och Blackrock-orchernas framryckning.",al={"varför övergivet","vem övergav alther's mill","vad hände med mjölnarna"}},{q="Vilka varelser strövar kring sågverket?",a="Markerna och den omgivande snårskogen har främst tagits över av jättelika bergstarantellor, asätande gamar och strövande rovdjur, samt kringdrivande rövare som rör sig mellan Stonewatch och Lake Everstill.",al={"fiender vid alther's mill","varelser vid sågverket","vad lever här"}},{q="Varför besöker skurkar Alther's Mill?",a="De avlägsna, skräpfyllda markerna är en omtyckt övningsplats för alliansskurkar. Deras tränare skickar dem hit för att öva på att dyrka upp låsta fotkistor och hämta värdefulla tjuvcertifikat.",al={"skurkuppdrag vid sågverket","låsdyrkning vid alther's mill","tjuvcertifikat"}}},fx={f58217b4={q="Vad hände med Alther's Mill?",a="Alther's Mill var en gång ett verksamt sågverk som tjänade kungariket Stormwind och folket i Redridge. När området blev alltmer isolerat och hotades av fientliga vilddjur och invaderande orcher från bergen, förlorade människorna kontrollen över sågverket. Arbetarna övergav platsen, som till slut översvämmades av vilddjur, kringströvande asätare och kringdrivande orcher på väg mot Stonewatch Keep.",al={"alther's mills historia","vad hände vid alther's mill","historia om alther's mill"}}},fp="13,178,26.355.0,17.394.0,22.187.0,26.220.0,36.182.0,34.181.0"}
P.entries["subzone:ambermill"] = {n="Ambermill",s="Ambermill är en befäst mänsklig bosättning i sydöstra Silverpine Forest, strax sydväst om Lordamere Lake. Den var en gång en stillsam timmerby, men ockuperas nu av överlevande magiker och lärlingar från Dalaran. Deras närvaro utgör en farlig utpost för mänskligt motstånd vid Forsakens rikes södra gräns.",h="Ambermill är en befäst mänsklig bosättning i sydöstra Silverpine Forest, strax sydväst om Lordamere Lake.",kw={"ambermill","dalaran","kirin tor","ley-linje","shadow priest allister","silverpine forest"},ang={["class:Mage"]="Bosättningen visar Kirin Tors försök att återupprätta sitt inflytande efter att Scourge och Burning Legion ödelade Dalaran.",["faction:Horde"]="För Forsakens operatörer är Ambermill en av de få återstående enklaverna av levande mänskligt motstånd i Silverpine, som hotar logistiken i söder och ruvar på farliga arkanska hemligheter."},sec={{t="Dalarans bastion",b="Före det tredje kriget var Ambermill en stillsam timmerstad utan större betydelse. I det kaotiska efterspelet till Lordaerons fall flyttade Kirin Tors överlevande magiker in och befäste bosättningen. Dalarans runskrivare, besvärjare och lärlingar patrullerar nu byggnaderna och stallarna och använder Ambermill som ett framskjutet fäste mot de odöda."},{t="Att utnyttja ley-linjerna",b="Kirin Tors intresse för Ambermill sträcker sig långt bortom enkelt territoriellt försvar. Byn ligger direkt ovanpå en vilande energinod i en ley-linje. Forsakens spioner och Deathstalkers som bevakar staden har upptäckt att Dalarans magiker försöker återaktivera denna knutpunkt för storskaligt arkanskt arbete. Om det slutförs kan kraftutbrottet hota Forsakens bräckliga grepp om Silverpine Forest, vilket får Shadow Priest Allister och Deathstalkers att iscensätta sabotage, stöld av Kirin Tor-dokument och mord runt kvarnområdet."}},faq={{q="Varför ockuperar Dalarans magiker en by i Silverpine?",a="Efter Dalarans förödelse under det tredje kriget flyttade överlevande styrkor från Kirin Tor till Ambermill för att upprätta en utpost för levande mänskligt motstånd. Forsakens agenter undersöker deras förehavanden.",al={"varför är magiker här","vem kontrollerar ambermill","kirin tor silverpine"}},{q="Har Ambermill alltid tillhört Dalaran?",a="Nej. Före det tredje kriget var Ambermill en obetydlig timmerby. Dalarans magiker flyttade in och befäste den först efter att Scourge hade översvämmat Lordaeron.",al={"ambermills historia","vem ägde ambermill"}},{q="Varför vill Forsaken anfalla Ambermill?",a="Ambermill är ett befäst centrum för mänskligt motstånd i Silverpine Forest. Forsaken betraktar dess Dalaran-stödda styrkor och hemliga arkanska arbete som ett hot mot sitt grepp om regionen.",al={"forsaken ambermill","varför döda magikerna i ambermill"}},{q="Vad letar Deathstalkers efter i Ambermill?",a="Forsakens Deathstalkers fick veta av tillfångatagna mänskliga fångar att magikerna i Ambermill förvarar säkrade dokument med detaljer om Dalarans hemliga planer och militära avsikter. Därför är bosättningen ett huvudmål för hemlig infiltration och stöld.",al={"ambermill dokument","mennet carkad ambermill"}}},fx={["9833b496"]={q="Vad är Ambermill?",a="Ambermill är en befäst bosättning för människor i kullarna i sydöstra Silverpine Forest, sydväst om Lake Lordamere. Den var ursprungligen en stillsam skogsarbetarutpost med rådhus, stall och sågverk, men har gjorts om till ett hårt bevakat militärläger för magiker. Byggnaderna genljuder av arkan energi medan magiker och vakter håller skogen på avstånd.",al={"vad är ambermill","översikt över ambermill","berätta om ambermill"}},c529bf0b={q="Vad hände med Ambermill?",a="Före det tredje kriget var Ambermill en stillsam timmerstad av liten betydelse. Efter att Scourge härjade i området och krossade Dalaran under det tredje kriget, flyttade överlevande styrkor från Kirin Tor in och befäste staden för att bevara ett strategiskt fäste i Silverpine.",al={"ambermills historia","ambermills bakgrund","historia om ambermill"}},fc63f553={q="Vilka bor i Ambermill?",a="Ambermill är helt och hållet bebott och skött av Kirin Tor-personal från Dalaran. Dalaran Protectors, frammanade arkana ormar, lärlingar och runskrivare patrullerar området, medan erfarna besvärjare övervakar de magiska operationerna från rådhuset och byggnaderna runtomkring. Lokala tjänstefolk som sömmerskan Avelina Lilly har också försett magikerna med mat och kläder.",al={"vem kontrollerar ambermill","invånare i ambermill","vem finns vid ambermill"}},b9a41d98={q="Är Ambermill farligt?",a="Ambermill är ytterst farligt för alla som står på de Fördömdas eller Hordens sida. Styrkorna från Kirin Tor som är stationerade här ser de odöda som ett existentiellt hot och anfaller inkräktare så fort de får syn på dem. Utöver beväpnade vaktposter skyddas bosättningen av skickliga magiker som brukar kraftfull offensiv magi och frammanar beskyddande arkana skydd och ormtjänare för att utplåna inkräktare.",al={"är ambermill fientligt","faran i ambermill","är ambermill tryggt"}}},fp="9,242,20.278.0,21.489.1,58.202.0,37.149.0,45.182.0,54.237.0"}
P.entries["subzone:amberstill-ranch"] = {n="Amberstill Ranch",s="Amberstill Ranch är en fridfull dvärgbosättning längs den snötäckta vägen mot Loch Modan, strax norr om Gol'Bolar Quarry. Här föds Ironforges berömda bergsbaggar upp och tränas. Äventyrare besöker ranchen för att skaffa tåliga dvärgriddjur, lära sig rida eller hjälpa familjen att försvara boskapen mot traktens rovdjur.",h="Amberstill Ranch är en fridfull dvärgbosättning längs den snötäckta vägen mot Loch Modan, strax norr om...",kw={"amberstill","riddjursförsäljare","baggar","ranch","ridtränare","snöskohare","vagash","yarlyn"},ang={["faction:Alliance"]="De tåliga baggar som familjen Amberstill föder upp ger Alliance ett pålitligt kavalleri för kallt klimat och oländig bergsterräng.",["race:Dwarf"]="För dvärgäventyrare är ranchen en stolt kulturell hörnsten där unga hjältar skaffar sitt första riddjur av typen Barak Tor'ol."},sec={{t="Bergsbaggarnas hem",b="Amberstill Ranch ligger intill klipporna i Dun Morogh och är vida känt i Khaz Modan för uppfödningen av de tåligaste bergsbaggarna i Eastern Kingdoms. Familjen Amberstill sköter stall och fållor och tränar de säkra djuren att ta sig fram över förrädiska snöpass och branta alpklippor. Utöver att sälja riddjur och boskap får familjen ofta tampas med kullarnas vilda djur, särskilt kringströvande wendigos som lockas av doften från den färska hjorden."}},faq={{q="Vad är Amberstill Ranch känt för?",a="Ranchen är Alliances centrala plats för uppfödning av bergsbaggar av typen Barak Tor'ol. Dvärgar och ärade Alliance-mästare kommer hit för att lära sig rida på baggar och köpa riddjur av de lokala stallmästarna.",al={"amberstills syfte","varför besöka amberstill","amberstills baggar"}},{q="Kan andra än dvärgar köpa riddjur här?",a="Baggar är traditionellt förbehållna dvärgryttare som förstår deras envisa läggning. Medlemmar av andra Alliance-folk kan bara lära sig rida på dem och köpa dem om de har förtjänat Ironforges största förtroende och uppnått upphöjd status där.",al={"köpa baggar icke-dvärg","kan människor köpa baggar","krav för baggriddjur"}},{q="Vilka hot står ranchen inför?",a="Hjorden hotas ständigt av hungriga wendigos som kommer ner från de frusna branterna. Det mest beryktade rovdjuret i höjderna runt omkring är Vagash, en väldig wendigo som regelbundet ger sig på den sårbara boskapen.",al={"fara vid amberstill","wendigohot","vagash uppdrag"}},{q="Kan man få tag på något annat på ranchen?",a="Den unge Yarlyn Amberstill har en samling tama snöskoharar och säljer gärna harar i bur till resenärer som söker ett sällskapsdjur för vägen.",al={"amberstills hare","snöskohare som sällskapsdjur","yarlyn amberstill"}}},fx={["0dde8a5d"]={q="Vad är Amberstill Ranch?",a="Amberstill Ranch är en dvärggård och avelsplats bland kullarna i östra Dun Morogh, norr om Gol'Bolar Quarry. Den fungerar som det främsta stallet för uppfödning av de tåliga bergsbockar som Ironforges dvärgar uppskattar som pålitliga riddjur i Khaz Modans karga terräng.",al={"vad är amberstill ranch","amberstill ranchs syfte","vad är amberstill för plats"}},f9ed26f9={q="Vilka bor på Amberstill Ranch?",a="Gården är hem åt familjen Amberstill, som föder upp, sköter och tränar Dun Moroghs berömda bergsbockar. Familjemedlemmarna sköter stallen, säljer lokala husdjur som snöskoharar och lär ut ridning till dem som vunnit Ironforges djupa förtroende.",al={"vem driver amberstill ranch","invånare på amberstill ranch","vilka bor här"}},["1facab92"]={q="Är Amberstill Ranch farligt?",a="Själva gården är en trygg alliansfristad, men utkanterna är farliga. Vilda bestar strövar omkring på de snötäckta branterna i närheten. Ingen fruktas mer av de lokala uppfödarna än det monstruösa vidundret Vagash, som jagar deras boskap.",al={"faran vid amberstill ranch","är amberstill tryggt","faror vid amberstill ranch"}}},fp="16,171,25.325.0,35.172.0,37.200.0,33.184.0,42.127.0"}
P.entries["subzone:ameth-aran"] = {n="Ameth'Aran",s="Ameth'Aran är en uråldrig ruin i södra Darkshore, en gång en blomstrande stad där drottning Azsharas Highborne utövade arkan trolldom. När den stora Sunderingen krossade den uråldriga världen föll staden med den. I dag hemsöks de sönderslagna kolonnaderna av de hämndlystna spökena efter alverna som dog där.",h="Ameth'Aran är en uråldrig ruin i södra Darkshore, en gång en blomstrande stad där drottning Azsharas...",kw={"ameth'aran","anaya dawnrunner","athrikus narassin","bashal'aran","cerellean whiteclaw","darkshore","highborne","tysha moonblade"},ang={["class:Druid"]="Druider ser ruinerna som ett oläkt sår i Darkshore, där plågade andar dröjer sig kvar och stör vildmarkens naturliga balans.",["race:NightElf"]="För nattalver är Ameth'Aran ett dystert minnesmärke över Highborne-kastens övermod och förräderi, som ledde till Sunderingen."},sec={{t="En stad av trollkarlar",b="Före den stora Sunderingen var Ameth'Aran och systerboplatsen Bashal'Aran två centra för Highbornes inflytande längs den uråldriga kusten. Med drottning Azsharas gunst ägnade sig stadens styrande adel åt obehindrade arkanexperiment. Staden styrdes på avstånd av trollkarlen Athrikus Narassin i Tower of Althalaxx och blomstrade tills den katastrofala kollapsen av Evighetens brunn slet sönder Kaldorei-imperiet."},{t="Förräderi och evig plåga",b="När världen började slitas sönder återvände Athrikus Narassin till Ameth'Aran och lovade sina panikslagna undersåtar räddning med kraftfull skyddsmagi. I stället för att skydda dem begick trollkarlen ett fruktansvärt förräderi. Han stal deras livskraft för att ge näring åt sina egna själsädelstenar, under förevändningen att han skulle bevara dem för evigt. Krossat av katastrofen och mörk magi föll Ameth'Aran. I dag hemsöker plågade Highborne-vålnader området och kan inte finna ro, tiotusen år efter att de mördades."}},faq={{q="Vad hände med Ameth'Aran?",a="Ameth'Aran låg redan i ruiner under Kaldorei-imperiets sista dagar och förstördes när Evighetens brunn krossades i den stora Sunderingen för tiotusen år sedan. Ruinerna hemsöks fortfarande av andarna efter de Highborne som dog där.",al={"varför ligger ameth'aran i ruiner","ameth'aran historia","ameth'arans fall"}},{q="Vilka är spökena som vandrar bland ruinerna?",a="De är rastlösa andar efter Highborne-alverna som bodde i staden och utövade arkan magi före den stora Sunderingen. De kan inte finna ro och vandrar bland de sönderslagna stenarna i ständig plåga och vrede.",al={"spöken i ameth'aran","vålnader i ameth'aran","highborne-spöken i darkshore"}},{q="Vem var Anaya Dawnrunner?",a="Anaya Dawnrunner bodde i Ameth'Aran och var Cerellean Whiteclaws älskade. Hon dog när staden föll under Sunderingen, och hennes spöke förblev bundet till ruinerna tills Cerellean sökte hjälp utifrån för att äntligen befria hennes själ.",al={"anaya dawnrunner","cerelleans älskade","förlorad kärlek i ameth'aran"}},{q="Vad är stentavlorna som hittats i ruinerna?",a="Ruinerna innehåller uråldriga stentavlor med Ameth'Arans historia och en skildring av stadens fall. Sentinel Tysha Moonblade försökte tyda dem för att sammanställa en historisk rapport åt Cenarion Circle, men fientliga spöken tvingade henne att förlita sig på förbipasserande resenärer.",al={"ameth'arans stentavlor","runstenar i ameth'aran","ameth'arans fall på stentavlorna"}}},fx={["1468cad3"]={q="Är Ameth'Aran farligt?",a="Ja. Ruinerna hemsöks av rastlösa Highborne-spöken som våldsamt försvarar sitt forna hem mot de levande. Sentinel-spejare som Tysha Moonblade har drivits bort av deras vrede, och alla resenärer som söker de uråldriga tavlorna måste ta sig försiktigt fram bland de spektrala uppenbarelserna.",al={"är ameth'aran tryggt","faror i ameth'aran","hot i ameth'aran"}},["5cae2414"]={q="Vad är Ameth'Aran?",a="Ameth'Aran är en gammal, förfallen nattalvsbosättning i södra Darkshore, sydöst om Auberdine. Före Sunderingen var den en storslagen tvillingstad till Bashal'Aran, där drottning Azsharas gunstlingar bland Highborne utövade sin arkana konst.",al={"vad är ameth'aran","om ameth'aran","ameth'aran-ruinerna"}},bf7a1160={q="Varför ligger Ameth'Aran i ruiner?",a="Ameth'Aran föll under den stora Sunderingen för tiotusen år sedan, när Well of Eternity krossades och den uråldriga kaldorei-världen slets sönder. De sönderbrutna ruinerna hemsöks fortfarande av rastlösa Highborne-andar.",al={"varför förstördes ameth'aran","hur förstördes ameth'aran","ameth'arans fall"}}},fp="10,207,19.397.0,28.428.1,28.242.0,39.192.0,25.220.1,46.227.0"}
P.entries["subzone:andorhal"] = {n="Andorhal",s="Andorhal var en gång norra Lordaerons blomstrande jordbrukshjärta, men blev brännpunkten för kungarikets undergång under det tredje kriget. Det var här Kel'Thuzad smittade säden med odödhetens pest och spred fasa över hela trakten. I dag hålls den förstörda staden stadigt i Scourges järngrepp.",h="Andorhal var en gång norra Lordaerons blomstrande jordbrukshjärta, men blev brännpunkten för kungarikets...",kw={"andorhal","säd","spannmålsmagasin","kel'thuzad","pestländerna","scourge","uther"},ang={["class:Paladin"]="Andorhal är helig mark, invigd med Silverhandens blod. Det var här Uther the Lightbringer och hans trogna riddare gjorde sitt tragiska sista motstånd mot Arthas.",["race:Undead"]="För Forsaken är Andorhals fält en bitter påminnelse om deras ursprung och platsen där The Cult of the Damned iscensatte deras dödliga livs undergång."},sec={{t="Pestens ursprung",b="Före det tredje kriget var Andorhal det välmående sädesmagasinet i Eastweald, där säd från hela Lordaeron samlades och skickades österut till Hearthglen och Stratholme. På grund av detta omfattande distributionsnät valde Kel'Thuzad och The Cult of the Damned Andorhal som bas för sin fasansfulla plan. Genom att smitta sädeslådorna med odödhetens pest förvandlade kulten kungarikets kornbod till en källa till förruttnelse och smittade otaliga invånare innan kronan ens förstod hotet."},{t="Silverhandens fall",b="Prins Arthas Menethil och Jaina Proudmoore mötte Kel'Thuzad här och dödade honom till en början, men nekromantikerns död var inte slutet. När Arthas återvände från Northrend som Scourges förkämpe marscherade han tillbaka till Andorhal för att återta Kel'Thuzads kvarlevor. Uther the Lightbringer och resterna av Silver Hand gjorde ett desperat sista motstånd för att försvara kung Terenas aska. Paladinerna blev övermannade, Uther dödades av sin forna lärjunge och den storslagna bosättningen förvandlades till ett Scourge-fäste kvävt av pest."}},faq={{q="Varför är Andorhal så viktigt för pestens historia?",a="Andorhal var den centrala knutpunkten för jordbruksvaror i norra Lordaeron. Kel'Thuzad utnyttjade försörjningskedjan, smittade spannmålssilorna med odödhetens pest och skickade den smittade skörden längs King's Road direkt till Stratholme och närliggande städer.",al={"hur började pesten här","andorhal sädespest","varför andorhal var viktigt"}},{q="Vem kontrollerar Andorhal just nu?",a="Den odöda Scourge kontrollerar Ruins of Andorhal med järnhand. Skelettvakter, nekromantiker och gastar stryker omkring på de förkolnade gatorna och bevakar platsen för sin första stora seger i Western Plaguelands.",al={"vem styr andorhal","scourge i andorhal","vem har makten i andorhal"}},{q="Dog Uther the Lightbringer här?",a="Ja. Efter Capital Citys fall skyddade Uther och hans paladiner urnan med kung Terenas aska i utkanten av Andorhal. Arthas angrep följet för att ta urnan till Kel'Thuzads kvarlevor och duellerade till slut med sin mentor och dödade honom på vägen.",al={"var dog uther","uthers död andorhal","dödade arthas uther här"}}},fp="8,260,25.441.0,27.485.0,53.223.0,32.181.0,36.221.0"}
P.entries["subzone:angerfang-encampment"] = {n="Angerfang Encampment",s="Angerfang Encampment är Dragonmaw-klanens främsta fäste i centrala Wetlands. Under hövdingen Nek'rosh Skullcrushers ledning använder dessa avfälliga orcher det vidsträckta lägret som bas för att hota närliggande dvärgbosättningar och planera Menethil Harbors förstörelse.",h="Angerfang Encampment är Dragonmaw-klanens främsta fäste i centrala Wetlands.",kw={"angerfang","dragonmaw","menethil","nek'rosh","skullcrusher","stoutfist","wetlands","whelgar"},ang={["class:Warlock"]="De mörka skuggväktarna i lägret bär på Rods of Channeling, viktiga föremål som eftersöks för de bindningar som beskrivs i Tome of the Cabal.",["faction:Alliance"]="För Menethil Harbors försvarare är Angerfang ett tydligt och omedelbart hot. Att fälla Nek'roshs krigsbaner och ta hans huvud är avgörande för att trygga handelsvägarna längs kusten."},sec={{t="Ett fäste i träsket",b="Angerfang Encampment breder ut sig över dyn i centrala Wetlands och är Dragonmaws befästa maktcentrum i området. Till skillnad från de utspridda rövarband som strövar i träskmarkerna har lägret välförsvarade barrikader, vakttorn och en mäktig här av krigare, benväktare och mörka besvärjare som håller fast vid de gamla sederna. Härifrån sprider Dragonmaw sin militära styrka över träskmarkerna, angriper resande längs vägarna och hotar närliggande dvärgruiner som Whelgar's Excavation Site."},{t="Nek'roshs ambitioner",b="Lägret leds av hövdingen Nek'rosh Skullcrusher, son till den ökände häxmästaren Nekros som en gång förslavade den röda drakflykten vid Grim Batol. Nek'rosh hyser ett djupt hat mot Alliansen och har samlat katapulter och rest krigsbaner inför ett fullskaligt anfall mot Menethil Harbor. Alliansens befälhavare i hamnstaden känner till den hotande belägringen och skickar hjältar in i Angerfangs hjärta för att ta deras baner, slå sönder deras krigsmaskiner och ta Nek'roshs huvud innan hans anfall dränker hamnen i eld."}},faq={{q="Vem styr Angerfang Encampment?",a="Lägret styrs av hövdingen Nek'rosh Skullcrusher, son till den ökände Dragonmaw-häxmästaren Nekros Skullcrusher. Från sitt befälstält djupt inne i lägret leder Nek'rosh rövarband i området och planerar erövringen av Menethil Harbor.",al={"vem leder angerfang","angerfangs boss","vem bestämmer här","nekroshs läger"}},{q="Är orcherna här allierade med Thralls hord?",a="Nej. Dragonmaw-klanen här är fortfarande oberoende av Thralls nya hord. De håller fast vid den gamla hordens mörka arv och är fientliga mot både Alliansens och hordens resande. Thralls krigare betraktar dem som vildsinta utstötta och jagar dem till och med för material till rustningar.",al={"tillhör dragonmaw horden","är angerfang vänligt mot horden","är angerfang en del av thralls hord"}},{q="Varför fokuserar Alliansen på att förstöra lägret?",a="Captain Stoutfist och dvärgf örsvararna i Menethil Harbor upptäckte att Nek'rosh har samlat katapulter och en väldig styrka vid Angerfang för att bombardera och erövra hamnen. Alliansen anfaller i förebyggande syfte för att krossa belägringen innan den börjar.",al={"varför anfalla angerfang","captain stoutfist angerfang","varför döda nekrosh"}},{q="Varför söker häxmästare sig till lägret?",a="De mörka besvärjarna bland Dragonmaw vid Angerfang bär på Rods of Channeling, mörka rituella redskap som eftertraktas av utövare av demonisk magi som vill färdigställa Tome of the Cabal.",al={"häxmästaruppdrag angerfang","tome of the cabal wetlands","rod of channeling angerfang"}}},fx={["02ce636e"]={q="Vad är Angerfang Encampment?",a="Angerfang Encampment är Dragonmaw-orkernas främsta fäste i centrala Wetlands. Denna befästa utpost breder ut sig över den sumpiga terrängen och fungerar som uppmarschområde och samlingsplats för Dragonmaw-styrkor som smider planer på att erövra regionen och marschera mot Menethil Harbor.",al={"vad är angerfang encampment","angerfang encampment i wetlands","om angerfang encampment"}},["5926baf0"]={q="Vad hände vid Angerfang Encampment?",a="Efter det andra kriget och deras slutliga reträtt in i träsken upprättade resterna av Dragonmaw-klanen detta läger som sin huvudsakliga operationsbas. Under Nek'rosh Skullcrushers befäl samlade klanen belägringsvapen och katapulter här och förberedde aktivt ett fälttåg för att förstöra Alliansens fäste i Menethil Harbor.",al={"angerfang encampments bakgrund","angerfang encampments historia","vad hände vid angerfang"}},c64d3749={q="Är Angerfang Encampment farligt?",a="Det är ytterst farligt. Lägrets område vimlar av disciplinerade Dragonmaw-stridsmästare, härdade plundrare, mörka häxmästare och skuggväktare. Oförberedda resenärer som kommer för nära möts av övermäktiga styrkor och fientliga orker som är fast beslutna att krossa alla utomstående.",al={"är angerfang encampment farligt","hur farligt är angerfang encampment","är angerfang encampment tryggt"}}},fp="20,206,21.332.0,19.441.1,35.213.0,45.259.0,52.232.0,41.164.0"}
P.entries["subzone:anvilmar"] = {n="Anvilmar",s="Anvilmar är en befäst dvärgpost inbäddad bland de snöiga djupen i Coldridge Valley i Dun Morogh. Runt en väldig stensmedja ligger den främsta träningsplatsen och samlingspunkten för unga Bronzebeard-dvärgar och fördrivna gnomiska flyktingar som ger sig ut på sina äventyr.",h="Anvilmar är en befäst dvärgpost inbäddad bland de snöiga djupen i Coldridge Valley i Dun Morogh.",kw={"anvilmar","coldridge valley","dun morogh","smedja","frostmane","modimus anvilmar","startområde"},ang={["race:Dwarf"]="För dvärgar markerar Anvilmar början på resan ut i världen och bär kanske namnet på den forntida High King som en gång styrde ett enat dvärgrike.",["race:Gnome"]="Gnomer som söker skydd här efter Gnomeregans fall finner ståndaktiga dvärgallierade, varma härdar och instruktörer som hjälper dem att anpassa sig till den frusna vildmarken."},sec={{t="Coldridges hjärta",b="Anvilmar ligger undangömt bland de norra klipporna i Coldridge Valley och står som en beständig symbol för dvärgarnas uthållighet. Den stadiga stenbyggnaden domineras av en dånande central smedja och rymmer klassmentorer, försäljare av förnödenheter och erfarna bergsbestigare som tränar rekryter innan de skickar ut dem i det större kungariket. Även om bosättningen skyddas av väldiga snödrivor är den ständigt på sin vakt mot de fientliga Frostmane-trollen och aggressiva vilddjur som stryker omkring i den frusna dalen."},{t="Ett arv av järn och troll",b="Bosättningen har troligen fått sitt stolta namn efter High King Modimus Anvilmar, den forntida härskare som styrde alla dvärgklanerna före War of the Three Hammers. I dag håller garnisonen fortsatt vakt och ser till att smedjans eldar brinner trots dalens troll och vilddjur."}},faq={{q="Vad är Anvilmar?",a="Anvilmar är ett dvärgfäste och en bosättning i norra Coldridge Valley i Dun Morogh. Det fungerar som första utpost och träningsplats för nyrekryterade äventyrare bland dvärgar och gnomer.",al={"vad är anvilmar","anvilmars plats","översikt över anvilmar"}},{q="Varför heter platsen Anvilmar?",a="Utposten kan ha fått sitt namn efter High King Modimus Anvilmar eller Anvilmar-blodslinjen. Modimus styrde dvärgklanerna före War of the Three Hammers, men bosättningens namngivning är inte bekräftad.",al={"vem var anvilmar","anvilmars namnbakgrund","namnets betydelse"}},{q="Vilka hot står Anvilmar inför?",a="Utposten hotas ständigt av de inhemska Frostmane-trollen som håller till bland klipporna i Coldridge Valley, liksom av farliga lokala vilddjur som vargar och wendigos.",al={"anvilmars fiender","vem angriper anvilmar","hot mot anvilmar"}},{q="Kan du lära dig yrken här?",a="Anvilmar har en dånande smedja som lämpar sig för smide och smältning, men inga tränare i hantverksyrken är stationerade här. Unga rekryter måste ta sig längre in i Dun Morogh, till exempel till Kharanos eller Ironforge, för att lära sig hantverkskonsterna ordentligt.",al={"yrken i anvilmar","anvilmars smedja","smide i anvilmar"}}},fx={["449334a9"]={q="Är Anvilmar farligt?",a="Själva bosättningen är trygg och väl skyddad, med ett storslaget smedjearbete, en härd, tränare och vakter. Men faror lurar åt alla håll strax utanför dess närmaste omgivning. Aggressiva vargar, hungriga björnar och plundringståg av fientliga Frostmane-troll strövar omkring i Coldridge Valleys snötäckta drivor och utgör ständiga hot mot oförsiktiga resenärer och nya rekryter.",al={"är anvilmar tryggt","faror i anvilmar","hot i anvilmar"}}},fp="8,189,23.363.0,27.219.0,17.151.0,25.178.0,32.114.0,31.167.0"}
P.entries["subzone:apothecarium"] = {n="Apothecarium",s="Apothecarium är Undercitys sydvästra kvarter och högkvarter för Royal Apothecary Society. I dessa giftiga laboratorier arbetar Forsaken-al kemister outtröttligt under Master Apothecary Faranell för att framställa smittsamma farsoter, gifter och konstruerade fasor. Det är det dystra hjärtat för Undercitys biologiska forskning, avgörande för Lady Sylvanas kamp mot de levande och Scourge.",h="Apothecarium är Undercitys sydvästra kvarter och högkvarter för Royal Apothecary Society.",kw={"abominations","alkemi","apothecarium","faranell","the new plague","royal apothecary society","sylvanas","undercity"},ang={["profession:Herbalism"]="Botaniker förser Royal Apothecary Societys avskyvärda destillatörer med sällsynta, pesthärjade växter från ruinerna i de norra kungadömena.",["race:Undead"]="För Forsaken är Apothecarium smedjan där deras överlevnad formas. Där framställs de kemiska och ihopsydda vapen som behövs för att hålla Lordaeron mot övermäktiga fiender."},sec={{t="Fasornas kammare",b="Apothecarium ligger på den underjordiska huvudstadens sydvästra terrass och är en labyrint av bubblande kar, dissektionsbord och stickande kemiska ångor. Under ledning av Master Apothecary Faranell använder Royal Apothecary Society stadsdelen för att fördjupa sin förståelse för dödlighet och förruttnelse. Här experimenterar alkemister och kirurger med vävnadstransplantat, vivisektion och hopfogning av mäktiga abominations. Deras främsta mål, på uppdrag av Lady Sylvanas Windrunner, är att framställa en ny farsot som kan utrota både Scourge och den kvarvarande mänskliga närvaron i Lordaeron."},{t="Centrum för Forsaken-alkemi",b="Utöver storslagna militära ambitioner fungerar kvarteret som Horde:s främsta centrum för praktisk alkemi och örtmedicin i Eastern Kingdoms. Både lärlingar och mästare samlas vid de giftiga kanalerna för att destillera brygder, studera botaniska farsoter och rådfråga mästerutövare."}},faq={{q="Vad används Apothecarium till?",a="Apothecarium fungerar som forsknings- och tillverkningsavdelning för Royal Apothecary Society. Här brygger Forsaken-alkemister experimentella gifter, förfinar The New Plague, konstruerar abominations och utbildar utövare i alkemi och örtmedicin.",al={"apothecariums syfte","vad händer här","varför finns apothecarium"}},{q="Vem leder Apothecarium?",a="Stadsdelen och dess forskare leds av Master Apothecary Faranell, Royal Apothecary Societys chefsforskare, med drottning Sylvanas Windrunners fulla befogenhet och beskydd.",al={"apothecariums ledare","vem styr apothecarium","faranell undercity"}},{q="Vad försöker Royal Apothecary Society skapa?",a="Deras främsta projekt är att odla fram The New Plague, en dödlig farsot konstruerad för att utplåna både Lich Kings Scourge-styrkor och allt levande mänskligt motstånd som utmanar Forsakens territorium i Lordaeron.",al={"forsakens farsotforskning","the new plague undercity","vad brygger de"}},{q="Kan spelare lära sig yrken här?",a="Ja. Stadsdelen är huvudstadens viktigaste knutpunkt för alkemister och örtmedicinare, med avancerade yrkeslärare längs gångarna och i kamrarna.",al={"apothecariums yrkeslärare","alkemi i undercity","örtmedicinlärare i undercity"}}},fx={["05b32189"]={q="Vad är Apothecarium?",a="Apothecarium är Undercitys sydvästra kvarter och fungerar som Royal Apothecary Societys dystra högkvarter och laboratoriekomplex. Djupt inne i dess väldiga salar brygger Forsaken-alkemister och forskare giftiga blandningar, skapar mäktiga styggelser och utför makabra experiment för att främja Forsakens sak.",al={"vad är apothecarium","apothecarium i undercity","undercitys apothecarium"}},["170a66ad"]={q="Är Apothecarium farligt?",a="Det är tillräckligt tryggt för Horde-resenärer, men utomstående finner en skräckkammare. Luften är stinkande av giftiga ångor, öppna kar sjuder av frätande kemikalier och pestsmittade reagenser, och släpande styggelser strövar genom salarna. Varje levande inkräktare som är dum nog att gå in riskerar att hamna fastspänd på en apotekares dissektionsbord.",al={"är apothecarium tryggt","faror i apothecarium","fara i apothecarium"}}},fp="12,270,18.447.0,26.244.0,34.209.0,27.196.0,54.197.0,35.153.0"}
P.entries["subzone:ariden-s-camp"] = {n="Ariden's Camp",s="Ariden's Camp är ett övergivet läger strax norr om stigen genom Deadwind Pass. Det förfaller i skuggan av Karazhan och står där som en kuslig, tyst avvikelse bland den ödsliga ravinens vindar. Resande mellan Duskwood och Swamp of Sorrows passerar det ofta med olust och undrar vem som en gång slog upp ett tält här.",h="Ariden's Camp är ett övergivet läger strax norr om stigen genom Deadwind Pass.",kw={"ariden","ariden's camp","deadwind pass","duskwood","karazhan","medivh","swamp of sorrows"},ang={["class:Mage"]="För lärda i arkana ämnen är det övergivna lägret en obehaglig påminnelse om hur nära Karazhan tornar upp sig. Få stannar länge nära Medivhs torn.",["class:Rogue"]="Någon slog läger under Eastern Kingdoms mest skräckinjagande spira och kom aldrig tillbaka efter sina saker. Antingen var personen oerhört ambitiös eller anmärkningsvärt dumdristig."},sec={{t="Ett tyst läger",b="Inbäddat mot klipporna norr om ravinvägen mellan Duskwood och Swamp of Sorrows ser denna förfallna lägerplats ut som ett vanligt tillfälligt stopp som sedan länge övergetts av levande människor. Men i Deadwind Pass tryckande mörker förblir inget orört av mörk magi. Oavsett vem som gav lägret namnet Ariden's och vilken lycka dess ägare sökte i Karazhans närhet, slukade passets kvardröjande fasor det och lämnade bara väderbitet tyg, kall aska och ett olöst mysterium."}},faq={{q="Var ligger Ariden's Camp?",a="Ariden's Camp ligger i Deadwind Pass, strax norr om huvudvägen som går från Duskwood i väster till Swamp of Sorrows i öster, inte långt från Karazhan.",al={"aridens camp plats","var ligger ariden camp","läger i deadwind pass"}},{q="Finns det några aktiva hot vid lägret just nu?",a="Gläntan vid lägret är stilla och kusligt tyst, men i Deadwind Pass stryker dödliga deadwind ogres, vålnader och de vidriga bevingade bestar som häckar nära Karazhan omkring.",al={"är aridens camp farligt","fiender vid aridens camp"}}},fp="13,181,19.378.0,31.156.0,51.151.0"}
P.entries["subzone:astranaar"] = {n="Astranaar",s="Astranaar är den främsta bosättningen för Night Elf i centrala Ashenvale, byggd på en ö i en stillsam sjö där den gamla skogsvägen går fram. Som hjärtat i Alliansens verksamhet i området erbjuder staden en livsviktig tillflykt åt resenärer som hotas av fientliga furbolger, satyrer och Horden.",h="Astranaar är den främsta bosättningen för Night Elf i centrala Ashenvale, byggd på en ö i en stillsam sjö där...",kw={"ashenvale","astranaar","kalimdor","night elf","raene wolfrunner","väktare","thistlefur"},ang={["faction:Alliance"]="Astranaar fungerar som Alliansens ledningspost och främsta logistiknav när styrkorna rör sig genom Ashenvales omstridda vildmark.",["race:NightElf"]="För Kaldorei är Astranaar den centrala bastionen i deras uråldriga hemland i centrala Kalimdor, där heliga lundar skyddas mot skogens växande hot."},sec={{t="Skogens hjärta",b="Astranaar ligger på en ö mitt i en skogssjö och är den största bosättningen för nattalver i Ashenvale. Träbroar över vattnet förbinder staden med fastlandet, och där bor väktare, präster och hantverkare som håller vakt över skogen. Här finns också grundläggande bekvämligheter som ett värdshus, handelsmän och en erfaren läderarbetare. Högt belägna utsiktsplatser rymmer en flygmästare som erbjuder hippogryffärder till avlägsna utposter runt om i Kalimdor."},{t="En belägrad bastion",b="Trots det lugna vattnet och de lysande lyktorna är Astranaar alltid redo för strid. Lokala ledare som Raene Wolfrunner samordnar patruller och försvar mot de korrumperade Thistlefur-furbolgerna som tränger fram från norr. De fruktar att furbolgerna kan gå till direkt angrepp mot staden."}},faq={{q="Vilka tjänster finns i Astranaar?",a="Astranaar erbjuder Alliansens resenärer ett brett utbud av bekvämligheter, däribland ett värdshus, försäljare av allmänna varor, en tränare i läderarbete på expertnivå och en flygmästare med förbindelser till viktiga utposter i Ashenvale och Kalimdor.",al={"astranaars tjänster","vad finns i astranaar","astranaars flygmästare"}},{q="Vem är begravd på kyrkogården på andra sidan sjön?",a="Ingen skildring från den här tiden nämner vem som vilar där. Kyrkogården ligger på andra sidan sjön från staden, och gravarna bevarar sina hemligheter.",al={"astranaars grav","valstann staghelms grav","vem är begravd här"}},{q="Varför oroar sig väktarna i Astranaar för furbolgerna i området?",a="Thistlefur-furbolgerna i norr har fallit under mörka, korrumperande krafter. Väktaren Raene Wolfrunner fruktar att deras växande aggressivitet, om den lämnas obekämpad, ska uppmuntra dem att öppet angripa själva Astranaar.",al={"hotet från thistlefur","varför slåss mot furbolger","raene wolfrunners uppdrag"}},{q="Kan spelare från Horden besöka Astranaar utan risk?",a="Nej. Astranaar är ett kraftigt befäst fäste för Alliansen, bevakat av beväpnade Night Elf-väktare som angriper medlemmar av Horden så fort de får syn på dem.",al={"är astranaar vänligt mot horden","horden i astranaar"}}},fx={["7c629b8a"]={q="Vad är Astranaar?",a="Astranaar är den främsta nattalvstaden i centrala Ashenvale och den största bosättningen i hela skogen. Staden är byggd på en ö i en fridfull sjö och sträcker sig över den stora handelsvägen. Två träbroar förbinder den med vildmarken. För nattalverna och deras allierade i Alliansen är den skogens bultande hjärta och främsta försvarsbastion mot intrång i Ashenvale.",al={"vad är astranaar","astranaars bakgrund","om astranaar"}},["262340cc"]={q="Vilka bor i Astranaar och vem styr där?",a="Astranaar befolkas främst av nattalvsinvånare, hantverkare och Sentinels, som har i uppgift att skydda Ashenvale. Bland stadens framstående ledare och försvarare finns Sentinel Raene Wolfrunner, som samordnar den lokala spaningen och håller uppsikt över växande hot i de omgivande skogarna.",al={"vem styr astranaar","astranaars ledning","vem leder astranaar","astranaars sentinels"}},["62cff95a"]={q="Är Astranaar farligt?",a="Inom broarna är Astranaar ett väl befäst tillhåll för Alliansens resenärer, bevakat dygnet runt av vaksamma Sentinels. Men staden ligger i en skog där striderna blir allt vanligare. Aggressiva Thistlefur-furbolgs lurar strax norrut, och Warsong-orkernas närliggande läger innebär ett ständigt hot om räder genom centrala Ashenvale. För Horde-resenärer leder ett enda steg in i staden till en omedelbar attack från Sentinels.",al={"är astranaar tryggt","fara i astranaar","hot mot astranaar"}}},fp="9,238,19.366.0,21.281.0,41.157.0,47.119.0,68.175.0,41.114.0"}
P.entries["subzone:auberdine"] = {n="Auberdine",s="Auberdine är en kuststad för nattalver vid Darkshores dystra stränder och fungerar som Alliansens främsta sjöväg till norra Kalimdor. Under mulna skyar och tallklädda klippor förbinder staden Teldrassils öhem med Eastern Kingdoms och erbjuder en administrativ tillflykt undan vildmarken som tränger sig på.",h="Auberdine är en kuststad för nattalver vid Darkshores dystra stränder och fungerar som Alliansens främsta...",kw={"auberdine","båt","darkshore","hamnbryggor","kaldorei","fyr","hamn","sentinels","thundris windweaver"},ang={["faction:Alliance"]="Den här hamnen är livsnerven för Alliansens resor och försörjningslinjer in i norra Kalimdor och säkerställer ett stadigt flöde mellan Stormwind, Ironforge och Darnassus.",["race:NightElf"]="För kaldorei som ger sig av från Teldrassil är Auberdine den första riktiga knutpunkten på fastlandet, där uråldrig tradition möter yngre allierades främmande seder och livliga industri."},sec={{t="Porten till norra Kalimdor",b="Vid Veiled Seas stränder är Auberdine den enda större bosättningen som har överlevt i dagens Darkshore. Till skillnad från Teldrassils avskilda städer bland trädtopparna blickar Auberdine utåt och är Alliansens mest trafikerade hamn i norr. Regelbundna skepp går härifrån till Eastern Kingdoms, till Stormwind Harbor och, via Southshore, till Menethil Harbor, medan lokala färjor går till Rut'theran Village vid världsträdets grenar. Tack vare sin roll i handeln har Auberdine en mer mångkulturell prägel än traditionella alvboplatser. Besökare ser lampor lysa upp stenlagda gator och utländska handelsmän, däribland dvärgar och gnomer, samsas bland låga timmerhus med välvda tak."},{t="En hårt prövad tillflykt",b="Äldste Thundris Windweaver och Auberdine Village Council styr staden och samordnar försvaret av Darkshore tillsammans med de lokala Sentinels. Trots sin roll som ett viktigt handelscentrum nämns Auberdine sällan i Darnassus grenar, där minnet dröjer vid de stora städer som Sundering tog. Staden uthärdar ständiga faror i trakten: aggressiva murlocs plundrar fiskebåtarna längs stranden, korrumperade Blackwood furbolgs tränger på från söder och mörk magi som sipprar ned från Felwood gör den lokala faunan orolig."}},faq={{q="Vart går skeppen från Auberdine?",a="Hamnen förbinder norra Kalimdor med den vidare alliansvärlden. En brygga har färjan till Rut'theran Village vid foten av Teldrassil, medan andra tar emot stora oceangående fartyg som seglar över Great Sea till Stormwind Harbor och, via Southshore i Hillsbrad Foothills, till Menethil Harbor i Wetlands.",al={"båtar i auberdine","vart går båtarna","resor från auberdine"}},{q="Vem styr Auberdine?",a="Äldste Thundris Windweaver och Auberdine Village Council ansvarar för Auberdine. Sentinels har uppsikt över bosättningens försvar och leds lokalt av Sentinel Glynda Nal'Shea.",al={"ledare i auberdine","vem bestämmer","byråd"}},{q="Varför bor dvärgar och människor i en nattalvstad?",a="Eftersom Auberdine är Alliansens främsta hamn i norra Kalimdor kommer utländska handelsmän, hantverkare och resenärer hit först. Dvärgar har öppnat en smedja för att serva besökande skepp och resenärer, vilket gör staden ovanligt mångsidig och välkomnande jämfört med traditionella nattalvboplatser.",al={"icke-alver i auberdine","varför dvärgar här"}},{q="Varför ser nattalver från Darnassus ned på Auberdine?",a="Thundris Windweaver kallar Auberdine en anspråkslös plats vars namn inte nämns i Darnassus grenar. De flesta kaldorei minns bara vad Sundering tog: de blomstrande städerna Ameth'Aran och Bashal'Aran. Auberdine lever kvar i deras skugga.",al={"rivalitet mellan darnassus och auberdine","utstötta i auberdine"}}},fx={a08cc347={q="Vad är Auberdine?",a="Auberdine är en fridfull kusthamn på Darkshores dimhöljda stränder och den främsta porten mellan norra Kalimdor och den vidare Alliansen. Den ligger längs Veiled Sea och har klassisk nattalvisk träarkitektur, glödande gatlyktor och vidsträckta bryggor. Här välkomnas resenärer som anländer med skepp från Menethil Harbor eller tar färjan till Teldrassil, med skydd, handel och gemenskap mitt i den skuggiga vildmarken.",al={"vad är det här för stad","berätta om auberdine","översikt över auberdine"}},["36b132df"]={q="Vad hände vid Auberdine?",a="Efter den stora klyvningen, som krossade det forntida Kaldorei-imperiet och skapade Darkshores kust, misslyckades många försök att återbefolka den ödsliga regionen. Auberdine blev den enda bosättningen som överlevde och blomstrade längs dessa hemsökta stränder. Efter att nattalverna anslutit sig till den stora Alliansen byggde det stillsamma fiskesamhället ut sina hamnar och blev den viktiga sjöfartsförbindelsen mellan nattalvernas hemland och Eastern Kingdoms.",al={"auberdines historia","auberdines förflutna","vad är auberdines historia"}},ba4d867a={q="Är Auberdine farligt?",a="Inom sina gränser är Auberdine tryggt tack vare vaksamma nattalviska Sentinels som är stationerade längs vägarna och bryggorna. Men farorna i den omgivande vildmarken blir allt fler. Fördärvade furbolgs lurar i söder, uppjagat vilt strövar i skogarna och aggressiva murlocs patrullerar de grunda vattnen och hotar aktivt lokala fiskare och sjöfarten längs kusten.",al={"är det tryggt här","hot mot auberdine","är auberdine under attack"}}},fp="9,225,28.448.0,19.478.0,35.282.0,20.153.0,60.258.0,57.250.0"}
P.entries["subzone:azurelode-mine"] = {n="Azurelode Mine",s="Azurelode Mine är en aktiv järngruva som tillhör Alliansen, belägen bland kullarna i den sydvästra delen av Hillsbrad Foothills. Southshores milis vaktar gruvan, där mänskliga arbetare bryter malm som i stadig takt försörjer det lokala mänskliga krigsarbetet mot De övergivna i Tarren Mill.",h="Azurelode Mine är en aktiv järngruva som tillhör Alliansen, belägen bland kullarna i den sydvästra delen av...",kw={"azurelode mine","förman bonds","hillsbrad foothills","gruvarbetare i hillsbrad","järngruva","southshore"},ang={["faction:Horde"]="Ett angrepp mot Azurelode Mine stryper Southshores tillförsel av färskt järn och understödjer direkt De övergivnas offensiv i Foothills.",["profession:Mining"]="Gångarna och höjderna runt Azurelode är rika på järnfyndigheter, men Alliansens gruvarbetare vaktar gruvans inre hårt."},sec={{t="Foothills malmådror",b="Azurelode Mine ligger sydväst om det öppna jordbrukslandet och strax väster om Southshore. Gruvan har länge utnyttjat de mineralrika höjderna längs kusten. I dag arbetar mänskliga gruvarbetare djupt under jord under uppsyn av förman Bonds och bryter järn till vapen och rustningar åt Alliansens försvarare som håller stånd mot Undercity i regionen."},{t="Ett viktigt militärt mål",b="Eftersom Azurelode Mine står för merparten av järnet som behövs för att hålla Southshores garnisoner och stadsmilis rustade, är gruvan ett direkt mål för Horde. Tarren Mill har gett sig på arbetarna och vakterna för att slå sönder försörjningslinjerna som håller Hillsbrads mänskliga fästen vid liv."}},faq={{q="Vem kontrollerar Azurelode Mine?",a="Azurelode Mine kontrolleras av Alliansen och drivs av mänskliga gruvarbetare med band till Southshore och Hillsbrad township. Förman Bonds har uppsikt över arbetet på plats.",al={"vem driver azurelode","azurelode mines fraktion","vem äger azurelode"}},{q="Varför är gruvan viktig för Horde?",a="Gruvan förser Southshores rustkammare och den lokala Alliansmilisen med viktigt järn. Ledningen i Tarren Mill riktar in sig på gruvarbetarna och arbetsledarna för att slå ut människornas vapentillverkning i Foothills.",al={"varför anfalla azurelode","slaget om hillsbrads gruva","hordes intresse för gruvan"}},{q="Har Azurelode Mine alltid varit en del av Hillsbrad?",a="Berättelserna från den här tiden säger inte vem som hade dessa kullar innan Hillsbrad. I dag arbetar gruvarbetare från Hillsbrad Fields i gruvan under förman Bonds ledning.",al={"greymane walls historia","var azurelode gilneas","gilneas gruva"}},{q="Vilka metaller bryter man här?",a="Gruvan producerar främst järnmalm till mänskliga rustkammare i närheten.",al={"vilken malm finns i azurelode","azurelodes resurser"}}},fx={["9018e270"]={q="Vad är Azurelode Mine?",a="Azurelode Mine är en aktiv järngruva uthuggen i kullarna i sydvästra Hillsbrad Foothills, söder om Hillsbrad Fields och väster om Southshore. Den är en viktig strategisk tillgång för traktens människor och förser Alliansens vapenförråd i regionen med järn till deras pågående kamp mot fientliga styrkor.",al={"azurelode mine","vad är azurelode","information om azurelode mine"}},["549159c0"]={q="Vad hände vid Azurelode Mine?",a="Gruvarbetare från Hillsbrad Fields har länge brutit malm i Azurelode Mine under Foreman Bonds ledning och levererat järn till Alliansens vapenförråd. I dag är gruvan fortfarande fullt bemannad och i drift under Alliansens kontroll, även om trycket ökar när Forsaken gör anspråk på Hillsbrad.",al={"azurelodes historia","azurelode mines historia","azurelodes förflutna"}},b1a6dc2c={q="Vilka bor eller arbetar i Azurelode Mine?",a="Gruvan drivs av mänskliga arbetare från närliggande Hillsbrad Fields, under ledning av Foreman Bonds. På grund av det ständiga hotet från Horde och det lokala viltet är Hillsbrad-väktare och beväpnade vakter stationerade i tunnlarna och utanför för att skydda gruvarbetarna medan de arbetar.",al={"vem styr azurelode mine","azurelode mines tillsyningsman","vem arbetar i azurelode"}},["7c8c1de2"]={q="Är Azurelode Mine farligt?",a="Ja. Utöver de vanliga farorna med underjordiskt gruvarbete är Azurelode Mine ett militärt mål mitt i det större slaget om Hillsbrad. Platsen är kraftigt befäst och bevakas av vaksamma mänskliga väktare. Horde-agenter undersöker ofta tunnlarna för att störa malmproduktionen, mörda Foreman Bonds och slakta arbetarna.",al={"är azurelode farligt","hot mot azurelode","fara vid azurelode mine"}}},fp="14,133,22.266.0,23.215.0,28.136.0,39.192.0,44.149.0,27.69.0"}
P.entries["subzone:bael-dun-digsite"] = {n="Bael'dun Digsite",s="Bael'dun Digsite är en dvärgisk utgrävning djupt inskuren i bergen längs Mulgore västra kant. Prospector Khazgorms grupp från Bael Modan anlade stenbrottet, som de lokala tauren ser som en direkt skändning av sitt förfädersland och en förolämpning mot Earth Mother.",h="Bael'dun Digsite är en dvärgisk utgrävning djupt inskuren i bergen längs Mulgore västra kant.",kw={"bael modan","bael'dun","baeldun","baine bloodhoof","utgrävningsplats","dvärgar","earth mother","explorers league","mulgore"},ang={["faction:Alliance"]="Bael'dun-gruvarbetarna drivs av en uppriktig törst efter historiska upptäckter, men har trängt för långt in i Horde-territorium och väckt våldsam vrede bland lokalbefolkningen.",["race:Tauren"]="De sår som utgrävningen skär in i Mulgore västra kullar gör Bael'dun till en direkt förolämpning mot Earth Mother. Förfädernas jord måste skyddas från främmande skändning med beslutsamma åtgärder."},sec={{t="Intrång i kullarna",b="Bael'dun Digsite ligger högt på bergssluttningarna i västra Mulgore och utgör den sydligaste utposten för dvärgarnas expedition från Explorers' League, baserad i Bael Modan i södra Barrens. Dvärgiska prospektörer brydde sig inte om gränser eller de nybosatta stammarnas andliga traditioner. De anlände med hackor, spadar och sprängpulver för att gräva fram forntida Titan-reliker begravda under slätterna."},{t="Att försvara Earth Mother",b="Bloodhoof-stammen såg denna inträngande stenbrytning som ett direkt angrepp på Earth Mother. Baine Bloodhoof uppmanade först till försiktighet och försökte varna inkräktarna, men dvärgarna vägrade blankt att överge sina diken. När diplomatin hade misslyckats beslutade tauren att slå sönder expeditionens verktyg och med våld driva bort gruvarbetarna innan deras destruktiva grävande skadar Mulgore heliga jord ännu mer."}},faq={{q="Varför gräver dvärgar i Mulgore?",a="Prospektörerna tillhör dvärgexpeditionen med högkvarter i Bael Modan i södra Barrens. De drevs av Explorers' Leagues strävan att hitta forntida artefakter och lämningar efter Titanerna och anlade denna utpost där deras instrument visade att reliker kunde finnas, utan hänsyn till taurenernas självbestämmande.",al={"varför är dvärgar här","dvärgar i mulgore","baeldun-dvärgar"}},{q="Hur reagerar Bloodhoof-stammen på utgrävningsplatsen?",a="Tauren ser verksamheten som ett oacceptabelt sår i Earth Mother. När dvärgarna vägrade hörsamma de tidiga varningarna och lämna platsen fredligt skickade Baine Bloodhoof och byns ledare krigare för att förstöra gruvarbetarnas verktyg och driva ut inkräktarna från Mulgore.",al={"vad tycker tauren","baines reaktion","taurenernas svar på utgrävningen"}},{q="Vad har Bael'dun för koppling till Bael Modan?",a="Bael'dun är en utgrävningsplats som anlades direkt från fästningen och den huvudsakliga utgrävningen i Bael Modan, precis på andra sidan bergsryggen i södra Barrens.",al={"koppling till bael modan","var kommer de här dvärgarna ifrån"}},{q="Varför förhandlade tauren inte bara med expeditionen?",a="Baine Bloodhoof försökte först hitta diplomatiska lösningar och utfärdade formella varningar till expeditionens ledare. Dvärgarna betraktade dock Mulgore som obebodd vildmark och ignorerade helt taurenernas andliga oro, så stammen såg våld som sin enda utväg.",al={"försökte tauren sluta fred","diplomati med dvärgar"}}},fx={["02606c94"]={q="Vad är Bael'dun Digsite?",a="Bael'dun Digsite är en aktiv dvärgisk utgrävning som är uthuggen direkt i bergen i västra Mulgore. Den grundades av Prospector Khazgorm och medlemmar av Dwarven Archaeological League från Bael Modan och är ett ovälkommet intrång från Alliansen djupt inne på taurenfolkets territorium.",al={"vad är bael'dun digsite","bael'duns utgrävningsplats i mulgore","dvärgisk utgrävningsplats i mulgore"}},cc534035={q="Vad hände vid Bael'dun Digsite?",a="Dvärgiska utgrävare anlände från Barrens för att gräva fram titanreliker och uråldriga hemligheter begravda under jorden. De ignorerade Baine Bloodhoofs rasande protester och varningar och började gräva. Bloodhoof-stammen svarade med att sabotera deras gruvdrift och bryta sönder deras hackor för att tvinga bort dem från helig mark.",al={"bael'duns historia","vad hände vid utgrävningsplatsen"}},fc08309c={q="Vem styr Bael'dun Digsite?",a="Platsen drivs av dvärgiska gruvarbetare och utgrävare som skickats från Bael Modan i södra Barrens. De arbetar på uppdrag av Explorer's League och dvärgiska expeditionsledare, som sätter upptäckten av uråldriga artefakter framför fred med taurenfolket som bor där.",al={"vem kontrollerar bael'dun","ledare för bael'dun digsite","vem styr utgrävningsplatsen"}},["30c4a8af"]={q="Är Bael'dun Digsite farligt?",a="Ja. De dvärgiska utgrävarna och förmännen här är fientliga mot resande från Horde och försvarar sitt område med hackor, gevär och klubbor. Dessutom riskerar deras skoningslösa sprängningar och utgrävningar av bergssidan att störa Mulgore naturliga andar.",al={"hur farlig är bael'dun digsite","är bael'dun tryggt"}}},fp="16,204,22.377.0,26.336.0,35.274.0,52.237.0,55.129.0,59.195.0"}
P.entries["subzone:bael-dun-keep"] = {n="Bael'dun Keep",s="Dvärgstyrkor håller Bael'dun Keep ovanför utgrävningen vid Bael Modan i södra Barrens. Under general Twinbraid förankrar denna imponerande befästning Alliansens omstridda närvaro i regionen och leder till våldsamma konflikter med de omgivande hordterritorierna.",h="Dvärgstyrkor håller Bael'dun Keep ovanför utgrävningen vid Bael Modan i södra Barrens.",kw={"bael modan","bael'dun keep","baeldun","explorers' league","gann stonespire","general twinbraid","haggis boatmurder","southern barrens"},ang={["faction:Alliance"]="Bael'dun Keep är ditt främsta militära fäste i södra Barrens och skyddar Explorers' Leagues viktiga upptäckter mot fientliga hordstyrkor.",["race:Tauren"]="Bael'dun Keep ligger på mark som tagits från Stonespire-stammen, en påminnelse om Alliansens intrång i ditt hemland."},sec={{t="Ett dvärgfäste i Kalimdor",b="Bael'dun Keep reser sig över utgrävningen vid Bael Modan och utgör den befästa militära kärnan i Ironforges närvaro i södra Barrens. Den dvärglika arkitekten Haggis Boatmurder ritade fästet för att skydda Prospektörerna och arkeologerna som söker efter forntida titanar­tefakter i schakten. Smidesverk och artilleri rustar garnisonen, som håller vakt, säkrar dvärgarnas försörjningslinjer och visar upp Alliansens militära styrka i Kalimdors inland."},{t="En krutdurk för blodspillan",b="Fästet och den intilliggande utgrävningsplatsen trängde undan den lokala taurenstammen Stonespire från deras förfäders hem. Bael'dun förblir en oroshärd i Barrens, och närliggande hordutposter ser det som ett uppenbart militärt intrång. Gann Stonespire utkämpar ett personligt hämndkrig mot inkräktarna. Förbittrade taurer, opportunistiska spejare och misstänksamma utposter som Camp Taurajo håller fästningen hotad av räder och sabotage."}},faq={{q="Vem kontrollerar Bael'dun Keep?",a="Dvärgsoldater bemannar Bael'dun Keep under Alliansen och Ironforges Explorers' League. Deras ståndaktige befälhavare är general Twinbraid.",al={"vem styr bael'dun keep","vem leder baeldun","general twinbraid"}},{q="Varför byggdes Bael'dun Keep i södra The Barrens?",a="Alliansen upprättade Bael'dun Keep för att försvara Bael Modan, en väldig arkeologisk expedition som söker titanklenoder och dvärgarnas forntida ursprung i Kalimdor.",al={"varför finns dvärgar i the barrens","bael'dun keeps syfte","varför byggde dvärgarna här"}},{q="Varför anfaller de lokala taurerna Bael'dun Keep?",a="Utgrävningen och fästningen trängde undan Stonespire-taurerna från deras förfäders marker. Överlevande som Gann Stonespire söker hämnd och vill förgöra de invaderande dvärgarna.",al={"gann stonespires hämnd","varför hatar taurerna baeldun","konflikten med stonespire"}},{q="Vem var fästningens arkitekt?",a="Dvärgarnas arkivhandlingar anger Haggis Boatmurder som arkitekten som ritade och byggde fästningen.",al={"vem byggde bael'dun keep","haggis boatmurder","baelduns ritningar"}}},fx={c3860f97={q="Vad är Bael'dun Keep?",a="Bael'dun Keep är en kraftigt befäst dvärgisk fästning som byggts i södra The Barrens. Den tornar upp sig över utgrävningsplatsen Bael Modan och fungerar som militärt högkvarter och försvarsankare för prospektörer och soldater som skickats dit av Explorers' Guild och Alliance. Bakom stenmurar och artilleri skyddar dvärgarna sina pågående arkeologiska utgrävningar och säkrar ett väpnat fäste mitt i Kalimdor.",al={"bael'dun keep","bael'dun-fästningen","vad är bael modan keep"}},["5592ca31"]={q="Vad hände vid Bael'dun Keep?",a="Dvärgiska expeditionsstyrkor trängde djupt in i The Barrens för att gräva fram forntida titanartefakter. De tog höjderna vid Bael Modan och byggde den befästa borgen. Därmed drev deras utgrävningar och militära närvaro våldsamt bort den inhemska taurenstammen Stonespire från dess heliga förfädersmarker. Det utlöste en öppen och bitter konflikt, och de överlevande tauren sökte hjälp från Horde för att slå tillbaka och förstöra fästningen.",al={"bael'duns historia","bael'dun keeps historia","vad hände vid bael'dun"}},["223c6b8e"]={q="Är Bael'dun Keep farligt?",a="Ja, särskilt om du svurit trohet till Horde. Bael'dun Keep är bemannat av tungt beväpnade dvärgiska gevärsskyttar, officerare och vaktposter under befäl av General Twinbraid. De är aggressivt fientliga mot alla inkräktare från Horde som närmar sig utgrävningen. Med sina starka försvarsmurar, tunga vapen och samlade eldkraft från Alliance innebär det att du riskerar att bli skjuten direkt om du går nära portarna.",al={"är bael'dun farligt","hoten vid bael'dun keep","är bael modan fientligt"}}},fp="13,221,32.398.0,25.426.0,27.120.0,51.152.0,49.179.0,38.106.0"}
P.entries["subzone:bael-modan"] = {n="Bael Modan",s="Dvärgarnas arbetslag spränger sig in i den röda jorden vid Bael Modan i jakt på titanförmål. Deras befästa utpost har drivit bort Stonespire-tauren från deras heliga mark och tänt en bitter strid.",h="Dvärgarnas arbetslag spränger sig in i den röda jorden vid Bael Modan i jakt på titanförmål.",kw={"bael modan","bael'dun","utgrävning i barrens","feegly","gann stonespire","stonespire","tear of the moons","twinbraid"},ang={["race:Dwarf"]="Som dvärg ser du hur Explorers' League arbetar vidare för att avslöja titanhistoria. Dess befälhavares hårda metoder har väckt de lokala stammarnas starka hat.",["race:Tauren"]="Som tauren ser du Bael Modan som ett öppet sår, byggt över Stonespire-stammens heliga mark. Att hjälpa Gann Stonespire att utkräva hämnd hedrar stammen."},sec={{t="Uppgrävda hemligheter och blodsutgjutelse",b="Bael Modans murar skyddar Bael'dun Keep, belägringskanoner, landningsplattor för gyrokoptrar och en djup utgrävningsgrop. Dvärgarnas guldgrävare kom till Kalimdor övertygade om att en uråldrig titanb anläggning låg under den röda jorden. Deras sprängningar slet sönder Stonespire-taurernas heliga mark. Expeditionen svarade inte på någon uppmaning att förhandla. Skottlossning och sprängämnen drev stammen från dess förfäders marker och lämnade överlevande utspridda och hämndlystna."},{t="Priset för uppgrävda reliker",b="Grävarna har grävt fram mer än gammalt stenarbete. Bland fynden finns Tear of the Moons, en artefakt som ingjuter paranoia och vansinne hos dem som kommer nära den. Feegly the Exiled, en guldgrävare som förvisats från lägret, föll helt under dess inflytande. När stenen åter hamnade i hans händer blev han en trogg. Utanför portarna söker rasande taurer hämnd, medan dödliga reliker hotar dvärgarna där inne."}},faq={{q="Varför gräver dvärgar i Barrens?",a="Dvärgarnas arbetslag söker efter uråldriga titanstrukturer och reliker begravda under jorden på Kalimdor. De tror att begravda titaniska forskningsanläggningar rymmer ledtrådar till deras folks ursprung.",al={"varför är dvärgar här","bael modans syfte","vad gräver dvärgarna efter"}},{q="Vad hände med taurenerna som bodde här?",a="Stonespire-stammen betraktade en gång dessa kullar som helig mark. När dvärgarna kom sprängde de upp utgrävningsplatsen med sprängämnen, dödade några taurer och drev bort andra medan de förstörde deras by.",al={"stonespire-taurener","vem bodde i bael modan","taurenby"}},{q="Vem är Gann Stonespire?",a="Gann Stonespire är en av de få överlevande från Stonespire. Efter att fredliga försök misslyckats slog han läger vid vägen utanför Bael Modan och uppmanar resande från Horde att sabotera dvärgarnas flygmaskiner och döda officerarna som förstörde hans folks hem.",al={"gann","gann uppdragsgivare"}},{q="Vad är Tear of the Moons?",a="Tear of the Moons är en mystisk artefakt som grävts fram av utgrävarna. Den driver dödliga som hanterar den till vansinne, och den förvisade dvärgen Feegly är besatt av att återta den.",al={"tear of the moons-relik","feeglys artefakt"}}},fx={["85aa09cd"]={q="Vad är Bael Modan?",a="Bael Modan är en kraftigt befäst dvärgisk utgrävningsplats och fästning i de södra delarna av The Barrens. Området domineras av mäktiga befästningar, väldiga kanoner och stora mekaniska grävmaskiner. Explorer's League grundade anläggningen för att gräva fram forntida titanmysterier begravda djupt under marken. Den är Alliance främsta bas för makt och arkeologiska ambitioner i regionen.",al={"information om bael modan","vad är det här för plats, bael modan","dvärgbas i södra the barrens"}},["8ce94b36"]={q="Vad hände vid Bael Modan?",a="Innan dvärgarna anlände var dessa marker Stonespire-taurenernas förfädersområde. Drivna av arkeologiska ambitioner rev dvärgiska expeditionsstyrkor upp jorden med kraftiga sprängämnen och belägringsmaskiner. Intrånget utlöste en våldsam konflikt som ödelade den fredliga stammen Stonespire, skingrade de överlevande och förvandlade de heliga markerna till en aktiv, befäst krigszon, genomsargad av gruvschakt.",al={"bael modans historia","vad hände här vid bael modan"}},f7e6e142={q="Vem styr Bael Modan?",a="Fästningen och de arkeologiska utgrävningarna står under gemensam ledning av militära officerare från Ironforge och prospektörer. Bland de viktigaste ansvariga finns General Twinbraid, Heggin Stonewhisker, Prospector Khazgorm, Malgin Barleybrew, Captain Gerogg Hammertoe och den berömde flygmaskinspiloten Lord Cyrik Blackforge.",al={"vem leder bael modan","bael modans ledare","vem styr bael modan"}},e130d5b0={q="Är Bael Modan farligt?",a="Ja, särskilt om du går under Horde fana. Dvärgarna som är förlagda här är på högsta beredskap och har gevärsgrupper, belägringsmaskiner, flygmaskiner och väldiga befästningar. Dessutom riskerar deras underjordiska utgrävningar att störa begravda reliker och flyktiga förbannelser som bäst får förbli glömda i jordens djupaste mörker.",al={"faror vid bael modan","är bael modan fientligt","kan jag ta mig till bael modan"}}},fp="10,184,31.416.0,29.390.1,39.175.0,50.208.0,23.254.0,30.168.1"}
P.entries["subzone:bal-lal-ruins"] = {n="Bal'lal Ruins",s="Bal'lal Ruins är urgamla Gurubashi-ruiner längs den nordvästra kusten av Stranglethorn Vale, strax norr om Grom'gol Base Camp. De förfallna stenmurarna står ovanför Vile Reefs grumliga vatten och är nu bebodda av fientliga Bloodscalp-troll.",h="Bal'lal Ruins är urgamla Gurubashi-ruiner längs den nordvästra kusten av Stranglethorn Vale, strax norr om...",kw={"bal'lal ruins","bloodscalp","grom'gol","gurubashi","stranglethorn vale","the vile reef"},ang={["faction:Horde"]="De fientliga Bloodscalp-trollen vid Bal'lal, en bit längs kusten från Grom'gol Base Camp, är ett ständigt säkerhetsbekymmer för Hordens patruller längs stranden.",["race:Troll"]="För Darkspear-troll som står på Hordens sida är platser som Bal'lal en allvarlig påminnelse om det forna Gurubashi-imperiets glans, vars ruiner nu hålls av kusinstammar förblindade av obeveklig blodtörst."},sec={{t="En förfallen utpost vid revet",b="Bal'lal Ruins ligger vid kusten norr om Grom'gol Base Camp och är ännu en rest av det sönderslagna Gurubashi-imperiet. Platsen var en gång del av den storslagna trollcivilisation som dominerade södra Azeroth, men har förfallit till mossiga stenmurar och sprucken sten. Ruinerna ligger precis intill Vile Reef och blickar ut över de förrädiska grunda kustvattnen. I dag håller aggressiva Bloodscalp-troll till på platsen och försvarar sina förfäders slitna reliker mot inkräktare."}},faq={{q="Vem kontrollerar Bal'lal Ruins?",a="Ruinerna är för närvarande bebodda av medlemmar ur Bloodscalp-stammen, som aggressivt vaktar området mot främlingar, resenärer och rivaler.",al={"vem bor här","fiender i bal'lal ruins","vem finns vid bal'lal ruins"}},{q="Var ligger Bal'lal Ruins?",a="Du hittar dem längs Stranglethorn Vales nordvästra kust, precis norr om Grom'gol Base Camp, med utsikt över Vile Reef.",al={"bal'lal ruins läge","var ligger bal'lal ruins","hitta bal'lal ruins"}},{q="Vilken historia har ruinerna?",a="Precis som de flesta stenbyggnader utspridda över Stranglethorn Vale härstammar Bal'lal Ruins från det urgamla Gurubashi-imperiet, innan det splittrades i rivaliserande djungeltrollstammar.",al={"bal'lal-historia","bal'lal ruins historia","vem byggde bal'lal ruins"}}},fp="13,159,31.384.0,27.110.0,36.120.0,33.107.0"}
P.entries["subzone:balia-mah-ruins"] = {n="Balia'mah Ruins",s="Balia'mah Ruins är de mossklädda resterna av en urgammal Gurubashi-bosättning i norra Stranglethorn Vale. Öster om Grom'gol Base Camp, på andra sidan floden, ligger de sönderfallande stenterrasserna som nu intagits och bevakas av krigare från den fientliga trollstammen Skullsplitter.",h="Balia'mah Ruins är de mossklädda resterna av en urgammal Gurubashi-bosättning i norra Stranglethorn Vale.",kw={"balia'mah","baliamah","gurubashi","ruiner","skullsplitter","stranglethorn"},ang={["faction:Horde"]="Skullsplitters fientliga läge vid Balia'mah, precis på andra sidan floden från Grom'gol Base Camp, utgör ett ständigt hot mot Hordens spejare och försörjningslinjer.",["race:Troll"]="För Darkspear är det en påminnelse om den stolta Gurubashi-civilisation som deras förfäder delade, liksom om den mörka fraktionsstrid som slet isär djungeltrollens samhälle, att vandra längs dessa urgamla stenterrasser."},sec={{t="Ett splittrat arv",b="Liksom många av stenbyggnaderna som ligger utspridda i djungeln är Balia'mah en rest av det vidsträckta Gurubashi-imperiet, som en gång härskade över stora delar av södra Eastern Kingdoms. Efter deras urgamla huvudstads fall splittrades Gurubashis territorium i stridande fraktioner. I dag tjänar ruinerna som ett fäste för stammen Skullsplitter, som häftigt försvarar stenterrasserna mot kringströvande bestar, närliggande ogres från Mosh'Ogg mound och alla utomstående som är dumdristiga nog att korsa floden."}},faq={{q="Var ligger Balia'mah Ruins?",a="Ruinerna ligger i norra Stranglethorn Vale, öster-sydöst om Hordens utpost Grom'gol Base Camp på andra sidan floden och sydväst om Mosh'Ogg Ogre Mound.",al={"balia'mah-ruinernas läge","var ligger balia'mah","karta över balia'mah ruins"}},{q="Vem kontrollerar ruinerna just nu?",a="Ruinerna är för närvarande ockuperade av stammen Skullsplitter, en fientlig fraktion av djungeltroll som aggressivt vaktar de urgamla stenterrasserna.",al={"vem bor i balia'mah","vilka fiender finns i balia'mah","balia'mahs fiender"}},{q="Vad är Balia'mahs historia?",a="Anläggningen byggdes under Gurubashi-imperiets storhetstid. Efter imperiets sammanbrott förföll platsen och återtogs så småningom av djungelns växtlighet och överlevande trollstammar.",al={"balia'mahs historia","vem byggde balia'mah"}},{q="Har Skullsplitters vid Balia'mah band till andra trolläger?",a="Ja. Stammen Skullsplitter har flera läger och ruiner i norra och centrala Stranglethorn Vale, där de ständigt utkämpar territoriella strider mot rivaliserande stammar som Bloodscalp.",al={"skullsplitters i stranglethorn","skullsplitters i balia'mah"}}},fp="15,193,20.328.0,38.153.0,33.81.0,33.163.0,67.174.0"}
P.entries["subzone:balnir-farmstead"] = {n="Balnir Farmstead",s="Balnir Farmstead är en övergiven gård i östra Tirisfal Glades, nordost om Ruins of Lordaeron. Balnirfamiljen brukade en gång marken, men nu ligger den i ruiner och hemsöks av kringströvande Scourge som tar sig förbi The Bulwark.",h="Balnir Farmstead är en övergiven gård i östra Tirisfal Glades, nordost om Ruins of Lordaeron.",kw={"balnir","gård","lejongap","tirisfal"},ang={["class:Mage"]="Forsaken-magiker skickas till dessa pestdrabbade marker för att samla in överlevande Balnir Snapdragons och studera dem för att upptäcka Scourges kvardröjande magiska fördärv.",["race:Undead"]="För Forsaken är gården en bitter påminnelse om Lordaeron som de förlorade, och dessutom en ständigt oroande säkerhetslucka där Scourge från Plaguelands smiter bakom The Bulwark."},sec={{t="En gård före pesten",b="I generationer brukade Balnirfamiljen sin gård bland kullarna i östra Tirisfal, och deras trädgård med snapdragons blommar fortfarande bland ruinerna. När Scourge svepte genom Lordaeron under det tredje kriget blev gården översvämmad och dess invånare försvann, så byggnaderna lämnades att förfalla."},{t="Ödeläggelse och Scourge-infiltration",b="Efter det tredje kriget fungerar ruinerna som ett fäste för tanklösa Scourge som smiter förbi The Bulwark. Forsaken-dödsvakter håller gården under vaksam uppsikt, medan magiker från Undercity skördar överlevande snapdragons i trädgården för att undersöka hur djupt pestens fördärv har trängt ner i jorden."}},faq={{q="Varför är Balnir Farmstead viktig?",a="Den ligger vid de östra tillfarterna till Tirisfal, precis bakom The Bulwark. Scourge som smiter förbi försvararna samlas här, och trädgårdens snapdragons låter Forsaken-magikerna mäta hur långt pesten har spridit sig i Tirisfal.",al={"balnir farmstead betydelse","varför besöka balnir farmstead"}},{q="Vilka bodde på gården före pesten?",a="Gården tillhörde Balnirfamiljen, som gav den dess namn. De gick under när Scourge svepte genom Tirisfal under det tredje kriget, och i dag är det bara de odöda som vandrar över åkrarna.",al={"vem ägde balnir farmstead","balnirfamiljen"}},{q="Varför håller Forsaken gården under uppsikt nu?",a="Tanklösa Scourge smiter ofta förbi The Bulwark från Plaguelands och samlas på gården, vilket hotar de östra tillfarterna till Tirisfal. Dessutom studerar forskare från Undercity de tåliga snapdragons som fortfarande växer i trädgårdarna för att mäta pestens spridning.",al={"varför bryr sig forsaken om balnir","lore om rear guard patrol","balnir snapdragons"}}},fx={["40268029"]={q="Vad är Balnir Farmstead?",a="Balnir Farmstead är en förfallen egendom i östra Tirisfal Glades, strax nordost om Ruins of Lordaeron. Innan kungariket föll var den ett fridfullt lanthem för familjen Balnir. I dag ligger den i ruiner och hemsöks, övervuxen av vilda lejongap och översvämmad av kringströvande odöda.",al={"vad är balnir farmstead","balnir-gården","om balnir farmstead"}},decbf492={q="Vad hände vid Balnir Farmstead?",a="När Scourge svepte genom Tirisfal under det tredje kriget blev gården översvämmad av odöda och familjen Balnir gick förlorad. I dag samlas tanklösa odöda bland ruinerna efter att ha smitit förbi The Bulwark.",al={"balnir farmsteads historia","vad hände här"}},["037a698c"]={q="Varför ligger Balnir Farmstead i ruiner?",a="Gården ödelades under Lordaerons härjningar, när de odöda invaderade östra Tirisfal. Ägarna, familjen Balnir, gick förlorade i angreppet. Byggnaderna lämnades att förfalla och markerna togs över av kringströvande andar och fasor från de närliggande Plaguelands.",al={"varför ligger balnir i ruiner","varför är balnir farm övergiven","vad förstörde balnir farmstead"}},["05134e04"]={q="Är Balnir Farmstead farligt?",a="Ja. Det är en fristad för rastlösa odöda och kringströvande andar som tar sig förbi The Bulwark från Western Plaguelands. Blödande fasor och hämndlystna vålnader stryker omkring på de igenvuxna fälten och bland de förfallna uthusen. Området utgör ett ständigt hot mot resande längs den östra vägen.",al={"är balnir farm farlig","faror vid balnir farmstead","hot vid balnir farm"}},["55c3446e"]={q="Varför heter platsen Balnir Farmstead?",a="Marken har fått sitt namn från familjen Balnir, de mänskliga bönder som brukade egendomen i generationer tills de gick förlorade när Scourge invaderade Tirisfal under det tredje kriget.",al={"varför heter platsen balnir","balnir farmsteads namns ursprung","vilka är familjen balnir"}}},fp="16,165,24.263.0,35.263.0,38.241.0,45.185.0,45.265.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="Ban'ethil Barrow Den",s="Ban'ethil Barrow Den är en helig underjordisk fristad, uthuggen bland Teldrassils rötter. Den skapades ursprungligen som viloplats åt de sovande Druids of the Talon, men grottkomplexet har nyligen kastats in i kaos. De fördärvade furbolgerna i Gnarlpine-stammen har tagit över dess salar och förvandlat en plats för fridfull sömn till ett farligt vansinnesnäste.",h="Ban'ethil Barrow Den är en helig underjordisk fristad, uthuggen bland Teldrassils rötter.",kw={"ban'ethil","barrow den","druids of the talon","emerald dream","furbolg","gnarlpine","teldrassil"},ang={["class:Druid"]="Ban'ethil är helig mark för Cenarion Circle och byggdes särskilt för att skydda Druids of the Talon när de förenar sig med Emerald Dream.",["race:NightElf"]="Att de fördärvade Gnarlpine-furbolgerna har tagit över Ban'ethil är ett oroande tecken på den växande sjukdom som plågar deras nya hem, Teldrassil."},sec={{t="En vanhelgad fristad",b="Barrow Dens är heliga vilokammare där nattalvernas druider sover medan deras andar färdas i Emerald Dream. Ban'ethil Barrow Den vigdes särskilt åt att skydda Druids of the Talon när de förenade sig med naturen. Den underjordiska hålan är uppdelad i övre och nedre kammare och genljöd en gång av fridfull dröm och djup meditativ magi. Men den plåga som sveper över Teldrassils djurliv skonade inte Gnarlpine-furbolgerna. De invaderade komplexet och förvandlade dess uthuggna salar till ett befäst näste."},{t="Gnarlpine-stammens intrång",b="Gnarlpine-stammen drevs till vansinne av en mystisk korruption som fått fäste över hela World Tree och jagade bort eller hotade de sovande druiderna i Ban'ethil. Furbolgerna vaktar nu de slingrande tunnlarna med våldsamhet och går till angrepp mot alla nattalver som närmar sig. För Teldrassils försvarare är det brådskande att återta barrow den, både för att driva bort de fientliga furbolgerna och för att skydda druiderna och de heliga reliker som är fångade i hålans nedre djup."}},faq={{q="Vad är Ban'ethil Barrow Den?",a="Ban'ethil Barrow Den är en underjordisk håla i Teldrassil, skapad av nattalverna. Den byggdes för att skydda sovande Druids of the Talon medan deras andar vandrade i Emerald Dream.",al={"vad är ban'ethil","ban'ethil barrow den syfte","vad är den här grottan"}},{q="Varför finns det furbolger i Ban'ethil Barrow Den?",a="Gnarlpine-furbolgerna har fallit offer för en korruption som sprider sig bland Teldrassils varelser. De blev fientliga och revirhävdande, invaderade barrow den, trängde undan väktarna och hotar de sovande druiderna.",al={"varför finns gnarlpine i ban'ethil","furbolger i barrow den","vem tog över ban'ethil"}},{q="Vilka delar består barrow den av?",a="Grottkomplexet är uppdelat i två huvudsakliga, sammanlänkade nivåer: Upper Den nära ingångspassagerna och Lower Den längre in bland de underjordiska rötterna.",al={"ban'ethils utformning","upper den lower den","ban'ethils nivåer"}},{q="Varför är barrow dens så viktiga för druider?",a="Barrow dens ger tryggt fysiskt skydd åt druider som går in i djup, långvarig sömn för att sända sitt medvetande till Emerald Dream. Deras vakna kroppar lämnas hjälplösa i åratal eller årtionden.",al={"varför sover druider i gravhögar","lore om druidernas barrow dens","emerald dream barrow den"}}},fx={["129d8c28"]={q="Vad hände vid Ban'ethil Barrow Den?",a="Ban'ethil Barrow Den byggdes av nattalverna som en helig tillflyktsort för att hysa sovande Druids of the Talon. Den skulle vara en stillsam fristad. Men nyligen tog sig en förvridning in bland de inhemska furbolgarna från stammen Gnarlpine. Galna av förvridningen stormade de gravhögarna och gjorde lyan till sin, drev bort nattalverna och vanhelgade de heliga hålorna.",al={"ban'ethil barrow dens historia","vad hände vid ban'ethil","berättelsen om ban'ethil barrow den"}},["698c9749"]={q="Varför övergavs Ban'ethil Barrow Den?",a="Nattalverna övergav inte gravhögen frivilligt; den togs med våld. När stammen Gnarlpine föll för förvridningen invaderade de fristaden i stort antal. De sovande druiderna och deras vårdare kunde inte behålla kontrollen, och de fientliga furbolgarna tog över både den övre och den nedre lyan helt.",al={"varför är ban'ethil övergiven","varför lämnade druiderna ban'ethil","ban'ethil barrow den översvämmad"}},["9b622bd1"]={q="Är Ban'ethil Barrow Den farligt?",a="Det är extremt farligt att gå in ensam. De slingrande tunnlarna i både Upper Den och Lower Den myllrar av aggressiva, förvridna furbolgar från Gnarlpine. De trånga underjordiska gångarna och de galna bestarnas starka revirinstinkt gör att en oförsiktig resande lätt kan bli omringad och övermannad.",al={"är ban'ethil barrow den farligt","hur farligt är ban'ethil","faror vid ban'ethil"}}},fp="20,265,19.441.0,23.381.0,29.170.0,51.182.0,40.144.0,43.186.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="Ban'ethil Hollow",s="Ban'ethil Hollow är en karg ravin som skär genom skogen strax söder om huvudvägen mellan Dolanaar och Darnassus. Den har blivit en farlig tillflyktsort för fördärvade, aggressiva furbolger som ständigt hotar resande. Längst in i ravinen ligger ingången till Ban'ethil Barrow Den.",h="Ban'ethil Hollow är en karg ravin som skär genom skogen strax söder om huvudvägen mellan Dolanaar och...",kw={"överfall","ban'ethil barrow den","ban'ethil hollow","darnassus","dolanaar","furbolg","ravin","teldrassil"},ang={["class:Druid"]="Ravinen döljer ingången till Ban'ethil Barrow Den, helig mark där druider traditionellt vilar för att komma i kontakt med The Emerald Dream, nu hotad av rabiata vilddjur.",["race:NightElf"]="Att se furbolgerna bli vansinniga så nära vägen mellan Dolanaar och Darnassus är ett dystert tecken på att Teldrassils sjukdom förvärras. Unga väktare och druider måste ingripa."},sec={{t="En farlig ravin",b="Ban'ethil Hollow ligger vid vägen mellan Dolanaar och Darnassus och påminner skarpt om att Teldrassils grenar inte är helt trygga. Furbolger som drivits till vansinne av den märkliga plåga som drabbat världsträdet har tagit sin tillflykt längs den steniga sluttningen. De smyger ofta längs den närbelägna stigen och väntar på att överfalla oförsiktiga kurirer och vandrande väktare. Djupt inne i ravinen ligger ingången till Ban'ethil Barrow Den, där sovande druider och gamla tunnlar hotas av de vansinniga bestarna utanför."}},faq={{q="Var ligger Ban'ethil Hollow?",a="Ban'ethil Hollow är en ravin mitt på Teldrassil, strax söder om huvudvägen mellan byn Dolanaar och huvudstaden Darnassus.",al={"banethil hollow plats","var ligger ban'ethil hollow","hitta banethil hollow"}},{q="Varför är furbolgerna här fientliga?",a="Furbolgerna över hela Teldrassil har dukat under för en spridande korruption och det vansinne som gripit världsträdets djurliv. I stället för att leva fredligt sida vid sida med nattalverna, som de gjort sedan gammalt, har dessa stammar blivit våldsamt revirhävdande och våldsamma.",al={"varför är furbolger vansinniga","fientliga furbolger banethil","furbolger anfaller banethil"}},{q="Vad finns i Ban'ethil Barrow Den längst in i ravinen?",a="Ban'ethil Barrow Den är ett underjordiskt komplex som nattalvsdruider sedan gammalt har använt för att gå i djup dvala och komma i kontakt med The Emerald Dream. Men i takt med att korruptionen sprider sig i ravinen har hålan blivit en farlig plats.",al={"vad finns i gravhögen","banethil barrow den","gravhåla i banethil hollow"}},{q="Är vägen ovanför ravinen trygg att färdas på?",a="Huvudvägen patrulleras vanligtvis av nattalvsväktare, men furbolger från Ban'ethil Hollow tar sig ofta upp från ravinen för att överfalla resande. Den som färdas mellan Dolanaar och Darnassus bör vara på sin vakt.",al={"är vägen säker","furbolgeröverfall","är vägen till darnassus säker"}}},fx={fa7d6d41={q="Vad är Ban'ethil Hollow?",a="Ban'ethil Hollow är en avskild, nedsänkt ravin uthuggen i centrala Teldrassil, strax söder om huvudvägen mellan Dolanaar och Darnassus. Ravinen domineras av tät växtlighet och branta sluttningar och är ett läger för förvridna furbolgar. Längst in ligger ingången till den vidsträckta Ban'ethil Barrow Den.",al={"ban'ethil hollow","vad är det här för plats","översikt över ban'ethil hollow"}},["5004ddfb"]={q="Vem bor i Ban'ethil Hollow?",a="Ravinen har tagits över av aggressiva, förvridna furbolgar. De var en gång fredliga grannar till nattalverna, men har fallit i galenskap och blivit fientliga. Nu gör de ravinen till sitt revir och hotar alla som färdas i närheten.",al={"vem bor här","invånare i ban'ethil hollow","vilka bor i ban'ethil hollow"}},f75c8a95={q="Är Ban'ethil Hollow farligt?",a="Det är extremt farligt. Ravinen myllrar av fientliga furbolgar som försvarar den ursinnigt. Resande på huvudvägen strax ovanför faller ofta offer för bakhåll från ravinens kanter, så området är farligt även för dem som bara passerar och inte går ner.",al={"hur farligt är ban'ethil hollow","är ban'ethil hollow tryggt","faror i ban'ethil hollow"}}},fp="16,172,17.448.0,34.109.0,34.201.0,66.210.0,44.167.0"}
P.entries["subzone:bandarion-keep"] = {n="Bandarion Keep",s="Bandarion Keep är en befäst utpost med koppling till Tyr's Watch, belägen i västra Tirisfal Glades nära Whispering Forest. Den har fått sitt namn till ära för Garek Bandarion och fungerar som en isolerad försvarspost bland de kvarvarande hoten vid skogsgränsen. Försvararna möter allt från fientliga kustmurlocer till kringströvande fanatiker och instabila odöda.",h="Bandarion Keep är en befäst utpost med koppling till Tyr's Watch, belägen i västra Tirisfal Glades nära...",kw={"bandarion","bandarion keep","garek bandarion","jorin croge","tirisfal","tyr's watch","whispering forest"},ang={["class:Paladin"]="För heliga krigare som möter den kalla verkligheten i odöden är Bandarion Keep både en fristad och en varning: vissa paladiner som inte kan förlika Ljuset med sin odöda tillvaro har brutit samman och vänt sina vapen mot sina Fördömda fränder.",["race:Undead"]="Fästningen ligger långt västerut i Tirisfal och visar att de Fördömda måste vara vaksamma, inte bara mot Scourge och Scarlet Crusade, utan också mot oron inom de egna leden."},sec={{t="En bastion vid västgränsen",b="Bandarion Keep ligger nära det avskilda Whispering Forest i västra Tirisfal Glades och står som en ensam väktare för de Fördömda. Fästningen är uppkallad efter Garek Bandarion och har nära band till Tyr's Watch. Kvartermästare som Jorin Croge arbetar hårt för att hålla garnisonen försörjd, trots dess avlägsna och utsatta läge långt från Undercitys livliga gårdar."},{t="Omgiven av hot",b="Att hålla fästningen är inget lugnt uppdrag. Utposten hotas ständigt av Vile Fin-murlocernas räder längs de närliggande vattnen, sonderande skärmytslingar med Scarlet Crusade och kringirrande, själlösa Scourge-trälar som släpar sig genom dunklet. Än värre är de inre farorna: vissa paladiner som kämpar med att finna sig till rätta i sin odöda tillvaro som Fördömda har drabbats av vansinne och vänt sina vapen mot sina egna."}},faq={{q="Var ligger Bandarion Keep?",a="Bandarion Keep ligger i den avlägsna vildmarken längst västerut i Tirisfal Glades, nära det gåtfulla Whispering Forest.",al={"bandarion keeps läge","var ligger bandarion keep","hur hittar man bandarion keep"}},{q="Vem har Bandarion Keep fått sitt namn efter?",a="Fästningen har fått sitt namn till ära för Garek Bandarion, en framstående person med koppling till orden som är stationerad där.",al={"vem är bandarion","garek bandarion","bandarion keeps namnets ursprung"}},{q="Vad är Tyr's Watch?",a="Tyr's Watch är namnet som förknippas med Bandarion Keep och de Fördömdas paladiner som håller det. Fästningen räknas till Tyr's Watch, och de två namnen används ofta omväxlande.",al={"tyrs watch","vad är tyrs watch"}},{q="Vilka faror hotar fästningen?",a="Fästningens försvarare slår regelbundet tillbaka Vile Fin-murlocer, strider mot Scarlet Crusades fanatiker, gör sig av med kringirrande, själlösa Scourge och oskadliggör instabila Fördömda paladiner som förlorar förståndet och angriper sina egna allierade.",al={"vem anfaller bandarion keep","hot mot bandarion keep","bandarions fiender"}}},fx={c054e935={q="Vem bor i eller styr Bandarion Keep?",a="Bandarion Keep är bemannat av medlemmar i Tyr's Watch. Bland dem som sköter bastionen finns Jorin Croge, som övervakar försörjningen och ser till att garnisonen har tillräckligt med förnödenheter trots hoten i omgivningen.",al={"vem styr bandarion keep","invånare i bandarion keep","vem finns i bandarion keep"}},a6af85d6={q="Vad är Bandarion Keep?",a="Bandarion Keep är en fästning som hålls av Tyr's Watch, nära den mystiska Whispering Forest i västra Tirisfal Glades. Den fungerar som utpost i en stillsam men farlig del av regionen och hyser Forsaken som håller vakt långt från Undercitys hjärta.",al={"vad är bandarion keep","information om bandarion keep","om bandarion keep"}}},fp="14,173,31.271.0,21.349.0,32.74.0,35.49.0,20.171.0,31.214.0"}
P.entries["subzone:baradin-bay"] = {n="Baradin Bay",s="Baradin Bay är det vidsträckta vattenområdet mellan Khaz Modans, Wetlands, Arathi Highlands och södra Lordaerons kuster. Under andra kriget patrullerades bukten intensivt av Kul Tiras mäktiga flotta, men nu döljer vattnen förrädiska rev, sjunkna krigsskepp och fientliga rovdjur.",h="Baradin Bay är det vidsträckta vattenområdet mellan Khaz Modans, Wetlands, Arathi Highlands och södra...",kw={"baradin bay","the drowned reef","great sea","kul tiras","the lost fleet","menethil harbor","southshore","wetlands"},ang={["faction:Alliance"]="Baradin Bay är den livsviktiga sjövägen mellan Alliances verksamhet i Khaz Modan och dess utposter i Arathi och Hillsbrad, men marina faror och sjunkna vrak gör varje överfart riskfylld.",["race:Human"]="För människor, särskilt dem som härstammar från Kul Tiras eller Lordaeron, är bukten helig och sorgtyngd mark där sjömän från andra kriget fått sin grav i havet."},sec={{t="En strategisk farled",b="Med Dun Moroghs kuster i söder och Lordaerons i norr är Baradin Bay en viktig sjöväg mellan Eastern Kingdoms hamnar. Vid bukten ligger livliga hamnar som Menethil Harbor i Wetlands och Southshore i Hillsbrad Foothills. Men det är farligt att färdas här: grunda sandbankar, vassa rev och farlig fauna som murlocer, krokolisker och djuphavshajar hotar ständigt både sjömän och resenärer."},{t="Flottornas gravplats",b="Under andra kriget utkämpades hårda sjöslag i Baradin Bay, där Kul Tiras flottor drabbade samman med Horde. I dag ligger dystra minnen av striderna utspridda längs kusten och på havsbotten. De sönderslagna skroven från Kul Tiras tredje flotta, lokalt känd som The Lost Fleet, ligger halvt nedsänkta längs Wetlands kust, medan andra skepp störtat ner till The Drowned Reef. Fientliga andar, skattsökande bärgare och glupska havsbestar hemsöker nu vattnen kring dessa ruttnande trävrak."}},faq={{q="Vilka större hamnar ligger längs Baradin Bay?",a="De främsta bosättningarna längs buktens kust är Menethil Harbor i Wetlands och Southshore i Hillsbrad Foothills. De upprätthåller viktiga sjöförbindelser över havet.",al={"hamnar i baradin bay","vart leder baradin bay"}},{q="Varför finns det så många skeppsvrak längs buktens kust?",a="Vraket längs Wetlands kust är The Lost Fleet, Kul Tiras tredje flotta, som förstördes under andra kriget. Andra skepp har förlist på det förrädiska The Drowned Reef utanför Arathi-kusten.",al={"skeppsvrak i wetlands","varför har skepp sjunkit här","the lost fleets ursprung"}},{q="Vilka faror finns i Baradin Bays vatten?",a="De grunda vattnen kryllar av aggressiva murlocer och sumpkrokolisker, medan djupare vatten är fullt av rovkrabbor, hajar och rastlösa andar efter drunknade sjömän.",al={"monster i baradin bay","murlocer i baradin bay","är det säkert att simma i baradin bay"}},{q="Vilka områden gränsar till Baradin Bay?",a="Baradin Bay omges av nordvästra Dun Morogh, Wetlands sumpiga stränder, klipporna i Arathi Highlands och kusterna i södra Hillsbrad och Gilneas.",al={"vilka områden gränsar till baradin bay","baradin bays geografi"}}},fx={["3e0a5d97"]={q="Vad är Baradin Bay?",a="Baradin Bay är en vidsträckt havsvik vid Great Seas västra kust, mitt i Eastern Kingdoms. Vattnet sträcker sig från nordvästra Dun Morogh i Khaz Modan ända norrut mot de södra delarna av Gilneas och Hillsbrad. Viken är en viktig sjöväg mellan kungadömen som Stromgarde, Gilneas och Ironforges kustbesittningar, och Menethil Harbor ligger framträdande vid dess södra strand.",al={"översikt över baradin bay","var ligger baradin bay","vad är den här viken"}},["9b3de034"]={q="Är Baradin Bay farlig?",a="Det är långt ifrån säkert att ge sig ut på Baradin Bays vatten. De grunda kustvattnen kryllar av aggressiva murlocer och hungriga krokolisker, medan våldsamma hajar och jättekrabbor håller till på öppet, djupare vatten. Utöver naturens faror har förrädiska rev och kvardröjande sjöfararhot sänkt dussintals fartyg genom åren, och vattenfyllda faror lurar strax under ytan.",al={"hot i baradin bay","faror i baradin bay","är det säkert att simma i baradin bay"}}},fp="11,228,20.276.0,23.317.0,47.142.0,55.169.0,55.136.0,37.113.0"}
P.entries["subzone:bashal-aran"] = {n="Bashal'Aran",s="Bashal'Aran är en uråldrig Highborne-ruin i norra Darkshore, strax öster om Auberdine. Staden var en gång en blomstrande systerstad till Ameth'Aran före den stora Sunderingen. Nu kryllar den av demoniska satyrer och grells som livnär sig på kvarvarande magisk energi, medan en ensam alvande fortfarande hålls fången av en flera hundra år gammal förbannelse.",h="Bashal'Aran är en uråldrig Highborne-ruin i norra Darkshore, strax öster om Auberdine.",kw={"ameth'aran","asterion","athrikus narassin","bashal'aran","darkshore","deth'ryll","grell","highborne","satyr"},ang={["class:Mage"]="Månstenens skydd som binder Asterion visar hur skrämmande beständig och kraftfull Highbornes besvärjelsekonst är.",["race:NightElf"]="Bashal'Aran är en tragisk påminnelse om den vårdslösa arkaniska hybris som ledde till det uråldriga Kaldorei-imperiets fall och banade väg för demonisk korrumpering."},sec={{t="En delad tvillingstad",b="Innan den stora Sunderingen krossade det uråldriga Kalimdor för tiotusen år sedan bosatte drottning Azshara sina gynnade Highborne-undersåtar i tvillingstäderna Bashal'Aran och Ameth'Aran. Städerna styrdes av den mäktige magikern Athrikus Narassin och stoltserade med praktfulla marknader och tempel helgade åt Elune. När Evighetens brunn kollapsade ödelade katastrofen båda bosättningarna. Av skäl som gått förlorade i tiden använde Athrikus sin arkanska mästarförmåga för att binda sin närmaste medarbetare, magikern Asterion, i en månstenstalisman i Bashal'Aran. Även efter att hans fysiska kropp gått under förblev Asterions vålnad fjättrad vid den förstörda helgedomen."},{t="Demoniskt angrepp",b="I nutid har Bashal'Arans sönderfallna stenar tagits över av avskyvärda inkräktare: satyrerna Deth'ryll och de lekfulla grells. De dras till den kvarvarande magin som dröjer sig kvar i det uråldriga murverket, och dessa förvridna varelser suger i sig energin för att stärka sina vidriga konster. De svärmar över de sönderslagna gårdarna och terroriserar resande längs Darkshores skogsstigar, men demonerna håller sig på behörigt avstånd från den centrala helgedomen där Asterion uthärdar sin ändlösa vaka."}},faq={{q="Vad var Bashal'Aran innan staden förstördes?",a="Bashal'Aran var en storslagen Kaldorei-stad som drottning Azshara grundade åt sina gynnade Highborne-aristokrater före den stora Sunderingen. Tillsammans med tvillingstaden Ameth'Aran styrdes den av magikerherren Athrikus Narassin.",al={"bashal'arans historia","vem byggde bashal'aran","vad var den här ruinen"}},{q="Vem är vålnaden som vandrar i helgedomen?",a="Anden är Asterion, en respekterad Highborne-krigarmagiker som en gång hade uppsikt över både Bashal'Aran och Ameth'Aran. Han förråddes under mystiska omständigheter och bands till platsen med en månstenstalisman av sin ståthållare Athrikus Narassin. Fångenskapen fortsatte även efter hans död.",al={"vem är asterion","bashal'arans vålnad","varför finns det en vålnad"}},{q="Varför bor satyrer i ruinerna?",a="Satyrer och grells lockades till Bashal'Aran av resterna av den kraftfulla arkanmagi som de uråldriga Highborne lämnade efter sig. De frossar i dessa kvarvarande magiska utsöndringar för att stärka sin mörka demonmagi.",al={"varför finns det satyrer här","deth'ryll-satyrernas historia","grells i bashal'aran"}},{q="Hur hänger Bashal'Aran ihop med Ameth'Aran?",a="Bashal'Aran och Ameth'Aran var systerstäder som styrdes tillsammans under drottning Azsharas regeringstid. Asterion färdades ofta mellan bosättningarna för att ta hand om folkets behov, innan båda krossades av Sunderingen.",al={"kopplingen till ameth'aran","tvillingstäder i darkshore","ameth'aran och bashal'aran"}}},fx={["9019c4fd"]={q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig nattalvsruin i norra Darkshore. För länge sedan, innan den stora klyvningen slet sönder Kalimdor, var staden en välmående Highborne-stad med livliga basarer och ståtliga tempel tillägnade Elune. Tillsammans med tvillingstaden Ameth'Aran i söder vittnade den om höjdpunkten i den tidiga nattalvscivilisationen. I dag ligger den i ruiner, hemsökt och övervuxen av vild växtlighet, med kvarlevor av uråldrig arkana magi.",al={"vad är bashal'aran","översikt över bashal'aran","om bashal'aran"}},["3b163f6e"]={q="Vad hände med Bashal'Aran?",a="Under Kaldorei-imperiets tid slog drottning Azshara sig ned här med sina gynnade Highborne under ståthållaren Athrikus Narassin och hans löjtnant Asterion. När den första Evighetens brunn imploderade under den stora klyvningen för tiotusen år sedan förstördes staden fullständigt. Vid en okänd tidpunkt använde Athrikus ett månstenstätning för att med magi binda Asterion till en helgedom. Asterion dog, men hans vålnad blev för evigt fångad bland ruinerna långt efter att hans folk försvunnit.",al={"bashal'arans historia","bashal'aran i korthet","vad hände vid bashal'aran"}},["0673c761"]={q="Är Bashal'Aran farligt?",a="Ja. De sönderslagna stenbyggnaderna har tagits över av fientliga grells och vidriga Deth'ryll-satyrer. De demoniska varelserna dras till den kraftfulla arkanmagi som fortfarande sipprar ur de uråldriga Highborne-stenarna, och livnär sig på resterna för att stärka sin egen mörka magi. De fruktar och undviker den helgade helgedomen där vålnaden Asterion dröjer sig kvar, men angriper alla resenärer som ger sig in i ruinerna omkring den.",al={"är bashal'aran säkert","faror i bashal'aran","fiender i bashal'aran"}}},fp="11,144,21.565.0,19.349.0,45.202.0,38.187.0,36.164.0,42.202.0"}
P.entries["subzone:bathran-s-haunt"] = {n="Bathran's Haunt",s="Bathran's Haunt är en forntida kaldorei-ruin i nordvästra Ashenvale, öster om The Zoram Strand. Nyligen har Forsaken-örtmästare och deras väktare tagit över platsen för att samla in traktens växter till sin alkemiska forskning. Skogen runtomkring vissnar sakta.",h="Bathran's Haunt är en forntida kaldorei-ruin i nordvästra Ashenvale, öster om The Zoram Strand.",kw={"ashenvale","bathran's hair","bathran's haunt","forsaken","örtmästarkonst","kaldorei-ruiner","the ruins of ordil'aran","the zoram strand"},ang={["profession:Herbalism"]="Ruinerna är botaniskt unika som den enda kända växtplatsen för Bathran's Hair, en ört som eftersöks för sina sällsynta läkande egenskaper.",["race:NightElf"]="Forsakens läger vid Bathran's Haunt är en skymf mot kaldoreis arv. Odöda inkräktare vanhelgar forntida alviska stenar och skändar den heliga jorden."},sec={{t="En vanhelgad plats i forntida skogar",b="Norr om The Ruins of Ordil'Aran står vittrande Night Elf-pelare, uppslukade av Ashenvales täta växtlighet. Det som en gång var en fridfull kaldorei-relik har hamnat i Forsakens skugga. Bland den sönderslagna marmorn har odöda örtmästare och deras förkämpar satt upp ett enkelt laboratorium under bar himmel. Bara deras närvaro vanhelgar den forntida jorden: gräset ruttnar och blir sjukt brunt, livfulla blommor vissnar och ett onaturligt förfall sprider sig genom lunden medan de metodiskt samlar in sällsynta skogsingredienser till sina experiment."},{t="Skörden av Bathran's Hair",b="Den främsta lockelsen med ruinerna är Bathran's Hair, en unik medicinalväxt som bara slår rot bland just dessa stenar. Night Elf- och Alliance-spejare ser Forsakens närvaro som en avskyvärd skändning av helig alvisk jord, medan de odöda arbetar flitigt med att utvinna växtens kraftfulla egenskaper. Horde har ett starkt intresse av den botaniska skörden, men Forsakens hemlighetsfulla metoder och den förorening av jorden som följer väcker misstankar hos både utomstående och allierade."}},faq={{q="Var ligger Bathran's Haunt?",a="Bathran's Haunt ligger i nordvästra Ashenvale, precis norr om The Ruins of Ordil'Aran och inåt land öster om The Zoram Strand.",al={"var ligger bathran's haunt","bathran's haunt plats","hur tar man sig till bathran's haunt"}},{q="Varför är Forsaken här?",a="Forsaken-örtmästare har slagit läger och inrättat ett laboratorium bland ruinerna för att samla in och studera skogens unika växtliv, framför allt en sällsynt medicinalväxt som kallas Bathran's Hair.",al={"vad gör odöda i ashenvale","varför är forsaken vid bathran's haunt","forsakens syfte bathran"}},{q="Vad är Bathran's Hair?",a="Bathran's Hair är en särpräglad och värdefull ört med kraftfulla läkande egenskaper. Den växer enbart runt de vittrande stenarna vid Bathran's Haunt.",al={"bathran's hair växt","vad är bathran's hair","bathran ört"}},{q="Varför håller marken på att dö runt ruinerna?",a="Forsakens långvariga närvaro och alkemiska verksamhet har förorenat området närmast ruinerna. Gräset vissnar och blir brunt, och skogens skira blommor dör.",al={"varför är gräset brunt här","vanhelgad mark vid bathran's haunt","varför förfaller marken"}}},fx={["72c7f68d"]={q="Vad är Bathran's Haunt?",a="Bathran's Haunt är en uråldrig Kaldorei-ruin i nordvästra Ashenvale, norr om The Ruins of Ordil'Aran. Nattalverna övergav platsen för länge sedan. Nyligen har Forsaken-örtmedicinare och deras väktare slagit läger bland de sönderfallande marmorpelarna och igenvuxna gårdarna.",al={"bathran's haunt","vad är den här platsen","bathran's haunt i korthet"}},["43b0b094"]={q="Vem bor i eller styr Bathran's Haunt?",a="Ruinerna är för närvarande bebodda av Forsaken-örtmedicinare och inhyrda busar som har inrättat ett utomhuslaboratorium bland den uråldriga marmorn. De välkomnar medlemmar av Horde, men deras experiment och närvaro hålls under uppsikt, och Alliance-inkräktare drivs bort så fort de visar sig.",al={"vem kontrollerar bathran's haunt","vem bor i bathran's haunt","invånare i bathran's haunt"}},["0d907f15"]={q="Är Bathran's Haunt farligt?",a="Det är mycket farligt, särskilt för resenärer från Alliance. De Forsaken som är stationerade här är beväpnade, fientliga mot främlingar och utför onaturliga experiment. Även den omgivande jorden har vissnat och blivit brun under deras ockupation, ett tecken på en miljö som är djupt fientlig mot allt levande.",al={"faror i bathran's haunt","är bathran's haunt säkert","är det farligt här"}}},fp="15,182,38.425.0,29.375.0,33.124.0,26.174.0,23.141.0,41.132.0"}
P.entries["subzone:bay-of-storms"] = {n="Bay of Storms",s="Bay of Storms är en vidsträckt, stormpinad vik som skär in i Azsharas karga östra klippor. Dess virvlande vatten döljer forntida ruiner, översvämmade grottor och farliga havsbestar som gör sjöfarten längs kusten riskabel.",h="Bay of Storms är en vidsträckt, stormpinad vik som skär in i Azsharas karga östra klippor.",kw={"azshara","bay of storms","great sea","hetaera's clutch","scalebeard's cave","temple of arkkoran"},ang={["profession:Cooking"]="Bay of Storms djupa, oroliga vatten är välkända bland kustfiskare som söker sällsynta och eftertraktade djuphavsfångster utanför Kalimdors kust."},sec={{t="En stormpinad kust",b="Bay of Storms öppnar sig mot Great Sea och präglar en stor del av Azsharas dramatiska kustlandskap. Här finns ingen lugn hamn; det turbulenta vattnet och de klippiga grunden hyser farligt djurliv och uråldriga hot från havsdjupen. I och längs viken ligger landmärken som det sjunkna Temple of Arkkoran, korallreven vid Hetaera's Clutch och Scalebeard's Cave. Därför undviker vanliga sjöfarare i stor utsträckning viken, som i stället tagits över av kustens monster."}},faq={{q="Var ligger Bay of Storms?",a="Bay of Storms ligger vid Azsharas östra kant och mynnar direkt ut i Great Sea utanför Kalimdors kust.",al={"bay of storms läge","var ligger bay of storms","var ligger viken"}},{q="Vilka kända landmärken finns i viken?",a="Viken har flera kända kustformationer, däribland Temple of Arkkoran, revet Hetaera's Clutch och Scalebeard's Caves dolda tillhåll.",al={"landmärken i bay of storms","vad finns i bay of storms","sevärdheter i bay of storms"}},{q="Varför är det farligt att färdas genom viken?",a="Häftig bränning, vassa klippor och fientliga vattenlevande varelser gör viken förrädisk för förbipasserande fartyg. Här finns få kustsamhällen som kan komma till undsättning.",al={"är bay of storms säker","varför farlig","faror i viken"}}},fp="13,157,19.346.0,35.97.0,42.110.0,37.148.0"}
P.entries["subzone:bear-s-head"] = {n="Bear's Head",s="Bear's Head är ett avskilt bergsområde längs de sydöstra klipporna i Azshara. Det har fått sitt namn efter Timbermaw-furbolgerna som bor där och vars bosättningar ligger utspridda över den karga höjden. Området fungerar som en utpost med förbindelser till deras större hem längre norrut, samtidigt som det ligger direkt nedanför Archmage Xylems tillflyktsort på klippan.",h="Bear's Head är ett avskilt bergsområde längs de sydöstra klipporna i Azshara.",kw={"archmage xylem","azshara","bear's head","furbolg","timbermaw","ursolan"},ang={["class:Mage"]="Den väldiga klippan med utsikt över Bear's Head är hem åt Archmage Xylem, en mäktig och säregen magiker som söks upp av utövare av arkana konster för avancerad träning."},sec={{t="Furbolgutposter och klippmagi",b="Undangömt i sydöstra Azshara har Bear's Head fått sitt namn från de läger som de okorrumperade Timbermaw-furbolgerna har upprättat på höjderna. Dessa enkla bosättningar fungerar som utposter knutna till furbolgernas stora lyor i Ursolan och Timbermaw Hold i norr. Högst uppe på de resliga klipporna, direkt ovanför området, ligger Xylem's Tower, en säregen tillflyktsort där Archmage Xylem och hans lilla skara lärlingar bedriver arkana studier i lugn avskildhet från den oroliga kusten."}},faq={{q="Varför kallas området Bear's Head?",a="Området har fått sitt namn efter Timbermaw-furbolgernas byar som ligger utspridda bland kullarna. Björnfolket har aktiva läger här, som fungerar som sydliga utposter för deras fästen i norra Kalimdor.",al={"bear's head namnets ursprung","varför bear's head","bear's head betydelse"}},{q="Vilka furbolger bor i Bear's Head?",a="Området befolkas av Timbermaw-stammen. Till skillnad från många andra furbolgstammar i Kalimdor, som föll offer för demonisk korruption, har Timbermaw i stort sett stått emot smittan och har fortfarande band till sina främsta bosättningar i Ursolan och Timbermaw Hold.",al={"furbolger i bear's head","timbermaw i bear's head","vilken furbolgstam finns här"}},{q="Vad är tornet på klipporna ovanför Bear's Head?",a="Spiran på klippan tillhör Archmage Xylem. Han är en säregen mänsklig magiker som bedriver sina studier i avskildhet i Azshara, tillsammans med en handfull lärlingar och högälvssläktingar.",al={"tornet ovanför bear's head","vem bor i tornet här","xylem tower"}}},fp="11,199,36.356.0,36.155.0,35.220.0,50.178.0"}
P.entries["subzone:beezil-s-wreck"] = {n="Beezil's Wreck",s="Beezil's Wreck markerar platsen där ett olyckligt zeppelinarluftskepp från gobliner störtade djupt inne i Dustwallow Marshs träskmarker. Vraket ligger öster om Tabetha's Farm, och dess sönderslagna lastrum rymmer utspridda förnödenheter och instabila tekniska komponenter som lockar asätare.",h="Beezil's Wreck markerar platsen där ett olyckligt zeppelinarluftskepp från gobliner störtade djupt inne i...",kw={"beezil","beezil's wreck","dustwallow marsh","seaforium","tabetha","zeppelinarkrasch"},ang={["profession:Engineering"]="Det förvridna vraket av ett zeppelinarluftskepp från gobliner rymmer instabila mekaniska komponenter, särskilt Seaforium boosters som varje mekaniker skulle åtrå.",["race:Gnome"]="Att undersöka de rykande resterna av rivaliserande goblinflyg ger en kuslig påminnelse om farorna med flygkonstruktioner som inte är byggda av tomtar."},sec={{t="En katastrofal landning",b="Gomt i den fuktiga gyttjan öster om Tabetha's Farm ligger det splittrade skelettet av ett zeppelinarluftskepp från gobliner, känt som Beezil's Wreck. Farkosten fraktade last söderut över Kalimdor innan den störtade katastrofalt ner i träsket. Medan vrakdelarna fortfarande pyr bland trassliga vassruggar har dess excentriske kapten, Beezil, till synes försvunnit från träsket och lämnat utspridda lådor och tickande maskineri att långsamt ruttna i det salta vattnet."},{t="Bärgning i gyttjan",b="Trots den ogästvänliga miljön är kraschplatsen fortfarande ett populärt mål för opportunistiska utforskare. Luftskeppet fraktade en last med instabila varor, framför allt Seaforium boosters och tunga lådor som klarade nedslaget. Asätare som vågar vada genom de omgivande bestarna riskerar ofta liv och lem för att säkra det som återstår av den förlorade lasten innan det frätande träskvattnet förstör alltihop."}},faq={{q="Vad är Beezil's Wreck?",a="Beezil's Wreck är platsen där ett zeppelinarluftskepp från gobliner störtade djupt inne i Dustwallow Marsh, rakt öster om Tabetha's Farm. Luftskeppet kraschade medan det fraktade last genom träsket.",al={"beezils wreck","störtat zeppelinarluftskepp dustwallow","vad är det här för vrak"}},{q="Var är piloten Beezil?",a="Piloten Beezil syns inte till någonstans kring kraschplatsen. Om han flydde ut i den förrädiska vildmarken eller lämnade träsket helt och hållet är fortfarande ett mysterium för dem som söker igenom skrovet.",al={"var är beezil","vem är beezil","beezils plats"}},{q="Vilken värdefull last fraktade zeppelinaren?",a="Zeppelinaren var lastad med handelsvaror och instabil goblinteknik, däribland Seaforium boosters. Dessa värdefulla tekniska komponenter gör platsen till ett återkommande mål för äventyrare och bärgare.",al={"vad fanns i zeppelinaren","seaforium boosters","vrakets last"}}},fp="14,99,20.255.0,19.258.0,23.159.0,27.120.0,46.147.0"}
P.entries["subzone:beggar-s-haunt"] = {n="Beggar's Haunt",s="Beggar's Haunt är ett övergivet spanartorn från Stormwind, beläget på en sluttning i nordöstra Duskwood nära bergsvägen till Deadwind Pass. Det byggdes ursprungligen för att hålla uppsikt över rikets östra gränser, men har blivit en utpost för Forsaken-infiltratörer djupt inne på Alliansens territorium.",h="Beggar's Haunt är ett övergivet spanartorn från Stormwind, beläget på en sluttning i nordöstra Duskwood nära...",kw={"apothecary faustin","beggar's haunt","deathstalker zraedus","duskwood","knight's hollow","spanartorn","stormwind guard"},ang={["faction:Alliance"]="Att Forsaken-agenter är stationerade i ett gammalt spanartorn från Stormwind, strax intill huvudvägen, är ett oroväckande tecken på Horde-infiltration precis vid Darkshires tröskel.",["race:Undead"]="För Forsakens operatörer erbjuder denna avskilda utpost ett sällsynt och farligt fotfäste djupt inne i söderns människoländer."},sec={{t="Ett vakttorn i skuggorna",b="Beggar's Haunt ligger högt ovanför de dimmiga kullarna öster om Manor Mistmantle. En gång var det en aktiv utkikspost bemannad av Stormwind Guard, som skulle säkra rikets östra tillfartsvägar. När området sjönk in i det moderna Duskwoods mörker och rikets patruller drog sig tillbaka till Darkshire, överlämnades stentornet åt väder och vind. I dag tjänar dess dominerande utsiktspunkt ett betydligt mer illavarslande syfte: agenter från Forsaken, däribland medlemmar av Royal Apothecary Society och Deathstalkers, använder den förfallna fästningen för forskning och för att övervaka området mitt framför näsan på Alliansen."},{t="Knight's Hollow och de bortglömda döda",b="Bakom tornet leder en brant, slingrande stig ner till en avskild damm och ett vattenfall som kallas Knight's Hollow. Här ligger en omärkt grav, flankerad av två hotfulla, huvklädda stenstatyer som liknar väktarna vid The Dark Portal. Närliggande gravplatser, däribland en okänd soldats grav, vittnar om bortglömda strider längs denna gräns långt innan Forsaken tog över vakttornet."}},faq={{q="Varför finns Forsaken vid Beggar's Haunt?",a="Agenter från Undercity har tagit över det övergivna vakttornet. Bland dem finns Apothecary Faustin från Royal Apothecary Society och Deathstalker Zraedus. Härifrån kan de övervaka Alliansens rörelser och i tysthet utföra experiment långt i söder.",al={"vem finns vid beggar's haunt","varför är horde här","odöda vid beggar's haunt"}},{q="Byggdes tornet ursprungligen av Forsaken?",a="Nej. Stormwinds rike byggde tornet som en spanarutpost. När det lokala försvaret sviktade och området förföll till Duskwood övergav Stormwind Guard det, och det stod tomt tills Forsakens spejare tog över det.",al={"vem byggde beggar's haunt","beggar's haunts historia","är det här ett allianstorn"}},{q="Vad är den märkliga graven bakom tornet?",a="Längs stigen bakom Beggar's Haunt ligger Knight's Hollow, en avskild damm vid ett vattenfall med en omärkt grav omgiven av huvklädda väktarstatyer. De är utförda i samma stil som monumenten vid The Dark Portal.",al={"statyerna i knight's hollow","graven bakom tornet","statyer från the dark portal i duskwood"}},{q="Är Beggar's Haunt fientligt mot resande från Alliansen?",a="Ja. Forsaken vid tornet är erfarna agenter som slår ner alla äventyrare från Alliansen som kommer för nära deras fäste på sluttningen.",al={"kommer de att anfalla mig","vakter vid beggar's haunt","är beggar's haunt säkert"}}},fx={["221bad0c"]={q="Vad är Beggar's Haunt?",a="Beggar's Haunt är ett gammalt, övergivet vakttorn som ursprungligen uppfördes av Stormwind Guard i nordöstra Duskwood. Den befästa stenposten ligger högt uppe på åsen öster om Manor Mistmantle och blickar ut över passet mot Deadwind. Den föll för länge sedan ur människornas händer och har sedan dess drabbats av skogens framryckande mörker.",al={"beggar's haunt","vad är det här tornet","beggar's haunt i duskwood"}},["945d85f8"]={q="Vem bor i Beggar's Haunt?",a="Tornet bebos av två högt uppsatta Forsaken-agenter: apotekare Faustin från Royal Apothecary Society och hans beskyddare, Deathstalker Zraedus. Tillsammans använder de den avskilda utposten för mörk alkemisk forskning, långt från blickarna från både Stormwind och deras fiender i Lordaeron.",al={"vem finns i beggar's haunt","vem kontrollerar beggar's haunt","invånare i beggar's haunt"}},["29ce06ab"]={q="Varför övergavs Beggar's Haunt?",a="Precis som stora delar av Duskwood övergavs utposten när Stormwinds militära närvaro i regionen kollapsade. Night Watch kämpade för att ens försvara Darkshire mot glupska bestar, odöda fasor och spindlar, så avlägsna vakttorn längs åsarna lämnades öde och övertogs snabbt av fientliga styrkor.",al={"varför övergavs beggar's haunt","beggar's haunt i ruiner","varför lämnade stormwind beggar's haunt"}},dbe0cc4e={q="Är Beggar's Haunt farligt?",a="Extremt farligt, särskilt för ovetande Alliance-utforskare som färdas genom östra Duskwood. Apothecary Faustin och Deathstalker Zraedus är erfarna veteraner och långt dödligare än djurlivet i området. De slår skoningslöst ner alla från Alliance som kommer för nära deras avskilda fäste.",al={"är beggar's haunt säkert","nivå för beggar's haunt","faror vid beggar's haunt"}}},fp="14,180,27.386.0,38.388.0,41.240.0,48.190.0,43.180.0,48.130.0"}
P.entries["subzone:beren-s-peril"] = {n="Beren's Peril",s="Beren's Peril är en avskild bergsgrotta i de klippiga kullarna sydväst om Ambermill i Silverpine Forest. Den fungerar som ett befäst fäste för förrädiska Scourge-anhängare under nekromantikern Thule Ravenclaw, som smider planer mot de närliggande Forsaken.",h="Beren's Peril är en avskild bergsgrotta i de klippiga kullarna sydväst om Ambermill i Silverpine Forest.",kw={"allister","ambermill","beren's peril","berens peril","ravenclaws dagsverkare","scourge","the sepulcher","silverpine","thule ravenclaw"},ang={["faction:Horde"]="Om de karga stigarna i Silverpine Forest ska säkras måste förrädiska odöda nästen rensas ut innan de kan skära av försörjningslinjerna mellan The Sepulcher och de södra områdena.",["race:Undead"]="Ravenclaws hantlangare vid Beren's Peril är en bitter påminnelse om Scourges kvardröjande grepp. De hotar säkerheten vid The Sepulcher och måste snabbt och skoningslöst utrotas av Sylvanas lojala anhängare."},sec={{t="Ett dolt hot i kullarna",b="Högt uppe i klipporna sydväst om Ambermill ligger Beren's Peril, med en skuggig grotta och en slingrande bergsstig som döljs från huvudvägen. Efter förödelsen under det tredje kriget befäste förrädiska Scourge-odöda under den avfällige nekromantikern Thule Ravenclaws befäl denna enklav. I stället för att böja sig för Dark Lady eller dra sig norrut samlades Ravenclaws slavar – regenter, väktare och dagsverkare – här i hemlighet för att förbereda ett anfall mot Forsaken-basen The Sepulcher. Forsaken-spejare upptäckte dem, och den stilla bergssidan blev en aktiv krigszon för Horde-operatörer som skickats för att undanröja hotet innan ett anfall kunde inledas."}},faq={{q="Vad är Beren's Peril?",a="Det är en grotta och ett omgivande bergspass sydväst om Ambermill i Silverpine Forest, mellan huvudvägen genom området och sidovägen till Ambermill.",al={"berens peril","var ligger berens peril","grottan berens peril"}},{q="Vem kontrollerar Beren's Peril?",a="Grottan är ockuperad av Scourge-odöda som är lojala mot nekromantikern Thule Ravenclaw, däribland Ravenclaws väktare, dagsverkare och regenter.",al={"vilka bor i berens peril","fiender i berens peril","ravenclaws odöda"}},{q="Varför bryr sig Forsaken om den här platsen?",a="Forsaken-spejare upptäckte att de odöda som barrikaderat sig i Beren's Peril samlade trupper och rustade sig för ett förestående anfall mot The Sepulcher. Det fick Shadow Priest Allister att beordra förebyggande angrepp mot dem.",al={"allister berens peril","varför anfalla berens peril","hot mot the sepulcher"}},{q="Vem är Thule Ravenclaw?",a="Thule Ravenclaw är en mäktig nekromantiker verksam i Silverpine Forest, som behöll kontrollen över grupper av viljelösa och fientliga Scourge-hantlangare. Han använde platser som Beren's Peril och Fenris Keep för att hota området.",al={"thule ravenclaw","thule silverpine"}}},fx={["896a3c65"]={q="Vad hände vid Beren's Peril?",a="Efter det tredje kriget blev detta avskilda grottsystem i Silverpine Hills en samlingsplats för utbrytare bland de odöda. Forsaken-spejare som spårade hot mot regionen upptäckte att fientliga odöda, lojala mot den förrymde nekromantikern Thule Ravenclaw, hade samlats i grottorna och i hemlighet förberedde ett angrepp mot den närliggande Forsaken-bosättningen The Sepulcher.",al={"beren's perils historia","vad hände vid beren's peril","beren's peril i korthet"}},["25ec4175"]={q="Är Beren's Peril farligt?",a="Ja, Beren's Peril är extremt farligt. Grottan i sluttningen kryllar av fientliga odöda som styrs av Thule Ravenclaw, däribland Ravenclaw-arbetare, väktare och regenter. Den som ger sig in i grottorna riskerar att övermannas av dessa organiserade odöda innan de hinner anfalla The Sepulcher.",al={"faror i beren's peril","hur farligt är beren's peril","är beren's peril säkert"}}},fp="13,120,28.517.0,22.143.0,27.115.0,45.155.0,23.190.0"}
P.entries["subzone:bitter-reaches"] = {n="Bitter Reaches",s="Bitter Reaches är en karg, vindpinad vildmark i nordöstra Azshara. De branta klipporna är nästan orörda av civilisationen och strövas omkring av rovdjur och väldiga bergsjättar.",h="Bitter Reaches är en karg, vindpinad vildmark i nordöstra Azshara.",kw={"azshara","bitter reaches","chimär","hippogryf","bergsjätte","mountain silversage","ooze"},ang={["class:Hunter"]="Klipphyllorna i Bitter Reaches är utmärkta jaktmarker, fulla av vilda hippogryfer och aggressiva chimärer som hör hemma längs den uråldriga kusten.",["profession:Herbalism"]="De vindpinade höjderna i Bitter Reaches är en av få platser i Azshara där den eftertraktade Mountain Silversage växer, men du måste tampas med chimärer och jättar för att skörda den."},sec={{t="En farlig kustgräns",b="Bitter Reaches ligger bland Azsharas nordöstra klippor och är ett kargt, otämjt område med stenig terräng ovanför Stora havet. Flockar av vilda hippogryfer och tvåhövdade chimärer bygger bo bland höjderna, medan frätande oozar sipprar genom den kalla marken. Längs de höga nordliga åsarna har väldiga bergsjättar gjort sluttningarna till sitt revir. De driver bort mindre varelser och gör de frusna tillfarterna farliga för ensamma resenärer."},{t="Kragarnas växtliv",b="Trots de hårda vindarna och aggressiva rovdjuren växer sällsynta bergsväxter i det klippiga landskapet. Glesa bestånd av Mountain Silversage klamrar sig fast vid höga klippväggar och blåsiga utsprång. Därför kan den farliga terrängen ibland vara värd att korsa för modiga örtsamlare som vågar hålla sig undan jättarna och de revirhävdande chimärerna."}},faq={{q="Var ligger Bitter Reaches?",a="Bitter Reaches utgör den nordöstra delen av Azshara och täcker de höga kustklipporna och åsarna ovanför bukten.",al={"bitter reaches plats","var ligger bitter reaches","bitter reaches azshara"}},{q="Vilka varelser lever här?",a="Området är hem för revirhävdande hippogryfer, tvåhövdade chimärer och oozar. Väldiga bergsjättar strövar omkring vid den norra gränsen.",al={"varelser i bitter reaches","vad lever i bitter reaches","monster i bitter reaches"}},{q="Varför finns det bergsjättar här?",a="De uråldriga bergsjättarna lever på Azsharas höga nordliga toppar och klippkanter. De tar området i besittning och driver bort det mesta av det lokala djurlivet från sina marker.",al={"bergsjättar azshara","varför finns jättar i bitter reaches"}},{q="Vilka värdefulla resurser växer i Bitter Reaches?",a="Sällsynta örter från höga höjder, som Mountain Silversage, växer glest bland klippformationerna och längs åsarna.",al={"örter bitter reaches","insamling i bitter reaches"}}},fp="14,157,28.349.0,18.190.0,29.82.0,25.120.0,35.128.0,51.90.0"}
P.entries["subzone:black-channel-marsh"] = {n="Black Channel Marsh",s="Black Channel Marsh är ett grumligt träsk i Wetlands sydvästra del, intill huvudvägen mot Menethil Harbor. Här vimlar det av aggressiva raptorer, och den blöta marken utgör ett omedelbart hot mot oförsiktiga resenärer och kurirer med förnödenheter som färdas genom kustlandets lågland.",h="Black Channel Marsh är ett grumligt träsk i Wetlands sydvästra del, intill huvudvägen mot Menethil Harbor.",kw={"black channel marsh","träsk","menethil harbor","raptorer","träskmark","wetlands"},ang={["class:Hunter"]="Träsket är en farlig prövningsplats för jägare som vill tämja eller spåra Wetlands vilda raptorer alldeles intill huvudvägen.",["faction:Alliance"]="Den här förbindelsen är en livsviktig länk mellan hamnen i Menethil Harbor och resten av Khaz Modan, vilket gör raptorernas intrång till ett ständigt bekymmer för resenärer."},sec={{t="Faror på vägen till Menethil",b="Black Channel Marsh breder ut sig över den sumpiga låglänta marken sydväst om huvudvägen och är ökänt bland karavanförare och kurirer på väg till Menethil Harbor. Den upphöjda vägen ger en falsk känsla av trygghet, men de stillastående vattenfårorna och täta vassen är hem åt revirhävdande raptorflockar. Hungriga bestar irrar ofta rakt ut på vägen och överfaller nya rekryter och trötta vandrare som avviker bara ett steg eller två från den upptrampade stigen."}},faq={{q="Var ligger Black Channel Marsh?",a="Black Channel Marsh ligger i Wetlands sydvästra hörn. Det gränsar till den stora väg som leder in till Menethil Harbor, på dess södra sida.",al={"var ligger black channel marsh","black channel marsh läge","black channel i wetlands"}},{q="Varför anses det här träsket vara farligt för resenärer?",a="Träsket vimlar av raptorbon. Eftersom dessa rovdjur jagar längs träskets kanter stryker de regelbundet ända fram till vägkanten och överrumplar oförsiktiga resenärer och äventyrare på låg nivå.",al={"varför är det farligt","hot i black channel marsh","raptorer på vägen"}},{q="Vilka färdas oftast här?",a="Alliansens budbärare, dvärgiska köpmän och resenärer mellan Ironforge och Menethil Harbors hamnar färdas ofta längs vägen som går precis förbi träsket.",al={"vilka använder vägen","resenärer här"}}},fp="19,151,26.354.0,37.117.0,53.145.0,36.138.0"}
P.entries["subzone:blackchar-cave"] = {n="Blackchar Cave",s="Blackchar Cave är en mystisk, avspärrad grotta i de sydvästra klipporna i Searing Gorge, nära foten av Blackrock Mountain. Ingången är blockerad av ogenomträngliga stenar och rasblock.",h="Blackchar Cave är en mystisk, avspärrad grotta i de sydvästra klipporna i Searing Gorge, nära foten av...",kw={"blackchar cave","blackrock mountain","förseglad grotta","searing gorge"},sec={{t="En förseglad ingång",b="Blackchar Cave ligger undangömd bland de brännande klipporna nära vägen mot Blackrock Mountain. Där en djup grottöppning en gång kan ha funnits finns nu en massiv stenvägg. Tunga rasblock och förbränd slagg blockerar öppningen, så ingen kan utforska tunnlarna som kan finnas längre in bland bergets rötter. Det ödsliga landskapet runt grottan är svedd av aska och magma och erbjuder föga tröst åt vandrare."}},faq={{q="Kan du gå in i Blackchar Cave?",a="Nej. Ingången till Blackchar Cave är helt blockerad av rasade klippor, aska och stenblock. Det finns inget öppet utrymme där inne att utforska.",al={"är blackchar cave öppen","gå in i blackchar cave","inne i blackchar cave"}},{q="Var ligger Blackchar Cave?",a="Den ligger i det sydvästra hörnet av Searing Gorge, vid de klippiga fotbergen nära passagen mot Blackrock Mountain.",al={"blackchar caves läge","var ligger blackchar cave"}}},fp="14,77,18.197.0,33.106.0,32.116.0"}
P.entries["subzone:blackfathom-deeps"] = {n="Blackfathom Deeps",s="Blackfathom Deeps är ett översvämmat tempelruin under jord, begravt under The Zoram Strand längs Ashenvales nordvästra kust. De sjunkna salarna var en gång en storslagen helgedom tillägnad mångudinnan Elune, men har tagits över av naga, satyrer och den illvilliga kulten Twilight's Hammer.",h="Blackfathom Deeps är ett översvämmat tempelruin under jord, begravt under The Zoram Strand längs Ashenvales...",kw={"aku'mai","blackfathom","djupen","ghamoo-ra","kelris","sarevess","twilight's hammer","the zoram strand"},ang={["faction:Horde"]="För horden ligger djupen obehagligt nära Zoram'gar. Kultisterna och naga som samlas vid The Zoram Strand utgör ett hot som utpostens försvarare inte kan ignorera.",["race:NightElf"]="Skändningen av detta forntida tempel är en djup sorg för kaldorei, som sörjer att tomrumsdyrkare och naga har besudlat en gång helig helgedom till Elune och dess månbrunn."},sec={{t="Från Elunes tempel till den mörkaste avgrund",b="Innan den stora klyvningen krossade forntida Kalimdor för tiotusen år sedan var detta komplex ett tempel tillägnat gudinnan Elune, med en egen månbrunn. När Evighetens brunn kollapsade sjönk helgedomen under havets vågor och ansågs för alltid förlorad. Under årtusendena drog sig strandlinjen tillbaka och marken under jord skiftade, så att ruinerna delvis översvämmades under Ashenvales klippor."},{t="Aku'mai och kulten",b="På senare år sipprade en fornguds korruption upp från jordens djup och besudlade templets heliga månbrunn. Aku'mai, en monstruös hydra med tre huvuden och forngudens tjänare, steg upp ur vattnet. Kulten Twilight's Hammer upprättade ett fäste i de sjunkna ruinerna under Twilight Lord Kelris befäl. Tillsammans med naga under Lady Sarevess ledning och kringströvande satyrer offrar kultisterna oskyldiga till Aku'mai för att få makt."}},faq={{q="Vad byggdes Blackfathom Deeps ursprungligen för?",a="Det var ett nattalvstempel tillägnat mångudinnan Elune, med en helig månbrunn i dess mitt, innan det sjönk under vågorna under den stora klyvningen.",al={"bfd:s historia","vad var blackfathom deeps","bfd-templet"}},{q="Varför är kulten Twilight's Hammer här?",a="Twilight's Hammer kom för att dyrka Aku'mai, en uråldrig hydra och forngudens tjänare. Under Twilight Lord Kelris ledning offrar kulten oskyldiga till besten i utbyte mot mörk makt.",al={"varför finns kultister i bfd","twilight's hammer i blackfathom","kelris mål"}},{q="Var ligger ingången?",a="Ingången ligger gömd bland grottliknande ruiner längs The Zoram Strand på Ashenvales yttersta nordvästra kust. Äventyrare måste ta sig genom översvämmade kammare och fientliga naga-utposter för att nå templets portal.",al={"var ligger bfd","blackfathom deeps läge","hur tar man sig in i bfd"}},{q="Vem är Ghamoo-ra?",a="Ghamoo-ra är en jättelik, vansinnig sköldpadda som lurar på en ö i en av templets översvämmade grottor och anfaller alla inkräktare som kommer nära.",al={"jättesköldpaddans boss","ghamoo-ras bakgrund","sköldpadda i bfd"}}},fx={f0315c0b={q="Vad är Blackfathom Deeps?",a="Blackfathom Deeps är en översvämmad underjordisk ruin under The Zoram Strand vid Ashenvales kust. En gång var den ett praktfullt nattalvstempel tillägnat mångudinnan Elune, men det krossades och sjönk under den stora klyvningen. I dag utgör dess delvis översvämmade salar och havsgrottor en mörk fristad som tagits över av kultister, uråldriga bestar och de vidriga tjänarna till de gamla gudarna.",al={"vad är blackfathom deeps","översikt över blackfathom deeps","berätta om blackfathom deeps"}},["11da3285"]={q="Vad hände vid Blackfathom Deeps?",a="För länge sedan byggde nattalverna detta tempel till Elune, med heliga bassänger och en månbrunn. För tiotusen år sedan slet den stora klyvningen Kalimdor i stycken och sänkte helgedomen under vågorna. Man trodde att den var förlorad för alltid, men de gamla gudarnas korrumperande kraft har sipprat in i månbrunnen och lockat mörka krafter tillbaka till de ljuslösa ruinerna för att väcka en uråldrig fasa.",al={"blackfathom deeps historia","vad hände här","lathar'lazals historia"}},e07691c2={q="Vem bor i Blackfathom Deeps?",a="Det sjunkna templet domineras av Twilight's Hammer-kulten, ledd av Twilight Lord Kelris, som utför mörka ritualer och blodsoffer åt sina skuggfyllda herrar. Bland invånarna finns också ormlika naga under Lady Sarevess, korrumperade satyrer som lockats dit av den uråldriga kraften och vattenlevande vidunder. Främst bland dem är Aku'mai, ett monstruöst hydraliknande väsen och en gammal guds tjänare.",al={"vem bor här","vem kontrollerar blackfathom deeps","vem finns i blackfathom"}},bfbbd665={q="Varför ligger Blackfathom Deeps i ruiner?",a="Templet förstördes när Evighetens brunn imploderade under den stora klyvningen för tiotusen år sedan. Katastrofen slet sönder kontinenten och dränkte tempelområdet under havet, så att dess månbrunnar översvämmades och dess praktfulla arkitektur förvandlades till ett mörkt grottsystem under vatten.",al={"varför ligger det i ruiner","varför ligger blackfathom under vatten","varför förstördes det"}},e7974e12={q="Är Blackfathom Deeps farligt?",a="Det är ytterst farligt. Långt inne slaktar fanatiska kultister fångar i hädiska riter för att stärka Aku'mai, ett urtidsvidunder vars uppvaknande hotar att släppa lös kaos över Kalimdor. Inkräktare måste ta sig genom översvämmade tunnlar där fradgande vattenbestar, grymma nagatrollkarlar, listiga satyrer och kultister stryker omkring. Kultisterna dödar alla främlingar för att dölja sina ritualer.",al={"är blackfathom deeps säkert","hur farligt är blackfathom deeps","faror i bfd"}}},fp="17,177,36.425.0,20.383.1,48.140.0,39.177.0,30.192.0,17.138.0"}
P.entries["subzone:blackrock-mountain"] = {n="Blackrock Mountain",s="Blackrock Mountain är en enorm, aktiv vulkan som reser sig mellan Burning Steppes och Searing Gorge. Den uppstod när Ragnaros the Firelord kallades fram i en våldsam katastrof. I dess urholkade djup finns forntida dvärgbyggnader, stridande arméer och pyrande fasor.",h="Blackrock Mountain är en enorm, aktiv vulkan som reser sig mellan Burning Steppes och Searing Gorge.",kw={"blackrock mountain","blackrock spire","burning steppes","doomhammer","ragnaros","searing gorge","shadowforge","thaurissan"},ang={["faction:Horde"]="För dagens Horde är Blackrock Spire en symbol för deras forna fångenskap och blodsutgjutelse under Doomhammer. Nu strider där upproriska orker som förkastar Thralls ledarskap.",["race:Dwarf"]="Berget står för det mörkaste kapitlet i dvärgarnas historia: Dark Iron-klanens tragiska dårskap, som kostade dem friheten och satte djupa ärr i Eastern Kingdoms."},sec={{t="Ett katastrofalt ursprung",b="Blackrock Mountain fanns inte förrän vid höjdpunkten av War of the Three Hammers för två och ett halvt sekel sedan. När Ironforges och Wildhammerklanens förenade arméer hotade att utplåna honom sökte Sorcerer-Thane Thaurissan ett vapen i jordens djup. Hans vårdslösa besvärjelse krossade de dimensionella barriärerna och kallade fram Ragnaros the Firelord till Azeroth. Den efterföljande apokalypsen slet itu Redridgebergen, gröpte ur Searing Gorge och Burning Steppes och slungade samtidigt en kolossal vulkan mot himlen. Thaurissan dog i explosionen, och den överlevande Dark Iron-klanen bands i evig träldom under Eldherren. De högg ut sin huvudstad, Shadowforge City, djupt inne bland bergets rötter."},{t="Aska och blodets citadell",b="Under det första och andra kriget fick berget en ny, mörk betydelse. Efter plundringen av Stormwind rensade Orgrim Doomhammer ut Shadow Council och gjorde Blackrock Spire till Hordens fästningshuvudstad. Än i dag är berget en våldsam krigsskådeplats: Dark Iron-dvärgarna och deras elementmästare håller de brinnande djupen, medan Blackrock-orkerna som gått sin egen väg, drakfolket och deras mörka herrar besitter spirorna ovanför."}},faq={{q="Hur skapades Blackrock Mountain?",a="Det skapades för ungefär tvåhundrafemtio år sedan under War of the Three Hammers. Sorcerer-Thane Thaurissan försökte desperat frigöra djupa krafter under jorden för att besegra rivaliserande dvärgklaner. Av misstag kallade han fram Ragnaros the Firelord, vilket utlöste en apokalyptisk explosion som reste vulkanen.",al={"blackrock mountains ursprung","vem skapade blackrock mountain","hur bildades vulkanen"}},{q="Varför heter det Blackrock Mountain?",a="Berättelserna från den här tiden säger inte vem som först gav berget dess namn. Det delar namnet med orkernas Blackrock-klan: Orgrim Doomhammers Horde gjorde Blackrock Spire till sin huvudstad under det andra kriget, och rester av Blackrock-klanen håller fortfarande spirans fäste.",al={"blackrocks namnets ursprung","uppkallat efter blackrock-klanen"}},{q="Vem kontrollerar Blackrock Mountain just nu?",a="Berget är delat av en brutal konflikt. De förslavade Dark Iron-dvärgarna kontrollerar de underjordiska salarna i Shadowforge City i Ragnaros tjänst, medan resterna av Blackrock-klanen och svarta drakfolk dominerar den övre fästningen Blackrock Spire.",al={"vem bor i blackrock","vem styr blackrock mountain"}},{q="Vilka zoner förbinds genom Blackrock Mountain?",a="Stigarna och kedjorna inne i Blackrock Mountain utgör en direkt passage mellan Searing Gorge i norr och Burning Steppes i söder.",al={"hur tar man sig genom blackrock","blackrock mountains förbindelser"}}},fp="18,208,20.647.0,24.398.0,35.276.0,35.230.0,42.149.0,46.127.0"}
P.entries["subzone:blackrock-pass"] = {n="Blackrock Pass",s="Blackrock Pass är en bergskorridor som förbinder de norra klipporna i Redridge Mountains med Burning Steppes torra ödemarker. Under en tung järnport markerar den den plötsliga gränsen mellan människornas fridfulla kärnland och Dark Iron-dvärgarnas och Blackrock-orchernas farliga krigszoner. För varje utmattad resenär som färdas norrut till fots är den en hård och förrädisk gränsmark.",h="Blackrock Pass är en bergskorridor som förbinder de norra klipporna i Redridge Mountains med Burning Steppes...",kw={"blackrock-orcher","blackrock pass","burning steppes","gränsmark","port","lakeshire","redridge mountains"},ang={["faction:Alliance"]="För Redridges försvarare och kungariket Stormwind är Blackrock Pass en ständig källa till oro, eftersom det ger Blackrock-orcherna en rak väg söderut in i människornas marker."},sec={{t="En svedd gräns",b="Blackrock Pass, uthuggen i bergens taggiga ryggrad, fungerar som landvägen mellan Redridge Mountains och Burning Steppes. En kraftig järnport står längs den klippiga gränsen och skiljer de idylliska skogarna och sjöarna i de södra dalarna från det vulkaniska förfallet bortom. När du korsar gränsen lämnar du de pastorala markerna, som skyddas av Lakeshires hårt ansatta milis, bakom dig och hamnar i en öppen ödemark befolkad av eldelementarier, drakfolk och fientliga orchkrigshorder. Få korsar den till fots om de inte är på väg till skuggan av själva Blackrock Mountain."}},faq={{q="Vart leder Blackrock Pass?",a="Blackrock Pass förbinder Redridge Mountains norra gräns direkt med Burning Steppes södra utkant. Det är en av de direkta landvägarna mellan Alliansens södra territorier och Blackrock Mountains fotland.",al={"vart leder blackrock pass","blackrock pass destination","väg från redridge till burning steppes"}},{q="Är det säkert för resenärer från Lakeshire att korsa passet?",a="Nej. Markerena omedelbart norr om passet är mycket dödligare än Redridges omgivande kullar. Burning Steppes kryllar av våldsamma Blackrock-orcher, jättelika eldelementarier och svarta drakungar, vilket gör området extremt farligt för äventyrare på låg nivå och vanliga resenärer.",al={"kan jag ta mig genom blackrock pass","är blackrock pass farligt","nivåkrav för blackrock pass"}},{q="Vem kontrollerar Blackrock Pass?",a="Varken Stormwind eller Horden har full kontroll över passet. Det förblir en omstridd och glest befäst flaskhals, flankerad av framryckande Blackrock-orcher och vilda bestar, och bevakas med stor oro av Redridges stadsvakter där nere.",al={"vem äger blackrock pass","vakter vid blackrock pass","fraktionskontroll över blackrock pass"}}},fp="14,269,20.433.0,31.234.0,58.235.0,28.210.0"}
P.entries["subzone:blackrock-stronghold"] = {n="Blackrock Stronghold",s="Blackrock Stronghold är ett kraftigt befäst läger uthugget i klipporna i norra Burning Steppes, precis utanför ingången till Blackrock Mountain. Det fungerar som en viktig fältgarnison för Blackrock-orcherna och deras allierade under Dark Hordes baner.",h="Blackrock Stronghold är ett kraftigt befäst läger uthugget i klipporna i norra Burning Steppes, precis...",kw={"blackrock-klanen","blackrock stronghold","burning steppes","dark horde","rend blackhand"},ang={["faction:Alliance"]="Fästningen är en dyster påminnelse om det andra kriget och ligger inom räckhåll för attacker mot Stormwinds norra gränser.",["faction:Horde"]="För Thralls Horde representerar Blackrock-klanen det skamliga arvet från den gamla Horden – blodtörstiga, korrumperade kvarlevor som vägrar ära och fred."},sec={{t="Dark Hordes garnison",b="Fästningen breder ut sig över de förkolnade sluttningarna nedanför Blackrock Mountain och fungerar som Blackrock-klanens främsta bas i Burning Steppes. Till skillnad från Thralls Horde håller dessa orcher fast vid sitt krigiska arv och tjänar Rend Blackhand och drakfolket som lurar ovanför i spiran."},{t="Blackrock Spires frontlinje",b="Fästningen fungerar både som yttre försvar och som uppmarschområde för attacker mot Redridge Mountains och närliggande mänskliga länder. Den håller ständig uppsikt över de södra vägarna till berget och utmanar alla som vågar ta sig genom de ödelagda ödemarkerna."}},faq={{q="Vad är Blackrock Stronghold?",a="Det är en befäst militärbas i norra Burning Steppes, precis utanför Blackrock Mountain, och fungerar som en yttre garnison för Blackrock-klanens orcher.",al={"vad är det här för plats","blackrock stronghold burning steppes","vad är blackrock stronghold"}},{q="Är orcherna här vänligt sinnade mot Thralls Horde?",a="Nej. Orcherna i Blackrock Stronghold tillhör Dark Horde, som leds av Rend Blackhand. De förkastar Thralls ledarskap och är fientliga mot både Alliansen och den nya Horden.",al={"är det här horden","är blackrock-orcherna horden","vänligt sinnade mot horden"}}},fp="20,149,26.286.0,29.233.0,29.146.0,45.172.0"}
P.entries["subzone:blackthorn-ridge"] = {n="Blackthorn Ridge",s="Vid Blackthorn Ridge vaktar Razormane quilboar södra Barrens, norr om Razorfen Kraul. Brine, en orcisk schaman, håller utkik från ett läger ovanför en källa med ovanligt rent bergsvatten.",h="Vid Blackthorn Ridge vaktar Razormane quilboar södra Barrens, norr om Razorfen Kraul.",kw={"barrens","blackthorn ridge","brine","rent vatten","quilboar","razorfen kraul","razormane"},ang={["class:Shaman"]="Unga schamaner från Horde söker upp Brine vid åsen för att lära sig om de naturliga vattenelementens renhet mitt bland de karga, torra slätterna.",["faction:Horde"]="Razormane quilboar hotar Hordes försörjningslinjer genom södra Barrens mot Thousand Needles, så karavaner på genomresa måste vara vaksamma."},sec={{t="En törnbemängd skans",b="Blackthorn Ridge reser sig intill Razorfen Kraul, med sluttningar täckta av täta snår av vassa törnen. Razormane quilboar gör anspråk på marken som sitt förfäders territorium och använder de taggiga barriärerna för att ligga i bakhåll för främlingar och skärmytsla i södra Barrens. Resenärer söker sig till åsen trots faran, lockade av Brine, en eremit och orcisk schaman. Hans läger ligger ovanför en källa som är berömd över hela Kalimdor för sitt klara, andligt rena vatten."}},faq={{q="Var ligger Blackthorn Ridge?",a="Blackthorn Ridge ligger längst söderut i Barrens, strax norr om törnsnåren runt Razorfen Kraul och söder om Camp Taurajo.",al={"blackthorn ridge plats","var ligger blackthorn","hitta blackthorn ridge"}},{q="Vilka bor vid Blackthorn Ridge?",a="Fientliga Razormane quilboar håller till på dalens botten. Brine, en orcisk schaman, bor på en klippavsats ovanför deras törnsnår och vakar över den närbelägna bergskällan.",al={"vem finns vid blackthorn ridge","invånare vid blackthorn ridge","quilboar blackthorn"}},{q="Varför är källan nedanför Brines läger speciell?",a="En gömd källa under åsen rymmer exceptionellt rent och klart vatten, trots de torra slätterna och quilboar-folkets törnsnår runt den. Schamaner använder källan som en helig mittpunkt för sina ritualer.",al={"brines källa","blackthorns vatten","källan vid blackthorn ridge"}}},fx={a60eac08={q="Vad är Blackthorn Ridge?",a="Blackthorn Ridge är en taggig dal, full av snår, i södra Barrens, strax norr om den väldiga quilboar-fästningen Razorfen Kraul. Området har fått sitt namn efter den höga åsen ovanför dalen, där enorma törnbuskar slingrar sig över den torra klippan. Platsen fungerar som en befäst utpost för lokala quilboarstammar, avskild från de öppna slätterna.",al={"vad är blackthorn ridge","översikt över blackthorn ridge","berätta om blackthorn ridge"}},["4cf5ece9"]={q="Är Blackthorn Ridge farligt?",a="Ja, det är extremt farligt för oförsiktiga resenärer. Dalbottnen och stigarna omkring patrulleras flitigt av fientliga Razormane-quilboars som vaktar vägarna till Razorfen Kraul. Förutom en ensam orc-schaman vid namn Brine, som slagit läger på den höga åsen, finns inga vänliga utposter eller säkra vägar genom snåren.",al={"är blackthorn ridge säkert","faror vid blackthorn ridge","hur farligt är blackthorn ridge"}}},fp="16,180,22.409.0,26.124.0,30.162.0,45.191.0"}
P.entries["subzone:blackwolf-river"] = {n="Blackwolf River",s="Blackwolf River är ett vattendrag som rinner från Cragpool Lake genom Windshear Crag i Stonetalon Mountains. En gång var det en ren fjällbäck, men vattnet har förorenats svårt av Venture Companys hänsynslösa skogsavverkning och industriella verksamhet.",h="Blackwolf River är ett vattendrag som rinner från Cragpool Lake genom Windshear Crag i Stonetalon Mountains.",kw={"blackwolf river","cragpool lake","skogsavverkning","förorening","stonetalon mountains","venture company","windshear crag"},ang={["class:Druid"]="Goblinernas timmerverksamhet skändar Blackwolf River och är en skarp förolämpning mot Cenarion Circle och alla som vördar Kalimdors otämjda vatten.",["race:Tauren"]="Att se hur jorden ärras och vattnet förorenas av profitdrivna inkräktare stärker taurenfolkets beslutsamhet att rena Stonetalon från hänsynslös industriell förstörelse."},sec={{t="Industriella utsläpp",b="Blackwolf River rinner från Cragpool Lake och skär genom Windshear Crags bäcken. Det som borde vara en orörd alpin biflod har i stället fått ta den värsta stöten från tygellös goblinverksamhet. När Venture Company röjer skogarna runtomkring med tunga maskiner och motorsågar läcker slam, olja och avverkningsavfall stadigt ut i strömmen. Den fördärvade floden är ett tydligt exempel på den kommersiella plundring som hotar Stonetalon Mountains vildmark."}},faq={{q="Var börjar Blackwolf River och vart rinner den?",a="Floden rinner från Cragpool Lake högt uppe i bergen och slingrar sig genom den avverkade bäcken vid Windshear Crag.",al={"blackwolf river källa","var ligger blackwolf river","blackwolf river plats"}},{q="Varför är flodvattnet förorenat?",a="Venture Company bedriver storskalig skogsskövling och mekanisk avverkning i hela Windshear Crag. Avrinning från deras ångmaskiner, avfall och kalhyggen rinner direkt ut i vattendraget.",al={"varför är blackwolf river smutsig","förorening av blackwolf river","venture company föroreningar"}},{q="Vilka bedriver verksamhet längs floden just nu?",a="Venture Company dominerar flodstranden och använder den omgivande dalen för storskalig timmeravverkning och mekanisk verksamhet, trots motstånd från traktens vilda djur och ursprungsbefolkning.",al={"vem kontrollerar blackwolf river","vilka finns vid blackwolf river","fiender nära blackwolf river"}}},fx={d14d2651={q="Vad är Blackwolf Rivers historia?",a="Blackwolf River rann en gång klar genom hjärtat av Stonetalon Mountains och flöt från Cragpool Lake över Windshear Crag. Den balansen bröts när Venture Company flyttade tung industri till klippan. Deras hänsynslösa skogsskövling och mekaniserade avverkning förgiftade snabbt vattendraget och förvandlade en orörd bergsbäck till giftigt, slambemängt avfall från goblinernas industri.",al={"blackwolf rivers berättelse","blackwolf rivers historia","vad hände med blackwolf river"}},["476e6164"]={q="Är Blackwolf River farlig?",a="Ja, både vattnet och stränderna innebär allvarliga risker. Floden för med sig giftigt industriavfall från Venture Companys avverkning uppströms. Dessutom vimlar klippan omkring av aggressiva arbetare och skogshuggare från Venture Company samt mekaniska flishuggare. De vaktar sina maskiner våldsamt och röjer skog utan hänsyn till någon som passerar.",al={"är blackwolf river säkert","faror vid blackwolf river","risker med blackwolf river"}}},fp="15,151,17.265.0,46.84.0,32.117.0,43.161.0"}
P.entries["subzone:blackwood-den"] = {n="Blackwood Den",s="Blackwood Den är ett fördärvat läger för furbolger, beläget i södra Darkshore nära gränsen till Ashenvale. Grottan och lägren runtom var en gång fridfulla boplatser, men har drabbats av vansinne tillsammans med resten av Blackwood-stammen. En ensam nattalvsspanare vid namn Volcor sitter fången i grottan och väntar på hjälp från Auberdine.",h="Blackwood Den är ett fördärvat läger för furbolger, beläget i södra Darkshore nära gränsen till Ashenvale.",kw={"ashenvale","auberdine","blackwood den","blackwood-fästet","darkshore","furbolg","volcor"},ang={["class:Druid"]="Druider sörjer furbolgernas fall. De var en gång ståndaktiga beskyddare av vildmarken, och vansinnet i Blackwood Den ser de som ännu ett smärtsamt tecken på Kalimdors besudlade natur.",["race:NightElf"]="För nattalverna i Auberdine är Blackwood-stammens fall för fördärvet en tragisk utveckling. Att rädda Volcor ur deras klor är en brådskande plikt för att hålla deras folk säkra längs den södra vägen."},sec={{t="Ett fördärvat fäste",b="Blackwood Den ligger nära den södra gränsen där Darkshore möter Ashenvale och består av ett vindlande nätverk av enkla läger och en klippgrotta. Blackwood-furbolgerna som bor här har dukat under för den utbredda fördärvande kraft som griper tag i trakten och blivit våldsamt fientliga mot främlingar. Långt inne i grottan i Blackwood Den är nattalven Volcor fortfarande fastklämd och i fara, omgiven av den aggressiva stammen. Han behöver desperat hjälp från spanare och resenärer som skickats ut från Auberdine."}},faq={{q="Vad är Blackwood Den?",a="Blackwood Den är en furbolgbosättning med grottor längst i södra Darkshore, nära gränsen till Ashenvale. Den fungerar som bas för den fördärvade Blackwood-furbolgstammen.",al={"vad är blackwood den","blackwood-fästet","var ligger blackwood den"}},{q="Vem befinner sig i grottan i Blackwood Den?",a="I grottan sitter Volcor, en nattalv som har blivit fångad bakom fiendens linjer. Resenärer som stöter på honom måste samordna sig med allierade i Auberdine för att iscensätta en flykt och leda honom i säkerhet ut ur grottan.",al={"vem är fångad i grottan","vem är volcor","nattalv i blackwood den"}},{q="Varför är furbolgerna här fientliga?",a="Blackwood-furbolgerna har fallit offer för det mörka fördärv som sprider sig över Darkshore och Kalimdor efter det tredje kriget. Plågan har drivit dem in i ett vansinnigt raseri och får dem att angripa alla främlingar de får syn på.",al={"varför är blackwood-furbolger aggressiva","är blackwood-furbolger onda","fördärvade furbolger i darkshore"}}},fx={["9f3b6295"]={q="Vad hände vid Blackwood Den?",a="Blackwood Den var en gång en vanlig bosättning för Blackwood-furbolgstammen i södra Darkshore. Men furbolgarna här föll, liksom mycket av det lokala djurlivet och ursprungsstammarna, offer för en mörk fördärvelse som spred sig över landet. De vred sig bort från sina tidigare fredliga seder, blev våldsamt aggressiva, byggde befästa läger och gillrade fällor för främlingar som vågade sig nära deras hålor.",al={"blackwood dens historia","vad hände vid blackwood den","berättelsen om blackwood den"}},d219a6ba={q="Vilka bor i Blackwood Den?",a="Hålan och lägren omkring hålls av de fördärvade Blackwood-furbolgarna, som aggressivt försvarar sitt område mot inkräktare. Djupt inne i grottan har en olycklig night elf vid namn Volcor blivit fångad, inträngd av de fientliga furbolgarna och väntande på att någon modig nog att kämpa sig igenom hålan ska rädda honom.",al={"vilka bor i blackwood den","invånare i blackwood den","vem håller blackwood den"}},["3aa28176"]={q="Är Blackwood Den farligt?",a="Ja, det är mycket farligt. Blackwood-furbolgarna bor i flera grupperade läger precis utanför grottmynningen och inne i själva hålan. De är fördärvade och våldsamma, och anfaller alla främlingar de får syn på i flock. Att försöka ta sig in, särskilt för att nå den fångade night elfen Volcor, är livsfarligt utan noggranna förberedelser.",al={"är blackwood den farligt","faror i blackwood den","hur farligt är blackwood den"}},f77a0955={q="Varför heter platsen Blackwood Den?",a="Hålan har fått sitt namn efter Blackwood-furbolgstammen som har sitt hem här. Grottan och lägren omkring ligger i södra Darkshore, nära gränsen till Ashenvale, och är den fördärvade klanens centrala håla och fristad.",al={"varför heter det blackwood den","betydelsen av namnet blackwood den","varifrån kommer namnet blackwood den"}}},fp="13,246,22.313.0,22.149.0,40.160.0,34.141.0"}
P.entries["subzone:blackwood-lake"] = {n="Blackwood Lake",s="Blackwood Lake är en fördärvad sjö i södra Eastern Plaguelands, full av fientliga, korrumperade elementaler. Området hemsöks av minnen av tragedier och krig och bevakas av ett litet frontläger från Argent Dawn.",h="Blackwood Lake är en fördärvad sjö i södra Eastern Plaguelands, full av fientliga, korrumperade elementaler.",kw={"blackwood","darrowshire","elementaler","horgus","sjö","plaguelands"},ang={["class:Paladin"]="Det förorenade vattnet och den förruttnade atmosfären kring Blackwood Lake visar tydligt hur blighten korrumperar Lordaerons naturliga elementaler och hur de behöver renas av Ljusets kraft.",["race:Human"]="För Lordaerons människor är Blackwood Lake en bitter påminnelse om hur fullständigt Scourge förgiftade rikets lantliga hjärtland."},sec={{t="Ett förgiftat minne",b="Liksom stora delar av Eastweald har Blackwood Lake förgiftats av den härjande farsoten av odöda. Sjuka och motbjudande vattenelementaler virvlar under den grumliga ytan och angriper alla som närmar sig stranden."},{t="Reliker från de fallna",b="Sjön rymmer också dystra reliker från slaget om Darrowshire. Lokala historiska skildringar, som Extended Annals of Darrowshire, berättar att den avhuggna skallen från Horgus the Ravager, en krigsherre i Scourge, kastades ner i Blackwood Lakes stinkande djup. I närheten vårdar en läkare från Argent Dawn sargade fotsoldater vid en liten framskjuten utpost och kämpar för att hålla soldater vid liv i skuggan av Scourges förödelse."}},faq={{q="Vilka varelser lurar i Blackwood Lake?",a="Sjön är angripen av korrumperade vattenelementaler. Liksom mycket av sötvattnet i Plaguelands har vattnet förvridits av nekromantisk avrinning och smuts, vilket förvandlat de lokala andarna till våldsamma, giftiga varelser.",al={"vad finns i vattnet","sjömonster","elementaler i blackwood lake"}},{q="Varför är Argent Dawn stationerade vid sjön?",a="Argent Dawn har ett litet fältläger nära sjön där en Argent Medic tar hand om sårade fotsoldater. Det fungerar som en nödstation för patruller som strider längs vägarna mellan Darrowshire och närbelägna fästen tillhörande Scourge.",al={"argent-läger","argent-läkare","varför finns det soldater här"}},{q="Vilken relik från Darrowshire ligger begravd i Blackwood Lake?",a="Enligt Annals of Darrowshire kastades skallen från Horgus the Ravager, en av Scourges främsta ledare under anfallet mot Darrowshire, ner i sjöns djup efter att han hade fällts.",al={"horgus the ravagers huvud","uppdragsföremål i sjön","annals of darrowshire och sjön"}}},fp="14,170,17.175.0,20.341.1,38.155.0,45.209.0,51.242.0"}
P.entries["subzone:bladefist-bay"] = {n="Bladefist Bay",s="Bladefist Bay öppnar sig mot Stora havet längs östra Durotar, strax bortom Orgrimmars portar. Branta klippor reser sig över stranden, med Azsharas sydkust på andra sidan vattnet.",h="Bladefist Bay öppnar sig mot Stora havet längs östra Durotar, strax bortom Orgrimmars portar.",kw={"bukt","bladefist","durotar","stora havet","kargath","orgrimmar","shattered hand","skull rock"},ang={["class:Rogue"]="Som skurk vet du att Shattered Hand verkar i Orgrimmars skuggor som hordens tjuv- och lönnmördargille. Den här kusten väcker en stillsam genklang hos hemliga agenter.",["race:Orc"]="Som ork vet du att bukten bär Kargath Bladefists stolta och brutala namn, en påminnelse om klanen Shattered Hands prövningar på Draenor."},sec={{t="En bukt vid Stora havet",b="Bladefist Bay möter Stora havet längs Durotars nordöstra kant. Klippiga stup höjer sig över de förrädiska vågorna, strax öster om Orgrimmar, hordens huvudstad. På andra sidan vattnet i norr markerar Azsharas uråldriga röda klippor och ruiner den avlägsna stranden. Bukten bildar en gräns mellan Durotar och det öppna havet."},{t="Den skuggade handen",b="Kargath Bladefist gav bukten dess namn. Som hövding för klanen Shattered Hand högg han av sin egen hand och ersatte den med ett blad under den gamla hordens prövningar på Draenor. Skull Rock ligger i närheten, där kultister och hemliga nätverk av skurkar verkar i skuggorna. Kusten bär spår av klanhövdingens våldsamma och hänsynslösa arv."}},faq={{q="Vem är Bladefist Bay uppkallad efter?",a="Bladefist Bay är uppkallad efter Kargath Bladefist, hövding för klanen Shattered Hand. Han var känd för att ha ersatt sin avhuggna hand med ett dödligt skärblad.",al={"vem är bladefist","bladefists namne","kargath bladefist-bukten"}},{q="Var ligger Bladefist Bay?",a="Bladefist Bay sträcker sig längs Durotars nordöstra kust, öster om Orgrimmars huvudportar och söder om Azshara på andra sidan vattnet.",al={"bladefist bay läge","var ligger bladefist bay","hur tar man sig till bladefist bay"}},{q="Vilka hot lurar runt Bladefist Bay?",a="Skull Rock ligger vid strandlinjen, och dess grottor hyser häxmästare, demoner och medlemmar av kulten Burning Blade.",al={"faror vid bladefist bay","fiender i bladefist bay"}},{q="Varför kallas bukten ibland för en avskrädeshög?",a="Ingen skildring från den här tiden kallar bukten en avskrädeshög. Det är en klippig kuststräcka i Durotar, öster om Orgrimmar, med Azshara på andra sidan vattnet.",al={"avskrädeshög","vrakgods vid bladefist","skräp i havsviken"}}},fx={["6e8d698f"]={q="Vad är Bladefist Bay?",a="Bladefist Bay är en kustvik vid Great Sea, längs Durotars nordöstra stränder, öster om Orgrimmar och söder om Azshara.",al={"vad är bladefist bay","bladefist bay i durotar","om bladefist bay"}}},fp="13,190,22.277.0,28.315.0,33.184.0,31.134.0,39.113.0,46.148.0"}
P.entries["subzone:bloodfen-burrow"] = {n="Bloodfen Burrow",s="Bloodfen Burrow är en grotta i sydvästra Dustwallow Marsh, full av vildsinta rovraptorer. Bestarna har tagit grottan och gläntan runt den och helt översvämmat ruinerna av en bosättning som en gång försökte överleva i våtmarkerna.",h="Bloodfen Burrow är en grotta i sydvästra Dustwallow Marsh, full av vildsinta rovraptorer.",kw={"bloodfen burrow","bloodfen-raptor","cortello's riddle","dustwallow marsh","raptorgrotta"},ang={["class:Hunter"]="Bloodfen-raptorerna som häckar här är vildsinta och snabba bestar, väl lämpade för jägare som söker tåliga, aggressiva träskkompanjoner."},sec={{t="Ett rovdjursnäste",b="Bloodfen Burrow ligger gömd i sydvästra Dustwallow Marsh och är näste för områdets aggressiva Bloodfen-raptorer. Grottöppningen och hålan runt den kryllar av flocken, som lockas av den skyddade skrevan och de rika jaktmarkerna i träsket. Precis utanför ingången ligger utspridda rester och splittrade lämningar från en oidentifierad bosättning, en dyster påminnelse om vem som verkligen härskar i träskets inre. Resande viskar också om att Cortello, en äventyrslysten fribytare, lämnade en av sina dolda gåtledtrådar någonstans i detta dödliga näste."}},faq={{q="Vad lever i Bloodfen Burrow?",a="Grottan är översvämmad av Bloodfen-raptorer. De har etablerat en tät häckningsplats både inne i grottan och över gläntan runt den och angriper alla som är dumdristiga nog att inkräkta på deras revir.",al={"vem bor här","raptorer i bloodfen burrow","vilka fiender finns i bloodfen burrow"}},{q="Vad är ruinerna utanför grottan?",a="Resterna av en oidentifierad bosättning ligger utanför grottan. Raptorerna förstörde bosättningen, men invånarnas identitet och öde finns inte nedtecknade.",al={"förstörd bosättning i dustwallow","vem byggde hyddorna nära bloodfen burrow","ruiner utanför grottan"}},{q="Varför skulle en äventyrare söka igenom Bloodfen Burrow?",a="Förutom att jaga de vildsinta träskraptorerna måste upptäcktsresande som löser Cortello's Riddle ta sig in i grottan. Piraten gömde en av sina gåtledtrådar i grottans skuggiga djup.",al={"cortello's riddle bloodfen","skatt i bloodfen burrow","uppdrag i bloodfen burrow"}}},fp="15,173,18.355.0,30.141.0,36.164.0,47.164.1"}
P.entries["subzone:bloodhoof-village"] = {n="Bloodhoof Village",s="Bloodhoof Village är en central bosättning för tauren vid Stonebull Lakes strand i Mulgore. Den har fått sitt namn till Bloodhoof-stammens ära och är den första större samlingsplatsen för unga jägare och krigare på väg från Camp Narache till Thunder Bluff. Under Baine Bloodhoofs ledning samordnar byn det lokala försvaret, handeln och traditionella riter över slätterna.",h="Bloodhoof Village är en central bosättning för tauren vid Stonebull Lakes strand i Mulgore.",kw={"baine bloodhoof","bloodhoof village","camp narache","kodo","mulgore","stonebull lake","zarlman two-moons"},ang={["faction:Horde"]="Denna fridfulla bosättning är ett viktigt stopp och en logistisk länk mellan Mulgore södra slätter och Hordens huvudstad Thunder Bluff.",["race:Tauren"]="För unga tauren markerar ankomsten till Bloodhoof Village det första verkliga steget från ungdomen mot ett större ansvar i stammen och andlig mognad."},sec={{t="Slätternas hjärta",b="Bloodhoof Village ligger kring Stonebull Lakes klara vatten och är ett livligt centrum för handel, hantverk och ceremonier i centrala Mulgore. Unga tauren som lämnar sina prövningar i Camp Narache kommer hit för att vässa sina färdigheter innan de fortsätter mot Thunder Bluffs väldiga platåberg. Här bor också de tålmodiga uppfödare som tämjer vilda kodo för färder."},{t="Ledarskap och riter",b="Baine Bloodhoof, son till överhövding Cairne Bloodhoof, ansvarar för den dagliga styrelsen och försvaret av området. Under hans vakande blick skickas krigare ut för att skydda gräsmarkerna mot aggressiva vilda djur, quilboar som tränger in på deras marker och Venture Companys skuggor. Tillsammans med Baine vårdar andliga vägledare som Zarlman Two-Moons stammens inre liv och leder noviser genom heliga färder som Synens rit."}},faq={{q="Vem leder Bloodhoof Village?",a="Baine Bloodhoof, son till överhövding Cairne Bloodhoof, leder bosättningen och samordnar försvaret mot hoten mot de centrala slätterna.",al={"byledare","baine bloodhoof plats","vem styr bloodhoof village"}},{q="Vilka viktiga riter utförs här?",a="Andliga rådgivare som Zarlman Two-Moons vägleder unga tauren genom den traditionella Synens rit, en viktig andlig färd på vägen mot vuxenlivet.",al={"synens rit","andliga prövningar","zarlman two-moons uppdrag"}},{q="Vad är bosättningen känd för att framställa?",a="Bloodhoof Village är det främsta navet där vilda kodo från slätterna tämjs och tränas som riddjur.",al={"taurenriddjur","kodotämjning","bloodhoof-trummor"}},{q="Vart beger sig resenärer när de har slutfört sina uppgifter här?",a="När deras uppdrag i centrala Mulgore är slutförda hänvisas resenärer vanligtvis norrut till Thunder Bluff, taurenfolkets huvudstad.",al={"efter bloodhoof","vart efter bloodhoof","nästa nav"}}},fx={["0d479a74"]={q="Vad är Bloodhoof Village?",a="Bloodhoof Village är en viktig taurenbosättning i centrala Mulgore, vid Stonebull Lakes stränder. Den fungerar som den främsta rastplatsen och vägkorsningen för resenärer och unga krigare på väg norrut från Red Cloud Mesa mot Thunder Bluff. Här samlas taurerna för att handla, söka andlig vägledning och tämja vilda kodo-djur för färder.",al={"vad är bloodhoof village","bloodhoof villages berättelse","om bloodhoof village"}},["4dcc3235"]={q="Är Bloodhoof Village farligt?",a="Själva byn är en välbevakad fristad, som Baine Bloodhoof och lokala krigare vakar över. Men Mulgore-slätterna omkring rymmer ständiga faror, från rovdjur på jakt och aggressiva gnoller till Venture Companys inträngande skogshuggare och skumma Grimtotem-agenter som motarbetar de förenade stammarnas fred.",al={"faror vid bloodhoof village","är bloodhoof säkert","hot mot bloodhoof"}},["39f13758"]={q="Varför heter platsen Bloodhoof Village?",a="Bosättningen är uppkallad efter Bloodhoof-stammen, den framstående taurenklanen som leds av högklanledaren Cairne Bloodhoof. Den bär stolt klanens namn och står fortfarande under direkt ledning av Cairnes son, Baine.",al={"bloodhoof villages ursprung","varför bloodhoof village","efter vem är bloodhoof village uppkallad"}}},fp="17,186,19.311.0,20.360.0,28.144.0,36.157.0,43.82.0,55.114.0"}
P.entries["subzone:bloodtooth-camp"] = {n="Bloodtooth Camp",s="Bloodtooth Camp är ett läger med fientliga, fördärvade furbolger i centrala Ashenvale, strax väster om Falfarren River. Under hövdingen Ran Bloodtooth har dessa en gång fridfulla varelser fallit offer för mörkt vansinne och anfaller alla som närmar sig. Lägret är ett huvudmål för alliansens spejare, som försöker rena skogarna i området.",h="Bloodtooth Camp är ett läger med fientliga, fördärvade furbolger i centrala Ashenvale, strax väster om...",kw={"ashenvale","bloodtooth camp","falfarren river","furbolg","krolg","raenes rening","ran bloodtooth"},ang={["faction:Alliance"]="För äventyrare i Alliansen är Bloodtooth Camp en lokal härd för fördärvning som hotar tryggheten i Ashenvales södra lundar och månkällor.",["race:NightElf"]="Nattalverna ser Ran Bloodtooths stam som offer för ett vansinnestillstånd, ett tragiskt tecken på den djupa fördärvning som plågar deras uråldriga hemland."},sec={{t="En fördärvad lya",b="Bloodtooth Camp ligger sydväst om den södra månkällan och väster om Falfarren River och är en dyster påminnelse om förfallet som breder ut sig i Ashenvale. Furbolgerna som bor här stod en gång i förbindelse med Kalimdors heliga vildmark, men en kvardröjande andlig fördärvning har slukat deras stam. Under Ran Bloodtooths befäl vaktar de sin enkla bosättning med ursinnig fientlighet och vänder sig mot både resenärer och nattalvernas beskyddare."},{t="Att rena skogen",b="Eftersom Ran Bloodtooths följe utgör ett omedelbart hot mot närliggande heliga platser kan alliansens väktare och deras allierade inte ignorera lägret. Som en del av arbetet med att återställa balansen i skogen, framför allt genom att hjälpa Raene Wolfrunner med hennes reningsarbete, får äventyrare i uppdrag av Krolg att infiltrera lägret, döda Ran Bloodtooth och göra slut på hans våldsamma livvakter."}},faq={{q="Var ligger Bloodtooth Camp?",a="Bloodtooth Camp ligger i centrala Ashenvale, precis väster om Falfarren River och strax sydväst om den södra månkällan.",al={"bloodtooth camp plats","var ligger bloodtooth camp","hitta bloodtooth camp"}},{q="Varför är furbolgerna här fientliga?",a="Liksom många furbolgstammar i Ashenvale har Bloodtooth-klanen fallit offer för en mörk demonisk fördärvning som dröjer kvar i vildmarken. Den driver dem till vansinne och gränslös aggression mot alla utomstående.",al={"varför anfaller furbolgerna i bloodtooth","bloodtooth-fördärvning","är furbolgerna onda här"}},{q="Vem leder furbolgerna i Bloodtooth Camp?",a="Lägret styrs av Ran Bloodtooth, en våldsam hövding som leder de lokala furbolgerna tillsammans med sin egen grupp livvakter.",al={"boss i bloodtooth camp","ran bloodtooth","vem leder bloodtooth camp"}},{q="Varför skickar Alliansen spejare hit?",a="Under arbetet med Raene's Cleansing leder den landsförvisade furbolgen Krolg alliansens förkämpar till att slå till mot lägret, döda Ran Bloodtooth och undanröja hotet från hans fördärvade anhängare i området.",al={"uppdrag i bloodtooth camp","varför döda ran bloodtooth","krolgs uppdrag"}}},fx={f92ad28e={q="Vad är Bloodtooth Camp?",a="Bloodtooth Camp är ett läger i centrala Ashenvale, väster om Falfarren River och sydväst om en helig night elf-månkällare. Det är ett fäste för en grupp fördärvade furbolgar som fallit under mörka krafter och nu våldsamt angriper alla som tar sig in på deras område.",al={"vad är bloodtooth camp","bloodtooth camps berättelse","bloodtooth camp i ashenvale"}},["15670459"]={q="Vilka bor i Bloodtooth Camp?",a="Lägret bebos av en stam vilda, fördärvade furbolgar under Ran Bloodtooths befäl. Med lojala furbolg-beskyddare och livvakter omkring sig ser dessa varelser, som en gång var fredliga, alla främlingar som dödsfiender och försvarar sitt läger med vildsint våldsamhet.",al={"vilka bor i bloodtooth camp","furbolgarna i bloodtooth camp","invånare i bloodtooth camp"}},["3d0c2137"]={q="Är Bloodtooth Camp farligt?",a="Ja, det är oerhört farligt. Furbolgarna här är uppslukade av fördärvelsen och anfaller genast med vildsint raseri. Om du går in i lägret ställs du mot hårdföra furbolg-krigare och Ran Bloodtooths personliga livvakter. Ett oförsiktigt närmande kan bli ditt sista misstag.",al={"är bloodtooth camp farligt","faror vid bloodtooth camp","hot vid bloodtooth camp"}},["39c5c848"]={q="Varför heter platsen Bloodtooth Camp?",a="Lägret har fått sitt namn efter Ran Bloodtooth, den hårdföre klanledaren som styr den fördärvade furbolgstammen här.",al={"varför heter det bloodtooth camp","betydelsen av namnet bloodtooth camp","vem är bloodtooth"}}},fp="15,206,15.324.0,20.265.1,33.110.0,34.163.0,42.74.0,39.196.0"}
P.entries["subzone:bloodvenom-falls"] = {n="Bloodvenom Falls",s="Bloodvenom Falls är ett högt, motbjudande vattenfall som störtar nerför de fördärvade klipporna i norra Felwood. Dess giftiga flöde mynnar i Bloodvenom River och sprider demonisk röta nerför bergen och vidare till länderna nedströms.",h="Bloodvenom Falls är ett högt, motbjudande vattenfall som störtar nerför de fördärvade klipporna i norra...",kw={"bloodvenom falls","bloodvenom river","korruption","darkshore","felwood","slemvarelse","vattenfall","wildbend river"},ang={["class:Druid"]="Den förorenade forsningen i Bloodvenom Falls är en bitter syn för Cenarion Circle och fungerar som en av de främsta vägarna för Felwoods vidriga sjukdom ner till länderna nedanför.",["race:NightElf"]="För nattalver är synen av Bloodvenom Falls, som föder den förgiftade Wildbend River i Darkshore, ett direkt hot mot deras förfäders hem och kusthelgedomar."},sec={{t="En källa till röta",b="Bloodvenom Falls forsar över klipporna i Felwood och är ett av de tydligaste såren som tillfogats Kalimdors uråldriga skogar. Vattenfallet var en gång en orörd fjällkaskad, men under det tredje kriget förvandlades vattnet till ett smittosamt slam av demonisk magi och resterna av Burning Legion. Fallen mynnar direkt i Bloodvenom River, som slingrar sig genom hjärtat av Felwood. Därifrån rusar den förgiftade strömmen nerför bergssluttningarna och blir den motbjudande Wildbend River i Darkshore, där den för med sig farsoten långt bortom Felwoods fördärvade gränser."},{t="Ekologiskt gift",b="Det smittosamma avrinningen från Bloodvenom Falls missfärgar inte bara flodbädden, utan förvrider allt den vidrör. De sumpiga stränderna kring vattenstänket ger upphov till förvridna treanter, sjuka bestar och aggressiva slemvarelser. För druider och väktare som försöker hejda Felwoods röta är fallen en iskall påminnelse om att vattnen i norra Kalimdor fortfarande är svårt sjuka redan vid källan."}},faq={{q="Vart rinner vattnet från Bloodvenom Falls?",a="Vattenfallet mynnar direkt i Bloodvenom River. Floden skär genom Felwood innan den störtar nerför bergen till Darkshore, där den blir den fördärvade Wildbend River.",al={"vart rinner bloodvenom river","bloodvenom falls flodens lopp","vart rinner vattnet"}},{q="Varför är vattenfallet fördärvat?",a="Under det tredje kriget mättade Burning Legions demoniska magi området och fördärvade Felwoods vilda skogar. Källorna och de högt belägna fjällbäckarna som föder vattenfallet sög upp denna felkorruption och förvandlade vattnet till giftig sörja.",al={"varför är bloodvenom falls grönt","varför är vattnet förgiftat","vad fördärvade bloodvenom falls"}},{q="Påverkar fördärvet vid vattenfallet andra zoner?",a="Ja. Vattnet störtar från Felwood nerför de västra bergskammarna till Darkshore, där det återkommer som den förgiftade Wildbend River och sprider röta mot kusten.",al={"förgiftar felwood darkshore","hur påverkar det darkshore","förorening av floden i darkshore"}},{q="Går det att rena vattnet i Bloodvenom Falls?",a="Cenarion Circle fortsätter att söka sätt att rena Felwood, men den enorma vattenmängden och den djupa mättnaden av demonisk smitta i floden gör det till en monumental kamp att bota vattenfallet, och den är ännu olöst.",al={"kan druiderna rädda bloodvenom falls","går bloodvenom falls att rena","rengöring av vattenfallet"}}},fp="16,160,17.438.0,17.323.0,48.157.0,31.234.0,52.169.0,47.209.0"}
P.entries["subzone:bloodvenom-post"] = {n="Bloodvenom Post",s="Bloodvenom Post är en avlägsen bosättning för Horde på de klippiga branterna i västra Felwood, med utsikt över Darkshore. Byggnader i taurenstil och taurenvakter ger ett fäste i ett område hemsökt av demonisk smitta och förvildat, korrumperat djurliv.",h="Bloodvenom Post är en avlägsen bosättning för Horde på de klippiga branterna i västra Felwood, med utsikt...",kw={"bloodvenom post","bloodvenom river","darkshores klippor","felwood","horde-utpost","tauren"},ang={["faction:Horde"]="Som Hordes enda befästa tillflyktsort i Felwood erbjuder lägret trygghet, skydd och en bas i en annars genomfientlig vildmark.",["race:Tauren"]="Taurenkrigare håller vakt vid utposten för att studera den miljöförstörelse som Legion orsakat och hejda korruptionen som förstör landets naturandar."},sec={{t="Ett osäkert fotfäste",b="Bloodvenom Post ligger undangömt längs de höga klipporna ovanför Darkshore. Du når platsen genom att följa den korrumperade södra stranden av Bloodvenom River bort från Felwoods huvudled. Lägrets traditionella taurentält, totem och vaktposter ger Horde-vandrare en viktig bas i en döende skog. Härifrån följer spejare de demoniska styrkornas framryckning, studerar hur vattnet förorenas och försöker hålla uppsikt över det fientliga djurliv som förvridits av Burning Legions kvardröjande kraft."},{t="Utblick över bergsryggen",b="Förutom att hålla uppsikt över Felwoods besmittade vildmark ligger lägret alldeles vid stupet, med utsikt över norra Darkshore. Det avskilda läget fyller två syften: Horde-styrkorna får information om Night Elfs rörelser längs västkusten, samtidigt som lägret ligger utom räckhåll för Alliance-patruller på skogens huvudväg."}},faq={{q="Var ligger Bloodvenom Post?",a="Bloodvenom Post ligger gömt längs de västra bergsryggarna i centrala Felwood. Från huvudvägen som går från norr till söder följer du Bloodvenom Rivers södra strand västerut längs en smal stig som slingrar sig runt den klippiga sluttningen.",al={"hitta bloodvenom post","hur man tar sig till bloodvenom post","vägbeskrivning till bloodvenom post"}},{q="Vem kontrollerar den här utposten?",a="Bloodvenom Post är en utpost för Horde med taurenvakter och traditionell taurenarkitektur.",al={"vem styr bloodvenom post","bloodvenom posts fraktion"}},{q="Varför heter platsen Bloodvenom?",a="Namnet kommer från den närliggande Bloodvenom River, vars vatten har förorenats och blivit giftigt av demonisk smitta som trängt in i skogen.",al={"varför bloodvenom","betydelsen av namnet bloodvenom"}},{q="Vilka hot möter spejarna här?",a="Utposten utsätts för ständiga angrepp från Felwoods korrumperade djurliv, däribland rabiata sabelkatter, besmittade slem och förvridna treants. Dessutom finns Shadow Council och rester av Burning Legion i hela området.",al={"bloodvenom posts fiender","vad angriper bloodvenom post"}}},fp="15,159,21.433.0,21.275.0,33.198.0,26.98.0,33.126.0,37.178.0"}
P.entries["subzone:bloodvenom-river"] = {n="Bloodvenom River",s="Bloodvenom River är en vidrig flod som skär genom centrala Felwood, mättad av den demoniska fördärvning som hemsökte den uråldriga skogen. Dess stinkande vatten sipprar nedströms över bergen till Darkshore och blir den besmittade Wildbend River.",h="Bloodvenom River är en vidrig flod som skär genom centrala Felwood, mättad av den demoniska fördärvning som...",kw={"bloodvenom river","fördärvning","darkshore","felwood","slemvarelser","besmittat vatten","wildbend river"},ang={["class:Druid"]="Bloodvenom River är ett tydligt vittnesbörd om skändningen av Kalimdors heliga lundar. Den för med sig demoniskt fördärv mellan regioner och kräver att naturen återställs.",["race:NightElf"]="För kaldorei är det en bitter påminnelse om Legionens kvardröjande sår att se vattnet från deras förfäders skogsmark förgifta Darkshore via Wildbend River."},sec={{t="En åder av fördärvning",b="Bloodvenom River löper genom Felwoods fördärvade hjärta och utgör en öppen kanal för landets andliga och fysiska förfall. Stränderna är täckta av vidriga slemvarelser, muterade bestar och giftigt avfall som lämnades efter Burning Legions invasion. Fördärvningen i flodfåran är så stark att den kan besmitta områden långt bortom själva Felwood, när vattnet rinner västerut till Darkshores kustskogar som Wildbend River."}},faq={{q="Varför är floden fördärvad?",a="Floden rinner genom centrala Felwood, en uråldrig nattalvskog som förvridits djupt av Burning Legions demoniska magi under det tredje kriget. Fördärvningen genomsyrade landet och vattnet, och gjorde floden till en kanal för giftigt slam och nekrotiskt slem.",al={"bloodvenom river fördärv","varför är vattnet grönt","felwood flodgift"}},{q="Vart rinner Bloodvenom River?",a="Floden rinner genom Felwoods besmittade dal innan den störtar genom bergen till Darkshore. Bortom bergsryggen fortsätter dess fördärvade strömmar nedströms under namnet Wildbend River.",al={"bloodvenom river sträckning","vart rinner den","flod till darkshore"}},{q="Vilka varelser lever längs flodbankarna?",a="I vattnet och på de leriga stränderna lever giftiga slemvarelser, förvridet djurliv och fördärvade rovdjur som lockas dit eller skapats av den virulenta demoniska farsoten.",al={"bloodvenom river djurliv","monster nära bloodvenom river","monster i floden"}}},fp="16,178,20.304.0,27.247.0,37.190.0,41.164.0"}
P.entries["subzone:bluefen"] = {n="Bluefen",s="Bluefen är ett blött träskland i norra Dustwallow Marsh, strax öster om Brackenwall Village. Här kryllar det av aggressiva rovdjur, och sankmarken har också blivit en samlingsplats för Theramore Infiltrators, som i hemlighet håller uppsikt över Hordens rörelser i området.",h="Bluefen är ett blött träskland i norra Dustwallow Marsh, strax öster om Brackenwall Village.",kw={"bluefen","brackenwall","krokolisker","dustwallow","träsk","theramore infiltrators"},ang={["faction:Alliance"]="Vilda bestar gör resor farliga, men Theramore-spejare använder Bluefens täta träskvegetation för att hålla den närliggande ogrebylägret under uppsikt.",["faction:Horde"]="Bluefen ligger strax öster om Brackenwall Village och innebär dubbel fara för Hordens kämpar: vildsinta träskbestar och vaksamma Theramore Infiltrators som spionerar på dina Stonemaul-allierade."},sec={{t="Ett omstritt träsk",b="Bluefen ligger strax öster om Stonemaul-ogrerna i Brackenwall Village och visar prov på de otämjda farorna i Dustwallow Marsh. Det fuktiga träsklandet vimlar av rovdjur, bland annat raptorer, jättespindlar, asätande fåglar och lurande krokolisker. Utöver de naturliga rovdjuren måste resande också se upp för Theramore Infiltrators, som smyger genom den grumliga terrängen för att spionera på Horden och utöka människornas inflytande längre in i träsket."}},faq={{q="Var ligger Bluefen?",a="Bluefen ligger i norra Dustwallow Marsh, strax öster om Brackenwall Village.",al={"bluefen plats","var ligger bluefen","bluefen karta"}},{q="Vilka hot finns i Bluefen?",a="Träsket är fullt av farliga varelser, däribland spindlar, krokolisker, raptorer och träskfåglar. Dessutom rekognoserar Theramore Infiltrators området i hemlighet och utgör ett hot mot resande från Horden.",al={"fiender i bluefen","vad lever i bluefen","varelser i bluefen"}},{q="Varför är spejare från Theramore aktiva i Bluefen?",a="Theramore Infiltrators övervakar norra Dustwallow Marsh från Bluefen. De håller uppsikt över den närliggande bosättningen Brackenwall Village, där Stonemaul-ogrerna bor, och patrullerar träskets omstridda stigar.",al={"theramore infiltrators","varför är alliansen här","theramore spioner"}}},fp="7,160,15.305.0,25.76.0,37.152.0,43.144.0"}
P.entries["subzone:bluegill-marsh"] = {n="Bluegill Marsh",s="Bluegill Marsh är ett blött kärr i västra Wetlands, där den fientliga murlocstammen Bluegill har brett ut sin bosättning. De här vattenlevande humanoiderna vaktar vattenvägarna och hyddorna svartsjukt under den brute som kallas Gobbler. Resenärer genom de västra sankmarkerna måste ta sig fram försiktigt för att undvika att bli omringade på grunt vatten.",h="Bluegill Marsh är ett blött kärr i västra Wetlands, där den fientliga murlocstammen Bluegill har brett ut sin...",kw={"bluegill","bluegill marsh","gobbler","menethil","murloc","träsk","wetlands"},ang={["faction:Alliance"]="De aggressiva Bluegill-murlocer som håller till nära Menethil Harbor är ett ständigt besvär för resenärer och försörjningsleder genom västra Wetlands."},sec={{t="En svärm av faror",b="Mitt bland de sumpiga slätterna i västra Wetlands är Bluegill Marsh fullt av lera, vass och de bofasta murlocernas gälla stridsrop. Bluegill-stammen har byggt primitiva läger runtom i det stillastående vattnet och gör anspråk på området. Till skillnad från träskets mer ensamma bestar lever och jagar murlocer i tätt sammansvetsade flockar. Vaksamma vandrare och spejare från Menethil Harbor vet att det snabbt kan gå illa om man vadar in på deras område, särskilt när den väldige hövdingen Gobbler stryker genom det grumliga grunda vattnet."}},faq={{q="Vad är Bluegill Marsh?",a="Bluegill Marsh är ett sumpigt delområde i västra Wetlands. Det är den aggressiva Bluegill-stammens främsta boplats och häckningsområde.",al={"var ligger bluegill marsh","vad är det här för plats","murlocträsk i wetlands"}},{q="Vem styr över kärret?",a="Bluegill-stammen leds av en mäktig och grym murloc som kallas Gobbler. Han håller uppsikt över de tätt samlade lägren och slår ner alla landvandrare som tränger in i deras vatten.",al={"murlocledare i wetlands","gobbler","vem leder bluegill-murlocer"}},{q="Varför är det farligt att resa ensam här?",a="Murlocer här strövar sällan omkring ensamma. De samlas kring hyddor och stränder i täta grupper om två eller tre, så ensamma resenärer kan lätt övermannas i den djupa, trögflytande leran.",al={"varför finns det så många murlocer","är bluegill marsh svårt","murlocaggro"}},{q="Varför beger sig resenärer till Bluegill Marsh?",a="Spejare och äventyrare från närliggande bosättningar som Menethil Harbor skickas regelbundet till kärret för att minska antalet aggressiva murlocer och återta stöldgods som förts till deras läger.",al={"varför bege sig hit","uppdrag i bluegill marsh","anledningar att besöka"}}},fx={c61162da={q="Varför heter platsen Bluegill Marsh?",a="Träsket har fått sitt namn direkt från Bluegill-murlocerna som har byggt flera läger i dess grumliga vatten. Deras aggressiva stam dominerar de västra våtmarkerna här, och området är beryktat under deras namn.",al={"varför bluegill marsh","betydelsen av namnet bluegill marsh","varifrån kommer namnet bluegill marsh"}}},fp="14,164,17.342.0,23.126.0,25.153.0,41.153.0,45.175.0"}
P.entries["subzone:bolgan-s-hole"] = {n="Bolgan's Hole",s="Bolgan's Hole är en underjordisk grotta i de södra klipporna vid Gelkis Village i Desolace. Den fungerar som Gelkis-centaurklanens innersta helgedom och rymmer deras högsta hövdingar och heliga jordreliker.",h="Bolgan's Hole är en underjordisk grotta i de södra klipporna vid Gelkis Village i Desolace.",kw={"bolgan's hole","centaur","desolace","gelkis","khan shaka","theradras tårar"},ang={["class:Shaman"]="Grottan visar bistert hur dyrkan av jorden kan förvridas när den knyts till Princess Theradras våldsamma arv i stället för andarnas naturliga balans."},sec={{t="Gelkis maktsäte",b="Bolgan's Hole är uthuggen djupt i de skrovliga klipporna med utsikt över Gelkis läger och fungerar som stammens Command Center. Här håller den styrande khanen hov, omgiven av erfarna vakter och stammens mest inflytelserika schamaner. Grottan ger ett naturligt skydd mot rivaliserande klaner, framför allt de blodtörstiga Magram-centaurerna i öster."},{t="Jordprinsessans tårar",b="Utöver sin militära betydelse har grottan en djup religiös betydelse för Gelkis. Lysande blå mineralformationer, kända som Theradras tårar, växer fram ur de fuktiga stenväggarna. Gelkis-schamanerna skördar och vaktar dessa kristaller tvångsmässigt och vördar dem som gudomliga välsignelser som skänker skydd under jord från Princess Theradras, centaurernas ursprungliga jordelementarmoder."}},faq={{q="Var ligger Bolgan's Hole?",a="Bolgan's Hole är en grotta i den södra delen av Gelkis Village, inbäddad i kullarna i södra Desolace.",al={"bolgan's hole plats","var ligger bolgan's hole","ingången till bolgan's hole"}},{q="Vem bor i Bolgan's Hole?",a="Grottan rymmer Gelkis-centaurernas högsta ledare, däribland klanens khan, som Khan Shaka, samt deras inre krets av beskyddare och mystiska schamaner.",al={"vem finns i bolgan's hole","boss i bolgan's hole","gelkis khans plats"}},{q="Vad är de lysande blå kristallerna i grottan?",a="Kristallerna kallas Theradras tårar. Gelkis vördar dem som fysiska uttryck för deras jordmoders välvilja och tror att stenarna ger mystiskt skydd åt dem som bär dem.",al={"blå kristaller i bolgan's hole","theradras tårar","stenar i bolgan's hole"}},{q="Kan spelare gå in säkert i Bolgan's Hole?",a="Gelkis-centaurerna där inne är som regel aggressivt fientliga mot främlingar. Resande som ställer sig på Gelkis sida genom att slakta deras hatade rivaler i Magram-klanen kan dock vinna tillräckligt anseende för att röra sig fredligt genom grottan.",al={"är bolgan's hole fientligt","vän med gelkis","kan jag gå in i bolgan's hole"}}},fp="13,132,24.235.0,27.308.0,31.82.0,31.112.0,51.171.0,39.180.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="Bones of Grakkarond",s="Bones of Grakkarond är de skelettrester av en väldig bronsdrake som ligger blekta under solen i centrala Silithus. Denna fallna wyrm, som dödades under det uråldriga War of the Shifting Sands, står som ett dystert monument vördat av qirajis Anubisath-väktare.",h="Bones of Grakkarond är de skelettrester av en väldig bronsdrake som ligger blekta under solen i centrala...",kw={"anubisath","bones of grakkarond","bronsdrake","grakkarond","ossirian the unscarred","silithus","war of the shifting sands"},ang={["race:NightElf"]="Skelettet är en tydlig påminnelse om War of the Shifting Sands, då kaldorei och de fyra drakflyglarna kämpade sida vid sida för att slå tillbaka qirajis anstormning."},sec={{t="Ett monument över skiftande sand",b="Över de vindpinade sanddynerna i centrala Silithus breder Grakkaronds väldiga bröstkorg och skalle ut sig. Han var en bronsdrake som mötte sin död under det uråldriga War of the Shifting Sands. I den apokalyptiska striden för tusen år sedan fälldes den mäktiga draken av Ossirian the Unscarred, en Anubisath-krigare som upphöjts av stadskungadömets mörka krafter. För Anubisath är denna trofé från slagfältet ett heligt vittnesbörd om deras makt över drakflyglarna, lämnad orörd där han föll."}},faq={{q="Vems ben är det här?",a="Det här är resterna av Grakkarond, en mäktig bronsdrake från Bronze Dragonflight. Han föll i strid mot Ahn'Qirajs insektslika styrkor för tusen år sedan under War of the Shifting Sands.",al={"vem var grakkarond","vilken drake dog här","drakskelett silithus"}},{q="Vem dödade Grakkarond?",a="Grakkarond dödades av Anubisath-krigaren Ossirian the Unscarred. Ossirians seger över bronswyrmen gav honom stort anseende och mörka välsignelser från Ahn'Qirajs härskare.",al={"vem dödade draken","hur dog grakkarond"}},{q="Varför vördar Anubisath den här platsen?",a="Anubisath anser att skelettet är heligt eftersom det minner om deras avgörande seger över en mäktig drakflygel. Det står bland de öppna sanddynerna som en triumferande symbol för deras styrka mot dem som kom för att försegla dem.",al={"varför är benen heliga","anubisath-ben"}}},fp="19,172,32.391.0,22.190.0,22.163.0,39.167.0"}
P.entries["subzone:booty-bay"] = {n="Booty Bay",s="Booty Bay är en vidsträckt pirathamn insprängd i de branta havsklipporna i södra Stranglethorn Vale, som drivs av Steamwheedle Cartels Blackwater Raiders. Från land når du hamnen genom gapet i käftarna på ett jättelikt hajkadaver. Här råder strikt upprätthållen neutralitet, och Alliance och Horde möts under beväpnade goblinslagskämpars vaksamma blickar.",h="Booty Bay är en vidsträckt pirathamn insprängd i de branta havsklipporna i södra Stranglethorn Vale, som...",kw={"blackwater raiders","bloodsail buccaneers","booty bay","ratchet","revilgaz","salty sailor","seahorn","steamwheedle cartel","stranglethorn"},ang={["class:Rogue"]="Booty Bay är känt som ett paradis för skurkar och kryllar av kontakter i undre världen, hälerier, låsta kistor och hemliga informatörer som gärna byter hemligheter mot mynt.",["faction:Alliance"]="Booty Bay ligger långt söder om Stormwinds skyddade gränser och erbjuder resenärer från Alliance sällsynta neutrala bekvämligheter, flygrutter och skeppsfärder raka vägen till Kalimdor."},sec={{t="En håla för skurkar och vinst",b="Viken kallades ursprungligen Blackwater Cove. Den var då en mänsklig bosättning som senare övertogs av djungeltroll. Till slut erövrades den av goblinerna i Steamwheedle Cartel. I dag är den en internationell knutpunkt och en fristad för skurkar, utstötta och köpmän. Baron Revilgaz och Fleet Master Seahorn övervakar hamnen från Salty Sailor Taverns balkonger. Här tycks lagarna saknas, men verksamheten sköts ändå strikt. Alla får dricka, handla och anlita legosoldater, så länge de respekterar kartellens fred och betalar hamnavgifterna."},{t="Hot till sjöss",b="De livliga hamnbryggorna i Booty Bay förbinder Eastern Kingdoms direkt med Ratchet på andra sidan Great Sea, vilket gör staden till en viktig knutpunkt för handel och resor mellan kontinenter. Men stadens enorma rikedom lockar till ständiga angrepp. Stadens främsta fiende är Bloodsail Buccaneers, en aggressiv piratflotta som oupphörligen angriper Blackwater-fartyg, patrullerar Stranglethorns kust och planerar att förgöra och plundra goblinhamnen."}},faq={{q="Vem styr Booty Bay?",a="Hamnen styrs av Baron Revilgaz, en framstående medlem av Steamwheedle Cartel, i nära samarbete med Fleet Master Seahorn, taurenbefälhavaren för Blackwater Raiders. De leder båda sin verksamhet från de övre däcken på Salty Sailor Tavern, med utsikt över hamnen.",al={"ledare för booty bay","vem styr booty bay","chef för booty bay"}},{q="Varför kan Alliance- och Horde-spelare stå tillsammans här?",a="Booty Bay kontrolleras av det neutrala Steamwheedle Cartel, som värderar vinst och handel långt högre än fraktionskonflikten. Kartellen håller strikt på sin neutralitet och välkomnar alla som har mynt. Den skickar elittränade goblinslagskämpar på den som är dum nog att starta bråk.",al={"varför är booty bay neutralt","säker zon i booty bay","kan horde attackera alliance här"}},{q="Vilka är Bloodsail Buccaneers?",a="Bloodsail Buccaneers är ett rivaliserande band av laglösa som ligger i bitter strid med Blackwater Raiders. De kontrollerar fartyg längs Stranglethorn Vales sydkust och smider planer på att inta Booty Bay och lägga beslag på den inkomstbringande hamnen.",al={"bloodsail-pirater","varför hatar bloodsail booty bay","bloodsail buccaneers historia"}},{q="Vart seglar båten från Booty Bay?",a="Passagerarfartyget från de nedre hamnbryggorna seglar över Great Sea direkt till hamnstaden Ratchet i The Barrens. Det är den främsta neutrala färdvägen mellan södra Eastern Kingdoms och Kalimdor.",al={"båtdestination från booty bay","vart seglar skeppet","båt till kalimdor"}},{q="Vad föreställer den jättelika statyn vid vikens inlopp?",a="Den väldiga statyn föreställer en okänd goblin med utsträckta armar. Den står på Janeiro's Point, strax utanför hamninloppet. Den fungerar som navigationsmärke och välkomstmonument för handelsfartyg och piratbesättningar på väg in.",al={"statyn i booty bay","kolossen i booty bay","statyn på ön"}}},fp="9,229,30.476.0,20.328.0,20.230.0,55.184.0,33.217.0,38.181.0,56.203.0"}
P.entries["subzone:bough-shadow"] = {n="Bough Shadow",s="Bough Shadow är en avskild lund i Ashenvales nordöstra hörn, öster om Forest Song. Den kretsar kring ett kolossalt Great Tree, vars rötter omsluter en uråldrig portal direkt till The Emerald Dream.",h="Bough Shadow är en avskild lund i Ashenvales nordöstra hörn, öster om Forest Song.",kw={"ashenvale","bough shadow","dragonspawn","dreamstalker","emerald dream","great tree","gröna drakar","phantim","portal"},ang={["class:Druid"]="Bough Shadow är helig mark för druider och rymmer en av de påtagliga trösklarna som länkar Azeroth direkt till Green Flights domän och The Emerald Dream.",["race:NightElf"]="Djupt bortom Forest Song står detta väldiga träd och dess vilande portal som en levande påminnelse om bandet mellan kaldorei och The Emerald Dream."},sec={{t="En port till drömmen",b="I Bough Shadow står ett av de sällsynta Great Trees, med rötter som sträcker sig djupt ner i jorden runt en naturlig passage till The Emerald Dream. I dag vaktas den fridfulla men mäktiga lunden noga av Green Dragonflight. Smaragddrakar som Phantim och Dreamstalker kretsar ovanför trädkronorna, medan patruller av Emeraldon dragonspawn och orakel håller en vaksam och orubblig uppsikt över den virvlande gröna portalen vid trädets fot. De avvisar alla dödliga som närmar sig utan tillstånd."}},faq={{q="Vad är den glödande gröna portalen här?",a="Virveln vid foten av Great Tree är en direkt port till The Emerald Dream, Azeroths otämjda andevärld. Den är en av flera sådana naturliga passager utspridda över världen.",al={"portal i bough shadow","vad är portalen i bough shadow","grön portal i ashenvale"}},{q="Varför vaktar gröna drakar Bough Shadow?",a="Yseras Green Dragonflight har fått i uppdrag att vaka över The Emerald Dream och dess direkta passager till den fysiska världen. Smaragddrakar och dragonspawn patrullerar Bough Shadow för att hindra korrumperande krafter och inkräktare från att ta sig över tröskeln.",al={"varför finns det drakar i ashenvale","green dragonflight i bough shadow","varför gröna drakar här"}},{q="Kan spelare gå in i portalen?",a="Nej. Porten hålls hårt förseglad för dödliga i den fysiska världen, och om du kommer för nära väcker du de omgivande elitskyddsvakternas vrede.",al={"kan jag gå igenom portalen","gå in i portalen i bough shadow","hur går man in i drömportalen"}}},fx={ca240e18={q="Vad är Bough Shadow?",a="Bough Shadow är en avskild glänta i Ashenvales nordöstra utkant, öster om Forest Song. Den ligger kring ett av världens Great Trees och rymmer en mystisk portal som leder rakt in i The Emerald Dream.",al={"vad är det här för plats","berättelsen om bough shadow","om bough shadow"}},["626e8e50"]={q="Vad hände vid Bough Shadow?",a="Vid Bough Shadow står ett av världens Great Trees, med rötterna över en av portalerna till The Emerald Dream. Den gröna drakflykten håller noggrann uppsikt över platsen.",al={"bough shadows historia","historia om bough shadow"}},f0692632={q="Vilka bor vid Bough Shadow?",a="Lunden bebos helt av medlemmar av Green Dragonflight. Drakevarelser som Phantim och Dreamstalker vakar över gläntan, med stöd av patruller av gröna dragonspawn, däribland Emeraldon Tree Warders, Boughguards och Oracles.",al={"vilka är här","vilka bor i bough shadow","invånare i bough shadow"}},["30f2c168"]={q="Är Bough Shadow farligt?",a="Ja, det är mycket farligt för resenärer. De gröna drakarna och deras drakspawn-väktare bevakar portalen med sträng vaksamhet, och de tvekar inte att slå ner dödliga som kommer för nära deras heliga vaka.",al={"är bough shadow säkert","faran i bough shadow"}}},fp="12,156,22.362.0,38.169.0,44.207.0,29.103.0"}
P.entries["subzone:boulder-gor"] = {n="Boulder'gor",s="Boulder'gor är en karg kulle i västra Arathi Highlands, direkt norr om det förstörda människoriket Stromgarde. Den fungerar som ett aktivt läger för Boulderfist-ogrerna och deras ovanliga allierade bland Witherbark-skogstrollen.",h="Boulder'gor är en karg kulle i västra Arathi Highlands, direkt norr om det förstörda människoriket Stromgarde.",kw={"arathi highlands","boulder'gor","boulderfist","og rer","stromgarde","witherbark","vissnad bark"},ang={["faction:Alliance"]="För alliansens styrkor som vill återta Stromgarde utgör Boulder'gor ett allvarligt hot precis vid det fallna rikets norra gräns.",["race:Troll"]="Darkspear-troll som besöker höglandet finner ingen samhörighet här: Witherbark-skogstrollen i Boulder'gor hyser djupt rotade, urgamla agg mot alla främlingar, även andra trollstammar."},sec={{t="Ett näste för og rer och troll",b="Boulder'gor reser sig strax norr om de sönderfallande murarna vid Stromgarde Keep och är en brant klippa som Boulderfist-klanen gör anspråk på. I dess skugga ligger kullen Boulderfist Outpost, som gör platsen till ett centralt fäste för ogremakt i höglandet. Ovanligt nog delar og rerna här eldar och befästningar med skogstroll från Witherbark-stammen, däribland skuggfulla besvärjare som bidrar med sin mörka magi till klanens råstyrka. Detta samarbete utgör ett ständigt hot mot alla resenärer längs Arathis centrala vägar."},{t="Omgivande område",b="Sluttningarna runt Boulder'gor vetter ut över det öppna höglandet i västra Arathi. Boulder'gor ligger inklämt mellan Stromgardes ruiner, som infiltrerats av Syndicate, och slätternas vilda elementplatser, och förblir ett hårt bevakat och fientligt fäste för stamgemenskap mot både alliansens och hordens vandrare."}},faq={{q="Vad är Boulder'gor?",a="Boulder'gor är en upphöjd kulle och ett läger norr om Stromgarde Keep i Arathi Highlands. Här bor stora mängder Boulderfist-ogrer och Witherbark-skogstroll.",al={"var ligger boulder'gor","information om boulder'gor","vad är det här för plats"}},{q="Varför bor skogstroll tillsammans med og rer här?",a="Witherbark-trollen och Boulderfist-ogrerna har en pragmatisk allians i Arathi. Båda vill behålla sitt herravälde över höglandet och hålla rivaliserande fraktioner borta, och förenar trollens skuggkonst med og rernas råstyrka.",al={"varför är troll här","witherbark-allians med og rer","troll och og rer"}},{q="Vilka viktiga landmärken finns nära Boulder'gor?",a="Boulder'gor ligger direkt norr om Stromgarde Keep, och og rernas kulle Boulderfist Outpost ligger inuti själva höjden.",al={"platser i närheten","vad ligger intill boulder'gor","landmärken"}},{q="Är Boulder'gor vänligt inställt till horden eller alliansen?",a="Ingetdera. Boulder'gor-ogrerna och Witherbark-trollen är helt fientliga mot både alliansen och horden och försvarar aggressivt sin kulle mot främlingar.",al={"kan jag gå dit säkert","är boulder'gor fientligt"}}},fp="11,124,25.408.0,21.298.0,20.157.0,50.211.0,42.110.0,49.134.0"}
P.entries["subzone:boulder-lode-mine"] = {n="Boulder Lode Mine",s="I nordöstra Barrens gräver Venture Company sig in i Boulder Lode Mine efter dess rikedomar. Orcherbaner och vakttorn markerar ett område som Horden en gång höll.",h="I nordöstra Barrens gräver Venture Company sig in i Boulder Lode Mine efter dess rikedomar.",kw={"boss copperplug","boulder lode mine","dizzywig","gruvarbetarens lycka","samophlange manual","the barrens","venture company"},ang={["faction:Horde"]="Som medlem av Horden är det en bitter påminnelse om kartellens räckvidd över Kalimdor att se Venture Companys arbetslag verka från befästningar märkta med Hordens baner.",["profession:Mining"]="Som gruvarbetare kan du se rika ådror i de djupa gångarna som skurits in i de torra kullarna, där Venture Company skövlar jorden utan nåd."},sec={{t="Företagets anspråk",b="Väderbitna orcharbeten ramar in gruvmynningen, tecken på att Horden en gång höll eller grundade området. Nu lyder Venture Companys tillsynsmän och handgångna under Boss Copperplug. Goblinsyndikatet utvinner mineraler, ädelstenar och maskindelar ur ravinen, utan större hänsyn till marken eller arbetarna."},{t="Ädelstenar och ritningar",b="Rikedomarna från gruvan har väckt Ratchets intresse. Wharfmaster Dizzywig har skickat legosoldater efter en ryktad jättestor smaragd som hittats i gångarna. Ingenjörer som vill förstå goblinernas maskiner vet också att Boss Copperplug förvarar viktiga driftmanualer i sitt läger."}},faq={{q="Vem kontrollerar Boulder Lode Mine?",a="Venture Company driver Boulder Lode Mine under Boss Copperplug, med beväpnade handgångna och tillsynsmän som bevakar verksamheten.",al={"vem driver boulder lode mine","boulder lode-gruvans boss","vilka finns i boulder lode"}},{q="Ägde Horden gruvan från början?",a="Väderbitna orcharbeten i trä, vakttorn och Hordens baner antyder att Horden först grundade eller gjorde anspråk på platsen innan Venture Company tog kontrollen.",al={"orciska fanor vid boulder lode","hordens gruva","varför finns hordefanor"}},{q="Varför är Wharfmaster Dizzywig intresserad av platsen?",a="Wharfmaster Dizzywig fick höra att en gruvarbetare grävt fram en ovanligt stor smaragd i gångarna. Han anlitar banditer för att stjäla den mot en andel av vinsten.",al={"dizzywigs gruvuppdrag","smaragduppdrag i barrens","gruvarbetarens lycka"}},{q="Vad har Boss Copperplug med samophlangen att göra?",a="Boss Copperplug har driftmanualen till den närbelägna samophlange-maskinen. Ingenjörer i Ratchet skickar äventyrare för att återta boken och dess utspridda sidor från hans besättning.",al={"samophlange manual boulder lode","copperplugs manual","rilli greasygob-gruvan"}}},fx={["60cbae83"]={q="Vad är Boulder Lode Mine?",a="Boulder Lode Mine är en gruvverksamhet bland de klippiga kullarna i nordöstra Barrens. Den byggdes med tydligt orcisk timmer och fanor som antyder att Horden en gång grundade den, men gruvan har tagits över av Venture Company. I dag driver goblinernas förmän och inhyrda väktare febrila utgrävningar djupt inne i berget, på jakt efter värdefulla malmer och dyrbara ädelstenar.",al={"vad är boulder lode mine","boulder lode mine i barrens","om boulder lode mine"}},["97c77cb5"]={q="Vem bor i eller styr Boulder Lode Mine?",a="Gruvan är för närvarande ockuperad av Venture Company, under Boss Copperplugs hänsynslösa överinseende. Han håller uppsikt över en arbetsstyrka som vaktas av förmän och väktare från Venture Company. De driver på utgrävningarna i kullarna och håller samtidigt hårt i exklusiva maskinmanualer och värdefulla fynd.",al={"vem styr boulder lode mine","vem finns vid boulder lode mine","invånare i boulder lode mine"}},a11a7920={q="Är Boulder Lode Mine farligt?",a="Ja. Venture Company välkomnar inte besökare eller inkräktare som snokar runt i deras verksamhet. Gruvan kryllar av beväpnade väktare och vaksamma förmän som attackerar alla som hotar deras anspråk eller försöker plundra de dyrbara mineralådrorna och skatterna där inne.",al={"är boulder lode mine farligt","faror i boulder lode mine","fara från venture company vid boulder lode"}}},fp="17,158,15.292.0,19.272.0,31.111.0,39.151.0,53.152.0,56.177.0"}
P.entries["subzone:boulderfist-hall"] = {n="Boulderfist Hall",s="Boulderfist Hall är en kraftigt befäst ogrebosättning i Arathi Highlands södra kullar, strax norr om Thandol Span. Den är Boulderfist-og­rernas lokala fäste, varifrån de under Kor'gresh Coldrages befäl utövar sin råa makt över de närliggande handelsvägarna och dalarna.",h="Boulderfist Hall är en kraftigt befäst ogrebosättning i Arathi Highlands södra kullar, strax norr om Thandol...",kw={"arathi highlands","boulderfist","boulderfist hall","kor'gresh coldrage","ogrekulle","phalanax","thandol span"},ang={["faction:Alliance"]="Boulderfist-ogrerna håller till strax ovanför Thandol Span och utgör ett ständigt bakhållshot mot Alliansens kurirer och förstärkningar som färdas norrut från Ironforge till Arathi.",["faction:Horde"]="För att säkra Arathi Highlands måste ogrernas självständiga makt brytas och den södra bergskammen rensas, så att Hordens rörelser från Hammerfall skyddas."},sec={{t="Ett fäste byggt på råstyrka",b="Boulderfist Hall är uthugget i de karga södra klipporna i Arathi Highlands och utgör klanen Boulderfists främsta fäste i området. I skydd av jordvallar och djupa grottor upprätthåller ogrekrigare och magiker en befäst bosättning bara några steg från Witherbark Village och den strategiska bron vid Thandol Span. Djupt inne i kullen lurar deras regionala hövding, Kor'gresh Coldrage, tillsammans med väktare som Phalanax. Från detta fäste utövar ogrerna våldsam kontroll över de omgivande vägarna, vilket gör fredliga resor mellan Arathi och Wetlands farliga för både resenärer och försörjningskaravaner."}},faq={{q="Vad är Boulderfist Hall?",a="Det är en befäst ogrekulle med grottor i södra Arathi Highlands, och fungerar som bas för klanen Boulderfists verksamhet i området.",al={"vad är det här för plats","boulderfist-kulle","ogregrotta arathi"}},{q="Vem styr Boulderfist Hall?",a="Fästet leds av ogrehövdingen Kor'gresh Coldrage, som styr sin klan från den djupa grottan inne i kullen tillsammans med kämpar som Phalanax.",al={"vem leder boulderfist hall","ogreboss arathi","kor'gresh"}},{q="Varför är platsen strategiskt viktig?",a="Närheten till Thandol Span gör att Boulderfist-ogrerna kan hota den viktiga landvägen mellan Arathi Highlands och Khaz Modan, stoppa trafiken och ge sig på resenärer.",al={"varför finns ogrer här","fara vid thandol span"}},{q="Är Boulderfist allierade med de närliggande Witherbark-trollen?",a="Ingen formell allians finns dokumenterad. Boulderfist-ogrerna och skogstrollen i Witherbark Village bor nära varandra, och på andra håll i höglandet, vid Boulder'gor, delar Witherbark-trollen till och med mark med ogrerna. Båda är fientliga mot utomstående från alla fraktioner.",al={"är ogrer och troll vänner","witherbark-allians"}}},fp="16,159,27.458.0,25.131.0,27.112.0,45.167.0,61.278.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Boulderfist Outpost",s="Boulderfist Outpost är en befäst kulle djupt inne i ogrebosättningen Boulder'gor i Arathi Highlands. Den fungerar som ett inre näste och förvaringsplats, där aggressiva Boulderfist-ogrer håller till tillsammans med några Witherbark-troll.",h="Boulderfist Outpost är en befäst kulle djupt inne i ogrebosättningen Boulder'gor i Arathi Highlands.",kw={"arathi","boulder'gor","boulderfist","fångar","kovork","ogrekulle","witherbark","vissnad bark"},ang={["faction:Alliance"]="Alliansens spejare som färdas genom Arathi bör hålla sig långt från kullen, eftersom Boulderfist-väktarna där inne angriper alla inkräktare så fort de får syn på dem.",["faction:Horde"]="Boulderfist-ogrerna gör ingen skillnad mellan fraktionerna och angriper hordens vandrare lika gärna som sina rivaler i Alliansen."},sec={{t="Ett fäste i kullen",b="Boulderfist Outpost är uthugget i jorden och stenen i västra Arathi och fungerar som Boulder'gors hjärta. Ovanför dominerar brutala väktare bosättningen, medan utpostens inre samlar klanens främsta styrka och erbjuder ett mörkt skydd under jord. Några Witherbark-trollhäxdoktorer ses ibland bland ogreerna här, vilket antyder ett skört stamsamarbete."}},faq={{q="Var ligger Boulderfist Outpost?",a="Boulderfist Outpost är en inre kulle i den större ogrebosättningen Boulder'gor, som ligger i västra delen av Arathi Highlands.",al={"boulderfist outpost plats","var ligger boulderfist outpost","ingång till boulderfist-kullen"}},{q="Varför finns det troll i en ogreutpost?",a="Witherbark-skogstroll bor i närheten i Arathi Highlands och delar ibland mark med Boulderfist-ogrerna. Några Witherbark-häxdoktorer kan ses utöva sin magi djupt inne i utposten tillsammans med ogreerna.",al={"varför är witherbark här","troll i boulderfist","witherbark-troll i arathi"}},{q="Vem hålls fången i utposten?",a="Det finns inga kända namngivna fångar i utposten i dag. Dess fuktiga korridorer tillhör Boulderfist-väktarna och några Witherbark-häxdoktorer, och den som går in bör räkna med strid snarare än räddning.",al={"boulderfist-fångar","vem hålls fången i boulderfist","fångar hos arathis ogreer"}},{q="Vem leder ogreerna i utposten?",a="Klanens brutala väktare patrullerar det inre, men en ovanligt vildsint ogre vid namn Kovork sägs lura i kullen och utgör ett stort hot.",al={"kovork","boulderfist-boss i arathi","sällsynt boulderfist"}}},fp="19,152,29.357.0,37.104.0,44.201.0,33.204.0,39.134.0"}
P.entries["subzone:boulderslide-cavern"] = {n="Boulderslide Cavern",s="Boulderslide Cavern är ett underjordiskt tunnelsystem längst in i Boulderslide Ravine i Stonetalon Mountains. Det är lya och utgrävningsplats för traktens Boulderslide-kobolder, som maniskt gräver tunnlar efter lysande mineralformationer.",h="Boulderslide Cavern är ett underjordiskt tunnelsystem längst in i Boulderslide Ravine i Stonetalon Mountains.",kw={"boulderslide","grotta","jordvarelse","goggeroc","kobold","resonit","stonetalon"},ang={["class:Shaman"]="Både resonitkristallerna och den slumrande jordvarelsen Goggeroc genljuder av uråldrig jordmagi, ett eko av världens forntida stenskapare.",["profession:Mining"]="Boulderslide-klanen arbetar intensivt i grottan och gräver outtröttligt för att hitta lysande ådror av magisk resonit."},sec={{t="Resonitegruvan",b="Boulderslide-kobolderna har grävt sig djupt in i klipporna i Stonetalon och gjort Boulderslide Cavern till sitt fäste. Till skillnad från vanliga skadedjur som bara söker skydd bryter kobolderna frenetiskt resonit, en sällsynt lysande lila kristall som finns inbäddad i stenen. Kristallerna pulserar av kvarvarande jordmagi och driver varelserna till ursinne mot alla inkräktare som närmar sig gruvan."},{t="Den slumrande jätten",b="Djupare in i grottorna har vårdslös utgrävning blottlagt uråldriga hemligheter. Inbäddad i den underjordiska stenen finns en resonitbehållare med Goggeroc, en slumrande jordvarelse från en svunnen tid. Koboldernas ihärdiga grävande kring denna mystiska relik riskerar att väcka en varelse fylld av uråldrig stenmagi, vilket plötsligt kan hota hela ravinen."}},faq={{q="Vad bryter kobolderna här?",a="Kobolderna bryter resonit, en sällsynt lila kristall som finns inbäddad i grottans klippväggar. Mineralet surrar av svaga spår av jordmagi, vilket gör det till ett värdefullt byte och får kobolderna att vakta sina förråd fanatiskt.",al={"vad är resonit","lila kristaller i stonetalon","varför bryter kobolder"}},{q="Vem är Goggeroc?",a="Goggeroc är en uråldrig jordvarelse som vilar i en resonitbehållare djupt inne i grottan. Koboldernas utgrävning kring hans viloplats riskerar att störa hans sekelgamla slummer.",al={"goggerocs historia","jordvarelse i boulderslide","sovande jätte i grotta"}},{q="Var ligger Boulderslide Cavern?",a="Grottans ingång ligger längst bort i Boulderslide Ravine, bland de klippiga bergen i södra Stonetalon Mountains, strax nordost om stigen mot The Barrens.",al={"boulderslide caverns läge","hitta boulderslide cavern","var ligger grottan"}},{q="Varför är Horde intresserade av den här grottan?",a="Horde håller grottan under uppsikt för att hejda den aggressiva koboldinvasionen som sprider sig i ravinen, och för att de är intresserade av resonitkristallernas magiska egenskaper.",al={"hordeuppdrag i boulderslide","varför skickas jag till boulderslide"}}},fx={["5c565568"]={q="Vad är Boulderslide Cavern?",a="Boulderslide Cavern är en underjordisk gruva långt inne vid slutet av Boulderslide Ravine i Stonetalon Mountains. Den fungerar som både aktivt bo och omfattande utgrävningsplats för traktens kobolder, som outtröttligt gräver fram sällsynta magiska resonitkristaller ur dess steniga djup.",al={"vad är boulderslide cavern","boulderslide caverns bakgrund","om boulderslide cavern"}},["66cd11c1"]={q="Vem bor i Boulderslide Cavern?",a="Grottan bebos helt av kobolderna från Boulderslide. De här aggressiva underjordiska grävarna har byggt sina bon här och arbetar febrilt med att utvinna resonit, samtidigt som de våldsamt försvarar sina tunnlar mot alla inkräktare som vågar närma sig.",al={"vem bor i boulderslide cavern","invånare i boulderslide cavern","vem finns i boulderslide cavern"}},babd5bca={q="Är Boulderslide Cavern farligt?",a="Ja, det är extremt farligt. Kobolderna där inne försvarar sina gruvor med livet som insats och svärmar över alla som tränger in i deras bon. Dessutom har deras djupa utgrävningar nått forntida reliker, däribland en vilande jordvarelse djupt nere i gruvan.",al={"är boulderslide cavern farligt","fara i boulderslide cavern","hot i boulderslide cavern"}}},fp="19,146,16.272.0,20.252.1,33.160.0,16.173.1,37.155.0,43.148.0"}
P.entries["subzone:boulderslide-ravine"] = {n="Boulderslide Ravine",s="Boulderslide Ravine är en karg, avskild ravin bland Stonetalon Mountains centrala toppar, dit du kommer via Webwinder Path. Den har i stort sett skonats från de direkta sammandrabbningarna mellan Horde och Alliance och utgör den steniga vägen till Boulderslide Cavern, samtidigt som den fortfarande är hem åt vilda bergsdjur.",h="Boulderslide Ravine är en karg, avskild ravin bland Stonetalon Mountains centrala toppar, dit du kommer via...",kw={"boulderslide cavern","boulderslide ravine","cliff stormer","baggar","stonetalon","webwinder path"},ang={["profession:Mining"]="Ravinens branta klippväggar är en pålitlig plats att hitta mineralådror som blottats när bergets stenmassor rört sig.",["race:Tauren"]="Den blekta konsten i den lilla sidogrottan har tydliga drag av taurenstammarnas markeringar och antyder urgamla färdvägar genom Stonetalon Mountains höjder."},sec={{t="Ett stilla bergspass",b="Undangömd vid sidan av Webwinder Path är Boulderslide Ravine en smal skreva bland Stonetalon Mountains höjder. Medan skogshuggare, nattalver och Horde strider om timmer och heliga gläntor i hela regionen, förblir det klippiga passet relativt ostört av militärstyrkor. Vilda bergsbaggar och kringströvande klippbestar som Cliff Stormers utgör den lokala faunan och tar sig fram längs de förrädiska avsatserna och de lodräta stenväggarna. Prospektörer håller också ögonen på ravinen, eftersom rika mineralådror ofta blottas längs de steniga sluttningarna som leder djupare in mot grottsystemet."},{t="Spår i stenen",b="Mittemot ingången till Boulderslide Cavern ligger en liten, stillsam grotta med utsikt över ravinen. Skyddet lyses upp av grovhuggna facklor och är fyllt med staplade, väderbitna förrådstunnor. På innerväggarna finns primitiva stammålningar. De grova bilderna påminner slående om uråldriga taurenmönster och antyder att inhemska stammar färdades genom eller sökte tillfälligt skydd bland klipporna långt innan den moderna konflikten nådde bergen."}},faq={{q="Var ligger Boulderslide Ravine?",a="Boulderslide Ravine ligger i Stonetalon Mountains. Du tar dig dit genom att följa Webwinder Path upp bland de högre klipporna.",al={"boulderslide ravine läge","hur man tar sig till boulderslide ravine","var ligger boulderslide ravine"}},{q="Vilka varelser lever i Boulderslide Ravine?",a="Ravinen hyser främst lokala vilda djur, särskilt bergsbaggar och farliga klippstalkare som Cliff Stormers.",al={"varelser i boulderslide ravine","vad finns i boulderslide ravine"}},{q="Vad är den övergivna grottan mittemot Boulderslide Cavern?",a="Mitt emot grottans ingång ligger en liten håla, upplyst av facklor och fylld med gamla tunnor. På stenväggarna finns stamristningar som liknar traditionell taurenkonst, vilket tyder på att lokala vandrare eller jägare använde platsen förr.",al={"övergiven grotta boulderslide","grotta i boulderslide ravine","taurengrotta stonetalon"}},{q="Varför är Boulderslide Ravine betydelsefull?",a="Ravinen utgör den naturliga vägen till Boulderslide Cavern, en underjordisk håla djupt inne i bergen, och erbjuder värdefulla mineralfyndigheter för resande som passerar genom området.",al={"vad används boulderslide ravine till","boulderslide ravines syfte"}}},fx={["92909b11"]={q="Vad är Boulderslide Ravine?",a="Boulderslide Ravine är en karg ravin i bergen i Stonetalon, som nås via Webwinder Path. Den fungerar främst som vägen fram till den djupare Boulderslide Cavern. Kriget mellan Horden och Alliansen härjar i stora delar av de omgivande bergstopparna, men den undangömda ravinen är fortfarande till stor del avskild från striderna.",al={"vad är boulderslide ravine","översikt över boulderslide ravine","boulderslide ravines bakgrund"}},["846b0de4"]={q="Varför är grottan i Boulderslide Ravine övergiven?",a="Mitt emot grottans ingång ligger ett avskilt, övergivet skydd med enkla facklor och gamla tunnor. På väggarna syns bleknad stamkonst som påminner om taurenhantverk, vilket antyder att lokala stammar eller kringvandrande jägare en gång slog läger här, innan de lämnade ravinen åt vilddjuren.",al={"varför är grottan övergiven","övergiven grotta i boulderslide","vem övergav grottan"}},["2463d3df"]={q="Är Boulderslide Ravine farligt?",a="Även om ravinen har skonats från organiserade militära strider är den långt ifrån säker. Lokala baggar betar längs de branta stigarna, och oberäkneliga elementära Cliff Stormers stryker omkring bland klipporna. Det gör det riskabelt för resenärer att ta sig fram oförsiktigt när de söker efter malmådror eller är på väg mot grottan.",al={"är boulderslide ravine farligt","faror i boulderslide ravine","hot i boulderslide"}}},fp="19,252,21.412.0,19.331.0,37.110.0,43.122.0,59.228.0,39.178.0"}
P.entries["subzone:brackenwall-village"] = {n="Brackenwall Village",s="Brackenwall Village är Hordens främsta utpost i Dustwallow Marsh, omgiven av träsk i zonens nordvästra hörn. Byn grundades av Stonemaul-ogrer som överlevde efter att drakar ödelagt deras ursprungliga bosättning i söder. Den fungerar som ett osäkert fäste, omringat av alliansspioner, desertörer och den svarta drakflykten.",h="Brackenwall Village är Hordens främsta utpost i Dustwallow Marsh, omgiven av träsk i zonens nordvästra hörn.",kw={"brackenwall","draz'zilb","dustwallow","infiltratörer","mok'morokk","ogrer","paval reethe","stonemaul"},ang={["faction:Alliance"]="Brackenwall ligger djupt inne på fientligt territorium, men utredningar om den försvunna diplomaten och förrymda desertörer från Theramore för djärva agenter ända fram till utkanten av ogrelägret.",["faction:Horde"]="Brackenwall är din enda fristad och flygförbindelse i träsket. Om du försvarar byn kan Horden behålla en viktig lyssningspost och en försvarsflank mot Theramore."},sec={{t="Stonemauls tillflykt",b="När svarta drakvarelser drev bort Stonemaul-ogrerna från deras uråldriga hem i Stonemaul Village i det södra träsket, ledde deras ledare Overlord Mok'Morokk, efterträdare till Rexxar, de överlevande norrut genom träsket för att bygga Brackenwall. Bosättningen byggdes kring traditionella jordhögar, hyddor och ett gammalt vakttorn och gav den sargade klanen en försvarbar fristad. Byn står på Hordens sida, men plågas av inre förfall: Mok'Morokk sitter sysslolös, lägger beslag på förråd och vägrar konfrontera drakhotet. Därför får personer som ogremagikern Draz'Zilb och Hordens sändebud stå för klanens andliga och taktiska vägledning."},{t="Ögon i träsket",b="Utöver problemen inom byn plågas Brackenwall av yttre hot. Theramores infiltratörer gömmer sig ständigt i snåren, spionerar på byns förehavanden och rapporterar tillbaka till öfästningen. Samtidigt misstänks Paval Reethe, en desertör från Theramore som förvisats från Lost Point, stjäla viktiga förråd från utposten. Med vaksamma ögon i öster och svarta drakar som stryker omkring i söder är Brackenwall Hordens isolerade uppmarschområde, där man håller både Alliansen och Onyxias avkomma på avstånd."}},faq={{q="Varför är ogres här allierade med Horden?",a="Det här är Stonemaul-ogrerna, en hedervärd klan som Rexxar, Hordens förkämpe, upptog i den moderna Horden när Durotar grundades. Rexxar blev deras hövding efter att ha besegrat deras tidigare ledare. Därmed knöt han klanen till hövding Thralls nya allians innan han lämnade över ledarskapet till Mok'Morokk.",al={"varför ogres i horden","stonemaul-klanens historia","vilka är de här ogrerna"}},{q="Varför slog sig Stonemaul ner här i stället för att stanna i sitt gamla hem?",a="Deras förfäders bosättning i södra Dustwallow Marsh invaderades och utplånades av den svarta drakflykten. Overlord Mok'Morokk ledde de fördrivna överlevande norrut genom träsket för att grunda Brackenwall som en befäst tillflyktsort.",al={"vad hände med stonemaul village","varför brackenwall","ogreflyktingar"}},{q="Vem styr Brackenwall Village?",a="Overlord Mok'Morokk leder bosättningen, men många avskyr hans styre. I stället för att samla sitt folk för att återta deras hemland eller konfrontera drakarna hukar han inne i byn och tvingar ogremagikern Draz'Zilb och Hordens sändebud att hantera de dagliga kriserna.",al={"brackenwalls ledare","vem styr brackenwall","mok'morokk"}},{q="Varför finns det spioner från Theramore utanför byn?",a="Trots den sköra vapenvilan mellan Theramore och Orgrimmar håller Lady Jaina Proudmoores militär noga uppsikt över alla truppförflyttningar från Horden i Dustwallow. Infiltratörer rör sig längs Brackenwalls utkant och rapporterar om ogrestyrkan och Hordens operationer.",al={"alliansspioner i dustwallow","infiltratörer från theramore","varför håller theramore uppsikt"}}},fp="19,200,23.518.0,15.405.1,47.266.0,71.218.0,40.235.0,50.205.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Brackwell Pumpkin Patch",s="Defias-brigander har tagit över Brackwell Pumpkin Patch i sydöstra Elwynn Forest. Gården tillhörde en gång familjen Brackwell, men nu används stugan och fälten som gömställe där konspiratörer möts och stulet guld från gruvorna tas emot.",h="Defias-brigander har tagit över Brackwell Pumpkin Patch i sydöstra Elwynn Forest.",kw={"brackwell","defias","elwynn","erlan drudgemoor","morgan the collector","princess","pumpaodling","surena caledon"},ang={["class:Warlock"]="Surena Caledon, en förrymd lärling, gömmer sig i gårdens skjul. Hennes stulna blodstenshalsband behövs för att binda en voidwalker.",["faction:Alliance"]="Den övertagna odlingen är en av Defias Brotherhoods östligaste baser i Elwynn och hotar gårdar och handelsvägar i närheten."},sec={{t="Ett tillhåll för banditer",b="Du hittar Brackwell-gården sydost om The Stonefield Farm, och fälten ligger obrukade. Familjen Brackwell har försvunnit, bortdriven eller värre, när brottsligheten spred sig i området. Defias Brotherhood håller nu till i den stadiga stugan och de igenvuxna fälten. Brigander samlas här, utom räckhåll för Goldshires patruller. Morgan the Collector och andra framstående konspiratörer använder den avskilda gården för att ta emot olagligt guld från skogens gruvor."},{t="Grisar och mörk magi",b="Defias delar pumpakvistarna med en jättesugga vid namn Princess, som Brackwell-familjen lämnade kvar. Hon strövar omkring bland odlingarna och terroriserar grannfälten. Vinden på gården och uthusen rymmer andra farliga förehavanden. Banditen Erlan Drudgemoor förförde Surena Caledon, en skurkaktig trollkarlslärling som flydde från sin mästare i Stormwind med en stulen blodstensartefakt. Hennes närvaro har lockat mörka utövare till gömstället."}},faq={{q="Vad hände med familjen Brackwell?",a="Ingen känner till familjen Brackwells exakta öde. När Defias Brotherhood spred sig över sydöstra Elwynn Forest flydde familjen eller dödades, och lämnade sina pumpafält och gårdshus åt banditerna.",al={"var är familjen brackwell","vem bodde på brackwell-gården","familjen brackwells öde"}},{q="Varför använder Defias Brotherhood den här gården?",a="Gården ger Defias en avskild bas nära skogens gränser. Där förvarar de plundrade varor och organiserar smuggling, bland annat leveranser av stulet gruvguld som kurirer som Morgan the Collector för med sig, långt från Stormwind Guard.",al={"varför är defias här","vad gör banditerna vid pumpaodlingen","defias vid brackwell"}},{q="Vem är Princess?",a="Princess är en enorm, prisbelönt sugga som fötts upp av familjen Brackwell. När hon lämnades kvar efter att gården föll blev hon större genom att gång på gång bryta sig in på The Stonefield Farm och äta deras värdefulla grödor.",al={"jättegris","grisen princess","varför finns det ett enormt vildsvin här"}},{q="Varför kommer trollkarlar till pumpaodlingen?",a="Surena Caledon, lärling hos Stormwinds trollkarlstränare Gakin the Darkbinder, stal ett kraftfullt blodstenshalsband och flydde till gården med sin älskare, Defias-banditen Erlan Drudgemoor. Gakin skickar novisa trollkarlar för att döda henne och återta reliken.",al={"trollkarlsuppdrag brackwell","surena caledon","gakin-uppdraget med voidwalker"}}},fx={f38a2be0={q="Vad är Brackwell Pumpkin Patch?",a="Brackwell Pumpkin Patch är en stormwindisk gård i sydöstra Elwynn Forest. Den var en gång en fridfull bondgård där man odlade mogna pumpor och födde upp boskap, men har nyligen hamnat i kaos och laglösa händer.",al={"brackwell pumpkin patch","vad är det här för gård","brackwell-gården"}},["0e932b65"]={q="Vad hände vid Brackwell Pumpkin Patch?",a="Gården var tidigare en produktiv familjegård, men banditer från Defias Brotherhood tog över området och intog den. Brackwellfamiljen försvann, och gården blev snart en utpost för Defias verksamhet, bland annat gulnavlämningar och olagliga gömställen.",al={"brackwell-gårdens historia","vad hände här","brackwells bakgrund"}},ae1356ee={q="Vem bor på eller styr Brackwell Pumpkin Patch?",a="Gårdens ursprungliga ägare är borta, och banditer från Defias ockuperar nu området. Bland dem gömmer sig personer som Erlan Drudgemoor och hans förrymda älskarinna Surena Caledon här, medan Morgan the Collector använder gården för att ta emot guldförsändelser från lokala gruvor.",al={"vem styr brackwell patch","vem bor vid brackwell","invånare i brackwell"}},["90becbea"]={q="Är Brackwell Pumpkin Patch farligt?",a="Ja, du bör gå försiktigt fram. Beväpnade ficktjuvar från Defias patrullerar pumpafälten, liksom den ökända och glupska prisbelönta grisen Princess, som aggressivt försvarar sina betesmarker med hjälp av sina griseskorter.",al={"är brackwell säkert","faror vid brackwell","är den här gården farlig"}},["43009602"]={q="Varför heter det Brackwell Pumpkin Patch?",a="Platsen är uppkallad efter familjen Brackwell, de mänskliga bönder som slog sig ner här och odlade de särpräglade pumpafälten innan banditräder tvingade bort dem från sitt hem.",al={"brackwells namnets ursprung","varför brackwell","vilka var familjen brackwell"}}},fp="23,203,14.413.0,19.414.1,38.209.0,46.259.0,16.192.0,42.244.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Brambleblade Ravine",s="Brambleblade Ravine är en karg ravin som skär in i den nordöstra kanten av Red Cloud Mesa. Den tjänar som befäst näste åt quilboarstammen Bristleback, som gång på gång plundrar den närliggande taurenbosättningen Camp Narache. Unga taurenkrigare skickas hit för att bevisa sin styrka och skydda sitt hemland från dessa våldsamma inkräktare.",h="Brambleblade Ravine är en karg ravin som skär in i den nordöstra kanten av Red Cloud Mesa.",kw={"brambleblade","bristleback","camp narache","mulgore","quilboar","ravin","red cloud mesa","thornmantle"},ang={["faction:Horde"]="Att rensa ut de aggressiva Bristleback-quilboar i Brambleblade Ravine bidrar till att befästa Hordens tidiga fotfäste i Mulgore.",["race:Tauren"]="För unga tauren som når vuxen ålder i Camp Narache är ett anfall mot Brambleblade Ravine ett av de allra första proven på kampmässig och andlig uthållighet för att försvara stammen."},sec={{t="En tagg i mesans sida",b="Brambleblade Ravine ligger uthuggen i Red Cloud Mesas solstekta jord och är fylld av täta, taggiga snår och quilboarläger. Bristlebackstammen använder denna naturliga fästning som utgångspunkt för räder mot Camp Narache och hotar säkerheten för unga tauren som når vuxen ålder. Bristlebackschamaner och krigare, ledda av Chief Sharptusk Thornmantle, håller till djupt inne i ravinen bland tränade stridsvildsvin. För Shu'halo är ett anfall mot ravinens hjärta en avgörande övergångsrit och en bister nödvändighet för att säkra slätterna."}},faq={{q="Vad är Brambleblade Ravine?",a="Brambleblade Ravine är en ravin vid den nordöstra kanten av Red Cloud Mesa i Mulgore. Den är tätbefolkad av Bristleback-quilboar och fungerar som deras lokala fäste.",al={"brambleblade ravine","vad är brambleblade ravine","brambleblade mulgore"}},{q="Varför anfaller Bristleback-quilboar härifrån?",a="Bristleback-quilboar är våldsamt territoriella och ser taurenfolkets närvaro som ett intrång på marker de gör anspråk på. Från Brambleblade Ravine genomför de frekventa räder mot den närliggande bosättningen Camp Narache.",al={"varför anfaller quilboar","bristlebackmotiv","quilboar camp narache"}},{q="Vem leder quilboar i Brambleblade Ravine?",a="Quilboar här leds av Chief Sharptusk Thornmantle, en mäktig hövding som bor i en stor hydda längst in i ravinen.",al={"brambleblades ledare","quilboarhövding mulgore","chief sharptusk thornmantle"}},{q="Varför tar sig unga tauren till ravinen?",a="Taurenäldste och hövdingar i Camp Narache ger unga krigare i uppdrag att ta sig in i ravinen, slå tillbaka Bristleback-hotet, minska deras antal och besegra deras ledare för att hålla mesan trygg.",al={"taurenuppdrag brambleblade","varför ta sig till brambleblade","uppdrag camp narache"}}},fx={["9e3e8e60"]={q="Vem bor i Brambleblade Ravine?",a="Ravinen är ett befäst bosättningsområde för quilboar från Bristleback. Bristleback har byggt hyddor längs jordstigarna och håller sig med aggressiva stridsvildsvin, stammedlemmar och shamaner. De lyder under Chief Sharptusk Thornmantle och hans släkt.",al={"vem bor i brambleblade ravine","invånare i brambleblade ravine","vem finns i brambleblade ravine"}},cff45375={q="Är Brambleblade Ravine farligt?",a="Det är mycket farligt för oförsiktiga resenärer. Quilboarerna försvarar sina hålor aggressivt och svärmar över inkräktare med tränade stridsvildsvin och mystiska shamaner. Den som tar sig ner i ravinen utan att vara försiktig kan snabbt bli instängd mot de höga kanjonväggarna.",al={"är brambleblade ravine farligt","hur farligt är brambleblade ravine","faran i brambleblade ravine"}}},fp="19,193,26.466.0,28.124.0,53.139.0,46.122.0,41.194.0"}
P.entries["subzone:bramblescar"] = {n="Bramblescar",s="I södra The Barrens för Bramblescars Razormane krig mot Bristleback på andra sidan Gold Road. Täta törnsnår befäster deras bosättning.",h="I södra The Barrens för Bramblescars Razormane krig mot Bristleback på andra sidan Gold Road.",kw={"agama'gor","barrens","bramblescar","bristleback","gold road","quilboar","razormane"},ang={["faction:Horde"]="Som medlem av Horden behöver du hålla Gold Road fri från räder från Bramblescar för att kunna resa tryggt mellan Crossroads, Camp Taurajo och den södra gränsen."},sec={{t="En taggig skans",b="Bramblescar är uthugget bland de taggiga snåren i södra The Barrens. De täta, vassa törnena gör platsen till ett viktigt fäste för Razormane quilboar och håller tillfälliga vandrare borta. Stammen vaktar sitt område med våldsam iver och är fientlig mot främlingar. De ger sig i skärmytslingar med alla som närmar sig och ser alla som inte är quilboar som inkräktare på mark som välsignats av deras uråldriga gudar i vildsvinsgestalt."},{t="En blodig stamfejd",b="Bramblescar lever i ständig spänning med Agama'gor, Bristlebacks läger på andra sidan Gold Road. De rivaliserande stammarna utkämpar ett skoningslöst krig om herraväldet över södra The Barrens. Razormane-krigare strider mot hordens resenärer längs landsvägen och slår tillbaka Bristlebacks plundringståg, så de ständigt är redo för våldsam strid."}},faq={{q="Vem bor i Bramblescar?",a="Razormane-stammen av quilboar bor i Bramblescar. De försvarar sitt törnbemängda läger mot rivaliserande quilboar och resenärer på genomfart.",al={"vem finns här","bramblescar-monster","bramblescar quilboar"}},{q="Varför slåss quilboarerna här mot varandra?",a="Razormane i Bramblescar och Bristleback på andra sidan vägen vid Agama'gor är bittra fiender, fast i en våldsam revirtvist om kontrollen över södra The Barrens.",al={"varför krigar de","razormane mot bristleback","quilboar-krig"}},{q="Var ligger Bramblescar?",a="Bramblescar ligger på The Barrens södra slätter, strax öster om Gold Roads huvudstråk och mittemot Agama'gor.",al={"bramblescars plats","var ligger bramblescar","hur hittar man bramblescar"}},{q="Är quilboarerna här fientliga mot Horde?",a="Ja. Razormane ser Horden som inkräktare på sina heliga stammarker och angriper alla resenärer som kommer för nära.",al={"är bramblescar vänligt","horde-rykte bramblescar"}}},fx={["86a75fd0"]={q="Vad är Bramblescar?",a="Bramblescar är ett läger och tillhåll för Razormane-quilboar i södra Barrens. Det ligger längs huvudvägen, mittemot Bristleback-quilboarernas fäste Agama'gor. Bosättningen fungerar som en befäst bas för Razormane i deras obevekliga territoriella krig mot rivalerna från Bristleback.",al={"vad är bramblescar","information om bramblescar","om bramblescar"}},f9fc9349={q="Är Bramblescar farligt?",a="Ja, Bramblescar är extremt farligt för alla resenärer. Razormane-quilboarerna som bor här är mycket aggressiva och överfaller gärna alla som kommer nära deras tillhåll, oavsett vem de är. Samtidigt utkämpar de ett våldsamt krig mot den närliggande stammen från Bristleback.",al={"är bramblescar farligt","faran i bramblescar","hur säkert är bramblescar"}}},fp="11,145,17.245.0,17.314.0,25.138.0,46.129.0,29.114.0,43.116.0"}
P.entries["subzone:brewnall-village"] = {n="Brewnall Village",s="Brewnall Village är en liten dvärgisk bosättning i Chill Breeze Valley, nära ingången till Gnomeregan. Den grundades av familjen Barleybrew och fungerar som en utpost där djärva bryggexperiment prövas och trakten försvaras mot vilda djur. Trots namnet by består den mest av ett enkelt läger i Dun Moroghs snöiga gnomiska lågland.",h="Brewnall Village är en liten dvärgisk bosättning i Chill Breeze Valley, nära ingången till Gnomeregan.",kw={"barleybrew","öl","brewnall","chill breeze valley","dun morogh","gnomeregan","stout"},ang={["race:Dwarf"]="För dvärgar är Barleybrew-familjens jakt på det ultimata receptet ett hedervärt mål som värnar om en av Ironforges främsta traditioner.",["race:Gnome"]="Byn ligger nära Gnomeregan och är en oväntad dvärgisk utpost djupt inne bland de gnomiska dalarna i västra Dun Morogh."},sec={{t="En bitter brygd i dalen",b="Brewnall Village ligger undangömt i snödrivorna i Chill Breeze Valley, mitt i de traditionella gnomiska trakterna i västra Dun Morogh. Här bor klanen Barleybrew, hängivna dvärgbryggare som strävar efter att fullända urgamla recept och skapa den bästa stouten. Trots att platsen kallas en by består utposten mest av tält och bryggutrustning utomhus, snarare än permanenta stenbyggnader. Barleybrew-familjen testar experimentella ölsorter och försvarar sig mot dalens vildsinta vargar och björnar, och förlitar sig på kringvandrande bergsmän för att samla sällsynta ingredienser och hålla dalen trygg."}},faq={{q="Vad är Brewnall Village?",a="Brewnall Village är ett litet dvärgläger i Chill Breeze Valley i västra Dun Morogh, strax öster om Gnomeregan. Det är en utpost där klanen Barleybrew experimenterar med nya ölsorter och hanterar hot från traktens vilda djur.",al={"var ligger brewnall","vad är brewnall village","information om brewnall"}},{q="Varför kallas det en by om det inte finns några byggnader?",a="Trots namnet by är platsen egentligen ett läger under bar himmel med tält och tunnor med förråd. Barleybrew-familjen har etablerat sin bryggverksamhet här i det kalla klimatet utan att bygga riktiga stenhus.",al={"varför är det ett läger","var finns husen","brewnalls byggnader"}},{q="Varför ligger en dvärgisk bosättning i gnomiskt territorium?",a="Västra Dun Morogh omger Gnomeregan och bebos främst av gnomer, men den nära alliansen mellan Ironforge och gnomerna gör gemensamma bosättningar vanliga. Barleybrew-familjen slog sig ner här i Chill Breeze Valley för att ägna sig åt sitt hantverk i lugn och ro.",al={"dvärgar nära gnomeregan","varför är dvärgar här","dvärgläger i gnomiskt territorium"}},{q="Vilka problem möter invånarna?",a="Lägret utsätts ofta för angrepp från dalens aggressiva vilda djur, särskilt klippvildsvin, björnar och frostvargar. Dessutom letar Barleybrew-familjen ständigt efter sällsynta och exotiska ingredienser för att skapa nya och bättre brygder.",al={"brewnalls uppdrag","vad behöver barleybrew-familjen","problem i byn"}}},fx={c4fa2ce1={q="Vem bor i Brewnall Village?",a="Brewnall Village är hem och testplats för familjen Barleybrew. De här dvärgbryggarna har slagit läger här i Chill Breeze Valley för att ägna sig helt åt sitt hantverk och ständigt experimentera för att finslipa och fullända konsten att brygga dvärgal.",al={"vem styr brewnall","invånare i brewnall village","vem bor i brewnall village"}}},fp="16,145,27.379.0,25.196.0,53.162.0,57.186.0,36.155.0"}
P.entries["subzone:brightwater-lake"] = {n="Brightwater Lake",s="Brightwater Lake är den största sjön i Tirisfal Glades och sträcker sig över de dimhöljda låglanden nordost om Brill. En gång var den en fridfull tillflyktsort i kungariket Lordaeron. Nu ligger vattnet kallt och mörkt kring en central ö, där en utstött nekromantiker bedriver förbjuden forskning.",h="Brightwater Lake är den största sjön i Tirisfal Glades och sträcker sig över de dimhöljda låglanden nordost...",kw={"brightwater lake","brill","gunther arcanus","gunther's retreat","nekromantiker","scarlet watch post","tirisfal glades","odöda"},ang={["class:Mage"]="På sjöns ö finns ett unikt prov på den okontrollerade mästerskap som den avfällige magikern Gunther Arcanus uppvisar.",["race:Undead"]="För Forsaken är kontrollen över Brightwater Lake avgörande för att försvara Brills östra infarter och bedöma om den självständige nekromantikern Gunther Arcanus blir en tillgång eller en fiende."},sec={{t="Vattnen i norr",b="Brightwater Lake breder ut sig över de norra slätterna mellan staden Brill och Scarlet Watch Post och är ett stillsamt, kusligt landmärke i hjärtat av Tirisfal. Under kungariket Lordaerons fredliga århundraden var sjön en naturskön tillflyktsort på landsbygden. I dag är dess orörda karaktär sedan länge borta, liksom i resten av Tirisfal Glades. Plaguelands ligger inte långt österut, och det grumliga, kalla vattnet speglar bara grå himmel, vissna träd och det ständiga hotet från kringströvande murlocs och fientliga odöda."},{t="Eremitens tillflykt",b="Mitt i Brightwater Lake ligger en ö som kallas Gunther's Retreat. Gunther Arcanus bröt sig själv fri från Lich King's kontroll, men trodde att alla andra odöda fortfarande var Scourges slavar. Han isolerade sig och lät odöda tjänare vakta sin tillflykt. Bethor Iceshard vill visa sin gamle vän att även Forsaken har en fri vilja. När en äventyrare bevisar sitt motstånd mot Scourge går Gunther med på att ansluta sig till Forsaken."}},faq={{q="Var ligger Brightwater Lake?",a="Brightwater Lake ligger i nordöstra Tirisfal Glades, strax nordost om Forsakens knutpunkt Brill. Sjön ligger precis söder om den karga North Coast och väster om Scarlet Watch Post, som bevakar bergspassen mot Western Plaguelands.",al={"brightwater lake plats","var ligger brightwater lake","hitta brightwater lake"}},{q="Vem bor på ön mitt i sjön?",a="Den centrala ön kallas Gunther's Retreat. En isolerad nekromantiker och hans odöda tjänare bor där, vilket väcker intresse hos Forsaken i närliggande Brill och Undercity.",al={"vem finns på ön","gunther arcanus","npc på brightwater island"}},{q="Vilka hot finns kring vattnet?",a="Resenärer längs stränderna stöter ofta på aggressiva vilefin och murlocs som letar föda längs strandkanten. Närmare man sig den centrala ön hotar de odöda tjänare som svurit att skydda Gunther Arcanus från inkräktare.",al={"sjömonster","fiender vid brightwater","faror vid brightwater lake"}},{q="Varför pratar vakterna i Brill om ett sommarläger här?",a="Dödsvakterna i Brill skämtar torrt om att Forsaken försökte driva ett sommarläger för barn vid Brightwater Lakes stränder, men tvingades stänga det eftersom maskerade psykopater terroriserade området. Det är ett makabert lokalt skämt som speglar människornas lägereldsberättelser.",al={"rykte om sommarläger","skämt om sjön från brill-vakter","maskerad psykopat på läger"}}},fx={["010a8c36"]={q="Vad är Brightwater Lake?",a="Brightwater Lake är den största vattenmassan i Tirisfal Glades och sträcker sig nordost om Brill. I öster kantas sjön av kullar som leder mot Scarlet Watch Post. Mitt i det mörka vattnet ligger en framträdande ö som kallas Gunther's Retreat, tillsammans med mindre klippöar som är utspridda över sjön.",al={"vad är brightwater lake","brightwater lake och dess historia","berätta om brightwater lake"}},["5d21e80d"]={q="Vad är Brightwater Lakes historia?",a="Före pesten var Brightwater Lake en fridfull idyll på landsbygden i kungariket Lordaeron. I dag omger det kalla vattnet Gunther's Retreat, där den odöda magikern Gunther Arcanus gömmer sig från omvärlden.",al={"brightwater lakes historia","vad hände vid brightwater lake","brightwater lake förr i tiden"}}},fp="16,194,19.347.0,19.415.1,34.218.0,50.169.0,41.124.0,57.224.0"}
P.entries["subzone:brightwood-grove"] = {n="Brightwood Grove",s="Brightwood Grove är ett skuggigt skogsområde strax väster om Darkshire i Duskwood. Det som en gång var en fridfull jordbruksbygd är nu hemsökt av vilda Nightbane-worgen, som slår läger bland ruinerade gårdar och anfaller alla resenärer som kommer för nära.",h="Brightwood Grove är ett skuggigt skogsområde strax väster om Darkshire i Duskwood.",kw={"brightwood grove","darkshire","duskwood","night watch","nightbane","vargmän","worgen"},ang={["class:Hunter"]="Lundens mörka snår gör det svårt att spåra de vildsinta Nightbane. De prövar jägarens uppmärksamhet med bakhåll som lurar bakom trädridån.",["faction:Alliance"]="Brightwood Grove ligger precis utanför Darkshires portar, så det är avgörande att utrota worgenflockarna där för att hindra att den hårt ansatta staden skärs av från väster."},sec={{t="En lund i skugga",b="Brightwood Grove ligger inom synhåll från Darkshires utkanter och utgör det växande hotet mot stadens gränser. Gårdarna och stängslen som en gång avgränsade fridfull åkermark ligger nu rasade och ruttnande. I deras ställe har Nightbane-worgen byggt enkla läger och stryker omkring på de igenvuxna gläntorna. De här vargbestarna så nära staden utgör ett ständigt hot. Därför måste Night Watch och förbipasserande äventyrare hela tiden minska deras antal innan bosättningen blir övermannad."}},faq={{q="Var ligger Brightwood Grove?",a="Brightwood Grove ligger i östra Duskwood, strax väster om staden Darkshire längs huvudvägarna.",al={"brightwood grove plats","var ligger brightwood grove","brightwood duskwood"}},{q="Vilka varelser håller till i Brightwood Grove?",a="Lunden är full av vilda Nightbane-worgen. Dessa förbannade vargmän har slagit upp enkla läger bland de ruinerade byggnaderna och anfaller alla som kommer nära.",al={"monster i brightwood grove","fiender i brightwood","vad lever i brightwood"}},{q="Varför är lunden farlig för Darkshire?",a="Eftersom Brightwood Grove ligger precis väster om Darkshire utgör de aggressiva worgenflockarna som lurar i snåren ett omedelbart hot mot stadens patruller, försörjningsleder och alla resenärer som kommer längs vägen.",al={"varför är brightwood grove farligt","hotet från brightwood mot darkshire"}},{q="Finns det några vänligt sinnade bosättningar i lunden?",a="Nej. De få stenbyggnaderna och gårdarna i utkanten av lunden ligger helt i ruiner, övergivna åt väder och vind och bebodda av kringströvande worgen.",al={"finns det vänligt sinnade i brightwood","brightwood stad"}}},fx={d7b16ad8={q="Vad är Brightwood Grove?",a="Brightwood Grove är ett skuggigt område strax väster om Darkshire i Duskwood. Lunden var en gång en del av den grönskande skogen, innan mörkret kröp in över trakten, men ligger nu under ett tryckande mörker. Byggnaderna som en gång stod utspridda längs dess gränser har rasat till ruiner, och förvildade flockar av Nightbane-worgen har gjort anspråk på de igenvuxna fälten och skogarna som sina jaktmarker.",al={"brightwood grove","vad är brightwood grove","brightwood i duskwood"}},d83f7d45={q="Varför ligger Brightwood Grove i ruiner?",a="Liksom stora delar av Duskwood föll Brightwood Grove offer för den förbannelse och skräck som spred sig och slukade trakten. Gårdarna och byggnaderna i utkanterna övergavs och förföll när rovlystna Nightbane-worgen flyttade in. I stället för fridfulla åkrar eller skyddade utposter finns nu bara primitiva bestläger och krossade stenfundament kvar.",al={"varför ligger brightwood grove i ruiner","ruinerna i brightwood","varför övergavs brightwood grove"}},f237257f={q="Är Brightwood Grove farligt?",a="Brightwood Grove är ytterst farligt för resande. Vilda Nightbane-worgen stryker omkring på de mörka fälten, slår upp primitiva läger och attackerar ursinnigt alla som närmar sig. Eftersom området ligger precis väster om Darkshire utgör de glupska vargmännen ett ständigt hot mot stadens utkanter. Därför måste ståndaktiga försvarare och äventyrare aktivt minska deras antal.",al={"är brightwood grove farligt","faror i brightwood","hur farligt är brightwood grove"}},["90b29732"]={q="Varför kallas det Brightwood Grove?",a="Ingen bevarad källa förklarar lundens namn. Det verkar minna om en ljusare tid, då Duskwood var en lummig, solbelyst skog under Stormwinds beskydd. Skuggorna, förbannelserna och worgen har sedan dess helt stulit ljuset från skogen.",al={"varför kallas det brightwood grove","betydelsen av brightwood groves namn","brightwoods namns ursprung"}}},fp="16,108,17.325.0,26.87.0,40.125.0,40.151.0,48.154.0"}
P.entries["subzone:brill"] = {n="Brill",s="Brill är de Fördömdas främsta bosättning i hjärtat av Tirisfal Glades, strax norr om Ruins of Lordaeron. Staden var en gång en blomstrande mänsklig ort, men fungerar nu som administrativt och militärt centrum för nyväckta odöda som lämnar Deathknells gränser.",h="Brill är de Fördömdas främsta bosättning i hjärtat av Tirisfal Glades, strax norr om Ruins of Lordaeron.",kw={"brill","de fördömda","gallows' end","lordaeron","magistrate sevren","tirisfal glades","zeppelin"},ang={["faction:Horde"]="Zeppelinkajen utanför staden är norra hordens främsta förbindelse mellan Lordaeron och de allierade fästena i Kalimdor och Eastern Kingdoms.",["race:Undead"]="För Fördömda som lämnar Deathknell är Brill den första glimt av civilisation och platsen där de får börja bevisa sin lojalitet mot den mörka damen."},sec={{t="Från pestmark till fäste",b="Före det tredje kriget var Brill en livlig by under regionala adelsfamiljer som Barov och Agamand. Blomstringen tog slut när Kel'Thuzad valde området för The Cult of the Damned allra första experiment med odödhetens pest. Den förödande farsoten spreds så snabbt genom befolkningen att den lokala milisen drevs bort och lämnade en vidsträckt massgrav efter sig.\n\nNu har de Fördömda återuppbyggt staden under Magistrate Sevrens ledning. Den har kvar sin väderbitna Lordaeron-arkitektur, men präglas av ett bistert syfte. Brill fungerar som regionalt kommandocentrum och samordnar försvaret mot Scarlet Crusades angrepp, kringströvande rester av Scourge och inhemska bestar som förvridits av nekromantisk förruttnelse."},{t="Norra Lordaerons knutpunkt",b="Brill är också en viktig knutpunkt som förbinder Tirisfal Glades med den större horden. Ovanför staden erbjuder goblinernas zeppelintorn resor söderut mot Durotar och ända till Stranglethorn Vale. I bosättningen fungerar Gallows' End Tavern inte bara som ett mörkt skydd för resenärer, utan också som ett improviserat laboratorium där tillfångatagna fanatiker från Scarlet Crusade förhörs och utsätts för alkemiska tester."}},faq={{q="Vem styr Brill?",a="Magistrate Sevren ansvarar för Brills civila förvaltning och lokala försvar på Lady Sylvanas Windrunners och de Fördömdas vägnar.",al={"brills ledare","vem styr brill","brills magistrat"}},{q="Varför finns det en så stor gravplats utanför Brill?",a="Kel'Thuzad utförde några av sina allra första försök på levande med odödhetens pest i Brill. Smittan utplånade den lokala mänskliga befolkningen i fasansfullt snabb takt, så en massgrav behövdes för att begrava offren innan de reste sig som Scourge.",al={"brills gravplats","kyrkogården nära brill","varför så många gravar"}},{q="Vad används Gallows' End Tavern till?",a="Förutom att ge trötta resenärer husrum fungerar värdshusets källare som bas för alkemister som utför kemiska och toxikologiska experiment på tillfångatagna fanatiker från Scarlet Crusade.",al={"gallows' end","värdshuset i brill","vad händer på värdshuset i brill"}},{q="Vart går zeppelintornet utanför Brill?",a="Zeppelintornet, som sköts av gobliner, förbinder Lordaeron direkt med Kalimdor utanför Orgrimmar och går även söderut till Grom'gol Base Camp i Stranglethorn Vale.",al={"zeppeliner från brill","vart går luftskeppen från brill","flygvägar från brill"}}},fx={["0490a2ec"]={q="Vad är Brill?",a="Brill är den centrala bosättningen i Tirisfal Glades, strax norr om Ruins of Lordaeron. Den var en gång en sömnig mänsklig by, men fungerar nu som ett viktigt militärt nav och en utpost för Forsaken. Nya rekryter från Deathknell rapporterar hit för att hjälpa Lady Sylvanas Windrunners styrkor att säkra gläntorna mot hot som närmar sig.",al={"vad är brill","översikt över brill","staden brill"}},["3209731c"]={q="Vad hände med Brill förr i tiden?",a="Under det tredje kriget var Brill en av de första byarna som drabbades av de odödas pest, när nekromantikern Kel'Thuzad inledde sina mörka experiment i Tirisfal Glades. Byns försvarare övermannades och de överlevande tvingades fly innan prins Arthas undersökte trakten. Efter att Scourge dragit fram genom kungariket återtog Forsaken den förstörda bosättningen och byggde upp den till sitt främsta befästa nav norr om huvudstaden.",al={"brills historia","vad hände i brill","brills historia och sägner"}},fbdb53db={q="Är Brill farligt?",a="Inom Brills gränser försvaras staden väl av vaksamma Deathguards och Magistrate Sevren. Utanför staden hotar faror från alla håll. Hjärndöda Scourge stryker omkring på landsbygden, våldsamma Rot Hide-kobolder genomsöker de närliggande vattendragen och fanatiska Scarlet Crusaders för ett skoningslöst krig över gläntorna. De vill utplåna alla som bor i bosättningen.",al={"är brill tryggt","hot mot brill","är brill farligt"}}},fp="5,198,29.552.0,32.284.0,16.121.0,52.235.0,37.137.0,54.130.0"}
P.entries["subzone:brill-town-hall"] = {n="Brill Town Hall",s="Brill Town Hall är den administrativa kärnan i bosättningen Brill, mitt i Tirisfal Glades. Som stadens mest framträdande byggnad fungerar den som samhällshögkvarter, där Forsaken styr sina lokala besittningar och samordnar försvaret av gläntorna.",h="Brill Town Hall är den administrativa kärnan i bosättningen Brill, mitt i Tirisfal Glades.",kw={"brill","forsaken","lordaeron","magistrate sevren","sevren","tirisfal glades","stadshus"},ang={["faction:Horde"]="Allierade till Horde som anländer till Tirisfal kan besöka stadshuset för att förstå hur Forsaken upprätthåller samhällsstyre och militär ordning i sina förmörkade hemländer.",["race:Undead"]="För Forsaken som ger sig av från Deathknell är stadshuset den första inblicken i ett organiserat samhällsstyre under drottning Sylvanas välde, där lokalt försvar och återerövring formellt samordnas."},sec={{t="Forsakens styressäte",b="Medan stora delar av Lordaeron ligger sönderslagna och ödelagda står Brill Town Hall kvar som ett fungerande samhällscentrum under odöd kontroll. Inne i byggnaden leder Magistrate Sevren stadens angelägenheter från sitt podium och delar ut viktiga uppdrag och direktiv till Forsaken-äventyrare. Bortsett från Defiler's Den i Arathi Highlands är det en av få erkända stadshus i den kända världen som aktivt drivs av Forsaken. Det är en dyster parodi på och en fungerande fortsättning av det gamla Lordaerons kommunala byråkrati."}},faq={{q="Vad används Brill Town Hall till?",a="Det fungerar som lokalt styressäte för bosättningen Brill. Forsakens ledarskap, särskilt Magistrate Sevren, använder byggnaden för att samordna det lokala försvaret, utfärda påbud och tilldela resenärer och nyväckta odöda viktiga uppgifter.",al={"brill town halls syfte","vad är den här byggnaden","varför besöka brill town hall"}},{q="Vem bestämmer här?",a="Magistrate Sevren leder stadshuset från sitt podium, sköter kommunala angelägenheter på Forsakens vägnar och styr verksamheten i centrala Tirisfal Glades.",al={"vem styr brill town hall","ledare för brill town hall","vem är magistraten"}},{q="Varför är det här stadshuset särskilt jämfört med andra?",a="Stadshus är vanligtvis lämningar från levande människoriken. Brill Town Hall är särskilt eftersom det är en av få aktiva samhällsbyggnader som Forsaken upprätthåller och driver. Endast platser som Defiler's Den i Arathi liknar det.",al={"unik stadshall för forsaken","finns det andra stadshus för forsaken"}}},fx={["27f01e5a"]={q="Vad är Brill Town Hall?",a="Brill Town Hall är den mest framträdande byggnaden i Brill, i centrala Tirisfal Glades. Den utgör stadens medborgerliga och administrativa hjärta, där Forsakens ledare sköter lokala angelägenheter och samordnar insatser i trakten.",al={"vad är brill town hall","brill town hall som plats","brills stadshus"}},["0a44eaf1"]={q="Är Brill Town Hall farligt?",a="Inte om du är en allierad till Forsaken och Horde. Brill Town Hall står stadigt under Forsakens kontroll och fungerar tryggt som deras lokala styresäte. Men inkräktare som är fientligt inställda till Dark Lady får ingen nåd innanför dess väggar.",al={"är brill town hall farligt","är brill town hall tryggt","faror i brill town hall"}}},fp="15,122,26.379.0,37.178.0,22.166.0,49.162.0"}
P.entries["subzone:broken-hall"] = {n="Broken Hall",s="Broken Hall är den översvämmade yttre förhallen till det sjunkna Temple of Atal'Hakkar i Swamp of Sorrows. Denna ruin krossades när den stora drakeaspekten Ysera och hennes flyg slet ner den väldiga zigguraten under vattnet. Nu står den öde medan Atal'ai-fanatikerna drar sig tillbaka till djupare helgedomar.",h="Broken Hall är den översvämmade yttre förhallen till det sjunkna Temple of Atal'Hakkar i Swamp of Sorrows.",kw={"atal'ai","broken hall","hall of masks","pool of tears","sunken temple","swamp of sorrows","the temple of atal'hakkar"},ang={["race:Troll"]="För troll som vördar loa är Broken Hall en dyster påminnelse om den förödelse som drabbade Atal'ai-fanatikerna när de trotsade resten av sitt folk för att tjäna Hakkar the Soulflayer."},sec={{t="Översvämmad förhall",b="När de gröna drakarna lät sin vrede drabba Atal'ai-prästerskapet och sänkte deras oheliga ziggurat under Pool of Tears, tog den yttersta arkitekturen den värsta stöten av katastrofen. Golvet i Broken Hall rasade helt samman och lät grumligt träskvatten fylla kammaren. På grund av skadorna och översvämningen övergav trollkultisterna denna entréhall och drog sig längre in i komplexet. Äventyrare som går in i det sjunkna templet måste vada genom dessa genomblöta ruiner innan de går uppför trapporna till Hall of Masks."}},faq={{q="Vad är Broken Hall?",a="Det är den yttersta entrékammaren i Temple of Atal'Hakkar, precis innanför den översvämmade ingången under Pool of Tears.",al={"översikt över broken hall","vad är det här för plats","templets entréhall"}},{q="Varför är Broken Hall översvämmad och förstörd?",a="Kammaren krossades när den gröna drakflygeln drog hela templet under träskvattnet för att stoppa frammanandet av blodduden Hakkar. Golvet bröts sönder och hallen dränktes.",al={"varför är broken hall blöt","varför är broken hall översvämmad","vem förstörde hallen"}},{q="Bor det några Atal'ai-troll i den här hallen?",a="Broken Hall ligger till största delen övergiven. Efter att den övre delen av templet dränktes drog sig Atal'ai-kultisterna tillbaka till torrare och lättare försvarade kammare längre in i komplexet.",al={"fiender i broken hall","är broken hall tom"}},{q="Vart leder trapporna i Broken Hall?",a="Om du går uppför stentrapporna från den översvämmade Broken Hall kommer du direkt till Hall of Masks.",al={"trappor i broken hall","utgång från broken hall","vart går man från broken hall"}}},fp="11,205,17.342.0,24.130.0,42.190.0,49.159.0,44.79.0"}
P.entries["subzone:broken-pillar"] = {n="Broken Pillar",s="Broken Pillar är en väderbiten samling forntida trollruiner som skjuter upp ur sanddynerna söder om Gadgetzan. Platsen fungerar som en avskild forskningspost för goblinprospektören och vetenskapsmannen Marvon Rivetseeker, som studerar de gåtfulla föremål som ligger begravda under sanden runtomkring.",h="Broken Pillar är en väderbiten samling forntida trollruiner som skjuter upp ur sanddynerna söder om Gadgetzan.",kw={"broken pillar","gadgetzan","gahz'ridian","marvon rivetseeker","ratchet","tanaris","trollruiner"},ang={["race:Gnome"]="Marvon Rivetseekers nyfikenhet på okända relikers egenskaper speglar gnomernas vetenskapliga ambitioner, även om hans metoder är typiskt gobliniska.",["race:Troll"]="De sönderfallande pelarna är högtidliga lämningar av trollens förfäders arkitektur och bär ekon från en tid innan imperiets välde över södra Kalimdor bröts ned av tid och sand."},sec={{t="Solblekt sten",b="Broken Pillar reser sig ur sanden söder om Gadgetzan och öster om det förrädiska Abyssal Sands och markerar resterna av forntida trollarkitektur som Tanaris länge har slukat. Trots den ödsliga omgivningen och ökenbestarnas framfart erbjuder platsen sällsynta ledtrådar om kontinentens förhistoriska civilisationer. Goblinforskaren Marvon Rivetseeker, som ursprungligen höll till i Ratchet, har slagit läger ensam intill det sönderslagna stenverket för att undersöka märkliga reliker kallade Gahz'ridian, som ligger utspridda över ödemarken."}},faq={{q="Vad är Broken Pillar?",a="Broken Pillar är en forntida trollruin mitt i Tanaris, söder om Gadgetzan och öster om Abyssal Sands. Nästan inget av den ursprungliga byggnaden återstår, förutom väderbitna stenpelare och bråte som delvis begravts i de drivande sanddynerna.",al={"broken pillar tanaris","vad är broken pillar","pelarruiner"}},{q="Vem har slagit läger vid Broken Pillar?",a="Marvon Rivetseeker, en nyfiken goblinvetenskapsman och prospektör från Ratchet, har slagit upp ett ensligt forskningsläger bland ruinerna. Han undersöker de mystiska Gahz'ridian-ornamenten som ligger begravda i öknen runtomkring.",al={"vem är vid broken pillar","npc vid broken pillar","marvon rivetseeker plats"}},{q="Vem byggde de ursprungliga ruinerna här?",a="Stenverket har forntida trollstil och härstammar från den tid då forntida trollimperier härskade över södra Kalimdor, långt innan ökensanden uppslukade området.",al={"vem byggde broken pillar","broken pillars historia","broken pillars ursprung"}},{q="Vad är Gahz'ridian-reliker?",a="Gahz'ridian är forntida stenföremål och uthuggna ansikten som ligger begravda i Tanaris sand. Marvon Rivetseeker studerar dem från sitt läger vid Broken Pillar för att avslöja hemligheterna och kraften i det försvunna imperiets hantverk.",al={"gahzridian","vad är gahzridian","marvons uppdragsföremål"}}},fp="13,163,18.419.0,26.194.0,35.187.0,34.154.0,28.208.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="Bronzebeard Encampment",s="Bronzebeard Encampment är en karg dvärgutpost i södra Silithus, strax öster om den väldiga The Scarab Wall. Lägrets härdade upptäcktsresande och forskare från Explorer's League använder det som bas för att undersöka urgamla silithidrunor och gåtorna som dröjer kvar under öknens sand.",h="Bronzebeard Encampment är en karg dvärgutpost i södra Silithus, strax öster om den väldiga The Scarab Wall.",kw={"bronzebeard encampment","deathclasp","explorers league","frankal stonebridge","glibb","rutgar glyphshaper","the scarab wall","silithus"},ang={["faction:Alliance"]="För alliansens resenärer som färdas genom Silithus dystra vidder är det avlägsna lägret en välkommen, vänligt sinnad utpost långt söder om Cenarion Hold.",["race:Dwarf"]="Utposten visar prov på Explorer's Leagues orubbliga uthållighet och bevisar att ingen ofruktbar öken är för fientlig för Ironforges dvärgar när de söker historisk sanning."},sec={{t="Ett fäste i den skiftande sanden",b="Vid Silithus ödsliga sydliga klippor erbjuder Bronzebeard Encampment en sällsynt tillflykt präglad av dvärgarnas hårdhet i en annars fientlig ödemark. Lägrets grundades inom ramen för Ironforges arkeologiska expeditioner och ligger inom synhåll från den väldiga The Scarab Wall. Här trotsade forskare som Rutgar Glyphshaper och Frankal Stonebridge den brännande hettan, skorpionerna och de växande silithidsvärmarna för att studera de märkliga inskrifterna och monumenten från glömda civilisationer."},{t="Runor och desperation",b="Livet i lägret är långt ifrån en stillsam utgrävning. Silithidhotet sprider sig från underjordiska bon över ödemarken, och farliga vidunder som den monstruösa skorpionen Deathclasp strövar omkring i närheten. Utposten balanserar därför noggrann forskning med ren överlevnad. Forskarna förlitar sig i hög grad på äventyrare som kommer dit för att hämta avtryck av svårtolkade runor, tyda urgamla insektspråk och leta efter försvunna följeslagare som vågat sig för djupt in i öknens galenskap."}},faq={{q="Var ligger Bronzebeard Encampment?",a="Lägret ligger i södra Silithus, öster om den väldiga The Scarab Wall och norr om den södra bergsryggen.",al={"var ligger bronzebeard encampment","bronzebeard encampment plats","hitta bronzebeard encampment"}},{q="Vilka sköter Bronzebeard Encampment?",a="Lägret bemannas av medlemmar och allierade till dvärgarnas Explorer's League, däribland runforskaren Rutgar Glyphshaper, Frankal Stonebridge och deras följeslagare Glibb.",al={"vilka finns vid bronzebeard encampment","rollpersoner vid bronzebeard encampment","vem leder bronzebeard encampment"}},{q="Vad studerar dvärgarna här?",a="Forskarna ägnar sig åt att tyda urgamla stenrunor, förstå silithidernas kommunikationssystem och gräva fram de länge begravda hemligheterna i södra Kalimdor.",al={"varför är dvärgar i silithus","vad studerar rutgar","bronzebeard encampments syfte"}},{q="Vilka hot lurar nära lägret?",a="Aggressiva silithidinsekter och sandlevande skorpioner stryker omkring i öknen. Där finns också den ökända jätteskorpionen Deathclasp, Sandskräckens skräck, som har sitt bo strax åt sydöst.",al={"faror nära bronzebeard encampment","deathclaps plats","monster vid bronzebeard encampment"}}},fp="22,195,32.341.0,22.324.0,44.115.0,36.169.0,35.124.0,38.181.0"}
P.entries["subzone:browman-mill"] = {n="Browman Mill",s="Browman Mill är ett pestdrabbat sågverk strax norr om Light's Hope Chapel i Eastern Plaguelands. Det var en gång en blomstrande del av Lordaerons timmerhandel, men nu kryllar det av odöda tjänare under Scourges järngrepp. Dess tidigare ägare, Stephen Browman, är fortfarande fångad i döden i sin förstörda verkstad.",h="Browman Mill är ett pestdrabbat sågverk strax norr om Light's Hope Chapel i Eastern Plaguelands.",kw={"styggelser","banshees","browman mill","eastern plaguelands","light's hope chapel","sågverk","scourge","stephen browman"},ang={["class:Paladin"]="Sågverkets vanhelgade lämningar och de plågade andar som hemsöker området står för allt som de heliga ordnarna kämpar för att rena bort från Lordaeron.",["race:Undead"]="Stephen Browmans slaveri är en tydlig påminnelse om det öde som drabbade alla Lich Kings offer som förvägrades den fria vilja som Forsaken vann."},sec={{t="En ruinerad industri",b="Före det tredje kriget betjänade Browman Mill Lordaerons omgivande städer och gårdar och sågade timmer från Eastwealds rika skogar. När Scourges pest svepte över riket föll sågverket tillsammans med resten av provinsen. I dag står murkna timmerstockar och krossade hjul stilla medan styggelser, banshees och skelettkrigare patrullerar området. Närheten till Light's Hope Chapel gör platsen till en ständig och hotfull påminnelse om den odöda horden som tränger ända fram till Argent Dawns tröskel."},{t="Förmannens öde",b="Sågverkets ursprungliga ägare, Stephen Browman, mötte samma dystra öde som otaliga vanliga invånare i Lordaeron. Han mördades när Scourge intog egendomen och återuppväcktes som en glupsk ghoul. Berövad sin mänsklighet och förslavad under Lich Kings vilja dröjer Browman sig kvar i sitt före detta sågverks mörka vrår och vaktar ruinerna av sitt livsverk."}},faq={{q="Var ligger Browman Mill?",a="Browman Mill ligger i den allra östligaste delen av Eastern Plaguelands, precis norr om Light's Hope Chapel.",al={"browman mill plats","var ligger browman mill","hitta browman mill"}},{q="Vilka fiender finns i sågverket?",a="Området kryllar av Scourge-styrkor, däribland väldiga styggelser, jämrande banshees, skelettbestar och kringströvande ghouls.",al={"fiender i browman mill","vem finns vid browman mill","vad finns vid browman mill"}},{q="Vem var Stephen Browman?",a="Stephen Browman var sågverkets ursprungliga mänskliga ägare och föreståndare. Han slaktades under Lordaerons fall och återuppväcktes som en odöd ghoul, bunden att vakta sin förstörda byggnad.",al={"vem är stephen browman","stephen browmans historia","browman som ghoul"}},{q="Varför är Browman Mill farligt för resenärer?",a="Den stora mängden mäktiga odöda gör platsen till en dödlig fara, särskilt eftersom den ligger bara en kort ridtur norr om Argent Dawns fäste vid Light's Hope Chapel.",al={"varför är browman mill farligt","hotet från browman mill"}}},fp="12,174,17.410.0,19.231.0,30.111.0,38.82.0,24.157.0,43.157.0"}
P.entries["subzone:bulwark"] = {n="The Bulwark",s="The Bulwark är en befäst utpost som sträcker sig över gränsen mellan Tirisfal Glades och Western Plaguelands. Den underhålls gemensamt av Forsaken och det neutrala Argent Dawn och fungerar som Horde:s frontlinje mot Scourge och den främsta utgångspunkten för expeditioner in i det besmittade österlandet.",h="The Bulwark är en befäst utpost som sträcker sig över gränsen mellan Tirisfal Glades och Western Plaguelands.",kw={"argent dawn","bulwark","chillwind","forsaken","scourge","tirisfal","western plaguelands"},ang={["faction:Horde"]="The Bulwark är Hordes motsvarighet till Alliances Chillwind Camp och fungerar som huvudport och operationsbas för räder i Plaguelands.",["race:Undead"]="För Forsaken är The Bulwark den avgörande flaskhalsen som hindrar Lich Kings arméer från att marschera rakt mot Brill och Undercity."},sec={{t="En sköld mot Scourge",b="The Bulwark ligger precis vid Tirisfal Glades östra gräns och är den sista barriären som skyddar Forsakens kärnland från Western Plaguelands pestdrabbade fasor. I dag försvarar grova träpalissader och tungt beväpnade vakter passet mot kringströvande odöda. Platsen står för ett spänt men nödvändigt samarbete, där Forsakenstyrkor samordnar sig med Argent Dawn för att rekrytera härdade hjältar från Horde och driva tillbaka Lich Kings hantlangare innan de väller in i Tirisfal."}},faq={{q="Vad är syftet med The Bulwark?",a="The Bulwark fungerar som Hordes första försvarsgarnison och uppmarschområde mot Scourge. Den skyddar Tirisfal Glades och Undercity från angrepp som strömmar ut från Western Plaguelands, samtidigt som den hyser befälhavare från Argent Dawn och Forsaken som samordnar anfall in i det pestdrabbade området.",al={"varför finns bulwark här","syftet med bulwark","vad är det här för plats"}},{q="Kan Alliance-karaktärer besöka The Bulwark för att tala med Argent Dawn?",a="Nej. Även om Argent Dawns representanter där är neutrala, är lägret tungt bevakat av Forsaken-vakter. Alla från Alliance som går innanför palissaderna blir attackerade så fort de upptäcks.",al={"kan alliance använda bulwark","alliance vid bulwark","är bulwark bara för horde"}},{q="Är The Bulwark säkert för unga äventyrare som lämnar Tirisfal?",a="Nej. Även om porten gränsar direkt till Tirisfal Glades är Western Plaguelands bortom den fullt av dödliga odöda på hög nivå och pestkittlar. Nybörjarresenärer som går förbi palissaden möter en snabb död.",al={"kan låglevelkaraktärer gå förbi bulwark","ta sig in i plaguelands på låg nivå"}}},fx={["3800d924"]={q="Vad är Bulwark?",a="Bulwark är en befäst utpost vid gränsen mellan Tirisfal Glades och Western Plaguelands. Den utgör Forsakens östra försvarslinje och skyddar ingången till Tirisfal mot Scourges skoningslösa fasor. Här samarbetar Forsaken-vakter och sändebud från Argent Dawn för att samordna försvaret, hålla tillbaka odöda intrång och skicka kapabla förkämpar till de pesthärjade länderna bortom utposten.",al={"vad är bulwark","översikt över the bulwark","om the bulwark"}},["7098c368"]={q="Vilka håller till i Bulwark?",a="Utposten bemannas av Forsaken-soldater som svurit drottning Sylvanas trohet, tillsammans med medlemmar ur det neutrala Argent Dawn. Forsaken vaktar gränsen och säkrar sitt nordliga kungarike, medan Argent Dawn har en närvaro här för att rekrytera erfarna äventyrare från Horde. De ger dem uppdrag att slå till mot Lich Kings undersåtar i Plaguelands.",al={"vem styr bulwark","vilka finns i bulwark","invånare i bulwark"}},a92b042c={q="Varför kallas det Bulwark?",a="Befästningen har fått sitt namn av sin roll som en verklig sköldmur, byggd för att skydda Forsakens länder från invasion. Den står mitt vid gränsen där Tirisfal möter Plaguelands, och dess tunga barrikader bildar den sista försvarslinjen mot Scourges monstruösa härskaror.",al={"varför kallas det bulwark","betydelsen av bulwarks namn","varför namnet bulwark"}}},fp="7,192,28.348.0,35.254.0,72.168.0,59.173.0"}
P.entries["subzone:burning-blade-coven"] = {n="Burning Blade Coven",s="I de norra klipporna i Valley of Trials hotar Burning Blade Coven Hordens nyaste rekryter. Korrumperade kultister och åkallade demoner hemsöker de gamla gruvgrottorna och använder dem som bas för mörk magi vid Durotars tröskel.",h="I de norra klipporna i Valley of Trials hotar Burning Blade Coven Hordens nyaste rekryter.",kw={"burning blade coven","demon","durotar","smådemoner","thazz'ril","valley of trials","yarrog baneshadow"},ang={["class:Warlock"]="Som warlock får du här en tidig varnande glimt av demoniska imps och mörka ritualer, där felmagi brukas vårdslöst.",["race:Orc"]="Som orch kan du se Burning Blade-kultens närvaro nära Valley of Trials som en outhärdlig förolämpning mot Thralls nya Horde och en tydlig påminnelse om den demondyrkan som orcherna kämpade för att lämna bakom sig."},sec={{t="En skugga över prövningsplatsen",b="Mörka ritualer hemsöker nu grottorna längs Valley of Trials norra kant. Imps och mindre onda väsen strömmar ut ur grottöppningen, sprider kaos och hotar de unga orcher och Darkspear trolls som tränar här för att tjäna Horden. Burning Blade-kulten har befäst sig djupt inne, ledd av den skuggfulle trollkarlen Yarrog Baneshadow. Det som en gång var vildmark för prövningar är nu ett aktivt slagfält mot demonisk korrumpering."},{t="Korruption i klipporna",b="Innan demonerna slog rot i grottorna hoppades lokala uppsyningsmän kunna utvinna råmaterial där för bosättningen. Foreman Thazz'ril begav sig in på en mineralundersökning, men kultisterna drev hastigt ut honom, och han lämnade värdefull utrustning bakom sig. Att driva tillbaka Baneshadows coven är nu det ultimata prövningsprovet för blivande krigare, skurkar och magiker innan de anses redo att bege sig vidare ut i Durotar."}},faq={{q="Var ligger Burning Blade Coven?",a="Burning Blade Coven håller till i grottor bland de höga röda klippryggarna längs Valley of Trials norra kant i Durotar.",al={"covenens plats","var ligger burning blade coven","grottans plats i dalen"}},{q="Vem leder kultisterna här?",a="Trollkarlen Yarrog Baneshadow leder coven, styr dess ritualer och befaller dess åkallade demoner.",al={"covenens ledare","vem leder burning blade coven","yarrog"}},{q="Vilka slags fiender lurar där inne?",a="Grottorna rymmer rogue imps, mindre demoniska tjänare och dödliga akolyter som slutit sig till Burning Blade-kulten.",al={"vilka fiender finns i grottan","covenens monster","demoner i valley of trials"}},{q="Varför går nya rekryter in i grottan?",a="Nya äventyrare bland orcher och troll vågar sig ner i grottans djup, återfinner förlorade verktyg som Foreman Thazz'rils hacka och dräper Yarrog Baneshadow som sin sista invigningsrit innan de lämnar dalen.",al={"varför gå till coven","covenens syfte","covenens slutprov"}}},fx={["8ab36280"]={q="Vad är Burning Blade Coven?",a="Burning Blade Coven är en mörk grotta uthuggen i de norra röda bergen i Valley of Trials. Den undersöktes en gång för mineralfyndigheter, men övergavs och har nu tagits över av demoniska kultister som hotar Hordes egna prövningsmarker.",al={"vad är burning blade coven","burning blade covens historia","vad är det här för grotta"}},["7f26a7cc"]={q="Är Burning Blade Coven farligt?",a="Grottan utgör ett allvarligt hot mot Valley of Trials. Busiga imps och farliga demoner har börjat välla ut genom grottöppningen, och lömska medlemmar av Burning Blade lurar i djupet. Att ge sig in i grottan och möta farorna där är det sista provet för blivande orc- och trolläventyrare innan de får resa in i Durotar.",al={"är burning blade coven farligt","hur farligt är coven","är det tryggt här"}},["5cf26a24"]={q="Varför kallas det Burning Blade Coven?",a="Grottan har fått sitt namn av kulten Burning Blade, vars medlemmar i hemlighet har tagit över gångarna. De använder dess avskilda hålor som en samlingsplats för att umgås med demoniska väsen och smida planer mot det unga Horde, mitt framför näsan på dess mentorer.",al={"varför kallas det burning blade coven","burning blade covens namns ursprung","vem namngav burning blade coven"}}},fp="19,218,33.377.0,23.397.0,41.122.0,28.101.0,34.108.0,37.202.0"}
P.entries["subzone:caer-darrow"] = {n="Caer Darrow",s="Caer Darrow är en befäst ö i Darrowmere Lake i Western Plaguelands. Ön var tidigare säte för den aristokratiska adelsätten House Barov. Dess fäste såldes i hemlighet till Kel'Thuzad och förvandlades till den nekromantiska skolan Scholomance. Staden ovan jord lämnades åt kringströvande gastar.",h="Caer Darrow är en befäst ö i Darrowmere Lake i Western Plaguelands.",kw={"barov","caer darrow","the cult of the damned","darrowmere lake","gandling","runsten","sarkhoff","scholomance","spectral essence"},ang={["faction:Alliance"]="För Alliance står Caer Darrow för två djupa svek: överfallet från kapare i Alterac under andra kriget, som avslöjade kung Perenoldes förräderi, och House Barovs försäljning av sitt förfädershem till Kel'Thuzad.",["race:Human"]="Mänskliga resenärer känner igen ön som det tidigare sätet för House Barov, en gång en av Lordaerons rikaste adelsfamiljer, innan girigheten drev dem till pakter med The Cult of the Damned."},sec={{t="Ett arv av krig och svek",b="Långt före Scourge var Caer Darrow ett strategiskt fäste i Lordaeron, där en uråldrig alvisk runsten förvarades. Under andra kriget plundrade Horde fästningen och högg upp runstenen för att skapa Gul'dans Altar of Storms. När Lord Uther the Lightbringer seglade dit för att hjälpa de överlevande överfölls hans flotta av kapare från Alterac. Förräderiet avslöjade Alteracs svek mot Alliance."},{t="House Barovs fall",b="Efter andra kriget byggdes Caer Darrow upp igen och blev familjen Barovs praktfulla gods. De ägde omfattande jordegendomar runt Brill, Tarren Mill och Southshore. När åldern började ta ut sin rätt slöt Barovfamiljen ett avtal med Kel'Thuzad för att bevara sin rikedom och odödlighet. The Cult of the Damned slog rot under fästningen och grundade Scholomance. Innan tredje kriget ens svepte in över Lordaeron spreds en första pest bland öns tjänstefolk och stadsbor. Invånarna dog och förbannades till att hemsöka den förfallna borgen som dröjande ekon."}},faq={{q="Vad är Caer Darrow?",a="Caer Darrow är en fästningsö i Darrowmere Lake i Western Plaguelands. Det var en gång den stolta herrgården som tillhörde den rika familjen Barov. Nu är det en kuslig ruin vars katakomber rymmer den nekromantiska akademin Scholomance.",al={"översikt över caer darrow","vad är det här för plats","caer darrows historia"}},{q="Varför är staden övergiven och förstörd?",a="Familjen Barov slöt ett avtal med Kel'Thuzad och överlät sitt gods till The Cult of the Damned i utbyte mot odödlighet. Kulten använde tjänstefolket i fästningen till tidiga nekromantiska experiment och släppte till slut lös en dödlig pest över hela bosättningen innan den större invasionen av Lordaeron började.",al={"varför är caer darrow förstört","vad hände med caer darrow","caer darrows historia"}},{q="Varför kan jag inte se spökena i staden?",a="Caer Darrows mördade invånare dröjer kvar som rastlösa andar, fångade i sina sista ögonblick. Vanliga ögon kan inte se dem utan särskild magisk syn, till exempel med Spectral Essence som Eva och Lucien Sarkhoffs andar ger dig.",al={"var finns spökena","osynliga personer i caer darrow","hur man ser spöken"}},{q="Vad var runstenen som fanns här?",a="Under andra kriget förvarades en uråldrig högelvisk runsten i Caer Darrow. Horde plundrade ön och högg den heliga stenen i bitar. Gul'dan använde dem för att bygga Altar of Storms och leda magi till ogremager.",al={"runstenen i caer darrow","alvisk runsten","stenen från altar of storms"}},{q="Vad finns under fästningen?",a="Under borgen ligger Scholomance, The Cult of the Damneds högkvarter och utbildningsakademi. Nekromantiker och akolyter studerar svartkonster där under ledning av Darkmaster Gandling och utför experiment på de döda.",al={"vad finns under caer darrow","vad finns i källaren","grotta under caer darrow"}}},fp="11,164,28.361.0,23.497.1,20.216.0,37.243.0,39.240.1,44.226.0,32.202.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Calmbreeze Inn",s="Calmbreeze Inn är namnet på de viktigaste värdshusen på Zephras Isle, som finns i både Shen'dar Village och Valaanar. De erbjuder resenärer på ön välbehövliga viloplatser med lokala yrkesinstruktörer, värdshusvärdar och historiska föremål.",h="Calmbreeze Inn är namnet på de viktigaste värdshusen på Zephras Isle, som finns i både Shen'dar Village och...",kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar village","valaanar","zephras isle"},ang={["class:Rogue"]="Miriann Mistblade erbjuder skurk-instruktioner vid härden på Calmbreeze Inn i Shen'dar Village.",["profession:Herbalism"]="Örtkunniga som besöker Shen'dar Village kan söka upp Halassa Fernbreeze på Calmbreeze Inn för att finslipa sina insamlingskunskaper."},sec={{t="Vila på ön",b="Calmbreeze Inns erbjuder en fristad längs Zephras Isles slingrande stigar. I Shen'dar Village drivs värdshuset av Coriella Calmbreeze och fungerar också som en central mötesplats för öns hantverkare, däribland instruktörer i örtväsen, flåning och förtrollning. På andra sidan vägen i Valaanar finns ännu ett Calmbreeze Inn för lokala resenärer, med sällsynta kuriositeter, däribland en ljudkristall som berättar om det forntida upproret i Eldre'Thalas."}},faq={{q="Var ligger Calmbreeze Inns?",a="Calmbreeze Inn finns både i Shen'dar Village och Valaanar på Zephras Isle.",al={"calmbreeze inn plats","var ligger calmbreeze inn","calmbreeze inn karta"}},{q="Vem driver värdshuset i Shen'dar Village?",a="Värdshuset i Shen'dar Village sköts av värdshusvärden Coriella Calmbreeze, som välkomnar både öns invånare och resenärer.",al={"värdshusvärd calmbreeze inn","vem driver calmbreeze inn"}},{q="Vilka instruktörer finns på värdshuset?",a="I Shen'dar Village finns Halassa Fernbreeze för örtväsen, Mendalass Tattermend för flåning, Nasalanna Windsinger för förtrollning och Miriann Mistblade för skurk-träning på värdshuset.",al={"calmbreeze inn instruktörer","instruktörer på värdshuset i shen'dar"}},{q="Vad är ljudkristallen på övervåningen i Valaanar?",a="På övervåningen i värdshuset i Valaanar finns en ljudkristall med del tre av ”The Rebellion In Eldre'Thalas”, som skildrar historiska händelser från den forntida högborne-staden.",al={"ljudkristall i valaanar","kristall med the rebellion in eldre'thalas"}}},fx={["043ce63b"]={q="Vad är Calmbreeze Inn?",a="Calmbreeze Inn syftar på ett nätverk av värdshus för resande runt Zephras Isle, med värdshus i både Valaanar och Shen'dar Village. De fungerar som viktiga samlingsplatser för lokalsamhället, där trötta resande kan vila, träffa lokala hantverkare och tränare samt få nyheter från ön.",al={"vad är calmbreeze inn","calmbreeze inns historia","om calmbreeze inn"}},c8344be2={q="Är Calmbreeze Inn farligt?",a="Nej. Värdshusen Calmbreeze Inn är fridfulla tillflyktsorter i Shen'dar Village och Valaanar. Där finns vänliga invånare, värdshusvärdar och hantverkstränare, inte fientliga hot.",al={"är calmbreeze inn tryggt","faror vid calmbreeze inn","fara vid calmbreeze inn"}}},fp="14,128,16.384.0,38.75.0,37.104.0,38.192.0,53.146.0"}
P.entries["subzone:camp-aparaje"] = {n="Camp Aparaje",s="Camp Aparaje var en gång en fridfull taurenby, belägen bland de östra höjderna i Stonetalon Mountains. I dag är den översvämmad och ockuperad av den fientliga Grimtotem-stammen, som massakrerade de ursprungliga nybyggarna och tog utposten för egen del.",h="Camp Aparaje var en gång en fridfull taurenby, belägen bland de östra höjderna i Stonetalon Mountains.",kw={"camp aparaje","grimtotem","grimtotem post","grundig darkcloud","kaya flathoof","makaba flathoof","stonetalon"},ang={["faction:Horde"]="Att driva bort Grimtotem från Camp Aparaje handlar om hämnd och försvar, och om att se till att den förrädiska stammen straffas för att ha slaktat oskyldiga undersåtar i Horde i Stonetalon.",["race:Tauren"]="Ruinerna av Camp Aparaje påminner bittert om grymheten hos Magathas Grimtotem-stam och visar att inte alla Moder Jordens barn delar Cairne Bloodhoofs vision om ära och fred."},sec={{t="Ett tragiskt fall",b="Camp Aparaje låg högt bland klipporna i Stonetalon Mountains och grundades av fridfulla tauren som ville leva stillsamt i höglandet. Friden krossades när rövare från det närbelägna Grimtotem Post, ledda av Grundig Darkcloud, inledde ett brutalt och oprovocerat anfall. Byborna slaktades eller drevs bort, och överlevande som Makaba Flathoof sörjde sitt förstörda hem och fruktade för sina tillfångatagna släktingars öde."},{t="Under Grimtotems herravälde",b="Camp Aparaje är nu helt ockuperat av Grimtotem-krigare och fungerar som en framskjuten operationsbas för den aggressiva stammen i regionen. Till skillnad från vanliga Grimtotem-bosättningar, som pryds av blå markeringar, är den stora totempålen i Aparaje målad i djupt karmosinrött."}},faq={{q="Vilka bodde tidigare i Camp Aparaje?",a="Camp Aparaje beboddes av fridfulla tauren med band till Horde och Bloodhoof-stammen, däribland Makaba Flathoof och hans dotter Kaya, innan bosättningen invaderades.",al={"vilka bodde här","camp aparajes ursprungliga bybor","makaba flathoofs by"}},{q="Varför är lägret fientligt mot spelare i Horde?",a="Byn intogs med våld av Grimtotem-stammen, en främlingsfientlig och förrädisk taurenklan som vägrar svära trohet till Cairne Bloodhoof och aktivt angriper främlingar, även medlemmar av Horde.",al={"varför attackerar tauren mig","vem kontrollerar camp aparaje","varför är camp aparaje rött"}},{q="Vem ledde anfallet mot Camp Aparaje?",a="Anfallet leddes av Grundig Darkcloud, en brutal Grimtotem-hövding som verkar från Grimtotem Post och vill utöka sin stams våldsamma grepp om Stonetalon.",al={"vem attackerade aparaje","grundig darkcloud","vem är ledaren här"}},{q="Vad hände med byborna som överlevde?",a="De flesta invånarna dödades under anfallet. Några lyckades fly, medan andra, som unga Kaya Flathoof, tillfångatogs av Grimtotem och hölls fångna vid det närbelägna Grimtotem Post.",al={"kaya flathoof","var finns de överlevande","finns det överlevande"}}},fx={fcad7814={q="Vad är Camp Aparaje?",a="Camp Aparaje var en gång en fridfull taurenbosättning i Stonetalon Mountains östra höjder. Den var hem åt stillsamma familjer som Makaba Flathoofs, men den tillvaron slogs i spillror när våldsamma Grimtotem-rövare kom stormande ned från sitt fäste och tog byn med våld.",al={"översikt över camp aparaje","vad är det här för läger","berätta om camp aparaje"}},["358940fc"]={q="Vad hände i Camp Aparaje?",a="Fientliga Grimtotem-krigare inledde ett plötsligt, brutalt angrepp mot byn från närbelägna Grimtotem Post. Under ledning av Grundig Darkcloud drev angriparna bort eller slaktade byns tauren, tillfångatog dem som inte hann fly och lade hela utposten under sin förrädiska stam.",al={"vad hände här","camp aparajes historia","hur förstördes camp aparaje"}},["8b937e47"]={q="Vem kontrollerar Camp Aparaje nu?",a="Lägret hålls för närvarande av ockuperande Grimtotem-rövare under Grundig Darkclouds befäl. Efter att ha fördrivit de ursprungliga invånarna använder dessa fientliga tauren nu byn som ett aktivt läger, med vaktposter och fångar under bevakning.",al={"vem bor i camp aparaje","vem håller camp aparaje","vilka finns i camp aparaje"}},["33da0239"]={q="Varför övergav Camp Aparajes ursprungliga folk platsen?",a="De fredliga byborna hade ingen chans mot Grimtotems överraskningsanfall. De som överlevde den första massakern, som Makaba Flathoof, tvingades fly för sina liv ut i vildmarken och lämna hem och ägodelar bakom sig för att plundras av erövrarna.",al={"varför ligger camp aparaje i ruiner","varför gick byn förlorad","varför lämnade byborna platsen"}},["46090024"]={q="Är Camp Aparaje farligt?",a="Ja. Boplatsen är hårt ockuperad av aggressiva Grimtotem-krigare som angriper alla som närmar sig lägret, oavsett din ställning hos resten av Horde. Om du tar dig in på dess område hamnar du genast i strid med Grundig Darkclouds hårdföra rövare.",al={"är camp aparaje tryggt","faran i camp aparaje","hot mot camp aparaje"}}},fp="12,172,17.332.0,20.199.0,33.171.0,41.162.0,36.143.0,41.140.0"}
P.entries["subzone:camp-e-thok"] = {n="Camp E'thok",s="Camp E'thok är en bosättning för Galak-centaurer i nordvästra Thousand Needles. Den aggressiva centaurstammen använder lägerplatsen i ravinen som bas för att överfalla karavaner som färdas genom flodbädden nedanför.",h="Camp E'thok är en bosättning för Galak-centaurer i nordvästra Thousand Needles.",kw={"camp e'thok","centaur","ethok","galak","thousand needles","wizlo bearingshiner"},ang={["race:Tauren"]="Galak-centaurernas obevekliga aggressivitet vid Camp E'thok påminner ständigt om uråldrigas krig mellan tauren och centaurerna i södra Kalimdor."},sec={{t="Ett Galak-fäste",b="Camp E'thok ligger undangömt bland de karga nordvästra delarna av Thousand Needles och är en viktig bosättning för de fientliga Galak-centaurerna. Liksom sina fränder runtom i Kalimdor är Galak-centaurerna obevekligt rovgiriga och ger sig på alla resenärer som vandrar in i ravinens skuggor. Lägrets ökända räder riktas mot handelskaravaner. En gång överföll de goblinen Wizlo Bearingshiner och lade beslag på hans varor, men hans dyrbara mojäng undkom dem tack vare hans vilda husdjurspanter."}},faq={{q="Vem bor i Camp E'thok?",a="Lägret bebos av centaurklanen Galak, en aggressiv stam som härskar över delar av nordvästra Thousand Needles.",al={"vem finns i camp ethok","invånare i camp ethok","vem kontrollerar camp ethok"}},{q="Vad hände med Wizlo Bearingshiner här?",a="En handelskaravan med goblinen Wizlo Bearingshiner överfölls av Galak-centaurerna från Camp E'thok. De plundrade karavanen men lyckades inte ta Wizlos dyrbara mojäng, eftersom den var fäst vid halsbandet på hans vilda husdjurspanter.",al={"wizlo bearingshiners räd","goblinkaravan överfallen","vad stal centaurerna från wizlo"}},{q="Var ligger Camp E'thok?",a="Camp E'thok ligger i nordvästra Thousand Needles, inbäddat längs ravinväggarnas fot.",al={"camp ethoks plats","var ligger camp ethok","camp ethok karta"}}},fx={["740a44e0"]={q="Vad är Camp E'thok?",a="Camp E'thok är ett aktivt läger för centaurstammen Galak, beläget i kanjonerna i nordvästra Thousand Needles. Centaurerna använder den befästa platsen som bas för våldsamma bakhåll och räder mot resenärer och handelskaravaner som passerar genom ravinerna nedanför.",al={"vad är camp ethok","camp ethoks historia","berätta om camp ethok"}},["7ec291b4"]={q="Är Camp E'thok farligt?",a="Camp E'thok är extremt farligt. Galak-centaurerna som bor här angriper främlingar vid synen av dem och jagar handelskaravaner som vågar ta sig genom kanjonen. Den som irrar in i lägret möter fientliga krigare, schamaner och allt byte de har rövat till sig med våld.",al={"är camp ethok fientligt","hur farligt är camp ethok","faran vid camp ethok"}}},fp="11,117,18.341.0,25.118.0,42.183.0,29.85.0"}
P.entries["subzone:camp-kosh"] = {n="Camp Kosh",s="Camp Kosh är ett ogreläger i norra Badlands, där de aggressiva Dustbelcher-ogrerna bor. Lägrets bestar håller till nära viktiga färdvägar och ger sig på karavaner som passerar samt samlar på sig utrustning som resenärer lämnar efter sig i den ogästvänliga öknen.",h="Camp Kosh är ett ogreläger i norra Badlands, där de aggressiva Dustbelcher-ogrerna bor.",kw={"badlands","camp kosh","dustbelcher","ogrer","sigrun ironhew","uldaman"},ang={["faction:Alliance"]="Alliansens spejare som färdas genom det nordliga passet mot Searing Gorge måste vara på sin vakt nära Camp Kosh, eftersom bestarna gärna överfaller karavaner som passerar.",["race:Dwarf"]="De asätande ogrerna i Camp Kosh plundrade de viktiga matransonerna och vapengömmorna som lämnats kvar av Sigrun Ironhews hårt ansatta expedition till Uldaman."},sec={{t="Ett näste för asätare",b="Camp Kosh ligger i Badlands nordliga ödemarker och är Dustbelcher-ogres nordligaste bosättning. De bor också i närliggande läger som Boff, Cagg och Wurg. Ogrerna här utnyttjar närheten till vägarna och plundrar utsatta försörjningsleder på väg mot Kargath eller västerut in i Searing Gorge. När dvärgprospektörer under Sigrun Ironhews ledning tvingades fly från utgrävningen vid Uldaman, plundrade bestarna i Camp Kosh snabbt deras övergivna vagnar och släpade dyrbara matransoner och vapen till det dammiga lägret."}},faq={{q="Vilka bor i Camp Kosh?",a="I Camp Kosh bor Dustbelcher-ogrerna, en brutal ogrestam som kontrollerar flera små läger i det torra Badlands.",al={"fiender i camp kosh","vem finns i camp kosh","ogrer i camp kosh"}},{q="Varför ligger Camp Kosh här?",a="Dess nordliga läge gör att Dustbelcher-ogrerna kan överfalla försörjningskaravaner och oförsiktiga resenärer som färdas mellan Searing Gorge, Uldaman och Hordens utpost Kargath.",al={"varför camp kosh","camp kosh plats"}},{q="Vad stal ogrerna från dvärgarna?",a="När Sigrun Ironhews dvärgexpedition drog sig tillbaka från farorna inne i Uldaman lämnade de försörjningsvagnar i öknen. Ogrerna i Camp Kosh tog vara på vraket och for iväg med lådor fulla av mat och vapenleveranser.",al={"dvärgarnas förråd camp kosh","sigrun ironhews förråd","uldamanvagnar"}}},fp="9,166,19.444.0,23.102.0,30.151.0,42.166.0"}
P.entries["subzone:camp-mojache"] = {n="Camp Mojache",s="Camp Mojache är Hordens främsta utpost i Feralas, grundad som en befäst taurenboplats vid vattendragen som mynnar ut i Wildwind Lake. Den erbjuder skydd, förnödenheter och flygförbindelser åt resenärer som trotsar den otämjda vildmarken, aggressiva djurlivet och den djupa skogens forntida ruiner.",h="Camp Mojache är Hordens främsta utpost i Feralas, grundad som en befäst taurenboplats vid vattendragen som...",kw={"krigare","camp mojache","feralas","flygmästare","gordunni","tauren","wildwind lake","woodpaw"},ang={["faction:Horde"]="Som Hordens enda befästa knutpunkt i Feralas är Mojache din enda tillflykt för att vila, fylla på förråden och snabbt ta dig genom den djupa skogen.",["race:Tauren"]="Camp Mojache markerar den sydligaste utposten för ditt folks traditionella hantverk och bosättningar i Kalimdor, där tauren skapar harmoni mitt i den djupa regnskogen."},sec={{t="En taurenbastion i regnskogen",b="Camp Mojache ligger i östra Feralas, vid en strid bäck som rinner ut i Wildwind Lake. Det är en taurenboplats byggd för att säkra ett fotfäste i den vilda sydliga skogen. Den täta djungeln rymmer faror, från vildsinta djur till Gordunni-ogrer och aggressiva Woodpaw-gnoller, men lägret är en trygg ö. Med inkvartering, handelsmästare och en vindryttarklyka fungerar det som en livsviktig logistisk knutpunkt för Hordens hjältar i området."},{t="Utpost i gränslandet",b="Lägrets jägare och krigare är kända för sitt mod och sin tjocka hud. De håller ständig vakt mot räder från vildmarken runt omkring. För Horden är det nödvändigt att hålla Mojache för att utöka sitt inflytande över Feralas och hålla både nattalverna från kusten och de mörka krafter som lurar i Dire Maul i schack."}},faq={{q="Vad är Camp Mojache?",a="Camp Mojache är Hordens främsta operationsbas i Feralas. Den har främst byggts och underhållits av tauren, ligger på båda sidor om en bäck som mynnar i Wildwind Lake och erbjuder vila, handelsvaror och flygtransport.",al={"camp mojaches syfte","vad är det här för läger","taurenstad i feralas"}},{q="Vem leder eller försvarar lägret?",a="Boplatsen skyddas av erfarna taurenkrigare, som försvarar den mot intrång från lokala rovdjursflockar, Gordunni-ogrer och aggressiva Woodpaw-gnoller som stryker omkring i kullarna strax söderut.",al={"camp mojaches vakter","vem försvarar mojache","vem styr camp mojache"}},{q="Vart flyger den lokala flygmästaren?",a="Från lägrets vindryttarplats kan resenärer flyga till centrala knutpunkter som Thunder Bluff, The Crossroads i The Barrens, Shadowprey Village i Desolace och närliggande utposter som Gadgetzan i Tanaris.",al={"flygrutter från camp mojache","vart kan jag flyga från camp mojache"}},{q="Vilka stora hot omger Camp Mojache?",a="I skogarna runt omkring finns Woodpaw-gnollklanen i söder, revirhävdande Gordunni-ogrer i norr och söder samt Alliansens styrkor vid den avlägsna västkusten, i Feathermoon Stronghold.",al={"faror i feralas nära camp mojache","hot nära camp mojache","fiender nära mojache"}}},fp="12,209,34.290.0,16.194.0,21.194.0,30.136.0,42.163.0,41.179.0"}
P.entries["subzone:camp-narache"] = {n="Camp Narache",s="Camp Narache är en avskild by på Red Cloud Mesa i södra Mulgore. Den är Hawkwind-stammens uråldriga hem och en plats där unga tauren inleder sin träning. Högt ovanför slätterna bevarar lägret gamla traditioner och håller samtidigt stånd mot de framryckande quilboarerna och de kvarvarande centaurhoten.",h="Camp Narache är en avskild by på Red Cloud Mesa i södra Mulgore.",kw={"bristleback","greatmother hawkwind","hawkwind","mulgore","narache","red cloud mesa","andesal","tauren"},ang={["class:Shaman"]="Unga schamaner tar sina allra första steg på den andliga vägen här. De genomgår prövningar för att förtjäna sin Earth Totem och tala direkt med mesans elementandar.",["race:Tauren"]="För tauren markerar Camp Narache slutet på barndomen. Här, på helig jord, tar du dina första jaktriter och stämmer dig med förfädernas andar under Hawkwind-äldstes vaksamma blick."},sec={{t="Hawkwind-stammens hjärta",b="Camp Narache ligger vid den norra kanten av Red Cloud Mesas höjdplatå och är Hawkwind-stammens främsta bosättning. Byn består av flera stora hudarbetade hyddor och paviljonger, däribland ett gemensamt tält för sårade krigare, en vapenkammare, ett bageritält och en andesal för meditation och kontakt med förfäderna. Mitt i lägret står stamäldste och vägvisare i en ring. Där ger den vördnadsvärda Greatmother Hawkwind fortfarande råd och vägleder de nyinvigda ungdomarna när de tar sig an sina roller som Jordmoderns försvarare."},{t="En prövningsplats under hot",b="Trots att mesans branta, lodräta klippor ger ett naturligt skydd råder ständig oro i Camp Narache. Bristleback-quilboarer från Brambleblade Ravine tränger oupphörligt in på Hawkwind-stammens marker, medan centaurspanare håller sig på avstånd. Unga jägare, schamaner, druider och krigare visar sitt mod här genom att gallra bland det aggressiva djurlivet, skydda byns vattenkälla och slå tillbaka quilboarernas plundrare innan de går nedför den stora stigen mot Mulgore bredare dalar."}},faq={{q="Vad är Camp Narache?",a="Camp Narache är startbyn för unga tauren och ligger på Red Cloud Mesa i södra Mulgore. Det är Hawkwind-stammens centrala läger, en fristad där unga jägare, krigare, druider och schamaner lär sig sina färdigheter innan de reser vidare till Bloodhoof Village och Thunder Bluff.",al={"vad är camp narache","naraches historia","taurenernas startby"}},{q="Vem leder byn?",a="Chief Hawkwind vägleder stammens krigare och samordnar försvaret av mesan tillsammans med stammens vördnadsvärda äldste, Greatmother Hawkwind. Stammens tränare och äldste samlas mitt i lägret för att undervisa unga äventyrare.",al={"vem leder camp narache","hövding i camp narache","hawkwind-ledare"}},{q="Vilka hot möter lägret?",a="Lägret utsätts ständigt för angrepp från Bristleback-quilboarer som har sin bas i Brambleblade Ravine österut. Förutom vildsinta stridsvildsvin och striders som strövar omkring på de omgivande klipporna håller även hotet från rovgiriga centaurband Hawkwind-krigarna ständigt på sin vakt.",al={"camp naraches fiender","vem anfaller camp narache","hot mot mesan"}},{q="Kan resande enkelt lämna mesan?",a="Red Cloud Mesa omges naturligt av lodräta klippor. Den enda vägen ned till Mulgore vidsträckta slätter går längs en bevakad bergsstig norrut. Hawkwind-krigare håller uppsikt där för att hindra fientliga bestar och quilboarer från att överfalla resande.",al={"lämna red cloud mesa","utgång från camp narache","stigen ner från mesan"}}},fx={["8b10e970"]={q="Vad är Red Cloud Mesa?",a="Red Cloud Mesa är en hög, skyddad platå ovanför södra Mulgore. Branta klippor håller de flesta rovdjur och inkräktare från låglandet borta. Här ligger Camp Narache, en avskild plats där unga tauren får visa vad de går för.",al={"red cloud mesa","vad är den här platån","om red cloud mesa"}},dff4694b={q="Vad är Thunder Bluff?",a="Thunder Bluff är taurenfolkets storslagna huvudstad, högt belägen på flera vindskulpterade platåer i norra Mulgore. Den är sammanlänkad av hängande repbroar och nås via väldiga trähissar. Den grundades av Cairne Bloodhoof som en fristad för alla taurenstammar.",al={"vad är thunder bluff","om thunder bluff","taurenfolkets huvudstad"}},["51c45aa6"]={q="När anslöt sig tauren till Horden?",a="Tauren slöt förbund med Horden under det tredje kriget, kort efter att Thrall och hans orcher landstigit på Kalimdor. Thrall såg deras gemensamma andliga hederskänsla och släktskap. Han hjälpte Cairne Bloodhoof att försvara sin karavan mot centaurernas räder, och vänskapen som följde förde tauren in i den nya Horden.",al={"tauren går med i horden","hur gick tauren med i horden","när träffade tauren thrall"}},["6d7e8195"]={q="Hur hamnade jag i Camp Narache?",a="Du kom till Camp Narache, på Red Cloud Mesas avskilda höjder, för att träna och visa vad du går för bland Hawkwind-stammen. Mulgories låglänta slätter nås bara genom ett befäst pass. Här samlas unga tauren i en skyddad tillflykt för att finslipa sina färdigheter under stamäldsternas och klassinstruktörernas vakande ögon, innan de ger sig ut i den större världen.",al={"hur kom jag hit","hur hamnade jag här","varför är jag i camp narache"}},ccbc2a7d={q="Vad förväntas jag göra i Camp Narache?",a="Din uppgift är att hjälpa Chief Hawkwind och lägrets äldste medan du lär dig din vägs riter. Red Cloud Mesa utsätts ständigt för angrepp från aggressiva Bristleback quilboars i Brambleblade Ravine och bergspumor som stryker omkring på platån. Försvara bosättningen, hjälp skadade krigare och utför heliga ritualer för Jordmodern. Då förtjänar du rätten att bege dig ner till Bloodhoof Village och tjäna Horden.",al={"vad ska jag göra här","vad är mitt syfte här","varför är jag här"}},["74e7cbb8"]={q="Varför börjar en ny tauren här, i Camp Narache?",a="Camp Narache är taurenfolkets urgamla plats där unga tauren tar sina första steg mot vuxenlivet. Lägrets höga läge på Red Cloud Mesa skyddar det från kringströvande centaurer och andra hot i centrala Kalimdor. Här vägleder Hawkwind-stammens äldste och instruktörer nya krigare i jakt, andevördnad och försvar av det nya hemland som Cairne Bloodhoof säkrade åt ditt folk.",al={"varför börjar tauren här","varför börja i camp narache","varför är detta taurenfolkets startområde"}},["017769ab"]={q="Vad hände i Camp Narache?",a="Camp Narache grundades som ett skyddat hem för Hawkwind-stammen på Red Cloud Mesas höga höjder. Under generationer utvecklades det från en enkel samlingsplats för stammen till den främsta prövningsplatsen för unga tauren i hela Mulgore. Branta klippor och naturliga vallar skyddade lägret, där unga jägare, schamaner och krigare kunde genomgå sina traditionella riter på avstånd från de våldsamma centaurräderna som plågade de öppna slätterna nedanför.",al={"camp naraches historia","vad hände här"}},de5ddd4a={q="Vilka bor i Camp Narache?",a="Camp Narache är Hawkwind-stammens främsta by, som leds av Chief Hawkwind och hans äldre mor, Greatmother Hawkwind. Här samlas stammens modiga krigare, handelsmän och hantverkare tillsammans med lärare från taurenfolkets olika traditioner. Schamaner, druider, krigare och jägare bor i lägrets hyddor av hudar och tränar unga tauren som kommit hit för att genomgå sina vuxenritualer.",al={"vem bor i camp narache","invånarna i camp narache","vem bor här"}},["452dc8d4"]={q="Är Camp Narache farligt?",a="Själva boplatsen är fredlig och väl bevakad av Hawkwind-stammens krigare, men den omgivande mesan blir allt farligare. Aggressiva bergspumor och revirhävdande stridsvildsvin stryker längs gränserna, medan allt fler Bristleback quilboar har trängt in i ravinen i närheten. Det är tryggt innanför hyddornas område, men oerfarna ungdomar utsätter sig genast för fara om de vandrar långt från lägrets eldar.",al={"är camp narache tryggt","hur farligt är camp narache","faran i camp narache"}},["602085f2"]={q="Är det här alla tauren börjar?",a="Ja. Camp Narache ligger högt uppe på Red Cloud Mesas skyddade klippor och fungerar som det främsta träningslägret för alla unga tauren. Innan du får ge dig ut i Mulgore bredare dalar eller tjäna hövdingen i Thunder Bluff måste du först bevisa din styrka, visdom och respekt för naturen under de äldstes vakande ögon här.",al={"börjar alla tauren här","taurens startområde","varför börjar tauren här"}},e8115520={q="Vem byggde Camp Narache?",a="Lägret grundades av Hawkwind-stammen som deras förfädersby på Red Cloud Mesa. Det byggdes främst av stadiga lädertält, snidade totem och naturligt timmer, enligt traditionella nomadiska metoder. Det har blivit en bestående samlingsplats för stammen och en plats där taurenungdomar får lära sig.",al={"vem skapade camp narache","camp naraches ursprung","vem grundade camp narache"}},["9d2ccac7"]={q="Är Chief Hawkwind viktig för tauren?",a="Chief Hawkwind leder Hawkwind-stammen och vakar över Red Cloud Mesa. Han styr lägret och leder försvaret mot Bristlebacks, men hans viktiga kulturella roll är att vägleda nyväckta krigare genom deras första prövningar innan de går i de förenade stammarnas tjänst.",al={"chief hawkwinds roll","vem är chief hawkwind","chief hawkwinds betydelse"}},["5c34accd"]={q="Lyder Chief Hawkwind under någon annan?",a="Ja. Liksom alla stamhövdingar i Mulgore erkänner Chief Hawkwind Cairne Bloodhoof som de förenade taurenstammarnas högste hövding. Utöver Cairne har tauren svurit trohet till Warchief Thrall och den större Horde, även om den dagliga styrningen av lägret ligger i Hawkwinds händer.",al={"vem lyder chief hawkwind under","chief hawkwinds överordnade","vem styr över hawkwind"}},["4397ed07"]={q="Vilka är Bristlebacks och varför angriper de oss?",a="Bristlebacks är en vild quilboarstam som lever bland mesans klippor och taggiga snår. De är starkt revirhävdande och desperata efter resurser, och ser taurenbosättningarna som ett intrång på deras betesmarker. Uppmuntrade av sina hövdingar har de börjat plundra taurenfolkets försörjningsleder och hota Camp Narache direkt.",al={"varför angriper bristlebacks","bristleback quilboar","vilka är bristlebacks"}},["35bda353"]={q="Vad är Brambleblade Ravine?",a="Brambleblade Ravine är en taggig kanjon täckt av björnbärssnår, på den nordöstra kanten av Red Cloud Mesa. Den är det främsta boet och fästet för regionens Bristleback quilboar och här finns deras stridsvildsvin och deras hövding, Sharptusk Thornmantle.",al={"brambleblade ravine","var ligger brambleblade ravine","om brambleblade ravine"}},["7ff27be4"]={q="Vem är Earthmother?",a="Earthmother är den välvilliga skapargudom som tauren vördar över allt annat. Enligt taurenfolkets traditioner födde hon världen, blåste liv i landet och skapade deras folk för att leva i harmoni med vildmarken. Hennes vilja vägleder deras andliga seder, schamanistiska ritualer och vördnad för naturen.",al={"vem är earth mother","earthmothers historia","tauren och earthmother"}},d26e5d41={q="Vad är Mulgore?",a="Mulgore är taurenfolkets förfädersland, en vidsträckt, grönskande trakt med vindpinade grässlätter, böljande kullar och höga platåer. Ogenomträngliga bergsväggar omger landet på alla sidor. I de bördiga dalarna lever vandrande kodo, vargar och taurenfolkets permanenta huvudstad Thunder Bluff.",al={"vad är mulgores land","om mulgore","mulgores historia"}},["2ba66ce3"]={q="Varför bosatte sig tauren i Mulgore?",a="I generationer tvingade brutala centaurmarodörer taurenfolket att leva ett kringvandrande nomadliv över The Barrens. Efter att ha slutit sig samman med Warchief Thrall och New Horde för att driva bort centaurerna från regionen ledde High Chieftain Cairne Bloodhoof sitt folk till en permanent bosättning i deras förfäders bördiga och försvarbara dalar.",al={"varför bor tauren i mulgore","varför kom tauren till mulgore","bosättningen i mulgore"}},b543a978={q="Är Mulgore tryggt?",a="Mulgore är naturligt befäst och fredligt jämfört med The Barrens, men faror saknas inte. Fientliga Palemane-gnoller, Windfury-harpior, aggressiva quilboar och opportunistiska goblingruvarbetare från Venture Company stör ständigt friden och tvingar tauren att vara vaksamma.",al={"är mulgore farligt","hur tryggt är mulgore","hot i mulgore"}},["2e7cb737"]={q="Vad är Bloodhoof Village?",a="Bloodhoof Village är en central taurenbosättning vid Stonebull Lakes stränder, mitt i Mulgore. Den är ett viktigt handels- och kulturcentrum mellan prövningsplatserna på Red Cloud Mesa och Thunder Bluffs svindlande höjder.",al={"om bloodhoof village","var ligger bloodhoof village","vad är bloodhoof"}}},fp="12,280,27.381.0,29.413.0,21.305.0,22.200.0,32.163.0,36.191.0"}
P.entries["subzone:camp-taurajo"] = {n="Camp Taurajo",s="Camp Taurajo håller passets östra mynning in mot Mulgore. Taurenlägret erbjuder resenärer ett värdshus, förnödenheter, tränare och vindryttarrutter över slätterna och centrala Kalimdor.",h="Camp Taurajo håller passets östra mynning in mot Mulgore.",kw={"the barrens","bloodhoof village","camp taurajo","passet till mulgore","southern barrens","taurajo","taurenutpost"},ang={["faction:Horde"]="Som medlem av Horde kan du använda Camp Taurajos vägkorsning och flygrutt för att förbinda Mulgore med resten av Horde-kontrollerade centrala Kalimdor.",["race:Tauren"]="Som tauren som lämnar Mulgore för första gången finner du Camp Taurajo som det första vänliga skyddet på The Barrens hårda slätter."},sec={{t="Utpost vid Red Rocks",b="Vid Camp Taurajo når du passets östra mynning in mot Mulgore. För unga tauren som lämnar Bloodhoof Village är lägret ofta deras första glimt av det vidsträckta The Barrens. Torr buskmark och karga platåberg omger denna utpost och handelsplats. Jägare, läderarbetare och fältörterforskare finner skydd här, medan vindryttare förbinder lägret med Thunder Bluff, The Crossroads och Freewind Post längre söderut."}},faq={{q="Vad är Camp Taurajo?",a="Camp Taurajo är en taurenbosättning och utpost i södra The Barrens, mellan Mulgore och The Barrens torra buskmarker.",al={"översikt över camp taurajo","vad är taurajo","taurajos historia"}},{q="Vart leder vägen västerut?",a="Den jordiga stigen västerut från Camp Taurajo går genom bergspasset in i Mulgore, mot Bloodhoof Village och Thunder Bluff.",al={"taurajos västra pass","vägen väster om camp taurajo","vägen till mulgore"}},{q="Vart flyger vindryttarna från Camp Taurajo?",a="Vindryttare från Camp Taurajo färdas till The Crossroads i norr, Thunder Bluff i väster och Freewind Post i Thousand Needles i söder.",al={"taurajos flygmästare","taurajos flygrutter","flygförbindelser från taurajo"}}},fx={["9a32993c"]={q="Är Camp Taurajo farligt?",a="Själva lägret är en trygg bosättning som skyddas av taurenkrigare, men vildmarken i södra Barrens är förrädisk. Aggressiva quilboarstammar kämpar om de närliggande buskmarkerna, och kringströvande rovdjur gör det farligt att vika av långt från vägen.",al={"är camp taurajo tryggt","faror nära camp taurajo","hoten runt taurajo"}}},fp="12,173,25.394.0,21.113.0,30.121.0,47.132.0"}
P.entries["subzone:camp-wurg"] = {n="Camp Wurg",s="Camp Wurg är ett ogreläger i Badlands torra vidder. Det är en av flera utposter som tillhör de territoriella Dustbelcher-ogrerna, som dominerar stora delar av Badlands.",h="Camp Wurg är ett ogreläger i Badlands torra vidder.",kw={"badlands","boss tho'grun","camp boff","camp cagg","camp kosh","camp wurg","dustbelcher","ogre","wurg"},sec={{t="Ett Dustbelcher-fäste",b="Camp Wurg ligger undangömt bland Badlands klippor och är ett av de fyra främsta lägren som Dustbelcher-ogrerna har slagit sig ned i, tillsammans med Camp Cagg, Camp Boff och Camp Kosh. Ogrerna som är stationerade här försvarar sitt karga territorium med våldsamhet och samlar vad de kan från den ogästvänliga ödemarken. Vanliga råskinn och väktare håller till kring Wurgs enkla eldar och grova hudar, men deras hövding Boss Tho'grun har ingen fast plats här. I stället strövar han längs Badlands stigar för att hålla uppsikt över alla sina läger."}},faq={{q="Vilka bor i Camp Wurg?",a="Camp Wurg bebos av Dustbelcher-ogrerna, en våldsam och territoriell stam som har grundat bosättningar över hela Badlands.",al={"varelser i camp wurg","vem finns i camp wurg","vilka bor här"}},{q="Var finns lägrets ledare?",a="Dustbelcher-ogrerna leds av Boss Tho'grun, som inte håller sig till Camp Wurg. I stället patrullerar han Badlands öppna stigar mellan Wurg, Cagg, Boff och Kosh.",al={"camp wurgs ledare","var finns boss tho'grun","vem leder camp wurg"}},{q="Vilka andra läger tillhör stammen?",a="Dustbelchers kontrollerar fyra huvudfästen i Badlands: Camp Wurg, Camp Cagg, Camp Boff och Camp Kosh.",al={"dustbelcher-läger","andra ogreläger i badlands","ogrebosättningar i badlands"}}},fp="9,109,24.414.0,23.82.0,32.132.0,38.107.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Canals (Stormwind City)",s="Stormwinds kanaler slingrar sig mellan stadens stadsdelar, där flanörer och fiskare delar stigarna längs vattnet.",h="Stormwinds kanaler slingrar sig mellan stadens stadsdelar, där flanörer och fiskare delar stigarna längs...",kw={"kanalstadsdel","kanaler","krokolis","gallina","avlopp","stockade","stormwind","vattenvägar"},ang={["faction:Alliance"]="Som medlem av alliansen kan du se hur kanalerna återställdes efter förstörelsen under det första kriget, medan Stormwind blev en livlig och pittoresk stad.",["profession:Cooking"]="Som blivande kock kan du fiska längs kanalernas stillsamma stränder utan att lämna huvudstadens trygga murar."},sec={{t="Huvudstadens pulsådror",b="Du kan följa kanalerna mellan Stormwinds stadsdelar, från Trade Districts marknader till Old Towns åldrade gränder, katedralens trädgårdar och Dwarven District. Stenbroar, valv och promenadstråk längs vattnet passerar Gallina Winery, skräddarbutiker och stillsamma hem. Köpmän och fiskare använder vattenvägarna, medan den befästa ingången till The Stockade ligger under gatorna och håller Stormwinds farligaste brottslingar och rebeller inspärrade."},{t="En fasansfull historia och hotande skuggor",b="Stormwinds kanaler låg i ruiner efter att horden plundrat staden under det första kriget. Vattenvägarna återställdes när huvudstaden reste sig på nytt efter det andra kriget. De är rena och reparerade nu, men rykten talar om en enorm albino-krokolis under bryggorna."}},faq={{q="Vad hände med kanalerna under det första kriget?",a="Horden plundrade Stormwind under det första kriget och lämnade staden och dess vattenvägar i ruiner. Kanalerna återställdes när huvudstaden byggdes upp igen efter det andra kriget.",al={"kanalernas historia","kanalerna första kriget","stormwind plundring kanaler"}},{q="Finns det verkligen ett monster i Stormwinds kanaler?",a="Ingen kan säga säkert. Rykten talar om en enorm vit krokolis som lurar i vattenvägarna, även om vakter och invånare ofta avfärdar berättelserna som krogskvaller. Rapporterna fortsätter, och äventyrare varnas för att inte falla i.",al={"stormwind krokodil","kanalalligator","avloppsmonster","vit krokolis"}},{q="Var ligger ingången till The Stockade?",a="Ingången till The Stockade ligger längs den nordligaste delen av kanalen runt Mage Quarter, bevakad av Stormwind City Guard.",al={"var ligger stockade","ingång till stockade","hur tar man sig till stockade"}},{q="Kan spelare simma genom kanalerna för att ta sig runt i Stormwind?",a="Du kan simma genom kanalerna och sedan leta efter stentrappor eller bryggor längs stigarna vid vattnet för att ta dig upp till gatan igen.",al={"simma i kanaler","resa via vatten stormwind","vattenväg stormwind"}}},fx={["8ec6c1e0"]={q="Vad är kanalerna?",a="Kanalerna är ett vidsträckt nätverk av vattenvägar och stenlagda kajer som löper genom hela Stormwind City och delar upp stadens större distrikt. De används främst som vattenvägar och genomfartsleder, men gångstråken och kajerna kantas av små butiker, skrädderier och fiskeplatser. Kanalerna ger också tillgång till den säkra ingången till Stormwind Stockade.",al={"vad är kanalerna","stormwinds kanaler i historien","kanaldistriktet"}},["74e84108"]={q="Är kanalerna farliga?",a="För det mesta är kanalerna trygga och vältrafikerade av stadens invånare, butiksägare och lokala sportfiskare. Men se ändå upp nära vattnet. Bland lokalbefolkningen går rykten om en monstruös albino-krokolisk som lurar under ytan och utgör ett verkligt hot mot den som är oförsiktig nog att falla i.",al={"är det tryggt i kanalerna","fara i kanalerna","är kanalerna farliga"}}},fp="23,100,23.400.0,38.255.0,49.169.0,50.225.0,46.127.0,63.114.0"}
P.entries["subzone:canals-undercity"] = {n="Canals (Undercity)",s="Kanalerna bildar en grumlig, cirkelformad vallgrav som slingrar sig mellan Undercitys tydligt åtskilda kvarter. De är fyllda med ett onaturligt, giftigt grönt slem i stället för färskvatten och fungerar både som avloppssystem och som en dyster symbol för Forsakens underjordiska fäste.",h="Kanalerna bildar en grumlig, cirkelformad vallgrav som slingrar sig mellan Undercitys tydligt åtskilda...",kw={"kanaler","fiske","forsaken","grönt slem","lordaeron","slam","giftigt","undercity"},ang={["class:Shaman"]="Elementen har föga makt över det förorenade slammet i Undercitys vattenleder. Därför misslyckas vanliga besvärjelser som Water Walking helt.",["race:Undead"]="För Forsaken är de stinkande kanalerna helt ofarliga för deras odöda kroppar. De fungerar som en vallgrav och en kanal för kemiska utsläpp, väl lämpade för deras underjordiska rike."},sec={{t="En giftig vallgrav",b="Kanalerna är uthuggna i djupet under Ruins of Lordaeron och omringar Undercitys hjärta. Breda kanaler med trögflytande grönt slam skiljer kvarteren åt. Dödliga städer leder rinnande flodvatten genom gatorna för att hålla dem rena, men Forsaken har fyllt dessa stenkulvertar med industriavfall, kemiska utsläpp och alkemiskt avfall. Vätskan avger ett svagt, sjukligt sken och illaluktande ångor. Därför går det inte att ta sig över den med vanliga magiska metoder som Water Walking. Trots slammets dödlighet lyckas desperata fiskare ibland dra upp märkliga, förorenade kuriositeter ur smutsen."}},faq={{q="Vad är den gröna vätskan i kanalerna?",a="Det är ett alkemiskt slam av giftiga utsläpp, pestbiprodukter och industriavfall som samlas i Undercitys avloppssystem. Till skillnad från rent vatten är det tydligt förorenat och giftigt.",al={"grönt vatten i undercity","vad är slemmet i undercity","grön slemflod"}},{q="Kan man fiska i Undercitys kanaler?",a="Ja, tålmodiga fiskare kan kasta ut ett metspö i slammet. Förutom sjukliga, förorenade fiskar drar folk ibland upp bortkastat skräp, däribland gamla människoskallar från Lordaerons fallna förflutna.",al={"fiske i undercity","kan man fiska här","fiske i grönt slem"}},{q="Varför fungerar inte Water Walking i kanalerna?",a="Det tjocka, kemiska slammet beter sig inte som naturligt vatten. Dess illaluktande trögflytenhet och onaturliga sammansättning hindrar shamaner och andra besvärjare från att skapa ytspänning med vanlig vattenvandringsmagi.",al={"water walking i undercity","shaman water walking bugg","varför kan jag inte gå på vattnet i undercity"}}},fx={dc46e6d3={q="Vad är kanalerna i Undercity?",a="Kanalerna är nedsänkta vattenvägar som slingrar sig mellan Undercitys olika kvarter. De löper i en vid cirkel genom den underjordiska staden. De djupa stentrågen bär en trög flod av stinkande grönt slam som delar upp distrikten och samtidigt binder samman den väldiga staden under jord.",al={"undercitys kanaler","vad är kanalerna","undercitys kanalsystem"}},c0800d9e={q="Är kanalerna farliga?",a="Kanalerna utgör inget omedelbart fysiskt hot från rovdjur som lurar där, men det grumliga gröna vattnet är långt ifrån rent. Det trögflytande slammet är tillräckligt vidrigt för att rymma bortkastade ben, människoskallar och sjuka, muterade vattenvarelser. Ett ofrivilligt dopp blir därför en högst obehaglig upplevelse.",al={"fara i kanalerna","är det tryggt att simma i undercitys kanaler","är undercitys kanaler trygga"}}},fp="18,147,12.411.0,39.184.0,37.172.0,45.170.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="The Cape of Stranglethorn",s="The Cape of Stranglethorn utgör den solstekta sydspetsen av Stranglethorn Vale och sträcker sig söderut från Gurubashi Arena till havsklipporna. Regionen kretsar kring pirathamnen Booty Bay och är en stridszon där gastar, Bloodsail Buccaneers, uråldriga djungeltroll och framryckande vilddjur kämpar om makten.",h="The Cape of Stranglethorn utgör den solstekta sydspetsen av Stranglethorn Vale och sträcker sig söderut från...",kw={"baron revilgaz","blackwater raiders","bloodsail buccaneers","booty bay","the cape of stranglethorn","gurubashi arena","south seas","stranglethorn vale"},ang={["class:Rogue"]="Kusten är en fristad för kapare, skurkar och stråtrövare. Här finns oändliga möjligheter att länsa fickor, smuggla längs kusten eller spela ut Blackwater Raiders mot Bloodsail Buccaneers.",["profession:Cooking"]="South Seas och kustvattnen runt omkring erbjuder värdefulla fiskevatten och sällsynta recept som bara fiskhandlarna och hamnkockarna i Booty Bay säljer."},sec={{t="Kontinentens utkant",b="Söder om det uråldriga amfiteatern Gurubashi Arena övergår den täta djungeln i kusten som kallas The Cape of Stranglethorn. Här finns förfallna trollbosättningar som Ruins of Jubuwal och Ruins of Aboraz. Området har sedan länge undgått Gurubashis kejserliga kontroll. I dag präglas stränderna, vikarna och djungelgläntorna av farliga rovdjur, murlocläger och rivaliserande piratbesättningar som strider om handelsleder och nedgrävda skatter."},{t="Booty Bay och piratkriget",b="Den dominerande makten längs kusten är Blackwater Raiders, ledda av Baron Revilgaz och Fleet Master Seahorn från piratstaden Booty Bay. Den neutrala hamnen är uthuggen direkt i klipporna vid den södra viken och förbinder Eastern Kingdoms med Kalimdor genom ångbåtar till Ratchet. Goblinernas kontroll är dock osäker. Bloodsail Buccaneers härjar längs de södra grundbankarna och de yttre öarna, angriper försörjningsleder och smider öppet planer på att störta Booty Bay och ta full kontroll över South Seas."}},faq={{q="Vad är skillnaden mellan Stranglethorn Vale och The Cape of Stranglethorn?",a="The Cape of Stranglethorn syftar specifikt på den södra delen av det större Stranglethorn Vale, med landområdena och kusterna söder om Gurubashi Arena ner till Booty Bay.",al={"kusten eller dalen","stranglethorns geografi","var ligger kusten"}},{q="Vem styr The Cape of Stranglethorn?",a="Ingen enskild makt kontrollerar hela kusten. Booty Bay och vattnen omkring staden styrs av Baron Revilgaz och de goblinstödda Blackwater Raiders, medan Bloodsail Buccaneers, nagor och kvarlevor av trollfolket kontrollerar olika stränder och ruiner inåt land.",al={"vem leder booty bay","kustens härskare","vem kontrollerar kusten"}},{q="Kan både Horde och Alliance använda Booty Bay?",a="Ja. Booty Bay är en öppen, neutral hamn som sköts av Steamwheedle Cartel. Så länge resenärer håller vapnen i slidan och bevarar freden inom stadens gränser får äventyrare från både Alliance och Horde använda hamnen, handlarna, flygmästaren och auktionshuset.",al={"är booty bay neutral","alliance och horde i booty bay","kan horde gå in i booty bay"}},{q="Vad är Gurubashi Arena?",a="Gurubashi Arena är en uråldrig trollarena nära kustens norra gräns, där kombattanter samlas för att pröva sin styrka.",al={"gurubashi-kistan","arenaregler","pvp-arena i stranglethorn"}},{q="Hur tar sig resenärer mellan The Cape och Kalimdor?",a="En goblinstyrd ångbåt går regelbundet mellan Booty Bays kajer och hamnstaden Ratchet i The Barrens. Den erbjuder en av få passagerarförbindelser över South Seas.",al={"båt till ratchet","transport till kalimdor","båten från booty bay"}}},fp="21,201,21.299.0,31.432.0,80.146.0,36.213.0,42.239.0,28.129.0,51.160.0"}
P.entries["subzone:capital-gardens"] = {n="Capital Gardens",s="Capital Gardens utgör den västra flygeln av de forntida alvruinerna i Dire Maul i Feralas. Parken var en gång en fridfull, välskött trädgård för kaldoreiernas adel, men har vissnat till en fördärvad skog där förvridna uråldringar, spöken och rester av Shen'dralar stryker omkring.",h="Capital Gardens utgör den västra flygeln av de forntida alvruinerna i Dire Maul i Feralas.",kw={"athenaeum","capital gardens","västra dire maul","eldre'thalas","feralas","immol'thar","shen'dralar"},ang={["class:Mage"]="Trots förfallet rymmer trädgårdarna stigar mot Athenaeum, ett av de största arkiven med magisk teori från tiden före klyvningen som fortfarande finns kvar i Kalimdor.",["race:NightElf"]="För nattalverna är det en plågsam påminnelse om högbornas övermod och de katastrofala följderna av ett beroende av magi att vandra på den fördärvade stenläggningen i Capital Gardens."},sec={{t="En förfallen fristad",b="För tiotusen år sedan var Eldre'Thalas en av kaldoreiernas glänsande kronjuveler. Capital Gardens var dess utomhusdistrikt, frodigt av förtrollad växtlighet och storslagna marmorterrasser där högborne trollkarlar debatterade och kopplade av. Efter den stora klyvningen drabbades enklaven av svåra tider. Utan Evighetens brunn tog Shen'dralar som bodde där till mörk magi för att bevara sin odödlighet och lät trädgårdarna förfalla. I dag fyller grå, förvridna grenar och fördärvade trädandar de sönderfallna gårdarna, medan kvarvarande magisk korruption hindrar skogen från att någonsin läka helt."},{t="Athenaeum och fängelset",b="Bortom de igenvuxna gränderna och fientliga uråldringarna leder Capital Gardens djupare in i Shen'dralars befästa tillflykt. Stigarna går direkt till högbornas hov och Athenaeum, det bevarade biblioteket med århundraden av magisk kunskap och bortglömda avhandlingar. Ännu längre in ligger Immol'thars fängelse, där de överlevande alverna band en demon för att suga åt sig dess kraft. Denna desperata handling förvandlade de omgivande trädgårdarna till den mardröm de är i dag."}},faq={{q="Vad är Capital Gardens?",a="Capital Gardens är den västra flygeln av Dire Maul, belägen bland ruinerna av Eldre'Thalas i centrala Feralas. Det var en gång en välskött offentlig park och bostad för stadens högborne elit.",al={"vad är capital gardens","västra trädgårdarna i dire maul","parken i eldre'thalas"}},{q="Varför är träden och uråldringarna fördärvade här?",a="Efter att Evighetens brunn förstördes höll sig de överlevande Shen'dralar vid liv genom att suga åt sig mörk felenergi från en tillkallad demon, Immol'thar. Det läckande, instabila magiska energiflödet förvred långsamt växtligheten i området och drev de uråldringar som bodde där till våldsamt vansinne.",al={"varför är uråldringarna onda här","vad hände med träden","varför är området fördärvat"}},{q="Vart leder området?",a="Trädgårdarna leder djupare in i den västra delen av Dire Maul och öppnar sig mot högbornas hov, det lärda Athenaeum och den innersta fristaden där demonen Immol'thar hålls fången.",al={"vad ansluter till capital gardens","vart leder det"}},{q="Finns det några vänligt sinnade alver kvar i trädgårdarna?",a="De flesta högborne som strövar längs stigarna är fientliga andar eller vansinniga försvarare. Men i det närliggande Athenaeum finns några Shen'dralar-lärda kvar, villiga att byta till sig uråldrig kunskap eller handla med förlorade alviska libramer.",al={"finns det några allierade där inne","vem bor i capital gardens"}}},fp="15,195,19.544.0,28.332.1,28.179.0,46.235.0,26.163.0,49.203.0"}
P.entries["subzone:cathedral-of-light"] = {n="Cathedral of Light",s="Cathedral of Light reser sig över Cathedral Square som Stormwinds främsta helgedom för Church of the Holy Light. Den är stadens andliga hjärta och centrum för människornas prästerskap och Knights of the Silver Hand.",h="Cathedral of Light reser sig över Cathedral Square som Stormwinds främsta helgedom för Church of the Holy...",kw={"benedictus","cathedral of light","cathedral square","duthorian rall","det heliga ljuset","laurena","shadowbreaker","silverhanden","stormwind"},ang={["class:Paladin"]="Som paladin hittar du din ordens främsta samlingssal i Stormwinds Cathedral of Light, där Duthorian Rall och Lord Grayson Shadowbreaker leder dig genom de heliga prövningarna i Tome of Valor och Tome of Divinity.",["class:Priest"]="Som präst hittar du Church of the Holy Lights främsta säte i de södra kungadömena, i Cathedral of Light, där High Priestess Laurena och Archbishop Benedictus vägleder din fromhet och heliga läkekonst."},sec={{t="De troendes helgedom",b="Archbishop Benedictus leder de troende från Cathedral of Light, som återuppbyggdes efter förödelsen under första kriget. Archbishop Alonsus Faol och Bishop Benedictus ledde återuppbyggnaden, och dess höga silhuett är fortfarande en symbol för motståndskraft. Efter att Scourge intog Lordaeron under tredje kriget flyttade kyrkan sitt säte söderut till Stormwind. Från denna stora sal ger Benedictus andlig vägledning åt alliansen."},{t="Hallar för andakt och vapenövning",b="Cathedral of Light är både en plats för bön och läkedom och Knights of the Silver Hands främsta högkvarter i de södra kungadömena. Lord Grayson Shadowbreaker och Duthorian Rall tränar lovande väpnare genom de heliga prövningarna i Tome of Valor och Tome of Divinity. High Priestess Laurena vägleder fromma akolyter i Ljusets djupaste lärosatser och förbereder heliga förkämpar på att försvara riket mot de växande hoten från Defias Brotherhood och Scourge."}},faq={{q="Vem leder kyrkan i katedralen?",a="Archbishop Benedictus leder Church of the Holy Light från Stormwind. Efter att Lordaeron föll och Archbishop Alonsus Faol dog tog Benedictus andligt ledarskap över den ombildade kyrkan.",al={"katedralens ledare","vem är ärkebiskopen","vem leder kyrkan"}},{q="Hur är katedralen knuten till paladinerna?",a="Cathedral of Light är Knights of the Silver Hands högkvarter i Stormwind. Lord Grayson Shadowbreaker och Duthorian Rall undervisar nya väpnare, ger dem heliga skrifter och leder korsfarare mot rikets fiender.",al={"silverhanden stormwind","paladinorden stormwind","varför är paladiner här"}},{q="Vad finns under katedralens golv?",a="Katedralens katakomber ligger under den främsta helgedomen. Där vilar kvarlevorna efter ärade hjältar, präster och paladiner.",al={"katedralens källare","katedralens katakomber","vad finns under katedralen"}}},fx={["2c1d9b08"]={q="Vad är Cathedral of Light?",a="Cathedral of Light är det andliga hjärtat i Church of the Holy Light och Alliansen. Den ligger i Stormwinds Cathedral Square och är en helig plats för bön, meditation och läkande. Lovande präster och paladiner från Knights of the Silver Hand reser från hela riket för att studera under dess välvda tak. Under de koboltinlagda stengolven vilar de ärade döda.",al={"vad är cathedral of light","cathedral of lights syfte","stormwinds katedral"}},e612604f={q="Vad hände med Cathedral of Light förr i tiden?",a="Under det första kriget skadades den ursprungliga katedralen svårt av den gamla Horden. Efter det andra kriget ledde ärkebiskop Alonsus Faol och hans dåvarande lärling Benedictus återuppbyggnaden. När Lordaeron föll under det tredje kriget blev katedralen trons främsta säte.",al={"cathedral of lights historia","stormwinds katedrals historia","vad hände vid cathedral of light"}},b98edca3={q="Är Cathedral of Light farlig?",a="Nej. Cathedral of Light är en fridfull helgedom i Stormwind Citys välbevakade hjärta. Den är tillägnad eftertanke, gudsdyrkan och läkekonsten. Om du inte är en fiende till Alliansen eller en inkräktare på flykt från stadsvakten, finner du bara trygghet, mentorer och andra som utövar Ljusets konst i dess salar.",al={"är cathedral of light farlig","är stormwinds katedral trygg","fara vid cathedral of light"}}},fp="18,203,25.417.0,26.474.0,42.188.0,51.228.0,38.123.0"}
P.entries["subzone:cathedral-square"] = {n="Cathedral Square",s="I Cathedral Square möts tro och stadsliv under Cathedral of Light. Här ligger stadshuset, barnhemmet och Argent Dawns högkvarter i Stormwind.",h="I Cathedral Square möts tro och stadsliv under Cathedral of Light.",kw={"argent dawn","cathedral of light","cathedral square","stadshus","heliga distriktet","barnhem","paladin","präst","stormwind"},ang={["class:Paladin"]="Som paladin hittar du mentorer, heliga löften och rustningsmakare för heliga krigare i Cathedral Square.",["class:Priest"]="Som präst kan du studera det Heliga Ljuset, be och tjäna Stormwinds invånare i torgets salar och spiror."},sec={{t="Det heliga distriktet",b="Cathedral Square ligger nordväst om Trade District och sydöst om Dwarven District och lockar troende från hela kungariket Stormwind. Cathedral of Light reser sig över torget och är Azeroths främsta helgedom för det Heliga Ljuset. Präster, paladiner och helare kommer hit för att studera, be och träna. Invånare och pilgrimer blandas med lokala skolbarn på torget, under ledning av School Mistress Danna."},{t="Stadens hjärta och helig orden",b="Bönen samsas i distriktet med arbetet för kungariket. Stadshuset och Stormwind Orphanage utgör kärnan i stadslivet. Längs avenyerna betjänar rustningsmakare och vapensmeder heliga korsfarare med bland annat Righteous Plates och Just Maces. Argent Dawn har sin bas i Stormwind här, där rekryterare och representanter samordnar hjälpinsatser och samlar hjältar mot Scourge i de norra kungarikena."}},faq={{q="Vad är Cathedral Square?",a="Cathedral Square samlar gudstjänst och stadsliv kring Cathedral of Light i Stormwind City. Stadshuset, det lokala barnhemmet och butiker fyller också distriktet.",al={"katedraldistrikt","heliga distriktet","vad är det här för plats"}},{q="Vilka tränar i Cathedral Square?",a="Präster, paladiner och helare studerar och tränar i Cathedral Square och Cathedral of Light. Sjukvårdare och vårdgivare studerar här med First Aid-tränare.",al={"klasslärare här","vem tränar här","paladin- och prästlärare"}},{q="Varför finns Argent Dawn här?",a="Argent Dawn har en bas i Cathedral Square för att rekrytera hjältar och samordna stöd från Stormwind i kampen mot Scourge i Plaguelands.",al={"argent dawn stormwind","argent dawns närvaro"}},{q="Vart leder Cathedral Square?",a="Broar och kanalvägar förbinder Cathedral Square med Trade District i sydöst, Dwarven District i nordväst och Park i sydväst.",al={"anslutna distrikt","vart leder det här"}}},fx={["2ce95091"]={q="Varför heter det Cathedral Square?",a="Distriktet har fått sitt namn från den storslagna Cathedral of Light som reser sig över det. Den magnifika byggnaden dominerar Stormwinds silhuett och är Azeroths främsta monument över det Heliga Ljuset. Därför har den också gett de omgivande gatorna och torgen sitt namn och heliga syfte.",al={"betydelsen av namnet cathedral square","varför cathedral square","hur fick cathedral square sitt namn"}},aa9b3d24={q="Vilka bor i eller styr Cathedral Square?",a="Cathedral Square är Stormwinds andliga och medborgerliga centrum. Katedralens prästerskap och paladiner vägleder områdets religiösa liv, medan stadens ledare sköter sina angelägenheter från stadshuset. Här finns också stadens barnhem, specialiserade vapen- och rustningshandlare samt framstående organisationer som Argent Dawn, som har en aktiv närvaro här.",al={"vem styr cathedral square","vem bor i cathedral square","invånarna i cathedral square"}},e4d635a7={q="Är Cathedral Square farligt?",a="Nej, Cathedral Square är en av rikets tryggaste och bäst skyddade platser. Torget ligger innanför Stormwinds murar och patrulleras av stadsvakter. Ståndaktiga paladiner och heliga präster vakar över det dag och natt för att bevara freden.",al={"är cathedral square tryggt","fara i cathedral square","hot i cathedral square"}}},fp="16,161,17.386.0,26.392.0,25.157.0,31.152.0,36.147.0,33.158.0"}
P.entries["subzone:cauldron"] = {n="The Cauldron",s="The Cauldron är en enorm dagbrottsgruva som dominerar mitten av Searing Gorge. Dark Iron-klanen driver platsen, där utmattade slavar arbetar dag och natt under grymma förmäns och kringströvande elementalers uppsikt.",h="The Cauldron är en enorm dagbrottsgruva som dominerar mitten av Searing Gorge.",kw={"the cauldron","dark iron","utgrävning","magmaelementaler","stenbrott","searing gorge","slavarbetare","slavar"},ang={["profession:Mining"]="The Cauldrons enorma mekaniska grävmaskiner och terrasserade dagbrott visar omfattningen av Dark Irons industriella gruvdrift, uthuggen direkt i den instabila vulkaniska jordskorpan.",["race:Dwarf"]="När dvärgar från Ironforge själva ser Dark Irons förfall, där kännande fångar används som förbrukningsbara, kuvade arbetare bland eldelementaler, väcks en djup avsky."},sec={{t="Det brinnande stenbrottet",b="Djupt in i Searing Gorges förbrända mark höggs The Cauldron ut och befästes efter att kejsar Thaurissan kallat fram Ragnaros i en katastrofal ritual. Massiva Dark Iron-maskiner som spyr rök kantar ravinens väggar och skrapar loss sten och malm från den glödande berggrunden. I de brinnande sprickorna strövar levande eld och magmaelementaler tillsammans med Dark Iron-förmän, medan underjordisk hetta ständigt stiger från bergets djup."},{t="Den kuvade arbetsstyrkan",b="Långt nere i gruvan uthärdar tillfångatagna slavar brutala, ändlösa arbetspass under Dark Iron-förmännens piska. Det hårda arbetet, den kvävande hettan och plågan har drivit många av arbetarna till fullständig galenskap. De känner inte längre skillnad på vän och fiende och går våldsamt till angrepp mot alla främlingar som stör deras slit, även dem som annars kunde erbjuda dem en chans till frihet."}},faq={{q="Vad är The Cauldron?",a="The Cauldron är en enorm dagbrottsgruva mitt i Searing Gorge. Dark Iron-klanen byggde och befäste den som ett industriellt centrum för utvinning av sten och malm under extremt instabila vulkaniska förhållanden.",al={"historien om the cauldron","vad är the cauldron","stenbrottet i searing gorge"}},{q="Vem styr gruvan?",a="Dark Iron-klanen kontrollerar hela området. De leder arbetet med tunga grävmaskiner och beväpnade förmän och håller gruvan och dess arbetare i ett brutalt grepp.",al={"vem driver the cauldron","förmän i the cauldron"}},{q="Varför anfaller slavarna äventyrare som försöker hjälpa dem?",a="Slavarna har kuvats av grym plåga, bländande hetta och obeveklig utmattning. Deras herrar och det plågsamma livet har drivit dem till vansinne. Deras splittrade sinnen ser varje avbrott i arbetet som ett hot, och därför anfaller de alla i närheten.",al={"varför är slavarna fientliga","slavar som anfaller arbetare","kan man befria slavarna"}},{q="Vilka varelser lever i gruvan?",a="Förutom Dark Iron-förmännen och deras förslavade arbetsstyrka kryllar The Cauldrons brinnande sprickor av oberäkneliga eld- och magmaelementaler, frammanade av ravinens vulkaniska natur.",al={"fiender i the cauldron","vad finns i the cauldron","monster i the cauldron"}}},fp="8,199,17.382.0,20.277.0,21.153.0,28.120.0,53.157.0,44.108.0"}
P.entries["subzone:cavern-of-mists"] = {n="Cavern of Mists",s="Cavern of Mists är den vidsträckta yttre förhallen som leder ner i Wailing Caverns djup. Underjordiska gejsrar bryter fram genom berget och förser dess centrala damm med vatten, medan hängande dimma döljer märkliga, muterade djur som strövar strax utanför portalens tröskel.",h="Cavern of Mists är den vidsträckta yttre förhallen som leder ner i Wailing Caverns djup.",kw={"the barrens","cavern of mists","gejsrar","träsktänder","trigore the lasher","wailing caverns"},ang={["class:Druid"]="Det förvridna djurliv som frodas i de tjocka ångorna ger Cenariondruiderna sin första varning om hur illa Naralexs förbindelse med Emerald Dream har gått snett.",["faction:Horde"]="Mitt i The Barrens är det avgörande att rensa bort rovdjuren som lurar i dimman för att säkra handelsvägarna och utposterna kring The Crossroads."},sec={{t="Mardrömmens tröskel",b="Innan de når Wailing Caverns verkliga hjärta måste resenärer ta sig genom Cavern of Mists. Tjock, varm ånga ligger ständigt i luften och kommer från naturliga gejsrar som bryter fram ur grottgolvet och fyller en djup damm i mitten. Grottan fungerar som en ingång, men är långt ifrån fridfull. Svärmar av rovfåglar, ormar, slem och halvvattenlevande träsktänder strövar längs avsatserna och i vattnet, liksom ökända bestar som hydran Trigore the Lasher. Här får äventyrare en olycksbådande försmak av den onaturliga tillväxt som frodas längre ner."}},faq={{q="Var ligger Cavern of Mists?",a="Cavern of Mists utgör det yttre grottsystemet i Wailing Caverns, sydväst om The Crossroads i The Barrens. Det är den instansfria kammare som spelare måste ta sig igenom för att nå själva instansportalen.",al={"cavern of mists plats","var ligger cavern of mists","wailing caverns ingångsgrotta"}},{q="Varför heter grottan Cavern of Mists?",a="Aktiva gejsrar bryter ständigt fram ur stengolvet, fyller dammen i mitten och mättar den underjordiska luften med tung, fuktig dimma.",al={"varför dimmigt","cavern of mists namnets ursprung"}},{q="Vilka varelser lever här?",a="I kammaren finns rovfåglar, slem, vindormar, ormar, paddor och träsktänder som lever i dammen. Den sällsynta hydran Trigore the Lasher kan också ibland skymtas.",al={"monster i cavern of mists","varelser i cavern of mists"}},{q="Vem är Trigore the Lasher?",a="Trigore the Lasher är en farlig, sällsynt hydra som ibland kan hittas simmande bland träsktänderna i kammarens centrala damm.",al={"trigore","sällsynt hydra wailing caverns"}}},fx={["923aae57"]={q="Vad är Cavern of Mists?",a="Cavern of Mists, även kallad Wailing Cavern, är den yttre underjordiska kammaren före de djupare delarna av Wailing Caverns. Aktiva gejsrar sprutar upp ur stengolvet. I grottans mitt finns en grönskande damm där varmt vatten och ånga blandas, så att den slutna underjordiska luften ständigt fylls av tät dimma.",al={"vad är cavern of mists","cavern of mists i historien","om cavern of mists"}},["8ec0c6f8"]={q="Är Cavern of Mists farlig?",a="Ja, kammaren är farlig för oförsiktiga resenärer. Vilda rovdjur stryker omkring längs de dimmiga stränderna och i de grumliga vattnen. Där finns aggressiva rovfåglar, slingrande slemvarelser, giftormar och huggande vindormar. I den djupa dammen lurar rovlystna threshadoner. Där finns också monster som den svårfångade hydran Trigore the Lasher.",al={"är cavern of mists farlig","faror i cavern of mists","hot i cavern of mists"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="Caverns of Time",s="Caverns of Time ligger inbäddade i Tanaris östra klippor och är Nozdormus och den bronsfärgade drakflyktens mystiska tillhåll. I dess vindlande djup vakar drakarna över Azeroths sköra tidsvägar och skyddar dem mot dödlig inblandning och manipulation av tiden.",h="Caverns of Time ligger inbäddade i Tanaris östra klippor och är Nozdormus och den bronsfärgade drakflyktens...",kw={"anachronos","bronsdrakflykten","caverns of time","nozdormu","tanaris","tidsmässig","tidsvägar"},ang={["class:Mage"]="Den tidsmagi som genomsyrar grottorna överträffar vida dödlig kronomanti och ger en ödmjukande glimt av krafter bortom arkan manipulation.",["race:NightElf"]="Kaldorei minns väl drakgestalternas uråldriga pakter och ser Nozdormus uppdrag som avgörande för att bevara världens överlevnad."},sec={{t="De vindlande tidsvägarna",b="Caverns of Time är uthuggna djupt under öknens klippor och utgör en knutpunkt där historiens strömmar möts. Titanerna gav Nozdormu, den tidlöse, och hans bronsfärgade drakflykt uppdraget vid världens gryning, och de vakar för evigt över dessa passager. Här beter sig tiden nyckfullt. Skymtar av det förflutna och framtiden sipprar genom dolda sprickor, och reliker från avlägsna tidsåldrar ligger utspridda i sanden. Den väldiga draken Anachronos håller vakt nära ingången, medan mindre bronsdrakar patrullerar den vindlande nedstigningen och försvarar den enda sanna tidslinjen med näbbar och klor."},{t="En skattkammare av tidsåldrar",b="Grottorna är mer än en förbindelse mellan dåtid och framtid. De fungerar också som ett egendomligt valv. Under årtusenden har bronsdrakarna samlat historiska fragment från Azeroths alla hörn: uråldriga dvärgbyggnader, ett vakttorn från Lordaeron, hövdingarnas bostäder från orc-klanerna och rustningar från Stromgardes första kungar. Enstaka resenärer vågar smita förbi väktarna för att få en glimt av dessa underverk, men de inre portarna förblir stängda i väntan på den dag då drakflykten anser att dödlig inblandning behövs."}},faq={{q="Kan jag gå in i Caverns of Time just nu?",a="Nej. Vägen in i grottorna är fortfarande förseglad, och bronsdrakflykten släpper inte in några dödliga. Var försiktig nära drakarna som patrullerar ingången. Den äldre bronsdraken Anachronos bryr sig inte om resenärer, men hans följeslagare attackerar alla dödliga som kommer för nära.",al={"kan jag gå in i caverns of time","hur går jag in i caverns of time","är caverns of time öppna"}},{q="Vem styr över Caverns of Time?",a="Grottorna tillhör Nozdormu den tidlöse, drakgestalten som titanerna gav makten att vaka över tiden. Den dagliga förvaltningen och bevakningen av ingången sköts ofta av hans främsta ättling, Anachronos, tillsammans med bronsdrakflyktens väktare.",al={"vem leder caverns of time","boss i caverns of time","vem bor i caverns of time"}},{q="Varför finns det slumpmässiga byggnader och artefakter där inne?",a="Nozdormu ägnade tidsåldrar åt att katalogisera och samla fysiska reliker från Azeroths historia. Utspridda i grottorna finns skatter som hamnat fel, däribland ett helt vakttorn från Lordaeron, dvärgarkitektur, orciska byggnader och vapen från sedan länge glömda dödliga kungadömen.",al={"varför finns det människotorn i caverns of time","artefakter i caverns of time"}},{q="Vad är bronsdrakflyktens uppgift här?",a="Deras heliga uppgift, given av titanerna, är att skydda tidens gång och bevara historiens integritet. De ser till att dödlig manipulation och yttre störningar inte får händelserna som formar världen att gå om intet.",al={"vad gör bronsdrakarna här","bronsdrakflyktens syfte"}}},fp="15,188,20.491.0,15.443.0,46.218.0,35.230.0,52.255.0,52.206.0"}
P.entries["subzone:cenarion-enclave"] = {n="Cenarion Enclave",s="Cenarion Enclave är Darnassus grönskande nordvästra distrikt och Cenarion Circles centrala samlingsplats och maktsäte i huvudstaden. Medan ärkedruiden Malfurion Stormrage slumrar i The Emerald Dream leder ärkedruiden Fandral Staghelm nattalvernas druider från lundens stora håligheter och levande grenar.",h="Cenarion Enclave är Darnassus grönskande nordvästra distrikt och Cenarion Circles centrala samlingsplats och...",kw={"cenarion circle","cenarion enclave","darnassus","druid","fandral staghelm","nattsabel","teldrassil"},ang={["class:Druid"]="För nattalvdruider är Cenarion Enclave din ordens administrativa centrum på Teldrassil, med träning och vägledning under ärkedruiden Fandral Staghelms stränga ledning.",["class:Hunter"]="Jägare samlas i enklavens östra grenar för att vässa sitt sikte och sin kunskap om vildmarken tillsammans med bestmästare som föder upp huvudstadens nattsablar."},sec={{t="Cirkelns hjärta",b="Cenarion Enclave ligger på en hög terrass ovanför The Temple Gardens och är formad av uråldriga ekar och askar med runmärkt bark. Cenarion Circles sammankomster äger rum i byggnader som formats direkt ur levande trä och sten. Eftersom Malfurion Stormrage är borta i The Emerald Dream sköter ärkedruiden Fandral Staghelm verksamheten här och driver sin ambitiösa vision för Teldrassil, trots kvarstående politiska motsättningar med översteprästinnan Tyrande Whisperwind. Förutom druiderna som mediterar vid bäckarna finns här också huvudstadens alviska jägare och stallen där skickliga ryttare lär sig tämja Darnassus nattsablar."},{t="Skuggor bland grenarna",b="Trots sitt rykte som en fridfull naturens fristad rymmer Cenarion Enclave även mer hemlig verksamhet. Under de urholkade rötterna i den västligaste grenen finns en underjordisk tillflyktsort för Darnassus hemliga skurkar, som sköter sina tysta affärer skyddade av lövverkets prassel ovanför."}},faq={{q="Vem leder Cenarion Enclave?",a="Ärkedruiden Fandral Staghelm leder för närvarande lunden och nattalvsdruiderna i Darnassus. Malfurion Stormrage, Cenarion Circles högste ledare, är fortfarande fångad i en djup och oförklarlig slummer i The Emerald Dream, vilket gör Staghelm till den faktiska auktoriteten.",al={"vem bestämmer här","ledare för cenarion enclave","fandral staghelm"}},{q="Vilka klasser tränar här?",a="Lunden är hem för huvudstadens druidtränare, som undervisar nybörjare bland de levande träden. I de östra grenarna finns stadens jägartränare, medan rotgångarna under den västra grenen rymmer en undangömd skurktränare.",al={"tränare i cenarion enclave","druidtränare darnassus","jägartränare darnassus"}},{q="Var kan jag köpa en nattsabel som riddjur?",a="Ridtränare och uppfödare som tar hand om Darnassus omhuldade sabelkatter finns vid foten av det östra trädet nära lundens ingång. De erbjuder både ridträning och nattsablar till berättigade resenärer i Alliansen.",al={"nattsabeltränare","nattalvernas riddjurstränare","ridtränare darnassus"}},{q="Vilken hållning har Cenarion Circle till Alliansen?",a="Distriktet ligger i en allianshuvudstad och leds av den starkt nationalistiske Fandral Staghelm, men Cenarion Circle som större organisation värnar den naturliga ordningen snarare än att utkämpa fraktionskrig. Staghelms närvaro gör dock just den här enklaven starkt knuten till nattalvernas regionala intressen.",al={"är cenarion circle med i alliansen","är bara alliansen druider"}}},fx={cda262fb={q="Vad är Cenarion Enclave?",a="Cenarion Enclave är en lummig lund och ett distrikt bland de nordvästra grenarna i Darnassus. Där finns urgamla ekar och askar med mystiska runor inristade i barken. Enklaven är stadens centrum för druidiskt liv och tänkande. Temple of the Moon vägleder prästerskapet, medan enklaven samlar naturens lärda, läkare och vårdare för att samtala, undervisa och fördjupa sina andliga färdigheter.",al={"cenarion enclave i darnassus","vad är cenarion enclave","om cenarion enclave"}},fed5260a={q="Vad hände vid Cenarion Enclave?",a="Enclave växte fram jämsides med Darnassus som samlingsplats för huvudstadens druider. Dess helgedomar förenar levande trä med huggen sten. Ärkedruiden Fandral Staghelm bor i den största av dessa byggnader och leder druiderna medan Malfurion Stormrage är borta i Emerald Dream.",al={"cenarion enclaves historia","vad hände här"}},["1a9fb52b"]={q="Är Cenarion Enclave farligt?",a="Nej. Enclave är ett av de lugnaste och mest välbevakade distrikten i Darnassus, fullt av erfarna druider, skickliga jägare och vaksamma treant-väktare. Om du inte hyser fientlighet mot nattalverna och Alliansen finner du en fridfull tillflyktsort för meditation och studier.",al={"är cenarion enclave tryggt","faran i cenarion enclave","cenarion enclave fientligt"}},["88e7d09b"]={q="Varför kallas det Cenarion Enclave?",a="Namnet kommer från Cenarion Circle, den druidska orden som har vigt sig åt att bevara naturen och hedra Cenarius, halvguden och alla druiders beskyddare. Som huvudsäte för Cirkelns utövare i nattalvernas huvudstad är det en enklav avskild särskilt för deras urgamla hantverk och samvaro med naturen.",al={"varför kallas det cenarion enclave","cenarion enclaves namnets ursprung","vem namngav cenarion enclave"}}},fp="16,226,19.563.0,21.219.0,31.278.0,24.235.0,35.197.0,57.262.0"}
P.entries["subzone:cenarion-hold"] = {n="Cenarion Hold",s="Cenarion Hold är Cenarion Circles befästa fäste i Silithus hårda öken. Det byggdes för att hålla uppsikt över urgamla faror begravda under sanden och är en av Kalimdors största druidbosättningar och en sällsynt trygg tillflykt i en ogästvänlig ödemark.",h="Cenarion Hold är Cenarion Circles befästa fäste i Silithus hårda öken.",kw={"cenarion circle","cenarion hold","druider","kalimdor","skiftande sanden","silithider","silithus"},ang={["class:Druid"]="Cenarion Hold är en av de största druidaenklaverna utanför Moonglade och förkroppsligar Circles löfte att bevara naturens balans mot kosmiska fasor.",["race:NightElf"]="För Night Elf hedrar denna fästning de urgamla uppoffringar som gjordes under det katastrofala War of the Shifting Sands för årtusenden sedan."},sec={{t="En bastion bland sanddynerna",b="Cenarion Hold ligger bland Silithus ödsliga sanddyner och fungerar som Cenarion Circles södra kommandocentral. Fästningen nås via en slingrande väg förbi Un'Goro Crater och byggdes för att hålla uppsikt över de vilande hot som förseglats under öknen efter det historiska War of the Shifting Sands. I ett ogästvänligt område fullt av insektslika silithider och torra stormar erbjuder fästet livsviktigt skydd, handel och logistiskt stöd åt både Night Elf- och taurendruider som vakar över det förflutnas inspärrade fasor."},{t="Neutral mark",b="Eftersom uppgiften att skydda världen mot uråldrig ondska står över dödligas konflikter råder strikt neutralitet under Cenarion Circle i Cenarion Hold. Resenärer från både Alliance och Horde släpps in genom murarna och välkomnas av lokala kvartermästare och väktare, vars försörjningslinjer är osäkra. Flygrutter förbinder fästet med utposter i Feralas, Tanaris och Un'Goro Crater. Därmed är det den enda samlingsplatsen för dödliga äventyrare som vågar undersöka den växande oron i öknen."}},faq={{q="Vem styr Cenarion Hold?",a="Fästet styrs och bemannas helt av Cenarion Circle, den druidaorden som grundades av Malfurion Stormrage. Orden är helt neutral och välkomnar medlemmar från både Alliance och Horde.",al={"vem styr cenarion hold","cenarion hold fraktion","är cenarion hold neutralt"}},{q="Varför byggdes fästningen här ute i öknen?",a="Den grundades efter War of the Shifting Sands för att hålla uppsikt över den uråldriga ondska som förseglats djupt under Silithus och hejda de insektslika silithiderna som åter svärmar över området.",al={"varför ligger cenarion hold i silithus","cenarion holds syfte","varför byggde druider här"}},{q="Hur tar du dig till Cenarion Hold?",a="Resenärer till fots brukar ta den branta bergsstigen som klättrar nordväst från Un'Goro Crater. Flygrutter förbinder också fästet med flygmästare i Gadgetzan, Un'Goro och Feralas.",al={"hur tar man sig till cenarion hold","stigen till cenarion hold","ta sig in i silithus"}},{q="Kan medlemmar från båda fraktionerna använda tjänsterna här?",a="Ja. Köpmännen och flyghanterarna i Cenarion Hold handlar fritt med alla äventyrare som vågar sig ut i öknen, oavsett politisk tillhörighet.",al={"är det säkert för horde","kan alliance vila här","försäljare i cenarion hold"}}},fp="13,171,22.407.0,14.392.0,27.183.0,50.170.0,35.133.0,47.128.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Chamber of Atonement",s="Chamber of Atonement är den dystra entréhallen till kyrkogårdsflygeln i Scarlet Monastery. Här, under stenvalv behängda med järnkedjor, utsätter Scarlet Crusade tillfångatagna odöda och andra som de betraktar som kättare för brutal förhör och tortyr innan de kastar kvarlevorna i klostergården bortom.",h="Chamber of Atonement är den dystra entréhallen till kyrkogårdsflygeln i Scarlet Monastery.",kw={"chamber of atonement","forlorn cloister","kyrkogård","interrogator vishas","scarlet monastery","tortyr","vorrel sengutz"},ang={["class:Priest"]="Ingenstans är vanhelgandet av heliga löften tydligare än här, där korstågets förhörsledare förvandlar helig disciplin till fysisk lemlästning och sadistisk plåga.",["race:Undead"]="Chamber of Atonement visar hur grym Scarlet Crusade är mot ditt folk. Här torteras tillfångatagna övergivna som Vorrel Sengutz systematiskt för att de existerar."},sec={{t="En plågornas hall",b="Chamber of Atonement fungerar som tröskel till Forlorn Cloister, men är långt ifrån en fristad för fridfull bön. Scarlet Crusade har i stället gjort den ståtliga entrén till ett plågohus, utrustat med sträckbänkar, bojor och brinnande eldfat. Fanatiska inkvisitorer använder redskapen för att framtvinga bekännelser och plåga fångar. De ser outhärdlig smärta som den enda lämpliga botgöringen för oheliga varelser. Kammaren genljuder ständigt av de fördömdas skrik, medan grymma fångvaktare ser till att de som går in sällan kommer ut oskadda."},{t="Inkvisitorns domän",b="Kammaren står under uppsikt av Interrogator Vishas, en av korstågets mest sadistiska utövare av tvång. Vishas är groteskt stolt över att knäcka beslutsamheten hos alla som ertappas med att korsa klostrets gränser. Bland hans mest uppskattade offer finns den övergivna fången Vorrel Sengutz, som har utstått ändlösa veckor av plågor under Vishas händer. Grymheten innanför dessa väggar visar utomstående att Scarlet Crusades korståg för renhet har förvridits till hänsynslös sadism."}},faq={{q="Vad används Chamber of Atonement till?",a="Den fungerar som Scarlet Crusades förhörs- och tortyrflygel i klostrets kyrkogårdsflygel. Fångar, främst övergivna och andra som betraktas som fiender, förhörs, kuvas och torteras här med brutala redskap innan deras kroppar kastas ut på kyrkogården.",al={"kammarens syfte","varför finns tortyrredskap här","vad händer i chamber of atonement"}},{q="Vem styr över kammaren?",a="Rummet står under befäl av Interrogator Vishas, en sadistisk torterare i Scarlet Crusade som är ökänd för att njuta av sina offers lidande.",al={"vem är bossen här","ledaren för chamber of atonement","vem styr tortyrkammaren"}},{q="Vart leder det här rummet?",a="Det är den yttersta hallen i kyrkogårdsflygeln och leder direkt till Forlorn Cloister, den öppna kyrkogården där fallna korsfarare och rastlösa döda vistas.",al={"kammarens utgångar","vart leder chamber of atonement","nästa område efter chamber of atonement"}},{q="Vem hålls fången här?",a="En övergiven fånge vid namn Vorrel Sengutz har hållits inspärrad och torterats i kammaren av Interrogator Vishas i flera veckor.",al={"vem är fånge här","vorrel sengutz","torterad fånge"}}},fx={["5cd82fbf"]={q="Vad är Chamber of Atonement?",a="Chamber of Atonement är den yttersta salen i kyrkogårdsflygeln i Scarlet Monastery. Den ligger precis framför Forlorn Cloister och den öppna kyrkogården och fungerar som en dyster tröskel dit Scarlet Crusade släpar fångar för brutala förhör.",al={"vad är chamber of atonement","information om chamber of atonement","om chamber of atonement"}},f468ffff={q="Är Chamber of Atonement farligt?",a="Det är ytterst farligt. Kammaren bemannas av fanatiska torterare från Scarlet, ledda av Interrogator Vishas, och omges av ohyggliga tortyrredskap. Alla inkräktare eller personer som misstänks sympatisera med de odöda angrips genast och utsätts för samma skoningslösa grymhet som fångarna.",al={"är chamber of atonement farligt","hot i chamber of atonement","hur farligt är chamber of atonement"}},["1937bc67"]={q="Varför kallas det Chamber of Atonement?",a="Scarlet Crusade gav salen dess namn utifrån sin förvridna tro att alla som besmittats av odödlighet eller motarbetar deras korståg måste bekänna och sona sina synder genom lidande. För inkvisitorerna är lidande och tortyr under deras klingor de enda sanna vägarna till botgöring.",al={"varför chamber of atonement","betydelsen av chamber of atonement","varför kallas det atonement"}}},fp="20,235,15.361.0,25.268.0,42.261.0,26.112.0,26.186.0,31.102.0"}
P.entries["subzone:champions-hall"] = {n="Champions' Hall",s="I Stormwinds Old Town vaktas Champions' Hall och är reserverad för Alliansens officerare. Kvartermästarna förser veteraner som bevisat sig i strid med vapen, rustningar och regalier.",h="I Stormwinds Old Town vaktas Champions' Hall och är reserverad för Alliansens officerare.",kw={"champions hall","överfältherre","riddare","officersbaracker","old town","pvp-försäljare","kvartermästare","stormwind"},ang={["class:Warrior"]="Som krigare vid frontlinjen kan du vända dig till Champions' Hall för tung stridsutrustning och vapen som är reserverade för beprövade befälhavare på slagfältet.",["faction:Alliance"]="För Alliansen hedrar Champions' Hall dem i Stormwind som viger sina liv åt att slå tillbaka hordens intrång."},sec={{t="Alliansens officersbaracker",b="Champions' Hall ligger bakom en bevakad ingång i Old Town och är reserverad för Alliansens framstående krigare. Militärbefäl samlas kring kartor över Azeroth för att diskutera pågående fälttåg, omgivna av vapen och gradbeteckningar. Endast allianssoldater som har uppnått graden riddare eller högre får komma in. Där inne förser kvartermästarna stridsvana soldater med elitvapen, rustningar och riddjur som ska hjälpa dem mot horden i omstridda länder."}},faq={{q="Var ligger Champions' Hall?",a="Champions' Hall ligger i södra Old Town i Stormwind City, bakom en bevakad ingång.",al={"var ligger champions hall","plats för pvp-försäljare i stormwind","hur hittar jag champions hall"}},{q="Vem får komma in i Champions' Hall?",a="Allianssoldater som har uppnått graden riddare eller högre i strid får komma in i Champions' Hall. Rekryter utan den graden och civila avvisas.",al={"får vem som helst gå in","krav för champions hall","varför kan jag inte gå in i champions hall"}},{q="Vad finns i Champions' Hall?",a="Kvartermästarna där inne erbjuder vapen och rustningar avsedda för officerare, gradbeteckningar och särskilda krigsmountar. Alliansens taktiker och generaler samlas kring bord täckta av kartor över Azeroth.",al={"vad finns i champions hall","vilka försäljare finns i champions hall","belöningar i champions hall"}},{q="Vad är hordens motsvarighet till den här byggnaden?",a="Hordens motsvarighet är Hall of Legends i Orgrimmar, där dekorerade hordkrigare får samma militära utrustning.",al={"hordens version av champions hall","pvp-rum i orgrimmar","hordens pvp-baracker"}}},fx={["5bb2303a"]={q="Vad är Champions' Hall?",a="Champions' Hall fungerar som Alliansens officerskaserner i Stormwind City. Den ligger undangömd i Old Town och är en exklusiv fristad där dekorerade militärer och beprövade stridskämpar från Alliansen samlas, går igenom krigsstrategier och utrustar sig med specialvapen och rustningar.",al={"vad är champions' hall","champions' hall i stormwind","vad är det här för plats"}},["68396c8b"]={q="Varför kallas det Champions' Hall?",a="Namnet kommer från Alliansens beprövade kämpar, som har förtjänat rätten att passera dess tröskel. Bara de som utmärkt sig på slagfältet och nått officersgraden riddare eller högre räknas som sanna mästare värdiga att träda in i dess salar.",al={"varför kallas det champions' hall","betydelsen av champions' hall","vilka är mästarna"}},b22714b1={q="Är Champions' Hall farligt?",a="Inte för Alliansens soldater. Kasernerna ligger djupt inne i Stormwinds Old Town och är skyddade bakom en förtrollad portal, med hård bevakning av Alliansens officerare och kvartermästare. Men en hordinfiltratör som är dumdristig nog att ta sig in i Stormwind skulle finna salen fylld av några av Alliansens mest fruktade veteraner.",al={"är champions' hall farligt","är det tryggt i champions' hall","hot i champions' hall"}}},fp="15,189,31.377.0,37.87.0,42.161.0,35.178.0,46.125.0"}
P.entries["subzone:charred-vale"] = {n="The Charred Vale",s="The Charred Vale är en pyrande dal i sydvästra Stonetalon Mountains, ödelagd av Venture Companys hänsynslösa avskogning och maskiner. Den var en gång en blomstrande tillflyktsort för trädandar och chimärer, men nu härjar eld, kringströvande elementarer och fientliga harpyor där.",h="The Charred Vale är en pyrande dal i sydvästra Stonetalon Mountains, ödelagd av Venture Companys hänsynslösa...",kw={"förkolnad uråldrig","bloodfury","the charred vale","chimär","eldelementar","stonetalon","sun rock retreat","venture company"},ang={["class:Druid"]="Förödelsen här är en hård varning om vad som händer när den naturliga balansen slås sönder av tygellös girighet. Därför står dalen i centrum för återställningsarbetet.",["faction:Horde"]="Hordens styrkor utgår från Sun Rock Retreat och samarbetar nära med cenarionallierade för att hejda den elementära oron och trycka tillbaka de fördärvande efterverkningarna av Venture Companys verksamhet."},sec={{t="En svedd skog",b="För inte länge sedan var den här sydvästra sänkan en frodig alpin skog, bevakad av ståtliga trädandar och bebodd av inhemska chimärer och harpyor. Förödelsen började när Venture Company anlände. Den giriga goblinligan kalhögg skogen med explosiva maskiner, fördärvade dess väktare och väckte kaotiska eldelementarer. Trädandarna lyckades till slut driva bort goblinerna, men landet lämnades sönderslaget, brandskadat och förgiftat av de avskyvärda anordningar som de flyende skogshuggarna hade lämnat efter sig."},{t="Kampen för återväxt",b="I dag vandrar förkolnade uråldriga blint genom rök och aska, sida vid sida med ursinniga elementarer. Bloodfury-harpyor häckar i de kala träden och försvarar det som återstår av deras revir. Trots dalens fientlighet vägrar druider från Sun Rock Retreat att överge området. De skickar ut resande för att så förtrollade frön och vårda de fördärvade uråldriga, i en ihärdig kamp för att återta den svedda marken."}},faq={{q="Varför brinner Charred Vale?",a="Förödelsen orsakades av Venture Companys hänsynslösa skogsavverkning. Deras destruktiva maskiner och aggressiva avskogning rasade landets ursprungliga andar och släppte lös destruktiva eldelementarer som spred sig över dalen.",al={"varför brinner den","vem brände charred vale","vad hände med charred vale"}},{q="Kan skogen i Charred Vale någonsin återhämta sig?",a="Taurendruider från närliggande Sun Rock Retreat tror det. De ber resande lugna de ursinniga trädandarna och plantera förtrollade jordfrön i askan, i hopp om att locka fram gröna skott ur den förstörda jorden.",al={"återhämtar sig charred vale","druider i charred vale"}},{q="Vilka varelser lever i Charred Vale?",a="Sänkan kryllar av fientliga elementära eldandar, förkolnade och hämndlystna uråldriga, Scorched Basilisks och vilda chimärer. Den hemsöks också av Bloodfury-harpyor.",al={"monster i charred vale","vad lever i charred vale"}},{q="Vad kallades Charred Vale innan den brann?",a="Dess ursprungliga namn har fallit i glömska, men den var känd som en frodig skogstillflykt långt innan goblinernas yxor kom dit.",al={"charred vales gamla namn","charred vales ursprungliga namn"}}},fx={e38ca889={q="Vad är The Charred Vale?",a="The Charred Vale är en vidsträckt, pyrande dal i sydvästra Stonetalon Mountains. Den var en gång en lummig skog som vaktades av uråldriga treants, men har förvandlats till aska, lavasprickor och brinnande stubbar efter förödande industriell exploatering.",al={"vad är the charred vale","översikt över the charred vale","om the charred vale"}},["97858e06"]={q="Vad hände vid The Charred Vale?",a="Gobliner från Venture Company drog genom dalen, kalhögg skogen och satte marken i brand. När de uråldriga trädväktarna reste sig för att försvara skogen och driva bort skogshuggarna, väckte konflikten de lokala naturandarnas vrede, slet upp jorden och släppte lös oberäkneliga eldelementarer. När goblinerna drog sig tillbaka förgiftade deras giftiga vapen de överlevande uråldringarna, som förvandlades till förkolnade, vansinniga skal.",al={"the charred vales historia","vad hände i the charred vale","hur förstördes the charred vale"}},["543e0702"]={q="Är The Charred Vale farligt?",a="Det är en av de mest fientliga platserna i Stonetalon. Förutom den pyrande marken och kvävande röken möter du eldiga elementarer, vildsinta Bloodfury-harpior, aggressiva chimärer, förkolnade basilisks och vansinniga, förmörkade uråldringar.",al={"är the charred vale farligt","hot i the charred vale","faror i the charred vale"}}},fp="12,205,19.456.0,20.358.0,32.189.0,48.222.0,40.166.0,50.134.0"}
P.entries["subzone:chill-breeze-valley"] = {n="Chill Breeze Valley",s="Chill Breeze Valley är ett kargt, snötäckt pass i västra Dun Morogh som förbinder dvärgbosättningen Kharanos med den belägrade staden Gnomeregan. Huvudleden trafikeras ofta av unga resenärer och flyktingar, men i de avskilda skrymslena lurar farliga bestar och blodiga lyor.",h="Chill Breeze Valley är ett kargt, snötäckt pass i västra Dun Morogh som förbinder dvärgbosättningen Kharanos...",kw={"grottor","chill breeze valley","dun morogh","gnomeregan","kharanos","t-formad","wendigo"},ang={["race:Dwarf"]="Bergsklättrare och unga dvärgjägare prövar sin skicklighet genom att rensa bort de våldsamma wendigos som hotar den viktiga passagen mellan centrala Dun Morogh och de västra högländerna.",["race:Gnome"]="För gnomiska flyktingar som flyr följderna av Gnomeregan mot tryggheten i Kharanos och Ironforge är det ett avgörande första steg att överleva färden genom Chill Breeze Valleys rovdjursmarker."},sec={{t="En korsväg av snö och klor",b="Chill Breeze Valley bildar en T-formad ränna genom bergen i västra Dun Morogh. Längs huvudleden från öster till väster färdas ständigt unga dvärgar och gnomer mellan Kharanos och utkanten av Gnomeregan. Men att ge sig in på dalens nord-sydliga sidospår är en helt annan sak. Här finns blodfläckar och sönderslitna kadaver, och i de skuggiga trakterna lurar våldsamma rovdjur. Framför allt jagar vilda wendigos från sina lyor i djupa isgrottor alla som är dumdristiga nog att vandra in på deras jaktmarker."}},faq={{q="Var ligger Chill Breeze Valley?",a="Chill Breeze Valley ligger i västra Dun Morogh, mellan bergsnoden Kharanos i öster och gnomernas teknologiska stad Gnomeregan i väster.",al={"chill breeze valley läge","var ligger chill breeze valley","chill breeze valley karta"}},{q="Varför är det så farligt att färdas genom dalen?",a="Huvudleden mellan Kharanos och Gnomeregan är relativt säker och vältrafikerad, men dalens norra och södra sidospår är jaktmarker för rovdjur. Snön där är fläckad av blod och sönderslitna kadaver, och spåren leder till grottor där våldsamma, revirhävdande wendigos håller till.",al={"monster i chill breeze valley","faror i chill breeze valley","varför finns det ben här"}},{q="Vilka slags bestar har sina lyor här?",a="I dalens djupare skrymslen håller våldsamma wendigos till. En särskilt stor och kraftfull wendigo har tagit en av grottorna i besittning som sin lya.",al={"wendigo i chill breeze valley","vad lever i chill breeze valley"}}},fx={["746bfe00"]={q="Vad är Chill Breeze Valley?",a="Chill Breeze Valley är ett kargt, T-format pass i västra Dun Morogh som förbinder ruinerna av Gnomeregan i väster med staden Kharanos i öster. Huvudleden är en viktig genomfartsled för resande dvärgar och flyktingar från gnomerna, medan de djupare delarna fortfarande är förrädisk, snötäckt vildmark.",al={"chill breeze valley","vad är det här för dal","om chill breeze valley"}}},fp="19,194,30.379.0,37.104.0,49.239.0,42.137.0"}
P.entries["subzone:chillwind-camp"] = {n="Chillwind Camp",s="Chillwind Camp ligger vid det södra passet från Alterac Mountains in i Western Plaguelands. En styrka från Alliansen bemannar lägret tillsammans med Argent Dawn. Det är den sista säkra samlingsplatsen före Lordaerons pestdrabbade ruiner. Härifrån leder befälhavarna anfall mot närliggande fästen som hålls av Scourge och mot pestkittlarna.",h="Chillwind Camp ligger vid det södra passet från Alterac Mountains in i Western Plaguelands.",kw={"alterac mountains","andorhal","argent dawn","ashlam valorfist","pestkittlar","chillwind camp","chillwind point","western plaguelands"},ang={["class:Paladin"]="Lord Grayson Shadowbreaker i Stormwind skickar lovande paladiner hit för att bistå Commander Valorfist och låta Silver Hands heliga vrede drabba de odöda leden.",["faction:Alliance"]="Chillwind Camp är spetsen i Alliansens försök att återta norra Lordaeron. Här finns en trygg tillflykt, griffontransporter och order för insatser mot Scourge."},sec={{t="Vid pestens rand",b="Chillwind Camp ligger i det klippiga passet som sluttar ner från Chillwind Point. Det är den första försvarslinjen och huvudbasen för Alliansens styrkor som tränger in i Western Plaguelands. Höga bergsryggar skiljer lägret från den värsta smittan, men nordens dödskyla vilar tungt över tälten och palissaderna. Under Commander Ashlam Valorfist försöker en liten garnison av soldater, spejare och specialister från Argent Dawn hejda fasorna längs King's Road och samla underrättelser som behövs för att återta Lordaerons fallna åkrar."},{t="Ett utnötningskrig",b="Chillwind Camp saknar den stående armé som krävs för ett fullskaligt anfall mot Andorhal eller den nekromantiska fästningen Scholomance och förlitar sig därför på fristående hjältar och legosoldater. Här fokuserar insatserna på riktade gerillaangrepp: att samla underrättelser i fält om Cult of the Damned, oskadliggöra de alkemiska pestkittlar som förgiftar jorden och hålla försörjningslederna öppna till utposter i öster, som Light's Hope Chapel. Med Scourge i ruinerna strax norrut och Forsaken som befäster den västra gränsen kämpar lägrets försvarare helt enkelt för att hindra fienden från att övermanna passet."}},faq={{q="Vad är syftet med Chillwind Camp?",a="Chillwind Camp är Alliansens och Argent Dawns främsta fäste i söder, vid gränsen till Western Plaguelands. Därifrån kan de iscensätta gerillaanfall mot Scourge i Andorhal och oskadliggöra områdets pestkittlar.",al={"varför finns chillwind camp här","syftet med chillwind","vad är chillwind camp"}},{q="Hur tar du dig till Chillwind Camp från Southshore?",a="Från Southshore i Hillsbrad Foothills reser du norrut mot Tarren Mill och följer bergsstigen in i den östra delen av Alterac Mountains. Stigen går upp förbi trollruinerna vid Chillwind Point och sedan ner norrut genom en ravin direkt till lägret.",al={"hur tar man sig till chillwind camp","vägbeskrivning till chillwind","vägen till chillwind"}},{q="Vilken utpost motsvarar den här för Horden?",a="Hordens motsvarighet är The Bulwark, vid den västra gränsen mellan Tirisfal Glades och Western Plaguelands. Båda utposterna är befästa samlingsplatser för fälttåg mot områdets Scourge.",al={"hordens chillwind camp","hordens motsvarighet till chillwind","finns det ett chillwind för horden"}},{q="Vem leder styrkorna vid Chillwind Camp?",a="Commander Ashlam Valorfist leder garnisonen vid Chillwind Camp. Han samordnar frivilliga från Alliansen, riddare från Silver Hand och Argent Dawns förbindelseofficerare i insatserna bland ruinerna och de förgiftade gårdarna i trakten.",al={"ledaren för chillwind camp","vem ansvarar för chillwind camp","befälhavaren för chillwind"}}},fp="14,225,22.506.0,18.422.0,38.220.0,48.252.0,45.194.0,42.206.0"}
P.entries["subzone:chillwind-point"] = {n="Chillwind Point",s="Chillwind Point är en klippig höjd och en forntida trollruin vid gränsen mellan Alterac Mountains, Hillsbrad Foothills och Western Plaguelands. Den har fått sitt namn av de iskalla vindarna som tjuter genom bergspasset från det pesthärjade norr. I dag är den en ödslig utsiktsplats där främst en ensam trollmystiker håller till.",h="Chillwind Point är en klippig höjd och en forntida trollruin vid gränsen mellan Alterac Mountains, Hillsbrad...",kw={"alterac","bath'rah","chillwind","chillwind point","hillsbrad","plaguelands","trollruiner","vindväktaren"},ang={["class:Shaman"]="De vilda vindbyarna som pressas genom passet gör Chillwind Point till en plats för att studera elementen. Därför söker sig utövare dit för att lära sig av eremiten Bath'rah the Windwatcher.",["faction:Alliance"]="Dessa forntida ruiner ligger strax söder om gränsposten vid Chillwind Camp och markerar övergången mellan de omstridda kullarna och Plaguelands skräckinjagande marker."},sec={{t="En bitter korsväg",b="Chillwind Point ligger högt i gränslandet där Hillsbrad övergår i Alterac och det pesthärjade norr, med utsikt över bergsravinen som leder rakt in i Western Plaguelands. Långt innan Lordaeron gjorde anspråk på passen byggde forntida troll stenbyggnader på dessa höjder. Resterna står fortfarande kvar, väderbitna av elementen. I dag blåser kalla vindar söderut genom ravinen och för med sig kylan från det fallna norr till kullarnas dalar nedanför."},{t="Vindväktaren",b="Trots sitt karga läge och närheten till marker som härjats av Scourge är Chillwind Point inte helt övergiven. De gamla murverken ger skydd åt Bath'rah the Windwatcher, en eremit av djungeltrollen som samtalar med de våldsamma vindarna som sveper genom bergspasset. Resande och schamaner som färdas norrut söker sig ofta till hans ensliga läger bland ruinerna för att lära sig bergsvindarnas hemligheter."}},faq={{q="Vad är Chillwind Point?",a="Chillwind Point är en forntida trollruin på en hög höjd med utsikt över passet mellan Hillsbrad, Alterac och Western Plaguelands. Platsen har fått sitt namn av de bitande vindarna som ständigt visslar genom den närliggande ravinen.",al={"översikt över chillwind point","var ligger chillwind point","vad är det här för plats"}},{q="Är Chillwind Point samma plats som Chillwind Camp?",a="Nej, även om de ofta förväxlas. Chillwind Camp är Alliancens och Argent Dawns befästa utpost strax norrut, på andra sidan gränsen i Western Plaguelands. Chillwind Point är däremot den förfallna trollhöjden en bit söderut.",al={"chillwind point eller camp","skillnaden mellan chillwind camp och point","är det här chillwind camp"}},{q="Vem bor vid Chillwind Point?",a="Den enda som bor i ruinerna är Bath'rah the Windwatcher, en vänlig djungeltroll som studerar vindarna och hjälper sökare efter elementarer och schamaner som vågar sig genom bergspasset.",al={"vem är här","vem är trollet","bathrah"}},{q="Varför är det så kallt här?",a="Platsen ligger precis intill en smal bergsravin som leder iskalla vindar från de höga nordliga trakterna och Western Plaguelands pesthärjade vidder ner till de lägre kullarna.",al={"varför är det kyligt","kalla vindar","iskall vind"}}},fx={["8e613e22"]={q="Vad hände med Chillwind Point förr?",a="Detta högt belägna pass var en gång en del av det välmående människoriket Lordaeron. Troll hade dock byggt den urgamla stenstrukturen som fortfarande kröner höjden långt innan Lordaeron föll. I dag står den som en övergiven relik mellan det oroliga Alterac och farsoten som kryper ner från norr.",al={"chillwind points historia","chillwind points förflutna","vad hände vid chillwind point"}},["14e6a6f5"]={q="Varför ligger Chillwind Point i ruiner?",a="Stenbyggnaden på höjden är en urgammal trollruin som förföll långt före de senaste krigen. Efter Lordaerons sammanbrott och förödelsen över de omgivande bergen är det ingen civiliserad makt som underhåller passet. Bara väderbiten sten står kvar och utsätts för de bittra väderkrafterna.",al={"varför ligger chillwind point i ruiner","ruinerna vid chillwind point","varför är chillwind point övergivet"}},b1aade3c={q="Är Chillwind Point farligt?",a="Själva höjden är förhållandevis lugn och hyser bara eremiten Bath'rah the Windwatcher. Men faran lurar alldeles intill: passet leder ner bittra vindar från de pesthärjade fasorna i Western Plaguelands strax norrut, och den omgivande vildmarken kryllar av rovdjur och banditer.",al={"är chillwind point tryggt","faran vid chillwind point","hot vid chillwind point"}}},fp="15,238,19.400.0,15.370.0,24.209.0,46.185.0,29.169.0,23.170.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Circle of Aquementas",s="Circle of Aquementas är en mystisk ring av resta stenar längs Tanaris östra kust, strax söder om Lost Rigger Cove. Här kan resenärer utföra en ritual och kalla fram elementaranden Aquementas.",h="Circle of Aquementas är en mystisk ring av resta stenar längs Tanaris östra kust, strax söder om Lost Rigger...",kw={"aquementas","circle of aquementas","elementar","lost rigger cove","resta stenar","tanaris"},ang={["class:Shaman"]="Cirkeln kan samla urkrafter och förankra en elementarande, vilket gör den till en fascinerande plats för alla shamaner som vandrar längs Tanaris kust."},sec={{t="En ring vid havet",b="Undangömd längs Tanaris vindpinade östkust ligger Circle of Aquementas stilla söder om piraternas fäste vid Lost Rigger Cove. Platsen består av väderbitna stenar som står resta i en cirkel och sjuder av elementarenergi vid öknens strand. Den fungerar som en samlingspunkt för att åkalla Aquementas, en elementarvarelse knuten till en uråldrig artefakt. Medan Southsea-rövare och kringströvande havsdjur härjar på stränderna intill, förblir cirkeln en högtidlig plats för ritualer bland sanddynerna."}},faq={{q="Vad är Circle of Aquementas?",a="Det är en cirkel av resta stenar på Tanaris sydöstra kust, som används för att åkalla elementarvarelsen Aquementas.",al={"vad är den här stencirkeln","circle of aquementas syfte","resta stenar tanaris"}},{q="Var ligger cirkeln?",a="Cirkeln ligger på Tanaris östra kust, rakt söder om klipporna och ingången till Lost Rigger Cove.",al={"var ligger circle of aquementas","hur hittar man circle of aquementas","circle of aquementas plats"}},{q="Vem är Aquementas?",a="Aquementas är en elementarande knuten till en uråldrig uppdragskedja om märkliga artefakter. Den åkallas direkt i stencirkeln.",al={"vem är aquementas","aquementas bakgrund"}},{q="Vaktas cirkeln av pirater?",a="Southsea-pirater stryker omkring vid Lost Rigger Cove och längs kusten, men själva cirkeln är främst en avskild plats för åkallelser.",al={"finns det pirater här","southsea-pirater nära cirkeln"}}},fp="20,93,17.353.0,33.121.0,28.108.0,18.98.0,33.125.0"}
P.entries["subzone:circle-of-east-binding"] = {n="Circle of East Binding",s="Circle of East Binding är en gåtfull, uråldrig ritualplats i den östra delen av Arathi Highlands, strax sydväst om Hammerfall. Platsen kretsar kring Stone of East Binding och är våldsamt omstridd och bevakad av kringströvande vattenelementarer som kallas cresting exiles.",h="Circle of East Binding är en gåtfull, uråldrig ritualplats i den östra delen av Arathi Highlands, strax...",kw={"arathi highlands","circle of east binding","cresting exile","elementarer","hammerfall","stone of east binding"},ang={["class:Shaman"]="Bindningsstenarna i Arathi vittnar om primitiva eller uråldriga metoder för att kuva elementarkrafter, något som står i skarp kontrast till en schamans strävan efter balans och samhörighet med elementen.",["faction:Horde"]="De oberäkneliga vattenandarna kring cirkeln ligger alldeles intill vägen från Hammerfall och är ett ständigt territoriellt besvär för Hordens patruller och försörjningsleder."},sec={{t="Den östra stenen",b="Circle of East Binding ligger bland de karga högländerna öster om Stromgarde och är en av flera uråldriga kraftplatser utspridda över Arathi Basin. I dess mitt står Stone of East Binding, ett gåtfullt monument som utstrålar kraftfull elementarmagi. Virvlande vattenelementarer som kallas cresting exiles strövar omkring i området och försvarar stenen ursinnigt mot alla dödliga som vågar närma sig."},{t="Elementarisk fångenskap",b="Stenarna runtom i Arathi är inga vanliga naturfenomen. De fungerar som uråldriga bindningsrunor, avsedda att kuva och fängsla oberäkneliga elementarkrafter. De rastlösa vattenandarna kring den östra cirkeln vittnar om påfrestningen på dessa runor, när varelser som dragits till eller fångats av stenens magi går till angrepp mot resenärer och äventyrare på vägen till Hammerfall."}},faq={{q="Var ligger Circle of East Binding?",a="Circle of East Binding ligger i den östra delen av Arathi Highlands, söder om huvudvägen och en bit sydväst om Hordens läger Hammerfall.",al={"platsen för east binding","var ligger circle of east binding","karta över circle of east binding"}},{q="Vilka varelser finns här?",a="Cirkeln är översvämmad av aggressiva vattenelementarer, cresting exiles, som skoningslöst vaktar Stone of East Binding.",al={"fiender vid east binding","vilka monster finns vid east binding","cresting exiles"}},{q="Varför finns det vattenelementarer i högländerna?",a="Stenarna som finns utspridda över Arathi fungerar som uråldriga elementarbindningar. Vattenelementarernas närvaro här tyder på att vattenelementarisk energi hålls instängd eller dras till platsen genom den östra bindningsstenen.",al={"varför vattenelementarer i arathi","elementarlore om east binding"}},{q="Vad har Stone of East Binding för syfte?",a="Stone of East Binding ingår i ett samordnat nätverk av bindningsstenar i Arathi Highlands, utformat för att förankra, kanalisera och låsa in oberäkneliga elementarvarelser.",al={"syftet med stone of east binding","vad gör east binding-stenen"}}},fp="22,156,16.294.0,22.248.0,44.118.0,30.103.0,48.139.0,49.169.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="Circle of Inner Binding",s="Circle of Inner Binding är en uråldrig ring av rituella stenar i de södra kullarna i Arathi Highlands, strax öster om Stromgarde Keep. Den bevakas av fientliga jordelementaler och rymmer Stone of Inner Binding, det kraftfullaste sigillet som används för att hålla den fängslade elementarprinsessan Myzrael fången djupt under jorden.",h="Circle of Inner Binding är en uråldrig ring av rituella stenar i de södra kullarna i Arathi Highlands, strax...",kw={"arathi highlands","circle of inner binding","jordelementaler","myzrael","rumbling exile","stone of inner binding","stromgarde keep"},ang={["class:Mage"]="Stenarnas geometriska placering bildar ett intrikat och långvarigt fält som kan kanalisera och förankra enorma magiska tryck från underjorden.",["class:Shaman"]="Den råa jordenergin som strömmar genom Circle of Inner Binding tyder på uråldriga, starka elementarband, men de lokala jordandarnas onaturliga oro varnar för en fördärvande kraft under marken."},sec={{t="Det inre sigillet",b="Circle of Inner Binding ligger på en platå söder om huvudvägen och förankrar de starkaste av de uråldriga skydden som håller Myzrael förseglad under Arathi. Höga stenblock omger den centrala Stone of Inner Binding, som pulserar av tät geomagisk kraft. Enorma, mullrande jordelementaler patrullerar stenarna utan uppehåll, dragna till platsens resonans eller bundna som väktare. Trots dessa kraftfulla skydd kan sprickor i det inre sigillet låta entiteten som fångats under höglandet nå ut telepatiskt och viska böner om frihet till intet ont anande vandrare som hanterar skärvor av stenen."}},faq={{q="Vad är syftet med Circle of Inner Binding?",a="I cirkeln finns Stone of Inner Binding, som fungerar som det främsta och starkaste skyddet och förankrar Myzraels underjordiska fängelse. Den verkar tillsammans med andra elementarcirklar utspridda över Arathi Highlands för att hålla varelsen fången under marken.",al={"varför finns den här cirkeln","vad gör den inre bindningen","circle of inner binding i historien"}},{q="Vilka varelser vaktar cirkeln?",a="Cirkeln vaktas noga av mäktiga jordelementaler, främst Rumbling Exiles. Dessa steniga jättar angriper aggressivt alla som närmar sig de rituella stenarna.",al={"vilka fiender finns här","fiender vid den inre bindningen","rumbling exile"}},{q="Vem viskar genom stenen?",a="Rösten som når ut genom bindningsskärvan tillhör Myzrael, en uråldrig och mäktig elementarprinsessa som hålls fängslad djupt under jorden. Hennes psykiska räckvidd har lyckats tränga igenom det spruckna sigillet och nå dödligas sinnen.",al={"vem talar till dig här","myzraels röst","viskande sten"}},{q="Var ligger Circle of Inner Binding?",a="Den ligger i den södra delen av Arathi Highlands, på den upphöjda bergsryggen strax öster om den förstörda fästningen Stromgarde Keep.",al={"den inre bindningens plats","var ligger circle of inner binding","hur hittar man den inre bindningen"}}},fp="23,213,13.435.0,51.221.0,33.138.0,36.198.0,45.106.0"}
P.entries["subzone:circle-of-west-binding"] = {n="Circle of West Binding",s="Circle of West Binding är en av flera forntida ritualplatser utspridda över Arathi Highlands, nära Thoradin's Wall. Runt Stone of West Binding trängs platsen av brinnande elementvarelser som är bundna dit.",h="Circle of West Binding är en av flera forntida ritualplatser utspridda över Arathi Highlands, nära Thoradin's...",kw={"arathi highlands","burning exile","circle of west binding","elementvarelse","ruul onestone","stone of west binding","thoradin's wall"},ang={["class:Mage"]="Arathis bindningsstenar ger magiker och andra utövare inblick i hur forntida magiker och shamaner förankrade och kuvade elementvarelser från andra plan.",["class:Shaman"]="Burning Exiles oberäkneliga närvaro visar att elementär oro fortfarande är bunden till dessa forntida arathiska hörnstenar."},sec={{t="Den västra hörnstenen",b="Circle of West Binding ligger intill de karga sluttningarna nära Thoradin's Wall och ingår i ett större nätverk av ritualplatser utspridda över Arathi Highlands. I dess mitt står Stone of West Binding, en forntida relik knuten till att hålla elementvarelser i schack. Området vimlar av Burning Exiles, oberäkneliga eldelementarer som skoningslöst vaktar platsens utkant och gör varje försök att närma sig stenen farligt för resande på de västra slätterna."}},faq={{q="Vad är Circle of West Binding?",a="Det är en forntida ritualplats i västra Arathi Highlands, nära Thoradin's Wall. Där finns Stone of West Binding, som vaktas hårt av fientliga eldelementarer.",al={"circle of west binding","stone of west binding","västra bindningscirkeln"}},{q="Varför finns eldelementarer här?",a="Burning Exiles håller till vid och vaktar Stone of West Binding. De är elementarkrafter som dragits till eller bundits vid de forntida magiska fokuspunkterna som byggdes över Arathi Highlands.",al={"burning exiles arathi","varför eldelementarer vid west binding","elementarer circle of west binding"}},{q="Vem är Ruul Onestone?",a="Ruul Onestone är en ogremagiker av Boulderfist som stryker omkring på platsen, en ovanlig och farlig best snarare än en lärd som studerar bindningsstenen.",al={"ruul onestone","ruul","dvärg vid west binding"}}},fp="22,173,20.332.0,35.179.0,35.164.0,21.131.0"}
P.entries["subzone:clean-zone"] = {n="Clean Zone",s="Clean Zone är en befäst enklav för sanering, inbäddad i den förstörda staden Gnomeregan, strax bortom övre Hall of Gears. Den är den enda trygga tillflyktsorten i den bestrålade anläggningen, där okorrumperade gnomiska styrkor håller stånd mot omgivande troggs och spetälska gnomer. Här erbjuder fältläkare, tekniker och specialiserade Sparklematic-maskiner en fristad och möjlighet att bärga föremål bland de radioaktiva ruinerna.",h="Clean Zone är en befäst enklav för sanering, inbäddad i den förstörda staden Gnomeregan, strax bortom övre...",kw={"clean zone","dormitory","gnomeregan","hall of gears","strålning","sparklematic 5200","tink sprocketwhistle","troggs"},ang={["profession:Engineering"]="De fungerande Sparklematic 5200-enheterna och handlaren Tink Sprocketwhistle gör utposten till en viktig plats för att leta igenom radioaktivt skrot efter sällsynta ritningar och mekaniska delar.",["race:Gnome"]="För gnomer är vistelsen i Clean Zone både en dyster påminnelse om hemmet de förlorat och en trotsig fyr av hopp om att Gnomegregans teknik fortfarande kan återtas från troggs."},sec={{t="En bastion i slaggen",b="Medan större delen av Gnomeregan föll offer för Mekkatorques katastrofala utsläpp av radioaktivt avfall, förblev Clean Zone orört. Den ligger strategiskt mellan Dormitory nedanför, som kryllar av troggs, och de omstridda korridorerna i Hall of Gears ovanför, och fungerar som en befäst framskjuten bas. Beslutsamma gnomiska försvarare, tekniker och fältläkare håller barrikaderna dag och natt, så att Alliansexpeditioner har en säker samlingsplats där de kan omgruppera sig, vårda sår och underhålla maskiner."},{t="Sparklematic 5200",b="Clean Zone är mer än en militär skans. Den är en knutpunkt för att bärga den förlorade huvudstaden. Gnomiska ingenjörer installerade Sparklematic 5200-enheter som kemiskt skrubbar och tvättar reliker täckta av ingrodd smuts, som hämtats från stadens radioaktiva djup. Tekniker och handelsmän som Tink Sprocketwhistle bearbetar de återvunna kugghjulen och prydnadssakerna, utrustar äventyrare och undersöker samtidigt de giftiga rester som fortfarande plågar de djupa tunnlarna."}},faq={{q="Varför är området inte bestrålat som resten av Gnomeregan?",a="I Clean Zone finns gnomer som inte påverkats av strålningen som ödelade Gnomeregan. Berättelsen förklarar inte exakt varför det här lilla området undgick kontaminering.",al={"varför är clean zone inte bestrålat","varför är det tryggt här","strålning i clean zone"}},{q="Vad gör Sparklematic 5200-maskinerna?",a="Sparklematic 5200-maskiner är specialiserade gnomiska tvätt- och saneringsapparater. Äventyrare kan mata in föremål täckta av ingrodd smuts, som hämtats från troggs och spetälska gnomer. Maskinerna tvättar bort radioaktiv smuts och blottar användbara malmer, ädelstenar, mynt eller tekniska märkvärdigheter.",al={"sparklematic 5200","vad är sparklematic-maskiner","tvätta bort smuts"}},{q="Vem styr och försvarar Clean Zone?",a="En hängiven avdelning av okorrumperade gnomiska vakter, fältläkare och tekniker håller vakt runt området. De slår tillbaka troggs som tränger fram från Dormitory och spetälska gnomer som kommer ner från de övre nivåerna, för att hålla samlingsplatsen säker.",al={"vem finns i clean zone","vakter i clean zone","vem håller clean zone"}},{q="Kan spelare vila eller reparera utrustning här utan fara?",a="Ja. Clean Zone fungerar som ett fältläger djupt inne i Gnomeregan. Där finns tekniska förnödenheter, reparationer hos handlaren Tink Sprocketwhistle och till och med en fungerande brevlåda för äventyrare bakom frontlinjen.",al={"reparationer i clean zone","kan man vila i clean zone","brevlåda i gnomeregan"}}},fx={dc9c4202={q="Vad är Clean Zone?",a="Clean Zone är en befäst fristad djupt inne i Gnomeregan, strax bortom den övre nivån i Hall of Gears. Den är den sista kvarvarande befästa platsen inne i den fallna huvudstaden där oförgiftade gnomer håller stånd, skyddade från det dödliga nedfallet.",al={"vad är clean zone","översikt över clean zone","om clean zone"}},fa9b1319={q="Vad hände med Clean Zone när Gnomeregan föll?",a="När överingenjör Mekkatorque öppnade strålningsventilerna för att rensa ut de invaderande troggarna ödelade det giftiga nedfallet staden och förvandlade många gnomer till lepragnomer. Gnomer som inte påverkats håller stånd i denna lilla tillflyktsort och försvarar den mot inkräktarna runt omkring.",al={"clean zones historia","vad hände vid clean zone"}},["844f3e3b"]={q="Är Clean Zone farligt?",a="Själva Clean Zone är säker och väl försvarad av elitvakter och sjukvårdare bland gnomerna. Men områdena precis intill är farliga: fientliga troggar har intagit sovsalen nedanför och svärmar över de övre nivåerna i Hall of Gears, alldeles utanför dess gräns.",al={"är clean zone farligt","hot i clean zone","faran i clean zone"}}},fp="10,243,21.370.0,21.371.0,59.158.0,42.269.0,40.220.0,39.178.0"}
P.entries["subzone:cleft"] = {n="The Cleft",s="Gnarlpine-furbolger överfaller resande i Cleft, nordväst om Dolanaar.",h="Gnarlpine-furbolger överfaller resande i Cleft, nordväst om Dolanaar.",kw={"the cleft","darnassus","dolanaar","furbolg","gnarlpine","moon priestess amara"},ang={["class:Druid"]="Som druid vet du att de fördärvade Gnarlpine hotar resande på vägen till Darnassus.",["race:NightElf"]="Som Night Elf ser du furbolger som länge varit allierade drivas till vansinne och attackera resande."},sec={{t="En härd av fördärv",b="Cleft ligger vid sidan av vägen mellan Dolanaar och Darnassus, där Gnarlpine-furbolger har sitt tillhåll. Den fördärvelse som sprider sig i Teldrassil har drivit dem till vansinne, och de har befäst sänkan. Därifrån hotar de resande på huvudvägen och riskerar att skära av Dolanaar från Darnassus."},{t="Vägarnas bakhåll",b="Moon Priestess Amara och hennes vaktposter håller vakt utanför ingången till Cleft. Deras försvar skyddar huvudvägen som förbinder Teldrassils byar med Darnassus, men Gnarlpine hotar fortfarande framkomligheten."}},faq={{q="Vad är Cleft?",a="Cleft är ett tillhåll för furbolger nordväst om Dolanaar, intill huvudvägen till Darnassus.",al={"vad är cleft","cleft teldrassil","cleft plats"}},{q="Vem kontrollerar Cleft?",a="Fientliga Gnarlpine-furbolger håller Cleft, drivna till vansinne av den fördärvelse som sprider sig i Teldrassil.",al={"vem bor i cleft","cleft fiender","vem styr cleft"}},{q="Varför strider nattalverna här?",a="Gnarlpine överfaller resande på vägen till Darnassus, så Moon Priestess Amara och Sentinels arbetar för att hålla vägen säker.",al={"varför anfalla cleft","cleft night elf uppdrag","vägen till darnassus"}},{q="Har Cleft någon koppling till Cleft of Shadow?",a="Nej. Cleft är en furbolggrotta i Teldrassil; Cleft of Shadow är en mörk grotta under Orgrimmar.",al={"cleft of shadow koppling","cleft jämfört med cleft of shadow"}}},fx={["3e19e4c1"]={q="Vad hände vid The Cleft?",a="Gnarlpine-furbolgerna tog sin tillflykt i grottan, men en ondskefull fördärvelse tog snabbt över deras sinnen. De blev vansinniga och började överfalla den närliggande vägen mot Darnassus, där de angrep oförsiktiga resenärer och hotade handeln med huvudstaden.",al={"the clefts historia","vad hände vid the cleft"}},de17fe22={q="Är The Cleft farligt?",a="The Cleft är mycket farligt. Fientliga, korrumperade Gnarlpine-furbolger trängs i den mörka hålan. De försvarar sin håla våldsamt och har redan överfallit försörjningsleder och hotat resenärer. Moon Priestess Amara och hennes väktare måste bevaka vägen precis utanför för att hålla dem tillbaka.",al={"fara i the cleft","är the cleft tryggt","hot i the cleft"}}},fp="5,72,19.284.0,21.188.1,18.84.0,23.95.0,38.126.0,44.102.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Cleft of Shadow",s="Rogues, warlocks och deras lärare samlas i Cleft of Shadow under Orgrimmar. Grottorna ger dem utrymme att öva sina konster under Hordens uppsikt.",h="Rogues, warlocks och deras lärare samlas i Cleft of Shadow under Orgrimmar.",kw={"cleft of shadow","darkfire enclave","orgrimmar","ragefire chasm","rövare","shadowswift brotherhood","häxmästare"},ang={["class:Rogue"]="Som rogue hittar du Shadowswift Brotherhood, giftköpmän och låsdyrkare i denna mörka avkrok, Hordens främsta samlingsplats för spejare.",["class:Warlock"]="Som warlock i Horden kan du åkalla demoner och binda felenergi i Darkfire Enclave under Orgrimmar, på avstånd från schamanernas och krigarnas omedelbara vrede."},sec={{t="En underjordisk fristad",b="Under Orgrimmar finns Cleft of Shadow, där rogues från Shadowswift Brotherhood och warlocks från Darkfire Enclave håller till. Thralls Horde hedrar schamanism och vapenkonst, men ledarna ger också plats åt subtilare konster. I grottorna verkar utövare av gift och felenergi på avstånd från dalens distrikt och under Orgrimmars uppsikt."},{t="En farlig gräns",b="Vid Clefts lägsta punkt öppnar sig en passage till Ragefire Chasm. Vulkaniska grottor genomkorsar marken under Orgrimmar, och deras faror lockar försvarare och ondskefulla kultister till grottans kant."}},faq={{q="Varför hålls häxmästare och rövare under jord här?",a="Thrall försöker ena Horden genom hedervärda schamaniska traditioner och krigartraditioner, medan många orcher misstror rogues och warlocks konster. Grottorna håller deras farliga felarbete och otillåtna verksamhet instängd och under uppsikt.",al={"varför cleft of shadow","varför häxmästare under jord i orgrimmar","cleft of shadow i berättelsen"}},{q="Vilka viktiga tränare och tjänster finns i Cleft of Shadow?",a="Tränare för rogues och warlocks arbetar i Cleft, tillsammans med giftleverantörer, reagentförsäljare och köpmän som säljer stavar och käppar.",al={"tränare i cleft of shadow","vilka finns i cleft of shadow"}},{q="Vad är ingången längst ner i grottan?",a="Öppningen leder till Ragefire Chasm, ett farligt nätverk av lavatunnlar under Orgrimmar. Troggs, brännande elementaler och avfälliga kultister hemsöker dess djup.",al={"grotta i cleft of shadow","ingång till cleft-grottan","vilken instans finns här"}}},fx={["866219a4"]={q="Vad är Cleft of Shadow?",a="Cleft of Shadow är en vidsträckt underjordisk grotta som skurits ut djupt under Orgrimmars klippiga kanjoner. Medan staden ovanför hyllar styrka, ära och öppen strid, rymmer denna dunkla underjordiska avkrok utövare vars konster väcker misstänksamhet: skurkar som lurar i skuggorna och häxdoktorer som utövar felmagi.",al={"vad är cleft of shadow","cleft of shadow i berättelsen","om cleft of shadow"}},["3bd03716"]={q="Vem bor i eller styr Cleft of Shadow?",a="Ingen enskild ledare styr grottan öppet. Den tillhör i stället de utstötta, spionerna och ockulta utövarna som horden tolererar. Här hittar du de smygande skurkarna i Shadowswift Brotherhood och häxdoktorerna i Darkfire Enclave, tillsammans med giftblandare och reagenthandlare som förser dem med material till deras olagliga konster.",al={"vem leder cleft of shadow","invånare i cleft of shadow","vem bor i cleft of shadow"}},b6f6ea67={q="Är Cleft of Shadow farligt?",a="Grottan är ett fungerande distrikt i Orgrimmar och relativt trygg för stadens invånare, även om demonbesvärjare och giftförsäljare gör den obehaglig. En mycket större fara lurar längst ner i klyftan: den vulkaniska nedstigningen till Ragefire Chasm, ett vidsträckt nätverk av lavatunnlar fullt av trogger och kultister, rakt under stadens grundvalar.",al={"är cleft of shadow tryggt","är cleft of shadow farligt","fara i cleft of shadow"}}},fp="15,133,24.319.0,21.192.0,50.228.0,69.130.0,49.155.0"}
P.entries["subzone:cliffspring-falls"] = {n="Cliffspring Falls",s="Cliffspring Falls är Darkshores dramatiska källa till den livsviktiga floden Cliffspring River, som störtar ner från de östra klipporna i kustskogen. Den har länge varit regionens främsta källa till rent dricksvatten, men vattnet har nyligen fallit offer för en illasinnad smitta som sprider sig. Den underjordiska grotta som matar vattenfallet har invaderats av fientliga naga och skuggiga kultister från Twilight's Hammer.",h="Cliffspring Falls är Darkshores dramatiska källa till den livsviktiga floden Cliffspring River, som störtar...",kw={"auberdine","cliffspring falls","cliffspring river","darkshore","felwood","naga","twilight's hammer","vattenkorrumpering","vattenförorening"},ang={["class:Druid"]="Druider från Cenarion Circle övervakar floden noga och försöker fastställa orsaken till och rena den onaturliga förruttnelse som hotar att kväva vildmarken.",["race:NightElf"]="För kaldorei i Auberdine är korrumperingen av Cliffspring Falls en miljömässig och andlig kris. Den förorenar det livsviktiga vatten som ger näring åt Darkshores uråldriga skogar."},sec={{t="En smittad källa",b="Från grottor högt uppe i de klippiga branterna längs Darkshores östra gräns forsar Cliffspring Falls och matar floden Cliffspring River, som slingrar sig västerut genom skogen och mynnar ut i havet. Förr gav vattenfallet de lokala Night Elf-bosättningarna det renaste dricksvattnet. På senare tid har vattnet dock blivit illaluktande och grumligt, och sjukdomar och ekologiskt förfall sprider sig i hela flodbäckenet. Naturforskare som undersökt saken har upptäckt att grottsystemet vid vattenfallets källor är fullt av vidriga naga och mörka kultister. De smider planer i skuggorna medan demonisk korrumpering från närbelägna Felwood hotar att tränga igenom berggrunden i högländerna."}},faq={{q="Vad är Cliffspring Falls?",a="Cliffspring Falls är ett stort vattenfall i östra Darkshore och bildar källflödet till Cliffspring River. Förr var det den främsta källan till färskvatten för skogen runtomkring.",al={"cliffspring falls","vad är cliffspring falls"}},{q="Varför är vattnet från vattenfallet korrumperat?",a="Man misstänker två mörka krafter: demonisk smitta som sipprar genom bergen från det korrumperade Felwood, och närvaron av Twilight's Hammers kultister och fientliga naga som lurar i grottorna där vattenfallet får sitt vatten.",al={"varför är vattnet smittat","korrumpering av cliffspring river","korrumperat vatten"}},{q="Vilka håller till i grottorna bakom vattenfallet?",a="Grottorna ovanför och bakom vattenfallet är fulla av fientliga naga som slingrar sig genom de översvämmade salarna, samt kultister som tillhör den apokalyptiska Twilight's Hammer.",al={"vilka finns i grottorna","fiender i cliffspring-grottan","vilka bor i cliffspring falls"}},{q="Varför är Cliffspring Falls så viktigt för Darkshore?",a="Cliffspring River skär genom norra Darkshore. Eftersom floden är den främsta källan till färskvatten hotar förgiftningen direkt djurlivet, uråldriga lundar och de lokala Night Elf-bosättningarna.",al={"varför bryr sig darkshore","cliffspring falls betydelse"}}},fx={b072a170={q="Vad hände med Cliffspring Falls?",a="Cliffspring Falls var en gång ett orört vattenfall i bergen som gav rent dricksvatten åt norra Darkshore. Efter förödelsen under det tredje kriget trängde mörka krafter in i vildmarken runt omkring. Grottan vid flodens källflöde korrumperades, så att det rena bergsvattnet blev förorenat och illvilliga väsen lockades till dess dolda djup.",al={"cliffspring falls historia","vad hände vid cliffspring falls","varför förändrades cliffspring falls"}},["894b4715"]={q="Är Cliffspring Falls farligt?",a="Vattenfallet och grottorna bakom det är ytterst farliga. Fientliga naga krälar genom vattenvägarna, medan fanatiska kultister från Twilight's Hammer lurar djupt inne i grottsystemet och utför fasansfulla ritualer. Utöver de livsfarliga invånarna utgör det förgiftade vattnet i sig en allvarlig fara för alla som vågar dricka det.",al={"fara vid cliffspring falls","är cliffspring falls tryggt","hot vid cliffspring falls"}}},fp="17,225,16.551.0,26.180.0,49.145.0,42.94.0,51.176.0"}
P.entries["subzone:clockwerk-run"] = {n="Clockwerk Run",s="Clockwerk Run är huvudkorridoren som leder in till hjärtat av det fallna Gnomeregan. Den sträcker sig mellan Train Depot och Hall of Gears och är svårt förorenad av giftigt nedfall och översvämmad av bestrålade troggs.",h="Clockwerk Run är huvudkorridoren som leder in till hjärtat av det fallna Gnomeregan.",kw={"clockwerk run","gnomeregan","hall of gears","bestrålade troggs","train depot","troggs"},ang={["profession:Engineering"]="Det förstörda maskineriet och den raserade infrastrukturen längs korridoren visar dystert vad som händer när gnomernas industriella mekanismer utsätts för katastrofala explosions- och strålningsskador.",["race:Gnome"]="Att ta sig genom Clockwerk Run påminner bittert om huvudstadens fall. Här ser du på nära håll hur det desperata försöket att rena staden muterade inkräktarna i stället för att förgöra dem."},sec={{t="En raserad tröskel",b="Clockwerk Run var en gång en livlig led för gnomernas logistik och transporter, och fungerade som huvudporten från den yttre tågdepån in i Gnomeregan. När High Tinker Mekkatorque beordrade att radioaktivt avfall skulle vädras ut för att hejda trogginvasionen blev korridoren en dödsfälla. Explosionen och de efterföljande striderna fick delar av korridoren att rasa in. I dag är passagen fylld av giftiga ångor och kringströvande bestrålade troggs. Den utgör frontlinjen som varje expedition måste kämpa sig igenom för att nå Hall of Gears övre delar."}},faq={{q="Vart leder Clockwerk Run?",a="Clockwerk Run förbinder Train Depot utanför de djupa valven direkt med de övre våningarna i Hall of Gears, inne i Gnomeregan.",al={"clockwerk run plats","vart leder korridoren","clockwerk run ingång"}},{q="Varför finns det så många troggs här?",a="De underjordiska troggarna svärmade upp genom Gnomeregans lägre passager under sin första invasion. De som strövar omkring i Clockwerk Run utsattes för stora mängder radioaktivt avfall som vädrats ut. Det muterade dem till våldsamma bestrålade troggs som angriper alla som försöker ta sig in i staden.",al={"varför troggs","clockwerk run fiender"}},{q="Varför har korridoren delvis rasat in?",a="De intensiva striderna under Gnomeregans fall och det katastrofala utsläppet av giftiga motåtgärder orsakade allvarliga strukturella skador längs hela stadens ytterområde. Korridoren rasade därför delvis in.",al={"clockwerk run rasat","varför är den trasig"}}},fx={["8c8c10db"]={q="Vad är Clockwerk Run?",a="Clockwerk Run är den stora ingångskorridoren som leder rakt ner i Gnomeregans djup. Den sträcker sig från det övre Train Depot mot Hall of Gears och var en gång en livligt trafikerad led som band samman gnomernas huvudstads yttre transportsystem med dess industriella hjärta. I dag är den en trasig och farlig port till den fallna staden.",al={"vad är clockwerk run","översikt över clockwerk run","vad är det här för område"}},["556e3735"]={q="Vad hände med Clockwerk Run?",a="När trogger vällde fram ur de djupa grottorna och översvämmade Gnomeregan släppte gnomerna ut giftig radioaktiv gas i ett desperat försök att utrota inkräktarna. Planen misslyckades katastrofalt: gnomerna tvingades fly eller gick under, korridoren rasade delvis samman i kaoset och bestrålade trogger tog själva passagen i besittning.",al={"clockwerk runs historia","vad hände vid clockwerk run","clockwerk runs fall"}},c5bdf1c1={q="Vem kontrollerar Clockwerk Run nu?",a="Ingen civiliserad makt kontrollerar längre passagen. Den är helt översvämmad av vilda trogger som muterades av det giftiga nedfall som släpptes ut under Gnomeregans fall. De angriper alla främlingar som vågar ta sig genom den förstörda passagen.",al={"vem bor i clockwerk run","vem kontrollerar clockwerk run","vem styr clockwerk run"}},aa198084={q="Är Clockwerk Run farligt?",a="Den är ytterst farlig. Fientliga, bestrålade trogger kryllar i passagen och har drivits till vansinne av kvarvarande radioaktivt nedfall, samtidigt som delar av taket och väggarna har rasat. Den som ger sig ner i korridoren måste vara beredd att kämpa sig igenom svärmar av muterade bestar bland instabila ruiner.",al={"är clockwerk run farligt","faror i clockwerk run","hot i clockwerk run"}}},fp="13,115,18.430.0,34.108.0,34.189.0,39.137.0"}
P.entries["subzone:cold-hearth-manor"] = {n="Cold Hearth Manor",s="Cold Hearth Manor är en härjad gård strax väster om Brill, längs huvudvägen genom Tirisfal Glades. Gården var en gång ett livligt och gästvänligt gods känt för sina rika skördar. Pesten av odöda utplånade invånarna och lämnade de omgivande fälten fulla av tanklösa Scourge. I dag har Forsaken säkrat huvudgården som utpost och rastställe för resande.",h="Cold Hearth Manor är en härjad gård strax väster om Brill, längs huvudvägen genom Tirisfal Glades.",kw={"brill","cold hearth manor","gård","forsaken","scourge","tirisfal glades","zombier"},ang={["faction:Horde"]="Godset ger en säker utsiktspunkt längs vägen mellan Brill och Tirisfals östra delar och erbjuder en trygg rastplats för resande genom det pestdrabbade landskapet.",["race:Undead"]="För Forsaken är återtagandet av platser som Cold Hearth Manor en bitter påminnelse om deras förlorade liv som dödliga. De gör om forna mänskliga tillflyktsorter till dystra försvarsposter mot både Scourge och Scarlet Crusade."},sec={{t="En kall härd",b="Före det tredje kriget var gården känd för sin värme och gästfrihet och gav rika skördar i hjärtat av Lordaeron. När pesten drog genom kungariket dukade hela familjen och deras arbetare under och reste sig på nytt som skal bundna till Scourge. Vilda odöda stapplar fortfarande genom de förfallna fälten, men Forsakens styrkor lyckades driva bort de tanklösa döda från huvudgården. De återtog byggnaden och gjorde den till handelsplats och fäste längs vägen mot de östra gläntorna."}},faq={{q="Vad hände med dem som bodde här?",a="Bönderna och arbetarna som skötte godset utplånades helt när Pesten svepte över Lordaeron. I stället för att finna frid i döden återuppväcktes de som tanklösa zombier som fortfarande hemsöker de omgivande fälten.",al={"vilka bodde på cold hearth","godsets bakgrund","vad hände med familjen"}},{q="Varför heter det Cold Hearth Manor?",a="Godset var ursprungligen känt för sin varma stämning och välkomnande eldar. Forsaken antog troligen det dystra namnet som en ironisk anspelning på dess forna liv och på hur kall, död och härjad gården har blivit.",al={"betydelsen av namnet cold hearth","varför cold hearth"}},{q="Vem kontrollerar godset just nu?",a="Forsaken har tagit kontroll över huvudgården och använder den som en trygg rastplats för resande och handelsmän längs vägen från Brill. De öppna fälten och ladorna runt godset är dock fortfarande fulla av fientliga Scourge.",al={"vem äger cold hearth manor","är cold hearth vänligt"}},{q="Varför rensar inte Forsaken fälten?",a="Forsaken i Tirisfal Glades är hårt ansatta och slåss mot rester av tanklösa Scourge samtidigt som de håller Scarlet Crusade på avstånd. Genom att säkra gården och huvudvägen får de omedelbar nytta av platsen, medan de utspridda döda på fälten får vara en plåga snarare än ett omedelbart hot mot Brill.",al={"varför finns det zombier på fälten","varför finns scourge här"}}},fx={["29a639a2"]={q="Vad är Cold Hearth Manor?",a="Cold Hearth Manor är en gård mitt i Tirisfal Glades, längs huvudvägen. Gården var en gång känd i hela Lordaeron för sina rika skördar och sin inbjudande atmosfär, men föll under det tredje kriget när de odödas pest svepte över landsbygden. I dag håller handelsmän från de Förfallna ett bräckligt fotfäste vid gården och handlar med resenärer medan de håller ett vakande öga på de fördärvade markerna runt omkring.",al={"vad är cold hearth manor","översikt över cold hearth manor","cold hearth manor i berättelsen"}},["673749f2"]={q="Vad hände vid Cold Hearth Manor?",a="Under det tredje kriget ödelade de odödas pest gården och dödade alla som bodde och arbetade på dess jord. Hjärnlösa zombier från Scourge reste sig ur de döda och strövar nu på de igenvuxna fälten. Efter Lorderaons fall återtog de Förfallna gården och gjorde den dystra lämningen av mänskligt jordbruksliv till en utpost längs vägen genom Tirisfal.",al={"cold hearth manors historia","vad hände här","cold hearth manors berättelse"}},["7e9cca93"]={q="Är Cold Hearth Manor farligt?",a="Själva gården erbjuder ett visst skydd tillsammans med de Förfallnas handelsmän, men fälten runt omkring är farliga. Hjärnlösa zombier från Scourge hemsöker fortfarande de karga markerna och angriper alla som viker av från vägen. Resenärer måste vara på sin vakt, för Scourge utgör ett ständigt hot precis utanför gårdens dörrar.",al={"fara vid cold hearth manor","är det tryggt här","hot vid cold hearth manor"}}},fp="17,183,16.529.0,43.178.0,35.176.0,33.163.0,44.274.0"}
P.entries["subzone:coldridge-pass"] = {n="Coldridge Pass",s="Coldridge Pass är en karg, snötäckt tunnel genom den södra bergsryggen i Dun Morogh. Den är den enda vägen över land från den avskilda träningsplatsen Coldridge Valley till resten av kungariket och mynnar ut nära den livliga staden Kharanos. Fientliga troggs har tagit över passagen, så den som försöker ta sig igenom måste slåss sig fram eller desperat rusa till andra sidan.",h="Coldridge Pass är en karg, snötäckt tunnel genom den södra bergsryggen i Dun Morogh.",kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","kharanos","bergspass","trogg","tunnel"},ang={["race:Dwarf"]="För dvärgarnas bergsvakter och rekryter innebär färden genom Coldridge Pass att du lämnar nybörjarträningen i Anvilmar och går i aktiv tjänst i Ironforges länder.",["race:Gnome"]="Gnomer i exil som vill hjälpa Alliansen måste kämpa sig igenom denna troggfyllda flaskhals för att nå Kharanos och den större vägen mot Ironforge."},sec={{t="Vägen ut ur dalen",b="För unga dvärgrekryter och gnomnoviser som tar sina första steg utanför Coldridge Valley är Coldridge Pass en hård prövning. Tunneln är uthuggen direkt ur berget och utgör den främsta förbindelsen österut till gränsutposten Kharanos för nyutbildade äventyrare. Den säkra bergskorridor som en gång var har blivit en farlig flaskhals, full av aggressiva troggs som tagit sig upp från mörka underjordiska gångar och hotar alla som färdas mellan den skyddade dalen och Dun Moroghs vidsträckta trakter."}},faq={{q="Vart leder Coldridge Pass?",a="Passet förbinder Coldridge Valley i sydväst med det större området Dun Morogh och mynnar ut i de snötäckta kullarna strax väster om staden Kharanos.",al={"vart leder coldridge pass","coldridge pass resmål","hur lämnar man coldridge valley"}},{q="Varför finns det troggs i Coldridge Pass?",a="Troggs har nyligen strömmat fram ur de djupa underjordiska sprickorna under Dun Morogh och tagit över mörka grottor och tunnlar i hela området. Coldridge Pass gav dem skydd och en bra plats att överfalla resande i bergen.",al={"varför finns troggs här","monster i coldridge pass","trogginvasion"}},{q="Är det säkert att färdas genom Coldridge Pass?",a="Nej, det är inte säkert. Tunneln vimlar av fientliga troggs, så rekryter och resande måste slå sig igenom bestarna eller rusa genom mörkret till andra änden.",al={"är coldridge pass farligt","kan jag gå genom coldridge pass"}},{q="Vem vaktar eller underhåller passet?",a="Bergsvakter bevakar dalen och vägens utgångar, men tunneln är fortfarande omstridd och har inte rensats. Därför måste resande försvara sig själva när de tar sig igenom.",al={"dvärgvakter vid coldridge pass","vem kontrollerar passet"}}},fx={["7f71f8e0"]={q="Vad är Coldridge Pass historia?",a="Coldridge Pass höggs ut genom bergen i Dun Morogh och blev den viktigaste livlinan mellan Coldridge Valleys avskilda övningsmarker och den större världen samt gränsstaden Kharanos. I generationer färdades dvärgaspiranter och bergsklättrare fritt genom korridoren mellan dalen och resten av kungariket. Men nyligen dök fientliga trogger upp i tunneln och störde friden, så resenärer tvingas nu kämpa sig igenom det som en gång var en trygg färdväg.",al={"coldridge pass historia","vad hände vid coldridge pass","bakgrund om coldridge pass"}}},fp="14,440,29.541.0,31.157.0,39.231.0,41.190.0,33.179.0"}
P.entries["subzone:coldridge-valley"] = {n="Coldridge Valley",s="Coldridge Valley är en skyddad, snötäckt dal i de sydvästra höjderna av Dun Morogh. Med Anvilmar i centrum är dalen en övningsplats där unga dvärgar och gnomiska flyktingar först tar till vapen i Ironforges tjänst. En enda tunnel, Coldridge Pass, förbinder denna avskilda dal med det större bergsriket.",h="Coldridge Valley är en skyddad, snötäckt dal i de sydvästra höjderna av Dun Morogh.",kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","frostmane","ironforge","startområde","troggar"},ang={["race:Dwarf"]="Som traditionell startplats för Bronzebeard-bergfarare och präster är dalen en dvärgs första steg bort från härden och in i High Seats tjänst.",["race:Gnome"]="För gnomiska landsflyktingar som tvingats bort från Gnomeregan erbjuder Coldridge Valleys snömarker en trygg tillflykt där de kan bemästra sina besvärjelser och sin mekanik sida vid sida med sina dvärgvärdar."},sec={{t="En avskild övningsplats",b="Coldridge Valley ligger inbäddad bland branta bergsklippor och är till stor del avskuren från Dun Moroghs livliga handelsvägar. I dalens hjärta ligger Anvilmar, en bastant stenhall och by där erfarna dvärginstruktörer och fördrivna gnomiska lärda tränar nya rekryter i stridskonst, smygande och trolldom. Utanför värmen från Anvilmars härdar ligger ett tjockt snötäcke över dalbottnen, där vildsvin och hungriga vintervargar strövar omkring och ger nybörjarna deras första riktiga smak av att överleva i vildmarken."},{t="Fiender rycker närmare",b="Trots sin isolering hotas Coldridge Valley omedelbart av två ihärdiga fiender. De inhemska Frostmane-trollen har slagit läger på platser som Frostmane Hovel, där de strider mot bergsfarare och försvarar sina förfäders marker mot dvärgarnas intrång. Än värre är att de vilda Rockjaw-troggarna har tagit över Coldridge Pass, den naturliga tunnel som förbinder dalen med Kharanos. Så länge dessa underjordiska bestar inte drivs tillbaka kan resenärer och förnödenheter inte färdas fritt mellan dalen och Ironforges höga säte."}},faq={{q="Hur tar du dig ut ur Coldridge Valley?",a="Den enda landvägen ut ur dalen går genom Coldridge Pass, en snöig tunnel som skär nordost genom bergsryggen. När du kommit igenom passet går vägen österut direkt mot staden Kharanos och vidare till Ironforges mäktiga portar.",al={"ut ur coldridge","hur man tar sig ut","vägen till kharanos"}},{q="Varför börjar gnomer här tillsammans med dvärgar?",a="Efter Gnomeregans tragiska fall för troggar och radioaktivt nedfall flydde de överlevande gnomerna som flyktingar till Dun Morogh. High Tinker Mekkatorques folk välkomnades av King Magni Bronzebeard, och många gnomiska lärlingar i exil började därför träna sida vid sida med unga dvärgar i Anvilmar.",al={"gnomer i coldridge","varför är gnomer här","gnomernas startområde"}},{q="Vilka hot plågar dalen?",a="Dalen står inför två stora hot: de fientliga Frostmane-trollen, som ogillar dvärgarnas bosättningar på deras bergsterritorium, och de råbarkade Rockjaw-troggarna, som klöst sig upp ur jordens djup för att blockera Coldridge Pass. Lokala rovdjur som vargar och vildsvin ger sig också på oförsiktiga resenärer.",al={"coldridges fiender","hot i dalen","vem anfaller"}},{q="Vad är Anvilmar?",a="Anvilmar är den centrala fästningsgården och bosättningen i Coldridge Valley. Där finns klassinstruktörer, smedmästare och lokala bergsfarare som samordnar dalens försvar och förbereder nyblivna äventyrare för den större världen.",al={"staden anvilmar","vad är det här för stad"}}},fx={["80e4cacf"]={q="Vad är Coldridge Valley?",a="Coldridge Valley är en skyddad, snötäckt sänka i Dun Moroghs sydvästra hörn. Den omges av taggiga bergstoppar och fungerar som en avskild övningsplats och samlingsläger för unga dvärgar och gnomiska flyktingar innan de ger sig ut i det större kungariket.",al={"översikt över coldridge valley","var ligger coldridge valley","information om coldridge"}},["73aec6cd"]={q="Är Coldridge Valley en del av Dun Morogh?",a="Ja, dalen ligger i Dun Moroghs sydvästra högland. Den är fortfarande fysiskt avskild från resten av den snötäckta regionen av en bergskedja och har bara en förbindelse med fastlandet: den smala tunneln Coldridge Pass i nordost.",al={"ingår coldridge i dun morogh","dun morogh coldridge valley"}},["0ba4a80e"]={q="Är Coldridge Valley farligt?",a="Dalen är tänkt att vara en lugn, skyddad övningsplats, men oroligheter har nyligen spridit sig dit. Fientliga Frostmane-troll lurar i läger i närheten, aggressiva vilddjur stryker omkring i snödrivorna och våldsamma trogger har tagit över det enda bergspasset ut till resten av Dun Morogh.",al={"fara i coldridge","är det tryggt här","hot i coldridge"}},["7fc500c6"]={q="Vem styr dvärgarna?",a="Dvärgarna i Ironforge styrs av King Magni Bronzebeard. King Magni är en orubblig ledare och veteran från de stora krigen. Han styr kungariket Ironforge från sitt mäktiga tronrum i berget och är en av alliansens mest beslutsamma förkämpar.",al={"vem är dvärgarnas kung","kung av ironforge","dvärgarnas ledare"}},ff57e405={q="Vad finns i Kharanos och varför pratar alla om staden?",a="Kharanos är en livlig gränsstad strax bortom Coldridge Pass, längs huvudvägen till Ironforge. Den är den främsta utposten där unga rekryter anmäler sig till aktiv tjänst, får hantverksutbildning och provar världsberömt öl på Thunderbrew Distillery.",al={"vad är kharanos","varför bege sig till kharanos","staden kharanos"}},["966deec9"]={q="Vem är Senir Whitebeard?",a="Senir Whitebeard är en framstående dvärgledare stationerad i den närliggande gränsstaden Kharanos. Han samordnar försvaret av regionen och arbetar aktivt för att utrota det farliga fäste som Frostmanes istroll har skapat bland Dun Moroghs bergstoppar.",al={"senir whitebeard","senir i kharanos"}},a3c72edd={q="Hur hamnade jag i Coldridge Valley?",a="Du kom till Coldridge Valley eftersom dalen är en skyddad övningsplats för nya rekryter i Dun Morogh. Djupt inne i de sydvästra bergen erbjuder dalen blivande försvarare en avskild plats där de kan lära sig sitt yrke, samla utrustning och visa sitt mod innan de ger sig ut i den större och farligare världen bortom.",al={"hur hamnade jag här","varför är jag här","hur kom jag hit","vad förde mig hit"}},["8bdf0a70"]={q="Vad förväntas jag göra i Coldridge Valley?",a="Din uppgift är att genomgå grundutbildning, vässa dina stridskunskaper och hjälpa de lokala myndigheterna vid Anvilmar. Du förväntas hålla den bångstyriga vilda faunan i schack, slå tillbaka Frostmane-troll och troggar som tränger sig på och till sist röja en väg genom Coldridge Pass för att anmäla dig till tjänst i Kharanos.",al={"vad gör jag här","vad är mitt uppdrag","vad ska jag göra i coldridge"}},["2eeaa2be"]={q="Varför börjar en ny dvärg här i Coldridge Valley?",a="Som ung dvärgäventyrare har du kommit till Anvilmar för att bemästra dina stridskonster och magiska traditioner under erfarna lärare. Ironforge behöver ståndaktiga hjältar som kan försvara riket, och denna bergsvagga är den perfekta prövningsplatsen för att göra nya rekryter till erfarna försvarare av Khaz Modan.",al={"varför börjar dvärgar här","varför är jag här som dvärg","startområde för dvärgar","varför coldridge valley för dvärgar"}},ef9153cd={q="Varför börjar en ny gnom här i Coldridge Valley?",a="Efter att Gnomeregan nyligen föll för troggarnas invasion flydde de överlevande gnomerna från sitt hem och fann skydd hos sina dvärgallierade. Som en landsförvisad gnom som vill hjälpa Alliansen och återuppbygga ditt folks framtid börjar du din utbildning tillsammans med dvärgrekryter i tryggheten i Coldridge Valley.",al={"varför börjar gnomer här","varför är jag här som gnom","startområde för gnomer","varför coldridge valley för gnomer"}}},fp="16,264,25.331.0,16.327.0,34.199.0,47.257.0,38.286.0,17.241.0"}
P.entries["subzone:command-center"] = {n="Command Center",s="I Stormwinds Old Town tränar Command Center rekryter medan större delen av armén tjänstgör utomlands. Det kallas också Stormwind Barracks och hyser stadens officerare och en erfaren kärntrupp som drillar rekryter och den lokala milisen.",h="I Stormwinds Old Town tränar Command Center rekryter medan större delen av armén tjänstgör utomlands.",kw={"ander germaine","kaserner","command center","old town","stormwind barracks","krigartränare","wu shen"},ang={["class:Warrior"]="Som krigare kan du träna vid Stormwinds Command Center, där veteraner som Ander Germaine och Wu Shen lär rekryter att slåss som disciplinerade frontsoldater."},sec={{t="Ett tunt försvar",b="I Old Town är Stormwinds Command Center en garnison och övningsplats för kungarikets soldater. Det är tystare än vanligt i salarna, eftersom större delen av den kungliga armén deltar i fälttåg utomlands. Erfarna instruktörer, däribland Ander Germaine och kampsportaren Wu Shen, tränar nya krigare för att stärka stadens försvar."},{t="Old Towns kampcentrum",b="När du frågar efter instruktioner i tunga vapen eller taktisk strid kan Stormwinds vakter hänvisa dig till Barracks. Byggnaden ligger nära Pig and Whistle Tavern och de skuggiga verksamheterna på andra håll i Old Town. Den bidrar till att upprätthålla ordningen i ett distrikt känt för krogslagsmål och skurkaktig verksamhet."}},faq={{q="Varför är Command Center så tomt?",a="Större delen av Stormwinds stående armé har skickats till avlägsna utposter och slagfält runtom i världen. En erfaren kärntrupp stannar kvar för att undervisa rekryter och organisera det lokala försvaret.",al={"varför så få vakter här","var finns stormwinds armé","tomma kaserner"}},{q="Är Command Center samma plats som Stormwind Barracks?",a="Ja. Byggnaden heter officiellt Command Center, men stadsvakter och lokalbor kallar den ofta Stormwind Barracks när de visar vägen.",al={"stormwind barracks","är command center och barracks samma plats","kasernernas läge"}},{q="Vem leder träningen här?",a="Ander Germaine samordnar och tränar Stormwinds krigare tillsammans med instruktörer som Wu Shen och Ilsa Corbin.",al={"vem tränar krigare här","krigartränare command center","vem leder kasernerna"}},{q="Var ligger Command Center?",a="Du hittar Command Center i Old Town, nära Pig and Whistle Tavern och distriktets träningsanläggningar.",al={"var ligger command center","command centers läge","hur hittar jag command center"}}},fx={["3e3491ec"]={q="Vad är Command Center?",a="Command Center är Stormwinds militära högkvarter och kasern för utbildning. Det ligger i Old Town och är den främsta samlingsplatsen där arméofficerare och krigarlärare tränar rekryter och samordnar kungarikets försvar.",al={"vad är command center","command center i stormwind","vad är det här för byggnad"}},["1a0e6604"]={q="Är Command Center farligt?",a="Inte alls. Command Center är en befäst borg som ligger tryggt i hjärtat av Stormwind City. Den bemannas av erfarna veteraner och elitinstruktörer i strid som är lojala mot Alliansen, vilket gör den till en av huvudstadens säkraste anläggningar.",al={"är command center farligt","fara vid command center","är det tryggt"}}},fp="14,224,22.264.0,22.284.0,35.179.0,57.145.0,28.114.0,36.112.0"}
P.entries["subzone:commons"] = {n="Commons",s="Commons är Ironforges livliga kommersiella hjärta och förbinder stadens ingång direkt med dess vidsträckta grottor. Här myllrar det av köpmän, resenärer och bankirer. Det är den mest trafikerade genomfartsleden i dvärgarnas huvudstad och hela Alliansens centrala marknadsplats.",h="Commons är Ironforges livliga kommersiella hjärta och förbinder stadens ingång direkt med dess vidsträckta...",kw={"auktionshus","bank","commons","ironforge","marknad","stonefire tavern","vault of ironforge"},ang={["faction:Alliance"]="Commons fungerar i praktiken som Alliansens handelsplats och lockar hjältar från Teldrassil, Stormwind och Gnomeregan som vill auktionera ut värdefulla byten och fylla på sina förråd.",["race:Dwarf"]="För Bronzebeard-dvärgarna är Commons en källa till stolthet. Här bevisas det att dvärgarnas gästfrihet, flit och handel kan blomstra djupt inne i ett fruset berg."},sec={{t="Bergens kommersiella knutpunkt",b="Commons ligger strax nordost om Gates of Ironforge och är det första distrikt som möter resenärer när de kommer in i bergariket. Den livliga marknadsgatan är uthuggen direkt ur stenen och rymmer Alliansens främsta auktionshus, Stonefire Tavern och stadens centralbank i Vault of Ironforge. Breda avenyer förbinder den smidigt med Great Forge, Mystic Ward och Military Ward, så nästan all trafik till fots genom berget passerar de livliga butiksfasaderna."},{t="En knutpunkt för Alliansen",b="Tack vare Ironforges centrala läge på kontinenten Eastern Kingdoms och dess direkta underjordiska förbindelse med Deeprun Tram till Stormwind fungerar Commons som Alliansens främsta handelscentrum. Äventyrare samlas här för att handla med varor från Azeroths alla hörn, köpa vapen hos Steelfury's Weapon Emporium och reagenser av Barim eller träffas under värdshusets varma lyktor innan de ger sig ut i Khaz Modans snölandskap."}},faq={{q="Varför är Commons så trångt jämfört med andra distrikt?",a="I Commons finns Alliansens främsta auktionshus, stadens huvudbank i Vault of Ironforge och det livliga Stonefire Tavern. Läget alldeles innanför huvudportarna gör det till den bekvämaste mötes- och handelsplatsen i hela riket.",al={"varför är commons så livligt","varför är så många spelare här","ironforges handelscentrum"}},{q="Vart leder Commons?",a="Commons förbinder nästan alla större distrikt i Ironforge. Går du sydväst kommer du tillbaka till stadsportarna, nordost leder till Great Forge, österut går en väg mot Military Ward och norrut kommer du till Mystic Ward.",al={"utgångar från commons","hur lämnar man commons","vägbeskrivning från commons"}},{q="Vilka viktiga butiker och tjänster finns här?",a="Förutom auktionshuset och banken finns Ironforge Visitor's Center, Steelfury's Weapon Emporium, Ironforge Armory, Barim's Reagents och Fizzlespinner's General Goods i Commons.",al={"försäljare i commons","tjänster i commons","bekvämligheter i ironforge commons"}},{q="Ligger banken här?",a="Ja. Vault of Ironforge ligger mitt emot auktionshuset i Commons och fungerar som stadens huvudbank.",al={"var ligger ironforges bank","ironforge vault","bankens läge"}}},fx={["1b528195"]={q="Vad är Commons?",a="Commons är Ironforges främsta handelsstråk. Det ligger strax innanför stadsportarna och förbinder nästan alla andra stadsdelar, och fungerar som dvärghuvudstadens livliga ekonomiska hjärta. Här samlas resenärer och invånare för att handla på auktionshuset, besöka stadens valv, bo på Stonefire Tavern eller se vad de lokala köpmännen har att erbjuda.",al={"vad är commons","commons i ironforge","om commons"}},e4c18740={q="Är Commons farligt?",a="Inte det minsta. Commons är en av de tryggaste och mest tätbefolkade stadsdelarna i hela Khaz Modan. Bergets ogenomträngliga stenväggar skyddar området, och vaksamma vakter från Ironforge patrullerar det ständigt. Besökare behöver därför inte frukta vilda djur eller fiendeangrepp medan de uträttar sina ärenden här.",al={"är commons farligt","fara i commons","är det tryggt här"}}},fp="7,203,34.338.0,29.400.0,62.180.0,28.171.0,43.190.0,25.103.0"}
P.entries["subzone:corin-s-crossing"] = {n="Corin's Crossing",s="Corin's Crossing är en förstörd mänsklig bosättning vid en viktig vägkorsning i södra centrala Eastern Plaguelands. Orten var en gång en blomstrande rastplats mellan Stratholme, Tyr's Hand, Darrowshire och Andorhal, men nu har Scourge tagit över den helt. I det förfallna rådhuset och smedjan dröjer fasor kvar, däribland osynliga spektrala väktare.",h="Corin's Crossing är en förstörd mänsklig bosättning vid en viktig vägkorsning i södra centrala Eastern...",kw={"corin's crossing","eastern plaguelands","the infectis scar","unseen servants","osynliga tjänare"},ang={["class:Paladin"]="Ruinerna av Corin's Crossing vittnar om den totala skändningen av Lordaerons hjärtland. De står kvar som ett eländigt fäste för Scourge, en hånfull spegelbild av Stratholmes heliga bastion längre upp längs vägen.",["class:Rogue"]="Lita inte på dina skuggor här. Unseen Servants strövar omkring i gränderna, osynliga för dödliga ögon, och ser rakt igenom din smygförmåga. En lugn promenad genom stadstorget kan bli din död."},sec={{t="En krossad vägkorsning",b="Före det tredje kriget var Corin's Crossing en central knutpunkt för resor genom östra Lordaeron. Orten låg mellan Lake Mereldars skimrande vatten och den sargade ravin som nu kallas The Infectis Scar. Längs vägarna färdades en gång handelsmän, kurirer och pilgrimer mellan Stratholmes mäktiga fäste och de södra bastionerna. När pesten svepte genom provinsen hamnade bosättningen mitt i förödelsens väg och föll snabbt under den stora vågen av odöda."},{t="En fristad för de fördömda",b="I dag är Corin's Crossing helt förlorat till Scourge. Vandrande odöda fyller de leriga gatorna, medan ruttnande bjässar och gastar dröjer sig kvar i den urholkade smedjan och rådhuset. Staden är särskilt förrädisk för spejare: spektrala Unseen Servants svävar bland ruinerna, helt osynliga för vanliga ögon. De genomskådar vanlig smygförmåga och överfaller alla som försöker ta sig förbi den stora horden obemärkt."}},faq={{q="Vad var Corin's Crossing före pesten?",a="Det var en välmående knutpunkt i östra Lordaeron. Staden kretsade kring ett rådhus och en smedja och tog emot resande mellan Stratholme, Tyr's Hand, Darrowshire och Andorhal innan Scourge utplånade dess invånare.",al={"corin's crossings historia","corin's crossings bakgrund","vad var corin's crossing"}},{q="Varför är Corin's Crossing så farligt för resande som smyger?",a="Staden hemsöks av Unseen Servants, osynliga gastar bundna till Scourge. Dessa vålnader genomskådar utan ansträngning både magisk och vanlig smygförmåga. De överraskar oförsiktiga skurkar och spejare och larmar närliggande odöda.",al={"smyga i corin's crossing","unseen servants","skurk i corin's crossing"}},{q="Vilka viktiga landmärken omger staden?",a="Corin's Crossing ligger mitt i södra delen av Eastern Plaguelands. Den sargade ravinen The Infectis Scar ligger alldeles intill, och Lake Mereldar löper längs dess gräns.",al={"corin's crossings läge","var ligger corin's crossing"}},{q="Vem kontrollerar Corin's Crossing i dag?",a="Scourge har full kontroll över ruinerna. Inga levande försvarare finns kvar i staden, och hela bosättningen vimlar av vandrande odöda soldater och andar.",al={"vem äger corin's crossing","corin's crossings fraktion"}}},fp="16,314,22.409.0,21.342.0,44.241.0,60.186.0,39.163.0,36.127.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="Corrahn's Dagger",s="Corrahn's Dagger är den andra av fyra bergiga utlöpare som reser sig över norra Hillsbrad Foothills. Den höga terrängen fungerar som gömställe för avfälliga agenter från Syndicate.",h="Corrahn's Dagger är den andra av fyra bergiga utlöpare som reser sig över norra Hillsbrad Foothills.",kw={"corrahn","corrahn's dagger","dolk","fyra fingrar","hillsbrad","syndicate"},ang={["race:Dwarf"]="Ryggen är ett gömställe för Syndicate, så dvärgiska resenärer som korsar de norra kullarna bör vänta sig banditer snarare än allierade.",["race:Undead"]="Stråtrövarna från Syndicate på ryggen är fientliga mot Forsaken som verkar i Hillsbrad."},sec={{t="En nordlig utpost",b="Corrahn's Dagger reser sig brant i norra Hillsbrad Foothills och är den andra av de fyra klippiga utlöpare som lokalt kallas Hillsbrads fingrar. Ryggen kryllar av stråtrövare från Syndicate, som använder den höga utsiktspunkten för att hålla uppsikt över dalen nedanför."}},faq={{q="Vem kontrollerar Corrahn's Dagger?",a="Ryggen hålls av avfälliga människor från Syndicate, som använder höjderna som gömställe.",al={"vem finns vid corrahn's dagger","corrahn's dagger-fraktion","vem bor här"}},{q="Vad är Hillsbrads fingrar?",a="Hillsbrads fingrar är fyra framträdande, fingerlika bergsryggar som skjuter söderut från den norra bergskedjan in i Hillsbrad-dalen. Corrahn's Dagger är den andra av dessa formationer.",al={"fyra fingrar hillsbrad","fyra bergsryggar hillsbrad","hillsbrads fingrar"}}},fx={["2610a3ae"]={q="Vad är Corrahn's Dagger?",a="Corrahn's Dagger är den andra av de fyra framträdande bergsryggarna som kallas Hillsbrads fingrar. Den reser sig längs den norra kanten av bergsfoten. Människor från Syndicate håller höjderna som ett gömställe med utsikt över dalen nedanför.",al={"vad är corrahns dagger","corrahns daggers bakgrund","corrahn dagger-berget"}},dcd9fc97={q="Är Corrahn's Dagger farligt?",a="Ja. Bergsryggen hålls av lönnmördare från Syndicate, som använder höjderna som gömställe. De angriper resenärer från både Alliansen och Horden som kommer för nära.",al={"är corrahns dagger tryggt","fara vid corrahns dagger","fiender vid corrahns dagger"}}},fp="16,167,22.207.0,30.85.0,34.163.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="Craftsmen's Terrace",s="Craftsmen's Terrace är det livliga hantverksdistriktet i den norra delen av Darnassus. Det är nattalvshuvudstadens främsta handels- och tillverkningscentrum, med verkstäder, yrkesinstruktörer och ett livligt värdshus. Här finns också representanter utifrån, däribland en ambassad för neutrala Argent Dawn.",h="Craftsmen's Terrace är det livliga hantverksdistriktet i den norra delen av Darnassus.",kw={"argent dawn","hantverkare","craftsmen's terrace","darnassus","teldrassil","instruktörer","tränare"},ang={["faction:Alliance"]="Besökare från Alliansen upplever Craftsmen's Terrace som ett av Darnassus mest välkomnande områden. Där finns välbekanta handelsvaror, skråadministration och logi, sida vid sida med utländska representanter.",["race:NightElf"]="För kaldoreierna visar terrassen hur deras samhälle klarar sig självt på Teldrassil och förenar urgammalt hantverk med vardagslivets behov i den nya huvudstaden."},sec={{t="Darnassus hantverkshjärta",b="Craftsmen's Terrace sträcker sig längs den norra kanten av staden under trädkronorna och samlar de olika yrken som håller Darnassus igång. Träsnidare, läderhantverkare, alkemister och andra hantverkare driver sina verkstäder här och förenar klassiska nattalvsmetoder med praktiskt hantverk. Distriktet erbjuder också viktiga bekvämligheter, däribland ett värdshus, en skråmästare och skrågillesombud. Broar förbinder terrassen direkt med Cenarion Enclave i väster och Warrior's Terrace i söder."},{t="Utländska band och bortglömd kunskap",b="Trots kaldoreiernas historiska isolering har Craftsmen's Terrace band till omvärlden. Mest framträdande är en ambassad som Argent Dawn upprättat för att samordna sig med nordliga allierade i kampen mot Scourge. Den som besöker distriktets olika verkstäder kan också snubbla över utspridda lärda skrifter, från historiska skildringar av War of the Ancients till krönikor om Second War och esoteriska avhandlingar om Old Gods."}},faq={{q="Vilka tjänster finns på Craftsmen's Terrace?",a="Distriktet rymmer de flesta av stadens yrkesinstruktörer för hantverksyrken, handlare med hantverksmaterial, ett värdshus och tjänster för skråregistrering. Det är handelscentrum för resenärer som vill lära sig eller utöva praktiska färdigheter i Darnassus.",al={"tjänster på craftsmen's terrace","vad finns på craftsmen's terrace","instruktörer i darnassus"}},{q="Varför finns Argent Dawn på Craftsmen's Terrace?",a="Argent Dawn har en ambassad i distriktet för att samarbeta med nattalverna och rekrytera hjälp mot Scourge. Deras närvaro skapar en diplomatisk förbindelse mellan Alliansens styrkor i väster och Lordaerons krigshärjade länder.",al={"argent dawn i darnassus","argent dawns ambassad","varför argent dawn här"}},{q="Hur tar du dig till Craftsmen's Terrace?",a="Terrassen ligger i den norra delen av Darnassus. Du kan nå den via broar som leder norrut från Warrior's Terrace eller österut från Cenarion Enclave.",al={"hur tar man sig till craftsmen's terrace","craftsmen's terrace läge","hitta craftsmen's terrace"}},{q="Vilka märkliga böcker finns nära verkstäderna?",a="Lärda skrifter finns utspridda i verkstäderna. Däribland finns historiska skildringar av War of the Ancients, följderna av Second War och en studie om Old Gods i Argent Dawns lokaler.",al={"böcker på craftsmen's terrace","loreböcker i darnassus"}}},fx={["7384ca35"]={q="Vad är Craftsmen's Terrace?",a="Craftsmen's Terrace är en livlig stadsdel i norra Darnassus, nattalvernas huvudstad på Teldrassil. Den är Kaldoreis främsta handels- och hantverkscentrum, där lärare, köpmän och verkstäder samlas under Världsträdets grenar. Här hittar resenärer och invånare skickliga hantverkare, skråtjänster, ett välkomnande värdshus och en officiell ambassad som drivs av Argent Dawn.",al={"vad är craftsmens terrace","craftsmen terrace i darnassus","om craftsmens terrace"}},ef9e89a7={q="Varför kallas det Craftsmen's Terrace?",a="Stadsdelen har fått sitt namn efter sin roll som centrum för industri och handel i Darnassus. Här finns stadens yrkeslärare, försäljare av förnödenheter och hantverksverkstäder, vilket gör den till en samlingsplats för nattalvernas hantverkare, byggmästare och yrkesfolk.",al={"varför heter det craftsmens terrace","betydelsen av craftsmen terrace","namnet craftsmen terrace"}},["1dc55189"]={q="Är Craftsmen's Terrace farligt?",a="Nej. Craftsmen's Terrace är en trygg stadsdel för civila i nattalvernas huvudstad Darnassus. Sentinels skyddar området, och lokala hantverkare och Argent Dawn håller uppsikt. Det är helt fridfullt och fritt från fientliga hot för Alliansens medlemmar.",al={"är craftsmens terrace tryggt","fara vid craftsmens terrace","hot vid craftsmens terrace"}}},fp="19,158,30.353.0,31.283.0,51.198.0,58.205.0,41.141.0,53.184.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Crag of the Everliving",s="Crag of the Everliving är en grönskande grottsal djupt inne i Wailing Caverns. Den domineras av frodig, förvriden växtlighet och rovlystna växtvarelser och är Fanglord Lord Pythas domän. I de höga övre delarna vilar den uråldriga varelse som gett klippan dess namn.",h="Crag of the Everliving är en grönskande grottsal djupt inne i Wailing Caverns.",kw={"the barrens","crag of the everliving","deviate shamblers","druids of the fang","lord pythas","lord serpentis","verdan","wailing caverns"},ang={["class:Druid"]="Att se Crag of the Everliving är en sorglig lärdom för Cenarion-druider: naturens rena livskraft och elementära väktarskap har förvridits till Mardrömmens dödliga redskap.",["profession:Herbalism"]="Klippans onaturligt frodiga, underjordiska miljö ger näring åt sällsynta rötter och svampar som frodas i den fuktiga, drömmättade jorden."},sec={{t="Ett förvridet växttak",b="Medan stora delar av Wailing Caverns består av fuktig underjordisk sten, svämmar Crag of the Everliving över av vild, förvriden växtlighet som får näring av Mardrömmen som fördärvar Naralex sömn. Höga, mossiga avsatser och slingrande stigar är övervuxna av Deviate Shamblers, levande växtkolosser som stryker omkring i snåren. Lord Pythas, en av Naralex fallna lärjungar, vakar över klippans centrala delar efter att ha bytt sina ädla druidlöften mot Druids of the Fangs giftiga riter."},{t="Den uråldriga väktaren",b="Salen har fått sitt namn efter Verdan the Everliving, en väldig, uråldrig växtandelemental som bor högt uppe i klippan. Emerald Nightmare har fördärvat Verdan och greppet om grottan, så nu är han en fruktansvärd försvarslinje i stället för en fridfull naturväktare. Bortom hans väldiga gestalt lurar Lord Serpentis, självutnämnd ledare för Fanglords, som övervakar sektens fall i ormlik galenskap."}},faq={{q="Varifrån kommer områdets namn?",a="Salen är uppkallad efter Verdan the Everliving, ett uråldrigt och väldig växtbest som bor på klippans högsta terrasser. Han var en gång naturens eviga livskraft förkroppsligad, men har fallit under Mardrömmens inflytande och den plåga den sprider i grottorna.",al={"varför crag of the everliving","ursprunget till everliving-namnet","klippans namn"}},{q="Vem styr den här delen av grottorna?",a="Lord Pythas, en av de främsta Fanglords, styr direkt över klippan. På de högre avsatserna ovanför honom lurar både Verdan the Everliving och Lord Serpentis, ledaren för Druids of the Fang.",al={"vem styr här","klippans boss","fanglord här"}},{q="Vilka varelser finns ofta i Crag of the Everliving?",a="Klippan är översvämmad av Deviate Shamblers, vandrande växtfasor som fötts ur de fördärvade källorna, samt förvridna ormar och fanatiska Druids of the Fang.",al={"monster i klippan","fiender i klippan","vad lever här"}},{q="Varför frodas växtlivet så djupt under marken?",a="Nattalvdruiden Naralex tog de underjordiska källorna i bruk för att återuppliva The Barrens. När Mardrömmen snärjde hans ritual löpte den vilda växtligheten amok och förvandlades till fientlig, vanställd flora.",al={"varför finns växter under marken","varför så grönt","fördärvad grönska"}}},fx={["6a6b08ee"]={q="Vad är Crag of the Everliving?",a="Crag of the Everliving är en frodig, grönskande underjordisk grotta djupt inne i Wailing Caverns. Den får näring från förvrängda naturkrafter och kännetecknas av ett rikt växtliv, hejdlös tillväxt och höga klipphyllor.",al={"vad är crag of the everliving","information om crag of the everliving","om crag of the everliving"}},cca8a755={q="Är Crag of the Everliving farligt?",a="Ja, det är en av grottornas dödligaste delar. Deviate Shamblers smyger omkring på de igenväxta terrasserna, och klippan försvaras av förvrängda druider från Fang. Lord Pythas styr dem, och Lord Serpentis lya ligger i närheten.",al={"hur farligt är crag of the everliving","är crag of the everliving farligt","hot i crag of the everliving"}}},fp="22,181,18.373.0,20.419.0,34.208.0,38.143.0,64.161.0,47.205.0"}
P.entries["subzone:cragpool-lake"] = {n="Cragpool Lake",s="Cragpool Lake är en sjö inne i Windshear Crag i Stonetalon Mountains. Ovanför det mörka vattnet reser sig en massiv träkonstruktion som Venture Company har byggt.",h="Cragpool Lake är en sjö inne i Windshear Crag i Stonetalon Mountains.",kw={"cragpool lake","gerenzo wrenchwhistle","stonetalon","venture company","windshear crag"},ang={["class:Druid"]="Avrinningen, träplattformarna och störningarna kring Cragpool Lake utgör ett fult sår i Stonetalon, som förvrider det lokala ekosystemet och tränger undan områdets inhemska djurliv.",["profession:Engineering"]="Den höga träställningen och de utskjutande maskinerna ovanför Cragpool Lake visar goblinernas industriella pragmatism i sin renaste form: snabbt byggt, tungt belastat och utan hänsyn till terrängen."},sec={{t="Industriell expansion",b="Inbäddad i Windshear Crag ligger Cragpool Lake direkt under den höga avverkningsanläggning som Venture Company har byggt. En enorm träkonstruktion sträcker sig ovanför vattnet och fungerar som utsiktsplats för Gerenzo Wrenchwhistle, som övervakar verksamheten i bergsdalen. Venture Companys arbetare håller till på plattformarna ovanför."}},faq={{q="Vad är den massiva träkonstruktionen som hänger över sjön?",a="Det är en industriell överbyggnad som Venture Company har uppfört för att sköta sina omfattande avverknings- och gruvverksamheter i Windshear Crag. Den förbinder plattformar och tunga maskiner som sträcker sig rakt över sjön.",al={"venture companys plattform","cragpools byggnadsställning","cragpools bro"}},{q="Vem övervakar verksamheten vid Cragpool Lake?",a="Gerenzo Wrenchwhistle, en viktig operatör för Venture Company, har sin utsiktsplats högst upp på den höga byggnadsställningen, där han övervakar skogsskövlingen och utvinningen av naturresurser i hela Windshear Crag.",al={"vem leder venture company här","vem är chefen här","gerenzo wrenchwhistle"}},{q="Vilka faror omger Cragpool Lake?",a="Venture Company bedriver verksamhet på plattformarna över sjön. De beväpnade arbetarna gör industriområdet farligt för inkräktare.",al={"vad finns i cragpool lake"}},{q="Har Venture Company övergett Cragpool Lake?",a="Nej. Venture Companys arbetare och Gerenzo Wrenchwhistle håller till i konstruktionen ovanför sjön.",al={"är venture company borta","vem bor vid cragpool lake"}}},fx={["588e76b4"]={q="Vad är Cragpool Lake?",a="Cragpool Lake är en liten sjö i Windshear Crag i Stonetalon Mountains. Den domineras av en vidsträckt, upphöjd träkonstruktion som Venture Company har byggt över vattnet för att stödja sina avverknings- och grävmaskiner i dalen.",al={"vad är cragpool lake","cragpool lakes bakgrund","cragpool lake i stonetalon"}},["686f269e"]={q="Vad hände vid Cragpool Lake?",a="Venture Company byggde sin enorma träkonstruktion över Cragpool Lake som en del av sin verksamhet i Windshear Crag. Gerenzo Wrenchwhistle övervakar arbetet från plattformarna.",al={"cragpool lakes historia","vad hände vid cragpool lake","cragpool lakes förflutna"}}},fp="13,99,23.214.0,59.166.0,45.185.0,36.130.0,48.95.0"}
P.entries["subzone:crossroads"] = {n="The Crossroads",s="Vid Crossroads möts Hordens resenärer där Gold Road korsar vägen från Ratchet till Stonetalon Mountains. Utposten sköter handel, militär uppmarsch och resor mellan Durotar, Mulgore och de norra frontlinjerna.",h="Vid Crossroads möts Hordens resenärer där Gold Road korsar vägen från Ratchet till Stonetalon Mountains.",kw={"the barrens","the crossroads","devrak","gold road","rovfåglar","ratchet","stonetalon","vindryttare"},ang={["faction:Alliance"]="Som medlem av Alliansen kan du slå till mot Crossroads för att störa Hordens förstärkningar som färdas mellan Orgrimmar, Mulgore och Ashenvales omstridda gränser.",["faction:Horde"]="Som medlem av Horden ser du hur Crossroads knyter samman orkernas, taurenfolkets och trollens hemländer och samordnar försörjningen över Kalimdor. Det är en prövningsplats för din unga nation."},sec={{t="En viktig knutpunkt på savannen",b="Crossroads ligger där Gold Road möter vägen från goblinhamnen Ratchet in i Stonetalon Mountains. Härbärgena är enkla, men under vakttornen hittar resenärer vindryttarmästare, handelsmän, smeder och tränare. För unga krigare från Durotar eller Mulgore visar utposten hur den nya Horden knyter samman sina avlägsna fronter och försörjer dem."},{t="Gränsutpost under belägring",b="Att upprätthålla ordningen vid Crossroads är en ständig kamp. Slättens rovfåglar stryker så nära att de stjäl lönepengar av silver från vakttornen, medan harpyor, quilboar och kentaurstammar pressar mot försvarslinjen. Det neutrala Ratchet ligger nära, och Ashenvales omstridda skogar är inom räckhåll. Alliansens spejare slår ofta till nära utpostens försvarsbarrikader."}},faq={{q="Varför är The Crossroads så viktigt för Horde?",a="Crossroads är navet för centrala Kalimdors huvudleder. Resenärer som färdas landvägen mellan Durotar, Mulgore, Ratchet, Stonetalon eller Ashenvale passerar genom eller nära utposten, vilket gör den till en viktig plats för förnödenheter och förstärkningar.",al={"varför är the crossroads viktigt","the crossroads funktion","varför the crossroads spelar roll"}},{q="Vem sköter flygtransporterna vid The Crossroads?",a="Devrak sköter vindryttarens rastplats vid Crossroads. Han förbinder resenärer med utposter över hela Kalimdor, däribland Orgrimmar och Thunder Bluff.",al={"flygmästare vid the crossroads","vem har vindryttare här","flygmästare the crossroads"}},{q="Varför anfaller Alliansen The Crossroads så ofta?",a="Crossroads ligger mitt i Hordens resvägar, inom slagavstånd från Ashenvale och Ratchet. Alliansens rövargrupper angriper utposten för att störa Hordens försörjningslinjer.",al={"varför anfaller alliansen the crossroads","alliansens pvp vid the crossroads","attacker mot the crossroads"}},{q="Vad hände med utpostens lönesilver?",a="Rovfåglar från Barrens stal en silversändning från vakttornet vid Crossroads. Silvret skulle användas till att betala vakterna som försvarade utposten, och rovfåglarna spred ut det över den omgivande savannen.",al={"stulet lönesilver vid the crossroads","vem tog silvret","silvret stulet vid the crossroads"}}},fx={["2f66b0ff"]={q="Vad är Crossroads?",a="The Crossroads är Hordens största och mest centrala bosättning i The Barrens. Den är byggd kring ett befäst vakttorn och värdshus och fungerar som den främsta rastplatsen och förrådsdepån som förbinder Orgrimmar, Thunder Bluff, Ratchet och gränstrakterna i Stonetalon och Ashenvale. För resenärer genom centrala Kalimdor är den ett livligt nav för vila, handel och regionalt försvar.",al={"vad är crossroads","crossroads i the barrens","vad är staden crossroads"}},["6d918d5a"]={q="Varför kallas det Crossroads?",a="Utposten har fått sitt namn direkt från sitt läge: den ligger precis där den huvudsakliga nord-sydliga vägen Gold Road korsar den öst-västliga leden från den neutrala hamnen Ratchet till Stonetalon Mountains. Eftersom nästan varje resa till lands genom The Barrens passerar här växte bosättningen naturligt fram kring denna viktiga vägkorsning.",al={"varför crossroads","crossroads ursprung","hur fick crossroads sitt namn"}},["9b710adc"]={q="Är Crossroads farligt?",a="Hordens vakter skyddar bosättningens inre, men platsen är ständigt utsatt för fara. Närheten till Ashenvale och Ratchet gör den till ett återkommande mål för djärva räder från Alliansen, medan de omgivande slätterna hemsöks av aggressiva raptorer, harpyor som plundrar och fientliga quilboarstammar som vill skära av Hordens livsviktiga försörjningsleder.",al={"är crossroads tryggt","faror vid crossroads","hot mot crossroads"}}},fp="10,226,32.341.0,28.340.0,48.216.0,48.139.0,58.174.0,46.187.0"}
P.entries["subzone:crown-guard-tower"] = {n="Crown Guard Tower",s="Crown Guard Tower är ett förstört spaningstorn från Lordaeron i södra Eastern Plaguelands. The Scourge förstörde det under invasionen av Lordaeron i det tredje kriget, och dess sönderslagna stenar har legat bland pesthärjningarna sedan dess.",h="Crown Guard Tower är ett förstört spaningstorn från Lordaeron i södra Eastern Plaguelands.",kw={"crown guard tower","eastern plaguelands","lordaeron","the scourge","spaningstorn","vakttorn"},ang={["faction:Alliance"]="För Alliance är det förstörda Crown Guard Tower en påminnelse om hur fullständigt The Scourge bröt ner Kingdom of Lordaerons försvar."},sec={{t="Ett fallit försvarsverk",b="Crown Guard Tower var en gång en del av Kingdom of Lordaerons försvar och ett spaningstorn som höll uppsikt över östra Lordaeron. När The Scourge övermannade kungariket förstördes tornet och lämnades i ruiner, ett av flera fallna torn utspridda över det som nu är Eastern Plaguelands. Dess förkolnade stenar står i ett land som de odöda fortfarande håller."}},faq={{q="Vad byggdes Crown Guard Tower ursprungligen för?",a="Det fungerade som ett regionalt militärt vakttorn och en spaningspost för människornas Kingdom of Lordaeron före det tredje kriget, och vaktade vägarna mot intrång.",al={"crown guard towers historia","varför byggdes det","lordaerons torn"}},{q="Varför ligger tornet i ruiner?",a="Tornet förstördes under The Scourges invasion av Lordaeron, när vågor av odöda övermannade kungarikets försvar och lämnade byggnaden i spillror.",al={"vem förstörde crown guard tower","vad hände här"}}},fp="17,156,16.317.0,48.177.0,24.156.0"}
P.entries["subzone:crusader-outpost"] = {n="Crusader Outpost",s="Crusader Outpost är ett befäst vakttorn på de karga kullarna i östra Tirisfal Glades. Det bemannas av fanatiska medlemmar av Scarlet Crusade och bevakar vägarna mot deras fäste vid Scarlet Monastery. Från denna höjd spanar korsfararna efter resande längs vägen och står redo att slå tillbaka varje intrång från Forsaken.",h="Crusader Outpost är ett befäst vakttorn på de karga kullarna i östra Tirisfal Glades.",kw={"captain vachon","crusader outpost","scarlet crusade","scarlet monastery","spaningstorn","tirisfal glades","vakttorn"},ang={["faction:Horde"]="Var försiktig när du färdas längs de östra stigarna i Tirisfal. Scarlet-vaktposterna på kullen anfaller snabbt alla som färdas mot klostret.",["race:Undead"]="Detta vakttorn ligger precis vid gränsen till Forsakens territorium och påminner bittert om att fanatiska levande korsfarare fortfarande håller enklaver i gläntorna."},sec={{t="Ögon över Tirisfal",b="Crusader Outpost är byggt i klipporna med utsikt över den östra vägen och fungerar som Scarlet Crusades främsta förvarningspost. Från det höga tornet håller vaktposterna uppsikt över rörelser mellan Brill och Lordaerons östra utmarker och ser till att kringströvande odöda eller spejarpatruller upptäcks långt innan de når klostrets portar. Tornet ger också garnisonen möjlighet att anfalla från flanken varje styrka som försöker marschera uppför dalen mot deras heliga bastion."},{t="En nagel i den mörka damens öga",b="Garnisonen här står under ledning av Scarlet-officerare som Captain Vachon och håller ständig vakt. De ser inte de omgivande skogarna som Forsakens suveräna territorium, utan som ohelig mark som stulits från mänskligheten av vidunder. För resande som är lojala mot Undercity är utposten en ständig risk för bakhåll, där armborstpilar och renande stål väntar alla som kommer för nära klipporna."}},faq={{q="Vad är Crusader Outpost?",a="Det är ett befäst spaningstorn som hålls av Scarlet Crusade i östra Tirisfal Glades. Det bevakar vägen nedanför och skyddar den södra infarten till Scarlet Monastery.",al={"vad är det här för torn","crusader outpost tirisfal","scarlet-vakttorn"}},{q="Vem kontrollerar utposten?",a="Utposten bemannas av fanatiker från Scarlet Crusade under befäl av Captain Vachon. De ser alla odöda som vidrigheter som måste utrotas så fort de upptäcks.",al={"vem äger crusader outpost","vem bor här","scarlet crusade-utpost"}},{q="Varför ligger tornet i dessa kullar?",a="Det höga läget ger fri sikt över Tirisfal Glades viktigaste östliga färdväg. Det gör att korsfararna tidigt kan upptäcka truppförflyttningar från Forsaken och anfalla från flanken mot styrkor som försöker storma Scarlet Monastery.",al={"varför bygga här","utpostens plats","taktiskt syfte"}},{q="Kommer vakterna här att anfalla mig?",a="Ja. Scarlet Crusade betraktar alla utomstående, särskilt Forsaken och deras allierade i Horde, som korrumperade fiender som måste renas i helig eld.",al={"är crusader outpost fientlig","är de aggressiva"}}},fx={a83c5de5={q="Vem leder Crusader Outpost?",a="Utposten leds av Captain Vachon, en officer i Scarlet Crusade som är stationerad här för att övervaka spaningen och hålla stånd mot inkräktare på Crusades territorium.",al={"vem leder crusader outpost","kaptenen på crusader outpost","befälhavaren för crusader outpost"}},b91596ef={q="Varför heter platsen Crusader Outpost?",a="Utposten har fått sitt namn direkt från Scarlet Crusade, den fanatiska människororden som byggde och underhåller den som en förvarningspost och försvarsflank för närbelägna Scarlet Monastery.",al={"varför heter det crusader outpost","ursprunget till namnet crusader outpost","varför crusader outpost"}}},fp="16,180,18.338.0,31.303.0,29.161.0,26.131.0,41.196.0,31.130.0"}
P.entries["subzone:crusader-s-armory"] = {n="Crusader's Armory",s="Crusader's Armory är en befäst inre sal i Scarlet Monastery Armory-flygeln. Här lagras ammunition, krut och kanonkulor, och salen fungerar som samlingsplats för fanatikerna som vaktar vägen mot det inre helgedomen. Bakom den låsta järndörren ligger Hall of Champions.",h="Crusader's Armory är en befäst inre sal i Scarlet Monastery Armory-flygeln.",kw={"rustkammare","crusader's armory","krut","hall of champions","scarlet key","scarlet monastery"},ang={["faction:Horde"]="För Forsaken och Horde utgör de explosiva förråden i Crusader's Armory ett direkt hot mot Tirisfal Glades gränser och Undercitys portar.",["profession:Blacksmithing"]="Vapnen och ammunitionen som lagras här visar vilken hög produktionsnivå och militär disciplin Lordaerons forna smeder hade, innan deras skicklighet vändes till fanatisk nitälskan."},sec={{t="Fanatikernas arsenal",b="Crusader's Armory ligger mellan Footman's Armory och den storslagna Hall of Champions och visar att Scarlet Crusade är redo för strid. Till skillnad från träningsgårdarna utanför är de smala stenkorridorerna fulla ända upp till taket av lådor med explosivt krut, staplade kanonkulor och tungt beväpnade korsfarare som är redo att slå tillbaka inkräktare. Korståget har förvandlat ett före detta klosterområde till en hotfull fästning och ägnat varje tillgänglig sal åt total krigföring. Längst bort i rustkammaren står en tung, låst järndörr som spärrar vägen till de inre kamrarna om du inte har The Scarlet Key."}},faq={{q="Vad är Crusader's Armory?",a="Crusader's Armory är en inre del av Scarlet Monasterys rustkammarvinge. Den fungerar som ammunitionsförråd och försvarskorridor mellan Footman's Armory och Hall of Champions.",al={"crusader's armory","vad är crusader's armory","rustkammarrum i klostret"}},{q="Varför är dörren längst bort låst?",a="Dörren längst bort i Crusader's Armory vaktar passagen till Hall of Champions och befälhavarens kvarter bortom den. Scarlet Crusade håller den strikt låst, och du behöver The Scarlet Key, som finns i klostrets biblioteksflygel, för att öppna den.",al={"låst dörr i rustkammaren","hur öppnar man dörren till rustkammaren","scarlet key till rustkammaren"}},{q="Varför finns det så många kanonkulor och krutlådor här?",a="Scarlet Crusade upprätthåller en aktiv belägringsnärvaro och artilleriförsvar runt Tirisfal Glades. Den här rustkammaren fungerar som ett centralt förråd för deras kanoner och explosiva ammunition och ser till att trupperna har gott om förnödenheter i kriget mot Scourge och Forsaken.",al={"krutlådor i rustkammaren","kanoner i klostret","varför krut"}},{q="Vem vaktar området?",a="Salen försvaras av erfarna soldater från Scarlet Crusade, däribland fotsoldater, korsfarare och bågskyttar som står bland ammunitionen för att stoppa inkräktare som försöker tränga djupare in i komplexet.",al={"fiender i rustkammaren","vem finns i crusader's armory"}}},fx={["2e345cd4"]={q="Är Crusader's Armory farligt?",a="Det är extremt farligt. Vapenkammaren är full av fanatiska Scarlet Crusade-krigare som angriper alla inkräktare de får syn på och ser varje främling som en agent för korruptionen eller Scourge. Faran förvärras av att hela korridoren är fullpackad med sprängämnen, däribland instabila kruttunnor och artillerilager redo för deras skoningslösa krig i Tirisfal Glades.",al={"faran med crusaders armory","är crusaders armory säkert","hot i crusader armory"}},["9c475e8e"]={q="Varför heter den Crusader's Armory?",a="Kammaren har fått sitt namn från Scarlet Crusaders som bemannar den och förvarar sitt belägringsmateriel där. Den ligger djupt inne i Scarlet Monasterys militära flygel, bortom Footman's Armory, och rymmer kanonkulor, krut och vapen avsedda för Crusades veteraner när de förbereder sig för att anfalla de omgivande Plaguelands.",al={"varför heter den crusaders armory","ursprunget till namnet crusaders armory","betydelsen av crusader armory"}}},fp="17,206,15.391.0,30.153.0,34.187.0,60.232.0,21.171.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Crusader's Outpost",s="Crusader's Outpost är ett befäst utkikstorn bemannat av Scarlet Crusade i västra Tirisfal Glades. Det ligger intill Solliden Farmstead och är Crusades västligaste utpost i hela Lordaeron. Det farliga avståndet till de främsta fästena i Scarlet Crusade lämnar garnisonen isolerad mitt i fientligt Forsaken-territorium.",h="Crusader's Outpost är ett befäst utkikstorn bemannat av Scarlet Crusade i västra Tirisfal Glades.",kw={"crusader's outpost","scarlet crusade","utkikstorn","solliden farmstead","tirisfal glades","tyr's hand"},ang={["faction:Horde"]="Utposten är en bitter påminnelse om Scarlet Crusades fanatiska vägran att lämna över Tirisfal till Forsaken och deras allierade i Horde.",["race:Undead"]="För de nyväckta Forsaken som kommer från Deathknell utgör det närbelägna tornet och Scarlet-fanatikerna som vaktar det ett omedelbart existentiellt hot precis vid gränsen."},sec={{t="Ett ensligt vakttorn",b="Det här stentornet ligger bland kullarna i västra Tirisfal, strax norr om Deathknell, och markerar Scarlet Crusades yttersta maktgräns i Lordaeron. Garnisonen här samarbetar med de kvarvarande mänskliga arbetarna på närbelägna Solliden Farmstead och försöker hålla de framryckande odöda stången. Från tornets topp håller utkiksposterna uppsikt över de omgivande pumpafälten och skogsstigarna, vaksamma på både kringströvande Scourge-odjur och patruller från Undercity."},{t="Isolerade bakom fiendens linjer",b="Att hålla den västra gränsen innebär stora risker. Korsfararna vid utposten är avskurna från sina främsta fästen i Scarlet Monastery och långt österut vid Tyr's Hand, så de kan inte räkna med snabba förstärkningar om ett angrepp bryter igenom palissaden. En belägring av Forsaken-styrkor som samlas på andra sidan Tirisfal innebär att de måste hålla tornet på egen hand eller gå under innan hjälp hinner fram."}},faq={{q="Varför är Scarlet Crusade ända här ute i västra Tirisfal?",a="Tornet fungerar som en förvarningspost och försvarsanläggning längs kullarna i västra Tirisfal. Det skyddar de levande mänskliga bönderna på Solliden Farmstead och bevakar de västra tillfartsvägarna mot både vilda Scourge och Forsakens förtrupper.",al={"varför är scarlet här","scarlet crusade i västra tirisfal","crusader outposts syfte"}},{q="Kan förstärkningar nå utposten om den blir angripen?",a="Inte utan svårigheter. Utposten är Scarlet Crusades västligaste fäste i Lordaeron. Deras främsta fästen ligger långt österut vid Scarlet Monastery och Tyr's Hand, vilket lämnar garnisonen helt avskuren om Forsaken-styrkor omringar den.",al={"kan scarlet få förstärkning","hjälp till utposten","hur långt bort är hjälpen"}},{q="Hur hänger tornet ihop med Solliden Farmstead?",a="Korsfararna har bildat en allians med de kvarvarande mänskliga bönderna på Solliden Farmstead. Soldaterna skyddar dem mot de vandrande döda i utbyte mot mat och en lojal bas i Lordaerons utkanter.",al={"kopplingen till solliden","varför är korsfararna vid gården","korsfarare och bönder"}},{q="Finns det fler torn av den här typen i området?",a="Ja. Det här tornet är ett av fyra liknande Crusader's Outposts som Scarlet Crusade har upprättat runtom i Tirisfal Glades för att spana på och patrullera de omgivande markerna.",al={"andra crusader outposts","fler scarlet-torn"}}},fx={["5e123392"]={q="Vad är Crusader's Outpost?",a="Crusader's Outpost är ett befäst spaningstorn i västra Tirisfal Glades, strax norr om Deathknell. Det är Scarlet Crusades västligaste fäste i Lordaeron och fungerar som en främre vaktpost mot hoten från Forsaken och Scourge i området. Tillsammans med de allierade bönderna på Solliden Farmstead håller det uppsikt över trakten.",al={"vad är crusaders outpost","crusader outpost i tirisfal","scarlet-utpost i västra tirisfal"}},["74d073f8"]={q="Vem kontrollerar Crusader's Outpost?",a="Tornet bemannas och drivs av fanatiska medlemmar av Scarlet Crusade. Långt från sina fästen i öster håller dessa vakter och korsfarare en isolerad garnison. De samarbetar nära med de sympatiserande människobönderna på Solliden Farmstead för att skydda sin lilla del av Tirisfal.",al={"vem bor vid crusaders outpost","invånare vid crusaders outpost","vem styr crusaders outpost"}},["30c5615e"]={q="Är Crusader's Outpost farligt?",a="Ja, mycket farligt om du är en främling eller odöd. Scarlet Crusade betraktar nästan alla utanför sina egna led som besmittade eller korrumperade, och angriper inkräktare direkt. Korsfararna här är isolerade djupt inne i fientliga områden och ständigt på helspänn, så det är riskabelt att närma sig.",al={"är crusaders outpost farligt","faran vid crusader outpost","är de fientliga här"}},["52f2bf53"]={q="Varför heter det Crusader's Outpost?",a="Namnet kommer direkt från Scarlet Crusade, den religiösa militärorden som byggde och ockuperar spaningstornet. Det är en av flera sådana utposter som rests runtom i Tirisfal Glades för att säkra deras fanatiska korståg mot Scourge och Forsaken.",al={"varför heter det crusaders outpost","ursprunget till namnet crusaders outpost"}}},fp="18,227,19.377.0,27.361.0,68.234.0,58.255.0,66.209.0,47.138.0"}
P.entries["subzone:crypt-badlands"] = {n="Crypt (Badlands)",s="Högt uppe bland Badlands dammiga kullar ligger en avskild underjordisk grav som bara kallas Crypt. Där inne vilar kvarlevorna av en uråldrig krigare: ett rustningsklätt skelett på en stentron, flankerat av urnor, kistor och ett väldig reliksvärd.",h="Högt uppe bland Badlands dammiga kullar ligger en avskild underjordisk grav som bara kallas Crypt.",kw={"badlands","barbarian king","crypt","hammertoe's digsite","svärd","tron"},ang={["class:Warrior"]="Kryptan skänker krigare en stunds stilla vördnad inför en fallen mästare, som dog klädd i plåt och fortfarande med sitt mäktiga svärd i handen.",["race:Dwarf"]="Arkitekturen och skelettets tron vittnar om mysterier från en tid före Ironforge's senaste utgrävningar, trots att kryptan ligger nära aktiva dvärgiska utgrävningsplatser."},sec={{t="Barbarerkungens grav",b="Badlands Crypt ligger sydost om Hammertoe's Digsite, längs en omärkt jordstig som slingrar sig uppför sluttningen, och är lätt att missa. I de mörka stenkamrarna sitter ett rustningsklätt skelett på en tron. Intill kvarlevorna vilar Sword of the Barbarian King, omgivet av utspridda ben, urnor och bortglömda kistor. Gruvarbetare och äventyrare söker ofta efter dvärgiska ruiner och skatter i de omgivande ravinerna, men den sittande härskarens ursprung och historia är fortfarande ett mysterium som gått förlorat i det torra ödemarkerna."}},faq={{q="Var ligger Crypt i Badlands?",a="Ingången ligger sydost om Hammertoe's Digsite. Följ en omärkt stig som slingrar sig uppför kullens krön ovanför utgrävningsplatsen.",al={"crypt i badlands","hitta crypt i badlands","ingången till crypt i badlands"}},{q="Vem är skelettet som sitter på tronen?",a="Det rustningsklädda skelettet kallas allmänt Barbarian King. Inga bevarade lokala skrifter berättar om hans regeringstid eller identitet, så han förblir en gåtfull kvarleva från en tidigare, bortglömd era i Badlands.",al={"skelett på tron","vem är barbarian king","skelettets identitet i crypt"}},{q="Vad är svärdet bredvid tronen?",a="Det kallas Sword of the Barbarian King. Det vilar tyst bredvid den skelettartade härskaren, som en högtidlig gravmarkör och ett vittnesmål om hans krigiska förflutna.",al={"sword of the barbarian king","svärd i crypt","svärd på tron i badlands"}},{q="Finns det några uppdrag knutna till den här kryptan?",a="Det finns inga vanliga uppdrag som leder äventyrare in i kryptan. Den är främst en kuslig, gömd upptäckt för resenärer som utforskar klipporna.",al={"uppdrag i crypt i badlands","varför besöka crypt i badlands"}}},fp="16,141,30.385.0,43.111.0,49.148.0,37.128.0,48.111.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Crypt (Stromgarde Keep)",s="Djupt inne i ruinerna av Stromgarde Keep ligger den kungliga kryptan, bortom kapellet i The Sanctum, i hjärtat av området som hålls av Stromgardes överlevande försvarare. Där finns den fallne kung Thoras Trollbanes grav och dynastins förfäderskatter. Valvet bevakas noga av Prince Galen och trogna vårdare och förblir en fristad för kunglig ära mitt i ett sönderslaget kungarike.",h="Djupt inne i ruinerna av Stromgarde Keep ligger den kungliga kryptan, bortom kapellet i The Sanctum, i...",kw={"arathi","krypta","galen","sanctum","stromgarde","thoras","trol'kalar","trollbane"},ang={["faction:Alliance"]="Stromgardes kungliga krypta är ett av de sista fästena för Alliansens arv i Arathi och försvaras envist mot banditer, og rer och Horden.",["race:Human"]="För Alliansens människor står graven för Stromgardes tragiska förfall, ett av de sju stora kungarikena, och är den helgade viloplatsen för en av Alliansens främsta krigsledare."},sec={{t="Thoras Trollbanes grav",b="Dold under The Sanctum i Stromgarde Keep är denna underjordiska gravkammare kung Thoras Trollbanes sista viloplats. Han var krigarkungen som ledde Stromgarde genom det andra kriget. Staden ligger i ruiner och är splittrad mellan Syndicate-rövare och Boulderfist-ogrer, men den återstående Stromgarde-milisen håller envist fast vid detta kvarter. Prince Galen Trollbane vakar själv över kryptorna tillsammans med hängivna kungliga vårdare, så att hans fars kropp och arv förblir orörda av asätarna och fienderna utanför."},{t="Trol'kalarvalvet",b="Förutom de kungliga gravarna skyddar kryptan dyrbara föremål som tillhör Trollbane-släkten. Det främsta av dessa är Trol'kalar, det urgamla runristade tvåhandssvärdet som smiddes för århundraden sedan för att dräpa troll. Kammaren och dess skatter anförtros åt edsvurna beskyddare som Alaric, Nevlin och Weston och säkras med kraftfulla skydd. Galen och hans lojala anhängare vaktar graven utan uppehåll, väl medvetna om att rivaliserande fraktioner och fientliga troll i Arathi skulle åtrå svärdets uråldriga kraft."}},faq={{q="Vem ligger begravd i kryptan?",a="Kung Thoras Trollbane, Stromgardes avlidne härskare, ligger begravd här. Hans son, Prince Galen Trollbane, vakar över graven mitt i den förstörda staden.",al={"vem ligger begravd här","vems grav är detta","krypta grav"}},{q="Vad är Trol'kalar?",a="Trol'kalar är ett urgammalt arvegods och svärd som tillhör Trollbane-familjen. Namnet betyder ”trolldräpare” på det forntida språket. Svärdet smiddes ursprungligen för att bekämpa Arathis skogstroll.",al={"trolkalar svärd","trollbane svärd","vad är trolkalar"}},{q="Vem vaktar kryptan?",a="Kryptan försvaras av Prince Galen Trollbane och Stromgardes kungliga vårdare, däribland Alaric, Nevlin och Weston. De skyddar gravkammaren mot Syndicate-tjuvar som tränger sig på och Boulderfist-ogrer.",al={"kryptans vakter","vem försvarar kryptan","vårdare"}},{q="Var ligger kryptan?",a="Den ligger i Stromgarde Keep i Arathi Highlands, djupt inne i The Sanctum-distriktet, bakom fästningens kapell, i den del som fortfarande hålls av Stromgardes lojala anhängare.",al={"kryptans plats","hur hittar man kryptan","var ligger stromgardes krypta"}}},fp="23,143,28.412.0,23.380.0,27.150.0,19.183.0,21.190.0,27.176.0"}
P.entries["subzone:crystal-lake"] = {n="Crystal Lake",s="Öster om Goldshire lockar Crystal Lake resenärer till en strand som murlocer gör anspråk på. Deras attacker gör vattnet farligt för bybor och förbipasserande.",h="Öster om Goldshire lockar Crystal Lake resenärer till en strand som murlocer gör anspråk på.",kw={"kristallkelp","crystal lake","elwynn","goldshire","murloc","william pestle"},ang={["faction:Alliance"]="Murlocer nära Goldshire visar hur hårt kungarikets militär är ansträngd när den ska skydda sina kärnområden.",["profession:Herbalism"]="Kristallkelp växer på sjöns grunda sötvattenbotten. Det mesta samlas in från sjöns murlocer, som skördar den från sjöbottnen."},sec={{t="En orolig strand",b="Crystal Lake ligger öster om Goldshire, på gångavstånd från Lion's Pride Inn. Sötvattenmurlocer gör nu anspråk på stranden och de grunda sandbankarna, och angriper alla som kommer för nära. William Pestle, en alkemist på värdshuset, anlitar resenärer för att driva bort dem och samla in kristallkelpen de bär på till hans experiment."}},faq={{q="Var ligger Crystal Lake?",a="Crystal Lake ligger öster om Goldshire i centrala Elwynn Forest, strax bortom byns utkanter.",al={"crystal lake plats","var ligger crystal lake","hitta crystal lake"}},{q="Varför har murlocer samlats vid Crystal Lake?",a="Crystal Lake ger sötvattenmurlocer en plats att bygga bo och leta föda på. De har blivit fler nära Goldshire medan Stormwinds lokala vakt har svårt att skydda området.",al={"varför murlocer crystal lake","murlocproblem goldshire","murlocer crystal lake"}},{q="Vad behöver äventyrare från Crystal Lake?",a="William Pestle, en apotekare på Lion's Pride Inn i Goldshire, anlitar resenärer för att dräpa murlocer längs stranden och samla kristallkelp till en osynlighetsdryck.",al={"william pestle crystal lake","kelpuppdrag crystal lake","osynlighetsdryck elwynn"}}},fx={["18711dcc"]={q="Vad är Crystal Lake?",a="Crystal Lake är en sötvattensjö strax öster om Goldshire, mitt i Elwynn Forest. Sjön kan en gång ha varit en fridfull vattningsplats, men det lugna vattnet har på senare tid blivit en källa till problem för resenärer och stadsbor i närheten.",al={"vad är crystal lake","crystal lake i elwynn","crystal lake i berättelsen"}},c07536f5={q="Är Crystal Lake farligt?",a="Ja, sjön kan bli dödlig för en oförsiktig eller oerfaren resenär. Stränderna och det grunda vattnet är fulla av aggressiva murlocs som angriper alla som kommer för nära vattenbrynet.",al={"hur farligt är crystal lake","är crystal lake säkert","hot vid crystal lake"}}},fp="12,118,16.314.0,30.94.0,41.149.0,43.167.0"}
P.entries["subzone:crystal-shore"] = {n="The Crystal Shore",s="Crystal Shore är en sandig kuststräcka längs den sydöstra kanten av Stranglethorn Vale, där South Seas vågor sköljer in. Stranden ligger skyddad nedanför branta kustklippor, strax söder om de forntida Ruins of Aboraz och på andra sidan vattnet från Jaguero Isle.",h="Crystal Shore är en sandig kuststräcka längs den sydöstra kanten av Stranglethorn Vale, där South Seas vågor...",kw={"the crystal shore","jaguero isle","mistvale valley","ruins of aboraz","south seas","stranglethorn vale","wild shore"},sec={{t="En avskild kustremsa",b="Crystal Shore löper längs den sydöstra utkanten av Stranglethorn Vale och bildar en naturlig gräns mellan den täta tropiska inlandsskogen och South Seas öppna vatten. Själva stranden skiljs från djungeln i inlandet av branta åsar, och bara ett par svårframkomliga passager låter resenärer ta sig mellan kusten och Mistvale Valleys djupare vildmark. I norr ligger de sönderfallande trollbyggnaderna i Ruins of Aboraz, medan Wild Shore följer uddens södra krök. Läget gör stranden till en stillsam, vindpinad avkrok långt från Booty Bays livliga hamnar."}},faq={{q="Var ligger Crystal Shore?",a="Crystal Shore ligger på den avlägsna sydöstra kusten av Stranglethorn Vale. Den sträcker sig längs vattnet mot South Seas, söder om Ruins of Aboraz och nordost om Wild Shore.",al={"crystal shore läge","var ligger crystal shore","crystal shore karta"}},{q="Hur tar du dig till Crystal Shore från inlandet?",a="En brant ås skiljer stranden från djungeln på fastlandet. Ett par smala, naturliga passager går dock genom de höga klipporna, bland annat en stig som leder direkt in i Mistvale Valley.",al={"hur tar man sig till crystal shore","stig till crystal shore","nå crystal shore"}},{q="Vilka landmärken finns i närheten?",a="Strax norr om stranden ligger de forntida Ruins of Aboraz, medan Jaguero Isle ligger på andra sidan sundet åt sydväst. Längre söderut längs kusten ligger Wild Shore.",al={"landmärken nära crystal shore","vad finns nära crystal shore"}},{q="Har någon fraktion bosatt sig vid Crystal Shore?",a="Ingen organiserad fraktion har en stad eller bosättning längs Crystal Shore. Stranden förblir otämjd och präglas av den inhemska faunan, forntida trollruiner i norr och South Seas dånande vågor.",al={"vilka bor vid crystal shore","bosättning vid crystal shore","städer vid crystal shore"}}},fp="13,160,24.407.0,35.162.0,48.155.0,26.173.0,44.161.0"}
P.entries["subzone:crystal-vale"] = {n="The Crystal Vale",s="Långt upp i Silithus nordvästra hörn ligger The Crystal Vale, en avlägsen ravin med taggiga mineralspröt och virvlande elementarkrafter. Jord- och luftelementaler strövar över dess steniga slätter och vaktar rika ådror av råmalm. Här finns också mäktig åkallels magi, djupt knuten till de uråldriga elementarherrarna.",h="Långt upp i Silithus nordvästra hörn ligger The Crystal Vale, en avlägsen ravin med taggiga mineralspröt och...",kw={"the crystal vale","elementaler","highlord demitrian","ravaged twilight camp","silithus","torium","thunderaan"},ang={["class:Shaman"]="Den råa friktionen mellan jord- och luftandar här påminner om det tygellösa kaos som okontrollerade elementaler sprider över hela Silithus.",["profession:Mining"]="De karga klippkanterna och ravinväggarna i The Crystal Vale rymmer värdefulla ådror av rikt torium. Därför är platsen lukrativ, men farlig, för mycket skickliga gruvarbetare."},sec={{t="Där sten möter vind",b="The Crystal Vale skiljer sig från de karga ökensanddynerna i södra Silithus. Branta klippor ramar in bäckenet, som fylls av skimrande kristalloidformationer, kringströvande jordelementaler och dånande virvelvindar av levande luft. Rika toriumfyndigheter lockar ibland djärva malmletare, men dalen är långt ifrån lugn. Elementarvarelserna här är fientliga mot inkräktare och vaktar en plats som genomsyras av ur-Azeroths ursprungliga konflikter."},{t="Vindjägarens sömn",b="Utöver sina mineraler och inhemska andar har The Crystal Vale stor betydelse för uråldriga elementarkrafter. Här dröjer sig Highlord Demitrian kvar och ruvar på hemligheterna om Prince Thunderaan, Vindjägaren. De som samlar den fallne prinsens avskurna elementarbojor och de sällsyntaste smidda metallerna hänvisas till den här dalen. Där kan den fängslade luftherren lockas loss från sina bojor och utmanas i öppen strid."}},faq={{q="Var ligger The Crystal Vale?",a="The Crystal Vale ligger längst upp i nordvästra Silithus, intill bergskammen som gränsar till öknen.",al={"var ligger the crystal vale","karta över the crystal vale","the crystal vale plats"}},{q="Vilka varelser bor i den här dalen?",a="Ravinen är främst bebodd av aggressiva luft- och jordelementaler som svävar och stampar omkring bland mineralformationerna.",al={"monster i the crystal vale","vad lever i the crystal vale","elementaler i the crystal vale"}},{q="Vem är Highlord Demitrian och varför är han här?",a="Highlord Demitrian är en ensam eremit som bor i dalen och besitter djup kunskap om Prince Thunderaan. Han hjälper hjältar som kan återförena Vindjägarens bojor för att åkalla elementarprinsen.",al={"vem är demitrian","highlord demitrian the crystal vale","demitrians plats"}},{q="Vad är Ravaged Twilight Camp?",a="Det är resterna av ett läger tillhörande Twilight's Hammer i dalen, som har övertagits och krossats av de våldsamma elementarvarelserna som gör ravinen till sitt revir.",al={"ravaged twilight camp the crystal vale","twilight-läger i dalen","förstört twilight-läger"}}},fp="12,241,30.321.0,29.307.1,34.100.0,35.77.0,45.179.0,34.136.0"}
P.entries["subzone:crystalvein-mine"] = {n="Crystalvein Mine",s="Crystalvein Mine är en grotta mitt i Stranglethorn Vale, nära de gamla ruinerna av Ruins of Zul'Mamwe. Grottan är rik på värdefulla ”sjungande kristaller”, men aggressiva basilisker från trakten har tagit över hela platsen och förvandlar blivande gruvarbetare till sten.",h="Crystalvein Mine är en grotta mitt i Stranglethorn Vale, nära de gamla ruinerna av Ruins of Zul'Mamwe.",kw={"basilisk","crank fizzlebub","crystalvein mine","sjungande kristaller","stranglethorn vale","venture company","zul'mamwe"},ang={["profession:Mining"]="Gruvarbetare som lockas av löftet om sjungande kristaller måste vara försiktiga, eftersom grottans basilisker gör prospektering här till en av de farligaste sysslorna i Stranglethorn."},sec={{t="En lönsam fälla",b="Crystalvein Mine ligger undangömd bland djungelklädda kullar nära Ruins of Zul'Mamwe och rymmer sällsynta fyndigheter av sjungande kristaller, ett unikt mineral som betingar höga priser i de södra handelshamnarna. Lockade av löftet om enorma vinster bestämde sig Venture Company för att utvinna ådrorna. Men gruvans naturliga invånare har visat sig vara katastrofala för affärerna. Basiliskerna i trakten äter de märkliga kristallerna, vilket gör deras fjäll hårda och dem onaturligt dödliga. Utanför grottöppningen står förstenade statyer av troll och människor som ett tyst vittnesmål om Venture Companys misslyckade expeditioner."}},faq={{q="Vad gör Crystalvein Mine värdefull?",a="Gruvan rymmer fyndigheter av sällsynta sjungande kristaller, ett lönsamt mineral som bara finns i Stranglethorn Vale. Gobliner som Crank Fizzlebub värdesätter dem för deras klang och penningvärde, vilket får guldgrävare att trotsa de farliga grottorna.",al={"varför är crystalvein mine viktig","vad finns i crystalvein mine","sjungande kristaller"}},{q="Varför finns det stenstatyer utanför gruvan?",a="Statyerna är de förstenade kvarlevorna av olyckliga troll från trakten och arbetare från Venture Company. Basiliskerna här livnär sig på de resonanta kristallerna, vilket stärker deras stenlika hudar och förstenar alla som är dumma nog att inkräkta på deras födosöksområde.",al={"förstenade människor crystalvein","kristalliserade troll crystalvein","stenkroppar stranglethorn"}},{q="Vem kontrollerar Crystalvein Mine just nu?",a="Venture Company gjorde anspråk på rätten att utvinna grottan, men kontrollerar den inte i praktiken. Basiliskinvasionen är så omfattande att goblinerna inte har kunnat inleda någon aktiv gruvdrift i djupet.",al={"vem äger crystalvein","crystalvein fraktion","venture company crystalvein"}}},fp="16,235,16.437.0,37.207.0,45.167.0,40.194.0"}
P.entries["subzone:cut-throat-alley"] = {n="Cut-Throat Alley",s="Bakom butikerna vid kanalen ligger Cut-Throat Alley tyst och tom i Stormwind City. Gå dit genom Shady Lady nära Dwarven District, där en stenlagd innergård slutar vid en obebodd bostad.",h="Bakom butikerna vid kanalen ligger Cut-Throat Alley tyst och tom i Stormwind City.",kw={"cathedral square","cut-throat alley","dwarven district","hemlig gränd","shady lady","stormwinds kanaler"},ang={["class:Rogue"]="Som Rogue kan du bara nå den här obevakade återvändsgränden genom bakdörren till en skum butik vid kanalen. Där får du ett gömställe utom synhåll för Stormwind City Guard."},sec={{t="En avskild vrå",b="Cut-Throat Alley ligger i ett lugnt hörn av Stormwind och räknas till Dwarven District, men ligger avskilt från dess smedjeeldar och sot. Ingen huvudgata leder hit; den enda gångvägen går genom Shady Lady, en liten butik vid kanalen strax söder om bron från Cathedral Square. Bakom dörren finns en stenlagd återvändsgränd med staplade lådor, bortglömda tunnor och en enda tom bostad i två våningar. Förbipasserande vakter och vanliga stadsbor kan inte se gränden, som förblir tyst mitt i huvudstaden."}},faq={{q="Hur tar du dig till Cut-Throat Alley?",a="Följ kanalen längs kanten av Dwarven District, strax söder om gångbron till Cathedral Square. Leta upp Shady Lady och gå genom butiken för att nå gränden.",al={"hitta cut throat alley","cut throat alley plats","var ligger cut-throat alley","hur tar man sig in i cut-throat alley"}},{q="Varför står det Dwarven District på kartan?",a="Cut-Throat Alley ligger inom Dwarven Districts gränser och räknas vanligtvis till distriktet. Här finns ingen rök från distriktet och ingen anslutning till gatan; gå in genom Shady Lady vid kanalen.",al={"minikarta dwarven district","varför står det dwarven district","namnfel cut-throat alley"}},{q="Bor det någon i Cut-Throat Alley?",a="Ingen bor i Cut-Throat Alley. Det enda huset i två våningar är övergivet, och gränden har bara staplade fraktlådor och tomma tunnor, utan invånare, butiksinnehavare eller stadsvakter.",al={"figurer i cut throat alley","vem bor i cut throat alley","tomt hus cut throat alley"}},{q="Finns det några uppdrag i Cut-Throat Alley?",a="Inga formella plikter eller kommunala uppdrag leder in i Cut-Throat Alley. Det är en förbisedd, avskild vrå av huvudstaden.",al={"uppdrag cut throat alley","berättelse cut throat alley"}}},fx={["636e4761"]={q="Vad är Cut-Throat Alley?",a="Cut-Throat Alley är en avskild, obebodd bakgata bakom Shady Lady, längs kanalerna i Stormwind. Den räknas officiellt till Dwarven District, men ligger avskilt från resten av stadsdelen och saknar den täta röken och livliga trafiken i närheten. Här finns några utspridda lådor och tunnor samt ett obebott tvåvåningshus.",al={"vad är cut throat alley","cut throat alley i berättelsen","om cut-throat alley"}},e98a554d={q="Är Cut-Throat Alley farligt?",a="Trots sitt illavarslande namn är gränden helt lugn och saknar fientliga hot. Här finns varken kringströvande stråtrövare eller lurande ficktjuvar, bara en tom gård, stilla lådor och ett övergivet radhus långt från stadsvaktens vanliga patrullrundor.",al={"är cut throat alley farligt","finns det fiender i cut throat alley","faran med cut throat alley"}}},fp="16,165,15.496.0,35.178.0,48.207.0,37.201.0,41.123.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="Dabyrie's Farmstead",s="Dabyrie's Farmstead är en lantlig bosättning i Alliansens tjänst i norra Arathi Highlands. I ett rike som krossats av det tredje kriget och översvämmats av Syndicate-banditer och Witherbark-troll förblir godset en okuvlig bastion för Stromgardes invånare, ledda av Kenata Dabyrie.",h="Dabyrie's Farmstead är en lantlig bosättning i Alliansens tjänst i norra Arathi Highlands.",kw={"arathi","callow","dabyrie","fardel","gård","kenata","marcel","stromgarde"},ang={["faction:Alliance"]="För resenärer i Alliansen är gården en sällsynt och tröstande påminnelse om att Stromgardes folk fortfarande överlever och kämpar för sitt land trots fiender som rycker allt närmare.",["race:Undead"]="För Forsaken är den välmående gården en irriterande syn: levande människor som samlar på varor plundrade från familjer som omkom under det tredje kriget."},sec={{t="En bastion i höglandet",b="Dabyrie's Farmstead ligger på de nordliga fälten i Arathi Highlands och är en av de få fungerande mänskliga gårdarna som återstår i det sönderslagna kungariket Stromgarde. Marken ägs av Kenata Dabyrie och brukas tillsammans med hennes söner, Fardel och Marcel. En lokal familjemilis försvarar gården med hård beslutsamhet. Gården omges av aggressiva vilda djur, opportunistiska banditer och Forsakens närvaro i norr, och står som en symbol för människors uthållighet i ett ödelagt land."},{t="Bittera fejder",b="Att överleva i Arathi innebär sällan att slippa bitter fiendskap. Godset har väckt Forsakens vrede, särskilt hos Genavie Callow, en före detta adelskvinna som förlorade sina marker och sin familj under det tredje kriget. Callow anklagar den överlevande Dabyrie-klanen för att ha plundrat hennes familjs dyrbara arvegods i pestens kaos. Därmed har den anspråkslösa gården blivit ett mål för hämndlystna legosoldater från Horden som vill göra upp gamla oförrätter i norr."}},faq={{q="Vem bor på Dabyrie's Farmstead?",a="Gården är hem åt Kenata Dabyrie och hennes söner, Fardel och Marcel. De är mänskliga medborgare i Stromgarde som är lojala mot Alliansen och skyddas av en svuren lokal milis.",al={"vem äger dabyrie's farmstead","familjen dabyrie","kenata dabyrie"}},{q="Varför angriper Horden den här gården?",a="En Forsaken-kvinna vid namn Genavie Callow hyser agg mot familjen Dabyrie. Hon hävdar att de plundrade hennes familjs gods och tog med sig de arvegods som överlevde medan hennes egna släktingar omkom i det tredje kriget.",al={"varför döda dabyrie","genavie callow-uppdrag","hordeuppdrag vid dabyrie's farmstead"}},{q="Tillhör Dabyrie's Farmstead Stromgarde?",a="Ja. Familjen Dabyrie ser sig som undersåtar till kungariket Stromgarde och allierade med den större Alliansen. De håller stånd trots att rikets huvudstad i söder har fallit.",al={"tillhör dabyrie alliansen","gård i stromgarde"}},{q="Vilka hot omger gården?",a="Gården ligger farligt nära fientliga rovdjur i höglandet, kringströvande lönnmördare från Syndicate och Forsaken-styrkor som tränger över gränsen från norr.",al={"hot mot dabyrie's farmstead","faror nära dabyrie's farmstead"}}},fp="19,195,26.395.0,12.349.1,33.166.0,37.188.0,42.145.0,36.108.0"}
P.entries["subzone:dagger-hills"] = {n="The Dagger Hills",s="Banditer håller The Dagger Hills, de klippiga höjderna bakom Moonbrook i södra Westfall. När de kungliga patrullerna har försvunnit hotar bergsryggen resenärer och slätterna nedanför.",h="Banditer håller The Dagger Hills, de klippiga höjderna bakom Moonbrook i södra Westfall.",kw={"the dagger hills","defias","grimbooze","leprithus","moonbrook","thunderbrew","westfall"},ang={["faction:Alliance"]="Kullarna visar hur lagen har brutit samman i södra Westfall. Gryan Stoutmantles People's Militia måste kämpa för att återta mark som Stormwind har lämnat åt sitt öde.",["race:Dwarf"]="Som dvärg kan du se Grimbooze Thunderbrews ensamma närvaro på den utsatta bergsryggen som ett tecken på hur envist bryggare söker ostörd plats för sitt hantverk."},sec={{t="Ett banditnäste",b="The Dagger Hills reser sig ovanför Moonbrook i södra Westfall, där Defias fredlösa håller utkik från de klippiga bergsryggarna. Stormwinds kungliga patruller är borta, vilket lämnar det torra höglandet som ett naturligt fäste för Defias Brotherhood. Knogkämpar, stigjägare och landsvägsrövare gömmer sig bland topparna och snåren. De överfaller resenärer och bevakar vägarna till sina fästen nedanför."},{t="Skuggor på bergsryggen",b="Mörkret för med sig egna faror till The Dagger Hills. Leprithus, en kringvandrande gast, har setts stryka omkring på de öde höjderna efter solnedgången. Fredlösa och kvarvarande odöda strövar längs bergsryggen, medan Grimbooze Thunderbrew, en dvärgisk bryggare, sätter upp sin destilleringsutrustning i den karga vildmarken trots farorna i närheten."}},faq={{q="Var ligger The Dagger Hills?",a="The Dagger Hills bildar Westfalls klippiga södra gräns, precis bakom Moonbrook.",al={"the dagger hills läge","var ligger the dagger hills","hur tar man sig till the dagger hills"}},{q="Vem kontrollerar The Dagger Hills?",a="Defias Brotherhood håller en stor del av bergsryggen, med landsvägsrövare, stigjägare och knogkämpar som vaktar de södra kullarna.",al={"defias i the dagger hills","vem bor i the dagger hills","fiender i the dagger hills"}},{q="Varför brygger en dvärg öl här ute?",a="Grimbooze Thunderbrew destillerar sina kraftiga dvärgbrygder på de ensliga höjderna och trotsar banditer och vidunder för den goda dryckens skull.",al={"grimbooze i westfall","dvärg i the dagger hills","grimbooze thunderbrews historia"}},{q="Vad är Leprithus?",a="Leprithus är en ökänd gast som strövar omkring bland klipporna i The Dagger Hills och skrämmer resenärer och banditer som möter den i mörkret.",al={"leprithus uppkomstplats","gast i the dagger hills","odöda i the dagger hills"}}},fx={["7ebc9df0"]={q="Vad gör Dagger Hills farligt?",a="Den karga åsen tornar upp sig alldeles bakom Moonbrook och kryllar av beväpnade banditer, landsvägsrövare och slagskämpar från Defias Brotherhood, som använder höjden för att hålla uppsikt över låglandet. Utöver banditpatrullerna sägs den rastlösa odöda gengångaren Leprithus stryka omkring på de ödsliga höjderna. Därför är det farligt för ensamma resenärer att färdas genom dessa klippiga trakter.",al={"faran vid dagger hills","är dagger hills farligt","vad är farligt med dagger hills"}}},fp="12,160,14.266.0,20.276.0,35.81.0,30.117.0,36.117.0,18.122.0"}
P.entries["subzone:dalaran"] = {n="Dalaran",s="Dalaran var en gång Kirin Tors lysande magokratiska huvudstad, belägen vid Lordamere Lakes södra strand. Staden krossades av Scourge och demonherren Archimonde under det tredje kriget. De överlevande magikerna bygger upp staden igen, och tog tidigt under återuppbyggnaden bort dess skyddande violetta sköld.",h="Dalaran var en gång Kirin Tors lysande magokratiska huvudstad, belägen vid Lordamere Lakes södra strand.",kw={"alterac","archimonde","council of six","dalaran","kupol","kirin tor","lordamere","sköld","violet citadel"},ang={["class:Mage"]="Dalaran är den historiska vaggan för mänsklig och högälvisk trolldomskonst. Att se dess legendariska spiror fortfarande byggas upp igen är en allvarlig påminnelse om de förödande förluster som magikerna led under det tredje kriget.",["faction:Alliance"]="Dalaran var ett av de sju kungadömen som grundade det ursprungliga Alliance of Lordaeron, och Kirin Tor bygger upp sin ödelagda huvudstad igen."},sec={{t="Magokratins fall",b="Dalaran grundades av trollkarlar från Arathorian Empire efter de forntida Troll Wars och stod i århundraden som mänsklighetens främsta tillflykt för studier i arkana konster. Under Council of Six ledning samlade Kirin Tor på sig väldiga magiska arkiv och vaktade mäktiga artefakter i Violet Citadel. Den storhetstiden fick ett abrupt slut under det tredje kriget. Förrädarprinsen Arthas ledde Scourge genom stadsportarna för att lägga beslag på Book of Medivh, och kort därefter krossade demonherren Archimonde Dalarans höga spiror till grus."},{t="Magokratin byggs upp igen",b="Efter Legionens nederlag återvände Kirin Tors överlevande trollkarlar till sitt ödelagda hemland. De vägrade överlåta sina förfäders mark åt Scourge eller plundrare och reste en ogenomtränglig, skimrande violett barriär över stadens hjärta. Skölden har sedan dess tagits bort, men återuppbyggnaden fortsätter. Magikerna fortsätter att bygga upp sin fallna tillflykt, och Archmage Ansirem Runeweaver finns i Violet Citadel."}},faq={{q="Vad hände med Dalarans skyddande sköld?",a="Kirin Tor reste en magisk sköld över Dalaran efter stadens förstörelse under det tredje kriget. Skölden har sedan dess tagits bort, och staden byggs fortfarande upp igen.",al={"lila bubbla","lila sköld alterac","vad är kupolen","dalarans kupol"}},{q="Kan spelare ta sig in i Dalaran?",a="Ja, medan återuppbyggnaden fortfarande pågår, och Archmage Ansirem Runeweaver bor i Violet Citadel. Kirin Tor står dock på Alliansens sida. Horden är Hatad av dem och attackeras så fort den syns i staden, men grupper från Horden kan fortfarande ta sig igenom City of Dalaran-dungeonen.",al={"kan jag komma in i dalaran","hur tar man sig in i dalaran","ta sig förbi dalarans sköld"}},{q="Vem förstörde Dalaran?",a="Dalaran angreps av prins Arthas och hans Scourge-armé, som stal Book of Medivh från stadens valv. Kort därefter åkallade demonherren Archimonde mörk magi och krossade staden till ruiner.",al={"hur föll dalaran","vem sprängde dalaran","varför ligger dalaran i ruiner"}},{q="Vem styr Dalaran?",a="Staden styrs av Kirin Tor, en elitorden av magiker som leds av en styrande församling kallad Council of Six.",al={"vem styr dalaran","dalarans ledning","vem leder kirin tor"}}},fp="7,230,21.503.0,24.413.0,43.159.0,26.258.0,22.187.0,18.78.0"}
P.entries["subzone:dalson-s-tears"] = {n="Dalson's Tears",s="Dalson's Tears är en förpestad gård mitt i Western Plaguelands. Den kallades en gång Dalson's Orchard. Under det tredje kriget tog pesten över marken, som blev uppmarschområde för en av Scourges giftiga pestgrytor. De odöda resterna av de tidigare ägarna hemsöker fortfarande fälten och uthusen.",h="Dalson's Tears är en förpestad gård mitt i Western Plaguelands.",kw={"cauldron lord malvinious","dalson's orchard","dalson's tears","farmer dalson","mrs dalson","pestgryta","western plaguelands"},ang={["class:Paladin"]="De vanhelgade fälten och Dalsonfamiljens lidande själar visar den ondska som dröjer kvar i Lordaeron och som Ljusets heliga krigare har svurit att rena landet från.",["race:Undead"]="Den förstörda gården påminner tydligt om det öde som drabbade många av Lordaerons invånare, innan Sylvanas Windrunner bröt Lich Kings kontroll över Forsaken."},sec={{t="En förgiftad skörd",b="Före det tredje kriget blomstrade gården som Dalson's Orchard, en produktiv gård i Lordaerons kornbod. I dag är fälten täckta av förruttnelse och platsen har fått namnet Dalson's Tears. Mitt bland ruinerna står en väldig järngryta som ständigt bolmar ut giftiga gröna pestångor över landskapet. Grytan övervakas av Cauldron Lord Malvinious och försvaras av en skara förpestade zombier, ruttnande lik och skelettfasor som tjänar Lich King."},{t="Dalsons öde",b="Gårdens ursprungliga invånare gick en tragisk död till mötes när pesten svepte genom trakten, men döden gav dem ingen ro. Mrs. Dalson vandrar omkring på den förgiftade jorden som ett själlöst skelett och håller krampaktigt i en nyckel till gårdens utedass. I det lilla skjulet lurar den fasansfulla ghoul som en gång var Farmer Dalson. Hans desperata hustru låste in honom där innan pesten helt tog dem båda i sitt grepp."}},faq={{q="Vad kallades Dalson's Tears före pesten?",a="Innan det tredje kriget ödelade Lordaeron var gården en välmående jordbruksegendom som kallades Dalson's Orchard.",al={"dalson's orchard","ursprungligt namn","vad hette gården"}},{q="Varför står det en jättelik gryta mitt på gården?",a="Scourge byggde väldiga pestgrytor på Lordaerons åkrar för att ständigt koka giftiga ämnen. Ångorna driver genom trakten, förpestar jorden, förgiftar vattenkällor och förvrider alla levande varelser som utsätts för dem.",al={"dalsons gryta","grön rökgryta","varför står det en gryta här"}},{q="Vem vaktar grytan vid Dalson's Tears?",a="Pestgrytan skyddas av Cauldron Lord Malvinious, en odöd befälhavare i Scourges tjänst, med horder av förpestade zombier, skelettfasor och ruttnande lik vid sin sida.",al={"grytans herre","vem är bossen här","cauldron lord malvinious"}},{q="Vad vet man om det låsta utedasset?",a="Det låsta utedasset hör till den övergivna gården. Mrs. Dalsons dagbok ger ledtrådar åt den som undersöker vad som hände familjen.",al={"utedassets monster","vem finns i utedasset","farmer dalson"}}},fp="14,230,18.343.0,23.337.1,49.123.0,56.228.0,42.153.0,40.105.1"}
P.entries["subzone:dandred-s-fold"] = {n="Dandred's Fold",s="Dandred's Fold är en avskild gård och herrgård vid Lordamere Lakes dimmiga nordvästra strand i Alterac Mountains. Nu har Syndicate tagit över platsen, som tjänar som säker tillflyktsort åt Lord Aliden Perenolde och hans medkonspiratörer. Både Horde och Alliance håller ett vaksamt öga på tillflyktsorten vid sjön, av helt olika skäl.",h="Dandred's Fold är en avskild gård och herrgård vid Lordamere Lakes dimmiga nordvästra strand i Alterac...",kw={"aliden perenolde","argus wake","dandred's fold","dandreds fold","elysa","lordamere lake","nagaz","syndicate","uplands"},ang={["faction:Alliance"]="Alliance kan inte tolerera en allians mellan mänskliga laglösa och den demoniska Argus Wake. Därför beordrar Magistrate Henry Maleb riktade anfall mot godset.",["faction:Horde"]="För Horde är det djupt personligt att infiltrera Dandred's Fold. Warchief Thrall vill återfå Taretha Foxtons halsband."},sec={{t="En adlig fristad i laglösas händer",b="Dandred's Fold låg en gång i tiden i västra utkanten av The Uplands, med egen tillgång till Lordamere Lakes vatten. Det var en fridfull lantgård, troligen ägd av en adelsman från Alterac vid namn Dandred. Efter kungarikets fall förvandlades egendomen till ett befäst näste för Syndicate. Syndicates lönnmördare och hantlangare patrullerar nu staketen och bryggorna och håller Southshores myndigheter och Forsaken på andra sidan sjön borta från den fallna adeln."},{t="En härva av intriger",b="Bakom herrgårdens stängda dörrar smids farliga konspirationer. Lord Aliden Perenolde, Syndicates erkände ledare, använder Dandred's Fold som bas tillsammans med sin älskarinna Elysa. Men laglösa är inte ensamma här. En förrädisk orch från Shadow Council vid namn Nagaz of the Argus Wake har också slagit sig ned här och förhandlar fram mörka pakter med de mänskliga rövarna. Den farliga alliansen gör Dandred's Fold till ett mål för både Southshores magistrater och Hordes mästare."}},faq={{q="Vem kontrollerar Dandred's Fold?",a="Godset ockuperas av Syndicate, ett aristokratiskt kriminellt nätverk som leds av Alteracs avsatta adelsmän. Syndicates lönnmördare och hantlangare vaktar området och lyder under Lord Aliden Perenolde.",al={"vem finns vid dandreds fold","vem bor vid dandred's fold","fiender vid dandreds fold"}},{q="Varför bryr sig Horde om godset?",a="Horde ger sig på herrgården för att fälla Lord Aliden Perenolde och återta ett stulet minne: arvehalsbandet som en gång tillhörde Taretha Foxton, Thralls räddare och förtrogna från barndomen.",al={"horde vid dandreds fold","varför åker horde till dandreds fold"}},{q="Varför skickar Alliance äventyrare hit?",a="Magistrate Henry Maleb från Southshore skickar Alliance-agenter hit för att döda Nagaz, en farlig medlem av kulten Argus Wake som samarbetar med Syndicates laglösa.",al={"alliance vid dandreds fold","magistrate malebs uppdrag dandreds fold"}},{q="Vem var Dandred?",a="Dandreds identitet finns inte dokumenterad. Godset bär hans namn, men inget bekräftat vittnesmål pekar ut den ursprungliga ägaren.",al={"vem är dandred","dandreds bakgrund"}}},fx={e469c160={q="Vad är Dandred's Fold?",a="Dandred's Fold är en avskild gård och herrgård på Alterac Mountains västra högland, vid Lordamere Lakes dimmiga stränder. Den var en gång ett fridfullt adelsgods, men fungerar nu som ett befäst tillhåll och en bas för Syndicate.",al={"vad är dandreds fold","dandreds fold i alterac","om dandreds fold"}},b8b5cedb={q="Vad hände vid Dandred's Fold?",a="Efter kungariket Alteracs fall hamnade gården vid sjön i Syndicates händer. Lord Aliden Perenolde gjorde den avskilda herrgården till sitt privata fäste och tillflyktsort och knöt farliga band till skumma organisationer som Argus Wake.",al={"dandreds folds historia","vad hände med dandreds fold"}},fc1f4fab={q="Är Dandred's Fold farligt?",a="Det är extremt farligt för ensamma resenärer. Området bevakas av skickliga hantlangare från Syndicate, smygande stråtrövare och hemliga agenter från Argus Wake. Alla är lojala mot Lord Aliden Perenolde och fientligt inställda till inkräktare.",al={"är dandreds fold farligt","faran vid dandred fold","vem finns vid dandreds fold"}}},fp="14,219,36.429.0,20.340.1,28.188.0,42.185.1,44.167.0,16.102.0"}
P.entries["subzone:dark-portal"] = {n="The Dark Portal",s="The Dark Portal är en monumental stenportal vid Blasted Lands södra gräns. Medivh och Gul'dan öppnade den med förenad magi, och den blev den ödesdigra väg som förde den gamla Horden till Azeroth och inledde det första kriget.",h="The Dark Portal är en monumental stenportal vid Blasted Lands södra gräns.",kw={"black morass","blasted lands","the dark portal","draenor","den stora portalen","gul'dan","khadgar","medivh"},ang={["faction:Alliance"]="För Alliansen är portalen ett högtidligt minnesmärke över det första kriget och det forna Stormwinds fall. Därför håller Nethergardes magiker ständig vakt.",["race:Orc"]="Portalen är den smärtsamma tröskeln till ditt folks förflutna: porten som den gamla Horden marscherade igenom, förslavad under demoniska härskare, när den övergav sitt urgamla hemland för krig."},sec={{t="En rift mellan världar",b="Innan portalen öppnades var området en del av Black Morass, ett blött träsk som sträckte sig över södern. Det förändrades när Medivh, besatt av Sargeras, förenade sin Tirisfal-magi med Gul'dans felmagi på Draenor. Ritualen krävde oräkneliga liv och slet sönder verklighetens väv. Den gamla Horden reste enorma stenbyggnader för att förankra riften och marscherade arméer genom öppningen för att krossa kungariket Stormwind i det första kriget. Portalens felutstrålning fördärvade omgivningarna i grunden och förvandlade frodiga träsk till de röda, förstenade ödemarker vi ser i dag."},{t="Vaksam i vila",b="Efter Alliansen av Lordaerons seger i det andra kriget krossade ärkemagikern Khadgar stenramen med kraftfull magi, i hopp om att för alltid skilja Draenor från Azeroth. Men dimensionssprickan därunder visade sig i praktiken vara oförstörbar. Alliansen byggde Nethergarde Keep i närheten för att hålla vakt över såret, medan demoner och rester av Skuggornas råd fortsätter att smyga genom den sönderslagna kalderan. I dag står portalen återuppbyggd men vilande, ett tyst ärr mellan världar som ingen sida vågar överge."}},faq={{q="Kan du gå genom The Dark Portal just nu?",a="Nej. Portalens stenram står intakt, men riften i den är vilande. Ingen resenär kan ta sig igenom öppningen just nu.",al={"kan jag gå in i the dark portal","är the dark portal öppen","portal till outland"}},{q="Vem byggde The Dark Portal från början?",a="Den skapades genom en gemensam ritual mellan den mänsklige väktaren Medivh på Azeroth och trollkarlen Gul'dan på den döende världen Draenor. Ritualen iscensatte invasionen som tände det första kriget.",al={"vem skapade the dark portal","medivh gul'dan portal","skaparna av the dark portal"}},{q="Varför håller Nethergarde Keep vakt över portalen?",a="Efter att ärkemagikern Khadgar krossat portalens ursprungliga ram efter det andra kriget övertalade han Alliansen att hålla vakt över ruinerna. Alliansen grundade Nethergarde Keep för att hålla ständig uppsikt över platsen ifall hoten skulle återvända.",al={"varför finns nethergarde keep här","nethergarde håller vakt över portalen","varför nethergarde"}},{q="Varför är marken kring portalen röd och karg?",a="Blasted Lands var en gång ett bördigt träsk som kallades Black Morass. De enorma felenergier som krävdes för att bryta igenom verkligheten, tillsammans med fördärvet från Draenor och demoniska bestar, förgiftade jorden och förstenade ekosystemet.",al={"varför är blasted lands dött","portalens fördärv","varför är blasted lands rött"}}},fp="11,160,23.477.0,17.496.0,47.108.0,37.185.0,40.207.0,51.171.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="Darkcloud Pinnacle",s="Darkcloud Pinnacle är en befäst taurenbosättning på flera sammankopplade platåberg öster om The Great Lift i Thousand Needles. Den hålls av den aggressiva Grimtotem-klanen och fungerar som bas för störningar i regionen och skumma affärer.",h="Darkcloud Pinnacle är en befäst taurenbosättning på flera sammankopplade platåberg öster om The Great Lift i...",kw={"arnak grimtotem","darkcloud pinnacle","grimtotem","harb foulmountain","platåberg","thousand needles"},ang={["faction:Horde"]="Grimtotem som ockuperar detta platåberg uppträder som fiender och hotar resenärer på väg från The Great Lift längre in i Thousand Needles.",["race:Tauren"]="Grimtotems förrädiska beteende på dessa platåberg står i skarp kontrast till den enighet och fred som Cairne Bloodhoof försöker bevara mellan stammarna."},sec={{t="En fästning på klipptoppen",b="Darkcloud Pinnacle breder ut sig över tre huvudplatåberg som förbinds av repbroar och behärskar kanjonens bäcken nedanför. Höjderna nås bara via en brant naturlig sluttning från kanjonens botten och över träbroar, eller via en hög passage nära Razorfen Downs. Från dessa vindpinade klippor vakar Grimtotem över dalen, skyddade från oöverlagda angrepp och avskilda från taurenstammarna i stort."},{t="Intriger på platåbergen",b="Bosättningen styrs av ledare som Arnak Grimtotem och Harb Foulmountain och är mer än en enkel utpost. Hemlig korrespondens som hittats på platåberget tyder på att Grimtotem aktivt samordnar sig med mörka och okända krafter och driver ambitioner som ligger långt från den fred som Cairne Bloodhoof skapade i Thunder Bluff."}},faq={{q="Vem kontrollerar Darkcloud Pinnacle?",a="Fästningen tillhör Grimtotem-klanen, en aggressiv och tillbakadragen taurenfraktion som öppet är fientlig mot de flesta utomstående och djupt misstänksam mot Horde.",al={"vem bor på darkcloud pinnacle","darkcloud pinnacle ägare","vilka finns på darkcloud pinnacle"}},{q="Hur tar du dig till Darkcloud Pinnacle?",a="Du når Darkcloud Pinnacle genom att klättra uppför en naturlig sluttning på ett närliggande platåberg från kanjonens botten och sedan ta dig över träbroar med rep, eller via en bro nära Razorfen Downs.",al={"hur tar man sig upp på darkcloud pinnacle","väg till darkcloud pinnacle","ingång till darkcloud pinnacle"}},{q="Vem leder Grimtotem här?",a="Bosättningens verksamhet övervakas av framstående Grimtotem-företrädare, däribland Arnak Grimtotem och Harb Foulmountain.",al={"darkcloud pinnacle ledare","vem leder darkcloud pinnacle","grimtotem-bossar"}},{q="Vad smider Grimtotem för planer här?",a="Grimtotem vid fästningen har hemlig kontakt med en okänd mörk kraft och arbetar mot dunkla mål som hotar stabiliteten i Thousand Needles.",al={"vad händer på darkcloud pinnacle","grimtotem-konspiration"}}},fx={["0ab7147f"]={q="Vad är Darkcloud Pinnacle?",a="Darkcloud Pinnacle är en befäst taurenby högt ovanför ravinens botten i Thousand Needles, strax öster om The Great Lift. Byn sträcker sig över tre bebodda platåer som binds samman av hängande repbroar. Den är ett viktigt fäste för Grimtotem-stammen, en aggressiv och isolerad taurenklan som försvarar sitt territorium svartsjukt mot främlingar.",al={"vad är darkcloud pinnacle","information om darkcloud pinnacle","om darkcloud pinnacle"}},["44a431c5"]={q="Är Darkcloud Pinnacle farligt?",a="Mycket farligt. Grimtotem-taurenerna som bor i Darkcloud Pinnacle är våldsamt fientliga mot inkräktare och håller hela bosättningen hårt bevakad. De höga platåerna och smala repbroarna gör att strider här alltid innebär en risk att falla ner i ravinen. Stammens schamaner och krigare är redo att döda alla som tar sig uppför sluttningarna.",al={"faran vid darkcloud pinnacle","hur farligt är darkcloud pinnacle","är darkcloud farligt"}}},fp="18,158,21.398.0,20.259.1,32.146.0,36.155.0,29.106.0,37.154.1"}
P.entries["subzone:darkened-bank"] = {n="The Darkened Bank",s="The Darkened Bank är den norra strandlinjen i Duskwood, längs floden som skiljer de skuggiga skogarna från Elwynn Forest. Den sträcker sig från områdets västra utkant österut mot Redridge Mountains och markerar gränsen mellan den relativa tryggheten i norr och skogens mörka fasor.",h="The Darkened Bank är den norra strandlinjen i Duskwood, längs floden som skiljer de skuggiga skogarna från...",kw={"the darkened bank","duskwood","elwynn forest","lars","flod","strandlinje","sven yorgen"},ang={["faction:Alliance"]="För alliansens äventyrare som lämnar Elwynn Forest fungerar The Darkened Bank som en första samlingsplats innan de ger sig djupare in i Duskwoods hemsökta hjärta."},sec={{t="En osäker gräns",b="Längs flodens södra strand, mitt emot Elwynn Forest, bildar The Darkened Bank Duskwoods norra kant. Den sträcker sig från flodkrökarna i väster österut mot stenbron som leder till Redridge Mountains. Trots det dystra intrycket under Duskwoods förbannelse är strandlinjen ofta den första platsen där resenärer får fäste när de beger sig söderut från Elwynn. Nära dess västligaste spets ligger ett provisoriskt läger där fördrivna flyktingar, däribland Sven Yorgen och Lars, har sökt skydd precis utanför den djupa skogens räckvidd."}},faq={{q="Var ligger The Darkened Bank?",a="The Darkened Bank sträcker sig längs hela Duskwoods norra strand vid floden, mittemot Elwynn Forest på andra sidan vattnet. Den sträcker sig från områdets västligaste utkanter österut till bron som leder in i Redridge Mountains.",al={"the darkened bank plats","var ligger the darkened bank","the darkened bank duskwood"}},{q="Vem bor längs The Darkened Bank?",a="Längst västerut vid stranden ligger ett enkelt läger där Sven Yorgen och Lars håller till. De har drivits bort från sina tidigare liv längre in i området och använder den norra flodstranden som en osäker tillflyktsort medan de söker hjälp mot Duskwoods hot.",al={"läger vid the darkened bank","vem finns vid the darkened bank","figurer vid the darkened bank"}},{q="Hur tar sig resenärer vanligtvis hit?",a="Resenärer kan enkelt nå den västra delen av The Darkened Bank genom att simma söderut över floden från sydvästra Elwynn Forest eller följa flodens södra strand västerut från bron till Redridge.",al={"hur tar man sig till the darkened bank","ta sig till the darkened bank"}}},fx={["84b37a17"]={q="Vad är The Darkened Bank?",a="The Darkened Bank är Duskwoods långa norra strandlinje, från skogens västra kant österut mot bron som leder till Redridge Mountains. Gränslandet blickar ut över floden mot Elwynn Forest och markerar övergången från det gyllene ljuset i norr till det onaturliga mörker som sveper in Duskwood.",al={"vad är darkened bank","darkened bank i duskwood","berätta om darkened bank"}},["180e4478"]={q="Är The Darkened Bank farlig?",a="Djurlivet och strövarna vid The Darkened Bank är jämförelsevis svagare än de dödliga fasor som lurar längre in i Duskwood, men platsen är långt ifrån säker. Rovdjur smyger genom snåren vid flodstranden, och flyktingarna som slagit läger på den västra stranden är ständigt på sin vakt mot mörkret som tränger närmare.",al={"faran vid darkened bank","är darkened bank säkert","hot vid darkened bank"}}},fp="13,174,21.383.0,35.177.0,34.221.0,41.163.0"}
P.entries["subzone:darkmist-cavern"] = {n="Darkmist Cavern",s="Darkmist Cavern är en övergiven gruva i nordvästra Dustwallow Marsh, helt översvämmad av jättespindlar som jagar sina byten. Förfallna ruiner utanför antyder att en bosättning gått under i träskets faror. Lokalbefolkningen är fortfarande oenig om grottan gav spindlarna deras namn eller tvärtom.",h="Darkmist Cavern är en övergiven gruva i nordvästra Dustwallow Marsh, helt översvämmad av jättespindlar som...",kw={"darkmist cavern","darkmist-spindlar","dustwallow marsh","gruvruiner","spindelgruva","swamp eye jarl"},ang={["profession:Cooking"]="Den excentriske eremiten ”Swamp Eye” Jarl tycker att de vidriga ögonen från Darkmist-spindlar är den främsta ingrediensen i en mustig träskgryta, men få utanför träsket delar hans smak.",["profession:Mining"]="Grottan grävdes uppenbart ut av gruvarbetare för länge sedan, men den som vill leta efter malm i dess steniga djup måste först kämpa sig igenom horder av häckande spindlar."},sec={{t="Kullen i gruvan",b="Darkmist Cavern ligger i nordvästra delen av Dustwallow Marsh och verkar en gång ha varit en aktiv gruva. I dag är alla människor sedan länge borta. Utanför ingången står förfallna skjul, och gångarna är fyllda av tjocka spindelnät. Darkmist-spindlar har tagit över grottan. Dessa rovdjur är fasansfulla, och deras gift och storlek gör gångarna livsfarliga för oförsiktiga vandrare. Träskets invånare tvistar fortfarande om grottan fick sitt namn efter den ruskiga spindelkullen därinne eller om spindlarna fick sitt namn från den dimmiga grottan."},{t="Eremitens skafferi",b="Trots den uppenbara faran lockar grottan ibland till sig asätare och excentriska träskbor. Eremiten ”Swamp Eye” Jarl är ökänd för att skicka resenärer djupt in bland näten för att samla in ögonen från dessa monstruösa spindlar. Han hävdar att de passar utmärkt som buljongbas. Bortsett från sådana märkliga utflykter för matlagning håller sig de flesta förståndiga resenärer långt borta från den nätklädda ingången."}},faq={{q="Vad är Darkmist Cavern?",a="Det är en övergiven gruva i nordvästra Dustwallow Marsh som helt har tagits över av jättelika, giftiga spindlar som kallas Darkmist-spindlar.",al={"vad är darkmist cavern","darkmist-grottan","spindelgrotta i dustwallow"}},{q="Vem bodde i ruinerna utanför grottan?",a="De små träruinerna tyder på att en bosättning eller ett gruvläger en gång fanns här, men de tidigare invånarna är inte identifierade.",al={"vem bodde här","hus utanför darkmist cavern","övergiven by vid darkmist"}},{q="Varför beger sig folk in i Darkmist Cavern?",a="Mycket få går frivilligt in, men den excentriske eremiten ”Swamp Eye” Jarl anlitar djärva äventyrare för att ge sig ner i gångarna och hämta spindelögon till sin märkliga träskgryta.",al={"varför gå till darkmist cavern","uppdrag i darkmist cavern"}},{q="Var det spindlarna eller grottan som fick namnet först?",a="Invånarna i Dustwallow Marsh är oense om spindlarna fick sitt namn efter grottan eller grottan efter spindlarna. Ingen fastställd berättelse slår fast vilket namn som kom först.",al={"spindlarnas namns ursprung","varför heter det darkmist"}}},fp="15,174,21.445.0,15.248.0,24.120.0,40.114.0,43.160.0,49.169.0"}
P.entries["subzone:darkshire"] = {n="Darkshire",s="Darkshire, tidigare känt som Grand Hamlet, är en hårt ansatt bosättning i östra Duskwood. Staden ligger insvept i ett ihållande, onaturligt mörker och försummas av Stormwind. Den överlever endast tack vare Night Watchs vaksamhet och invånarnas envisa uthållighet.",h="Darkshire, tidigare känt som Grand Hamlet, är en hårt ansatt bosättning i östra Duskwood.",kw={"brightwood","darkshire","duskwood","ebonlocke","grand hamlet","night watch","scarlet raven"},ang={["class:Paladin"]="När de döda reser sig på alla omgivande kyrkogårdar och de skräckslagna invånarna nästan glömt Ljuset, råder det ingen brist på oheliga styggelser att rena från byns utkanter för heliga krigare.",["faction:Alliance"]="Darkshire är en bister påminnelse om hur kungarikets gränsland splittras. Alliansens hjältar möter tacksamma stadsbor, men också en påtaglig bitterhet mot den adel i Stormwind City som inte svarar på deras rop."},sec={{t="En övergiven stad",b="Byn, som en gång var en fridfull skogsby kallad Grand Hamlet, jämnades med marken av Old Horde under First War och byggdes senare upp igen. Dess öde blev verkligt bittert efter Medivhs fall vid Karazhan. Hans dödskamp lämnade en förbannelse över skogarna omkring, som förvandlades till Duskwoods skuggiga vildmark. Staden tillhör formellt kungariket Stormwind, men stadshuset får nästan ingen hjälp från kronan. Politisk handlingsförlamning i Stormwind City har lämnat garnisonen obemannad och gränserna utan patrullering. Därför måste borgmästare Ello Ebonlocke och det lokala rådet skipa sin egen hårda, slutna rättvisa i skuggorna."},{t="Gränsen i mörkret",b="Darkshire klamrar sig fast vid livet bakom sina palissader, omgiven av vandrande döda från kyrkogårdarna i väster och vilda worgen som jagar genom skogarna. Stadens främsta skydd är Night Watch, en frivillig civil milis under befäl av Althea Ebonlocke. Dessa uttröttade väktare utgår från torget och patrullerar de becksvarta gatorna. De håller vägarna öppna och driver tillbaka fasorna som lurar vid skogsbrynet. Resenärer som kommer till Scarlet Raven Tavern möter misstänksamma och rädda invånare, desperata efter legosoldater som kan hålla i ett svärd."}},faq={{q="Varför bytte staden namn från Grand Hamlet?",a="Bosättningen hette från början Grand Hamlet, när trakten ännu var en solig skog. Efter att väktaren Medivh dog vid närbelägna Karazhan spred sig mörk magi genom skogarna, skymde solen och väckte de döda. När skogen förföll och blev Duskwood fick invånarna en dyster påminnelse om sin förbannade omgivning. Därför döpte de om byn till Darkshire.",al={"varför heter det darkshire","namnbytet från grand hamlet","darkshires historia"}},{q="Varför hjälper inte Stormwind till att försvara Darkshire?",a="Stormwind drog tillbaka sina trupper från Duskwood under den politiska oron efter kung Varian Wrynns försvinnande. Stadsborna bildade Night Watch för att försvara sig mot hot som kronan inte längre höll stången mot.",al={"var är stormwinds armé","varför finns inga vakter i duskwood","varför övergav stormwind darkshire"}},{q="Vem leder Darkshire?",a="Den civila makten ligger hos Lord Ello Ebonlocke och Darkshires råd, som arbetar från stadshuset tillsammans med stadsskrivaren Daltry. Försvaret leds av Ellos dotter, Commander Althea Ebonlocke, som för befäl över den frivilliga milisen Night Watch.",al={"vem styr darkshire","darkshires ledning","borgmästare i darkshire"}},{q="Vad är Night Watch?",a="Night Watch är en lokal civil milis som Althea Ebonlocke bildade av nödtvång. Eftersom Stormwinds armé inte skickar trupper till Duskwood har lokalbefolkningen tagit till vapen för att patrullera de dystra vägarna, säkra gränserna och slå tillbaka ghoulangrepp och kringströvande vilddjur.",al={"vad är night watch","darkshires vakter","vem skyddar darkshire"}},{q="Vem var Morgan Ladimore?",a="Morgan Ladimore var en veteran som återvände efter Third War och fann sitt hem förstört och sin familj försvunnen. Hans sökande ledde honom till Darkshire. De lokala berättelserna bevarar resten av hans historia.",al={"morla dime berättelse","ladimore darkshire","vem är ladimore"}}},fx={["59ecffc1"]={q="Vad är Darkshire?",a="Darkshire är den sista kvarvarande mänskliga bosättningen i Duskwood. Den var en gång en fridfull skogsby som kallades Grand Hamlet, men står nu som en isolerad, belägrad utpost höljd i ständig dysterhet. I staden finns ett värdshus, en smedja och ett rådhus. Den är den enda tillflyktsorten för resande och hårt prövade invånare som håller stånd mot skogens fasor.",al={"vad är det här för stad","berätta om darkshire","information om darkshire"}},["2c565dbf"]={q="Vad har hänt med Darkshire förr i tiden?",a="Staden grundades ursprungligen som Grand Hamlet i skogar som då var soliga, men brändes ner av Old Horde under första kriget. Den byggdes upp igen efter andra kriget, men sjönk långsamt in i skräck när Medivhs död fördärvade den omgivande skogen till Duskwood. När evig skymning lade sig över landet fick staden namnet Darkshire.",al={"darkshires historia","grand hamlets historia","vad hände med grand hamlet"}},a7f74618={q="Vilka bor i Darkshire?",a="I Darkshire bor trotsiga, lättskrämda invånare, hantverkare och den lokala förvaltningen, som leds av Lord Ello Ebonlocke och Clerk Daltry. Althea Ebonlocke och hennes frivilliga milis, Night Watch, försvarar staden. Invånarna lever i ständig rädsla och misstänksamhet, avskurna från kunglig hjälp men fast beslutna att försvara sitt förfädershem mot det annalkande mörkret.",al={"vilka bor här","invånare i darkshire","vilka bor i darkshire"}},a9d39424={q="Är Darkshire farligt?",a="Själva bosättningen vaktas noga av Night Watch, men faran tränger ända fram till stadsportarna. Levande döda fyller närliggande kyrkogårdar och vägar, våldsamma worgen smyger genom de mörka skogarna och Stormwind har lämnat regionen åt sitt öde. Att gå utanför stadens dunkla lyktljus utan eskort är att be om en för tidig grav.",al={"är det tryggt här","är darkshire farligt","hur farligt är darkshire"}}},fp="9,162,16.570.0,20.462.0,43.311.0,45.189.0,20.208.0,24.224.0,24.200.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Darkshire Town Hall",s="Darkshire Town Hall står vid den västra kanten av stadens torg och är Duskwoods lokala maktcentrum. Från de dunkelt upplysta salarna försöker borgmästare Lord Ello Ebonlocke och hans råd styra en bosättning som belägras av krypande mörker och odöda monster.",h="Darkshire Town Hall står vid den västra kanten av stadens torg och är Duskwoods lokala maktcentrum.",kw={"clerk daltry","råd","darkshire","duskwood","ello ebonlocke","town hall"},ang={["faction:Alliance"]="För resenärer i Alliansen står Town Hall för rikets bräckliga auktoritet vid de södra gränserna och visar hur begränsat Stormwinds skydd är i isolerade bosättningar."},sec={{t="Darkshires maktsäte",b="Town Hall ligger rakt väster om stadens stora torg och är platsen där Darkshires lokala ledare samlas för att styra ett alltmer isolerat område. Innanför de väderbitna murarna sitter borgmästare Lord Ello Ebonlocke, som kämpar för att bevara ordningen och skydda invånarna medan Stormwind knappt erbjuder någon militär hjälp. Tillsammans med borgmästaren arbetar kommunala tjänstemän som Clerk Daltry med att föra lokala register och hålla reda på resenärerna som färdas längs Duskwoods farliga vägar, men det är en dyster och svår uppgift att hålla liggarna uppdaterade i dessa farliga tider."}},faq={{q="Vem leder staden från den här byggnaden?",a="Lord Ello Ebonlocke är borgmästare i Darkshire och leder stadsrådet från Town Hall. Han leder det lokala försvaret och vädjar till besökande äventyrare om hjälp, eftersom staden knappt får några förstärkningar från rikets huvudstad.",al={"vem är borgmästare","vem styr darkshire","vem finns i town hall"}},{q="Vilka register förvaras i Town Hall?",a="Clerk Daltry för stadens register över invånarna och resenärerna som passerar genom Darkshire. På grund av kaoset och de ständiga farorna som plågar Duskwood har många av hans loggböcker och register blivit något föråldrade.",al={"clerk daltrys register","vad gör daltry","stadsregister"}},{q="Varför är Town Hall så viktig för Duskwoods överlevnad?",a="Eftersom Duskwood saknar direkt militärt stöd från Stormwind fungerar Town Hall som operationscentrum för Night Watch och de lokala myndigheterna. Där samordnar rådet försvaret av civilbefolkningen och skickar hjälp genom den skuggiga regionen.",al={"varför är town hall viktig","darkshires rådets roll"}}},fx={e48299c3={q="Vad är Darkshire Town Hall?",a="Darkshire Town Hall är bosättningen Darkshires administrativa hjärta och den lokala förvaltningens säte. Byggnaden ligger högt på västra sidan av stadstorget. Där samordnar lokala ledare, rådsmedlemmar och tjänstemän samhällsärenden, för offentliga register och försöker styra en skräckslagen befolkning som omges av Duskwoods fördärvade vildmark.",al={"vad är darkshire town hall","darkshire town halls syfte","om darkshire town hall"}},bcc317cc={q="Vilka bor i eller styr Darkshire Town Hall?",a="Rådhuset sköts av borgmästare Lord Ello Ebonlocke och Darkshire Council, tillsammans med administrativ personal som Clerk Daltry. Det är ingen privatbostad, utan ett kommunalt nav där Darkshires myndighetspersoner, historiker och skrivare dagligen håller ordning på stadens handlingar, sköter samhällsärenden och överlägger om bosättningens försvar.",al={"vilka arbetar i darkshire town hall","vilka finns i darkshire town hall","personalen på darkshire town hall"}},["8f432bfa"]={q="Är Darkshire Town Hall farligt?",a="Själva byggnaden är en av de tryggaste tillflyktsorterna i Duskwood. Den bevakas noga av Night Watch och omges av stadens försvarsverk. Den är skyddad från de odöda, vilda bestarna och mörkare hot som hemsöker skogarna runt omkring, så länge stadens försvar håller stånd mot angrepp utifrån.",al={"är darkshire town hall tryggt","faror vid darkshire town hall","fara inne i darkshire town hall"}}},fp="19,134,21.415.0,38.223.0,43.163.0,57.227.0"}
P.entries["subzone:darkspear-strand"] = {n="Darkspear Strand",s="Vid Darkspear Strand börjar stammens tillflyktsort på Durotars sydkust. Trollfolket kom i land efter att ha förvisats från Echo Isles och byggde Sen'jin Village i närheten under Vol'jins ledning.",h="Vid Darkspear Strand börjar stammens tillflyktsort på Durotars sydkust.",kw={"darkspear","darkspear strand","durotar","echo isles","sen'jin village","vol'jin","zalazane"},ang={["faction:Horde"]="För Horden markerar denna strand platsen där Darkspear slog sig ned på Kalimdors sydkust bredvid sina orciska allierade efter att ha förlorat sitt öhem.",["race:Troll"]="För Darkspear Trolls påminner denna kust om Zalazanes förräderi och deras flykt för att grunda Sen'jin Village."},sec={{t="En exilstrand",b="Darkspear Trolls kom i land här efter att ha förlorat Echo Isles. När häxdoktorn Zalazane tog deras hem i besittning korsade överlevande det smala vattnet och landade på denna kust. De slog sig ned bara några meter inåt land i stället för att skingras bland Durotars fientliga röda ödemarker, och byggde Sen'jin Village. Stranden vetter mot bränningarna och öarna som de fortfarande hoppas återta."}},faq={{q="Vad hände vid Darkspear Strand?",a="Darkspear Trolls landsteg på denna kust efter att ha flytt från Echo Isles. När Zalazane vände sig mot sitt folk korsade överlevande vattnet och samlades i närheten för att grunda Sen'jin Village.",al={"varför heter det darkspear strand","darkspear strand i berättelsen","vad är det här för strand"}},{q="Varför lämnade Darkspear Echo Isles?",a="Darkspear lämnade Echo Isles efter att häxdoktorn Zalazane förrådde sina fränder och förslavade sina stamfränders sinnen med mörk voodoo. Hövdingen Vol'jin ledde de återstående okorrumperade trollen bort för att undkomma total underkuvning, och de landade på denna strand.",al={"varför lämnade trollen echo isles","zalazanes fördrivning","evakueringen från echo isles"}},{q="Vilken bosättning ligger intill Darkspear Strand?",a="Sen'jin Village ligger bara några meter inåt land från stranden. Flyktingar grundade byn efter landstigningen, och den är Darkspears främsta utpost och andliga centrum i Durotar.",al={"by nära darkspear strand","stad intill stranden","var ligger sen'jin village"}}},fx={["88a2cf68"]={q="Vad är Darkspear Strand?",a="Darkspear Strand är den del av Durotars kust som ligger mitt emot Echo Isles, strax utanför Sen'jin Village. Det är den främsta stranden där Darkspear Trolls gick i land och samlade sig efter den tragiska flykten från sitt öhem.",al={"vad är darkspear strand","darkspear strands historia","om darkspear strand"}},["504bffc1"]={q="Varför heter det Darkspear Strand?",a="Stranden har fått namn efter Darkspear-stammen och hedrar deras landstigning här under evakueringen från Echo Isles. Den markerar den första trygga plats stammen nådde på Kalimdors fastland efter att ha flytt undan Zalazanes förrädiska kupp.",al={"varför darkspear strand","hur fick darkspear strand sitt namn","ursprunget till darkspear strands namn"}}},fp="16,171,16.383.0,34.194.0,43.258.0,52.163.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="Darkwhisper Gorge",s="Darkwhisper Gorge är en förrädisk ravin full av demoner, uthuggen i Wintersprings södra höjder. När Archimonde tillintetgjordes under Tredje krigets slutstrid flydde resterna av den krossade Burning Legion nerför Mount Hyjals sluttningar och befäste sig i dessa taggiga raviner. I dag strövar mäktiga fiender omkring på höjderna och vaktar uråldriga mineraler och mörka planära reliker.",h="Darkwhisper Gorge är en förrädisk ravin full av demoner, uthuggen i Wintersprings södra höjder.",kw={"burning legion","darkwhisper gorge","earthcaller franzahl","eye of shadow","hederine","lady hederine","mount hyjal","vi'el","winterspring"},ang={["class:Warlock"]="Hederine-demonerna som stryker omkring i grottorna bär på viktiga planära komponenter, vilket gör ravinen till en central prövningsplats för warlocks som vill bemästra mäktigare besvärjelseritualer som Doomguard.",["profession:Mining"]="De farliga ravinerna döljer rikliga fyndigheter av truesilver och rika thoriumådror, en belöning för gruvarbetare som vågar smyga förbi elitedemonerna."},sec={{t="Ett fäste för Legion i snön",b="Efter Archimondes nederlag på Mount Hyjal skingrades de överlevande demonerna från Burning Legion i de omgivande bergskedjorna. En disciplinerad förtrupp tog sin tillflykt till Darkwhisper Gorge och förvandlade Wintersprings södra gräns till ett dödligt fäste. Dessa fiender, ledda av Hederine-demoner – däribland dödliga manastalkers, slayers och initiates under Lady Hederine – försvarar sina underjordiska tunnlar och eldfängda läger med ursinne. Utöver det omedelbara hotet från ravinens elitinvånare står en olycksbådande, förseglad valvport vid dess lägsta punkt, en antydan om förseglade passager som leder högre upp på det heliga berget."},{t="Dolda reagenser och sällsynt kunskap",b="Trots den överväldigande faran tar sig modiga äventyrare och lycksökare in i ravinen för dess enastående rikedomar. Ravinerna är rika på värdefulla mineraler som truesilver och täta thoriumfyndigheter. Djupare in i de skuggiga grottorna kämpar ovanliga invånare för att överleva, som impförsäljaren Vi'el, som säljer reagenser påverkade av fel, såsom felcloth och gromsblood, och den svårfångade högalven Earthcaller Franzahl, som besitter uråldrig metallurgisk kunskap om smältning av sällsynt elementium."}},faq={{q="Varför finns det så många demoner i Winterspring?",a="Demonerna i Darkwhisper Gorge är överlevare från Burning Legions invasion av Mount Hyjal under Tredje kriget. Efter att Archimonde dödats vid World Tree drog sig hans slagna styrkor tillbaka ner i dessa raviner för att omgruppera sig, i stället för att utplånas helt.",al={"varför demoner här","darkwhisper legionens historia","varifrån kom demonerna"}},{q="Vad är den förseglade porten längst in i ravinen?",a="Djupt nere i ravinens södra delar står en runristad valvport och en aktiv magisk barriär. Den vaktar bergspasset som leder direkt upp till Mount Hyjal. Resenärer når bergets Tainted Foothills genom att flyga från Everlook.",al={"darkwhisper-portal","instansportal winterspring","hyjal-porten"}},{q="Vem leder demonerna här?",a="Lägret domineras av en sekt demoniska inkräktare som kallas Hederine och som tycks lyda under Lady Hederine. De patrullerar ravinerna tillsammans med slayers, initiates och fell hounds som kallas manastalkers.",al={"darkwhisper-boss","hederine-ledare","vem styr darkwhisper"}},{q="Varför skulle en äventyrare bege sig till Darkwhisper Gorge?",a="Området är exceptionellt farligt, och det krävs samordnade grupper för att ta sig fram säkert. Ändå lockas dit warlocks som söker planära bindningar, präster som jagar det sällsynta Eye of Shadow, smeder och gruvarbetare som söker rika thoriumådror samt lärda som letar efter den gömda Earthcaller Franzahl.",al={"varför bege sig till darkwhisper","darkwhisper-uppdrag","darkwhisper-belöningar"}}},fp="17,154,29.470.0,34.343.0,45.200.0,49.222.0,26.191.0,55.263.0"}
P.entries["subzone:darnassus"] = {n="Darnassus",s="Högt bland Teldrassils vidsträckta grenar ligger Darnassus, kaldoreiernas huvudstad och fristad. Staden är byggd vid stilla vatten och grönskande lundar. Den är nattalvernas andliga hjärta och Alliansens främsta fäste i norra Kalimdor. Härifrån leder översteprästinnan Tyrande Whisperwind och ärkedruiden Fandral Staghelm sitt folk genom prövningarna som följer med deras nyfunna dödlighet.",h="Högt bland Teldrassils vidsträckta grenar ligger Darnassus, kaldoreiernas huvudstad och fristad.",kw={"huvudstad","darnassus","kaldoreier","staghelm","teldrassil","temple of the moon","tyrande"},ang={["faction:Alliance"]="För resenärer från Eastern Kingdoms är Darnassus en avskild, fridfull tillflyktsort och Alliansens viktigaste fäste på kontinenten Kalimdor.",["race:NightElf"]="Darnassus är kaldoreiernas kulturella och politiska huvudstad. Staden är ert folks nya början och självständiga fristad efter Tredje krigets svåra uppoffringar."},sec={{t="En fristad bland grenarna",b="Darnassus byggdes efter Tredje kriget för att hedra nattalvernas överlevnad, efter att de förlorat den odödlighet som deras heliga världsträd Nordrassil skänkte dem. Till skillnad från Ironforges och Stormwinds täta stenstäder är Darnassus en öppen och stillsam bosättning med träbyggda hus, lysande helgedomar och välvda broar över kristallklara sjöar. Vaksamma Sentinels, väldiga krigsträdandar och druider som formar träd vakar över stigarna och bevarar naturens frid inom stadens gränser."},{t="En splittrad ledning",b="Darnassus står för kaldoreiernas enighet, men styret visar på sprickor. Översteprästinnan Tyrande Whisperwind sköter civila och militära frågor från det strålande Temple of the Moon, omgiven av Elunes systrar. Cenarion Circles angelägenheter sköts av ärkedruiden Fandral Staghelm, som förespråkade planteringen av Teldrassil för att återge alverna deras förlorade odödlighet. Malfurion Stormrage har försvunnit i en mystisk dvala djupt inne i The Emerald Dream. Staghelms offensiva framtidsvision skapar ofta motsättningar med det mer tålmodiga prästerskapet."}},faq={{q="Vem styr Darnassus?",a="Översteprästinnan Tyrande Whisperwind är nattalvernas främsta ledare och styr från Temple of the Moon, där hon leder Sentinels. Ärkedruiden Fandral Staghelm sköter druidernas angelägenheter och leder Cenarion Circle medan Malfurion Stormrage är borta.",al={"ledare i darnassus","vem styr darnassus","nattalvernas ledare"}},{q="Hur tar sig resenärer till Darnassus från platser utanför Teldrassil?",a="Darnassus ligger högt uppe i grenarna på ett väldig världsträd på en ö. Skepp och flyglinjer går därför bara till Rut'theran Village vid trädets fot. Därifrån för en magisk portal besökare upp till själva staden.",al={"hur tar man sig till darnassus","ingång till darnassus","ta sig in i darnassus"}},{q="Varför grundades Darnassus så nyligen?",a="Efter förstörelsen vid Mount Hyjal under Tredje kriget förlorade nattalverna sin odödlighet och sitt uråldriga levnadssätt. Fandral Staghelm och hans bundsförvanter planterade Teldrassil utanför Kalimdors kust. Darnassus slog rot på dess grenar som en ny fristad för deras folk.",al={"varför är darnassus nytt","när byggdes darnassus","darnassus ålder"}},{q="Var är Malfurion Stormrage?",a="Ärkedruiden Malfurion Stormrage är försvunnen. Hans ande är fångad i en djup, oförklarlig dvala inom The Emerald Dream. Hans frånvaro lämnar ledningen för Cenarion Circle i Darnassus helt i Fandral Staghelms händer.",al={"var är malfurion","är malfurion i darnassus","malfurions status"}}},fx={["24a1a5b0"]={q="Vad är Darnassus?",a="Darnassus är nattalvernas huvudstad, högt uppe bland de väldiga grenarna på det nyvuxna världsträdet Teldrassil. Staden är byggd runt en stilla sjö och öppen mot skymningshimlen. Efter tredje kriget är den civilisationens andliga och kulturella hjärta. Graciösa broar, hus av levande trä och heliga lundar formar staden, med det strålande Temple of the Moon som centrum. Den är en fristad för alliansen och ett levande bevis på kaldoreiernas vördnad för naturen.",al={"vad är det här för plats","berätta om darnassus","översikt över staden darnassus"}},["3a9c78e5"]={q="Vilka bor i Darnassus?",a="Staden är främst hem åt nattalver, och här välkomnas både druider, jägare, präster och krigare. Översteprästinnan Tyrande Whisperwind håller till i det storslagna Temple of the Moon tillsammans med sina Elunesystrar, medan ärkedruiden Fandral Staghelm leder Cenarion Circle från Cenarion Enclave. De vaksamma Sentinels patrullerar gatorna och uråldriga väktare vandrar längs stigarna. Besökare möter också sändebud från andra alliansfolk och representanter för neutrala ordnar som Argent Dawn.",al={"vilka bor här","invånare i darnassus","darnassus invånare"}},["0325f465"]={q="Är Darnassus farligt?",a="För alliansmedlemmar är Darnassus en ovanligt fridfull tillflyktsort, skyddad från Kalimdors hårdare faror av havet och Teldrassils höga läge. Beväpnade Sentinels och mäktiga Ancient Protectors försvarar staden. Hordens agenter möts däremot av ett fientligt mottagande och angrips genast av stadens ståndaktiga försvarare när de kommer in.",al={"är darnassus tryggt","hot i darnassus","finns det några faror i darnassus"}}},fp="9,348,23.457.0,20.553.0,20.204.0,57.166.0,38.274.0,29.190.0"}
P.entries["subzone:darrow-hill"] = {n="Darrow Hill",s="Darrow Hill är ett upphöjt område med kargt gräsland i norra Hillsbrad Foothills, strax nedanför Headland. På de öppna sluttningarna betar pumor och hjortar, medan vilda yetier lurar i The Foothill Caverns som perforerar bergssidan. Området är rikt på ådror av Alterac Granite och utgör en förrädisk gränsmark där vilda djur och rivaliserande resenärer ständigt drabbar samman.",h="Darrow Hill är ett upphöjt område med kargt gräsland i norra Hillsbrad Foothills, strax nedanför Headland.",kw={"alterac granite","darrow hill","the foothill caverns","headland","hillsbrad foothills","yetier"},ang={["class:Hunter"]="Kullarna erbjuder utmärkta jaktmarker för pumor och hjortar som rör sig mellan Alteracs skogsbryn och de lägre gräsmarkerna.",["profession:Mining"]="Grottsystemen som genomborrar Darrow Hill, särskilt The Foothill Caverns, är rika på Alterac Granite och regionala mineralådror, om du kan hantera yetierna som håller till i närheten."},sec={{t="En förrädisk gränsmark",b="Darrow Hill sträcker sig längs foten av de norra bergen nedanför Headland och förbinder de böljande betesmarkerna i södra Hillsbrad med Alteracs karga, kallare höjder. Pumor och hjortar smyger genom det höga gräset och delar de steniga sluttningarna med väldiga yetier som väller ut ur The Foothill Caverns. Förutom det vilda djurlivet döljer grottväggarna fyndigheter av tät Alterac Granite, som lockar stenbrytare, gruvarbetare och äventyrare rakt i faran. Områdets leder ligger mellan omstridda anspråk och är ökända för sin farlighet för ovetande resenärer från båda fraktionerna."}},faq={{q="Var ligger Darrow Hill?",a="Darrow Hill ligger i norra delen av Hillsbrad Foothills, strax söder om de klippiga branterna som kallas Headland och öster om huvudvägen in i Alterac.",al={"darrow hill läge","var ligger darrow hill","darrow hill karta"}},{q="Vilka varelser hotar resenärer kring Darrow Hill?",a="Hjortar och pumor stryker över de öppna sluttningarna, medan vilda yetier strövar i området kring och inne i The Foothill Caverns.",al={"darrow hill fiender","vad lever på darrow hill","monster på darrow hill"}},{q="Vad finns i The Foothill Caverns?",a="The Foothill Caverns är fulla av vilda yetier och innehåller ådror av eftertraktad Alterac Granite inbäddade i de klippiga väggarna.",al={"the foothill caverns","grotta på darrow hill","vad finns i grottan"}},{q="Varför anses området vara så farligt för resenärer?",a="Förutom vilda djur och yetilyor gör det öppna landskapet intill omstridda vägar Darrow Hill till en ökänd skärmytslingsplats där vandrare från Alliance och Horde ofta överfaller varandra.",al={"varför är darrow hill farligt","pvp på darrow hill","fara vid darrow hill"}}},fx={["35480940"]={q="Vad är Darrow Hill?",a="Darrow Hill är ett högt, kargt område i norra delen av Hillsbrad Foothills, alldeles nedanför Headlands väldiga höjder. Vilda djur strövar över de öppna sluttningarna, medan de närliggande Foothill Caverns skär in i berget och döljer faror under den fridfulla ytan.",al={"vad är darrow hill","darrow hill i hillsbrad","information om darrow hill"}}},fp="11,237,22.446.0,29.153.0,53.111.0,46.117.0,55.176.0"}
P.entries["subzone:darrowmere-lake"] = {n="Darrowmere Lake",s="Darrowmere Lake är en vidsträckt sötvattensjö i sydöstra delen av Western Plaguelands. Mitt i sjön ligger fästningsön Caer Darrow, vars ruiner döljer The Cult of the Damned:s fruktade nekromantiska akademi Scholomance.",h="Darrowmere Lake är en vidsträckt sötvattensjö i sydöstra delen av Western Plaguelands.",kw={"barov","caer darrow","darrowmere","darrowmere lake","proudmooreflottan","scholomance","thondroril river","western plaguelands"},ang={["faction:Alliance"]="För Alliansens veteraner är Darrowmere Lake ihågkommen som en viktig sjöfront där Proudmoores flotta stred mot den gamla Horden under det andra kriget.",["race:Undead"]="Sjön markerar gränsen till Caer Darrow, där de levande Barovarna sålde sitt hem i livet till Lich King för att skapa den fruktade akademin Scholomance."},sec={{t="Ett inlandshav med historia",b="Darrowmere Lake är en av de största insjöarna i Eastern Kingdoms, omgiven av Lordaerons pestdrabbade skogar och försörjd av floderna Thondroril och Darrowmere. Under det andra kriget utkämpades häftiga sjöstrider mellan Horden och storamiral Daelin Proudmoores flotta på sjöns djupa vatten. Horden angrep också fästningsön Caer Darrow mitt i sjön, plundrade den och förde bort dess uråldriga runsten. Sjön var en gång en livlig vattenväg och handelsled för House of Barov, men är nu en dyster, dimhöljd sänka mitt i Plaguelands."},{t="Skuggan över vattnet",b="Mitt i sjön reser sig Caer Darrow, en gång familjen Barovs stolta förfädersäte. Under dess sönderslagna grund ligger Scholomance, Scourges främsta akademi för nekromanti och mörka konster. Vattnet runt ön är stillastående och fullt av faror, en spegel av The Cult of the Damned:s mörka arv. Äventyrare som färdas över sjön måste trotsa både de pestdrabbade omgivningarnas faror och den genomträngande fasa som fästningen i dess mitt sprider."}},faq={{q="Var ligger Darrowmere Lake?",a="Darrowmere Lake ligger i sydöstra hörnet av Western Plaguelands och förbinder Thondroril River i norr med Darrowmere River, som rinner söderut.",al={"darrowmeres läge","var ligger darrowmere lake","hur tar man sig till darrowmere"}},{q="Vad finns på ön mitt i sjön?",a="På ön ligger Caer Darrow, en uråldrig bosättning som en gång styrdes av den ädla familjen House of Barov. Under den ruinerade staden ligger Scholomance, en vidsträckt skola för mörk magi som drivs av The Cult of the Damned.",al={"ön i darrowmere","vad finns på ön","caer darrows läge"}},{q="Vilken roll spelade Darrowmere Lake under det andra kriget?",a="Sjön var en omstridd vattenväg där Proudmooreflottan utkämpade sjöslag mot Horden. Horden plundrade också Caer Darrow på ön mitt i sjön, skövlade fästningen och lade beslag på dess uråldriga runsten.",al={"darrowmere under andra kriget","sjöslag vid darrowmere","darrowmeres historia"}},{q="Kan fartyg fortfarande segla in i Darrowmere Lake?",a="Under det andra kriget navigerade stora flottor på sjön, men de förbindande floderna har nu branta vattenfall och grunda passager som hindrar stora fartyg från att segla in från havet.",al={"båttrafik till darrowmere","kan fartyg nå darrowmere"}}},fp="15,185,20.508.0,24.429.0,33.159.0,48.201.0,53.189.0,42.190.0"}
P.entries["subzone:darrowshire"] = {n="Darrowshire",s="Darrowshire är en ruinerad by i Eastern Plaguelands södra kullar, en gång en fridfull by i Lordaeron. Under det tredje kriget gjorde invånarna ett desperat och tragiskt motstånd mot en övermäktig styrka från Scourge. I dag finns bara krossade timmer, rastlösa andar och bittra minnen kvar i tystnaden.",h="Darrowshire är en ruinerad by i Eastern Plaguelands södra kullar, en gång en fridfull by i Lordaeron.",kw={"slaget vid darrowshire","darrowshire","eastern plaguelands","gastar","horgus the ravager","lordaeron","marduk blackpool"},ang={["class:Paladin"]="Darrowshires tragiska öde är en bestående uppmaning till paladiner att föra det renande Ljuset till Plaguelands, både för att slå ner de odöda och ge plågade andar ro.",["race:Human"]="För människor i Alliance är Darrowshire ett högtidligt vittnesmål om den enorma förödelse som drabbade Lordaeron, där vanligt folk gjorde ett hopplöst försök att försvara sina familjer."},sec={{t="Ett tragiskt motstånd",b="Innan pesten slukade norra Lordaeron var Darrowshire en anspråkslös jordbruksby inbäddad nedanför de södra klipporna. När Scourge marscherade söderut under det tredje kriget belägrade en styrka under dödsriddaren Marduk Blackpool och ghoulherren Horgus the Ravager staden. Byborna och de lokala försvararna kämpade tappert och höll för en stund stånd mot omöjliga odds. Till slut bröt försvaret samman och hela byns befolkning slaktades. I stället för att finna frid i döden återuppväcktes många av Darrowshires fallna försvarare som gastar för att förstärka Scourges led. Byn blev ett kusligt, tomt minnesmärke över förlorat hjältemod."},{t="Ekon från slaget",b="Darrowshire har länge varit övergiven av de levande, men är långt ifrån helt tom. Slaktens psykiska tyngd vilar tungt över dalen och håller kvar spöklika rester av stadsborna bland ruinerna. Resenärer som passerar berättar om märkliga fenomen, däribland isande återskapanden där det tragiska slaget utspelar sig på nytt i spöklik tystnad. Marken är fortfarande mättad av sorg och påminner dystert om vad Scourge ryckte ifrån kungariket."}},faq={{q="Vad hände med Darrowshire?",a="Darrowshire förstördes under det tredje kriget när en väldig Scourge-armé anföll byn. De odöda, under ledning av dödsriddaren Marduk Blackpool och ghoulherren Horgus the Ravager, övermannade byns försvarare och slaktade invånarna. Bosättningen lämnades i ruiner.",al={"darrowshires historia","varför förstördes darrowshire","vad hände här"}},{q="Vilka ledde Scourges angrepp på Darrowshire?",a="Angreppet leddes av dödsriddaren Marduk Blackpool tillsammans med Horgus the Ravager, en monstruös ghoulherre. Tillsammans bröt deras styrkor igenom byns försvar och beseglade dess öde.",al={"vem anföll darrowshire","darrowshires skurkar","horgus och marduk"}},{q="Varför hemsöks Darrowshire?",a="Slakten var så plötslig och fasansfull att de fallnas andar förblev bundna till jorden. Förutom spöklika uppenbarelser som dröjer sig kvar i de ruinerade byggnaderna sägs själva det brutala slaget då och då utspela sig på nytt i spökform. De döda hålls fångna i sina sista, tragiska ögonblick.",al={"darrowshires spöken","varför finns det andar i darrowshire"}},{q="Vad blev det av byborna som dog när de försvarade byn?",a="De flesta försvararna höggs ner där de stod, och nekromantiker återuppväckte många av deras lik som tanklösa gastar. De tvingades tjäna just den Scourge-armé som förstörde deras hem.",al={"darrowshires bybor","darrowshires försvarare"}}},fp="11,245,14.578.0,20.354.0,29.246.0,58.184.0,27.224.0,57.147.0"}
P.entries["subzone:dawning-isles"] = {n="The Dawning Isles",s="The Dawning Isles är en grupp låglänta småöar i Lordamere Lake, längs den östra kanten av Silverpine Forest. De var en gång idylliska tillflyktsorter, men har fallit offer för De odödas pest och översvämmats av aggressiva murlocker.",h="The Dawning Isles är en grupp låglänta småöar i Lordamere Lake, längs den östra kanten av Silverpine Forest.",kw={"the dawning isles","lordaeron","lordamere lake","silverpine forest","vile fin"},ang={["faction:Alliance"]="De pesthärjade öarna är en dyster påminnelse om hur djupt Scourges förruttnelse nådde in i Lordaerons naturskönaste vatten.",["race:Undead"]="De pesthärjade The Dawning Isles ligger i Lordamere Lake, inom synhåll från Undercitys västra tillfartsvägar, och Vile Fin-murlockerna som håller öarna blir fler för varje år."},sec={{t="Pest över sjön",b="Före det tredje kriget var The Dawning Isles kända som natursköna småöar i Lordamere Lakes lugna, klara vatten. När De odödas pest svepte över Lordaeron trängde förruttnelsen in i sjöns grunda vatten. Växtligheten blev blek och ruttnade, och den idylliska friden försvann. I dag härskar Vile Fin-stammen av murlocker över de leriga stränderna och snåriga buskagen, och försvarar aggressivt sina växande kolonier mot alla som försöker ta sig över sjön."},{t="Ett murlockfäste",b="Murlockerna var inte alltid den enda faran på öarna. Kärrbestar strövade en gång omkring på de pesthärjade småöarna tillsammans med dem, men har sedan dess försvunnit. I deras frånvaro har Vile Fin-stammen vuxit så mycket att murlockerna nu helt kontrollerar öarna. Det som en gång var en stillsam kedja av småöar har blivit deras fäste i Lordamere Lake."}},faq={{q="Var ligger The Dawning Isles?",a="The Dawning Isles ligger i Lordamere Lake, vid Silverpine Forests östra gräns och strax väster om Ruins of Lordaeron.",al={"the dawning isles plats","var ligger the dawning isles","karta över the dawning isles"}},{q="Vilka varelser lever på The Dawning Isles?",a="Öarna är främst hemsökta av murlockstammen Vile Fin, som frodas längs de fördärvade stränderna. Förr strövade också farliga kärrbestar omkring på småöarna, men de har till stor del försvunnit och lämnat plats åt den myllrande murlockbefolkningen.",al={"fiender på the dawning isles","vad lever på the dawning isles","monster på the dawning isles"}},{q="Varför ruttnar träden och stränderna här?",a="Öarna besmittades under det tredje kriget när De odödas pest svepte över Lordaeron. Vattnet och jorden tog upp pesten, förgiftade växtligheten och lämnade småöarna grumliga, sjuka och förfallna.",al={"varför är the dawning isles pesthärjade","sjöpest på the dawning isles"}}},fx={["501d8847"]={q="Vad är Dawning Isles?",a="The Dawning Isles är en grupp låga småöar som höjer sig ur Lordamere Lake vid nordöstra Silverpine Forest. De sågs en gång som en idyllisk och fridfull tillflyktsort på sjöns kristallklara vatten, men har sedan dess förfallit under den kvardröjande farsoten från Plague of Undeath.",al={"vad är dawning isles","dawning isles historia","om dawning isles"}},["425e68c2"]={q="Vad har hänt med Dawning Isles?",a="The Dawning Isles var en gång orörda småöar i Lordamere Lake, men ödelades när Plague of Undeath spred sig och gjorde växtligheten sjuklig och stränderna ruttna. Murlocs och träskbestar tog över öarna. Träskbestarna har sedan försvunnit, och Vile Fin-murlocerna har blivit så talrika att de nu kontrollerar öarna.",al={"dawning isles historia","vad hände vid dawning isles"}},d646a662={q="Är Dawning Isles farliga?",a="Ja, de är mycket farliga. Förutom den kvardröjande förruttnelsen från Plague of Undeath har aggressiva Vile Fin-murlocer tagit över öarna. De har förökat sig kraftigt och anfaller alla som tar sig in på deras område.",al={"är dawning isles tryggt","hur farliga är dawning isles","faror på dawning isles"}}},fp="13,206,18.452.0,19.249.0,36.125.0,41.172.0,42.214.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="Dawning Wood Catacombs",s="Djupt under Raven Hill Cemetery ligger Dawning Wood Catacombs, en mörk labyrint full av de mest fruktade odöda i Duskwood. Den som vågar sig in i de underjordiska tunnlarna möter stora horder av skelettväktare och köttätande gastar.",h="Djupt under Raven Hill Cemetery ligger Dawning Wood Catacombs, en mörk labyrint full av de mest fruktade...",kw={"kryptor","dawning wood catacombs","duskwood","gastar","raven hill cemetery","skelett","odöda"},ang={["class:Paladin"]="Katakomberna är ett dystert vittnesmål om rikets fallna och kräver att Ljusets heliga vrede renar de vanhelgade gravarna.",["class:Priest"]="Under Raven Hills stenvalv ropar rastlösa andar och ruttnande lik efter den sista vilan, och katakomberna blir därmed en allvarsam prövning av tron."},sec={{t="Under Raven Hill",b="Långt innan skymningsförbannelsen lade sig över skogen var Dawning Wood Catacombs en viloplats för de döda från skogarna omkring. Nu ligger de begravda under det förstörda Raven Hill Cemetery, och i de mörka stenkorridorerna finns traktens mest dödliga odöda. Katakomberna har två tydliga underjordiska flyglar: de västra gångarna hålls av led efter led av animerade skelett som vaktar förfädernas gravar, medan de östra gångarna sluttar ner i ett stinkande näste fullt av glupska, sjukdomsbärande gastar. Ensamma resenärer överlever sällan långt nere i djupet."}},faq={{q="Var ligger Dawning Wood Catacombs?",a="Katakomberna ligger direkt under Raven Hill Cemetery, vid Duskwoods västra utkant. Ingångarna leder ner från markytan bland de vidsträckta gravstenarna och de förfallna kryptorna.",al={"katakombernas plats","var ligger dawning wood catacombs","hur tar man sig till katakomberna"}},{q="Vad lurar inne i katakomberna?",a="Katakomberna hyser den största koncentrationen av de mest ursinniga odöda i Duskwood. Den västra flygeln försvaras av tungt beväpnade skelettkrigare, medan de östra tunnlarna är fulla av vilda, pesthärjade gastar.",al={"katakombernas fiender","vad finns i dawning wood catacombs","katakombmonster"}},{q="Varför byggdes katakomberna från början?",a="När trakten ännu var grönskande grävdes katakomberna ut som ett storslaget gravvalv för lokala familjer och framstående personer. Den mörka förbannelse som senare slukade skogarna återupplivade dem som begravts därinne.",al={"katakombernas historia","varför bygga katakomber","katakombernas ursprungliga syfte"}},{q="Är det säkert att utforska katakomberna ensam?",a="Att ge sig in i katakomberna ensam är farligt. De trånga tunnlarna ger liten möjlighet att dra sig tillbaka, och de odöda samlas i täta, aggressiva horder som kan övermanna ensamma resenärer.",al={"kan jag klara katakomberna ensam","katakombernas faror","är katakomberna svåra"}}},fx={fdcc93ff={q="Vad är Dawning Wood Catacombs?",a="Dawning Wood Catacombs är en slingrande underjordisk labyrint under den vidsträckta Raven Hill Cemetery i västra Duskwood. De grävdes ursprungligen för att begrava traktens döda, men de väldiga stensalarna har sedan dess angripits av några av de våldsammaste och mest sjukdomsdrabbade odöda som stryker omkring i skogen. De är indelade i två huvuddelar. Den ena är ett motbjudande tillhåll för rabiata ghouls, och den andra hemsöks av beväpnade skelettväktare.",al={"vad är katakomberna","översikt över dawning wood catacombs","katakomberna i raven hill"}},["514fe1a3"]={q="Är det farligt att gå in i Dawning Wood Catacombs?",a="Att ge sig ner under kyrkogården är bland det dödligaste man kan göra i Duskwood. Katakomberna myllrar av skoningslösa odöda som snabbt kan övermanna en ensam resande i beckmörkret. Den östra delen är full av sjukdomsbärande ghouls som sliter sönder kött, medan erfarna skelettvakter håller den västra sidan och vakar över skändade gravar. Utan erfarna allierade vid din sida är en färd nerför trapporna nästan säkert dödlig.",al={"faror i katakomberna","är katakomberna farliga","hur farliga är katakomberna"}}},fp="22,151,18.504.0,45.165.0,32.184.0,48.192.0,42.161.0"}
